INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçimden Düşüyor Irak..', 'i-cimden-dusuyor-irak-tugba-gurelli-cmm8n', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sesime ses verir mi sırtımdaki ölüler,

Morarmış yüzleriyle

Ağzımdaki koca mataraya kim su verebilir ki

Üstü çizik umutlarımı sığdırabilirler mi göğüslerine.

Sesini sesimde boğsam gider miyiz istediğin yere

Yüzüne yüzümü sürsem alır mısın beni içinin kırlarına

Herkes bir dil,herkes bir din ya düşündüğünde

En büyük yanlış

Herkes bir peygamber aslında ana rahminde.

Martılar konuyor şimdi her çıplak ölünün üstüne

Ölü otları yoluyor bak sendeki bahçıvan

İçimden koca bir Irak düşüyor

Ben kendi repliğimden utanıyorum,söylemektense...', 'Sesime ses verir mi sırtımdaki ölüler, Morarmış yüzleriyle Ağzımdaki koca mataraya kim su verebilir ki Üstü çizik umutlarımı sığdırabilirler...', ARRAY['Türk Edebiyatı','Şiir','Tuğba Gürelli']::text[], 8.5, '{"poet":"Tuğba Gürelli","poet_slug":"tugba-gurelli","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/icimden-dusuyor-irak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'P l a t o n i k', 'p-l-a-t-o-n-i-k-birsen-ates-i06rn', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'gözlerim

yenik düşerse uykuya

o zaman düşlerimdesin

henüz bilmiyorum 

kimsin 

bir adın olmalı 

yüreğimde saklı

sadece hayalim

ve geleceğim

şu an nerelerdesin 

belki de uykunun 

en tatlı yerindesin

bekliyorum her gece

mavilerin içinde

seni saklıyacağım

her daim yüreğimde

emin yerdesin

sen beynimde

yüreğimdesin', 'gözlerim yenik düşerse uykuya o zaman düşlerimdesin henüz bilmiyorum  kimsin  bir adın olmalı  yüreğimde saklı sadece hayalim ve geleceğim ş...', ARRAY['Türk Edebiyatı','Şiir','Birsen Ateş']::text[], 8.5, '{"poet":"Birsen Ateş","poet_slug":"birsen-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/p-l-a-t-o-n-i-k-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Siyah Gözlerine Beni de Götür', 'siyah-gozlerine-beni-de-gotur-nurullah-genc-d3v4f', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Daha dokunmadan kurudu irem 

çöllere bir türlü yağamıyorum 

yeni bir koşunun başlangıcında 

biraz deprem sonrası 

biraz şehir hülyası 

bir kalp yangınından geriye kalan 

siyah gözlerine beni de götür 

artık bu yerlere sığamıyorum. 

Pembe uçurtmalar yolladığından beri 

sarardı tiryaki menekşeleri 

sonbaharın tozlu kafeslerinde 

sevgi turnaları yakalıyorum 

turnalar gidiyor; ben kalıyorum 

avareyim,asudeyim,yorgunum 

bilmiyorum neden sana vurgunum 

Erzurum garında banklar üstünde 

uyku tutmuyor karanlıkları 

yitik düşlerimi kovalıyorum 

gölgeler gidiyor; ben kalıyorum. 

Binbir türlü kokuyorsa yaylalar 

siyah gözlerine beni de götür 

baharın koynundan koparıp sana 

ipek bir mendile sardığım yüreğimle 

şehzade gülleri gönderiyorum 

umutlar kalıyor; ben gidiyorum. 

Bütün yelkenlileri,deniz fenerlerini 

kaptanları sorgulayan 

yanından geçen küheylanların 

korku tufanına yakalandığı 

siyah gözlerine beni de götür 

güneş ülkesinden gelen yiğitler 

benzeri olmayan bir dünya kursun 

cellat,ayrılığın boynunu vursun. 

Usul usul intizarı çürüten 

bu hercai diken,bu çılgın arzu 

sürüklüyor imkansız muştuların 

eşiğine gönül vadilerini 

bir ağaçtan düşen yapraklar gibi 

düşüyorum tanyerine 

ya topla yaralı kırlangıçları 

ya da bu vefasız şarkıyı bitir 

özgürlüğe giden tutsaklar gibi 

siyah gözlerine beni de götür.', 'Daha dokunmadan kurudu irem  çöllere bir türlü yağamıyorum  yeni bir koşunun başlangıcında  biraz deprem sonrası  biraz şehir hülyası  bir k...', ARRAY['Türk Edebiyatı','Şiir','Nurullah Genç']::text[], 8.5, '{"poet":"Nurullah Genç","poet_slug":"nurullah-genc","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/siyah-gozlerine-beni-de-gotur-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Musa ve Çoban', 'musa-ve-coban-mustafa-sureyya-sezgin-gnjii', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Günün birinde seçilmişlerden Musa

Yürüyordu kırlarda elinde  asa 

Farkındaydı içindeki varlığın

Peşindeydi yıllarca bu çağrının

“Uyanmışlardansın  Musa “ diyordu

Bu ses onu evrenleştiriyordu

Huzurla kucaklarken doğayı

Garipsedi gördüğü bir olayı

Bir çoban çıkıyor  önce tepeye

Yuvarlanıyor sonra güle güle

Musa bir anlam veremedi bu işe

Seslendi çobana;  “ Evlat bu da ne? “

Çoban; “ İbadetimdir Yaratana 

Böylece bedenim değer toprağa

Kavuşur kardeş oluruz onunla

Ben bu yolla ulaşırım Tanrıma”

Musa buna güldü; “ Be şaşkın çoban

İbadet dediğin bu işten utan

Tanrıya böyle ibadet edilmez

Senin gibi şaşkını Tanrı sevmez.

“Biliyorsan sen öğret” dedi çoban

Musa  anlattı çobana o zaman

“Ellerini semaya açacaksın

Sonra  Tanrımıza yalvaracaksın 

Eğilip toprağa kapanacaksın

Yaratanın  adını anacaksın

Belki bağışlar seni kim bilir ki

Budur işte ibadetinin şekli”

“Sanırım ki anladım “ dedi çoban

“Çok sağol cahillikmiş benim hatam “

Musa coşkuyla  yoluna yürüdü

Tanrısını memnun olmuş düşündü

Önüne bir nehir çıkınca durdu

Elindeki asayı nehre  vurdu

Yarıldı nehrin suları  duruldu

Musa nehri kolaylıkla geçmişti

Önünde yeni yollar belirmişti

Ancak arkasından bir ses duymuştu

Çoban  kendine doğru koşturmuştu

Arada nehir vardı geçemezdi

Artık çoban ona yetişemezdi

O da ne vurdu sopasını çoban

Nehir işte yarılıverdi o an

Birden şaşırdı Musa dondu kaldı 

Çoban dedi ki; “Unuttum  nasıldı? 

Şu ibadeti tekrar anlat bana

Çabuk kavuşurum belki mevlama”

Musa hıçkırdı, derinden sarsıldı

Birden hata yaptığını anladı

Defineler harabede gizlidir

Varlık zaten yaratılmış bilgidir

Söyleyecek şeyi yoktu Musa’nın

Bir dersiydi bu ona Tanrının

“Bildiğin gibi yap”  dedi çobana

“Sen bu yolla kavuşmuşsun mevlana”

İstanbul, 06.12.2004', 'Günün birinde seçilmişlerden Musa Yürüyordu kırlarda elinde  asa  Farkındaydı içindeki varlığın Peşindeydi yıllarca bu çağrının “Uyanmışlard...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Süreyya Sezgin']::text[], 8.5, '{"poet":"Mustafa Süreyya Sezgin","poet_slug":"mustafa-sureyya-sezgin","theme":"Türk Şiiri","is_hero":false,"total_lines":56,"source_url":"https://www.antoloji.com/musa-ve-coban-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüya içinde rüyanın gerçeğe dönüşmesinden olumluya uzatılan ile, sarf ''rüya içindeki rüyanın gerçeğe dönüşmesi''nden ortaya çıkanlar arasındaki ayrımların düşünsel boyut kazanması üzerine', 'ruya-icinde-ruyanin-gercege-donusmesinden-olumluya-uzatilan-ile-sarf-ruya-icindeki-ruyanin-gercege-donusmesi-nden-ortaya-cikanlar-arasindaki-ayrimlarin-dusunsel-boyut-kazanmasi-uzerine-akin-akca-9md5z', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Akvaryumun içinde ağladı lepistesten pike yiyen 

melek balıkları -aslında onların yutması gerekirdi

- kuyrukları kemirildi: Güldü onlardan 

bazıları daha sonra ama esas tuhaf olanı; 

Ve gidip, serin su seven Japon''ları 

yedi onlar da, dudaklarıyla kum ütüleyen...

Neden biri kemirir ki diğerini, anlamam:

aynı akvaryumun içinde vardır bir de köpekbalıkları; 

sallanan iskemlesinde büyük filozof-yaşlı adam''ın 

dinlencesi için başucuna koyulan, onu yoran; 

delice dolaşan, camdan duvarlı hülya aleminde.. 

ve melek balığını yemiş, yiyen lepistesi ham eden.', 'Akvaryumun içinde ağladı lepistesten pike yiyen  melek balıkları -aslında onların yutması gerekirdi - kuyrukları kemirildi: Güldü onlardan  ...', ARRAY['Türk Edebiyatı','Şiir','Akın Akça']::text[], 8.5, '{"poet":"Akın Akça","poet_slug":"akin-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ruya-icinde-ruyanin-gercege-donusmesinden-olumluya-uzatilan-ile-sarf-ruya-icindeki-ruyanin-gercege-donusmesi-nden-ortaya-cikanlar-arasindaki-ayrimlarin-dusunsel-boyut-kazanmasi-uzerine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'By Thy Silence', 'by-thy-silence-akin-akca-zu8cb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Rock’n punk, got©h(a)  electro access 

to an ordinary white white dress.. 

on a wagon-balcony in front of the sea … 

through secret, snapshot-oceans; 

she embraced by the sweet honour of grace … 

(Holy, multi-prayers of deliverance..)

I''m not sure for keeping my cries 

where love will never die. 

you always shall see a new face - 

in the middle of your cry, just try 

- about the phaseses of mists and haze. 

Speeches, enslaved and hanged by thy silence * 

from hangman''s sonnet 

upon verse; that that time could not 

escape from matter 

so as to be exterminated. 

- 

Rock ve punk ile goth elektro girişi 

sıradan bir beyaz bembeyaz entari içine; 

ki üzerinde, vagon bir balkon''un karşısında denizin... 

gizlice, şipşak algı’lı ya da böyle algılı okyanuslar''ın 

geçerek içinden doğru, kucakladı zerafetin tatlı şerefinden... 

(Kutsal, çoğul-yakarışları kurtarılışların..    )

Emin değilim gözyaşlarımı tutabileceğim hususunda 

ki aşk orada -ve sevgi de- ölüyor olmayacak. 

Ağlayışının orta yerinde, sadece dene; 

geçişken durumlarına sürecin, pus ile sisin. 

Söylemler, köleleştirilen ve asılan, leydim sizin 

sessizliğiniz tarafından; *.. celladın sonet’si 

ve verse’sinden; kaçamayacak zaman, 

öyle ki, yok edilmek uğruna madde''den...', 'Rock’n punk, got©h(a)  electro access  to an ordinary white white dress..  on a wagon-balcony in front of the sea …  through secret, snapsho...', ARRAY['Türk Edebiyatı','Şiir','Akın Akça']::text[], 8.5, '{"poet":"Akın Akça","poet_slug":"akin-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/by-thy-silence-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Haydutlar Ne Yapıyor?', 'bu-haydutlar-ne-yapiyor-kadir-soyturk-5tia5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bencileyin soran var mı; 

Bu haydutlar ne yapıyor? 

Hiç aklını yoran var mı; 

Bu haydutlar ne yapıyor? 

Çalışan aç,hırsızlar tok

Müslümana zulmeden çok

Misyonere dur diyen yok

Bu haydutlar ne yapıyor? 

Yakıp-yıkarak,soyarak

Seni-beni yok sayarak

Her yana mikrop yayarak

Bu haydutlar ne yapıyor 

Kurt ulur,sisde,dumanda

İslama ait vatanda.

Şu devirde,şu zamanda

Bu haydutlar ne yapıyor? 

Sanmayın kafir yatıyor

Dinime dil uzatıyor.

Sulara zehir katıyor

Bu haydutlar ne yapıyor? 

Cahillere yutturacak

Batıl bir yol tutturacak

Şehir şehir bucak-bucak

Bu haydutlar ne yapıyor? 

Hani laik-maiktiler...

Dinini yaymayı diler.

Yiyecek dişini biler

Bu haydutlar ne yapıyor? 

Din mi icad edecekmiş? 

Bizi o mu yedecek miş? 

Cennete mi gidecek miş

Bu haydutlar ne yapıyor? 

Kur''andan gayrısı yalan

Haktır gönlümüze dolan

Anlar bunu aklı olan

Bu haydutlar ne yapıyor?', 'Bencileyin soran var mı;  Bu haydutlar ne yapıyor?  Hiç aklını yoran var mı;  Bu haydutlar ne yapıyor?  Çalışan aç,hırsızlar tok Müslümana z...', ARRAY['Türk Edebiyatı','Şiir','Kadir Soytürk']::text[], 8.5, '{"poet":"Kadir Soytürk","poet_slug":"kadir-soyturk","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/bu-haydutlar-ne-yapiyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ytl', 'ytl-atila-gunal-zihp8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İçmişim sabaha kadar

Kafam bimilyon

Şamata bimilyon

Kızlar bimilyon

Cigaradan 

Ciğerler bimilyon

Eve gideceğim de

Yol bimilyon

Şu büfeye uğrayıp

Bi cila atayım

Bi köpeköldüren iyi gider

O da bimilyon

Yıl sonu da geliyor iyi mi

Hepsinden altı sıfır atarsak

Olmaz ki

Karşıyım arkadaş

Atmıyorum sıfır mıfır', 'İçmişim sabaha kadar Kafam bimilyon Şamata bimilyon Kızlar bimilyon Cigaradan  Ciğerler bimilyon Eve gideceğim de Yol bimilyon Şu büfeye uğr...', ARRAY['Türk Edebiyatı','Şiir','Atila Günal']::text[], 8.5, '{"poet":"Atila Günal","poet_slug":"atila-gunal","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ytl-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yolcu', 'yolcu-halil-i-brahim-ozdemir-0m19k', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gece gündüz, hayat ölüm, su aşa,

Yol engelli, takılınca bir taşa,

Sert gelmesin  bu cevizler süt dişe…

Nefeslerle tartılan yol, bir anlık…

Uzakları yakın eden  tren var.

Görülmeyen yerleri hep gören var.

Menzil aşıp saatleri kuran var…

Bundan öte bu yolculuk bir hanlık…

Suları gemleyip  aldım yoluma,,

Deniz sağ elime, dağ sol koluma,

Yağmur yağdı çiçek çiçek dalıma

Yiyip yiyeceğim hepsi bir günlük…

Gündüzle arama duvarlar ördüm

Gecede gölgenin izini sürdüm,

Saklandım güneşi kalbinden vurdum,

Bitti  yeryüzünde sahte aydınlık', 'Gece gündüz, hayat ölüm, su aşa, Yol engelli, takılınca bir taşa, Sert gelmesin  bu cevizler süt dişe… Nefeslerle tartılan yol, bir anlık… U...', ARRAY['Türk Edebiyatı','Şiir','Halil İbrahim Özdemir']::text[], 8.5, '{"poet":"Halil İbrahim Özdemir","poet_slug":"halil-i-brahim-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yolcu-63-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vermez geri', 'vermez-geri-burhan-kucuk-gc44k', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Vermez geri

Doğa bir kez aldı mı

Bir daha vermez geri

Savur saçlarını..

Düşmeden toprağa

Güzelim gözlerin

Bak güne doya doya

Hadi gel sarıl bana

Harcayalım tüm serveti

Düşmeden toprağa

Burhan KÜÇÜK

Kdz.Ereğli', 'Vermez geri Doğa bir kez aldı mı Bir daha vermez geri Savur saçlarını.. Düşmeden toprağa Güzelim gözlerin Bak güne doya doya Hadi gel sarıl ...', ARRAY['Türk Edebiyatı','Şiir','Burhan Küçük']::text[], 8.5, '{"poet":"Burhan Küçük","poet_slug":"burhan-kucuk","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/vermez-geri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahar Yazım Kalmadı', 'bahar-yazim-kalmadi-huseyin-sigirtmac-247go', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Küllendi yürekte yanan hasretin.

Artık söndürmeye lüzum kalmadı.

Gittiğim her yol, kolu gurbetin.

Vazgeçtim sıladan, gözüm kalmadı.

Dünyada beklerken dem ile devran.

Işığım tükendi karardı her yan.

Çağları atlatır duygumda zaman.

Oysa tarihlerde izim kalmadı.

Duygumdaki hayal gerçeğe zincir.

Sonucu hasretlik yüreğim incir.

Özleminle geçen gün ömür gelir.

Dünya varlığına hazım kalmadı.

Sığırtmaç hedeftir hasrete döşüm.

Yürekte duygumla belada başım.

Bitmedi fırtınam, yağmurum, yaşım.

Mevsim dört ya bahar yazım kalmadı.

Bursa 06/12/2004', 'Küllendi yürekte yanan hasretin. Artık söndürmeye lüzum kalmadı. Gittiğim her yol, kolu gurbetin. Vazgeçtim sıladan, gözüm kalmadı. Dünyada ...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Sığırtmaç']::text[], 8.5, '{"poet":"Hüseyin Sığırtmaç","poet_slug":"huseyin-sigirtmac","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bahar-yazim-kalmadi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Engel', 'engel-huseyin-sigirtmac-ix5qo', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Çığlık atsam gitmez sesim.

Dağlar avazıma engel.

Özgürlüğü aldı hissim.

Hasretin hazıma engel.

Odaklandım bir hayale.

Umutları saldım yele.

Kurduğum hayalde bile.

Kışım var yazıma engel.

Karardı aydınlık günüm.

Duygumla esir, sürgünüm.

Uyumlu değil bir yönüm.

Tellerim sazıma engel.

Hasretle Sığırtmaç doldu.

Varlığın kanat ve koldu.

Senden başka görmez oldu.

Hayalin gözüme engel.', 'Çığlık atsam gitmez sesim. Dağlar avazıma engel. Özgürlüğü aldı hissim. Hasretin hazıma engel. Odaklandım bir hayale. Umutları saldım yele. ...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Sığırtmaç']::text[], 8.5, '{"poet":"Hüseyin Sığırtmaç","poet_slug":"huseyin-sigirtmac","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/engel-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tefekkür-Tesbih', 'tefekkur-tesbih-ekrem-sama-r9mci', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Mümkündür hataları tavzih,

Çokça tefekkür, çokça tesbih...

(İstanbul:06.12.2004)', 'Mümkündür hataları tavzih, Çokça tefekkür, çokça tesbih... (İstanbul:06.12.2004)...', ARRAY['Türk Edebiyatı','Şiir','Ekrem Şama']::text[], 8.5, '{"poet":"Ekrem Şama","poet_slug":"ekrem-sama","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/tefekkur-tesbih-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dilbeste', 'dilbeste-i-brahim-dikmen-mhjzx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir salkım üzüm için

aşka gelmeli toprak, şahakalkmalı

güneş ve kamer toprağın iltifatı olmalı

ve toprak milyon eliyle semanın ellerinden tutmalı

ve sema sağnak sağnak yoğurmalı toprağı

müzeyyen küre ve sema aşka müştak olmalı

eyy bir salkımı ikram için

tüm bu külfete katlanan

madem bana bunca teveccühün var

teveccüh ki bende hissi infilak

bende sana ilan-ı aşk ediyorum

alnımı secdeden kaldırmayarak', 'Bir salkım üzüm için aşka gelmeli toprak, şahakalkmalı güneş ve kamer toprağın iltifatı olmalı ve toprak milyon eliyle semanın ellerinden tu...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Dikmen']::text[], 8.5, '{"poet":"İbrahim Dikmen","poet_slug":"i-brahim-dikmen","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/dilbeste-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saklı Kalsın Bende', 'sakli-kalsin-bende-arslan-arslan-5722q', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sevmek neden suç oldu sanki

Yürekler kahırla,sitemle doldu

Akan gözyaşları sel oldu

Bundan sonra arama sende

Yollar ayrılmış ne çare

Umutlar bitmiş tükenmiş bi çare

Sevda kalbe,hüzün göze; mahkum

Affa kılıf yok ne fayda

Arslan ARSLAN..........01.12.2004', 'Sevmek neden suç oldu sanki Yürekler kahırla,sitemle doldu Akan gözyaşları sel oldu Bundan sonra arama sende Yollar ayrılmış ne çare Umutlar...', ARRAY['Türk Edebiyatı','Şiir','Arslan Arslan']::text[], 8.5, '{"poet":"Arslan Arslan","poet_slug":"arslan-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sakli-kalsin-bende-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Serpiştirilmiş Kelimeler', 'serpistirilmis-kelimeler-i-brahim-dikmen-u32bf', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Şimdi korkularla yüzleşmenin korkusu

alımlı bir anının bunca yadı

önemsenmesi içindir önemsenenlerce

eyy nas! ! ! 

madem güzeldir bir çiçek bahar kadar

ve madem herşey tanıyalım ve sevelim içindir

durma! tanı, sevme ve önemse

madem aciz bir mide bunca nasiplidir

ya o müştak yüreğinin nedir rızkı(?) 

kim bilir belki şükrün tamamı

Şimdi yüzleştir iyi ile kötüyü

us dışı huzur versede bilmemek

tercih sebebidir bilmenin sancısı

helebirde onca anlatacak varken

susmak zorunluluğu

gönlün hayranlığı ve aklın küstahlığı

ağır bir yüktür(!)

bir çiçekte yaşamak bir baharı

can cermek kolaydır

hayat vermek külfetli

şimdi bize lazım olan

merhametine sığınacak biri

tüm yanılgılarımızı kabul edecek

ve bizi yenilmişliklerimiz içinde kahraman bilecek

beklemek başağrısı

Gitmek o dilbeste haneye

muhakeme etmek

ilkbahar resitalleirini dinlemek

na-fercam söylenceleri söylemek

buğsenin tırnaklarını kesmek

sebep can yakar endişesi

şimid ne buğse kalmıştır geriye ne de endişe

her gidişin ardından başlar

şimdi olsa sancısı

Biryerlere yetişme telaşından

hep unutulan en önemli olan

şimdi gerçek olan tek hakikat

yüreği çarpan kalemin yazma sancısı', 'Şimdi korkularla yüzleşmenin korkusu alımlı bir anının bunca yadı önemsenmesi içindir önemsenenlerce eyy nas! ! !  madem güzeldir bir çiçek ...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Dikmen']::text[], 8.5, '{"poet":"İbrahim Dikmen","poet_slug":"i-brahim-dikmen","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/serpistirilmis-kelimeler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MANİLER (ayrılık) ‘Sevgili Eşim Tayyibe Atay’a’', 'mani-ler-ayrilik-sevgili-esim-tayyibe-atay-a-abdullah-atay-zukdo', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'akmasın artık kanım 

suç bendeyse canım 

sen yoksan zehir olsun 

yaşadığım her anım... 

gül yüreğim kor oldu 

bu ayrılık zor oldu 

yar gurbete gidince 

dünya bana dar oldu... 

neler geldi başıma 

zehir kattım aşıma 

onsuz hayat neylerim 

canım feda eşime... 

sensin benim yıldızım 

kalbimde ince sızım 

yar beni terk eyledi 

şimdi artık yalnızım... 

kışa döndü bak yazım 

çalmıyor gönül sazım 

yeter ki yarim gelsin 

hak’ka budur niyazım... 

söndü yanan ocağım 

bak boş kaldı kucağım 

yar bir selam vermezse 

kor olup yanacağım... 

yıkıldı gönül tahtım 

gülmez ki kara bahtım 

son nefesimden önce 

yari görmektir ahdım... 

yar yoluna bakarım 

ağıtları yakarım 

eğer yarim gelmezse 

tanrıyadır yakarım 

harlı korlu ateşte 

yüreğimi yakarım... 

abdullah atay der ki: 

en sadık yar eşindir 

tükenmeyen aşındır 

ölümüne kadar hep 

hayat arkadaşındır...', 'akmasın artık kanım  suç bendeyse canım  sen yoksan zehir olsun  yaşadığım her anım...  gül yüreğim kor oldu  bu ayrılık zor oldu  yar gurbe...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Atay']::text[], 8.5, '{"poet":"Abdullah Atay","poet_slug":"abdullah-atay","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/maniler-ayrilik-sevgili-esim-tayyibe-atay-a-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Susuzluğumda Gizlisin', 'susuzlugumda-gizlisin-gulay-yildiz-8hye1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gecenin adımlarında gizli adın, 

Issızlığa bürünmüş 

Yanlızlığından ürkmüş... 

Farketmez; 

İki ya da üç günü yakıp 

ısınabilirdim bir kaç anıyla 

bu korda alev sen olsaydın... 

sevdanı yere serer, 

üstünde dua ederdim; 

İçimde yananların adını koysaydın! 

Serzeniş mi, inleyiş mi? 

Yüreğimi sulayan gözyaşlarını avuçla 

Susuzluğumda gizlisin....', 'Gecenin adımlarında gizli adın,  Issızlığa bürünmüş  Yanlızlığından ürkmüş...  Farketmez;  İki ya da üç günü yakıp  ısınabilirdim bir kaç an...', ARRAY['Türk Edebiyatı','Şiir','Gülay Yıldız']::text[], 8.5, '{"poet":"Gülay Yıldız","poet_slug":"gulay-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/susuzlugumda-gizlisin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Akşam Üstü', 'bir-aksam-ustu-bayram-tunca-819d7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Müptela olmuştum bir güle

Sordum ehline nasıldır diye

Tembih ettiler kaçırma diye

O Rab’den en güzel hediye

Vuruldum bir güle güneş batımında

İki katlı bir apartmanın balkonunda

Vuruldum bindiğim doru aşk atında

Dimağımdaki tat anzer balı tadında

Güneş bugün de gurup etmek üzere

Bir akşam üstü vuruldum bir güzele

Mevla’m yaratmış onu özene bezene

Dertlerimi unuturum bakınca yüzüne

Güneş giderken sırayla öper her cismi

Ayırmaz yaşı kuruyu, dikenli dikensizi

Öperim ben de sabah işe giderken eşimi

Bozamaz akşama dek hiçbir şey neşemi

Bir akşam güneş batımında, tutuldum sevdaya

Baktım bir semadaki aya bir de yanımdaki yare

O nazlımmış meğer ki, dermansız derdime çare

Şükürler olsun ki Rabbe kavuşturdu beni o yare

04.10.2004-10.04

Ölsem de gam yemem artık kavuştum ya o yare', 'Müptela olmuştum bir güle Sordum ehline nasıldır diye Tembih ettiler kaçırma diye O Rab’den en güzel hediye Vuruldum bir güle güneş batımınd...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/bir-aksam-ustu-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sitemkar', 'sitemkar-i-smet-temur-3murp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen hayaldin bir zamanlar,  düşünmeye bile cesaret edemediğim günlerimde

Sonra cesaretlenip seni rüyalarıma aldım, özlemlerimi sarıp sineme uykuya daldım

Ne zaman özlesem gelip rüyalarımda özlemlerime derman oldun habersizce kendinden

Büyüttün besledin içimdeki ateşi,  volkana döndürdün bakışlarınla,  dayanamaz oldum

İlk konuşmada ne hayaldin nede rüya,  çok şaşkındım asla imkansız derken sen 

Evet sen karşımdaydın bir masada, Gözgözeydik yılllaaaarrrrr sonra senle başbaşa

Konuşmak değil  öylece susup bakmak geldi içimden gözlerine doyaaaaa  doyaa

İçime doğmuş meğer hasret kalacakmışım sonunda beni yakan gözlerine bilemedim

Bakmaya bakmak güzelde birşeyler söylemezsem ne anlatacaktımki senin gibi ruhsuza

Konuşmayla saatlerce anlatmaya çalışmayla anlatamadığımı gözlerimmi anlatacaktı

O gün hiç bitmesin, saat hiç ilerlemesin istedim hep senle senin gözlerinle ve hayatı

Hayatı bana zehir eden bebek yüzünle bir ömür öyle kalmak istedim sana bakarak

Seni sevmek hataların en güzeli en tatlısıydı, iyiki seni sevdim  bebek yüzlüm

Pişman değilim sende olma sakın, olmayalım yıllar sonra bize lütfedilen güzel duygulara

Biliyormusun bilmem, ne zaman sana birşeylere yazmaya çalışsam düğüm düğüm boğazım

Gözlerim taş kesilmiş, kırpsam damla damla dökülecek  yüreğimde bir ağrı ellerim titriyor

Bazı anlar yaşamaktan bıkıyor, korkuyor  insanların kurtulmak için çare aradığı 

O soğuk ölümü çoookkkk sıcak buluyorum, onu ister onu özler oluyorum

Hergün hergün defalarca kahrolmaktan defalarca  ölmektense bir kere ölmeyi istiyorum

İstemekle kavuşmak olmuyor ölemiyorum, istemekle olsa sen yanımda olurdun sennnnnnnnn', 'Sen hayaldin bir zamanlar,  düşünmeye bile cesaret edemediğim günlerimde Sonra cesaretlenip seni rüyalarıma aldım, özlemlerimi sarıp sineme ...', ARRAY['Türk Edebiyatı','Şiir','İsmet Temur']::text[], 8.5, '{"poet":"İsmet Temur","poet_slug":"i-smet-temur","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sitemkar-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzel Sözler-5', 'guzel-sozler-5-huseyin-erdogan-hysea', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '''Keşke,rüzgar olup dağıtsaydım saçlarını,meltem olup okşasaydım yanaklarını,rüya olup girseydim gecelerine hiç çıkmamak üzere ömrünce...''

''Hayallerin olmak isterdim senin ama hiç gerçekleşmeyen hayallerin,ölünceye değin hep seninle yaşamak için...''

''Ne olurdu sanki düşlerin olsaydım senin,uyanınca seni gülümseten,sana mutluluk ve sevinç veren düşlerin,yaşadıkça her gece seninle olmak için...''

''Her sabah uyanınca,aç pencereni ve teninin kokusunu gönder bana serin esen rüzgarlarla,ben de buralarda seni içime çekeyim doya doya.Söyler misin sevdiğim bin ömür bile yeter mi sana doymaya? 

                                                                            06.12.2004', '''Keşke,rüzgar olup dağıtsaydım saçlarını,meltem olup okşasaydım yanaklarını,rüya olup girseydim gecelerine hiç çıkmamak üzere ömrünce...'' ''H...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Erdoğan']::text[], 8.5, '{"poet":"Hüseyin Erdoğan","poet_slug":"huseyin-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/guzel-sozler-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüzün, Aşk ve Ankara', 'huzun-ask-ve-ankara-oguzkan-bolukbasi-67day', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hüznün yayılır ortaya

Ankara bir tutsak şehirdir gecelerde

Işıklar çıkar sadece havalandırmaya

Birde soğuk

Bilmem

Nerede ısınır ellerimiz

Bir eski dosttur ceplerimiz

Adım yalnızca senin bildiğin kalabalık harflerden müteşekkil bir kelime

Taktığın isimden âleme ne

Her gece seni karşıladığımı bilmezler ki

Her sabah uğurladığımı

Bu rüyanın teline dokunmadığımı

Hayale yapışkan akşamlarda

Şiirlere sarındığımı

Aldığın hiçbir şeyi geri vermeyeceğini bilerek

Teslim ediyorum kendimi

Mükellef bir ölüm hazırla bana', 'Hüznün yayılır ortaya Ankara bir tutsak şehirdir gecelerde Işıklar çıkar sadece havalandırmaya Birde soğuk Bilmem Nerede ısınır ellerimiz Bi...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/huzun-ask-ve-ankara-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Belki', 'belki-ozge-baydil-1qtga', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kül rengi sabahlarin birinde kaybettim seni.

Bulmayi hiç istemedim,

Aramayi belki! ! !', 'Kül rengi sabahlarin birinde kaybettim seni. Bulmayi hiç istemedim, Aramayi belki! ! !...', ARRAY['Türk Edebiyatı','Şiir','Özge Baydil']::text[], 8.5, '{"poet":"Özge Baydil","poet_slug":"ozge-baydil","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/belki-63-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Olur Üzme Artık Şairini', 'ne-olur-uzme-artik-sairini-huseyin-erdogan-5pswf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'sen gidince

dünyam karardı birdenbire

bundan böyle 

ne güneş doğar

ne de bahar gelir

senin olmadığın yere

ellerim titriyor şu anda

üşüyorum yokluğunda

haydi gel

ısıt beni kollarında

bilmem ki

neden sükut içindesin 

ne yazıyorsun bana

ne de arayıp sorduğun var

aylardan bu yana

yoksa numaramı

kaydetmedin mi telefonuna? 

duymak istiyorum sesini

hele mutluluktan çıldırtır beni

hissetmek o sımsıcak nefesini

ne olur üzme artık şairini

                        06.12.2004', 'sen gidince dünyam karardı birdenbire bundan böyle  ne güneş doğar ne de bahar gelir senin olmadığın yere ellerim titriyor şu anda üşüyorum ...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Erdoğan']::text[], 8.5, '{"poet":"Hüseyin Erdoğan","poet_slug":"huseyin-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/ne-olur-uzme-artik-sairini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlayan Çiçek', 'aglayan-cicek-ekrem-sama-uk746', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Şehit mezarında mor bir çiçek varmış,

Her sabah yeniden canlanıp açarmış,

Katledilirse bir çocuk, hemen o an,

Dibine kan rengi gözyaşı saçarmış...

(İstanbul:06.12.2004)', 'Şehit mezarında mor bir çiçek varmış, Her sabah yeniden canlanıp açarmış, Katledilirse bir çocuk, hemen o an, Dibine kan rengi gözyaşı saçar...', ARRAY['Türk Edebiyatı','Şiir','Ekrem Şama']::text[], 8.5, '{"poet":"Ekrem Şama","poet_slug":"ekrem-sama","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/aglayan-cicek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Büyüme çocuk', 'buyume-cocuk-haydar-turan-rn9pu', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Büyüme çocuk,

Kal sıcak hayallerinle,

Büyüme çocuk,

Öğrenme yalanı sende.

Bilme çocuk sevgiyi, aşkı,

Bilme ki tatma ayrılığı,acıyı,

Öğrenme yaşamı, savaşı,

Tanıma kalleşi hayatın gerçeğini,

Büyüme çocuk,

Oyna hep oyuncaklarınla,

Sen yine masunca bak şu yalan dünyaya,

Büyüme çocuk kal hep çocukluğunla...', 'Büyüme çocuk, Kal sıcak hayallerinle, Büyüme çocuk, Öğrenme yalanı sende. Bilme çocuk sevgiyi, aşkı, Bilme ki tatma ayrılığı,acıyı, Öğrenme ...', ARRAY['Türk Edebiyatı','Şiir','Haydar Turan']::text[], 8.5, '{"poet":"Haydar Turan","poet_slug":"haydar-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/buyume-cocuk-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Huzur', 'huzur-sair-shimalwest-cp7p6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'komik bişey mi hayat

gülüyor mu bişeylere

acımasızca bakarak

içimi zor tutuyorum

benden kaçmasın diye

bir giderse yakalayamam

ebediyen susamam

sıkıntılar son bulsun

huzur artık beni bulsun

sanki gücüm tükeniyor

aynalar öyle diyor', 'komik bişey mi hayat gülüyor mu bişeylere acımasızca bakarak içimi zor tutuyorum benden kaçmasın diye bir giderse yakalayamam ebediyen susam...', ARRAY['Türk Edebiyatı','Şiir','Şair Shimalwest']::text[], 8.5, '{"poet":"Şair Shimalwest","poet_slug":"sair-shimalwest","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/huzur-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsyan', 'i-syan-sair-shimalwest-hfp5a', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'akıtamadığım gözyaşlarım

şiir oldu döküldü kağıda

hayata direnişim

umudumun biteyişi zannımca

gün olur devran döner diyerek

geldim bu yaşıma

isyan etmeye kalktıkca hayata

yapamadıklarım bağlıyor yaşama', 'akıtamadığım gözyaşlarım şiir oldu döküldü kağıda hayata direnişim umudumun biteyişi zannımca gün olur devran döner diyerek geldim bu yaşıma...', ARRAY['Türk Edebiyatı','Şiir','Şair Shimalwest']::text[], 8.5, '{"poet":"Şair Shimalwest","poet_slug":"sair-shimalwest","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/isyan-73-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Körebe', 'korebe-sair-shimalwest-u6hqr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'hep körebe değil mi hayat 

birilerini ebelemek için 

ama ebelediğimizde 

anlamıyor muyuz 

aslında ebelendiğimizi 

ama körebenin en güzel yanı 

ebelediğinde görmek gerçek yüzünü 

hala tutabiliyorsan ebelediğini 

işte bu hayatın güzel yanı', 'hep körebe değil mi hayat  birilerini ebelemek için  ama ebelediğimizde  anlamıyor muyuz  aslında ebelendiğimizi  ama körebenin en güzel yan...', ARRAY['Türk Edebiyatı','Şiir','Şair Shimalwest']::text[], 8.5, '{"poet":"Şair Shimalwest","poet_slug":"sair-shimalwest","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/korebe-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Telefon', 'telefon-sair-shimalwest-9240o', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'aklım kaldı uzaklarda

gözüm daldı yollara

attım kendimi sokaklara

bir haber alayım

rahat bakayım ufuklara

zamansız oldu bu sıkıntı

beklemiyor aramamı

elim gidiyor telefona

parmaklarım basamıyor tuşlara

dayanamadım en sonunda

sarıldım telefona

çaldı çaldı açılmadı

aldı beni bir sıkıntı

kötü hissettim kendimi

çaresizlik miydi benimki', 'aklım kaldı uzaklarda gözüm daldı yollara attım kendimi sokaklara bir haber alayım rahat bakayım ufuklara zamansız oldu bu sıkıntı beklemiyo...', ARRAY['Türk Edebiyatı','Şiir','Şair Shimalwest']::text[], 8.5, '{"poet":"Şair Shimalwest","poet_slug":"sair-shimalwest","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/telefon-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beklemek', 'beklemek-sair-shimalwest-7ryj5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'hayatın en zor şeyi

sabrın çaresiz kaldığı an

yol beklemek

iz beklemek

haber beklemek

ama kim bilebilirdi ki

bir çift güzel gözün

sonsuza dek beklenebileceğini,

bir tutam mutluluk için

seni hep bekleyeceğim', 'hayatın en zor şeyi sabrın çaresiz kaldığı an yol beklemek iz beklemek haber beklemek ama kim bilebilirdi ki bir çift güzel gözün sonsuza de...', ARRAY['Türk Edebiyatı','Şiir','Şair Shimalwest']::text[], 8.5, '{"poet":"Şair Shimalwest","poet_slug":"sair-shimalwest","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/beklemek-32-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul', 'i-stanbul-sair-shimalwest-irut3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İstanbul da bir bahar akşamı

ilk mi son mu hatırlamıyorum

serinliğin tadını çıkartıyorum

belki de ondan umursamıyorum

İstanbul da hisardayım

anadolu mu rumeli mi hatırlamıyorum

manzaranın tadını çıkartıyorum

belki de ondan umursamıyorum

İstanbul da sohbet ediyorum

kız mı erkek mi hatırlamıyorum

paylaşmanın tadını çıkartıyorum

belki de ondan umursamıyorum

İstanbul da ağlıyorum

nedenini iyi hatırlıyorum

hüznün tadını çıkartıyorum

onun için umursuyorum', 'İstanbul da bir bahar akşamı ilk mi son mu hatırlamıyorum serinliğin tadını çıkartıyorum belki de ondan umursamıyorum İstanbul da hisardayım...', ARRAY['Türk Edebiyatı','Şiir','Şair Shimalwest']::text[], 8.5, '{"poet":"Şair Shimalwest","poet_slug":"sair-shimalwest","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/istanbul-152-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kor', 'kor-sair-shimalwest-o36qt', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'sevdanın bize ettiği

korda yüzümüzü aramaksa

daha çok yanacağız demektir

o korların arasında

kınından çıkan bıçağı

yerine sokmamak aslolan

bedeller ödemedikce

sevgi olmaz vazgeçilmez

seni seviyorum dedikce

keskinleşen bıçak

bedelleri öderken

çok kan akıtır

ama her bedelin sonunda

mutlaka mutluluk vardır', 'sevdanın bize ettiği korda yüzümüzü aramaksa daha çok yanacağız demektir o korların arasında kınından çıkan bıçağı yerine sokmamak aslolan b...', ARRAY['Türk Edebiyatı','Şiir','Şair Shimalwest']::text[], 8.5, '{"poet":"Şair Shimalwest","poet_slug":"sair-shimalwest","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/kor-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öpsene', 'opsene-sair-shimalwest-da6xv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'nedir sevebileceğini hissettiren

aşık olmak için umutlandıran

bir çift güzel göz mü

kalbinin derinlerine işleyen

bir güzel gülüş mü

içini sımsıcak yapan

konuşurken saçtığı neşe mi

seni kendinden alan

yada hepsi birden mi

ona sımsıkı bağlayan

sadece bir çift sözdür

bazen herşeyin sebebi

söylemezsem içimde kalır

öpsene beni', 'nedir sevebileceğini hissettiren aşık olmak için umutlandıran bir çift güzel göz mü kalbinin derinlerine işleyen bir güzel gülüş mü içini sı...', ARRAY['Türk Edebiyatı','Şiir','Şair Shimalwest']::text[], 8.5, '{"poet":"Şair Shimalwest","poet_slug":"sair-shimalwest","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/opsene-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlama Yeter', 'aglama-yeter-fikret-kanat-3cjyl', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'kaderdir diyerek avut kendini

gecenin sesiyle ağlama yeter

çilenin tığıyla örüp alnımı

ilmek ilmek derdi bağlama yeter

    aşkın tezgahında dert desen desen

    endamın selvidir cemalin ahsen

    artık bir şey demem eli de sevsen

    bakıp; ciğerimi dağlama yeter.

                        f.kanat/dtcf', 'kaderdir diyerek avut kendini gecenin sesiyle ağlama yeter çilenin tığıyla örüp alnımı ilmek ilmek derdi bağlama yeter     aşkın tezgahında ...', ARRAY['Türk Edebiyatı','Şiir','Fikret Kanat']::text[], 8.5, '{"poet":"Fikret Kanat","poet_slug":"fikret-kanat","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/aglama-yeter-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kul Koleksiyoncusu', 'kul-koleksiyoncusu-i-brahim-bayraktar-rydqy', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İşgüzarlık parayla, pulla değil ki; 

Kimisi kulağını tersten gösterir,

Akılla meseleyi halletmek varken,

Abasının altından sopa gösterir.

Her şeye kulp takar, bahaneler arar,

Ne bir selam verir; ne, hal hatır sorar,

Doğruyu söylesen de kötüye yorar,

Hep moral bozmak için çaba gösterir.

Görür ama görmezden gelir emeği,

Her kayanın altına sokar çomağı,

Kendine uydurdu mu fitne yamağı,

Verilen emekleri heba gösterir.

Herkesi kendisine kul etmek ister,

Dilini koparıp da lâl etmek ister,

Ağzınla kuş tutsan da pul etmek ister,

Güzel bir sözü bile kaba gösterir.

Kimine hoşgörülü, kimine kaba,

Kimine baskı, zulüm; kimine baba,

Dil desen pabuç gibi sanırsın yaba,

Duvar dibini bile oba gösterir.

Asi olur adın, boyun eğmeyince,

Doğruluktan yana taviz vermeyince,

Korkup yelkenleri yere sermeyince,

Rüzgâra yüzün dönüp, popo gösterir.

06.12.2004/Ankara', 'İşgüzarlık parayla, pulla değil ki;  Kimisi kulağını tersten gösterir, Akılla meseleyi halletmek varken, Abasının altından sopa gösterir. He...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Bayraktar']::text[], 8.5, '{"poet":"İbrahim Bayraktar","poet_slug":"i-brahim-bayraktar","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/kul-koleksiyoncusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acı Kahve...!', 'aci-kahve-hasan-basri-kale-bhrep', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'vefalı bir dudakta 

kırk yıl hatırı olurdu

acı bir kahvenin.

üstünde piştiği 

meşenin külü 

olsaydı

benden geriye kalan..

varlığımın bir anlamı olmadı sende

yok oluşumu anlardın

en azından..

.....

.....

bir işe yarardım

belki o zaman..!', 'vefalı bir dudakta  kırk yıl hatırı olurdu acı bir kahvenin. üstünde piştiği  meşenin külü  olsaydı benden geriye kalan.. varlığımın bir anl...', ARRAY['Türk Edebiyatı','Şiir','Hasan Basri Kale']::text[], 8.5, '{"poet":"Hasan Basri Kale","poet_slug":"hasan-basri-kale","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/aci-kahve-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaban...Şehir...', 'yaban-sehir-melek-ayaz-cgdod', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yanlızdım O şehirde,

Uyuduğum yatak benim değil

Ağladığımı görenler tanıdık değildi

Sessizliğime üzülenlerse burada yok.

Yanlızdım O şehirde,

Yaslanacağım agaç çoktan çürümüş...

Saklanacağım duvarlarsa orada değil,

Yaşadığım sevgi bile bana ait değildi...

Sırtımdaki ele inat gözlerimi açmayacağım,

Sevgiyi dört bir kapıya idam edişini görmiyeceğim...', 'Yanlızdım O şehirde, Uyuduğum yatak benim değil Ağladığımı görenler tanıdık değildi Sessizliğime üzülenlerse burada yok. Yanlızdım O şehirde...', ARRAY['Türk Edebiyatı','Şiir','Melek Ayaz']::text[], 8.5, '{"poet":"Melek Ayaz","poet_slug":"melek-ayaz","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/yaban-sehir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özleme Dair', 'ozleme-dair-sirma-mersin-0ph2u', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Şehir! 

Geceye teslim olmuşken

Bu şehrin kayıp karanlığı 

Sessizliğe boyanmış ürkek saatlerin

Yalnızlığa yol alması ile başlardı, özlem...

Gecenin acı suyu ile yudumlanan yalnızlığından bir yudum

Daha içerken...

Karanlığa düşen sessizlikleri yırtarken,

Yürek haykırışı satırları karalarken...

Sayfalara sarılan her duygu birbirini kovalar! 

Cümlelerin gölgesi ile oyun oynayan kalemle kağıt 

Her adımda büyüyen yaşamda...

Soluk alıp veren yüreğin içinde sıkışan düşünceler

Duygulara ses verirken

Devam ediyordu, hayaller...

05.12.04', 'Şehir!  Geceye teslim olmuşken Bu şehrin kayıp karanlığı  Sessizliğe boyanmış ürkek saatlerin Yalnızlığa yol alması ile başlardı, özlem... G...', ARRAY['Türk Edebiyatı','Şiir','Sırma Mersin']::text[], 8.5, '{"poet":"Sırma Mersin","poet_slug":"sirma-mersin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ozleme-dair-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kızıl...Gölgeler...', 'kizil-golgeler-melek-ayaz-ok7o2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Zemheri ayazında kızıl gölgelerle,

Hayallere dalar yüreğim,

Kar tanelerinde üşür,

Kızılda yanarım kimi günlerde,

Her su serpildiğinde yüreğime

Çocuklar gibi bilye oynarım.

Kendimden parçalar koparıp yuvarlardım.

Ve...

Parmaklarımın arasında yollardım sevdiklerime,

Ama...

Bende bilye yapacak ben kalmamışım.

Birazım yılda bir kez açılan çekmecelerde,

Birazım eğilip alamadığım toprakta kalmış,

Ve...bir...bilye,

Tüm gücümle sıktığım yumruğumun içinde,

Parlaklığını kaybetmiş son atışı bekliyor...', 'Zemheri ayazında kızıl gölgelerle, Hayallere dalar yüreğim, Kar tanelerinde üşür, Kızılda yanarım kimi günlerde, Her su serpildiğinde yüreği...', ARRAY['Türk Edebiyatı','Şiir','Melek Ayaz']::text[], 8.5, '{"poet":"Melek Ayaz","poet_slug":"melek-ayaz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kizil-golgeler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elma Ağacı', 'elma-agaci-bekir-mutlu-gokcesu-yycy8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir elma ağacım vardı

Bana hep bahardı...

Eskiden bu şehirde

Biz çok kalabalıktık

Sevdiğim insanlar yaşardı...

Neden yıkılıyor? 

Birer, birer duvarlar

Neden gökyüzümü

Çalıyorlar? 

Çoğalmaya durmuştuk içimizde

Azalırken birbirimize...

Bir de baktım ki

Ben elma ağacı olmuşum

Duvarlar bir, bir yıkılırken

Gözlerimin önünde...

...

Bir çocuk yürüyor hep

Bir sürü çocuk da peşinde

Düşüyor, kalkıyor, gülüyorlar

Zamanın birinde...

Düşlerimde...

Açık kalmış müzik kutusu

Toprak, yağmur, çimen kokusu

Karışmış annemin melodisine

Duruyor çocuk gözlerimin tuzu

Hala tebessümlerimde...

Kopup, kanıyor kabuğu dizlerimin

Dallara sürtününce bir keresinde

Farkında değilim

Ben elma ağacının tepesinde...

Bir kadın ağlıyor benim yerime

O zamanlardan seviyor beni

Sonra, sonra fark ediyorum 

Düşlerimde...

Elma kokuyor

Ve hala seviyor beni

Gülüyor çocukluğuma

İçin, için ağlıyor

Dizlerim aklına geldikçe...

Asırlar öncesinden benim

Ve bana aşık sonsuza dek

O kadın

Seçebiliyorum siluetini

Ölümsüzleşiyorum

Ölümsüzleşiyor

Ölümsüzleşiyoruz

Düşlerimde...', 'Bir elma ağacım vardı Bana hep bahardı... Eskiden bu şehirde Biz çok kalabalıktık Sevdiğim insanlar yaşardı... Neden yıkılıyor?  Birer, bire...', ARRAY['Türk Edebiyatı','Şiir','Bekir Mutlu Gökçesu']::text[], 8.5, '{"poet":"Bekir Mutlu Gökçesu","poet_slug":"bekir-mutlu-gokcesu","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/elma-agaci-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kızıltepeli Çocuk', 'kiziltepeli-cocuk-adulera-ayza-wur6m', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Neler oluyor orada

Ajanslarda bir haber

On iki yaşında bir çocuk

Terörist oluyor

Soruyorum sizlere 

On iki yaşında bir çocuk

Nasıl terörist oluyor! öldürülüyor

Bu işin doğrusunu anlatına bana

On iki yaşında bir çocuk

Kalem yerine kalaşnikof tutuyor

Kızıltepe ve Türk halkı dikkat et

Önce sana, sonra bana

O mermilerin altı tanesi sırtıma

Sıkın ulan sıkın,

O mermiler canıma', 'Neler oluyor orada Ajanslarda bir haber On iki yaşında bir çocuk Terörist oluyor Soruyorum sizlere  On iki yaşında bir çocuk Nasıl terörist ...', ARRAY['Türk Edebiyatı','Şiir','Adulera Ayza']::text[], 8.5, '{"poet":"Adulera Ayza","poet_slug":"adulera-ayza","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/kiziltepeli-cocuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılığın Yalan Gibi', 'ayriligin-yalan-gibi-nurten-koroglu-45aj8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'biten o aşkın ardından

bir pişmanlık mı kaldı ki

günler geçti aradan

ayrılığın yalan gibi

düşler her akşam bir geçmiş

bir tazelik sunar sanki

daha dün gibi yaşananlar

ayrılığın yalan gibi

şimdi belki çok mutlusun

belki de pişmansın deli gibi

benim başımda kasırgalar 

hala  eskisi gibi

yara almış savaşında

bırakmaz  eski hatıralar beni

gördüğüm bir düş misali

ayrılığın yalan gibi', 'biten o aşkın ardından bir pişmanlık mı kaldı ki günler geçti aradan ayrılığın yalan gibi düşler her akşam bir geçmiş bir tazelik sunar sank...', ARRAY['Türk Edebiyatı','Şiir','Nurten Köroğlu']::text[], 8.5, '{"poet":"Nurten Köroğlu","poet_slug":"nurten-koroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ayriligin-yalan-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir', 'bir-zuhal-aksulu-7j6ij', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Benden bir kere gittin de

Bekledim seni bir sene

Bir senemi daha çalacaksan

Yok artık bir daha dönme', 'Benden bir kere gittin de Bekledim seni bir sene Bir senemi daha çalacaksan Yok artık bir daha dönme...', ARRAY['Türk Edebiyatı','Şiir','Zuhal Aksulu']::text[], 8.5, '{"poet":"Zuhal Aksulu","poet_slug":"zuhal-aksulu","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/bir-26-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Binmişsin Sırtıma İnmem Diyorsun', 'binmissin-sirtima-i-nmem-diyorsun-murat-demir-uygat', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sana verdiklerim yetmedimi ki

Hala gelmiş benden can istiyorsun

Azabın, işkencen bitmedimi ki

Binmişsin sırtıma inmem diyorsun

Yeterin yokmudur senin yeterin

Söyle nedir söyle bu ettiklerin

Bir değil beş değil bir hayat boyu

Yetmedi mi bana çektirdiklerin

Çekil bir kenara eserine bak

Bak işte kalmışım bak yalınayak

Ne şefkatin gerek ne sevdan artık

Git beni ne olur git rahat bırak

Hergün sürünsemde sorma istemem

Ölsemde aşkından sana yar demem

Dağ değil, taş değil, çöl değil bana

Yol olsan üstüne basıp yürümem', 'Sana verdiklerim yetmedimi ki Hala gelmiş benden can istiyorsun Azabın, işkencen bitmedimi ki Binmişsin sırtıma inmem diyorsun Yeterin yokmu...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/binmissin-sirtima-inmem-diyorsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'II/Aşk', 'ii-ask-ali-gencay-ukrs2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen bir hayal kurdun

İçine beni,seni koydun

Ben bir dilek tuttum

İçine seni,aşkı koydum

Aşk! 

Mevsim,mevsim vurur beni

Yaprak döker ağaçlar

Ve serçeler dam arasına kaçışırlar 

Rüzgarın çıldırtan uğultusu

Okşar kanatları,öldüren dokunuşu

Kanadımda yok 

Nereye saklansam ki

Sen okşamazsan 

Ölürüm belki

Yüzüne güneş vurur

Saklandığın pencere arkasında

Yine kısık çalar radyo

Fallar tutarsın şarkılarda

Nihavent çalarsa 

Gülümseme dudaklarında

Hüzzam çalarsa 

Yağmur yağmalı dışarıda

Sen ağlama! 

Donarda göz yaşların 

Tutunamam kayarım,umutlarımda

Sen bir masal yazdın

İçine beni,seni koydun

Ben bir şiir yazdım

İçine seni,aşkı koydum', 'Sen bir hayal kurdun İçine beni,seni koydun Ben bir dilek tuttum İçine seni,aşkı koydum Aşk!  Mevsim,mevsim vurur beni Yaprak döker ağaçlar ...', ARRAY['Türk Edebiyatı','Şiir','Ali Gençay']::text[], 8.5, '{"poet":"Ali Gençay","poet_slug":"ali-gencay","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/ii-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dipsiz', 'dipsiz-ozge-baydil-l0aee', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dipsiz bir kuyuya atilan tas ne kadar agirsa,

Canim bedenime o kadar agir.

Tasiyamiyorum sensiz!', 'Dipsiz bir kuyuya atilan tas ne kadar agirsa, Canim bedenime o kadar agir. Tasiyamiyorum sensiz!...', ARRAY['Türk Edebiyatı','Şiir','Özge Baydil']::text[], 8.5, '{"poet":"Özge Baydil","poet_slug":"ozge-baydil","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/dipsiz-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Masal', 'masal-zuhal-aksulu-tc39u', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Masallar anlattılar bize hep

Kırmızı başlıklı kızı kurtaran

Bir avcı değil miydi? 

Pamuk prensesi gelip götüren 

Yakışıklı prensiydi

İnandım hep bu mucizelere

Uyuyan güzeldim ben de

Nefes almadan, gülmeden

Sevilmeyip sevmeden

Yıllar boyu bekledim

Orda olduğunu bilmeden

Masallardaki sihirli kuşlar gibi

Geldin kondun birgün pencereme

Seninle uçtum göklerde

Dünyayı yeniden keşfettim sende

Sen beni uykumdan uyandırmıştın

Belki de bilmeden kendine bağlamıştın

Çok güzel vakit geçirmiştik de

En alıştığım anda yanımda kalmamıştın

Seninle kendi masalımızı yazmıştık

Her masal mutlu biter derler

Ama bunu biz başaramadık

Mutlu bir son yazamadık

''Sen başka bir masalın kahramanısın

Aslında her zaman orda kalmalısın''', 'Masallar anlattılar bize hep Kırmızı başlıklı kızı kurtaran Bir avcı değil miydi?  Pamuk prensesi gelip götüren  Yakışıklı prensiydi İnandım...', ARRAY['Türk Edebiyatı','Şiir','Zuhal Aksulu']::text[], 8.5, '{"poet":"Zuhal Aksulu","poet_slug":"zuhal-aksulu","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/masal-68-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Genç', 'genc-mehmet-isikoglu-ly89v', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'GENÇ! 

Öz değerini bil  kendini tanı

Vaktinde yakala şöhreti şanı

Her zaman yanında taşı oltanı

Kolla fırsatları boşa yandırtma

Kapılma korkuya güven kendine

Sakın düşmeyesin düşman fendine

Dikkat! getirirler seni punduna

Tuşa gelip sırtın yere kondurtma

Birbirine kenetlen de güçlü ol 

Parçalanıp tutmayasın ayrı yol 

Hiç habersiz götürürler kafa-kol 

Sakın işi o raddeye vardırtma 

Tehlikeler dolu hep solun sağın

İnancındır senin kuvvet kaynağın

Gerisinde kalma yaşanan çağın 

Geri kalmış damgasını vurdurtma', 'GENÇ!  Öz değerini bil  kendini tanı Vaktinde yakala şöhreti şanı Her zaman yanında taşı oltanı Kolla fırsatları boşa yandırtma Kapılma kork...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Işıkoğlu']::text[], 8.5, '{"poet":"Mehmet Işıkoğlu","poet_slug":"mehmet-isikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/genc-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akıl Parası', 'akil-parasi-mehmet-isikoglu-duwaa', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Akarken musluklar doldur testini

Bilmelisin düşmanını dostunu

Şimdi fırsat elden kaçtı ne fayda

Kurtarabilirsen kurtar postunu

Sular boşa aktı içenler gitti

Doymayan darıldı doyan eritti

Kalmadı çevrede dost çok sayıda

“Atı alan üsküdarı da geçti”

Umdun  göremedin sen de refahı

Mahvettin kendini çekersin ahı

Kalmadı varlığın değecek kayda

Suçlu sensin kime atsan günahı 

Oldu  paralar tren sen de istasyon

Ellerinden geçti yüzlerce milyon

Şimdi bak yayasın tren de yok rayda

Haklı“ para para „ diyen Napolyon

Geçti yaşın düştü suya arzular

Kurudu çeşmeler akmıyor sular

Şimdi içme suyun derin kuyuda

Kolla fırsatları ders olsun bunlar.', 'Akarken musluklar doldur testini Bilmelisin düşmanını dostunu Şimdi fırsat elden kaçtı ne fayda Kurtarabilirsen kurtar postunu Sular boşa ak...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Işıkoğlu']::text[], 8.5, '{"poet":"Mehmet Işıkoğlu","poet_slug":"mehmet-isikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/akil-parasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanmadım', 'yanmadim-zuhal-aksulu-9bkqv', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yanmadım...

Ben hiç böyle yanmadım

Gece soğuk

Duvarlar soğuk

Sen soğuk

Soğuk ellerim başımda

Herşey neden bu kadar donuk

Yanmadım

Ben hiç böyle aldanmadım

Gece sessiz

Duvarlar sessiz

Sen sessiz

Sessiz gözyaşlarım süzülür

Ağlar dururum sessiz sessiiz

Yanmadım

Ben hiç böyle ağlamadım

Bir sen varsın sanki

Bir sen

Bir de sevdan, beni benden eden

Yanmadım

Ben hiç böyle bağlanmadım

Sen 

Evet sen

Biraz beni dinlesen...

Sevgimi bir görsen

Yanmadım

Ben hiç böyle yalvarmadım

Sonunda oldu işte

Bir sana yandım

Bir sana aldandım

Sadece senn için ağladım

Sadece sana bağlandım

Ve hayatımda ilk defa 

Bir tanrı misali

El açıp sana yalvardım...', 'Yanmadım... Ben hiç böyle yanmadım Gece soğuk Duvarlar soğuk Sen soğuk Soğuk ellerim başımda Herşey neden bu kadar donuk Yanmadım Ben hiç bö...', ARRAY['Türk Edebiyatı','Şiir','Zuhal Aksulu']::text[], 8.5, '{"poet":"Zuhal Aksulu","poet_slug":"zuhal-aksulu","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/yanmadim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim Tutkun arkadaşım', 'benim-tutkun-arkadasim-emel-manav-yizf9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kimi tanıdımsa 

Aşka soyunan 

Gözleri ırmaktır, 

Yüreği volkan, 

Ve kafa karışık, ruh takıntılı. 

Mutluluksa eğer bu halin adı, 

Neden gülünmüyor da 

Yüzler hep ağlamaklı.. 

Kitabını yazmak mümkün mü aşkın? 

Ki bir şeyler acıtsa da canını. 

At desem aşkını, 

İşine gelmez. 

Çek dersin bu yükü 

Yüzü hiç gülmez. 

Belki; aşık arkadaşlardan, 

Biraz uzak durmalı! !', 'Kimi tanıdımsa  Aşka soyunan  Gözleri ırmaktır,  Yüreği volkan,  Ve kafa karışık, ruh takıntılı.  Mutluluksa eğer bu halin adı,  Neden gülün...', ARRAY['Türk Edebiyatı','Şiir','Emel Manav']::text[], 8.5, '{"poet":"Emel Manav","poet_slug":"emel-manav","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/benim-tutkun-arkadasim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçimdeki Fırtına', 'i-cimdeki-firtina-i-brahim-necati-gunay-zgl83', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gecenin yalnızlığını yırtan acı bir çığlık

Kulaklarımda çınlayan müthiş bir ıslık

Sessiz ve derinden gelen bir fırtına

Duygularım kendini aşmış ummandaki azgın dalgalar

Sensizliğin göz yaşlarımın akan damarlarındaki parıltısı

Çağlayan pınarların köpüren ırmakların çakıl taş sesleri

Derbeder olmuş gönül denen tutamadığım serseri

Dinlediğim her aşk sözleri ile dolu duygusal nameleri

Terk edilmişliğin hüzününü yaşarken mutluluğumun düşleri

İçimdeki dinmek bilmeyen bilemediğim o sevginin dişleri

Yağan yağmur ıslak dudaklar yapışmış saçlar

Bir adım ilerde apansız geçen bir hayalin ümit ışığı

Kaldırımları sarsan demir arabanın o yağız Akdenizli yiğiti

Son Arnavut kaldırımlarından çıkarken yokuş yukarı

Zengin olmanın o dayanılmaz hayali ve ışıldıyan boğaz

Kör etmiş gözlerinin içindeki yanan o ateşi

Ne kadar yazsam yazamam bitmiyor içimdeki kor fırtına', 'Gecenin yalnızlığını yırtan acı bir çığlık Kulaklarımda çınlayan müthiş bir ıslık Sessiz ve derinden gelen bir fırtına Duygularım kendini aş...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Necati Günay']::text[], 8.5, '{"poet":"İbrahim Necati Günay","poet_slug":"i-brahim-necati-gunay","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/icimdeki-firtina-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pınar Kurudu Akmıyor', 'pinar-kurudu-akmiyor-emel-manav-ita6w', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Beni yıktın, kör baktırdın 

Gönül defterimi yaktırdın 

Geldi başa çekilecek 

Yol ecelse gidilecek 

Bu aşk beni öldürecek 

Veya bir gün güldürecek 

Yara derin dert acı 

Sensin bunun ilacı 

Göz görecek de bakmıyor 

Pınar kurudu akmıyor', 'Beni yıktın, kör baktırdın  Gönül defterimi yaktırdın  Geldi başa çekilecek  Yol ecelse gidilecek  Bu aşk beni öldürecek  Veya bir gün güldü...', ARRAY['Türk Edebiyatı','Şiir','Emel Manav']::text[], 8.5, '{"poet":"Emel Manav","poet_slug":"emel-manav","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/pinar-kurudu-akmiyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgiyi Anlatmak', 'sevgiyi-anlatmak-zuhal-aksulu-1769s', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sevgi nerede

Heryerde

Sevgi kalbimde

Sevgi gözlerimde

Sevgi herşeyde...

Sen neredesin

Nereden bileceksin 

Sevgi senin için

Sevgi hayat için

O sevgili sensin..

Seni sensiz sevmek

''Seni seviyorum'' diyememek

Seni aylarca görememek

Hergün yeniden ölmek

Yeni sevgilerle dönmek demek...', 'Sevgi nerede Heryerde Sevgi kalbimde Sevgi gözlerimde Sevgi herşeyde... Sen neredesin Nereden bileceksin  Sevgi senin için Sevgi hayat için ...', ARRAY['Türk Edebiyatı','Şiir','Zuhal Aksulu']::text[], 8.5, '{"poet":"Zuhal Aksulu","poet_slug":"zuhal-aksulu","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sevgiyi-anlatmak-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Anlatmak', 'seni-anlatmak-zuhal-aksulu-dnjw2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gözlerim isyan ediyor

Kalbim çarpıyor

Elim bir telaş içinde

Seni anlatıyor

Ama yazılan her kelimede

Her sevgide

İçim yanıyor

İçim yanıyor....', 'Gözlerim isyan ediyor Kalbim çarpıyor Elim bir telaş içinde Seni anlatıyor Ama yazılan her kelimede Her sevgide İçim yanıyor İçim yanıyor......', ARRAY['Türk Edebiyatı','Şiir','Zuhal Aksulu']::text[], 8.5, '{"poet":"Zuhal Aksulu","poet_slug":"zuhal-aksulu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/seni-anlatmak-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'CaNıN SaĞ OLsUN,', 'canin-sag-olsun-mine-ozdemirtas-egf7r', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'dilinden bal damlarmış 

aynaya dargınların

buharına sitem yazılıyken

camların

kırılıp atılmalarını 

nasıl onayladın? 

oysa

ne lam dı ne de cim

anlattıklarım

keçilik var ya serde

anlamadın

ormana kulak verseydin bir an

duyardın. 

''akde vefa ''diye 

hışırdadığını yaprakların

bir tek soluk yeterdi biliyorsun

sönmesi için yangınların

senin

canın sağ olsun

kıpırdamadın

şimdi

türküsünü rahatça söyleyebilirsin

köpüklü fincanların

kurunun yanında yaşta yanıyor

.................

...............

gözün aydın.

06/12/2004....kartal', 'dilinden bal damlarmış  aynaya dargınların buharına sitem yazılıyken camların kırılıp atılmalarını  nasıl onayladın?  oysa ne lam dı ne de c...', ARRAY['Türk Edebiyatı','Şiir','Mine Özdemirtaş']::text[], 8.5, '{"poet":"Mine Özdemirtaş","poet_slug":"mine-ozdemirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/canin-sag-olsun-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Lüzumat Müzekkeresi', 'luzumat-muzekkeresi-abdurrahim-karakoc-nfs3w', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Uzun boylu, kısa boylu

Ölse ne ki, kalsa ne ki? 

Üç-beş yüz bin işçi, köylü

Ölse ne ki, kalsa ne ki? 

Fark etmez ırgat, amele

Harç diye basın temele

Alt tarafı hepsi köle

Ölse ne ki, kalsa ne ki? 

Hayatına küstü memur

Yediğini kustu memur

Altı memur, üstü memur

Ölse ne ki, kalsa ne ki? 

Vurguncuya işlesin çark

Namuslular etmesin fark

Esnafın destesi beş mark

Ölse ne ki, kalsa ne ki? 

Dulu,yetimi kim arar

İmhasına verin karar

Emekliler zaten zarar

Ölse ne ki, kalsa ne ki? 

İşsizler sürülsün yurttan

Büyükler kurtulsun dertten

İnsanlar kemikten, etten

Ölse ne ki, kalsa ne ki? 

Temizlensin sathı vatan

Sevinsin pusuda yatan

Vatandaş lüzumsuz zaten

Ölse ne ki, kalsa ne ki? 

(Yasaklı Rüyalar)', 'Uzun boylu, kısa boylu Ölse ne ki, kalsa ne ki?  Üç-beş yüz bin işçi, köylü Ölse ne ki, kalsa ne ki?  Fark etmez ırgat, amele Harç diye bası...', ARRAY['Türk Edebiyatı','Şiir','Abdurrahim Karakoç']::text[], 8.5, '{"poet":"Abdurrahim Karakoç","poet_slug":"abdurrahim-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/luzumat-muzekkeresi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gör-Dinle-Bil ve Anla beni', 'gor-dinle-bil-ve-anla-beni-orkun-isik-gcvp4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'ne yapsam, çizemiyorum seni 

ne olur gözyaşımda gör kendini 

ne yapsam, anlatamıyorum seni 

ne olur suskularımda dinle beni 

düşerim alevlere seni anarak

yudum yudum içerim kanarak

bir busede hayatı sanarak

ne olur düşlerinde bil beni

küskülerim ayandır dilsiz

umutlarım yitiktir ve ilsiz

yaşanırmı  hayat sevgisiz

ne olur usunda anla beni...', 'ne yapsam, çizemiyorum seni  ne olur gözyaşımda gör kendini  ne yapsam, anlatamıyorum seni  ne olur suskularımda dinle beni  düşerim alevler...', ARRAY['Türk Edebiyatı','Şiir','Orkun Işık']::text[], 8.5, '{"poet":"Orkun Işık","poet_slug":"orkun-isik","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gor-dinle-bil-ve-anla-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlemeyi Özle...', 'ozlemeyi-ozle-i-brahim-ethem-bingul-nv2wn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kayboldum

Her kayboluşta sende buldum kendimi

Hasretin ömrümü kışa çevirdi vakitsiz

Sen bahar yaşadın başka baharlarda umarsızca...

Sahile vurdu sandalım

Karaya oturdu umutlarım

Boranlara yâr oldu aşk şarkılarım...

Yazılan her satırın

Mürekkebi göz yaşlarım

Dağıldım...

Her zerremle 

Son sözüm sevgi bilmeze...

Özlemeyi özle 

Bu ne demek deme

Bunu bilen bilir yürek dilinde...

www.iebingul.com', 'Kayboldum Her kayboluşta sende buldum kendimi Hasretin ömrümü kışa çevirdi vakitsiz Sen bahar yaşadın başka baharlarda umarsızca... Sahile v...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ozlemeyi-ozle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nedir ki', 'nedir-ki-burhan-kucuk-nduyg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Nedir ki

Nedir ki ömür dediğin

Gözümü bir açtım

Orta yaşlı bir adamım

Sokakta çocuklar amca

Gençler ağabey derken

Anladım...

Nerde benim çocukluğum

Çoktan eskitmişim 

Bayramlık ayakkabılarımı

Oysa dün saklamıştım

Altındaydı yastığımın

Hani nerde sırt çantam

Üzerinde kaymıştım

Daha dün kar yağarken 

Karda yuvarlandığım önlüğüm

Ya kolalı yakalığım

Hani nerde tahta tabancam

Kırılmıştı,komen oynarken

Hani nerde Hacı Bakkal

Topumla camını kırdığım

Nerde yaldızlı şiir defterim

Çocukluğumu yazdığım

Nedir ki ömür dediğin

Gözümü bir açtım

Orta yaşlı bir adamım

Kim bilir? 

Belki de şanslıyım

Burhan KÜÇÜK

Kdz.Ereğli-05.12.2004', 'Nedir ki Nedir ki ömür dediğin Gözümü bir açtım Orta yaşlı bir adamım Sokakta çocuklar amca Gençler ağabey derken Anladım... Nerde benim çoc...', ARRAY['Türk Edebiyatı','Şiir','Burhan Küçük']::text[], 8.5, '{"poet":"Burhan Küçük","poet_slug":"burhan-kucuk","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/nedir-ki-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '^^^1 Kasım^^', '1-kasim-talip-sinecikli-5molp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Geldin demek,

İnan geleceğini hiç sanmıyordum,

Yani gelecektin biliyordum ama 

Seni görebileceğimi umut etmiyordum

Öyle olmadı,geldin karşımdasın

Karşılaşacağımızı bilsem hazırlanırdım

Nedense ben

Bütün önemli zamanlarda hazırlıksız yakalanırım

Bazen sarhoş olurum

Bazen uykusuz

Bazende böyle saçım sakalıma karışmış darma perişan

Yine hazırlıksız yakalandım velhasıl kelam

Yine sararmış rengin,yapraklarını dökmüşsün

Beni çökertmek isterken,sen kendin çökmüşsün

Niye soruyosun ki halimi hatırımı

Yıllardır beni takip etmiyormusun

Ne kadar bahtiyar,ne denli bahtsız olduğumu 

Sen benden daha iyi biliyorsun

Ne getirdin bu defa gelirken,çantandakiler ne

Yine avuç dolusu halay kırıklığı

Parça parça umutsuzluk

Birdolu gözyaşı mı

Bir tutam mutluluk,bir yudum umut yok mu

Ya da bir parça sevgi

Eski aşk acılarım geride kaldı

Şimdi elindekiler yenileri mi

Kusura kalma unuttum demeyi,geç otur hoşgeldin

Bir armağanda senden olsun bir kaç tel ak saçım

Bütün gençliğimi elimden aldın 1 Kasım

Ne getirdin bana ne götüreceksin 30 yaşım', 'Geldin demek, İnan geleceğini hiç sanmıyordum, Yani gelecektin biliyordum ama  Seni görebileceğimi umut etmiyordum Öyle olmadı,geldin karşım...', ARRAY['Türk Edebiyatı','Şiir','Talip Sinecikli']::text[], 8.5, '{"poet":"Talip Sinecikli","poet_slug":"talip-sinecikli","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/1-kasim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne zor şey', 'ne-zor-sey-i-brahim-duskun-94ycs', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ne kadarda soğuktu

zemheriydi seni alıp giden ölüm

yüreği temmuz ateşi gibi sıcak

umut alevli dost

yitik aşklar

yüreğine gömülü sevdalar

öyle kendine saklı

çekip gittin

bir ocak gününde

sivasta.

ufukta beliren umutlardan 

yaşanır dunyalar yaratırdın

kimini paylaşırdın

ne güzel umutlardı

öyle saf,sade,içli

sahiden yaşamak neydi

ölmek neydi

daha bir bardak çay içimiydi 

böyle insanı bırakıpta gitmek neydi

gittin be dost

gelmez oldun

ocakta ölüm ne zor şey 

ocakta ölüme durmak

ocakta seni ölüme sunmak

ne zor şey.', 'ne kadarda soğuktu zemheriydi seni alıp giden ölüm yüreği temmuz ateşi gibi sıcak umut alevli dost yitik aşklar yüreğine gömülü sevdalar öyl...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Düşkün']::text[], 8.5, '{"poet":"İbrahim Düşkün","poet_slug":"i-brahim-duskun","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/ne-zor-sey-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öğrendim', 'ogrendim-sair-melisa-1-fat1j', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Birlerin içinde yalnızlığı 

İkilerin içinde bölünmeyi öğrendim

Tam piştim derken 

Çiy düştü üzerime 

Üşümeyi öğrendim', 'Birlerin içinde yalnızlığı  İkilerin içinde bölünmeyi öğrendim Tam piştim derken  Çiy düştü üzerime  Üşümeyi öğrendim...', ARRAY['Türk Edebiyatı','Şiir','Şair Melisa_1']::text[], 8.5, '{"poet":"Şair Melisa_1","poet_slug":"sair-melisa-1","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/ogrendim-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senden Gayrısı Bana Haramdır.', 'senden-gayrisi-bana-haramdir-ali-osman-yilmaz-rklyp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kırmızı gülün çevresi,

Dikendir,har’dır,

O güle yalnız bülbül mü? 

Sanırsın ki yanandır.

Can''a,sevdiği canandır,

Gece gökyüzüne bakın,

O bana yıldızdır,Ay’dır,

Başkası da, yalandır.

Seviyorum seni güzel,

Canım sana helaldir,

Sarı saçların,mavi gözlerinden,

Gayrısı bana haramdır.

Sahilde duyduğun ses,

Rüzgarın getirdiği nefes,

Duyduğun türküdeki o es,

Sana yolladığım selamdır.', 'Kırmızı gülün çevresi, Dikendir,har’dır, O güle yalnız bülbül mü?  Sanırsın ki yanandır. Can''a,sevdiği canandır, Gece gökyüzüne bakın, O ban...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/senden-gayrisi-bana-haramdir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geçer mi Sensiz? Yine Bu Yaz.', 'gecer-mi-sensiz-yine-bu-yaz-ali-osman-yilmaz-4h12x', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gül bahçesinde yaptığın,

Bülbül için bir naz,

Sarı başaklar gibi,

Saçına takmışsın kiraz,

Dudaklarımdan dökülen,

Tanrıya ettiğim niyaz,

Sana kavuşmaktır dileğim,

Yoksa,nasıl geçecek? 

Sensiz yine bu yaz.', 'Gül bahçesinde yaptığın, Bülbül için bir naz, Sarı başaklar gibi, Saçına takmışsın kiraz, Dudaklarımdan dökülen, Tanrıya ettiğim niyaz, Sana...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/gecer-mi-sensiz-yine-bu-yaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Türk''ün Ağıdı', 'turk-un-agidi-habip-sabanli-wukiu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Evet ben bir Türk genciydim.

Bilğe kağan''ı, Kür-şad''ı, ve Osmanlı''yı bilirdim.

Örfümü, töremi, namusumu ve ülkemi korurdum.

Siz Türklüğümü kaybettirmeden önce,

Ben Türkoğlu Türk''tüm...

Yedi cihana hükümdar olmuş ecdatlarım.

Dizliye diz çöktürmüş başlıya baş eğdirmiş.

Ülküyü Nizam-ı Alem bilip, akınlar etmiş.

İslamın kalesi, müminlerin halifesi olmuş.

Ben, ben bunlarıda bilirdim.

Siz Türklüğümü kaybettirmeden önce,

Ben Türkoğlu Türk''tüm...

Damarımdaki asil kanıda bilirdim.

Çanakkale''i sakarya''yı Ötüken''i bilirdim.

Büyüklerimi severdim, sayardım.

Yani ben, beni bilirdim.

Siz Türklüğümü kaybettirmeden önce,

Ben Türkoğlu Türk''tüm...

Bayrak yere düşerken alkışlamayı ögrendik.

Avrupa''lı gibi yaşamaya alıştırıldık.

Burjuvalara özendik, biz bizi unuttuk.

Eğlence diye boğazımıza kadar pisliğe battık.

Gençlik artık Türk''ü İslam''ı degil Avrupa''yı biliyor.

Ben bayrağın  üstündeki al kanı da bilirdim.

Siz Türklüğümü kaybettirmeden önce,

Ben Türkoğlu Türk''tüm...

BİZ BUNUN İÇİN Mİ YARATILDIK? 

EY TÜRK MİLLETİ! TİTRE VE ÖZÜNE DÖN', 'Evet ben bir Türk genciydim. Bilğe kağan''ı, Kür-şad''ı, ve Osmanlı''yı bilirdim. Örfümü, töremi, namusumu ve ülkemi korurdum. Siz Türklüğümü k...', ARRAY['Türk Edebiyatı','Şiir','Habip Sabanlı']::text[], 8.5, '{"poet":"Habip Sabanlı","poet_slug":"habip-sabanli","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/turk-un-agidi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İhanet', 'i-hanet-necmiye-sarpkaya-01dvt', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yemeği ekmeği aşı gıdası ihanet

Suyu havası hayat pınarı ihanet

Ona sorulur mu ne neden niçin

Hayat Kaynağı kanı canı ihanet', 'Yemeği ekmeği aşı gıdası ihanet Suyu havası hayat pınarı ihanet Ona sorulur mu ne neden niçin Hayat Kaynağı kanı canı ihanet...', ARRAY['Türk Edebiyatı','Şiir','Necmiye Sarpkaya']::text[], 8.5, '{"poet":"Necmiye Sarpkaya","poet_slug":"necmiye-sarpkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ihanet-39-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
