INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unut Ne Olursun', 'unut-ne-olursun-kazim-tinaz-rn0ax', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir vefasız uğruna, ağlamaya değer mi? 

Ağlama be! arkadaşım, unut ne olursun.

Kırılan gururuna, o vefasız değer mi? 

İçme be! arkadaşım, unut ne olursun.

O vicdansız gelip de, seni mi arayacak? 

Yıkılsan bir yerlere, seni mi kaldıracak? 

Sebep oldun desen, sana mı aldıracak? 

İçme be! arkadaşım, unut ne olursun.

Uğrunda öldüğün, sevdim mi diyecek? 

Uğrayıp mezarına geldim mi diyecek? 

Devirdiğin şişeler, onu mu getirecek? 

İçme be! arkadaşım, unut ne olursun.', 'Bir vefasız uğruna, ağlamaya değer mi?  Ağlama be! arkadaşım, unut ne olursun. Kırılan gururuna, o vefasız değer mi?  İçme be! arkadaşım, un...', ARRAY['Türk Edebiyatı','Şiir','Kazım Tınaz']::text[], 8.5, '{"poet":"Kazım Tınaz","poet_slug":"kazim-tinaz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/unut-ne-olursun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umutlarım', 'umutlarim-baran-can-ij6m8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İstasyona geldim, 

Kimseler yok.

Ne biletçi, ne kondüktör,

Ne de bekleyen treni.

Raylara çıktım, 

Görünürde tren de yok.

Yürüdüm raylarda,

Denize taş atarak.

Suda taş sektirdim,

Gecenin karanlığında. 

Seni düşündüm; 

Umutlandım.

Tren geçti; 

Umutlarım raylara takılı kaldı.', 'İstasyona geldim,  Kimseler yok. Ne biletçi, ne kondüktör, Ne de bekleyen treni. Raylara çıktım,  Görünürde tren de yok. Yürüdüm raylarda, D...', ARRAY['Türk Edebiyatı','Şiir','Baran Can']::text[], 8.5, '{"poet":"Baran Can","poet_slug":"baran-can","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/umutlarim-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kısırdöngü', 'kisirdongu-cem-han-3lg0a', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hayatın acımasızlığı olmasaydı,

Dostlarımızın bize acıdığı belli olmazdı.

Hayatın ve dostların acımasızlığı olmasaydı...

Kalbimizin sızlaması olmaz,

Sevinçler yerini acılara bırakmazdı.', 'Hayatın acımasızlığı olmasaydı, Dostlarımızın bize acıdığı belli olmazdı. Hayatın ve dostların acımasızlığı olmasaydı... Kalbimizin sızlamas...', ARRAY['Türk Edebiyatı','Şiir','Cem Han']::text[], 8.5, '{"poet":"Cem Han","poet_slug":"cem-han","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/kisirdongu-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Çocuk Ağlıyor', 'bir-cocuk-agliyor-baran-can-hbjkm', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gecenin hüznü gibi,

Çöker üstüme ayrılık.

Başlar kor gibi yakmaya,

Aşk yangını, yüreğimi.

Şimdi ben; 

Çatısı başına geçecek, 

Bir virane gibiyim.

Beynimde çakan kıvılcım,

Yüreğime akıtıyor gözyaşlarını.

Ve; 

Yüreğimin yangın yerinde,

Usul usul bir çocuk ağlıyor.', 'Gecenin hüznü gibi, Çöker üstüme ayrılık. Başlar kor gibi yakmaya, Aşk yangını, yüreğimi. Şimdi ben;  Çatısı başına geçecek,  Bir virane gib...', ARRAY['Türk Edebiyatı','Şiir','Baran Can']::text[], 8.5, '{"poet":"Baran Can","poet_slug":"baran-can","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bir-cocuk-agliyor-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sür-ek', 'sur-ek-ahmet-aksoy-mdawq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Siyanür pazarında bunalma

Bir çocuk kokusu saflığında

İçre yenik alış-veriş

Soluk borusundan akarya

Tırtılın ömrü kelebeğin gönlü

Zaman uz-ar teninde devrik

Yaşam kapalı koza

….Annenin elleri yok ki!', 'Siyanür pazarında bunalma Bir çocuk kokusu saflığında İçre yenik alış-veriş Soluk borusundan akarya Tırtılın ömrü kelebeğin gönlü Zaman uz-a...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sur-ek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bizim Çoban Nerede?', 'bizim-coban-nerede-kadir-soyturk-7hzbe', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bizim çoban nerede; hiç bakmaz mı işine? 

Bu  “sırtlan sürüsü” nün içimizde işi ne?', 'Bizim çoban nerede; hiç bakmaz mı işine?  Bu  “sırtlan sürüsü” nün içimizde işi ne?...', ARRAY['Türk Edebiyatı','Şiir','Kadir Soytürk']::text[], 8.5, '{"poet":"Kadir Soytürk","poet_slug":"kadir-soyturk","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/bizim-coban-nerede-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeni Gün', 'yeni-gun-seckin-cingoz-55e13', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu gün yeniyken sen doğdun

Gözün görmesinden önce

Anlatmıştın o sahilleri,,

Taşın öncesini,

Bu gün benim günüm

Sahildeki taşın yosunu sildim,

Başlayan günün öncesinde 

Yine senin varlığın 

Dalganın kızgınlığında

Bir ateşin sönüşü

Ve kül,,

05/01/2001', 'Bu gün yeniyken sen doğdun Gözün görmesinden önce Anlatmıştın o sahilleri,, Taşın öncesini, Bu gün benim günüm Sahildeki taşın yosunu sildim...', ARRAY['Türk Edebiyatı','Şiir','Seçkin Cingöz']::text[], 8.5, '{"poet":"Seçkin Cingöz","poet_slug":"seckin-cingoz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yeni-gun-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ÇOCUKLAR Çiçektir! ..', 'cocuklar-cicektir-asik-sahturna-x6vfd', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '‘Uluslararası Çocuk Günü’ ne hitaben yazıp, bestelediğimiz  yapıtımızı ‘Çocukların umutlu yarınlarına’ sunuyoruz…

Tüm Renklerin Buket Oluşturduğu “Kardeşlik Bahçesinde“ buluşmak üzere! ... 

                        

ÇOCUKLAR ÇİÇEKTİR! ...

‘Öteler’ ötesinden

Figan çığlık sesinden

Koparıp alınmasın 

Çocuklar Annesinden! ...

Nakarat: Gelin çocuklar gelin

El -ele tutuşalım                               

Yarınlara koşalım! ...

Savaşlar söndürülsün

Yaşama döndürülsün

Dünya esenlik olsun

Çocuklar güldürülsün

Nakarat: Gelin çocuklar gelin, el-ele tutuşalım

Yarınlara koşalım! ....

Siyah”beyaz”-sarısı

Bir elmanın yarısı…

ŞahTurna tüm çocukları

Birer “çiçek” arısı…! 

                                             

Söz ve Müzik: Aşık  Şah Turna  (Ozan Şahturna)  

Yorum ve aranje: Ozan Şiar Ağdaşan www.siarcan.com

Vokalist Genç Çocuklar: ŞAFAK ve ŞİRİN AĞDAŞAN  Müzik Grubu

ŞAHTURNA KÜLTÜR ve SANAT Evi

www.sahturna.com', '‘Uluslararası Çocuk Günü’ ne hitaben yazıp, bestelediğimiz  yapıtımızı ‘Çocukların umutlu yarınlarına’ sunuyoruz… Tüm Renklerin Buket Oluştu...', ARRAY['Türk Edebiyatı','Şiir','Aşık Şahturna']::text[], 8.5, '{"poet":"Aşık Şahturna","poet_slug":"asik-sahturna","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/cocuklar-cicektir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Al', 'al-yasar-dogan-74gx3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Al

Atımı kırbacımı

Kuşlarımı

Kanatlarımı al

Gözlerimi

Hülyalarımı al

Yüzüne yüz

Gözüne göz

Ruhuna ruhum girsin

Nasırımı

Sancımı 

Çığlığımı

Sevdamı al

Kalbine aşk girsin

Al Ey Aç

Gel de doy masamda

Al şu kilidi

Önce ceviz ruhunu

Sonra

Evrene giden kapıları aç

İtlik doyurmaz seni

İtini bağlayıp çığlık ağacına

Ruhunla gel

Sil timsah göz yaşlarını

Göz yaşlarımdan bir damla al

Koy onu gözlerine

Sonra aç gözlerini

Eline bir kadeh bir de ah al

Ve yanına

Vahlarını

Ahlarını

Yakmak için

henüz çakmamış bir çakmak al

Çak

Ateşi ışığa

Yak 

Beni kendinde

Sonra keyfine bak

Gözlerimle bak

Yaşar Doğan  / Lolan	07/12/04', 'Al Atımı kırbacımı Kuşlarımı Kanatlarımı al Gözlerimi Hülyalarımı al Yüzüne yüz Gözüne göz Ruhuna ruhum girsin Nasırımı Sancımı  Çığlığımı S...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Doğan']::text[], 8.5, '{"poet":"Yaşar Doğan","poet_slug":"yasar-dogan","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/al-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çamurun Günahı', 'camurun-gunahi-yasar-dogan-tbps6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Her şey bir hayalle başladı

Koca bir yalnızlıktan sonra

Issızlığın çölleri

Dönünce baş ağrılarına

Yaratıcı

Önce hayali yarattı

Organikliğiyle 

Sonra renkleri

Ardı sıra ahenkleri

Ve her şeye bir ad

Bir sebep verdi

Tutup sildi sonra

Her şeyin hafızasını

Ve uyuyunca her kes

Sabaha 

Geceden

Sadece rüyası kaldı

Ve her şey hayal edilebilirdi

Günden güne devrilen zamanla

Yoklarken içini insan

Kardeşliğiyle yücelebilirdi

Her şeyin üstünde

Üstün insanda

Güzelliğini

Ve yaratıcısını

Bu ahenkler arasında

Orda keşfedilirdi

Çamurun ne günahı var

İnsan gidip içine batmışsa

Yaşar Doğan	/	Lolan  07/12/04', 'Her şey bir hayalle başladı Koca bir yalnızlıktan sonra Issızlığın çölleri Dönünce baş ağrılarına Yaratıcı Önce hayali yarattı Organikliğiyl...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Doğan']::text[], 8.5, '{"poet":"Yaşar Doğan","poet_slug":"yasar-dogan","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/camurun-gunahi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Töre, Hurafe, Yasak / ss-28', 'tore-hurafe-yasak-ss-28-nesrin-gocmen-p3ejz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir bahçedesin.

Sarhoş kokulu çiçekler etrafında. 

İlahi renklerle süslenmiş kelebekler başına, omzuna konmakta.

Göklerde sesleri bestelenmiş kuşlar....

Dibi görünen dereler, ırmaklar akmakta az ötende. 

Pınarların suları ''iç beni'' diye çağırmakta seni.

Tependeki sekiz bacaklı gökkuşağı, 

parmağını nereye işaret etsen oraya doğru dönmekte.

Yan tarafında bir göl, dibinde yeşil ormanlar görünen. 

Balıkları bir, bir sayabilecek kadar net ve şeffaf.

Şaşkınlıkla, hayranlıkla seyrederek, 

bu güzelliklere dala, dala yürümektesin..

Yürümektesin gözünün önünü görmeden. 

Birden önüne bir duvar çıkıyor. Engin bir duvar.

Ve duvarın öte tarafı daha da güzel. 

Daha da çekici ve hoş geliyor önce sana.

Adımını atsan geçeceksin belki. 

İrkiliyor, bir adım geri atıyor ve duvara tekrar bakıyorsun.

Gördüğün çürük, dört sütun üzerine kurulmuş sahte bir duvar.

Sütunlar: 

T....Ö....R....E....

Bir delikanlı, bir de çingene.

Çirkine, mingene, her neyse..

Gönül bu,  akıl ermez ki işine, 

sevmiş işte çingeneyi.

Çadırı gözüne saray, 

yüzü gönül mehtabında dolunay olmuş.

Elele, gökyüzünün altında, 

ıslak çiçeklerin arasında koşuyorlar.

Delikanlı eğilip, eğilip doğrulmakta.

Kırçiçeklerinin en güzellerini koparıp, 

çingenenin vücuduna asmakta.

Çiçekleye, çiçekleye sevdiğine, 

çiçeklerden elbise yapmakta.

Arada bir durup, çiçekleri unutup, 

gözlerini, boynunu, dudaklarını öpüp, koklamakta.

Doğa cennetinde mutlu, şen ikisi de.

Birden karşı dağın tepesinden bir hayal beliriyor.

Parmağıyla havaya birşeyler yazan, 

işaret parmağıyla çingeneye kızan bir hayal..

Bakıyor,  okuyor hayalin yazdıklarını çingene kız donmuşca. 

Ve sevdiğini olduğu yerde;  melül, mahzun bırakıp gidiyor.

Delikanlı bakınca yazılanlara,

gördüğü:

H...U...R...A...F...E..

T...Ö...R...EE...

! ! ! ! ! ! ! ! ! ! ! ! ! ! ! ! ! ! ! ! ! ! ! ! ! ! ! ! ! ! ! ! ! ! ! ! ! ! ! ! ! ! ! 

. 

İki sevda bilgini, sevgi kütüphanesine dalmış.

Biri Yabangülü, öbürü Hüzünçiçeği. 

Bütün sevda kitaplarını ellerine almış, 

bütün ansiklopedilere dalmış, sevdayı okumaktalar.

Okudukça yeni sevdalar, efsaneler yazmaktalar.

Kütüphane gün geçtikçe yazdıklarıyla dolup, taşmakta.

Ancak, bir gün, bir kitap geçer Yaban Gülü''nün eline.. 

Tarihin diplerinden kalan bir kitap.

İşte o anda, ne olursa olur, 

aklı takılı kalır kitabın kapağına. 

Hipnoz halinde, büyülenmiş gibi. 

Duymaz, yazacaklarını unutur. 

Gözbebekleri boş, boş uzaklara dalar,

yaşları sessizce boşalır.

Hüzünçiçeği kitabın adına bakar: 

Y::A::SS::A::K

H::U::R::A::F::E

T::Ö::R::E

Yazık, çok yazık! 

Boş yere, göz göre göre, 

takıntılar, sıkıntılar kemirmekte beynini...

Üstün aklına, 

yüreğindeki kocaman sevgiye rağmen 

sevdaların yarım kalmakta senin.

Çıkan dumanlara, 

boşa geçen, tekrarı olmayan, 

yiten zamanlara yazık..

Savunmaya geçme kendini,

''''ben öyle değilim'''' deme bana.

Sen sus, birşey deme, 

sen söyleme...

.

(sen söyleme-28)    

07/12/2004', 'Bir bahçedesin. Sarhoş kokulu çiçekler etrafında.  İlahi renklerle süslenmiş kelebekler başına, omzuna konmakta. Göklerde sesleri bestelenmi...', ARRAY['Türk Edebiyatı','Şiir','Nesrin Göçmen']::text[], 8.5, '{"poet":"Nesrin Göçmen","poet_slug":"nesrin-gocmen","theme":"Türk Şiiri","is_hero":false,"total_lines":82,"source_url":"https://www.antoloji.com/tore-hurafe-yasak-ss-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nereye Gider', 'nereye-gider-abdulkadir-karaman-i0h4v', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Engin  dur daima, yüksekten uçma 

Süz sözü her zaman, konuşma saçma

Kardeşine bile sırrını açma

Açıklanan sırlar ilana gider

Acı yoksa, hayat vermez hiç lezzet

Ameldir hayattan geriye özet

Ömür hazinedir, koru ve gözet

Kilitsiz hazine talana gider.

Yokluk kaygısıyla,yok etme varı

Yokta olsan elden koyma vakarı

Onurdur, şereftir insanın  kârı

Kaybedenler inan ziyana gider.

Dostluğa hudut koy, koymazsan şaşar

Hırsına bentler yap, yapmazsan taşar

Çileli de olsan gülmeyi başar

Başaramayanlar nâlana gider.

Her yol bir tek yere varır sonunda

Bir gün biri seni alır sonunda

Gözlerin dayalı kalır sonunda

Tüm yaşadıkların yalana gider.

www.kadirkaraman.com', 'Engin  dur daima, yüksekten uçma  Süz sözü her zaman, konuşma saçma Kardeşine bile sırrını açma Açıklanan sırlar ilana gider Acı yoksa, haya...', ARRAY['Türk Edebiyatı','Şiir','Abdulkadir Karaman']::text[], 8.5, '{"poet":"Abdulkadir Karaman","poet_slug":"abdulkadir-karaman","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/nereye-gider-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beklenen Yanıt', 'beklenen-yanit-erdem-nur-cengiz-68tb1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ne kırlangıç ölümsüzdü

                  ne ölüm kırlangıcı yendi

Ne mavilikler kucakladı onu

                   ne de toprak

Ne büyüdü kırlangıç

                    ne de küçüldü sana inat

O hep 

''orada''

Sen sandığı masalda

Sözsüz

Sana tutkun

Öylece kaldı.', 'Ne kırlangıç ölümsüzdü                   ne ölüm kırlangıcı yendi Ne mavilikler kucakladı onu                    ne de toprak Ne büyüdü kırl...', ARRAY['Türk Edebiyatı','Şiir','Erdem Nur Cengiz']::text[], 8.5, '{"poet":"Erdem Nur Cengiz","poet_slug":"erdem-nur-cengiz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/beklenen-yanit-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizlik', 'sensizlik-murat-sekerci-4q6rh', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yaprak kımıldamıyor dışarda

Büyük bir sessizlik var

Ama fırtınalar kopuyor içimde

Çünkü bende sensizlik var', 'Yaprak kımıldamıyor dışarda Büyük bir sessizlik var Ama fırtınalar kopuyor içimde Çünkü bende sensizlik var...', ARRAY['Türk Edebiyatı','Şiir','Murat Şekerci']::text[], 8.5, '{"poet":"Murat Şekerci","poet_slug":"murat-sekerci","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sensizlik-150-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sarmaşığın Aşkı ''Sevgili Eşim Tayyibe Atay''a''', 'sarmasigin-aski-sevgili-esim-tayyibe-atay-a-abdullah-atay-jcaxp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'canım manolya ağacım! .. 

sen hiç korkma 

acı rüzgardan 

yağan kardan doludan 

bir de fırtına talandan 

gövdende ben varım 

seni saran sarmaşığınım... 

geçse de mevsimler yıllar 

zemheride donsa da dallar

ben sana hep aşığım 

seninle gülüp 

seninle ağlıyacağım 

sen yoksan kollarımda 

inan canım inan 

nasıl ayakta duracağım....', 'canım manolya ağacım! ..  sen hiç korkma  acı rüzgardan  yağan kardan doludan  bir de fırtına talandan  gövdende ben varım  seni saran sarma...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Atay']::text[], 8.5, '{"poet":"Abdullah Atay","poet_slug":"abdullah-atay","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sarmasigin-aski-sevgili-esim-tayyibe-atay-a-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umut Gibi Sonsuz', 'umut-gibi-sonsuz-umut-ulbegi-5j86q', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kış

son kuşlar da üşüyor

soğuklarda

Soğuk 

içime işliyor

iliklerime

Yangın

o eski evin deminde

soğuğa kırgın

yağmur peşinde

Su 

tuzunu alıyor 

ruhumun

Gece

çoktan okunmuş

gazeteye tutunuyor

kağıt avcıları

Ay batarken düşüyor

kağıttan uçakları

Uyku 

ecelini örtüyor

umudun

Tutku 

Tanrı gibi

bıyık altından gülümsüyor

iki gölgenin üstünde

Aşk

seni anlatan bir kitap gibi

senle başlayıp

senle bitiyor

İnsanlar

en soğuk kışı görmeden

tutuşan yürekleri küle dönmeden

geceleri uykularından ölmeden

Anlamalı

Seni erkek gibi tutkun

Kadın gibi aşık

Umut gibi sonsuz

sevdiğimi', 'Kış son kuşlar da üşüyor soğuklarda Soğuk  içime işliyor iliklerime Yangın o eski evin deminde soğuğa kırgın yağmur peşinde Su  tuzunu alıyo...', ARRAY['Türk Edebiyatı','Şiir','Umut Ülbegi']::text[], 8.5, '{"poet":"Umut Ülbegi","poet_slug":"umut-ulbegi","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/umut-gibi-sonsuz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İyi ki Sen Varsın Yüreğimde', 'i-yi-ki-sen-varsin-yuregimde-huseyin-erdogan-60x4z', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'bu sabah gördüm ki

senin adın yazılı

geçtiğim bütün yollarda

senli çiçekler açmış

yeşil yapraklar arasında

dallarda

yalnızca 

senin kokunu buldum 

serin esen rüzgarlarda

yağan yağmurlarda

gece boyunca 

seninle uyudum

rüyalarımda

hem düşlerimde

hem hayallerimde

saçlarımı dağıtırken

meltem olup

yanaklarımı okşarken

sağanaklarında ıslatırken

kokunu içime çekerken

bu soğuk havalarda bile

inan ki canım

sıcacıktın yine

bir başka güzeldin

her halinle

iyi ki sen varsın yüreğimde

yoksa yoksa bir gece

donar kalırdım döşeğimde

             07.12.2004', 'bu sabah gördüm ki senin adın yazılı geçtiğim bütün yollarda senli çiçekler açmış yeşil yapraklar arasında dallarda yalnızca  senin kokunu b...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Erdoğan']::text[], 8.5, '{"poet":"Hüseyin Erdoğan","poet_slug":"huseyin-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/iyi-ki-sen-varsin-yuregimde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnanmam', 'i-nanmam-murat-demir-0e1jc', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir derdime bin dermanla

Gelsende sana inanmam

Gözyaşını damla damla

Döksende sana inanmam

Yalvarsanda gitme diye

Ben ettim sen etme diye

Sen önümde dizlerine

Çöksende sana inanmam

Hep aldattın boş konuşup

Alev alev yan tutuşup

Bu sevdadan derde düşüp

Çeksende sana inanmam

Yüreğime dalga dalga

Vursanda sana inanmam

Ölümüne hep yanımda

Dursanda sana inanmam

Soldurupta allarını

Açsan sevda yollarını

Boğazıma kollarını

Sarsanda sana inanmam

Sende renkler biçim biçim

Ne yapsanda sormam niçin

O meçhüle benim için

Varsanda sana inanmam', 'Bir derdime bin dermanla Gelsende sana inanmam Gözyaşını damla damla Döksende sana inanmam Yalvarsanda gitme diye Ben ettim sen etme diye Se...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/inanmam-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haberin Varmı', 'haberin-varmi-ahmet-kurt-1x9ro', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gözlerimin ışıltısı silindi,

Yüreğim volkanda haberin var mı? 

Eşkıya dağlardan merkeze indi,

Yarınlar tufanda haberin var mı? 

Kaç masum yanacak ateş alınca,

Süngüler korlarla hınca dolunca,

Kollar yana düşüp yüzler solunca,

Dönüşü bulunmaz, haberin var mı? 

Barutlar tükenip yürek atarken,

Virane evlerden duman tüterken,

Kahpeler meydanda caka satarken,

Hangi can solacak haberin var mı? 

İçimden  gelmezse yıkamaz atom,

Yurduma destursuz giremez ki tom,

Ayaklar altında eziliyor kum,

Hırsım büyümekte haberin var mı? 

Kurdoğlu ne desen anlamaz seni,

Fesada bürünmüş boyuyla eni,

Senden daha yakın onlara Coni,

Basireti bağlı haberin var mı?', 'Gözlerimin ışıltısı silindi, Yüreğim volkanda haberin var mı?  Eşkıya dağlardan merkeze indi, Yarınlar tufanda haberin var mı?  Kaç masum ya...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Kurt']::text[], 8.5, '{"poet":"Ahmet Kurt","poet_slug":"ahmet-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/haberin-varmi-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üzerimdeydi', 'uzerimdeydi-bayram-tunca-xcocn', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Geceleri eli hep üzerimdeydi

Gündüzleri gözü üstümdeydi

Sevgisiyle başım göğe deydi

Ya Rab, o melek miydi neydi

Tehlikelere karşı kol kanat oldu

Söylediklerimi hep hayra yordu

Hayat yolunda hep Hızır’ım oldu

Onunla günlerim huzur doluydu

Aah ne çok hakkı vardır üzerimde

Anam bir melekti benim gözümde

Sevgisi hazine gibi duruyor içimde

Hasret ateşi yanmaktadır özümde

Kendisi açken önce bizi doyururdu

İçi kan ağlarken bizleri güldürürdü

Bayramlarda önce bizleri giydirirdi

Çilesine rağmen bizleri sevindirirdi

Her ayrılıkta gözleri hep yollardaydı

Anam desem, Hızır gibi yanımdaydı

Anam başımın tacı/derdimin ilâcıydı

Anadan ayrılmak ölümden de acıydı

Ah çileli annem, sanki de bir melekti

İçime solmayan sevgi tohumları ekti

Aah elleri pamuk/saçları sanki ipekti

Onu bizlerden ayıran kader-i ilahiydi

Hissederdim duaları hep üzerimdeydi

Gidişiyle, başım ay çiçeği misali eğildi

Doyamadım anamı melek miydi neydi

İhtimal, o da doymadan gitti muradını

06.12.2004-12.06

Not:

Zaten bu dünya doyumluk değil, tadımlıktı

Ömür doğumla ölüm arasında bir adımlıktı', 'Geceleri eli hep üzerimdeydi Gündüzleri gözü üstümdeydi Sevgisiyle başım göğe deydi Ya Rab, o melek miydi neydi Tehlikelere karşı kol kanat ...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/uzerimdeydi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İhanetlerin Gölgesinde', 'i-hanetlerin-golgesinde-necmiye-sarpkaya-lsre0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İhanetlerin Gölgesinde 

 	

Gün doğar gün batar heyhat 

Yalnız senin ikliminde şefkat 

Yalnız senin katında şefaat 

Yalnız senin yaında itaat 

Bir hançer saplanır derinden 

Öleceğim Allah''ım kederimden 

Kırılır elim belim 

kesilir sesim soluğum 

Tutulur dilim

Hüzünler akar akar oluk oluk 

Gül benizler olmuş soluk

Al dudaklar  ak apak 

Titrer diz el ayak 

Kalmaz mecal dayana 

İhanetlerin gölgesinde 

Bu bir rüya olmalı 

Sabah olunca uyanmalı 

Ne etmeli nereye gitmeli 

Bitmeli bitmeli 

Kuyudaki karanlık 

Çöldeki gece 

Bitmeli bitmeli 



Necmiye Sarpkaya', 'İhanetlerin Gölgesinde   	 Gün doğar gün batar heyhat  Yalnız senin ikliminde şefkat  Yalnız senin katında şefaat  Yalnız senin yaında itaat...', ARRAY['Türk Edebiyatı','Şiir','Necmiye Sarpkaya']::text[], 8.5, '{"poet":"Necmiye Sarpkaya","poet_slug":"necmiye-sarpkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ihanetlerin-golgesinde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey Müslüman!', 'ey-musluman-ramazan-ece-i6a26', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ey Müslüman ey Müslüman

Gaflet uykusundan uyan

Bekliyor seni tüm cihan

Uyan uyan ey Müslüman! 

Tembel tembel oturma kalk

Kendine gel çevrene bak

Nefsini sen etme helak

Uyan uyan ey Müslüman! 

Allah''ı zikret her zaman

Kalbin dolsun kamil iman

Sever seni yüce Rahman

Uyan uyan ey Müslüman! 

                                

Dünyaya aldanma ey nas! 

Düşmanındır bil ki, Hannas

Dost  istersen  işte  Havvas

Uyan uyan ey Müslüman! 

                   

Dünya ahiret Tarlası

Burda ekilir tüm Harsı

Biçilecek Mevt sonrası

Uyan uyan ey Müslüman! 

                               

Geldin sen imtihan için

Ateşten kurtulmak için

Cenneti kazanmak için

Uyan uyan ey Müslüman! 

                      

Gelen tüm ''Hak''  Nebileri

Bildirdiler gerçekleri

Sakın Hak''tan kalma geri

Uyan uyan ey Müslüman! 

''ECE'' yim ben çoktur zenbim

Rahmetinle affet Rabbim

Bütün mümin kardeşlerim

Uyan uyan ey Müslüman!

                                         

    Ramazan Ece   (Danimarka / Odense)', 'Ey Müslüman ey Müslüman Gaflet uykusundan uyan Bekliyor seni tüm cihan Uyan uyan ey Müslüman!  Tembel tembel oturma kalk Kendine gel çevrene...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Ece']::text[], 8.5, '{"poet":"Ramazan Ece","poet_slug":"ramazan-ece","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/ey-musluman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Allahın Birliği', 'allahin-birligi-ramazan-ece-6ldwu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gökte parlayan yıldızlar

Bulut’tan yağan yağmurlar

Yerden çıkan yeşil otlar

Allah birdir diyor bunlar.! 

Yerden çıkan hububatlar

Çıkıp akan tatlı sular

Tatlı meyveli ağaçlar

Allah birdir diyor bunlar.! 

Şu  Kâinat’a  bakarsan

Şu mahlukat’a bakarsan

Dersin  bunları  yaratan

Allah’tan başka olamaz.! 

Tüm mahlukat’ın razıkı

Tüm  eşyaların  halıkı

Misilsiz olan Allah’tır

Mülkünde bir tek Allah’tır! 

                               

                   Ramazan  Ece    Danimarka / Odense', 'Gökte parlayan yıldızlar Bulut’tan yağan yağmurlar Yerden çıkan yeşil otlar Allah birdir diyor bunlar.!  Yerden çıkan hububatlar Çıkıp akan ...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Ece']::text[], 8.5, '{"poet":"Ramazan Ece","poet_slug":"ramazan-ece","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/allahin-birligi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Allah’a Şükrederim.!', 'allah-a-sukrederim-ramazan-ece-g3m3m', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Beni yoktan var eden

Bir çok nimet bahşeden

Allah’a  şükrederim.! 

Bana can, hayat veren

Bana el, ayak veren

Allah’a  şükrederim.! 

Bana göz, kulak veren

Burun, ağız, dil veren 

Allah’a  şükrederim.! 

Bana akıl, rızk veren

Konuşmayı öğreten

Allah’a  şükrederim.! 

Bana İslâm dinini

Farz ve hükümlerini

Açıklayıp bildiren

Allah’a  şükrederim.! 

 Ramazan   Ece   (Danimarka / Odense)', 'Beni yoktan var eden Bir çok nimet bahşeden Allah’a  şükrederim.!  Bana can, hayat veren Bana el, ayak veren Allah’a  şükrederim.!  Bana göz...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Ece']::text[], 8.5, '{"poet":"Ramazan Ece","poet_slug":"ramazan-ece","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/allah-a-sukrederim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sesleniş', 'seslenis-tevfik-mengulluoglu-qmk24', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ellerinden tuttu umudu çocuk

Lambalar,mumlar 

Lavlara karışacak korkular.

Ellerini ver koma bizi geceye çocuk

Rengine bürünsün tüm acılar,

İki yitik hasret iki yitik can

Nereye gidiyorsan al bizi çocuk.

İster sil ister yak,olmasın hatıralar.

Ve çocuk gördüm seni

Ellerin kardeşliğin simgesi,

Rüyaların tarihin cümlesi,

Bizi karanlığa koma bizi.

İnceden beliriyor ufuk çizgisi

Zaman sürüsü geçiyor altından.

Ellerin,ellerin çocuk ve gözlerin

Çözülmeli yüzündeki buzlar

Oysa ne çoktular korkular

Canımız yandı uykumuz kaçtı

Uyan canavar daha yolumuz var

Kıvrılıp içimizde uyuma çocuk', 'Ellerinden tuttu umudu çocuk Lambalar,mumlar  Lavlara karışacak korkular. Ellerini ver koma bizi geceye çocuk Rengine bürünsün tüm acılar, İ...', ARRAY['Türk Edebiyatı','Şiir','Tevfik Mengüllüoğlu']::text[], 8.5, '{"poet":"Tevfik Mengüllüoğlu","poet_slug":"tevfik-mengulluoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/seslenis-25-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırık İskemle', 'kirik-i-skemle-evren-dalgic-u8rha', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Madem ki bu defteri kapatacaktın; 

bensiz sürseydin her yazdığını

ve kalemini oynatırken umut cümlesinde,

beni tek başıma

yalnız bıraksaydın.

Sormasaydın adımı aşkı ararken,

istemeseydin yüreğimi olmaz mıydı? 

Bir kurbanlık gibi kesmeseydin bedenimi,

yollarına katmasaydın gözlerimi.

Geceleri karamsar olur buraların,

sensizken; gülmez mevsimler.

Ve her yağmur yağdığında kaldırımlara; 

o serseri kedere

gözyaşlarımın zerreleri karışır.

Ve şaşırır damlalar düşerken yanağıma.

Üşürken yanımda olmalıydın,

ısıtmalıydın yüreğimi bir bakışınla.

Madem ki ayrılığı saracaktın birgün,

seni böyle sevmeme karşı çıkacaktın.

Gülmüyecektin yüzüme,

her bakışında binbir şimşek

ve masmavi gökyüzüne kara bulut olacaktın.

Nasıl kıydın yüreğime..

Nasıl dayanır dedin bilmem ki bedenime.

Bu şiirlerin yüreğimin sancısını

boşuna mı taşırdığını sanırsın sence.

Madem ki topluyacaktın pılını pırtını

ve hüzünle çıkacaktın o yolculuğa,

ve beni bırakıp; 

yavrusunu yitirmiş bir ceylan gibi

yüreği yanık bırakacaktın.

Neden yattın o utanmaz gecelerde göğsüme.

Niye unuttun yollara köle olacağını.

Ve umut denen o kırık iskemleye,

neden buyur ettin o koca hayali.

Yıkıldığında duyacaktın o koca gövdeyi,

''O yok oldu'' dediklerinde; 

madem üzülecektin

neden tutsaklaştın ellere

söyle niye? 

Aslında geçti bunlar,

bitti aslında o yolculuk.

Benim ki sadece sitem,

ele avuca alınmaz bir taşkınlık.

Kendi kendine bir konuşma

ve hesaplaşmasıdır maziyle bugünümün.

Dilim acı söyler,

gerçekleri anlatır yaşanılan.

Bu bir yakarıştır,

bu ağlayışıdır özümün.

Son nefesinde olan bir cesedin,

açık gitmesidir gözünün.

(Ankara 2002)', 'Madem ki bu defteri kapatacaktın;  bensiz sürseydin her yazdığını ve kalemini oynatırken umut cümlesinde, beni tek başıma yalnız bıraksaydın...', ARRAY['Türk Edebiyatı','Şiir','Evren Dalgıç']::text[], 8.5, '{"poet":"Evren Dalgıç","poet_slug":"evren-dalgic","theme":"Türk Şiiri","is_hero":false,"total_lines":53,"source_url":"https://www.antoloji.com/kirik-iskemle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Deniz Öyküsü', 'bir-deniz-oykusu-gonul-duranoglu-4ljh8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kuşların bile uğramadığı

Bir adadır yalnızlık

Bu ada benim, dört yanım deniz

Sevgi ve hüzün yosun saçlı

İki kızkardeştir burda

Ben ve adam dört yanımız deniz

Sıkıldıkça milis gençliğimi anlatırım adaya

Kıyamadığım, hiçbir yere koyamadığım

Titreyen yüreğimden iki damla yaş

Akar sessizce eski meydanlara

Derler ki her sonbaharda

Hala yası tutulurmuş oralarda

Yaşanmamış gençliklerin

Güneşin batışıyla alacivertleşirken akşam

Ben ada bir sevdayı bekleriz

Ağustos kapısında

Gelir güvercin gülüşlüm

Saçları buğday kokar

Gözleri yıldız yıldız

Heybesinde temmuz gülleri

Kokuları yosun yosun

Renkleri deniz deniz', 'Kuşların bile uğramadığı Bir adadır yalnızlık Bu ada benim, dört yanım deniz Sevgi ve hüzün yosun saçlı İki kızkardeştir burda Ben ve adam d...', ARRAY['Türk Edebiyatı','Şiir','Gönül Duranoğlu']::text[], 8.5, '{"poet":"Gönül Duranoğlu","poet_slug":"gonul-duranoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/bir-deniz-oykusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mazi ve Kadın', 'mazi-ve-kadin-erdal-gisi-0xlvb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kadınlar maziden beslenir âşık

Her dar geçidinde tüy yolar, çaput bağlar

Bakışlar bulanır

Kurtlar kirli havadan

Kadınlar zehrini maziden alır

Koynunda akrepler dirilir…

Günler maziye döndürmeye görsün… 

Doğrular eğilir bükülür

Tebessüm ağaçları nasılda hüzün açar

Sen hüznü gülün dikeni diye tutarsın 

Matlubun gül

Damlarsa kanın

Gülün hüznüdür…

Lakin isterse maziye kir diye işler kadın

Neden geç kalmıştın ki tam 18 ay önce

Neden öyle bakmıştın, neden güneş batmıştı

…

Maziden balkon süsü kopsa saksısı ile

...Başın yarılır

Öyle denk getirir ki kadın…

Kadınlar bu çukura asla yalnız da düşmez…

Kuyu sanılan gibi serin ve büyük değil

Düştükçe nefesi kısılan kadın

Kısıldıkça mazisi aydınlanır…

Vefayı, aşkı tek o an anlayabilir

Gözyaşları sadece o an içilebilir

İlginçtir…

Kadın, panzehirini gözünden verebilir

Ne ölenler dirilir Ne diriler bilirler

Kadının mazisinin Yazarı ifritdirler

Kadınlar iki şeyi sürekli zikreder

Yarın için Allah’ı

Dün için şeytanları

O sebeple yarın hep bir erkek bulacaklar

O sebeple maziyi hüzne boyayacaklar.

Afyon bitkisinin beyaz sakızı ne ki

Kadının mazisinden akan zehir felç eder

Bu ilginç bir oyundur…

Kadın nankör kediye

Erkek fareye döner

18,1,04', 'Kadınlar maziden beslenir âşık Her dar geçidinde tüy yolar, çaput bağlar Bakışlar bulanır Kurtlar kirli havadan Kadınlar zehrini maziden alı...', ARRAY['Türk Edebiyatı','Şiir','Erdal Gişi']::text[], 8.5, '{"poet":"Erdal Gişi","poet_slug":"erdal-gisi","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/mazi-ve-kadin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anne...', 'anne-yusuf-ziya-leblebici-zwkbj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yaz ortası kış yaşarım

Kucağında ısıt anne

Bu yaşımda indi akım

Aklarımı kopart anne

Güneş doğsa önüm sıra

Alnımdaki çizgi kısa

Derdim yara bu sırtımda

Şu hançeri çıkart anne

Bu yollardan geçilmiyor

Nar''da tane seçilmiyor

Dostu postu bilinmiyor

Biliyorsan ayırt anne

Sırtıma bir kurşun geldi

Göğsümü de deldi geçti

Gelen yağmur değil seldi

Kollarını kapat anne

Yavrum yiğit desen bile

Dağa gücüm yetmez anne

Haydi al beni göğsüne

Sende sevgi bitmez anne', 'Yaz ortası kış yaşarım Kucağında ısıt anne Bu yaşımda indi akım Aklarımı kopart anne Güneş doğsa önüm sıra Alnımdaki çizgi kısa Derdim yara ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ziya Leblebici']::text[], 8.5, '{"poet":"Yusuf Ziya Leblebici","poet_slug":"yusuf-ziya-leblebici","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/anne-113-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasıl-ı Hayat -I-', 'hasil-i-hayat-i-erdal-gisi-qsf4r', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kim istemez aşkı yaşamayı, göz bebeğinde

Damla duruluğu, damla sakinliğinde gözlerinden sızmayı

Baharları avuçlarımla yanaklarına

Yazmayı kim istemez.

Güneşi düşün ki ne kadar uzak

İşte o kadar uzağım

Terliyorsan ne çare

Üşüyorsan biraz daha yanayım…

13.4.03', 'Kim istemez aşkı yaşamayı, göz bebeğinde Damla duruluğu, damla sakinliğinde gözlerinden sızmayı Baharları avuçlarımla yanaklarına Yazmayı ki...', ARRAY['Türk Edebiyatı','Şiir','Erdal Gişi']::text[], 8.5, '{"poet":"Erdal Gişi","poet_slug":"erdal-gisi","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/hasil-i-hayat-i-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gemi Taşına Ağıt', 'gemi-tasina-agit-zeki-ergin-f3glt', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'çocukluğumun geçilmezi

''gemi taşı''m yok artık

adını veren kimse 

ne de güzel demiş

''gemi taşı''oldu 

bir varmış bir yokmuş

önce denize uzanan burnunu kestiler

oluyor bir 40 yıl

içimiz burkulurdu her geçimizde

anımsadıkça

dalgalar ıslatsa da ayaklarımızı 

kumsalından geçerken 

sana kızmazdı kimse

yine bombalar patlamış

savurmuş seni dört bir yana

yoksun artık''gemi taşı''m 

40 yıl önceden kalan yarın da

o hep yaşayacak anılarda

düşündükçe çocuk yüreğim sızlar

düşündükçe çocuk yüreğim ağlar

___kadıköy 7ara''04

(gemi taşı görele-çavuşlu arasında,denize dek uzanan gemiyi andıran,granit kayadan oluşan bir burun du.)', 'çocukluğumun geçilmezi ''gemi taşı''m yok artık adını veren kimse  ne de güzel demiş ''gemi taşı''oldu  bir varmış bir yokmuş önce denize uzanan...', ARRAY['Türk Edebiyatı','Şiir','Zeki Ergin']::text[], 8.5, '{"poet":"Zeki Ergin","poet_slug":"zeki-ergin","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/gemi-tasina-agit-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahane', 'bahane-mehmet-ozer-k71jl', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dudaklarımdaki ıslaklığın nedeni 

Üzerine kondurduğun busedir

Kalbimdeki yaranın nedeni

Kör kurşuna benzettiğim sevgindir

Aşk şarkılarının bu kadar güzel olması

Senin notalara kattığın namedir

Her zaman karşına çıkmam ise

Seni görmek için bahanedir

Bahar gelip çiçeklerin açması

Gökyüzü ile denizin kucaklaşması

Sevdalıların gözyaşı akıtması

Ferhat’ın dağları delmesi

Mecnun’un çölleri gezmesi

Hani kara sevda dedikleri

Seni sevmek için bahanedir

Kadehlerdeki dudak izleri

Sigaradan derin bir fırt çekmek gibi

Aşkın için olurum divane bir deli

Turnalardır sevdamın şahidi

Anlamadığın bir anda gelir insanın eceli

Rabbimin canımı almak için Azrail’i göndermesi

Uğruna ölmek için bahanedir', 'Dudaklarımdaki ıslaklığın nedeni  Üzerine kondurduğun busedir Kalbimdeki yaranın nedeni Kör kurşuna benzettiğim sevgindir Aşk şarkılarının b...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Özer']::text[], 8.5, '{"poet":"Mehmet Özer","poet_slug":"mehmet-ozer","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/bahane-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adana', 'adana-necmiye-sarpkaya-njptd', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Buram buram sevdalar

Dostluk yarenlik 

Burcu burcu portakal çiçekleri 

Kimi zaman Karaca oğlan olur 

Alır sazı eline dokunur bam teline 

Düşer Toros Zirvelerine 

Kah Çamlı bele 

Kah Gülek Geçidine 

Güzel ne güzel olur 

Sazında sözünde 

Güvercin olur keklik olur 

Bıldırcın olur 

Sülün olur 

Yağız yiğitler geçer 

Seyhan Ceyhan dan 

Muştular sunar yavuklularına 

Anadan babadan yardan ayrı 

Sıladan dosttan ahbaptan ayrı 

Düşer yollara varır Aladağlara 

Çıkar Güzeller Tepesine 

Doruklara zirvelere 

Seyrine doyulmaz 

Gök kubbenin 

Yerkürenin arzın 

Mor sümbüller al laleler 

Ak zambaklar zümrüt 

Yeşili kır çiçekleri 

Doyum olmaz seyrine 

Boynu bükük içi burkuk 

Nicedir bağrı yanık 

Esmer kara yağız 

Serinler yaylalarında 

Kah Zorkun 

Kah Tekir 

Kah Çamlıyayla 

Kah Bürücek 

Uzanır Taşköprü boylu boyunca 

Saat kulesi eskisi yenisi 

Ulu Cami Tahtalı Cami 

Merkez Cami yükselir 

Göklere ulu çınar misali 

Ak altın döşeli 

Düzünde ovasında 

Yaylalara Yörükler göçeli 

Köşeli damlar köşeli 

Yarim orda yatalı 

Aslantepe 

Karatepe 

Anavarza 

Serinletir yanık sineleri 

Alp çayırlar sarar zümrüt yeşili 

Bodur makiler döşeli 

Kızılçam karaçam meşe 

Gürgen neşeli toroslar neşeli 

Ben bu derde düşeli 

Gün olur harman olur 

Devran döner kervan gelir 

Türkmen aşığı olur 

Dadaloğlu olur 

Afşar Boylarından 

Anlı şanlı Torosları 

Kozan Ceyhan İmamoğlu 

Dolaşır günler geceler boyu 

Sevda der gurbet der sıla der 

Özlem der vurur bellere 

Dokunur sazın teline dertli dertli 

Dile gelir ele gelir söze gelir 

Önce hayali düşer 

Gümüş renkli ovalara 

Beyaz altının 

Sonra kurulsun düğün dernek 

Çalınsın çifte davullar 

Kız anası kız anası 

Nerde bunun öz anası 

Kavuşur yavuklular 

Sevenler aşıklar 

Yağız delikanlılar 

Hilal kaşlı al yanaklı 

Kara gözlü ceylanlarına 

Adana da Adana da 

Necmiye Sarpkaya', 'Buram buram sevdalar Dostluk yarenlik  Burcu burcu portakal çiçekleri  Kimi zaman Karaca oğlan olur  Alır sazı eline dokunur bam teline  Düş...', ARRAY['Türk Edebiyatı','Şiir','Necmiye Sarpkaya']::text[], 8.5, '{"poet":"Necmiye Sarpkaya","poet_slug":"necmiye-sarpkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":81,"source_url":"https://www.antoloji.com/adana-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Birdirbir Oynayan Çocuk', 'birdirbir-oynayan-cocuk-kinyas-bulbul-jo5n9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'birdirbir oynayan çocuk,

hani söz vermiştin

güzel güneşler serecektin hani

grapon kağıtlarına

birdirbir oynayan çocuk,

topu tut! 

bal ırmaklar vaadedildi 

ve üstümüzden eksilmeyen güneşe

şükretmek öğretildi bize. 

ya kavlimiz bu muydu,

iç çekmek

yanıkla kavlayan derimize

birdirbir oynayan çocuk,

topu tut!', 'birdirbir oynayan çocuk, hani söz vermiştin güzel güneşler serecektin hani grapon kağıtlarına birdirbir oynayan çocuk, topu tut!  bal ırmakl...', ARRAY['Türk Edebiyatı','Şiir','Kinyas Bülbül']::text[], 8.5, '{"poet":"Kinyas Bülbül","poet_slug":"kinyas-bulbul","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/birdirbir-oynayan-cocuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İhanet', 'i-hanet-nalan-palabiyik-275kb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kara bulanık sular kaynıyor

Yine kara isli kazanlarda

Bizi kemiren güveler kaynıyor

Rahat uyuduğumuzu sandığımız yataklarımızda

Memleketimde ne oyunlar dönüyor

Hakkına, seni olana sahip çıkılıyor

Senin olan sana satılıyor

Belin bükülmüş haberin yok kamburun görünüyor

Uyan Artık Ey Millet…! 

Kuzuların içinde kurtlar dolanıyor

Çoban dönmüş ardından

Keyifle kaval çalıyor

Uyan Ey Millet Gaflet Uykundan…! 

Kurtul artık prangalarından

Üstümüze ölü toprağımı atılmış

Konuş,dinlet,kabul etmemek vekile mi kalmış

İşçiyi memuru oy uğruna kandıranlar

Şimdi sırtından atıyor

Sıfıra sıfır,elde var sıfır

İşte bak sıfırlarda atılıyor

Uyan Artık Ey Millet…! 

Kuzuların içinde kurtlar dolanıyor

Çoban dönmüş ardından

Keyifle kaval çalıyor

6.12.2004', 'Kara bulanık sular kaynıyor Yine kara isli kazanlarda Bizi kemiren güveler kaynıyor Rahat uyuduğumuzu sandığımız yataklarımızda Memleketimde...', ARRAY['Türk Edebiyatı','Şiir','Nalan Palabıyık']::text[], 8.5, '{"poet":"Nalan Palabıyık","poet_slug":"nalan-palabiyik","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/ihanet-40-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk ve Hüzün Yeniden', 'ask-ve-huzun-yeniden-i-brahim-taner-okumus-xlabb', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sen çekip çıkarttın beni 

Gecenin esmer aydınlığına

Ben seni ömrümce seveceğim

Ve sen 

Bunu ömrünce bilmeyeceksin', 'Sen çekip çıkarttın beni  Gecenin esmer aydınlığına Ben seni ömrümce seveceğim Ve sen  Bunu ömrünce bilmeyeceksin...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Taner Okumuş']::text[], 8.5, '{"poet":"İbrahim Taner Okumuş","poet_slug":"i-brahim-taner-okumus","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/ask-ve-huzun-yeniden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki Kalbin Arası', 'i-ki-kalbin-arasi-engin-namli-f5evy', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Saklıca gönderdiğin mektuplar neye yarar

Hüzünlü satırlarda hep bana sitemin var

İki kalbin arası bu kadar mı bozuk yar

Nereye varacak bu aşkla nereye kadar

Aşkımızı yaşatan sevgiye ne oldu yar

Günden güne uzuyor aramızdaki yollar

Her zaman yanıyorken  aşk ateşimiz bizim

Günden güne soğuyor sönmek üzre güzelim

Gül gibi bir sevgiyi taşıyamaz haldeyiz

Günden güne kuruyor dalımız çiçeğimiz

Bir garip ıssızlığa demir atmış gibiyiz

Gelip geçmeyenlerin unuttuğu yerdeyiz

Artık birbirimizi mesut eden değiliz

Azalmadan artıyor derdimiz kederimiz

ENGİN NAMLI 02.11.2004   22:43', 'Saklıca gönderdiğin mektuplar neye yarar Hüzünlü satırlarda hep bana sitemin var İki kalbin arası bu kadar mı bozuk yar Nereye varacak bu aş...', ARRAY['Türk Edebiyatı','Şiir','Engin Namlı']::text[], 8.5, '{"poet":"Engin Namlı","poet_slug":"engin-namli","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/iki-kalbin-arasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Alnımda ter oldun...', 'alnimda-ter-oldun-yusuf-ziya-leblebici-iect6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Uzaklardan kokun akar koynuma

Bağrımda gül oldun tenimde kokan

Sensiz her günüme dertler yağsa da

Alnımda ter oldun, yüzümden akan

Sılanın yolları dağdır aşılmaz

Hasretin bağrımı yakar kaçılmaz

Gurbet mezrasında sensiz yaşanmaz

Gönlüme fer oldun, yollar aşınmaz

Şu dağlarda keklik biter mi söyle

Bu gönülden sevdan geçer mi böyle

Tüfekler bir elden dönse de bize

Sazıma tel oldun, ferman türküme

Bülbüllerin güle küstüğü yalan

Gurbetin sılaya düştüğü yalan

Sevgin bana güçtür ardımda kalan

Yoluma bel oldun, bende yaşayan', 'Uzaklardan kokun akar koynuma Bağrımda gül oldun tenimde kokan Sensiz her günüme dertler yağsa da Alnımda ter oldun, yüzümden akan Sılanın y...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ziya Leblebici']::text[], 8.5, '{"poet":"Yusuf Ziya Leblebici","poet_slug":"yusuf-ziya-leblebici","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/alnimda-ter-oldun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni Anlamak', 'beni-anlamak-i-brahim-taner-okumus-wra6s', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ölümü yokla gözlerimde

Damla damla süzülen

Hayatı anla

Zifiri bir gecede

Sessiz bir hırka bürün

Yaslan kalbime

ve

Ölümü anla...', 'Ölümü yokla gözlerimde Damla damla süzülen Hayatı anla Zifiri bir gecede Sessiz bir hırka bürün Yaslan kalbime ve Ölümü anla......', ARRAY['Türk Edebiyatı','Şiir','İbrahim Taner Okumuş']::text[], 8.5, '{"poet":"İbrahim Taner Okumuş","poet_slug":"i-brahim-taner-okumus","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/beni-anlamak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'CANSU (akrostiş)', 'cansu-akrostis-muzaffer-erdogan-vnms5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'C an çekilmek üzere seven bu tenden

A şk dilenmekte başarı beklemek için senden

N iyet edip yola çıktım var mısın? Haydi cevap ver! 

S evda bahçesinden yediveren gülleri der.

U yut beni ateşinle,geç kalan mutlulluğa er...', 'C an çekilmek üzere seven bu tenden A şk dilenmekte başarı beklemek için senden N iyet edip yola çıktım var mısın? Haydi cevap ver!  S evda ...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Erdoğan']::text[], 8.5, '{"poet":"Muzaffer Erdoğan","poet_slug":"muzaffer-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/cansu-akrostis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Www.antoloji.com nereye!', 'www-antoloji-com-nereye-orkun-isik-88g0y', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Birlikte açmaktı kollarımızı insanlığa 

Haykırmaktı insan olmayanlara 

Bir ışık yakacaktık karanlığa 

Olmadı gözüm neyliyek... 

Kaçamadık insanların yobazlığından 

Kaçamadık münafıkların tırpanından 

Vurdular bize bir oyandan bir buyandan 

Dolmadı gözüm neyliyek... 

Bir merhabaya hasretti misafirler 

Havada uçuştu birden küfürler 

Caza döndü ezgili türküler 

Söylenmedi gözüm neyliyek... 

Kırılmazmıydı kötülüğün kolu 

Geçmezmiydi dostluğun yolu 

Ne gerek vardı batsın sağı solu 

Sevişemedik gözüm neyliyek... 

Bilmem kaçtane lakaplı 

Girdik kürsüye handikaplı 

VIP salonu mavi deniz kaplı 

Oturamadık gözüm neyliyek... 

Nereye gidersen git antoloji! ..

Anlatamadı bize bizi sosyoloji 

Türkoloji, İnsanoloji, adamoloji 

Masada kaldı çarpık ideoloji 

Kaldıramadık gözüm neyliyek... 

-

-

-

düzenleme yapılabilir.', 'Birlikte açmaktı kollarımızı insanlığa  Haykırmaktı insan olmayanlara  Bir ışık yakacaktık karanlığa  Olmadı gözüm neyliyek...  Kaçamadık in...', ARRAY['Türk Edebiyatı','Şiir','Orkun Işık']::text[], 8.5, '{"poet":"Orkun Işık","poet_slug":"orkun-isik","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/www-antoloji-com-nereye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk', 'ask-sair-shimalwest-prkrm', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'aşk dediğin doğar mı ki? ....

yoksa içinde var mıdır hep

ne zaman çıkacağını bilmeden

taşır mısın kalbinde

onu arayanı bekledikce

aşk dediğin doğar mı ki? ....

karşına sen gibi biri çıkmadan

senliğini hissettirmeden

gülüşünü görmeden

gözlerine dalmadan

aşk dediğin doğar mı ki? ....

sevgin karşılıklı olmadan

sevilmeyi yaşamadan

sevmeyi tatmadan

birlikteliği bulmadan

aşk dediğin doğar mı ki? ....', 'aşk dediğin doğar mı ki? .... yoksa içinde var mıdır hep ne zaman çıkacağını bilmeden taşır mısın kalbinde onu arayanı bekledikce aşk dediği...', ARRAY['Türk Edebiyatı','Şiir','Şair Shimalwest']::text[], 8.5, '{"poet":"Şair Shimalwest","poet_slug":"sair-shimalwest","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ask-317-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üstü(m) Kalsın', 'ustu-m-kalsin-yunus-guzel-yfo49', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Tamamım bu kadar işte

Taştan taşa çarpsalar beni

Bin parçaya bölseler yüreğimi

Bahçemden çıkarsalar gonca gülümü

Bütün belaları toplasalar başıma

Bu kadarım işte…

Fazla gelmişim anlaşılan

Bir türlü eksiltemediniz

Ben dizelerin dünyasına  dönüyorum

Üstü(m)   kalsın…', 'Tamamım bu kadar işte Taştan taşa çarpsalar beni Bin parçaya bölseler yüreğimi Bahçemden çıkarsalar gonca gülümü Bütün belaları toplasalar b...', ARRAY['Türk Edebiyatı','Şiir','Yunus Güzel']::text[], 8.5, '{"poet":"Yunus Güzel","poet_slug":"yunus-guzel","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ustu-m-kalsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kendimi Unuttum...', 'kendimi-unuttum-melek-ayaz-tfdk1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kendimi unuttum

Sana şiirler yazdım

Bekareti bozulmamış saatlerde

Ben seni düşünüyorum

İtiraf ediyorum

Seni düşünürken

Yağan yagmurlara aldırmadım

Seni düşünürken

Unuttum bütün şiirlerimi

Kitapların bana öğrettiklerini

Seni düşünürken

Yüreğim beni bırakıp gidiyordu

Seni düşünürken...yani

İçim dışım sendin

Sabah akşam kanımda rüyalarımdaydın

Seni seviyordum

Gecenin korkunç karanlığında

Eriyen mumun yanı başında

Senin için eridi ruhum

Vakit geçti karanlıktı

Vakit çoktu ama sen yoktun

Sensizlik artık ağır geliyor bana

Kapına onur karanfilleri bıraktım

Kelebeklerinle tangoların en güzeliyle

Dans ediyorum şimdi...Sensiz.', 'Kendimi unuttum Sana şiirler yazdım Bekareti bozulmamış saatlerde Ben seni düşünüyorum İtiraf ediyorum Seni düşünürken Yağan yagmurlara aldı...', ARRAY['Türk Edebiyatı','Şiir','Melek Ayaz']::text[], 8.5, '{"poet":"Melek Ayaz","poet_slug":"melek-ayaz","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/kendimi-unuttum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dünyayı Kucaklamak', 'dunyayi-kucaklamak-zulfikar-yapar-kaleli-rucpj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'font face=''Comic Sans MS'' color=''black'' size=''0,5''

Güneş soğuk, ay yırtık,

Kapımı çalar tık tık! 

Diyeceksen de artık,

Hele durun, derim, yok...

Aya fer veremeden,

Rabıta kuramadan,

Kapıyı aramadan,

Gönlünü ver, girim, yok...

Sakın deme, üstün ben,

Zannederim kastın ben,

Haykırsana, dostun ben,

İkiliğe pirim, yok...

Yolu yola doladım,

Yürüdüm adım adım,

Dünyayı kucakladım,

Oturacak yerim, yok...

Gönüllerin yatı ol,

Gül denilen otu ol,

Hak yanında katı ol,

Ki, zehir dökerim yok...', 'font face=''Comic Sans MS'' color=''black'' size=''0,5'' Güneş soğuk, ay yırtık, Kapımı çalar tık tık!  Diyeceksen de artık, Hele durun, derim, yo...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/dunyayi-kucaklamak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çizgiler', 'cizgiler-cigdem-bir-genc-zzb0r', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Uluorta soyunur oldu ağaçlar

Güneş bir diğer yarımkürenin sabahında oynaşta

Takvimler çoktan döktü yapraklarını

Doğacak çocuklarına isim arayanlar telaşta

Mevsimlik işçi göçü başladı

Gece gündüz demeden kardan/adamlar taşıyor bulutlar

Bense bir çocuğun düşü oluyorum düşümde

Uyandırmayın...', 'Uluorta soyunur oldu ağaçlar Güneş bir diğer yarımkürenin sabahında oynaşta Takvimler çoktan döktü yapraklarını Doğacak çocuklarına isim ara...', ARRAY['Türk Edebiyatı','Şiir','Çiğdem Bir Genç']::text[], 8.5, '{"poet":"Çiğdem Bir Genç","poet_slug":"cigdem-bir-genc","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/cizgiler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şair oldum', 'sair-oldum-i-brahim-duskun-lc5kd', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'baktım şiirdi

bir mavi sonsuzluk gibiydi

okudum

tekrar okudum

benim şiirimdi

kayıt düştüm zamana

yazdım şiirimi

ben şair oldum.', 'baktım şiirdi bir mavi sonsuzluk gibiydi okudum tekrar okudum benim şiirimdi kayıt düştüm zamana yazdım şiirimi ben şair oldum....', ARRAY['Türk Edebiyatı','Şiir','İbrahim Düşkün']::text[], 8.5, '{"poet":"İbrahim Düşkün","poet_slug":"i-brahim-duskun","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sair-oldum-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Kalabalığım', 'ben-kalabaligim-i-brahim-taner-okumus-qu5d7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'yanlızlık sadece bir özlemdi..

aşk gibisinden 

ben yanlızken kalabalığım

dünyalarca çoğalır 

ellerim

ve 

gözlerim

benim yanlızlığım

çiğ bir kelime

iğreti dudaklarda

ve ben

kalabalığım', 'yanlızlık sadece bir özlemdi.. aşk gibisinden  ben yanlızken kalabalığım dünyalarca çoğalır  ellerim ve  gözlerim benim yanlızlığım çiğ bir ...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Taner Okumuş']::text[], 8.5, '{"poet":"İbrahim Taner Okumuş","poet_slug":"i-brahim-taner-okumus","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ben-kalabaligim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Soruşturdum...', 'sorusturdum-melek-ayaz-ojbko', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ne kadar yanlış varsa,

Ben onu soruşturdum.

En sıkıcı sancılar,

Birikirdi kollarımda,

Hep acı çeken,

Ellerimi kovuşturdum.

Çığlık çığlığa,

Uzanıp nehirleri gözlerdim

Yumruğumu yılların.

Mutsuzluğuna vurarak,

Bütün yılgınlıkları savuşturdum.

Ve ihanetlerdi kan gibi şakaklarımda,

Sarsılmaz bir inancın kollarında bulurdum,

Kendinden güvenli koca bir kaya gibi,

Gururla kaldırır başımı onlarla boğuşurdum.

İşte yepyeni coşkulardı  şimdi dudaklarımda,

Dopdolu sevinçlerdi mutlu koşturan.

Yaşanacak o sessiz değerler için.

Ve daha neleri çağrıştırır dururdum.

Denizlerle güneşi tutuştururdum.

Sonra bir sevgi ezgisiydi kulaklarımda,

Eski acı güzelliğe kateh tokuştururdum.

Suyu toprakla gelinciklerle ateşi,

Sevgiyi rüzgarla ve çiçeklerle buluşturdum.', 'Ne kadar yanlış varsa, Ben onu soruşturdum. En sıkıcı sancılar, Birikirdi kollarımda, Hep acı çeken, Ellerimi kovuşturdum. Çığlık çığlığa, U...', ARRAY['Türk Edebiyatı','Şiir','Melek Ayaz']::text[], 8.5, '{"poet":"Melek Ayaz","poet_slug":"melek-ayaz","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sorusturdum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzel Sözler-6', 'guzel-sozler-6-huseyin-erdogan-10zwh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '''Güneş''in batışını,suyun akışını ve kadının bakışını bir arada görmek ne de güzeldir öyle değil mi? ''07.12.2004

''Çevir başını bak gök yüzüne,senin adını yazdım dün gece,istersen bir sabah erken uyanınca git bak Marmara''ya, dalgaların her vuruşunda aşkımızı kazıdıklarını göreceksin sahildeki kayalıklara,böylece,sevdamız dilden dile dolaşacak insanlar okudukça...'' 07.12.2004', '''Güneş''in batışını,suyun akışını ve kadının bakışını bir arada görmek ne de güzeldir öyle değil mi? ''07.12.2004 ''Çevir başını bak gök yüzüne...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Erdoğan']::text[], 8.5, '{"poet":"Hüseyin Erdoğan","poet_slug":"huseyin-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/guzel-sozler-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüler Gözüyle Bakma', 'oluler-gozuyle-bakma-ali-kilic-kakiz-ww94w', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Allahın elçileri, iyiye güzele çağırıyor.

İlim dolu hikmeti, akıl, ruh paylaşıyor.

Dağlar taşlar korkudan inim inim inlediler.

Etkileyici cinler, gelip Kur''an-ı dinlediler.

Kalbe elem çöktükçe, sabırla sarıl Kurana. 

Ölüler gözüyle bakma gönül sırrı kelama.

Gözünden kaldır perdeyi, bakışın keskin olsun.

Risaletle ikram edilen emanet rehberin olsun.

O, daralan gönülleri tutuşturur mest eder.

O''na hayran kalanlar, güzelliklerini seyreder.

......................

Lessines /2004', 'Allahın elçileri, iyiye güzele çağırıyor. İlim dolu hikmeti, akıl, ruh paylaşıyor. Dağlar taşlar korkudan inim inim inlediler. Etkileyici ci...', ARRAY['Türk Edebiyatı','Şiir','Ali Kılıç Kakiz']::text[], 8.5, '{"poet":"Ali Kılıç Kakiz","poet_slug":"ali-kilic-kakiz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/oluler-gozuyle-bakma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seviyorum seni', 'seviyorum-seni-mustafa-karamelek-z7edt', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '06.12.2004

Aşk’a açım sevdaya susuz

Yıllar  var ki duygularım uykusuz

Vuslattan yana  kollarım umutsuz

Varlığın zulüm 

Yokluğun işkence

Gülüşün çile

Gidişin ölüm

Seviyorum seni 

Yokluğun kadar

Seviyorum seni

Bildiğim kadar gülüm

Seviyorum seni…', '06.12.2004 Aşk’a açım sevdaya susuz Yıllar  var ki duygularım uykusuz Vuslattan yana  kollarım umutsuz Varlığın zulüm  Yokluğun işkence Gülü...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Karamelek']::text[], 8.5, '{"poet":"Mustafa Karamelek","poet_slug":"mustafa-karamelek","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/seviyorum-seni-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korkarım içinde kalakalırım...', 'korkarim-icinde-kalakalirim-ali-galip-sari-k0g3t', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Senden vazgeçerken seversen beni,

Korkarım içinde kalakalırım...

Sonra ömür boyu ararsın beni,

(Bense)  Başka bir diyarda soluklanırım...

Korkarım yaş bitmez gözlerindeki,

Ve adım silinmez sözlerindeki,

Giderken gönlüne girip öyle ki...

Bir ömür bin ömür orda kalırım! 

Şimdi iyisi mi  beni bekletme,

Tüketme sen, seni gözlerimdeki,

Bin ömür arasan bulamazsın yar...

Böyle karşılıksız ve çok seveni..! 

                                           Ankara/ 06.12.2004', 'Senden vazgeçerken seversen beni, Korkarım içinde kalakalırım... Sonra ömür boyu ararsın beni, (Bense)  Başka bir diyarda soluklanırım... Ko...', ARRAY['Türk Edebiyatı','Şiir','Ali Galip Sarı']::text[], 8.5, '{"poet":"Ali Galip Sarı","poet_slug":"ali-galip-sari","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/korkarim-icinde-kalakalirim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Külah', 'kulah-ahmet-turan-altunsu-9pybd', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'yazmadım,

varmadı elim kaleme.

içimdeki şeytan tıpışladı omuzumu,

çevirdim sırtımı bütün bir âleme,

yükledim yorgun omuzlarıma alın yazımı,

girdim sayfalarına bir yalan kitapçığın,

buldum devrik bir cümlede köksüz bir kelime,

sindim içerisine usulca,

çatlasın bakıp da hâlime! 

düşürdüm külahını şeytanın,

şeytan lânet okudu,

kızmadım! 

                      06.12.2004 / Ankara', 'yazmadım, varmadı elim kaleme. içimdeki şeytan tıpışladı omuzumu, çevirdim sırtımı bütün bir âleme, yükledim yorgun omuzlarıma alın yazımı, ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Turan Altunsu']::text[], 8.5, '{"poet":"Ahmet Turan Altunsu","poet_slug":"ahmet-turan-altunsu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kulah-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgim Gibi...', 'sevgim-gibi-melek-ayaz-nj76u', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İstanbul...2004...

Kadıköyde,

Köhne bir bankta,

Elimde sigaram dalarım..

Martıların yaşam savaşına,

Unutulmaya yüz tutmuş anılar,

Çıkagelir ansızdan.

Hüzün yerleşir yüreğime,

Dalar giderim uzaklara,

Bulamam bir türlü kendimi,

Bin parça olurum anılarda,

Bir türkü düşmez dilimden.

Dalar giderim...

Acı çeken denizin derinliklerine,

İdam edilmiş sevgi anılarım canlanır,

Dalarım yosunların arasına yok olur giderim,

Takılırım istirityenin içindeki inci tanesine,

Ne zordur o nadide inci tanesini yapmak.

Tıpkı benim uğraş verdiğim,

Sevgim gibi', 'İstanbul...2004... Kadıköyde, Köhne bir bankta, Elimde sigaram dalarım.. Martıların yaşam savaşına, Unutulmaya yüz tutmuş anılar, Çıkagelir ...', ARRAY['Türk Edebiyatı','Şiir','Melek Ayaz']::text[], 8.5, '{"poet":"Melek Ayaz","poet_slug":"melek-ayaz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sevgim-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Reis', 'reis-habip-sabanli-og5bs', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ne çabuk gittin be reis? 

Ansızın, bir gece vakti gittin.

Senden kalan ne seda ne ses,

Ne çabuk gittin be reis? 

Gel artık babacan, tutturma yas.

Bak kafa kagıdı bile yaşlandı.

Degişmeyen  dogum tarihin oldu.

Ne çabuk göçtün be reis? 

Türkülerimiz vardı, bizi anlayan.

Sevdiğimiz vardı, hep arkamızda olan.

Birde senin için dostlar vardı ölen.

ne çabuk unuttun be reis? 

Kimler aldı seni mahpus içre,

Çakallar mı, soktu seni bu derde.

Senle aşık atan hangi çakal sürüsü,? 

Pes varmı kitabımızda be reis? 

Devran döner birgün terse elbet.

Kafire indiği gibi bunlara da iner TEBBET.

Sen ALLAH''ı unutma, o unutmaz seni elbet.

Bir meçhule gider sonumuz be reis.

Doğum T: 20/09/1984

Ölüm   T:Bilinmiyor

Kabri     :Bilinmiyor

Adı         :REİS

Soyadı   :VATAN

SUÇU    :Vatanı satmamak', 'Ne çabuk gittin be reis?  Ansızın, bir gece vakti gittin. Senden kalan ne seda ne ses, Ne çabuk gittin be reis?  Gel artık babacan, tutturma...', ARRAY['Türk Edebiyatı','Şiir','Habip Sabanlı']::text[], 8.5, '{"poet":"Habip Sabanlı","poet_slug":"habip-sabanli","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/reis-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin İçin', 'senin-i-cin-ahmet-agdere-gucmm', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ah sevgilim benim olsan

Neler yapmam senin için

Uçup uçup bana konsan

Neler sermem senin için

Gülşeninden güller dersen

Aşk balımdan biraz yesen

Daha fazla yok mu desen

Neler vermem senin için

Gelsen sevda diyarından

Korksa güller nazarından

Gitse makus, bakışından

Neler yanmaz senin için

Derbeder’dim ettin usta

Gece gündüz elim tuşta

Gör hele, biraz konuş da

Neler bitmez senin için', 'Ah sevgilim benim olsan Neler yapmam senin için Uçup uçup bana konsan Neler sermem senin için Gülşeninden güller dersen Aşk balımdan biraz y...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ağdere']::text[], 8.5, '{"poet":"Ahmet Ağdere","poet_slug":"ahmet-agdere","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/senin-icin-89-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Lodos', 'lodos-burak-killioglu-tgses', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kim bilir ne soğuktur hava...

İnsanın içini nasıl titretir ayaz, bilirim.

Bu şehrin her mevsimi

Nazlı ve ürkek bir ceylan iken

Kışının hoyratlığını da hoş görebilirim.

İstanbul''un hırçın lodosudur

Vapurları bir sağa, bir sola atan

Ve dışarıdaki soğukla birlikte

Çatlak ellerimizin faili.

Onun sadık korosudur

Bir uğultu gibi sokakları dolduran

Ve içimizdeki fırtınayla birlikte

Mağlup gönüllerimizin galibi.

Sormalı aslında ona

nedendir tüm bu asiliği

Belki de, baktı ki bizden bize hayır yok

Söküp atabilmek içindir

Üstümüze yapışmış olan

kişiliksizliği.', 'Kim bilir ne soğuktur hava... İnsanın içini nasıl titretir ayaz, bilirim. Bu şehrin her mevsimi Nazlı ve ürkek bir ceylan iken Kışının hoyra...', ARRAY['Türk Edebiyatı','Şiir','Burak Kıllıoğlu']::text[], 8.5, '{"poet":"Burak Kıllıoğlu","poet_slug":"burak-killioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/lodos-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Serçe', 'serce-bekir-mutlu-gokcesu-v9mvo', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Son borandan sonra

Sığınmaya çalışıyordu

Hayata...

Yeniden oluşmaya

Alışmaya...

Yeniden karışmaya

Çabalıyordu yaşama...

Olmadı, başaramadı

Kocaman serçe yüreğini

Sığdıramadı

Küçücük dünyaya...', 'Son borandan sonra Sığınmaya çalışıyordu Hayata... Yeniden oluşmaya Alışmaya... Yeniden karışmaya Çabalıyordu yaşama... Olmadı, başaramadı K...', ARRAY['Türk Edebiyatı','Şiir','Bekir Mutlu Gökçesu']::text[], 8.5, '{"poet":"Bekir Mutlu Gökçesu","poet_slug":"bekir-mutlu-gokcesu","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/serce-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tanrım Af Eyle', 'tanrim-af-eyle-anil-esen-u92do', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Savaştan açlıktan ölen insanları unutup

Hektar hektar yanan ormanları unutup

Karanlık petrolde boğulan hayvanları unutup

Acı ve keder dolu devranları unutup

İnanmadım cehennemine

Tanrım bizede biraz insaf eyle

Hadi ben eşşeklik ettim sen af eyle', 'Savaştan açlıktan ölen insanları unutup Hektar hektar yanan ormanları unutup Karanlık petrolde boğulan hayvanları unutup Acı ve keder dolu d...', ARRAY['Türk Edebiyatı','Şiir','Anıl Esen']::text[], 8.5, '{"poet":"Anıl Esen","poet_slug":"anil-esen","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/tanrim-af-eyle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Masturbasyon', 'masturbasyon-anil-esen-cf7k5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Viagra gelmiş memlekete

güzel bahar aylarında

boş kalmasın diye

kelepçeli ellerimiz...', 'Viagra gelmiş memlekete güzel bahar aylarında boş kalmasın diye kelepçeli ellerimiz......', ARRAY['Türk Edebiyatı','Şiir','Anıl Esen']::text[], 8.5, '{"poet":"Anıl Esen","poet_slug":"anil-esen","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/masturbasyon-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kadınlar', 'kadinlar-nermin-altindag-i9d43', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'ne kadınlar gördüm dudakları mühürlü

dişleri kenetlenmiş dönmez dilleri

tüketilmiş kelimeler tutsağı zihinleri

unutmuşlar en güzel cümleleri

ne kadınlar gördüm konuşmaya hasret

eğildim ve öptüm dudaklarından

ne kadınlar gördüm gözleri mühürlü

kirpikleri birbirine sımsıkı kilitlenmiş

bir açsalar dökülecek kin dolu bakışlar

unutmuşlar ışıltılı bakışları

ne kadınlar gördüm bir damla yaşa hasret

eğildim ve öptüm gözlerinden

ne kadınlar gördüm elleri mühürlü

ah bir dokunabilseler sımsıcak bir söze

ellerinde keskin bir kılıç, kesiyorlar bütün yolları

istedikleri yüreklerine atılacak bir tek kurşun

ne kadınlar gördüm kolları hep boşluğu saran

eğildim ve öptüm ellerinden

ne kadınlar gördüm yürekleri mühürlü

dudaklarında dökemedikleri en güzel aşk sözcükleri

ah bir bakabilseydi gözleri ışıltılarla

tutabilseydi elleri sımsıcak bir yüreği

volkan olur yakarlardı bütün aşk yoksunu hainleri

ne kadınlar gördüm yürekleri yaralı

eğildim ama öpemedim alınlarından...

07/12/2004 Bor NİĞDE', 'ne kadınlar gördüm dudakları mühürlü dişleri kenetlenmiş dönmez dilleri tüketilmiş kelimeler tutsağı zihinleri unutmuşlar en güzel cümleleri...', ARRAY['Türk Edebiyatı','Şiir','Nermin Altındağ']::text[], 8.5, '{"poet":"Nermin Altındağ","poet_slug":"nermin-altindag","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/kadinlar-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Hikaye', 'bir-hikaye-serkan-yildirimoglu-j2ggv', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sana ilk defa anlatıyorum

O deva bulmaz derdimin sahibini

Ve ilk defa döküyorum kaleme

Onmaz ve son bulmaz hikayemi

Soğuk değildi hava kampüsde

Elleri titriyordu ama nedense

İlk defa konuştum onunla

Ellerinin titremesi sadece bahane

Konuşurken gözlerim titriyordu

Onun ise sadece elleri

Yüreğim titriyordu anlarsınya

Onun ise sadece sözleri

Derdi basit bir vize sınavı

Anlattım işte; yetebildiğimce

Rahatlamıştı, sınavı iyi geçmiş

Teşekkür için bir çay ile geldi

Çaya yok denilmez! Birde cigara

Keyfim yerine geldi o gelince

O soruyordu, ben anlatıyordum

Ben her şeyi çok iyi biliyordum

Diliyordu beni, ben onu seyrediyordum

Akşamlar akşamları kovaladı

Onu kendime alıştırıyordum

Hatta evden bile çıkarabiliyordum

Anneye küçük yalanlar

En mahsumundan, ders diye

Ben zaten onu –çok- seviyordum

O bana hep arkadaş gibi yaklaştı

Farklı değildi sadece gönlü ıraktı

Benim kalbim hep o diye attı

Söyleyince iki üç gün ayrı kalıyordu

Sonra iki damla göz yaşı ile geliyordu

Onunkisi sadece bir alışkanlıktı

Kabul etti sevmeyi, anlamayı

Naz yaptım, inanmazsın ağladım

Süre geldi hayat böyle devam etti

Tamı tamamına bir yıl bir ay yaşadım

Sonra okuldan ayrı kaldım

Ondan uzaklarda yaşadım

Gönlümden bir an olsun ayırmadım

Ölümün en acı çığlığını attım

Acı veriyordum ona ayrılıkla

Ben buna katlanamadım

Ve apansız bir akşam ayrıldım

Kahrettim hayata yaşamadım

Ölümü hak ettim, ağladım

Hastalandım, inanma tırlattım

Altı ay ayakta bile duramadım

Düzelince gittim yanına af dilenmeye

Her ne kadar affa layık olmasam bile

Anla işte başka biri vardı gönlünde

Yeminler unutulurmuş kısacık süre

Tamam dedim, yeter dedim

İlaçlarımı bıraktım, derlendim

Her gece birkaç şişe devirdim

Alkolik oldum, kimse bilmedi

Bilenlerde sormadı neden içtiğimi

Söylediğim türküleri Hayri Dayı dinledi

Hayri Dayının yeriydi meyhanenin adı

Oda her gece benimle içerdi

Kader çıkarıyor ya herkese

Bir nur yüzlüde çıkardı bize

Bıraktım Hayri Dayıyı köşesine

Ben ben oldum o günden bu güne

Sana geldi dertlerim dayandı

Hiç kimseye yazmadım bu hikayeyi

Yazamazdım belki okur anlardı

Hep bekledim bir telefon çalışını

Bir mektubu, bir selamını

Olmadı be canı sağ olsun dedim

Kendime acıdım, hep kendime

İnsan yapar mı bunu kendi kendine

O günden sonra hiç sevdalanmadım

Diyorum ya sadece aşkı yaşadım

Yüküme bir ortak aradım

Offf be bir hikaye, bir masal

Ben onsuzken bunca yıl

Elsiz ayaksız ve kör yaşadım

		06.12.2004', 'Sana ilk defa anlatıyorum O deva bulmaz derdimin sahibini Ve ilk defa döküyorum kaleme Onmaz ve son bulmaz hikayemi Soğuk değildi hava kampü...', ARRAY['Türk Edebiyatı','Şiir','Serkan Yıldırımoğlu']::text[], 8.5, '{"poet":"Serkan Yıldırımoğlu","poet_slug":"serkan-yildirimoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":79,"source_url":"https://www.antoloji.com/bir-hikaye-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ankara 2004...', 'ankara-2004-melek-ayaz-mcyiy', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ankara 2004...

Kızılay sakarya

Sokak başında bir kız çocuğu.? 

Yalın ayak

Bakışları ürkek

Ve elleri titrek

Masum bir çift ğöz simsiyah

Konuşur gibiydi

Hırçın acı bir gülümseyiş vardı

Dudak kıvrımlarında

Bir an bakıştık

Sanki yüreklerimiz birleşti

Neden ben der gibiydi

Virane bir sevgiyle seyrettim onu

Ezildi yüreğim

Çaresizce döndüm arkamı

Gözlerimde yağmurlar durmuyordu

Ogece ne kadar karanlık ve sessizdi

Sabahladım o gecede ben

Hırçın gülümseyişi dikilmişti karşıma

Sanki birşeyler anlatmak ister gibi

Karanlık öylesine kaplamıştıki geceyi ve yüreğimi

Sabahın oluşunu bile fark edememiştim.', 'Ankara 2004... Kızılay sakarya Sokak başında bir kız çocuğu.?  Yalın ayak Bakışları ürkek Ve elleri titrek Masum bir çift ğöz simsiyah Konuş...', ARRAY['Türk Edebiyatı','Şiir','Melek Ayaz']::text[], 8.5, '{"poet":"Melek Ayaz","poet_slug":"melek-ayaz","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/ankara-2004-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', ')))))) Olmazmı Canım ((((((', 'olmazmi-canim-i-brahim-dikmen-2-2ztbt', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir ben vardım

bir de,

karanlığı aydınlatan

renk cümbüşü yakamozlar.

ogece,

ağlaştık sabaha kadar.

Anlaşılan o ki! 

kaderimiz aynı

sizde benim gibi

yalnızsınız

gökyüzünde

yalnız gezen yıldızlar.

Elimden hiç düşürmediğim,

ciğerimi dumanaltı eden

katran karası.

benden,

ömrümün yarısını çalan

gavur cigarası.

Dahasımı? 

gecenin ayazı cabası,

hoşuma giden

mis gibi

yeşil yosun kokusu.

Ay dede,tepeden baka dursun,

binbir böcek ötüşsün,

uğursuz baykuş karanlığa gömülüp

kanat çırpsın.

Ama! 

o''güzelim parıltısıyla

renk renk yakamozlar,

yıldızlara bakıp

tebessüm etsin

bu kadarı yeter canım.

Çiğ taneleriyle ıslansam

şebnemler yüreğime aksa

kalbim yokluğunla sızlasa

gözlerim karanlığa dalıp

çocukça ağlasa da

hayallerinle yaşamak

sana,sahip olmak kadar

güzeldi canım.

Ahh! keşke şimdi

şimdi yanımda olsan

olmazmı? canım.', 'Bir ben vardım bir de, karanlığı aydınlatan renk cümbüşü yakamozlar. ogece, ağlaştık sabaha kadar. Anlaşılan o ki!  kaderimiz aynı sizde ben...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Dikmen 2']::text[], 8.5, '{"poet":"İbrahim Dikmen 2","poet_slug":"i-brahim-dikmen-2","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/olmazmi-canim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Beni Getirsem', 'sana-beni-getirsem-mehmet-husnu-asan-hnr33', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Beni benden ister içimdeki ses

Bilmem ki içimdeki ben ben miyim

Beni bana yöneltir içinde nefes

Bilmem ki içimde ben nefesmiyim

Aynada durup ta halime gülme

Gel ey gülizarım gönlümden gitme

Yunusun karnını şavkından etme

Garipler garibi ben ben değilim

Ben Kenan oldum sen kimlerdensin

Gönlüm taklamakan sen nerlerdensin

Eyyübe sabrı veren yerlendenmisin

Aşkıma aşık olup meşk eder oldum

Divanedir deli gönül divane

Divaneler gelir oldu divane

Dile geldi gönül deli  divane

Aşıklar aşıkı bin beter oldum

Dile gelse gönlüm anlatsa beni

Sana beni getirsem içimden beni

Beni benden bekleyen o abdal beni

Havanda eze eze un eder oldum

Mehmet Hüsnü ASAN

Şırnak-2004', 'Beni benden ister içimdeki ses Bilmem ki içimdeki ben ben miyim Beni bana yöneltir içinde nefes Bilmem ki içimde ben nefesmiyim Aynada durup...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Hüsnü Asan']::text[], 8.5, '{"poet":"Mehmet Hüsnü Asan","poet_slug":"mehmet-husnu-asan","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sana-beni-getirsem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Değişen Gurbet', 'degisen-gurbet-mehmet-husnu-asan-mn9e8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İşte gurbetteyim anne

Ben okuyorum sayfalar çevriliyor

Sayfalar çevriliyor ben okuyorum

Ve kirleniyor sayfalar parmaklarımda

Yürekler kirleniyor anne

Parmaklarım çevirdikçe

Ellerim kirleniyor anne

Yürekler kirlendikçe

Gurbet kirlenmiş anne

Sayfalar kirlenmiş harfler silinmiş

Kara tren düdüğü çalmaz olmuş

Makinist değiştikçe

Yollar değişmiş yurtlar değişmiş

Yüzler asılmış gözler söndükçe

Sevda bir tuhaf olmuş

Sevgililer sevmedikçe

Gurbet türküleri gurbette kalmış

Gurbet gurbeti gurbette gördükçe

Ben gurbetteyim anne

Yoksa gurbet mi bende

Yüreğim yanıyor

Canım acıyor

Dağlar yüreğime konuşlanmış

Gurbet dağlara çöktükçe

Gurbet bir kitap, okudukça acıtan

Gurbet bir kitap, okudukça ağlatan

Gurbet benim anne gurbet bende

Dönülmez bir yolda yürürken senle

Gel anne gurbetten al beni

Çal anne bu kitaptan çal beni

Kirlenen yüreğimle bul beni

Sev beni anne GURBETTE sev beni

Mehmet Hüsnü ASAN

Şırnak-2004', 'İşte gurbetteyim anne Ben okuyorum sayfalar çevriliyor Sayfalar çevriliyor ben okuyorum Ve kirleniyor sayfalar parmaklarımda Yürekler kirlen...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Hüsnü Asan']::text[], 8.5, '{"poet":"Mehmet Hüsnü Asan","poet_slug":"mehmet-husnu-asan","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/degisen-gurbet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ilgıt Ilgıt Bir Yürüyüş', 'ilgit-ilgit-bir-yuruyus-mustafa-gokcek-u6qzj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Uzun bir maratona başlamıştım, elimi tuttuğun an

Yolda yürürken yapayalnız, yalpalayarak

Nice düşler kurdum senli, sensiz

Yürüdüm delice ve seni kucaklamak için

Yağan yağmurda şemsiye oldun

Bir tür sevi sağanağında patırtılı bir kadındın

Yarınların seni yanlış tanıdı ama

Günlerinin dolu dolu finaline kucak açtın

O günler, ardı arkasına ve çok çabuk geçti

O günler, bir çabuk ve çok hızlı geçti

Yalpaladığımda elimden tuttun

Hatıralarını sakladığın, sandık odasında

Neden büyüdüm ve neden bıraktım elini

Mahcubiyet yaşatmayan bir tür tarihsel yanılgı

Yalın bir dil bu sıcakta, buruk, nemlenen gözlerin

Sana, dolu bir aşk sundum ama sen beni terk ettin, anne...', 'Uzun bir maratona başlamıştım, elimi tuttuğun an Yolda yürürken yapayalnız, yalpalayarak Nice düşler kurdum senli, sensiz Yürüdüm delice ve ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Gökçek']::text[], 8.5, '{"poet":"Mustafa Gökçek","poet_slug":"mustafa-gokcek","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ilgit-ilgit-bir-yuruyus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dilek', 'dilek-sair-shimalwest-fpme7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'bir dilek tut şimdi

tahmin et gözündeki kirpiği

dilerim olsun ne dilersen

aynı anda kirpik düşsün iki gözünden

bir dilek tut şimdi

kadın mı erkek mi köşeden dönen

dilerim olsun ne dilersen

çift olsun köşeden gelen

bir dilek tut şimdi

kayan yıldıza bakarken

dilerim olsun ne dilersen

yıldızları kaydırırım ben', 'bir dilek tut şimdi tahmin et gözündeki kirpiği dilerim olsun ne dilersen aynı anda kirpik düşsün iki gözünden bir dilek tut şimdi kadın mı ...', ARRAY['Türk Edebiyatı','Şiir','Şair Shimalwest']::text[], 8.5, '{"poet":"Şair Shimalwest","poet_slug":"sair-shimalwest","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/dilek-71-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Resim', 'resim-sair-shimalwest-2rqzj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'yoksa

mutluluk mudur herkesin aradığı 

huzur mudur kimsenin bulamadığı

yoksa

kolay mı kaybedilir zor bulunanlar

zor mu bulunur kaybedilmeyenler

yoksa

sevgi midir içimizi ısıtan

ısıttıkca içinde yanılan

yoksa

var mıdır mutluluğun resmi

çizmiş midir herkes

senin de çizdiğin gibi', 'yoksa mutluluk mudur herkesin aradığı  huzur mudur kimsenin bulamadığı yoksa kolay mı kaybedilir zor bulunanlar zor mu bulunur kaybedilmeyen...', ARRAY['Türk Edebiyatı','Şiir','Şair Shimalwest']::text[], 8.5, '{"poet":"Şair Shimalwest","poet_slug":"sair-shimalwest","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/resim-50-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben En Çok Seni Özledim', 'ben-en-cok-seni-ozledim-murat-karatekin-twwsh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ben en çok seni özledim 

Sana  sarılmayı,

Sımsıcak  kalp atışını

Ve ellerimin arasından

Akıp giden saçının titrek 

Tellerini  özledim.

Ben en çok seni özledim

Derinliğinde kaybolduğum

Gözlerine ne demeli bilmem.

Beni  sonsuzluğa sürükleyen

Ve ansızın hüzünlerin en çıkmazına iten

O derin ve

Güzel gözlerini özledim.

Ben en çok  seni özledim 

Sesindeki çocuksuluğu,

Varlığındaki çoşku ile

Kederin o muhteşem yoğruluşunu,

Olmadık zamanlarda

Olmadık  benzetmelerini,

Mesela ile başlayan

Ve insanın ruhunu okşayan

Hecelerinin kelime olmaya

Koşuşunu  özledim.

Ben en çok seni özledim 

Yorgun bir akşamda

Yürürken  kaldırımlarda

Sensizliği solumayı

Ve  sensizlikle yürümeyi özledim

Ben en çok seni özledim

Seni seviyorum 

Deyişin  içindeki seni

Ve şiirlerdeki her bir satırın,

Sana dönüşünü özledim.

Ben en çok seni özledim

Yağmur yağarken üzerime

Gözyaşlarımı bırakıp gökyüzüne

Başka bir yağmurla sana yağsın diye

Umut etmeyi  özledim…

Ben en çok seni özledim

Kalbindeki  insanlara rağmen

Orada sıkışacak bir yer bulmak

Ve dışarda kalmamak için yaptığım

Çırpınışları özledim…

Ben en çok seni özledim

Sen,

Kimi özledin…

MK…', 'Ben en çok seni özledim  Sana  sarılmayı, Sımsıcak  kalp atışını Ve ellerimin arasından Akıp giden saçının titrek  Tellerini  özledim. Ben e...', ARRAY['Türk Edebiyatı','Şiir','Murat Karatekin']::text[], 8.5, '{"poet":"Murat Karatekin","poet_slug":"murat-karatekin","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/ben-en-cok-seni-ozledim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Suni Beşer', 'suni-beser-tulay-sustam-ytf3e', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'takma tırnak mı taksam? 

dokunsa parmak uçlarım tenine

varlığımı öyle de olsa hissetsen! ...

takma saç mı taksam? 

parmak uçların dolansa saç tellerime

varlığını öyle de olsa hissetsem! ...

takma diş mi taksam? 

sana her kızdığımda kanasa dudaklarım

yokluğuna alışsam... her kızdığımda seni unutsam

aldırma! ... takma kafana! ...

takma! ...

uzağı görüpte yakını göremeyen gözlüklerini...

ben suni beşer değilim olamam da...

yüreği güzel, ismi güzel sevdiğim...

bundan böyle sen bana takılma...', 'takma tırnak mı taksam?  dokunsa parmak uçlarım tenine varlığımı öyle de olsa hissetsen! ... takma saç mı taksam?  parmak uçların dolansa sa...', ARRAY['Türk Edebiyatı','Şiir','Tülay Sustam']::text[], 8.5, '{"poet":"Tülay Sustam","poet_slug":"tulay-sustam","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/suni-beser-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Kendimi Arıyorum!', 'ben-kendimi-ariyorum-emel-manav-bpyth', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Baharda mı saklısın can 

Yoksa kışta mısın her an? 

Bahar gelir görmez misin, 

Sen hiç ışkın vermez misin? 

Dünyada mı, uzayda mı, 

Bu bedende, damarda mı? 

Can mı kaldı bu bedende 

Kuru bir tabutum böyle. 

Seni aradım sessizce, 

Sen ki saklandın hissizce! 

Umutlarımı tükettin, 

Ki isyana mecbur ettin. 

Pişmanlığa gebe gönül. 

Bak işte umutsuzum, 

Fakat sana da susuzum. 

Bir bana hayat dikenmiş, 

Sanki hayatım tükenmiş. 

Şu ayakta durana bak, 

Sadece bir et yığını. 

Gözlerini dersen eğer, 

Biçare bakar ve yaşlı! ! 

Aşk mı, de güldürme beni, 

Zayıflık ve acizlik de 

Hülasa sen ne dersen de. 

Ben artık yitirdiğim, 

kendimi arıyorum! !', 'Baharda mı saklısın can  Yoksa kışta mısın her an?  Bahar gelir görmez misin,  Sen hiç ışkın vermez misin?  Dünyada mı, uzayda mı,  Bu beden...', ARRAY['Türk Edebiyatı','Şiir','Emel Manav']::text[], 8.5, '{"poet":"Emel Manav","poet_slug":"emel-manav","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/ben-kendimi-ariyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beklemekteyim...', 'beklemekteyim-i-brahim-ethem-bingul-p33pw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Tarifesiz treni beklerim

Tek durağı aşk...

Bilet yok, ses yok

Seferler iptal olmuş...

İşaret beklerim

Kıpırtı

Aşk kokan...

Hareket yok

Hisler felç olmuş...

Seni bekledim senden

Tren yolculuğuna 

Sonsuza...

İstasyon soğuk, bomboş

Bekliyorum hâlâ

www.iebingul.com', 'Tarifesiz treni beklerim Tek durağı aşk... Bilet yok, ses yok Seferler iptal olmuş... İşaret beklerim Kıpırtı Aşk kokan... Hareket yok Hisle...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/beklemekteyim-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İşte Halim ve Netice….', 'i-ste-halim-ve-netice-emel-manav-tlstj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ben seni aramaz mı, 

Senden hesap sormaz mıyım? 

Sen de mutlu olamadın, 

Ahım yerde kalır sandın. 

Şunu bil ki; 

Benden yıllarımı çaldın. 

Ve kız sen seni ne sanırdın. 

Seni başıma taç ettim, 

Yaralara ilaç ettim. 

Bu gönül evime sultan, 

Ve de başıma taç ettim. 

Adın ki aklımda hece 

Sözüm vardı nice nice 

Doğranmışım ince ince', 'Ben seni aramaz mı,  Senden hesap sormaz mıyım?  Sen de mutlu olamadın,  Ahım yerde kalır sandın.  Şunu bil ki;  Benden yıllarımı çaldın.  V...', ARRAY['Türk Edebiyatı','Şiir','Emel Manav']::text[], 8.5, '{"poet":"Emel Manav","poet_slug":"emel-manav","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/iste-halim-ve-netice-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Can yoldaşım;', 'can-yoldasim-emel-manav-59y3i', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Darıldım yıllara, küskünüm sana. 

Kar yağdı, ak düştü bu saçlarıma. 

Hep sarıldım dostluğa, 

Sarıldım insanlara… 

Düşe kalka büyüdüm, 

Bu güne geldi yaşım 

Çok zamansız ağrıdı, 

Çok çile gördü başım 

Sohbetlerim dinlenir, 

Acı değildir çayım 

Can yoldaşım sen benim, 

Dertlerime ilacım 

Derdim ne para benim 

Ne de pulda, gözüm yok 

Olmasın tek ağacım, 

Ki ben sana muhtacım. 

Tek servetim ol benim, 

Ey sevgili yoldaşım! !', 'Darıldım yıllara, küskünüm sana.  Kar yağdı, ak düştü bu saçlarıma.  Hep sarıldım dostluğa,  Sarıldım insanlara…  Düşe kalka büyüdüm,  Bu gü...', ARRAY['Türk Edebiyatı','Şiir','Emel Manav']::text[], 8.5, '{"poet":"Emel Manav","poet_slug":"emel-manav","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/can-yoldasim-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canım Babam', 'canim-babam-i-brahim-ocak-3efyy', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Seni Sivas’tan çağırdım

Ankara’da herşey daha iyi olur sandım

Sağlık ve sıhhatindi tek arzuladığım

Aslında bilsen şimdi nasıl pişmanım

Keşke diyorum çağırmaz olsaydım

Ah canım babam nasıl yanıyor içim

Affet, ne olur affet sızlıyor vicdanım

Canım Babam

Seni en son yoğun bakımda gördüm

Ellerinden tuttum canım babam dedim

Duydun mu duymadın mı bilemedim

Sesim titreyerek bana küskün müsün dedim

Hiçbir şey demedin

İşte o an hem kendime hem de kaderimize kahrettim

Küskün müsün değil misin bilemedim

Düşündükçe tek tesellim

Hep nasihat ederdin

Baba oğul arasında küslük olmaz derdin

Belki de küskün değildin

Göz yaşlarımı hiç kimseden gizlemedim

Senden gizlediğim kadar

Gözlerine bakarken gözlerimi kırpmadım bile

Yaş akar da üzülürsün diye

Gördün mü görmedin mi bilemem

Hakkını helal et Canım Babam diyecektim

Üzer miyim üzmez miyim dedim

Bir türlü söyleyemedim

Helal ettin mi etmedin mi diyemedim

Her ziyaretimde saçlarını okşadım

Ellerinden tuttum öptüm

Ayrılırken yüreğimi seninle bıraktım

Allah’a emanet ol dedim ben çıktım

Yüreğimi hissettin mi hissetmedin mi bir işaret 

Vermedin

Tekrar görür müyüm göremez miyim bilemedim

Hep gitme oğul beni bırakma demeni bekledim

Niye demedin yoksa yoksa dedin de ben mi işitmedim

Dedin mi demedin mi bilemedim

Ah Canım Babacığım

Sen dertleri hep içine gömdün

Kış güneşi gibi gördü mutluluğu ömrün

Dertlerden yüreğine ağ ördün

Canım Babacığım

Son yolculuğuna uğurlarken

Acıyla kederle geçen bir ömrün

Gizli kasasıydı gönlün

Ben ise Canım Babam işte gördün

Seni önce yüreğime sonra da; 

Kara toprağa gömdüm

Gördün mü görmedin mi bilemedim

Canım Babam

Hava soğuk orda üşüyor musun

Senin için dualar ediyorum duyuyor musun

Acıların dindi mi rahat uyuyor musun

Yoksa sen de bizi mi düşünüyorsun

Biliyor musun baba ben seni çook çook özlüyorum

Elbet bir gün kavuşacağız be baba

Bak aslında hayat ne kadar da kısa

Birileri de beni verince kara toprağa

Kavuşacağız o zaman oğul babaya baba da oğula

Söylediklerini unuttun mu bizden ayrılınca yoksa

Hep demez miydin topraktan geldik döneceğiz toprağa

İnancımız sonsuz Yüce ALLAH’a

Unutma Canım Babam kucaklaşacağız bir gün doya doya

Canım Babam

Toprağın bol hesabın kolay

Cenabı ALLAH’ın (C.C)  selamı

Hz. MUHAMMED’in (S.A.V)  şefaati

Bizlerin de duaları seninle olsun

Ruhun Şâd mekânın da Cennet olsun', 'Seni Sivas’tan çağırdım Ankara’da herşey daha iyi olur sandım Sağlık ve sıhhatindi tek arzuladığım Aslında bilsen şimdi nasıl pişmanım Keşke...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ocak']::text[], 8.5, '{"poet":"İbrahim Ocak","poet_slug":"i-brahim-ocak","theme":"Türk Şiiri","is_hero":false,"total_lines":70,"source_url":"https://www.antoloji.com/canim-babam-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşığın Onuru', 'asigin-onuru-i-brahim-ocak-ed4ik', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gerçek aşk şiddetli fırtınaların 

Kabartıp coşturduğu azgın dalgaların

Yarattığı acımasız sarsıntıların

Çılgınca vurduğu açık denizlerdeki sandal kadar

Çaresiz, yalnız, masum ve duyguludur

Çalkantılı bir denizde ruhun kuytularına yolculuktur

Ama dalgalara meydan okuyacak kadar da cesurdur

Çünkü cesaret aşığın yüreğindeki onurudur', 'Gerçek aşk şiddetli fırtınaların  Kabartıp coşturduğu azgın dalgaların Yarattığı acımasız sarsıntıların Çılgınca vurduğu açık denizlerdeki s...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ocak']::text[], 8.5, '{"poet":"İbrahim Ocak","poet_slug":"i-brahim-ocak","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/asigin-onuru-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Ki Gülünce', 'sen-ki-gulunce-ali-aldemir-2trim', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bilmezdim nedir korku

Neye benzer korkmak,

Bükülmez sanırdım bileğimi

Dağ bilip yumruğumu,

Sakınmayıp budaktan gözümü

Yürüyüp giderdim ekmeğin üstüne

Gülün üstüne gider gibi,

Gider gibi sevdanın üstüne

Senin yoluna,

Giderdim ölümlerin,

Kanın üstüne, puşt zulalarına,

Daha kolaydı sanki

T a n ı y ı p   b i l m e d e n

Sevmeden önce seni yaşamak.

Emeklediğim düşe kalka büyüdüğüm

Çocukluğumun geçtiği ev,

Bu izbe sokaklar bu şehir

Ve yalnızlığım

Şimdi sensiz beni korkutur,

Uzattığımda sehpaya

Altındaysa sigara nasıl elimin

Duruyorsa nasıl yastık yatağımda

Ve nasılsa her sabah içtiğim kahvenin

T i r y a k i l i ğ i......

Sende öylesin,

Her dönüşümde  bulmaya alışmışım.

Vurmasa da ayın aydınlığı yoluma

Temmuz 

.....güneşli 

.........gülüşün

Yeterdi  bana,

Yolumu, yüreğimi aydınlatmaya.

Çiçekler açardı sen ki gülünce

...Türkü olur, 

....   ırmak olurdu,

Yüreğim 

...   sevdaya 

....      akan 

Sen ki gülünce 

...   utanırdı gül,

Susardı bülbül

Uyanıp açardı güneş gözlerini

Aydınlanırdı gecem,

Sen ki gidince

Yalnızlığım daha bir büyüdü

Ve yalnızlığımdan duyduğum korkularım,

Sen ki gidince korkular tanıdım 

...   Ve 

....      utanılacak 

.....         bir şey 

......            olmadığını

Canlılara özgü olduğunu anladım 

...   Korkuların

....      korkmanın,

Şimdi uzun bir yol sana erişmek

Korktuğum yürümekten.

Çekip gitmek var ya

Unutmak var ya seni bir dem olsun

...   Ben 

....      çekip 

.....         gitmeye de,

Seni 

...   unutmaya da 

....      korkarım

Sen ki gülünce........', 'Bilmezdim nedir korku Neye benzer korkmak, Bükülmez sanırdım bileğimi Dağ bilip yumruğumu, Sakınmayıp budaktan gözümü Yürüyüp giderdim ekmeğ...', ARRAY['Türk Edebiyatı','Şiir','Ali Aldemir']::text[], 8.5, '{"poet":"Ali Aldemir","poet_slug":"ali-aldemir","theme":"Türk Şiiri","is_hero":false,"total_lines":65,"source_url":"https://www.antoloji.com/sen-ki-gulunce-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bergüzar', 'berguzar-emine-tansu-2c58h', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Nefesi öksürüyor, el yordamıyla bulduğum kayıp düş atımlarının.

Hüzün kokuşlu bir kaktüsün iliklerime batan susuzluğu, gövdeme yaslıyor başını.

Siren sesleri tuzak gibi patlıyor,

Endamını soyunan zavallı çınarların üşüyen dallarına.

Aslında hakettiğim bir trajedinin,

Hariçten gazelini okuyorum sil baştan.

Birazdan basılırım zabıtalarca...

Baykuşlar az sonra devralır üşengeç nöbetini gecenin, kurşun askerlerden; 

Adımları iki göz odadan duyulur zıpkın yemiş gölgelerinin.

Ağız dolusu kahkaha boşalır sokaklara,

Salyaları ayağa bulaşmış adamcıl şakayıklardan.

Bir türkü yanıma oturur şimdi,

Çıkar yalım yalım kahrına, hasret komedyası yolların.

İlahi! 

Durup dururken nereden çıktı bu kasvetli nesir şimdi...

İki kuruş ziftli elyazım vardı, bütün kapıları ağlattı sen giderken.

Köstekli destekleri olmasa hani,

Peçesini çıkaran güz vurgunu sardunyaların,

Oturup bende ağlayacaktım.

Çınlayan kulaklarıma parmağını bassın biri! 

Yoksa bütün pervaneliği imzasız kalacak ökçeli yazıtlarımın...

Yolcu! 

Soluğuna bulaşan bu pelesenk firarı biliyorum.

Afişlere basmışlardı bir gece gözlerindeki kıskançlığı.

Fışkıran bir sessizlik var asude tavanlarda.

Bu çılgın dünyanın boylamlarında gezinen riyaya dayanamıyorum.

Ne olur, beni de götür cennetin ölümcül saklambaçlarına...

İki dirhem katran oluyor ağıtlarda sızım,

Ilıman bir ıssızlığın kollarını sıvıyor gece.

Ne kadar da senliymişim ben olmadan...

''Bergüzar yollamış ellerin yari,

Yüzden seven çok olur, candan sevenin hani...''

Lamekân! 

Sen nereden başlamıştın sevmeye beni...? 

Kaybolduğumu biliyorum bu felsefe bozuntusu anlatılarda.

Kötü bir nişancıyım ben.

O halde kendimden başlıyorum mitolojik acıları vurmaya...

Kamyonlar şehirleri taşıyor durmadan, 

Arabesk bakışlı camlara uyku kusarak.

''Pencereden kar geliyor...''

Yalınayak bir karabasan, damarlarından yakalıyor kabuslarımı.

Üzgünüm...

Cebimde düşleri korkutacak kadar ''aşk'' kalmadı...

İki yüz yirmi iki gündür bileklerine kan oturuyor harflerin.

Yazdığın ne varsa kangren olup kesiliyor.

Ben,

Kendimden başlıyorum bundan sonra paragraflara...

Dikiş tutmuyor adsız bıraktığın soluksuz yolculuklar,

Akıl sır ermiyor gülüşündeki tonsuz moral bozukluklarına.

Korkusuz korkakların titremeleri geçiyor yavan lakırdılarının ardına. 

Biliyorum...

Cezirelerden yankılanan benim adım değil! 

Bu bas bas kanırtılan gece,

Senin pencere diplerinde gidermedi yalnızlığını.

Katliamlara namzet bir suskunluğun bütün muştusu,

Kelimelerinin ayak sesinden çıkmadı.

Telaşsız imgeleşen ağzından tükürülmedi hayat hiçbir kere.

Bu başı kesilen kalabalık, irdelemedi senli- sevgili saatlerimi.

B e r g ü z a r... Nefesinden gelmedi...

Ahrar bir geleceğin yortusunu karşılarken yabancılar,

Dilime revan ''ır''lar çek gözlerine.

Ben sana ''at'' desem de, 

Sen kovma koleksiyonundan milatlık pulları.

Sadece suya ihtiyacım vardı bir bardak.

Nemli bir kutsallıkta, yanımda yatan yabancı! 

Ayrıntıları düşleyicilerinde bile kalmayan bir coğrafyadan,

Zeytin gözlü oğlan çocukları biriktirerek salıncaklara,

Daima ezberinde tut sıcaklığımı.

İçime sahip çık, dışıma türküler çal...

Düşümün sisli adamı! 

Bana şiirle bak...', 'Nefesi öksürüyor, el yordamıyla bulduğum kayıp düş atımlarının. Hüzün kokuşlu bir kaktüsün iliklerime batan susuzluğu, gövdeme yaslıyor başı...', ARRAY['Türk Edebiyatı','Şiir','Emine Tansu']::text[], 8.5, '{"poet":"Emine Tansu","poet_slug":"emine-tansu","theme":"Türk Şiiri","is_hero":false,"total_lines":71,"source_url":"https://www.antoloji.com/berguzar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Çocuklar Bizim.', 'bu-cocuklar-bizim-muharrem-ozturk-pjkwp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bu çocuklar bizim.

Ve bizim geleceğimiz hepsi kuşkusuz,

Soğuk kış gecelerinde yapayalnız,

Çaresiz bıraktığımız.

Bu Çocuklar bizim.

Titreyen elleri,

Ve aç karınları,

Ve hastalıkları bizim.

Kimi zaman sokağa terkettiğimiz,

Kimi zaman bir bombanın insafına,

Çoğunlukla hor görüp,

Bir tekme de biz attığımız,

Bu çocuklar bizim.

Ve bu çocuklar,

Korktuğum geleceğim!', 'Bu çocuklar bizim. Ve bizim geleceğimiz hepsi kuşkusuz, Soğuk kış gecelerinde yapayalnız, Çaresiz bıraktığımız. Bu Çocuklar bizim. Titreyen ...', ARRAY['Türk Edebiyatı','Şiir','Muharrem Öztürk']::text[], 8.5, '{"poet":"Muharrem Öztürk","poet_slug":"muharrem-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/bu-cocuklar-bizim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hakkın Yok', 'hakkin-yok-husamettin-gunacti-tcor2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'dilin varmasın bir daha

mutsuzum demeye...

senin için çarpan bir kalp

varsa hâlâ

hakkın yok

mutsuzluktan söz etmeye...

07-12-2004', 'dilin varmasın bir daha mutsuzum demeye... senin için çarpan bir kalp varsa hâlâ hakkın yok mutsuzluktan söz etmeye... 07-12-2004...', ARRAY['Türk Edebiyatı','Şiir','Hüsamettin Günaçtı']::text[], 8.5, '{"poet":"Hüsamettin Günaçtı","poet_slug":"husamettin-gunacti","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/hakkin-yok-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kim bilir...', 'kim-bilir-sezen-coban-ajr64', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Seni anlamadım 

anladığımı zannettim..

Konuşurken sen kendi içinde kendinle 

Ben hep bir adım geriden geldim

İzlerinden kaç yol boyu gittim kim bilir? 

Ararken seni ben yabancı gözlerde

Baktımsa bile görmedim..', 'Seni anlamadım  anladığımı zannettim.. Konuşurken sen kendi içinde kendinle  Ben hep bir adım geriden geldim İzlerinden kaç yol boyu gittim ...', ARRAY['Türk Edebiyatı','Şiir','Sezen Çoban']::text[], 8.5, '{"poet":"Sezen Çoban","poet_slug":"sezen-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/kim-bilir-29-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelme', 'gelme-ali-gencay-4qcjj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İstemem gelme

Seni zamandan öte sevdim

Bana tarih verme

Asırları önüne serdim

Yitikti sevda sende

Bitirdin beni de

Yeniden doğdum

Çocuk oldum

Eneklerimi çaldılar

Koptu uçurmamın ipi 

Güvercinlerimi  kaçırdılar

Ne bilirim kimler okşar

Kim bilir nerde

Hangi ellerde

Azalan ömürden bir gün

Bekli de bir an

Geceye büründüm

Korkma önünde durmam

Bak gecelerde bitti

Ben azaldım 

Sendin çoğalan

Çok geldi de

Yeter mi dedim

Yazma diyorsun

Ben her anı kelimelere böldüm

Yoksa seni nasıl beklerdim

Kara yazdım,gece oldu

Ak yazdım,güneş doğdu

Sayfa biti yıllar oldu

Yazma diyorsun

Korkma henüz bir asır oldu

Hadi gel

Saçlarımdan yıldızları ayıkla

Tak gerdanına

Yok! 

Dokunma vazgeçtim

Bunları ben istedim

Sen! 

Belki de hiç istemedin', 'İstemem gelme Seni zamandan öte sevdim Bana tarih verme Asırları önüne serdim Yitikti sevda sende Bitirdin beni de Yeniden doğdum Çocuk oldu...', ARRAY['Türk Edebiyatı','Şiir','Ali Gençay']::text[], 8.5, '{"poet":"Ali Gençay","poet_slug":"ali-gencay","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/gelme-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim...(DY3)', 'benim-dy3-murat-karatekin-6lzhi', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'En son kuytu bir sokak başında ve kuytu bir sesszilikte bırkamıştım kendimi. Küçük heceler birleşerek büyük kelimeleri oluşturmaya başladığından beri böyle sessiz ve kuytularda varoluyorum her nedense. Paylaşımım azaldı insanlarla çok sık yalnız kalır oldum kendimle ve benliğimle. Işte andımya adını fırsat bu fırsatmış gibi çıkı verdi gene karşıma her zamankinden daha neşeli görünüyor bu kez. Mutluluğunun nedeni nedir diye soruyorum kendisine hiç beklemediği bir anda. Toparlanmaya  çalışıyor ve şaşkına uğramadığını gösteren bir kaç çeki düzen hareketinden sonra yalnız oluşun, güvensiz oluşun ve herşeyden önce bu aralar sessiz oluşun mutluediyor beni diyor usulca. Ben miyim güvensiz olan diye haykırıyorum ve daha da bir siniyor içine, yüzünün mutluluktan kırışmış ifadesi tek tek düzeliyor ve geriye o kibirli,cansız ve hiçbir ifadeyi yansıtmayan dümdüz suratı kalıyordu karşımda. Artık başlamıştık karşılıklı sohbete – yada yüzleşmeye- tekrar etti neden bu kadar güvensizsin dedi bana neden neden neden diye tekrarladı üçkez. Anlamı güçlendirmek için böyle yapardı, her zaman soruları vurgulardı böylece daha bir güçlü gibi görünürdü soruları. Çok mu merak ediyorsun diye karşılık verdim kendisine. Ben meraketmiyorum unuttunmu ben senin beninim merak diye birşey yok bende. Ben    yaşadıklarına yön vermeye çalışırım, sende bunların hangisini yapacağını yada daha doğrusu ne kadarına karşı koyabileceğini sınarsın ve karşı koydukların senin başarın, karşı koyamadıklarında benim zaferim ve senin tükenişin oluyor anlıyormusun benim hım…! Bu gece çetin geçecek anlaşılan diyorum içimden, evet diyor oda cevap olarak – içimdi o benim doğruya duyamadığı ve göremediği hiçbirşey yoktu ben adına-. 

Benim güvensizliğim diye başlıyorum söze ve hemen kibirli bir karşılık; evet senin güvensizliğin diye sersemce bir ifadeyle bakıyor bana. Ben devamediyorum ve tekrarlıyorum benim güvensizliğim insana mı sanıyorsun  ahmak diye fırlatıyorum mızrağımı. Benim güvensizliğim insan olana değil, tam aksine insan gibi görünen insan müsveddelerine anlıyor musun? Müsveddelere güvenmiyorum, sayıları her geçen gün artan bu  kusursuz görünümlü,aynı aptal ifadeli,aynı tepkileri veren ve daha sayamayacağım pek çok özelliği aynı olan insanlara güvenmiyorum anlıyor musun Benim? Insanla hiç sorunum olmadı benim tüm kavgam tüm mücadelem müsveddelerle oldu. Insan gibi insan gördüğümde sımsıkı sarıldım bir daha bırakmamacasına. Gözlerine baktığında içini gördüğün insan gibi insanlardan bahsediyorum. Göz yaşını ucuz bir filmde harcamayan, tepkisizliği tepki sanmayan, inandıkları uğruna her şeyini feda etmeye hazır insanlardan bahsediyorum. Sorarım sana böyle kaç insan var hım..? Cevap veremezsin çünkü sen hep müsveddelerle varoldun, aslından korktun insanın çünkü senin için büyük tehlike onlar değil mi söyle hadi söyle…! Neden güvenmiyorum anlıyor musun şimdi ve kime güvenmiyorum anlıyor musun seni ucuz kahraman, seni kendini bilmez ve herşeyi bildiğini zanneden ahmak.

Herşeyde varoldu yalan

Aslı  kayboldu insanın

Müsveddeler oldu can 

Insanlık tuhaf  bir  kelime 

Talan üstüne talan…

Söylemiştim ya küçük heceler büyük kelimelere dönüştüğünden beri çözmeye başladım içimdeki gizi ve karşımdaki sizi. Sizi diyorum çünkü siz o kadar çoksunuz  ki ve o kadar aynısınız ki siz gibi küçük bir kelime bile ifade ediyor tümünüzü ve varlığınızı. Neden böyle oldu diye düşünüyorum artık benimle değil kendimle konuşuyorum. Neden böyle olduk? Neden tek tip oldu herşey? Neden koca bir yalanın parçası olduk? Yürürken hayat yolunda neleri kaybettikte çıktık insanlıktan ve razı olduk müsvedde olmaya. Düşünmek zor mu geldi bize, paylaşmak acıyı, mutluluğu ve gözyaşını saçmalık mı oldu, sorgulamak suç, sorgusuz yaşamak mutluluk mu oldu,aşk ucuz, seni seviyorum da dile dolanan ve öylesine söylenen bir kelime mi oldu. Ne oldu söyleyin, ne oldu…………………………………………… o kadar çok nokta bırakıyorum ki size gün olur belki sizde isyan edersiniz müsvedde olmaya ve doldurmak istersiniz “ne oldu” dan sonrasını. Umut ediyorum, umut bir çözüm olmasada. Bırakıyorum geceye küçük üç hece ve çok büyük bir boşluk noktalar içinde, siz doldurmak istersiniz diye.

İki damla yaş

Iki damla insan,

ele avuca sığmayan.

Üç  hece

Iki kelime

“ Ne oldu”, bize…

Geceye bırakılan bir kaç gözyaşı ve nemlenmiş gözlerle bakıyorum yıldızlara. Hiç bu kadar bulanık değillerdi diye düşünüyorum, gözümde olmayan gözlüklerimin farkında olmadan. Müseveddeler için bırakılmış iki gözyaşı damlası için özür diledikten sonra yağmurdan gözlüklerimi takıyorum ve merhaba diyorum size…', 'En son kuytu bir sokak başında ve kuytu bir sesszilikte bırkamıştım kendimi. Küçük heceler birleşerek büyük kelimeleri oluşturmaya başladığı...', ARRAY['Türk Edebiyatı','Şiir','Murat Karatekin']::text[], 8.5, '{"poet":"Murat Karatekin","poet_slug":"murat-karatekin","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/benim-dy3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim Şerefime', 'benim-serefime-halil-kesken-zjm11', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Her gece bir barda görürüm seni

Benden ayrılmanı kutluyormuşsun

Bir kere adımı bile anmadan

Benim şerefime içiyormuşsun

Sarhoş oluyorsun içince bir tek

Gerçekler ortaya çıkıyor tek tek

Sabahlara kadar gözyaşını sek

Benim şerefime içiyormuşsun

Sözde yüreğine gömmüşsün artık

Mutlu günlerine dönmüşsün artık

Şişenin dibini görmüşsün artık

Benim şerefime içiyormuşsun

Gece yarısında çıkıyor resmim

Artık yer ediyor diline ismim

Gelene geçene bu eski aşkım

Deyip şerefime içiyormuşsun', 'Her gece bir barda görürüm seni Benden ayrılmanı kutluyormuşsun Bir kere adımı bile anmadan Benim şerefime içiyormuşsun Sarhoş oluyorsun içi...', ARRAY['Türk Edebiyatı','Şiir','Halil Kesken']::text[], 8.5, '{"poet":"Halil Kesken","poet_slug":"halil-kesken","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/benim-serefime-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Bilirdim', 'ne-bilirdim-ali-gencay-slx7v', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Üşümüştü ellerin,yüreğin 

Isıtmak istedim

Ne bilirdim 

Çözülecek buzların

Göz yaşlarınla ıslanacaktı ellerim

Ben yazdım,sen oku istedim

Ne bilirdim 

Kayacaktı gözlerin

Geceyi ikiye bölecektin

Seni kaybedecektim

Uzaktan öylece seni izledim

Sigaradan derin bir nefes çektin

Kelimelerimde kayıp olu verdin

Ne bilirdim 

Kaybettim! 

Halen peşindeyim', 'Üşümüştü ellerin,yüreğin  Isıtmak istedim Ne bilirdim  Çözülecek buzların Göz yaşlarınla ıslanacaktı ellerim Ben yazdım,sen oku istedim Ne b...', ARRAY['Türk Edebiyatı','Şiir','Ali Gençay']::text[], 8.5, '{"poet":"Ali Gençay","poet_slug":"ali-gencay","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ne-bilirdim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece,Rüzgar,Deniz Ve Ben', 'gece-ruzgar-deniz-ve-ben-ali-gencay-i9n1m', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bak! 

Yalnız kaldık

Gece,sen ve ben

Bulutta çok,yıldızları sayacaktık

Sen mızmızlandın

Ayaklarını avuçlarına alıp

Çekip yorganı üzerine,saklandın

Ben uyuyamadım

Gece ve ben

O gece binlerce yıldızlar saydık

Gece bana masallar anlattı

Biliyorum duydun sende

Zaten biz onlara sana anlattık

Zaman ilerledi

Saatleri harcadık

Yağmur başladı

Bizse yağmurdan önce ıslandık

Gece ve ben

O gece sağanaklarla ağladık

Deniz kıskandı bizi

Kudurdu,köpürdü

Onu da yanımıza aldık

Yakamozlar ikram etti bize

İçtik,içtik sallandık

Gece denize sarıldı

Ben geceye yaslandım

Seni seyre daldık

Rüzgar çığlıklar attı

Avazına dayanamayıp

Onu da kareye aldık

Esti,esti biz sallandık

Dağıldı bulutlar

Yıldızları topladık

Uyandırmadan seni

Saçlarına taktık

Güneş kıskandı bizi

Kızardı,bozardı

İnadına ufku kararttık

Gece,deniz,rüzgar ve ben

Sımsıkı sarıldık

Gece gitti

Deniz duruldu

Rüzgar dindi

Sen uyanınca mutlu ol diye

Saçına güneşten taç taktık', 'Bak!  Yalnız kaldık Gece,sen ve ben Bulutta çok,yıldızları sayacaktık Sen mızmızlandın Ayaklarını avuçlarına alıp Çekip yorganı üzerine,sakl...', ARRAY['Türk Edebiyatı','Şiir','Ali Gençay']::text[], 8.5, '{"poet":"Ali Gençay","poet_slug":"ali-gencay","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/gece-ruzgar-deniz-ve-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kimsesiz''lik Ne Elîm', 'kimsesiz-lik-ne-el-m-ahmet-refik-tavsanli-v6xwc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kimsesiz gurbetteyim, 

...................................bu diyarda bir elim... 

Kimsesizlik ne acı..! 

...................................kimsesizlik ne elîm... 

Kimsesizler garîptir, 

...................................aman incitmiyelim... 

Kimsesiz etme Rabbim, 

...................................niyâzda iki elim... 

..Ahretahû.. 

28.11.2004 

.Karşıyaka.', 'Kimsesiz gurbetteyim,  ...................................bu diyarda bir elim...  Kimsesizlik ne acı..!  ......................................', ARRAY['Türk Edebiyatı','Şiir','Ahmet Refik Tavşanlı']::text[], 8.5, '{"poet":"Ahmet Refik Tavşanlı","poet_slug":"ahmet-refik-tavsanli","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/kimsesiz-lik-ne-elim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevince Böyle', 'sevince-boyle-ahmet-refik-tavsanli-b485u', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sevince  Böyle… 

