INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cezasını Vereceğim', 'cezasini-verecegim-fatih-konuk-oza3i', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'CEZASINI VERECEĞİM

Bu sefer yakacağım ben çıranı

Her şeylerimi senden alacağım

Dermanı,kurtuluşu ve çareyi

Hepsini bir bir senden alacağım

Kalacaksın dünyada tek başına

Kimse inanmayacak göz yaşına

Dost bildiğin bütün arkadaşıma

Meğer o hayırsızmış diyeceğim

Durduk yere ihanet edişinin

Öylece bırakıp da gidişinin

Herkesin önünde reddedişinin

Bir gün ben cezasını vereceğim

Terk edilip de kalırsan ortada

Bulamayacaksın beni burada

O zavallı haline bu arada

Kahkahalar atarak güleceğim', 'CEZASINI VERECEĞİM Bu sefer yakacağım ben çıranı Her şeylerimi senden alacağım Dermanı,kurtuluşu ve çareyi Hepsini bir bir senden alacağım K...', ARRAY['Türk Edebiyatı','Şiir','Fatih Konuk']::text[], 8.5, '{"poet":"Fatih Konuk","poet_slug":"fatih-konuk","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/cezasini-verecegim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zengin Olsun', 'zengin-olsun-fatih-konuk-6j58f', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'ZENGİN OLSUN

İstemem ne para nede pul

Yeter ki gönlüm zengin olsun

Olayım bir garip fakir kul

Yeter ki gönlüm zengin olsun

Varsın olmasın dikik taşım

Varsın dinmesin bu gözyaşım 

Varsın olmasın üç kuruşum

Yeter ki gönlüm zengin olsun

Gerekmez bana ne taht ne taç

Kimseye olmayım ben muhtaç 

Her gün sokakta gezeyim aç 

Yeter ki gönlüm zengin olsun

Haram parayı ne edeyim

Bir başıma nere gideyim

Düşmanım kim nerden bileyim

Yeter ki gönlüm zengin olsun

............................................................

