INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahara Beş Kala', 'bahara-bes-kala-i-brahim-bayraktar-8x85v', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bereketli günlere gebeydi yarınlar.

Tutunacak dalı kalmayan soğuklar; 

Sinesine çekilmiş nemli topraklar; 

Ölü toprağı serpilmişçesine durgun,

Yufka yüreğiyle, anne şefkatiyle, 

Gelecek baharın yolunu bekliyordu.

Güneşli günlerin özlemiyle yanıyor; 

Binlerce tohuma analık yapıyordu.

Minik bir tohumun inlemeleri duyuldu,

Üzerindeki tonlarca ağırlığın altından.

Yavaşça başını kaldırdı, doğruldu yerinden; 

Bir filiz, bir filiz, bir filiz daha...

Onu gören tüm tohumlar birer birer fışkırdı.

Görücüye çıkmış kız gibiydi,

En güzel elbiselerini giyen dağlar; 

Göğsünde taşıdığı nadide çiçeklerle,

Sevenlerine koşuyordu.

Ninem gözlüklerini aşağı indirmiş,

Gözlüğünün üzerinden bakıyordu,

Toprak, kadın gibidir. Dedi; 

İlgi ister, sevgi ister,

Sevdi mi tam sever,

Ne kadar işlersen, o kadar verir,

Okşadıkça un-ufak olur, erir erir...

Eğer ki bilirsen işin sırrını; 

Sen bir istersin, o, on verir.', 'Bereketli günlere gebeydi yarınlar. Tutunacak dalı kalmayan soğuklar;  Sinesine çekilmiş nemli topraklar;  Ölü toprağı serpilmişçesine durgu...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Bayraktar']::text[], 8.5, '{"poet":"İbrahim Bayraktar","poet_slug":"i-brahim-bayraktar","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/bahara-bes-kala-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Emine', 'emine-fatih-konuk-q4bif', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Telefonda sesini duymak yetmiyor

Seni görmek istiyorum ben emine

Ne yalan söyledimse gönlüm yutmuyor

Seni görmek istiyorum ben emine

Bir gün geleceğim diyorsun ne zaman

Sana geleceğim diyorsun ne zaman

Çıldırmak üzereyim,halimse yaman

Seni görmek istiyorum ben emine

Günden güne daha kötü oluyorum

Yazdığın mesajlarını okuyorum

Her güne gelir diye uyanıyorum

Seni görmek istiyorum ben emine

Seni görmeden öleceğim galiba

Çatır çatır çatlayacağım galiba

Son nefesimi vereceğim galiba

Seni görmek istiyorum ben emine

