INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Göremeseydim Gidişini', 'goremeseydim-gidisini-fatih-konuk-x6j86', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bu gözlerimin önü kararsaydı

Keşke göremeseydim gidişini

Topraklarda üzerime yağsaydı

Keşke göremeseydim gidişini

Ortalığı bir toz toprak sarsaydı

Gözlerimin önü buğulansaydı 

Dumanlarda her yeri kaplasaydı

Keşke göremeseydim gidişini

Gidişinle hayatım son bulsaydı

Bedenim yerin dibine girseydi

Biride gelip beni götürseydi

Keşke göremeseydim gidişini', 'Bu gözlerimin önü kararsaydı Keşke göremeseydim gidişini Topraklarda üzerime yağsaydı Keşke göremeseydim gidişini Ortalığı bir toz toprak sa...', ARRAY['Türk Edebiyatı','Şiir','Fatih Konuk']::text[], 8.5, '{"poet":"Fatih Konuk","poet_slug":"fatih-konuk","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/goremeseydim-gidisini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutuldum Galiba', 'unutuldum-galiba-fatih-konuk-wbpcr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ne zilim çalıyor ne telefonum

Unutuldum,unutuldum galiba

Böyle olmamalıydı benim sonum

Unutuldum,unutuldum galiba 

Önceleri sık sık arardın beni

Önceleri sık sık sorardın beni

Şimdiyse aramıyor,sormuyorsun

Unutuldum,unutuldum galiba

Bilmeyerek üzdü isem ben seni

İstemeyerek kırdıysam ben seni

Her şeylerden çok seni sevdiğimi

Anlamadın,anlamadın galiba

Varımı,yoğumu önüne serdim 

Hayatımı,ömrümü sana verdim

İnan seni ben canımda can bildim

Anlamadın,anlamadın galiba

Küçücük bir hatayı gurur yaptın

Beni bir kalemle neden silip attın

Sana Allah a tapar gibi taptım 

Anlamadın,anlamadın galiba', 'Ne zilim çalıyor ne telefonum Unutuldum,unutuldum galiba Böyle olmamalıydı benim sonum Unutuldum,unutuldum galiba  Önceleri sık sık arardın ...', ARRAY['Türk Edebiyatı','Şiir','Fatih Konuk']::text[], 8.5, '{"poet":"Fatih Konuk","poet_slug":"fatih-konuk","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/unutuldum-galiba-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tülden Şehir', 'tulden-sehir-hakki-hakan-kaya-43o4g', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'yeniden değer 

ellerim denize

karanlıkta gizlenip

öpüşür yakamozlar

kısa bir an 

aydınlanır gözlerim

kaldırırken tozu toprağı 

öfkeli rüzgar

bir masal esintisi duyarım

hayal dünyası hükümdarından

bir parmak 

yaşam çalar dudağıma

dört duvarı yıkılır 

hapishanemin

dolaşır ruhumun saçlarında 

kükürt kokan ellerim

saydam sokaklarından 

yürüdüğüm

asvalt yollarına

çiçek tohumları attığım

karanlık uçurumlarında 

rayikalar çalan

tülden bir şehir 

_____düşlerim', 'yeniden değer  ellerim denize karanlıkta gizlenip öpüşür yakamozlar kısa bir an  aydınlanır gözlerim kaldırırken tozu toprağı  öfkeli rüzgar...', ARRAY['Türk Edebiyatı','Şiir','Hakkı Hakan Kaya']::text[], 8.5, '{"poet":"Hakkı Hakan Kaya","poet_slug":"hakki-hakan-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/tulden-sehir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güneş Taşı''ndan', 'gunes-tasi-ndan-octavio-paz-qpfke', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Anımsama ile yiten yüz,

dokunuşum ile parçalanan el,

bin yıllık gülümseyişler üzerinde

örümcek sürülerinin döndürdüğü saçlar, geçiyor önümden

yola çıkarak alnımdan, arıyorum bir şeyler,

arıyorum istediğimi bulamadan, bir an''ı arıyorum,

fırtınadan yüzler ve şimşek ışıltıları

koşuşuyor gecenin ağaçlarında,

karartılmış bir bahçede, yağmurdan bir yüz,

yanımdan akan acımasız su duruyor,

arıyorum istediğimi bulmadan, tek başıma bunları yazıyorum,

kimse yok burada, ve bitiyor gün,

geçiyor yıllar, o anla birlikte yitiyorum,

derinliklere düşüyorum, aynaların üstündeki

görünmez patikaya, yeniden çıkarıyor o parçalanmış imgemi,

günlerin arasında dolaşıyorum, parçalanmış anlarda,

dolaşıyorum gölgemin düşünceleri arasında,

bir an''ı arayarak, dolaşıyorum gölgemin içinde,

bir kuş kadar canlı, bir an''ı arıyorum,

gözenekli taşın dışıyla tavlanmış

akşamüstü güneşi için:

üzüm salkımlarının olgunlaştırdığı o saat,

ve fışkırarak, kızlar taştı meyveden,

okulun taşlık avlusuna dağıldılar,

uzundu birisi bir sonbahar kadar

ve yürüdü...', 'Anımsama ile yiten yüz, dokunuşum ile parçalanan el, bin yıllık gülümseyişler üzerinde örümcek sürülerinin döndürdüğü saçlar, geçiyor önümde...', ARRAY['Türk Edebiyatı','Şiir','Octavio Paz']::text[], 8.5, '{"poet":"Octavio Paz","poet_slug":"octavio-paz","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/gunes-tasi-ndan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki ''Yüz'' İki Sebep', 'i-ki-yuz-i-ki-sebep-aysel-coban-yyyvq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İçim acıyor,

Yüreğim dağlanmış bir sonbahar akşamında

Yıllar yılgın, beden yorgun

Duygular inkarda

Yüzüm kaçışlarıma tanıklık eder

Ve hayallerimin ortasında bir vurgun izi

Baktıkça,

Her izde ayrı yüzler

Bir yüz,

Dünyaya gelme sebebin

Diğer yüz,

Yaşamı sevme sebebin

İki kayıp ruhumda,

İlk sebep sonsuz uykuda

İkinci sebep yalanların eşiğinde

Biri hiç dönmeyecekken

Diğerinin dönmeye yüzü yok

Bense,

Yalanlar ve gerçekler arasında

Kaybolurum.', 'İçim acıyor, Yüreğim dağlanmış bir sonbahar akşamında Yıllar yılgın, beden yorgun Duygular inkarda Yüzüm kaçışlarıma tanıklık eder Ve hayall...', ARRAY['Türk Edebiyatı','Şiir','Aysel Çoban']::text[], 8.5, '{"poet":"Aysel Çoban","poet_slug":"aysel-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/iki-yuz-iki-sebep-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yazılan', 'yazilan-emine-tansu-qz5e5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kapılar dillerini yutup kilitli kaldılar.

Kollarına değemez soğutamadığım ellerinden gerisi.

Yine bir hüzün ekledim sensiz sokakların gel gidinde, yüzümün çoğalan çizgilerine.

Durmadan ''garip''leşiyorum bu şehirde.

Gizli sokaklar malikanesinin, zengin suratlı koltuk köşelerinde, 

Uyku soluklu, sarhoş sohbetler çarpıyor yüzüme.

Bir lir, neye ağladığını bilmeyerek yamanıyor soysuz adamların ellerine.

Kılıkları hiçbir sureti çağrıştırmayan insanlar arasında, 

yalnızlığımın son perdesini giyiniyorum.

Dişlerimin arasından adın geçmeye yelteniyor, susturuyorlar.

Elimde, ezbere bildiğim bir hikayenin bitlenmiş satırları duruyor, 

”Oku! ” diyorlar,

Susuyorum.

Dilimin ucuna mimlenen bir unutkanlıksın sen.

Ha çıktı, ha çıkacak hesaplarının dengesizliğinde, 

Bir varmış, bir yokmuşlara dönüşeceğinden korktuğum ezbere bir hikaye.

Üzerimde taşıdığım sırıtkan bir huzursuzluk.

Aralarından çıkamadığım kalabalıkların kimsesizliği düşüyor üstüme.

Durmadan ''yalnız''laşıyorum bu şehirde.

Dehşetler bile yavan kalıyor, 

Sensizliğin köküme kibrit suyu salmış lirikliğinde...

İkinci el bir hayat taşıyorum sırtımın nasırlaşmış iskeletinde,

Korsan bir yürek, postal seslerinde aklını kaçıran…

Canımı pazarlarda satalı çok oldu.

Haraç mezat intihar yüklediler kamyonlara, sınırını geçemediler hiçbir ülkenin.

İçinden beni doğuran acıları vurdular sırtlarına, 

Sırtları Artos kadar dayanamadı Nemrut suratlı acılarıma.

Kerbela''da bir cehennem sıcağına bürüdüler düşlerimi,

Çobanaldatanlar izini çoktan kaybettirdi gideceğim yerlerin.

Ortada kaldım.

Yollar Cezayir Çıkmazı.

Bu sarmal nitelikli yorgunlukların defasında,

Biliyorum,

Gidişte, dönüşte yasak bana...

Ruhum, kaypak bir sadakatin sınırlarında buluyor kendini,

Dalgın unutkanlıklar biriktiriyor dirseklerimde, maşa başlarına. 

Yeni yeni anlıyorum.

Şairler yalancıdır! 

Ve “dokuz köy”, onlardan başka kimsenin yaşamadığı bir palavra    uygarlığıdır…

Düşüncelerime empoze edilen bir baldırandan arta kaldı şaşkınlıklarım.

Yakarışları içiyorum avuçlarımdan, senden kurtulabileyim diye.

Seni sevmekten cayıyorum.

Yalan söylüyorum,

Yalan söylüyorum! 

Yalanıma şairler bile çırak kalıyor…

Kendime gelmek için içimdeki çocuğunun yırtık ceplerini çitlembik oyunlarıyla dolduruyorum.

Fener alayına dönüyor yüzüm, gözlerinin esenliğiyle.

Şeytan uçurtmaları asıyorum, doğmamış günün gebe yüzüne.

Selamsız bandoları geçiyor önümden,

Seslerinden çocukluğumu dolduruyorum kaldırımlarda bekleşen konfeti renklerine...

Yine de yerleşik durmuyor sevinç dudaklarımın çeperlerine.

Zili çalınıp kaçılan evlerin kapısı gibi oldum.

Dışarı çıktığımda göreceğim manzarayı biliyorum.

Durmadan ''sensiz''leşiyorum bu şehirde…

Elime, piri olduğum oyunların şehvetinden dolma bir ''ben'' alıyorum.

Sandıklarda barınan geleceğimi hiçe sayarak ve durmadan yalnızlaşarak,

Bakire umutların zırva gümbürtülerini ayaklarımın altına alarak,

Yaşlar biriktirip boğazımın göllerine, burnumun ucunda bir sızı bırakarak,

Yırtık pırtık bir otogar telaşına terk ediyorum beni.

Kimseden cayamadım.

''Ben seni uzaklarda,

Ben seni tuzaklarda, 

Ben seni yasaklarla sevdim,

Ben seni yasaklarla...''

Ve şimdi, 

Yazgımın bahtsızlığında, 

Yazısı okunaksız yazgıma ağıtlar yakıyorum, silinmez mürekkeplerin diliyle.

Çarpılası kapılar bırakarak eleğin üstünde,

Sarılığı sokağı vurmuş yağmur birikintileriyle,

Yazgımın en müşkülpesent yerine terk ediyorum beni.

Kimseden cayamadım.

İçim,

Daim yazılan gibi,

Kendinden geçti yine...', 'Kapılar dillerini yutup kilitli kaldılar. Kollarına değemez soğutamadığım ellerinden gerisi. Yine bir hüzün ekledim sensiz sokakların gel gi...', ARRAY['Türk Edebiyatı','Şiir','Emine Tansu']::text[], 8.5, '{"poet":"Emine Tansu","poet_slug":"emine-tansu","theme":"Türk Şiiri","is_hero":false,"total_lines":74,"source_url":"https://www.antoloji.com/yazilan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Demir Parmaklık Yüreğin', 'demir-parmaklik-yuregin-aysel-coban-c4j3p', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yalnızlık, demir parmaklıkta esir

Sayısız seçenek gözlerinde

Bir el, demir kapıyı açsa

Yalnızlık kanatsız bir kuş

Ahhhh, yine yalnızlık

Ve sen yoksun

Kaçış, özgürlükte hapis

Süresiz bir mekan yüreğin

Yorgun kaçışların dursa

Özgürlük, dönüşsüz bir savaş

Öffff, yine kaçış

Ve yine yenilgi

Kabullenme, bir volkan geçmişe

Geçiş dönemi acılar ruhunda

Gerçekleri kabullensen

İsyanlar kısırlaşmış belleğinde

Offff, yine acı 

Ve aynı yaşantı', 'Yalnızlık, demir parmaklıkta esir Sayısız seçenek gözlerinde Bir el, demir kapıyı açsa Yalnızlık kanatsız bir kuş Ahhhh, yine yalnızlık Ve s...', ARRAY['Türk Edebiyatı','Şiir','Aysel Çoban']::text[], 8.5, '{"poet":"Aysel Çoban","poet_slug":"aysel-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/demir-parmaklik-yuregin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Merhaba Sevgili Gonca Gülüm', 'merhaba-sevgili-gonca-gulum-huseyin-erdogan-3dgc4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'merhaba sevgili gonca gülüm

inan ki sensin benim dünüm

seninle geçiyor bütün günüm

sensin benim düşlerim

yalnızca sensin gülüşlerim

bir gün bile açmasan bana

gülümsemesen sabahıma

bil ki isyan ederim yokluğuna

sakın bana küsme kırılma

her gün rengarenk açıver

kokunu rüzgarlara bırakıver

senden yayılsın yer yüzüne

en güzel kokular

başını kaldır bak gök yüzüne

senin yanında

yıldızlar bile loş kaldılar

                  10.12.2004', 'merhaba sevgili gonca gülüm inan ki sensin benim dünüm seninle geçiyor bütün günüm sensin benim düşlerim yalnızca sensin gülüşlerim bir gün ...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Erdoğan']::text[], 8.5, '{"poet":"Hüseyin Erdoğan","poet_slug":"huseyin-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/merhaba-sevgili-gonca-gulum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hani İstanbul Diyorsun ya', 'hani-i-stanbul-diyorsun-ya-ertugrul-sakar-a7lnj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hani İstanbul diyorsun ya

Emirgan,Kızkulesi

Hani Haydarpaşa''da tren

Eminönü''nde bilet gişesi

Hani yürümek vardı ya boğazda

Hani şehir hatlarıyla bir boğaz turu

Hani Yerebatan Sarayı''nda ışık

Hani Rumeli Hisarı''nda bayraktık

Hani gözlerin yeşil/mavi/kahve

Hani dalgalar kadar rahattık

Hani İstanbul diyordun ya güzelim

Biz o güzellikleri hiç yaşamadık

                       12.08.2001', 'Hani İstanbul diyorsun ya Emirgan,Kızkulesi Hani Haydarpaşa''da tren Eminönü''nde bilet gişesi Hani yürümek vardı ya boğazda Hani şehir hatlar...', ARRAY['Türk Edebiyatı','Şiir','Ertuğrul Şakar']::text[], 8.5, '{"poet":"Ertuğrul Şakar","poet_slug":"ertugrul-sakar","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/hani-istanbul-diyorsun-ya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Yalandın', 'sen-yalandin-tayyip-sag-ewtc4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sevgin gerçek sen yalandın,

Damarımda akan kandın,

Ben bir candım sen canandın,

Hayatımdan çıkıp gittin,

Beni böyle yıkıp gittin.

Aşkımız bir masal oldu,

Acılardan şifa umdu,

Mecnun Leyla''dan ne buldu,

Hayatımdan çıkıp  gittin,

Beni böyle yıkıp  gittin.

Çayır idik çorak olduk,

Nehir idik kurak olduk,

Söyle bu aşktan ne bulduk,

Hayatımdan çıkıp gittin,

Beni böyle yıkıp gittin.

Tayyib''e zulmeden kadın,

İplis mi, şeytan mı adın,

Yaptığından utanmadın,

Hayatımdan çıkıp gittin,

Beni böyle yıkıp gittin.

      08.12.2004', 'Sevgin gerçek sen yalandın, Damarımda akan kandın, Ben bir candım sen canandın, Hayatımdan çıkıp gittin, Beni böyle yıkıp gittin. Aşkımız bi...', ARRAY['Türk Edebiyatı','Şiir','Tayyip Sağ']::text[], 8.5, '{"poet":"Tayyip Sağ","poet_slug":"tayyip-sag","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sen-yalandin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adam', 'adam-evren-dalgic-mdc64', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Zor bir hayata 

adım attık.

Yürüdük dikenli yamaçlara doğru.

Ve ayağımızda hasretin cam kırıkları,

sürüldük bir kasvetli yağmura doğru.

Prangalar vurulmuş ayağıma,

suçum çok sevmek.

Sevmeseydim böyle; 

yanımda olurdun hep. 

Dünyanın kanunu bu,

seversen çekersin.

Taş kalpli olsaydım; 

ben hep gülerdim. 

Madalyalar takıldı

kalbime hasretten.

Elimde rekorlar

günleri bitirmekten.

Sen bir gün gel yeter

bu sinem hazır derde,

sevmeyi bilen adam

öğrendi beklemeyide. 

(Ankara 2002)', 'Zor bir hayata  adım attık. Yürüdük dikenli yamaçlara doğru. Ve ayağımızda hasretin cam kırıkları, sürüldük bir kasvetli yağmura doğru. Pran...', ARRAY['Türk Edebiyatı','Şiir','Evren Dalgıç']::text[], 8.5, '{"poet":"Evren Dalgıç","poet_slug":"evren-dalgic","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/adam-34-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'PERİHAN''A (Akrostiş)', 'peri-han-a-akrostis-muzaffer-erdogan-41k9r', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'P  eri kızı gibisin geldin bana,

E  vet desin diye dua edececeğim yaradana,

R  üyalarımdaki gibisin gönlüme girdin,

İ    nan yanlız dünyama mutluluk getirdin,

H  aydi tut ellerimden güldür yüzümü,

A  llah biliyor söyliyemedim, seviyorum diyen sözümü,

N  ice güzeller gördüm hiçbiri senin kadar yakmadı özümü,

A  llah seninle kapamayı nasip etsin o iki gözümü......''', 'P  eri kızı gibisin geldin bana, E  vet desin diye dua edececeğim yaradana, R  üyalarımdaki gibisin gönlüme girdin, İ    nan yanlız dünyama ...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Erdoğan']::text[], 8.5, '{"poet":"Muzaffer Erdoğan","poet_slug":"muzaffer-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/perihan-a-akrostis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bıraktım Yüreğimi...', 'biraktim-yuregimi-melek-ayaz-lxzvd', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Nerden geliyor bu yabancı Acılar,

Sular gibi, çıplak kayalara çarparak,

Uğramış Yüreğimize bir kez bağbozumu,

Acıyla yaşamak ne kötü, çekip gidememek,

Bıraktım yüreğimi esir olsun bir yalanla,

O güzelim düşlerle gözlerine dalsın da,

Uyuyup kalsın gölgesinde kirpiklerinin,

Gün olur öç ateşten çağrısını çalar da,

Sürgünlerde gibi başını alıp gidersin ya,

Hani korkuyla düşüp ardına güneşlerin.? 

Sıcağında üşürsünya, karda sevgiyle ısınırsınya,

Bir çırpıda anlatmak istersin ya o zaman,

Savaşırdı sözcükler kalemimden dökülürken,

Bıraktım yüreğimi varsın esir olsun bir yalanda.', 'Nerden geliyor bu yabancı Acılar, Sular gibi, çıplak kayalara çarparak, Uğramış Yüreğimize bir kez bağbozumu, Acıyla yaşamak ne kötü, çekip ...', ARRAY['Türk Edebiyatı','Şiir','Melek Ayaz']::text[], 8.5, '{"poet":"Melek Ayaz","poet_slug":"melek-ayaz","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/biraktim-yuregimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ardından', 'ardindan-oner-bagceci-2lcaj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'aydan, güneşten, yada bilcümle senden

ne geldiyse dilime

görünüp kaçtılar. sanki kaçaktılar.

sütten kesilen gündüz,

aynada akşamı gördü.

yazmak kangırendi. nasılda aktı içime.

şimdi şu vapurun benden farkımı kaldı.

gitti deniz oldu. sinemde izi kaldı.

bırakın bir çay bahçesinde otursun,

beklesin zaman beni.

kağıttan o martı 

çığlık çığlığa boşlukta kaldı.

sen, çarkına yandığım vapur,

çıkma karaya denizinde dur.

ama ellerim emekçi,

yüreğim çingene ise

geldiğinde, limana üç kere vur.', 'aydan, güneşten, yada bilcümle senden ne geldiyse dilime görünüp kaçtılar. sanki kaçaktılar. sütten kesilen gündüz, aynada akşamı gördü. yaz...', ARRAY['Türk Edebiyatı','Şiir','Öner Bağçeci']::text[], 8.5, '{"poet":"Öner Bağçeci","poet_slug":"oner-bagceci","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ardindan-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dargın', 'dargin-oner-bagceci-8pp2v', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'telefon çaldı. Keşke zil mi çalsaydı? 

belki bir harf getirirdi çocuklar.

bende kalmadı. lal gibiyim.

olursa boynuna dizilsin sözcükler.

darıldım ve öyle çok sustum ki geceye

artık ne ses, ne dilimde bir söz yanar.

kendisini taşıyan tabut gibiyim.

şimdi nereye gelirse gelsin bahar.

(17 Mart 2004)', 'telefon çaldı. Keşke zil mi çalsaydı?  belki bir harf getirirdi çocuklar. bende kalmadı. lal gibiyim. olursa boynuna dizilsin sözcükler. dar...', ARRAY['Türk Edebiyatı','Şiir','Öner Bağçeci']::text[], 8.5, '{"poet":"Öner Bağçeci","poet_slug":"oner-bagceci","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/dargin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ay Düşlere Dalıyor...', 'ay-duslere-daliyor-melek-ayaz-gfbet', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dalıyor düşlere bu akşam ay daha bitkin,

Sevgisiz kalmış bir kadın gibi yastıkların üstünde,

Okşuyor yıldızlar dalgın dalgın uyumadan önce,

Süzülüyor gözlerinden ap ak düşler avuntuyla,

Düşüyor solgun bir damlacık gözyaşı gizlice,

Alıyor eline solgun damlacığı ap ak düşlerle,

Koyuyor gönlüne güneşin gözünden uzak sevgiyle,

Sevdiğim yanlız sen, sevdiğimi bilende sen,

Hep özlediğim bir tını olacaktı sesinde yine,

Uzaklığa yenik düşecek, sevmek beklemek olacaktı,

Bir hüzün daha düşecekti sevdama dalga dalga,

Sözcükleri yıkıp geçecekti, dilim kocaman olacaktı,

Sesini duyacaktım ve yeni bir yolculuk daha başlayacaktı,

Kar tanelerinin içime ağır ağır düşmeye başladığında,

Dizelerim ters yüz olacaktı aklımda, perişanlık içinde,

Kendimi bir kez daha sorgu sandalyesine oturtacaktım,

Çağıracaktım işkencelerimin en yeteneklisini,

Yılları toplayıp imzaları çıktığı anlıma bakacaktım,

Tanışmak zorunda kalacaktım gözbebeklerime düşen hüzünle,

Dalıyor düşlere bu akşam ay daha da bitkin yorgun,

Sevgisiz kalmış bir kadın gibi yastıkların üstünde.', 'Dalıyor düşlere bu akşam ay daha bitkin, Sevgisiz kalmış bir kadın gibi yastıkların üstünde, Okşuyor yıldızlar dalgın dalgın uyumadan önce, ...', ARRAY['Türk Edebiyatı','Şiir','Melek Ayaz']::text[], 8.5, '{"poet":"Melek Ayaz","poet_slug":"melek-ayaz","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ay-duslere-daliyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dünya Gözü İle', 'dunya-gozu-i-le-huseyin-sigirtmac-ka8ym', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Baharı beklerken kış geldi başa.

Yürek dayanır mı gözdeki yaşa? 

Her efkar saplandı çıkmıyor döşe.

Derdimin dermanı olacak mısın? 

Yoruldu duygular gurbet elinde.

Leyla’dan uzağım Mecnun çölünde.

Nefesim tükenir günün birinde.

Rüzgar gibi esip erecek misin? 

Uzaktır aramız varlığın hayal.

Elimde kalıyor tuttuğum her dal.

Sonu çıkmazlarda gittiğim her yol.

Peşimden izimi sürecek misin? 

Sığırtmaç şifa yok hasret yarama.

Kışlar mekan kurdu gönül ovama.

Öbür taraf kayıp bilemem ama.

Dünya gözü ile görecek misin?', 'Baharı beklerken kış geldi başa. Yürek dayanır mı gözdeki yaşa?  Her efkar saplandı çıkmıyor döşe. Derdimin dermanı olacak mısın?  Yoruldu d...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Sığırtmaç']::text[], 8.5, '{"poet":"Hüseyin Sığırtmaç","poet_slug":"huseyin-sigirtmac","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/dunya-gozu-ile-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlâç Sabır...', 'i-l-c-sabir-i-brahim-ethem-bingul-ryst6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bazı sevgiler yalnız, bazı sevgiler yapay

Sevgilerin içinde bazıları güneş, ay

Sevenler sevgisini aşka etmeli saray

Yörüngesi olmayan günler kaybolacaktır...

Bazı acılar buruk, bazı acılar zehir

Acıların içinde bazıları panzehir

Sevenler, acılara tahammülle bilinir

Acıyı tatmayan gün takvimde solacaktır...

Bazı hastalar bitkin, bazı hastalar garip

Hastaların içinde bazıları muzdarip

En iyi ilâç sabır; zaman en iyi tabip

Sağlığını özleyen sağlığı bulacaktır...

www.iebingul.com', 'Bazı sevgiler yalnız, bazı sevgiler yapay Sevgilerin içinde bazıları güneş, ay Sevenler sevgisini aşka etmeli saray Yörüngesi olmayan günler...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ilac-sabir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Böcek Yok...', 'bocek-yok-melek-ayaz-vna5n', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ne hoş olurdu,

Bu geceye aksaydı yıldızlar,

Dalıyorum boşluğa,

Ve karanlığın çıplaklığına,

Bir şimşek patlıyor biraz aydınlık,

Sonra karanlık başlıyor gecede,

Herşey zamanın yeyip bitirdiği,

Yokluga bürünüyor acımasızca,

O çocuksu sevilerde oralarda,

Koca gövdeme bakıyorum,

Açık yaralarımdan çok şey sızıyor içeri,

Ve eskiden ağlardım istediğim zaman,

Oysa göz yaşlarımı bile kuruttu yanlızlığım,

İstersem güneşi indirebilirdim toprağa eskiden,

Oysa şimdi yıldızlar bile takmıyor beni,

Gölgemde onlarca kanat gererdim canlıya,

Güçlü kollarımla sarardım sevdiklerimi,

Şimdilerde kuşlar bile uğramaz oldu,

Kısa süre kalıp, başka diyarlara kanat çırparlar,

Eskiden akşamdan sabaha sarardım yaralarımı,

Şimdi küçük darbeler, günlerce uğraştırıyor beni,

Artık verecek birşey kalmadığını onlarda biliyor,

Dallarım ıssız, yapraklarımda eskisi gibi böcek yok,

Gövdem yaralar içinde, köklerim daha sık uyarıyor beni,

Ve çok üşüyorum,ne hoş olurdu,bu geceye yıldızlar aksaydı.', 'Ne hoş olurdu, Bu geceye aksaydı yıldızlar, Dalıyorum boşluğa, Ve karanlığın çıplaklığına, Bir şimşek patlıyor biraz aydınlık, Sonra karanlı...', ARRAY['Türk Edebiyatı','Şiir','Melek Ayaz']::text[], 8.5, '{"poet":"Melek Ayaz","poet_slug":"melek-ayaz","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/bocek-yok-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'At Gitsin', 'at-gitsin-aynur-baydar-dvgcb', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Valla billa camı ben kırmadım

Korku yalanı

Canım karım, senden başkasını gözüm görmez

Yalan yalanı

Yavrucum pembe panjurlu evimiz olacak

Pembe yalanı

Biz şeyi, şey etmiştik aslında

Ivıran kıvıran yalanı

Sensiz ölürüm, dön bana

Yakarış yalanı

Memur bey sarhoş değilim

Yanlayan yalanı

Ben büyük adamım be 

Yanılan yalanı

Çocuğum sen o sümsükten daha akıllısın

Yanlış yalanı

Bu markayı kullanırsa 

Aha böyle mutlu olur, havalara zıplarsın

Reklam yalanı

Ah şekerim, paran için değil, sevgimden…

Kıvrılan yalanı

Ah inanmam yaşınızı hiç göstermiyorsunuz

Teselli yalanı

Ülkemizi refaha çıkarıcaz

İşsizliği azaltıcaz…

Politika yalanı

Abicim bizim takım şöyle böyle yapaydı şampiyon olurduk

Kahve deki işsiz fanatiğin karın doyurmayan yalanı

Bizim parti iktidara gelse düzlüğe çıkarız

Avunma yalanı 

Özgürlük medeniyet için savaşıyoruz

Sam amca yalanı

Ülkem, canım milletim, devletim, dinim

Hep yerim, çıkar yalanı

Biz bölücü değiliz

Sadece insan, azınlık, inanç hakları…

Yılanların, kara yalanı

Şair miyim neyim

Aynurun yalanı', 'Valla billa camı ben kırmadım Korku yalanı Canım karım, senden başkasını gözüm görmez Yalan yalanı Yavrucum pembe panjurlu evimiz olacak Pem...', ARRAY['Türk Edebiyatı','Şiir','Aynur Baydar']::text[], 8.5, '{"poet":"Aynur Baydar","poet_slug":"aynur-baydar","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/at-gitsin-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geçiyoruz bu yol geçen handan', 'geciyoruz-bu-yol-gecen-handan-i-brahim-duskun-dqj1n', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'sıra bizim geçiyoruz

bu yol geçen handan

haberin varmı zamandan

kaç gün akşam oldu

kaç gece sabah

umutlar kürektir 

çektikçe çeker

bu sandal gibi handa

sermayemiz olandan

saniye,dakika,saat

gün,hafta,ay

nice yıllar

bir an gibidir zaman

hiç durmadan akan

o tatlar,o hazlar

geçermi dediğimiz

yürek dağlı acılar

yaşamadık sanki

geçen biz değilmiydik 

bu yol geçen handan

bir kaç resim

bir kaç dize

kalan o anılardı bize.', 'sıra bizim geçiyoruz bu yol geçen handan haberin varmı zamandan kaç gün akşam oldu kaç gece sabah umutlar kürektir  çektikçe çeker bu sandal...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Düşkün']::text[], 8.5, '{"poet":"İbrahim Düşkün","poet_slug":"i-brahim-duskun","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/geciyoruz-bu-yol-gecen-handan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Dekor Antalya''dır Mutlak', 'bu-dekor-antalya-dir-mutlak-can-ceylan-0jaqe', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Şimdi çocukluğum kadar özlediğim anlamda

Meltemlerin güç yetiremediği bir sahil

Bütün renkleri, ümitleri avucunda tutar

Aşksızlık ve korkuları değil

Burda ayrılık şarkıları bestelenmemiştir hiç

Yaşanmamıştır arzuklayışların hırçınlığı

Bilmem nice mesafelerden kopar geliverir

Ümitlerinizi besleyen dalgaların çığlığı

Tanrım bahar vermiştir cümle renkleriyle

Acılı insanlarım arınır süslerinde

Ne şiire ne şarkılara sığmayan süresiz mevsimler ki

Renge doymayan bir aşk çırpınır göğüslerinde

Güneş bütün, ay bütün doğar yaşantılara

Yıldızlar hele onları deniz ve bu sahil anlatsın size

Dağlardan çağlayanlardan gizli gizli

Her gün bir mutluluk iner denize

Zeki Ceylan', 'Şimdi çocukluğum kadar özlediğim anlamda Meltemlerin güç yetiremediği bir sahil Bütün renkleri, ümitleri avucunda tutar Aşksızlık ve korkula...', ARRAY['Türk Edebiyatı','Şiir','Can Ceylan']::text[], 8.5, '{"poet":"Can Ceylan","poet_slug":"can-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bu-dekor-antalya-dir-mutlak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul Leşi', 'i-stanbul-lesi-emine-tansu-rivt4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Önce saçlarımdan tutuşmaya başladı,

Belleğimden sökülen tahtaların arasında kaynayan hamamböceklerinin istilacı alaturkaları.

Bozuk bir şubat, eksik bırakılan tüm ayları tamamlıyordu.

Nasıl oldu anlamıyorum.

Yapış yapış bir ikindi arefesinin soğuk ve dingin parmak uçları, avuçlarımdan adım adım bir heyelan seferber etti.

Mola yerleri soğuktu.

Ve ben o zaman, şimdikinden daha korkaktım.

Başımda esecek bir İstanbul''un, manidar bir eylemsi niteliğinde yeller taşıyacağını bilmiyordum dallarıma, hem de kavaktan.

İstanbul başımda, başım dallarda, dallar rüzgarda...

Ki deniz, İstanbul kadar özlemdi, martıların gümüş rengi yemiş kanatlarının yorgunluğunda.

Sade bir ateş düştü, paçavralarından soyunan esmer suratlı yalnızlığımın, kır düşlü kışına.

Sanırım o zamandan beri yakıyorum, elimden düşüremediğim notaların ürkek bir porte üzerinde durakalan anlamlarını.

Kimse bilmez.

Her bir ''es'', susacağın zamanların intikam vaktinden önce dolanır diline.

Ve ezbere bildiğin şarkıları, bir akordeon körüğüne takılan parmakların kıvılcımında unutuverirsin.

Bildiklerin es olur, bildiklerin iki vuruşluk sus...

Beni sırtımdan vur! 

Bilmediklerimi, sırtımdan sus! 

Kıy bütün aysberglerin canına. Ki senden daha soğuk durmuyorlar bu uçsuz koridorların boşluğunda...

Yelkovan kaç kez parçalanırdı akrebin etrafında, soylu içerikler edinerek? 

Ya da akrep ne kadar beklerdi onu, belli etmeyerek, asil ısırıklarından sıyrılmış gecede.

Umurunda olmadığını sansa da yelkovan; akrep onsuz, bir ''hiç''e delalet ediyordu.

Ve ikisinin de elinden bir şey gelmiyordu.

Akrep, yelkovansız... Zaman zamansız... Sürünüyordu.

Bu sürüngeç zamanın perişan kollarında, tuhaf iksirlerin başımı kahreden travmalarına yüksünmeye başlıyordum.

Gözüm nereye baksa, kör duruyordu kekeç çan seslerinden kalan duvarların suskunluğu.

İsli sonbaharlar türüyordu adımlarımda, karşılığı imkanlı aşklar...

Bavulumdan sarkan alaycı ip cambazları, ilmeklerini sökmeye çalışıyorlardı, logar kapaklarında tökezleyen mumya kelebeklerin. 

İstasyonlarda bütün saatler durgundu... 

Yasaklardan çalıntı bir aşkın masum kaçaklığını, izbe tarihlere düğmeleyerek sezinliyordum içimde.

''Ben ki, belki... Sevdim, amansız sevdim...''

Ve sana geldim... Uğramadığım yerleri kalmadı kaza paslı kötücül garların...

Sonra... Boz sabahlarında yalın hikayeleri kaldı kentlerin.

Sokakları boşaltılmış, karanlıkları alınmış, cinlerin bile eyvallah etmediği kırık sabahları.

Erguvan renkli bir hücum boşaldı gözlerinden başlayan dünyaya.

Bir ben kaldım, bir de yarım bırakılan ne varsa içimden söylediğim.

Karanfil sokağında kuşları astılar sonra birer birer.

Çığlıkları sorgusuz bırakıldı, cehennem ateşinde kanayan canlarının mayasız kefaletine.

Karanfil sokağında bir sabah, gözlerini astılar...

Hiç bu kadar erken bastırmamıştı akşam sinirlerime.

Yazık ki,

Ve ne kadar yazık ki, seni çıkabileceğim yokuşları bile kaldırmıştı belediye işçileri, çöp tankerlerinin tekerine.

Bana kalan, bıçkın bir seremoni sunmaktı, bükülen dağların eğreltilerine, koşulsuz...

Artıkların bile çoğalabileceği yığınaklar varken leş tepelerinde, 

Ben neden bu kadar yalnızım? 

Hem de seninle.

Varsın, yoksun olsun suratımın ilgeçleri yine, 

Varsın, yoksun olsun tepinip duran yüreğim senden.

Varsın, yoksun... Varsın ve yoksun işte! 

Seninle yalnızım... Yalnızlığım seninle...

Bir sabahın, ardına düşülmez artığıyım ben.

Şimdi yanımda olsan, yine eksik kalır gözlerimin dalgınlıkları.

Ertelediklerimiz; bir sen, bir benden ibaret işte.

Kısır döngünün, kısırlaşmayan emaresi.

Sen, bendeki ''sen''i; ben, sendeki ''ben''i, moral ötesi bir aleme götürürken, 

''Başucumda Müzik'' kifayeleniyordu, iklimlerin öğle vaktine değip kaçan sıcaklığında.

Bozgun yedim, içerledim, durdum...

Yanağımdaki otobüsü, bir mendilde unuttum.

Ve otobüsten inerken, bir hamalın sırtına vurdum bütün yükümü.

''Bu kadar mı? '' dedi ve sustu; bakışlarının uykusuz, esnemeye meyilli, efendi varoşluğunda.

Kitabı ona verdim.

İçimden bir sen akıyordu.

''Başucumda Müzik'' onun sırtında susuyordu.

Ve ben, zamanın ayrılığında yine,

''Seni sevmek için bir neden bulamıyordum...''', 'Önce saçlarımdan tutuşmaya başladı, Belleğimden sökülen tahtaların arasında kaynayan hamamböceklerinin istilacı alaturkaları. Bozuk bir şuba...', ARRAY['Türk Edebiyatı','Şiir','Emine Tansu']::text[], 8.5, '{"poet":"Emine Tansu","poet_slug":"emine-tansu","theme":"Türk Şiiri","is_hero":false,"total_lines":65,"source_url":"https://www.antoloji.com/istanbul-lesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerin', 'gozlerin-deniz-karakaya-oevay', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Güzel gözlerin anlatır

Bazen bana bir çok  şeyi 

Sözlerinden ziyade....

Artık uzayan yollara ne dost olmak,

Ne yoldaş olmak ne de  sitemkar 

Kalmak istemiyorum.

Parlak bir yıldız bulmuş gibi

Etrafında çocuk kalbimle dönüyorum.

Ara sıra buğday başaklarının kokusunu özlüyorum

Artık akşamları sırf tütün içiyorum.', 'Güzel gözlerin anlatır Bazen bana bir çok  şeyi  Sözlerinden ziyade.... Artık uzayan yollara ne dost olmak, Ne yoldaş olmak ne de  sitemkar ...', ARRAY['Türk Edebiyatı','Şiir','Deniz Karakaya']::text[], 8.5, '{"poet":"Deniz Karakaya","poet_slug":"deniz-karakaya","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/gozlerin-135-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dörtlük', 'dortluk-abdullah-uslu-58oi9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hasret uçar geceleri karanlığa doğru kuşlar,

Çırpınır,kanat vurur,semalara doğru kuşlar.

Yorulunca başlayan öyle bir iniştirki; 

Kaybolur silinirler, sonsuzluğa doğru kuşlar', 'Hasret uçar geceleri karanlığa doğru kuşlar, Çırpınır,kanat vurur,semalara doğru kuşlar. Yorulunca başlayan öyle bir iniştirki;  Kaybolur si...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Uslu']::text[], 8.5, '{"poet":"Abdullah Uslu","poet_slug":"abdullah-uslu","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/dortluk-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dostum Ol Güzel...', 'dostum-ol-guzel-hayrettin-orak-70jtw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Çekemem artık aşkın cefalarını,

Yaşayamam ayrılığın hüsranlarını,

Kaldıramaz yüreğim acılarını,

Gel sevgilim olma, Dostum ol Güzel....

Aşktan söz edip, deşme yaramı,

Tövbeliyim sevmeye, kesme yolumu,

İçirme bana aşkın zehir suyunu,

Gel sevgilim olma, Dostum ol Güzel...

Uyandım kabus dolu rüyalarımdan,

Beklentim kalmadı''ki yarınlarımdan,

Ölsemde içmem artık kevser suyundan,

Gel sevgilim olma, Dostum ol Güzel...

Dost kanayan yarama olur merhemim,

Paylaşır dertlerimi olur tesellim,

Gün olur bu dünyadan göçer giderim,

Gözüm açık koma, Dostum ol Güzel.......! 

10.12.2004', 'Çekemem artık aşkın cefalarını, Yaşayamam ayrılığın hüsranlarını, Kaldıramaz yüreğim acılarını, Gel sevgilim olma, Dostum ol Güzel.... Aşkta...', ARRAY['Türk Edebiyatı','Şiir','Hayrettin Orak']::text[], 8.5, '{"poet":"Hayrettin Orak","poet_slug":"hayrettin-orak","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/dostum-ol-guzel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hançerinle...', 'hancerinle-melek-ayaz-fg1v3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir sana tutulmuşum,

Böyle geceler boyu,

Yüreğimin sessiz sevgisi,

Sen gecelerimin sesi,

Acılarımın en amansızı,

Yığıyorsun içime sevgini,

Değiştiremem gecelerimi,

İster kara gece ol,

İstersen gün doğumu,

Severim seni böylece,

İster sev beni gönlünce,

İstersen vur sevgideki hançerinle,

Değiştiremem gecelerimi,

Severim seni böylece,

Bir sana tutulmuşum ben.', 'Bir sana tutulmuşum, Böyle geceler boyu, Yüreğimin sessiz sevgisi, Sen gecelerimin sesi, Acılarımın en amansızı, Yığıyorsun içime sevgini, D...', ARRAY['Türk Edebiyatı','Şiir','Melek Ayaz']::text[], 8.5, '{"poet":"Melek Ayaz","poet_slug":"melek-ayaz","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/hancerinle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni', 'beni-ali-seyh-ozdemir-azndq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kalbur edip yüreğinde                                                                                      

Ele beni, ele beni...                                                                                               

Bebek gibi beşiklerde                                                                                       

Bele beni, bele beni... 

Yüreğimi yakıp pişir,

Ferhat gibi dağlar aşır.

Âlemin içinde düşür

Dile beni, dile beni...                                                                                    

Sırlarımı deme yâda,

Denizimde sen ol ada.

Muhtaç etme bu dünyada

Kula beni, kula beni...

Dakka dakka, saat saat

Kalbimi sana ayarlat.

Usanırsan pazarda sat	

Pula beni, pula beni...', 'Kalbur edip yüreğinde                                                                                       Ele beni, ele beni...           ...', ARRAY['Türk Edebiyatı','Şiir','Ali Şeyh Özdemir']::text[], 8.5, '{"poet":"Ali Şeyh Özdemir","poet_slug":"ali-seyh-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/beni-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Gelmeden', 'sen-gelmeden-mehmet-demirkapi-u64rt', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen daha gelmedin bu odaya.

İlk kez geleceksin.

Bütün aile seni bekler,

Komşular seni.

Uzaktakiler seni bekler.

Yakınlar seni.

Sen nerdesin? 

Biliyorum.

Bu evdesin,

Çok yakınımdasın.

Ama henüz yoksun.

Hatta her gece benimle yatarsın,

Hatta çok kez seninle karşı karşıya kaldık.

Gözlerine bakamadım.

Gözlerimi görmedin sen,

Saçlarımı okşamadın henüz,

Ama sevgin hep içimde.

Ellerimi uzattım, tut ellerimi.

Bana dokun, tenini kokunu duyayım.

Henüz erken diyorsun,

Evet, ama sabırsızlanıyorum.

Seninle tanışmadık bile,

Gözlerimi görmedin,

İçine hiç bakmadın.

Bir görsem, görebilsem diyorsun.

Beni seviyorsun.

Hasretlik yeter mi? 

Beklemek güzel seni,

Elbette geleceksin.

Gelmen gerektiği an,

Yolların açıldığı,

İzinlerin çıktığı an.

An o an! 

Hazırlıklar tamam şimdi.

Seni odada görmeyince yerinde,

Hissetim.

Gelişin yakın.

Seslerini duyuracaksın.

Bakışların, bence çok önemli

Gülüşün nasıl olacak? 

Ağlama,

Kavuşmak vakti yakın.

Sen bize kavuşacak,

Biz de sana.

Belki ilk anda sarılamayacaksın,

Meraklanma,

Ben sana iyi sarılırım.

Kokunu özledim,

Sıcaklığını,

Tenini özledim.

Sevdan güzeldi.

Ne zaman başladı bilsen? 

Sen iki yüz otuz dokuz

Evet, evet

Sen tam iki yüz otuz dokuz gramken.

                                                      

İzmir 13.04.1999', 'Sen daha gelmedin bu odaya. İlk kez geleceksin. Bütün aile seni bekler, Komşular seni. Uzaktakiler seni bekler. Yakınlar seni. Sen nerdesin?...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Demirkapı']::text[], 8.5, '{"poet":"Mehmet Demirkapı","poet_slug":"mehmet-demirkapi","theme":"Türk Şiiri","is_hero":false,"total_lines":56,"source_url":"https://www.antoloji.com/sen-gelmeden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Hayırlı İşte Afyon', 'her-hayirli-i-ste-afyon-ertugrul-sakar-9xvga', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Frig gibi,Hitit gibi  antika

Bağrımda bir kaya,bir dağ

Ulaşılmaz baş döndüren patika

Bir kale dimdik,dünya durdukça her çağ

Türkiye gelir geçer üstünden

Bembeyaz güler yüzlü otogar

Savaş ve barış tren demektir

Tarih kitabı gibi bir gar

Ah kaymaklı lokum,ah kaymak

Afyon et kokar, sucuk kokar

Arı kovanı gibi esnaf,arı

Yüzyıllardır mermer doğrar

Her makus talihi millet

Afyon''dan yakar,yıkar

Hürriyetin yüreğidir vuran

Zafertepe,Anafartalar

Köylüler,çalışkan köylüler

Alınteri bereket örülmüş duvar

Ya sanayi,yükselen bacalar

Daha güzele,iyiye yarış var

Tertemiz yollar,parklar,sokaklar

Afyon yeşillik,nazlı bir yar

İlçeleri iri yarı,gelişmiş

Her biri bir şehir çok bahtiyar

Anadolu deyince uzat elini

En eski çağlara kadar

Her taşın altından,her hayırlı işte

İnanın Afyon çıkar

                          1998', 'Frig gibi,Hitit gibi  antika Bağrımda bir kaya,bir dağ Ulaşılmaz baş döndüren patika Bir kale dimdik,dünya durdukça her çağ Türkiye gelir ge...', ARRAY['Türk Edebiyatı','Şiir','Ertuğrul Şakar']::text[], 8.5, '{"poet":"Ertuğrul Şakar","poet_slug":"ertugrul-sakar","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/her-hayirli-iste-afyon-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öylesine', 'oylesine-recep-gedikoglu-7dsm8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Öylesine sevdim ki seni güzelim,

Deli divane olurcasına,

Öylesine çok sevdim ki seni,

Kerem le Mecnun''a gülercesine

Öylesine çok  sevdim ki seni güzelim,

Kızgın çölde suyu ararcasına,

Öylesine çok sevdim ki seni,

Bulunan suyu kana kana içercesine.

Öylesine çok sevdim ki seni güzelim,

Hiç tereddüt etmeden uğrunda ölürcesine,

Öylesine çok sevdim ki seni,

Tanrıdan cenneti DİLERCESİNE

                                                           15.02.2002', 'Öylesine sevdim ki seni güzelim, Deli divane olurcasına, Öylesine çok sevdim ki seni, Kerem le Mecnun''a gülercesine Öylesine çok  sevdim ki ...', ARRAY['Türk Edebiyatı','Şiir','Recep Gedikoğlu']::text[], 8.5, '{"poet":"Recep Gedikoğlu","poet_slug":"recep-gedikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/oylesine-41-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Derin Yüreklere...', 'derin-yureklere-melek-ayaz-3xype', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir liman görürüm,

Yelkenler, kürekler dolu,

Az önce yorgun düşmüş,

Denizin dalgalarından,

Azgın dalgalarıyla denizin,

Yorgun düşen yelkenli gibi,

Rüzgarla arkadaş olurum,

Konuşurum kara bulutlarla,

Ardından göç eden kırlangıçlar,

Alır beni benden büğülü sürüsüyle,

Dalgaları durdurmak, bulutları itelemek,

Gün batımı rengini gözlerime doldurmak,

Acılarımı deşip kendimi öldürmek istedim,

Derin yüreklere gereken uçurumlarca.', 'Bir liman görürüm, Yelkenler, kürekler dolu, Az önce yorgun düşmüş, Denizin dalgalarından, Azgın dalgalarıyla denizin, Yorgun düşen yelkenli...', ARRAY['Türk Edebiyatı','Şiir','Melek Ayaz']::text[], 8.5, '{"poet":"Melek Ayaz","poet_slug":"melek-ayaz","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/derin-yureklere-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üç Kafadar', 'uc-kafadar-zeki-ergin-49vys', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'yıl 1968

aylardan mayıs

üç kafadar söyleşiyoruz

orman parkında

ne olacak bu memleketin hali

diyor İsmail

ekliyor Ahmet

sömürüsüz

yaşanabilir bir dünya

barış içinde

ustalardan 

şiirler okuyor İsmail

sonrasında Ahmet

gür sesiyle

Drama köprüsü dardır geçilmez diyor

ardından

peynir domates ekmekten oluşan 

öğle yemeğine başlıyoruz

_erenköy may04

_dağlara ver sırtını yt:haz09', 'yıl 1968 aylardan mayıs üç kafadar söyleşiyoruz orman parkında ne olacak bu memleketin hali diyor İsmail ekliyor Ahmet sömürüsüz yaşanabilir...', ARRAY['Türk Edebiyatı','Şiir','Zeki Ergin']::text[], 8.5, '{"poet":"Zeki Ergin","poet_slug":"zeki-ergin","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/uc-kafadar-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırlangıçlar...', 'kirlangiclar-melek-ayaz-2e1qz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir liman görürüm,

Yelkenler, kürekler dolu,

Az önce yorgun düşmüş,

Denizin dalgalarından,

Azgın dalgalarıyla denizin,

Yorgun düşen yelkenli gibi,

Rüzgarla arkadaş olurum,

Konuşurum kara bulutlarla,

Ardından göç eden kırlangıçlar,

Alır beni benden büğülü sürüsüyle,

Dalgaları durdurmak, bulutları itelemek,

Gün batımı rengini gözlerime doldurmak,

Acılarımı deşip kendimi öldürmek istedim,

Derin yüreklere gereken uçurumlarca.', 'Bir liman görürüm, Yelkenler, kürekler dolu, Az önce yorgun düşmüş, Denizin dalgalarından, Azgın dalgalarıyla denizin, Yorgun düşen yelkenli...', ARRAY['Türk Edebiyatı','Şiir','Melek Ayaz']::text[], 8.5, '{"poet":"Melek Ayaz","poet_slug":"melek-ayaz","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/kirlangiclar-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki Kumru', 'i-ki-kumru-bekir-mutlu-gokcesu-g6xml', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İki kumru

Bir telde

Bir cilve, bir cilve...

Ne avuçta var

Ne elde...

Baktılar şöyle bir 

Dünyanın hallerine

İyice sokuldular

Birbirlerine...', 'İki kumru Bir telde Bir cilve, bir cilve... Ne avuçta var Ne elde... Baktılar şöyle bir  Dünyanın hallerine İyice sokuldular Birbirlerine......', ARRAY['Türk Edebiyatı','Şiir','Bekir Mutlu Gökçesu']::text[], 8.5, '{"poet":"Bekir Mutlu Gökçesu","poet_slug":"bekir-mutlu-gokcesu","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/iki-kumru-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eğer', 'eger-recep-gedikoglu-6eczd', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Beklemek,umutla çok güzel birşey,

Günler ay, aylar yıl, yıllar bitmese bile,

Bunca geçen zamanın hepsine bile değer

Beklenen çıkıp geleckse bir gün eğer.

Sevmek, çok güzel birşey elbet,

Sonunda bitmez dertlere düçan olunsa bile,

Netice hiç mi hiç önemli değil,

Sevilen. bir gün gelip sevecekse eğer.

Çekilen çile,katlanılan dertler hiç önemli değil,

Umutlar bir gün yeşermeye yüz tutacaksa eğer,

Çekilen cehennem azabı olsa da değer,

Sevilen, kıymet bilip takdir edecekse eğer.

                                                                     28.10.2001', 'Beklemek,umutla çok güzel birşey, Günler ay, aylar yıl, yıllar bitmese bile, Bunca geçen zamanın hepsine bile değer Beklenen çıkıp geleckse ...', ARRAY['Türk Edebiyatı','Şiir','Recep Gedikoğlu']::text[], 8.5, '{"poet":"Recep Gedikoğlu","poet_slug":"recep-gedikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/eger-45-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nat Değil BİAT-10', 'nat-degil-bi-at-10-habip-sabanli-ji09b', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gecenin sabaha selam vermesiyle,

Gözlerim seni arıyor Sultan Ahmet''te.

Tarihi mekanlarda senin hayalin,

Seni bulmakmış benim kaderi.

Bilmem bu kaçıncı şiirim.

Hep dünyevi şiirler yazdım.

Ama seni sonunda buldum.

Alemlere rahmet olmak için geldin.

Ey gönlümün sultanı, Bedir''in kahramanı,

Gel artık gel, dindir gönül sızımı.

Sen nasıl ÜMMETİ dediysen rabbimize,

Bizde seni arzuluyoruz yedi tepeli şehirde...

Senin doğumunu kainat nasıl beklediyse,

Toprak nasıl yalvardıysa RABBİNE.

Nasıllar içinde bulduysa insanlık seni,

Bizde bulduk ve ölümü bekliyoruz,

Sana kavuşmak ve yanmak için....', 'Gecenin sabaha selam vermesiyle, Gözlerim seni arıyor Sultan Ahmet''te. Tarihi mekanlarda senin hayalin, Seni bulmakmış benim kaderi. Bilmem ...', ARRAY['Türk Edebiyatı','Şiir','Habip Sabanlı']::text[], 8.5, '{"poet":"Habip Sabanlı","poet_slug":"habip-sabanli","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/nat-degil-biat-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Kadın Ağlıyor', 'bir-kadin-agliyor-gonul-ozdemir-gmqvk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'BİR  KADIN  AĞLIYOR

Yüreğinde sevda yarası

Belki bir gün ortası belkide gece yarısı

Olur olmaz saatlerde düşer aklına sevdası

Çaresiz bir kadın ağlıyor şimdi

En çok sevdiği gecenin zifiri karanlığı

Çıkar cama bakınır söylenir kendi kendine

Yakar sigarasını çeker acı acı oysa ömürden çalıyor

Bunuda biliyor umutsuz bir kadın ağlıyor şimdi

En çok sevdiği şiir sitelerine girer

Gezinir bir bir şiirleri işte tam benlik şiir der

Damar şarkıları sevmesi gibi

Umutları umutsuz bir kadın ağlıyor şimdi

Suçu kadın olmaktı belki

Kıskanç ellerde ömür bitti kendini ifade edemedi

Belki biraz güzeldi çektikleri hep bunun bedelimiydi

Kimbilir belkide kuzguna yavrusu güzel gelirmiş

Gerçek payıda vardı belki ALLAH için güzeldi hani

Mesleği hayat üniversitesinde okuyor 

Oysa mezun olacağı günü sabırsızlıkla bekliyor

Beyazları giyeceği günü bekleyen bir kadın ağlıyor şimdi

Hadi hadi bitir artı şu üniversiteyi

Yada al başını git şu ellerden kurtulursun belki

Kolay olanı herkes başarır kurtuluş kaçmak değildirki

Zor olanı seçmiş bir kadın ağlıyor şimdi

Gecenin bir yarısı düşer aklına sevdası

Ah bir çıkıp gelse gelmez istesede gelemez

Belki o zaman susacak feryadı

Sabrı tükenmiş bir kadın ağlıyor şimdi

Sevdası düşünce aklına birazcıkda olsa umut olur yarınına

Belki temel taşlarımız yeniden kurulur gönül sarayımız

Artık yeteeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeer

Senin için bir kadın bir kadın ağlıyor şimdi ağlıyor şimdi..

22.6.2003      Gönül Özdemir      Bergkamen', 'BİR  KADIN  AĞLIYOR Yüreğinde sevda yarası Belki bir gün ortası belkide gece yarısı Olur olmaz saatlerde düşer aklına sevdası Çaresiz bir ka...', ARRAY['Türk Edebiyatı','Şiir','Gönül Özdemir']::text[], 8.5, '{"poet":"Gönül Özdemir","poet_slug":"gonul-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/bir-kadin-agliyor-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Güzel Hayat!', 'ne-guzel-hayat-erdogan-ergin-n8ti9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'ne güzel oturup, dinlenmek

hayat ne güzel

kuşlar

böcekler

çiçekler v.s

ne güzel

hani tüm şiirlerin

bahsettiği

şarkıların

ağızlardan düşmediği

yerde

v.s ler ne güzel

ne güzel

arkadaşımın söylediği söz

radyolardan çalan şarkı

nazan öncel, sezen aksu

ve tarkan ne güzel

ne güzel; 

hayata toz pembe bakan gözler

mutlu, umutlu yarınlar

yazarlar, çizerler

ve eleştirmenler ne güzel

ne güzel; 

zamansız gelen bahar

yağan yağmur

diz boyu kar

ve mevsimler ne güzel

ne güzel

kış uykusuna dalmış herkes

sessiz diller,ruhlar

ve bedenler ne güzel

ne akan hayat umrunda insanların

ne dökülen kanlar

vurulan insanlar

kaybolan çocuklar

aç kalıp, ölenler

onaltısında,evi terkeden

evine giden çocuklar

şehitler, gaziler 

değil umrumuzda

ne güzel; 

zamansız gelen bahar

yağan yağmur

diz boyu kar

ve mevsimler ne güzel

ne güzel

arkadaşımın söylediği söz

radyolardan çalan şarkı

nazan öncel, sezen aksu

ve tarkan ne güzel

ne güzel şiir

ve yazan şair', 'ne güzel oturup, dinlenmek hayat ne güzel kuşlar böcekler çiçekler v.s ne güzel hani tüm şiirlerin bahsettiği şarkıların ağızlardan düşmediğ...', ARRAY['Türk Edebiyatı','Şiir','Erdoğan Ergin']::text[], 8.5, '{"poet":"Erdoğan Ergin","poet_slug":"erdogan-ergin","theme":"Türk Şiiri","is_hero":false,"total_lines":52,"source_url":"https://www.antoloji.com/ne-guzel-hayat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Zormuş', 'ne-zormus-kenan-ozsaho-l3n8g', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ne zormuş,

Ah,ne zormuş; 

Delice sevmek.

Ne zormuş,

Allah''ım ağlarken gülmek.

Gözlerinin içine bakıp bakıp; 

Hasreti,gizlemek ne zormuş; 

Allah''ım yeter,yeter 

Al şu canımı; dayanamıyorum.

Yeter yeter Allah''ım yeter,

Al şu canımı; dayanamıyorum.

Bir gün,bir gün sen de yanarsın.

Bir tutam saç teline,

Kahve rengi (mavi yeşil)  gözlere,

Yalan tatlı sözlere

Sen de kanarsın.

Bir gün beni anlarsın.

Yeter yeter Allah''ım yeter,

Al şu canımı; dayanamıyorum.

Yeter yeter Allah''ım yeter,

Al şu canımı; dayanamıyorum.', 'Ne zormuş, Ah,ne zormuş;  Delice sevmek. Ne zormuş, Allah''ım ağlarken gülmek. Gözlerinin içine bakıp bakıp;  Hasreti,gizlemek ne zormuş;  Al...', ARRAY['Türk Edebiyatı','Şiir','Kenan Özşaho']::text[], 8.5, '{"poet":"Kenan Özşaho","poet_slug":"kenan-ozsaho","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ne-zormus-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayal', 'hayal-huseyin-sigirtmac-u74c1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Duygusuna kandım sanal alemin.

Hiçbir derde derman değilmiş hayal.

İlmine güvendim yazan kalemin.

Onu da diz çöküp kandırmış hayal.

Bir sorunu çözmez oldu bin kaygı.

Başıma dert oldu yürekte duygu.

Ne sevgiye çözüm, ne bulur saygı.

Bütün hücrelere dağılmış hayal.

Gecemde rüyadır, gündüzde serap.

Yer dibine battım oldukça turap.

Hiç ayık gezmedim yok rakı, şarap.

Işığı kör edip söndürmüş hayal.

Sığırtmaç yürekte hüznümdür neşe.

Hasretim değişmem yıldız, güneşe.

Belki gerçek kızar böyle gidişe.

Ne fayda deftere yazdırmış hayal.', 'Duygusuna kandım sanal alemin. Hiçbir derde derman değilmiş hayal. İlmine güvendim yazan kalemin. Onu da diz çöküp kandırmış hayal. Bir soru...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Sığırtmaç']::text[], 8.5, '{"poet":"Hüseyin Sığırtmaç","poet_slug":"huseyin-sigirtmac","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hayal-75-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Işıklar Sönsün', 'isiklar-sonsun-erdogan-ergin-6pbo1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bırak ışıklar sönsün

Karanlıkta da görür 

insan insanı

Bırak ışıklar sönsün

Aydınlıkta görülmeyen

Belki şimdi...', 'Bırak ışıklar sönsün Karanlıkta da görür  insan insanı Bırak ışıklar sönsün Aydınlıkta görülmeyen Belki şimdi......', ARRAY['Türk Edebiyatı','Şiir','Erdoğan Ergin']::text[], 8.5, '{"poet":"Erdoğan Ergin","poet_slug":"erdogan-ergin","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/isiklar-sonsun-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gömün Gitsin', 'gomun-gitsin-aynur-baydar-d5r81', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '09/12/2004 akşamı tv de bir habere rastladım. Haberde bir hiç uğruna başı tinere sokularak öldürülen genç bir adamın, yaşlı babasına cinayet zanlılarının mahkemeye çıkarken, şikayetçi oldular diye yaşlı adamı dövdükleri haberi verildi. Bastonlu ayakta zor duran yaşlı adam, oğlunu öldürenlerin şikayetinden vazgeçmezlerse, tüm ailenin kökünü kazıyacakları tehdidinde bulunduklarını, mahkeme salonuna girerken de kendine saldırıp dövdüklerini ağlayarak anlattı. Zanlı çıkarken kameralara bakıp, çekin çekin diye bağırıp, tehditler savurdu. 

Gazetelerde ilkokul çocuklarının tecavüze uğradıkları, yapanın bunu herkese söylerim, adın çıkar korkutması ile tecavüzlere devam ettiği, etrafa ballandıra ballandıra anlattığı için tecavüzcü halkasının genişlediği, hatta orada bulunan ileri gelenlerin, okumuş etmiş, yaşlı başlı ev bark sahibi adamlarında katıldığı ve kızın bunalıma girmesi üzerine olayın meydana çıktığı haberi vardı.

Empati yani kişinin kendisini başkasının yerine koymasını bu olaylarda düşünürsek.

Bakıp büyüttüğün fidan gibi oğlunu başını tinere sokup yok yere öldürüyorlar, yaşın gelmiş seksene öksüz torunlarına mı bakacaksın, gelinini mi koruyacaksın, oğlunun acısına mı dayanacaksın.

12 yaşında küçük bir kızsın,birinin tecavüzüne uğruyorsun, tecavüzcü sayısı her geçen gün artarak tam 2 yıl sürüyor. Her okul çıkışında, annen her bakkala yollayışında bu iğrençliği yaşıyorsun ve 14 yaşına gelip, kafayı yiyince olay ortaya çıkıyor. Kimsesizsin bir tek cahil bir anacığın var annenin öldürülme korkusu, dedikodu korkusu ve 2 yıl süren bu iğrenç işkence.

Mağdurların çoğunluğunun ortak yanı, kalabalık aileleri olmayışı, dar gelirli olmaları çocuk veya kimsesiz olmaları. Suçluların çoğunun ortak özellikleri güçlü, paralı, mafya örgütü benzeri davranış sergilemeleri. Özet kaba gücü veya parası olan bunlara sahip olmayanı yok ediyor.

İşin en kötü tarafı bunları her gün duya duya,  izleye izleye, okuya okuya normal olay gibi kanıksamaya başladık. Diğer bir deyişle adam sendeciliğimiz, bana dokunmayan yılan bin yıl yaşasın felsefemiz, çaresizliğimiz tepkisizlik sınırını geçmemize, daha da kötüsü her gün artan bu vahşeti normal görmemize sebep oldu. Peki ne yapabilirdik, cıyak cıyak bağıran vicdanlarımızı bastırmak için. Dedikoduyu bırakabilirdik, bu tür haberlerde olayı kınayan maillerle telefonlarla protesto sağınağı oluşturabilirdik. Yada mahkemeleri görülürken dışarıda bekler, çekin çekin diye kabadayılık taslayan katili ALLAH BELANI VERSİN KATİL diye yuhalıyabilirdik. Acaba bu kadar  küstah olabilir miydi? 

Televizyonda sözüm ona sanatçılardan bazıları ben aşiret çocuğuyum cümleleri kullanıyor, başka sanatçılarla tartışırken. Neden bu sözü söylüyorlar. Ayağını denk al kafamı bozarsan 3000 kişilik ordu ailemle canını okurum demek istiyorlar. Bunlarda gençlerin beğendiği örnek aldığı sanatçılar. Hukukun işlemesinin, toplum vicdanıyla beraber gittiği bir gerçek.

Bu arada bir ölüm haberi vermek istiyorum. Toplum vicdanımız, insanlığımız idam edildi hem de çok uzun bir süre önce, kokuşmaya başlayan ceset ikindi namazını müteaakip yüreklerimizden kaldırılacak. İmam soracak adı insan, soyadı vicdanı nasıl bilirdiniz. Her birimiz şaşıracağız, bu kim tanımıyoruz, ne diyelim diye susacağız. Beklemekten yorulan imam seslenecek GÖMÜN GİTSİN! 

Not: Şiir değil, düz yazı astığım için özür dilerim. Herhalde vicdanım birazcık sussun istedim.

Saygılarımla', '09/12/2004 akşamı tv de bir habere rastladım. Haberde bir hiç uğruna başı tinere sokularak öldürülen genç bir adamın, yaşlı babasına cinayet...', ARRAY['Türk Edebiyatı','Şiir','Aynur Baydar']::text[], 8.5, '{"poet":"Aynur Baydar","poet_slug":"aynur-baydar","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/gomun-gitsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kimse Görmedi', 'kimse-gormedi-i-smet-barlioglu-xk2ss', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ah, gözünü sevdiğimin belalısı,

İnsan gündüz de mi girermiş insanın düşlerine,

İliklerine, zerrelerine kadar mı işlermiş,

Kemiklerinde sızı, yüreğinde acı mı olurmuş,

Yaş mı olup süzülürmüş gözlerinden yanaklarına? 

Tanrı böylesine mi cömertçe izin vermiş

Sana? 

Darlardayım sevdana düştüm düşeli,

İğneli fıçılardayım.

Sanki bir takım eller

Beni bir Nürenberg Bakiresi ‘ne tıkmışlar

Ve tıpkı bir tabut kapaiı gibi

Üstüme üstüme mızraklı kapı

Kapatmışlar.

Dışarı damlayan kanım değil, aklım-fikrim,

Bedenim değil işkenceyi çeken, umutlarım,

Sana yürüyen ayaklarım, dualara kalkan ellerim

Ve birer pırıltılı sabun köpüğü gibi dağılıp giden

Hayallerim.

Meğer ne dayanıklı bedenmiş bu bedenim,

Meğer ne sabırlı kalpmiş bu kalbim; 

Çekileni onlar çekti, ben inledim,

Onlar yanıp kavruldu Nemrud ateşlerinde

Ben serinledim.

Ben isyanlar ettim çığlık çığlığa, onlar dinledi,

Tanrı ‘ya şükürler olsun ki; 

Sezilmedi.

(KAVAKYELLERİ İsimli Serbest Şiirler ''inden >17-18 /100)', 'Ah, gözünü sevdiğimin belalısı, İnsan gündüz de mi girermiş insanın düşlerine, İliklerine, zerrelerine kadar mı işlermiş, Kemiklerinde sızı,...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/kimse-gormedi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sakız Niyetine', 'sakiz-niyetine-i-smet-barlioglu-k9y3t', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir kız sevmişim ki; Aslı ‘dan Aslı,

Ne Leyla ‘ya benzer, ne Şirin ‘e,

Geçirmiş yüreğimi eline

Didikler durur örgü yerine şişlerle, bildiğince,

Güvendiğim dağlara kardır ki yağdırır

Gündüz,

Gece.

Ayaklarımda demirden çarıklar,

Elimde demirden asa,

Kör-topal düşmüşüm yollarına yıllar yılı,

Azlar gitmişim, uzlar gitmişim,

Ancak bir arpalar boyu yollar gitmişim

Bir büyük karasevdada.

Daha aşındıracak ne bir yollarım var, biliyorum; 

Aradığım

Kaf Dağı ‘nın

Arkasında.

Deve kesmiş yollarım anam-babam,

Bir dudağı yerde, bir dudağı gökte devler,

Dillerinde alevler, gözlerinde yıldırımlar,

Düşmüşüm işte

Bir karasevda uğrunda pençelerine,

Çiğneyip dururlar ağızlarında bir körpe ömrümü

Sakız niyetine.

(KAVAKYELLERİ İsimli Serbest Şiirler ''inden > 19-20/100)', 'Bir kız sevmişim ki; Aslı ‘dan Aslı, Ne Leyla ‘ya benzer, ne Şirin ‘e, Geçirmiş yüreğimi eline Didikler durur örgü yerine şişlerle, bildiğin...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/sakiz-niyetine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Şarkı Söyle Bana', 'bir-sarki-soyle-bana-i-smet-barlioglu-finz1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir şarkı söyle bana tüm içtenliğinle,

İçinde reçine kokusu olsun

Çam dallarından,

Kozalaklarla oynaşan bir ince ruhlu rüzgar,

Ormanla kucaklaşan körpe bir yosun kokusu,

Bir masmavi deniz bulutlar altında

Ve ilk aşkı seyreden bir küçük sincap

İri, parlar, kapkara gözleriyle,

İşte böyle bir şarkı söyle bana

İçtenliğinle.

Bir şarkı söyle bana

Geçmiş günlerimi geri getiren,

Bin kez arayıp bir kez bulamadığım,

Aklıma geldikçe ılgıt ılgıt ağladığım

O ilk görüp ilk vurulduğum günleri,

O ilk yürek çırpıntılarını

Geri getiren bir şarkı söyle bana,

Ki; güneşin yine yaldızlar yağdırdığını sanayım

Saçlarına.

Bir şarkı söyle bana tüm içtenliğinle,

Sen söylerken uzaklaşayım buralardan alıp başımı,

Kalsın kulaklarımda o şarkı sıcak sıcak,

Dilimde, avuçlarımda, dudaklarımda

Ve yine her zamanki gibi o güneşli yağmur aklımda,

Islak yollarda bir başıma yürüyüp gideyim,

Bir şarkı söyle bana sevgiden yana; 

Andıkça sevineyim.

(BİR ŞARKI SÖYLE BANA İsimli Serbest Şiirler ''inden > 5-6 /100)', 'Bir şarkı söyle bana tüm içtenliğinle, İçinde reçine kokusu olsun Çam dallarından, Kozalaklarla oynaşan bir ince ruhlu rüzgar, Ormanla kucak...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/bir-sarki-soyle-bana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz Bayram', 'sensiz-bayram-i-smet-barlioglu-cub8p', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sensiz bir bayram daha geçirdim güya,

Nasıl geçirdiğimi sen gel de bana sor,

Kimlerdi bilmiyorum,

Bilmek de istemiyorum,

Elbirliği ettiler ölümüne

Davul-zurna sesleri arasında,

Yüklediler sırtıma bilcümle dağları

Ve beni dermanım kesilene kadar yürüttüler,

Sonra dağları sırtımda bırakıp

Gittiler.

Yapayalnız geçtim

Defne dallarıyla süslü taklar altından,

Kalabalıklar içinde yapayalnız yürüdüm,

Nice bir fişekler gökleri aydınlattı yırta yırta

Fakat hiçbiri içimi aydınlatamadı,

Mutluluk kol geziyordu kıyasıya,

Beni bulamadı.

Sensiz bir bayram daha geçirdim,

Nasıl geçirdiğimi sen gel de bana sor,

Canımı İsa eyleyip çektim çarmıhlara

Rengarenk ışıklar arasında,

Sevinç çığlıkları kanım gibi akıp durdu

Yanımdan-yöremden,

Bir koskoca bayram gününde

Bir küçük mutluluk esirgendi

Benden.

(BİR ŞARKI SÖYLE BANA İsimli Serbest Şiirler ''inden > 7-8 /100)', 'Sensiz bir bayram daha geçirdim güya, Nasıl geçirdiğimi sen gel de bana sor, Kimlerdi bilmiyorum, Bilmek de istemiyorum, Elbirliği ettiler ö...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/sensiz-bayram-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bo Amedê', 'bo-amed-omer-dilsoz-ew6um', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Amed e; 

Delodîn e...

Hin caran wekî bûkeke serbixêlî kêfê tîne, 

hin caran jî wekî zêmara dayikeke cegersotî dinehwirîne

Amed delodîn e

û hîn caran çavên xwe ji rondikên bêriyan ziwa dike

hin caran jî bedenên xwe dike rextê guleyan 

û bi ser neyaran de direşîne

û hin caran girnijîna li ser lêvên yaran belav dike

hêrsa wê gelek e

hêrsa wê dîrokekê di dilê xwe de dihewîne

lê jîna wê gelektir e

keçên nûgiha mest dike

û bi dû xwe ve dibezîne

lawên hêj simbêlristî di kela xwe de dikuje 

û li ser celadên şewitî kulîlkan diçîne

Amed e,

Amed 

min got ya; delodîn e

Amed bûk e

bûkek e ku miraza wê li ber sînga wê beyirî ye

Omer Dilsoz & Dilyarê Dêrikî', 'Amed e;  Delodîn e... Hin caran wekî bûkeke serbixêlî kêfê tîne,  hin caran jî wekî zêmara dayikeke cegersotî dinehwirîne Amed delodîn e û h...', ARRAY['Türk Edebiyatı','Şiir','Ömer Dilsöz']::text[], 8.5, '{"poet":"Ömer Dilsöz","poet_slug":"omer-dilsoz","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/bo-amede-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey Aşk! Seni Çözen Var mı?', 'ey-ask-seni-cozen-var-mi-nigar-adak-7yim0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sevda ocağındaki dumanın hiç sönmedi,

Közlediğin yürekler sazla sözle bitmedi.

Çöllerin ortasında, sevene serap oldun,

Kör ettiğin gözlere, özlem seliyle doldun.

Fırtınalar kopardın, deryalara sığmadın,

Hükmeyledin çağlara, zamanı hiçe saydın.

Onca deli ırmaklar, çağladı gönüllere,

Nice aciz nefisler, düşürüldü yerlere.

Cefanla viran oldu, tahtlı gönül köşkleri, 

Divaneye döndürdün, gülistan yürekleri.

Ne saltanat dinledin, ne de sultan fermanı,

Lokman da çaresizdi, bulamadı dermanı.

Mantığı tanımazsın, kalplere musallatsın,

Boz bulanık sancıyı, has aşıklar anlatsın.

Kâinat sensiz olmaz, alem senle varoldu,

Özüne inen gönül, gören ruhlar şad oldu.

Gizem dolu ummansın, sırrını çözen var mı? 

Cihanda senden öte, makamı bilen var mı? 

Nigar Adak

08.12.2004

Dikkat: Şiirlerimin hepsi noter tasdiklidir..! Şair adı olmadan alıntı yapılamaz..!', 'Sevda ocağındaki dumanın hiç sönmedi, Közlediğin yürekler sazla sözle bitmedi. Çöllerin ortasında, sevene serap oldun, Kör ettiğin gözlere, ...', ARRAY['Türk Edebiyatı','Şiir','Nigar Adak']::text[], 8.5, '{"poet":"Nigar Adak","poet_slug":"nigar-adak","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ey-ask-seni-cozen-var-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mevsim Bahar', 'mevsim-bahar-sinan-dayan-y2mdb', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Mevsim bahar ama ilki değil ne farkeder? 

Ha rüzgar ılık ılık esmiş ürperirmiş benliğin...

Ha hava soguk, rüzgarda titrermişsin...

Mevsim bahar, ilki değilmiş ne farkeder.

Karaysa gözler iri iri kömür gibi,

Çatılınca kaşlar gerilmiş bir yay gibi,

Dökülünce sözler dudakdan şiir gibi,

Saclar ha uzun ha kısa, ne farkeder.

Ben Karacaoglan değilim, bilirim

Ama görürsem güzel severim,

Gönlümde ben sevda beslerim,

Biri sen, biri oysa ne farkeder...', 'Mevsim bahar ama ilki değil ne farkeder?  Ha rüzgar ılık ılık esmiş ürperirmiş benliğin... Ha hava soguk, rüzgarda titrermişsin... Mevsim ba...', ARRAY['Türk Edebiyatı','Şiir','Sinan Dayan']::text[], 8.5, '{"poet":"Sinan Dayan","poet_slug":"sinan-dayan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/mevsim-bahar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Teneşir', 'tenesir-ahmet-agdere-ducns', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Adaletsiz devlette rezil olursun,vezir olursun

Hamisiz muhabbette beterden beter olursun

Maksadın kaba cahile ders vermek ise

Emelsiz yol üstüne taş olursun

Teneşire konan baş olursun', 'Adaletsiz devlette rezil olursun,vezir olursun Hamisiz muhabbette beterden beter olursun Maksadın kaba cahile ders vermek ise Emelsiz yol üs...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ağdere']::text[], 8.5, '{"poet":"Ahmet Ağdere","poet_slug":"ahmet-agdere","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/tenesir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkına...', 'askina-sirma-mersin-anxze', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gönlüm

Deli divane olmuş, aşka...

Aradığım 

Ne Mecnun

Ne Ferhat...

Aradığım yalnızca sen! 

Senin sevdana tutulmuş gönlüm

Çaresizliğe mahkum olmuş,özlemim.

Umuduna sarılmış bekleyişimle 

Yaşamak istiyorum,aşkına

13.10.04

Aşka inanmış olan saf aşıklar, bu şiir size armağanım...', 'Gönlüm Deli divane olmuş, aşka... Aradığım  Ne Mecnun Ne Ferhat... Aradığım yalnızca sen!  Senin sevdana tutulmuş gönlüm Çaresizliğe mahkum ...', ARRAY['Türk Edebiyatı','Şiir','Sırma Mersin']::text[], 8.5, '{"poet":"Sırma Mersin","poet_slug":"sirma-mersin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/askina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni Anmak Zorundasın', 'beni-anmak-zorundasin-halil-kesken-fjxeb', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sevdiğimi biliyorsun

Farketmemiş olamazsın

Unutmaya gidiyorsun

Beni anmak zorundasın

Doğmadan batan güneşte

Yanmadan sönen ateşte

Her başlamadan bitişte

Beni anmak zorundasın

Buna biraz daha sabret

Vijdan azabına kahret

Kalbin sızlayacak elbet

Beni anmak zorundasın

Ya gerçekte, ya düşünde

Bir çocuğun gülüşünde

Her beyaz gül görüşünde

Beni anmak zorundasın', 'Sevdiğimi biliyorsun Farketmemiş olamazsın Unutmaya gidiyorsun Beni anmak zorundasın Doğmadan batan güneşte Yanmadan sönen ateşte Her başlam...', ARRAY['Türk Edebiyatı','Şiir','Halil Kesken']::text[], 8.5, '{"poet":"Halil Kesken","poet_slug":"halil-kesken","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/beni-anmak-zorundasin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölü', 'olu-erguapo-pako-paxnisi-49kv4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'ölüler gördüm ölüler

kör sağır ve dilsiz ölüler

daracık odalarda

yaralarına tuz basılmış

daracık odalarda kıvranan ölüler

bir daha uyanmadılar

yitip giden sevdlar gibi', 'ölüler gördüm ölüler kör sağır ve dilsiz ölüler daracık odalarda yaralarına tuz basılmış daracık odalarda kıvranan ölüler bir daha uyanmadıl...', ARRAY['Türk Edebiyatı','Şiir','Erguapo Pako Paxnisi']::text[], 8.5, '{"poet":"Erguapo Pako Paxnisi","poet_slug":"erguapo-pako-paxnisi","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/olu-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk / inkar', 'ask-inkar-erguapo-pako-paxnisi-j7r05', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'kuşalrın en kırılgan vaktidir

boğazın kanat çırptığı an

...

en tanrı tanıazların bile sığındıkları bir mabet

kuşların uçtuğu sonsuzbir gök yüzü

...

yorgun gemilerin limana sığınması gibidir

merhametsiz gözlrine destuırsuz sığınmam

...

orta boylu bir semazen duruşudur

ben de göz göz duruşun

...

tüm kirli limanlardan tutasım gelir seni

sonra saçalrın dan tarayışım ulu orta istanbul''da





..', 'kuşalrın en kırılgan vaktidir boğazın kanat çırptığı an ... en tanrı tanıazların bile sığındıkları bir mabet kuşların uçtuğu sonsuzbir gök y...', ARRAY['Türk Edebiyatı','Şiir','Erguapo Pako Paxnisi']::text[], 8.5, '{"poet":"Erguapo Pako Paxnisi","poet_slug":"erguapo-pako-paxnisi","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ask-inkar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Herseyi Söylerken', 'ben-herseyi-soylerken-gizem-unlu-canpek-kf6p8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ben herseyi söylerken...

kaynar sularda yüzüyordum, buz gibi ellerimle.

Kalbimin sesini duyuyordum, gözlerine bakarken.

Ve söylemedigin sözlerden, 

dokunmamis ellerinden korkuyordum...

Sensizlikten korkuyordum,

ben herseyi söylerken...

Ben herseyi söylerken...

sen olmak istiyordum, hakkim olmadan.

Sen olup, benim olmak.

Bir sigara yakmak, bir bardak sarap icmek.

Hayalleri degil, seni istiyordum umutsuzca. 

Ve bir tek senin olmak istiyordum,

ben herseyi söylerken...

Ben herseyi söylerken...

bir cocuk  agliyordu yakinlarda, sehrin gürültüsünü duyuyordum.

Telefonun calmasindan, kapida bekleyen bir misafirden,

sen ve ben olmayan herseyden korkuyordum.

Sende, benden baska bir ben olmasindan korkuyordum,

ben herseyi söylerken...

Ben herseyi söylerken...

kokunu sonsuzcasina icime cekiyordum.

Sensiz duran, zamani dinlerken, 

bir seyler söylemeni istiyordum bana dair.

sana ait birseyler olmak...

Biz olmak istiyordum, sonsuza dek.

aslinda sadece..... „Seni Seviyorum“ demek istiyordum...

ben herseyi söylerken...', 'Ben herseyi söylerken... kaynar sularda yüzüyordum, buz gibi ellerimle. Kalbimin sesini duyuyordum, gözlerine bakarken. Ve söylemedigin sözl...', ARRAY['Türk Edebiyatı','Şiir','Gizem Ünlü Canpek']::text[], 8.5, '{"poet":"Gizem Ünlü Canpek","poet_slug":"gizem-unlu-canpek","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/ben-herseyi-soylerken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saklı Anılar', 'sakli-anilar-altay-taskin-s1x7e', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'anılar

        gece karanlığında

        ayışığı da bulutlarla

saklambaç oynuyor şimdi

        bekliyorum

        bulutların ayı sobelemesini

hep ebe olsun ay

        isterim ki

        anılarımla 

        ağlaşayım

kimse duymadan

        özlemlerimi

        tazeleyim kendi kendime

        doğadan başkasına

yalvarmadan', 'anılar         gece karanlığında         ayışığı da bulutlarla saklambaç oynuyor şimdi         bekliyorum         bulutların ayı sobelemesin...', ARRAY['Türk Edebiyatı','Şiir','Altay Taşkın']::text[], 8.5, '{"poet":"Altay Taşkın","poet_slug":"altay-taskin","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sakli-anilar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkdeniz Kaçkını', 'askdeniz-kackini-ufuk-kesici-e59yv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Özlemin köprü altındayız çocuk, ağlama

Sevdanın kuğu kenti atlaslarda tuz ve buz

Kaptan bir kambur kıçın kıçın tornistan

Aşkdeniz kaçkını ben porsuk'' a alabanda

Yalnzlığın everest''indeyiz çocuk, ağlama

Sensizlik eski bir din dualarda toz ve kir

Kalbim, ufuk asri mezarlığı ölülerinde bin sitem

Cehennem kaçkını ben arafat''a alabanda

İzmir-Eskişehir 1984', 'Özlemin köprü altındayız çocuk, ağlama Sevdanın kuğu kenti atlaslarda tuz ve buz Kaptan bir kambur kıçın kıçın tornistan Aşkdeniz kaçkını be...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Kesici']::text[], 8.5, '{"poet":"Ufuk Kesici","poet_slug":"ufuk-kesici","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/askdeniz-kackini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yollayın Gam Yükünü', 'yollayin-gam-yukunu-ali-riza-unal-xq3cx', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yollayın gam yükünü, siz benden yana

Yeter ki bileyim geleni ben, dotsttan yana

Pişmişim bin gam ile ben, yana yana

Haz olmuşum bu narda, ben yardan yana

Sanma ki güçsüze külhan, ferman olandır

Açıp bağrını herkese, derman olandır

Bu meydanda baki olan er kişi

Cehdini sır edip, pinhan olandır

Kim gelirse pir ile üryan olup, merdana

Aşk yolunda sultana, meydan olandır

          güfte', 'Yollayın gam yükünü, siz benden yana Yeter ki bileyim geleni ben, dotsttan yana Pişmişim bin gam ile ben, yana yana Haz olmuşum bu narda, be...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/yollayin-gam-yukunu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsan Hakları Günü', 'i-nsan-haklari-gunu-kadir-soyturk-3d3hx', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Görüyorum ekranda,maşa olmuş bir kızı; 

Bir kahraman bacımı, hep susturmak istiyor!

Kirli elleri ile, kapatarak ağzını; 

Hem ona hem de bize, kan kusturmak istiyor! 

“İnsan hakkı” gününde, bak insanın haline...

Bu kanları döken kim, bu işlenen zulüm ne? 

İnsanlık itiliyor, bir maymunun  eline; 

Bu koskoca millete tuzak kurmak istiyor!', 'Görüyorum ekranda,maşa olmuş bir kızı;  Bir kahraman bacımı, hep susturmak istiyor! Kirli elleri ile, kapatarak ağzını;  Hem ona hem de bize...', ARRAY['Türk Edebiyatı','Şiir','Kadir Soytürk']::text[], 8.5, '{"poet":"Kadir Soytürk","poet_slug":"kadir-soyturk","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/insan-haklari-gunu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nat Degil BİAT', 'nat-degil-bi-at-habip-sabanli-af3df', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Anladım senden başka sevgili haram bana.

Zaman ve mekanımız ayrı olsa bile,

Beraberiz seni göremesemde.

Senden başka sevgili haram bana.

Belki geç kalmışım sana aşık olmakta.

Ama olsun benimlesin, bu yeter bana.

Sen olmasaydın yaratılmazdı alem.

Senden başka sevgili haram bana.

Belki bu şiir tam bir NAT degildir.

Ama sana gönülden BİATTIR.

Sen sultansın bizlerse birer geda.

Bundan sonra sen önde herşey arkamda.

Zaten dogrusuda bu degilmi? 

Senden başka sevgili haram bana.', 'Anladım senden başka sevgili haram bana. Zaman ve mekanımız ayrı olsa bile, Beraberiz seni göremesemde. Senden başka sevgili haram bana. Bel...', ARRAY['Türk Edebiyatı','Şiir','Habip Sabanlı']::text[], 8.5, '{"poet":"Habip Sabanlı","poet_slug":"habip-sabanli","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/nat-degil-biat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tilkiler Sana Hasret', 'tilkiler-sana-hasret-ali-riza-unal-950my', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gönlün olmadığı yere eyleme haslet

Kaderde varsa dost ile halvet

Korkma nasip ise gelir kısmet

Bil ki aşk sendedir, sevgin sana devlet

Sen kürkçü dükkânı ol yeter

Tilkiler sana hasret', 'Gönlün olmadığı yere eyleme haslet Kaderde varsa dost ile halvet Korkma nasip ise gelir kısmet Bil ki aşk sendedir, sevgin sana devlet Sen k...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/tilkiler-sana-hasret-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Martı Kanadında Sevdam', 'marti-kanadinda-sevdam-mehmet-asim-krxtl', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'öylesine uçuşkan,

kavuşmalara hasret bir ayrılıkla

duruyordun yanı başımda

göğümü kaplayan bir bulut gibi...

kısa geçişleri

kapsayan bir iklim gibi

kısa mesafelerde 

tutundum yokluğunun kollarına..

koparacak sandım

tüm ayrılıkları

bizim doğurduğumuz

rüzgar

götürecek sandım

zinlerimizden kurtarıp...

ve ödenecekti 

tüm ayrı kaldığımız vakitlerin bedeli

dinmeseydi rüzgar...

dinmeseydi fırtına....

düşmeseydik ayrılığa...

göğün rengi açılsaydı eğer

bir martı kanadında

düşecektim sevdama', 'öylesine uçuşkan, kavuşmalara hasret bir ayrılıkla duruyordun yanı başımda göğümü kaplayan bir bulut gibi... kısa geçişleri kapsayan bir ikl...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Asım']::text[], 8.5, '{"poet":"Mehmet Asım","poet_slug":"mehmet-asim","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/marti-kanadinda-sevdam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zalimim', 'zalimim-ali-riza-unal-ewlaa', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yaktın yandırdın beni

Bir bakışta zalimim

Ne sever ne sevmezsin

Eli hançerli zalimim

Nasıl kurtulam senden

Dili nardan zalimim

Dünya dar oldu bana

Çileme ferman zalimim

   türkü', 'Yaktın yandırdın beni Bir bakışta zalimim Ne sever ne sevmezsin Eli hançerli zalimim Nasıl kurtulam senden Dili nardan zalimim Dünya dar old...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/zalimim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Azabın Dolu', 'azabin-dolu-ali-riza-unal-0udwe', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Deşme sineyi gamımı

Her yanım hicranın dolu

Düşmeyen bilmez  ızdırabı

Senin gibi hor zalime

Çekmeye ram eden aşkının koru 

İstemem firaka lokmanı

Her anım, dem ile hatıran dolu

Görenler acır, şaşar halime

Sebebi sensin, içimde azabın dolu

     güfte', 'Deşme sineyi gamımı Her yanım hicranın dolu Düşmeyen bilmez  ızdırabı Senin gibi hor zalime Çekmeye ram eden aşkının koru  İstemem firaka lo...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/azabin-dolu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlık', 'yalnizlik-emre-akin-ysyrm', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yalnızlık

yolun yok ulasamıyorum sana

umudun yok  kuramıyorum düşünü 

sesin yok duyamıyorum şarkını

güneşin yok  üşüyorum dünyanda

yıldızın yok  göremiyorum önümü

sen yoksun

gözlerin yok kaybolabileceğim 

saçların yok öpebileceğim 

gülüşün yok görebileceğim 

sadece bir şey var yapabileceğim 

onu da yapmaya dayanmıyor içim

her gün senin için

farklı bir çiçek koparmak

ve koymak mezarına', 'Yalnızlık yolun yok ulasamıyorum sana umudun yok  kuramıyorum düşünü  sesin yok duyamıyorum şarkını güneşin yok  üşüyorum dünyanda yıldızın ...', ARRAY['Türk Edebiyatı','Şiir','Emre Akın']::text[], 8.5, '{"poet":"Emre Akın","poet_slug":"emre-akin","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/yalnizlik-210-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Visale Melhem', 'visale-melhem-ali-riza-unal-d50xr', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sana öyle meftunum ki, dilim varmaz söylemeye

Sevdan ile tarumarım, elim varmaz derlemeye

Yar canıma kasteylese, bahane bilmem vermemeye

Aşka düşen lokmanı neyler,visale merhem bellemeye 



güfte', 'Sana öyle meftunum ki, dilim varmaz söylemeye Sevdan ile tarumarım, elim varmaz derlemeye Yar canıma kasteylese, bahane bilmem vermemeye Aşk...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/visale-melhem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşık değilsem', 'asik-degilsem-emre-akin-irkiq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sana aşık değilsem,bu gece niye seni düşünüyorum

Sana aşık değilsem,niye sesini duymak istiyorum yanımda

Sana aşık değilsem,niye özlüyorum seni bakarken resmine

Sana aşık değilsem,niye her gece rüyamda seni görüyorum

Sana aşık değilsem,niye uyanmak istemiyorum 

Sana aşık değilsem,niye açıklayamıyorum bu duyguyu

Sana aşık değilsem,niye herkeste sana ait bir şey arıyorum

Sana aşık değilsem,niye günler geçmiyor

Sana aşık değilsem,niye seni düşündüğümde yanımdasın 

Sana aşık değilsem,niye seni düşünmediğimde hala ordasın

Sana aşık değilsem,niye bunlar başıma geliyor

Sana aşık değilsem,neden...', 'Sana aşık değilsem,bu gece niye seni düşünüyorum Sana aşık değilsem,niye sesini duymak istiyorum yanımda Sana aşık değilsem,niye özlüyorum s...', ARRAY['Türk Edebiyatı','Şiir','Emre Akın']::text[], 8.5, '{"poet":"Emre Akın","poet_slug":"emre-akin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/asik-degilsem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vay', 'vay-suleyman-yavuz-z2wqn', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Vay benim günlerim

Tarih oldu dünlerim

Yok, olmuş şimdiden yarınlarım

Vay benim hâllarım

Şimdi durup ağlasam mı? 

Yoksa yarını güzel düşünüp avunsam mı? 

Derdime yanıp kavrulsam mı? 

Yoksa durmadan ağlasam mı? 

Vay dedim halime vay ki ne vay

Hayatım anlamsız boşmuş vay

Vatan gurbet olmuş sevilen yalan 

Tek şeye inanırım oda en kolayı ölmektir

Yani kıymak bu cana', 'Vay benim günlerim Tarih oldu dünlerim Yok, olmuş şimdiden yarınlarım Vay benim hâllarım Şimdi durup ağlasam mı?  Yoksa yarını güzel düşünüp...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Yavuz']::text[], 8.5, '{"poet":"Süleyman Yavuz","poet_slug":"suleyman-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/vay-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sokak Çocuk''ları', 'sokak-cocuk-lari-i-brahim-necati-gunay-o63mm', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Çocuk sevgi ister,

Çocuk emek ister,

Çocuk oyun ister,

Çocuk mutluluktur,

Çocuk yaşamın kaynağıdır,

Çocuk gelecektir,

Üzmeyin çocukları,

Ezmeyin çocukları,

Sevin sokak çocukları''nı.

UNUTMAYIN SOKAKTAKİ ÇOCUKLARDAN BİRİDE SİZİN ÇOCUĞUNUZ OLABİLİRDİ.

ONLARI SEVİN SAHİP ÇIKIN ONLARA DEĞER VERİN VE YARDIM ELİNİZİ UZATIN.

EN GÜZEL DUYGU KARŞILIKSIZ VERİLEN SEVGİDİR.', 'Çocuk sevgi ister, Çocuk emek ister, Çocuk oyun ister, Çocuk mutluluktur, Çocuk yaşamın kaynağıdır, Çocuk gelecektir, Üzmeyin çocukları, Ezm...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Necati Günay']::text[], 8.5, '{"poet":"İbrahim Necati Günay","poet_slug":"i-brahim-necati-gunay","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sokak-cocuk-lari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey Şefaat Pınarı!', 'ey-sefaat-pinari-ali-kilic-kakiz-qfa9a', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yürek genişliği şerefli bir duygudur.

Kalpler vahiy gölgesinde tecelli bulur.

Güzelliği ilâhi bir sır, yansır aziz insana.

Sevgi ruh kanalıyla akar gönül pınarına.

Bize nursun ışıksın, alemlere ambersin.

Ey Nebi! gönüllerimize sevgi güneşisin.

Lütufla bakarsın yüreğimizde sevdan var.

Havzının başında içenler kana kana doyar.

Ey şefeat pınarı dönüp kaksan bir daha.

Çağırdın bizleri kudreti sonsuz Allaha.

Arşı âlanın aydınlığı altında, gölgesinde.

Gül gülümse dur, ümitsin yüreğimizde.

........................

Brüksel /  1985', 'Yürek genişliği şerefli bir duygudur. Kalpler vahiy gölgesinde tecelli bulur. Güzelliği ilâhi bir sır, yansır aziz insana. Sevgi ruh kanalıy...', ARRAY['Türk Edebiyatı','Şiir','Ali Kılıç Kakiz']::text[], 8.5, '{"poet":"Ali Kılıç Kakiz","poet_slug":"ali-kilic-kakiz","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ey-sefaat-pinari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül', 'gonul-abdullah-atay-vtmfk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'sevgisiz gönüllerde

gündüzler hep gecedir

yari çirkin olanın

bilmem hali nicedir...

sevgi yüklü gönüller

aşka asla doymuyor

gece gündüz ağlarım

o yar sesim duymuyor...

yaralı gönüllerde

sabahlar geç oluyor

ayrılık rüzgarıyla

kalbe hüzün doluyor...

gönül gonca bir güldür

şakıyan coşan dildir

senden başkası yarsa

sevdiğim beni öldür....

sevdalanan gönüller 

uçan bir kelebektir

ağlayan bu gönüller

gün gelir gülecektir...', 'sevgisiz gönüllerde gündüzler hep gecedir yari çirkin olanın bilmem hali nicedir... sevgi yüklü gönüller aşka asla doymuyor gece gündüz ağla...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Atay']::text[], 8.5, '{"poet":"Abdullah Atay","poet_slug":"abdullah-atay","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gonul-79-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gökçam''da Çiğdem zamanı', 'gokcam-da-cigdem-zamani-ali-sagmen-q94xi', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Son karın kalktığı bahar ayında                                     

Çiğdemler açar toprağımda                                          

Çocuk sevınciyle koşarım onlara                                               

sert ve yumuşak zeminde                                                           

elimde eşmek için bir kazgıç                                                     

çekerim ciğerime temiz havayı                                                                                     

bitince toplama işlemi                                                                

demet yapardım deste deste                                                    

Ve her nedense veremedim sevdiğime                                   

o nedenle ne zaman kar yağsa,eridiğinde yine çiğdemler çıkacak                                                                              

ve ben onları sevdiğime veremeyecek gibi  korku sarıyor içimi                                                                                             

Ne kadar isterdim şimdi çocuk olmayı                               

Gökçam tepelerinde topladığım                                            

çiğdem  destelereimin en güzelini ulaştırabilmeyi sevdiğime                                                                                                                                                                    01.02 1999', 'Son karın kalktığı bahar ayında                                      Çiğdemler açar toprağımda                                           Çoc...', ARRAY['Türk Edebiyatı','Şiir','Ali Sagmen']::text[], 8.5, '{"poet":"Ali Sagmen","poet_slug":"ali-sagmen","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/gokcam-da-cigdem-zamani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Solmuş', 'solmus-gokhan-oflazoglu-fofb2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Eğer söz taşıyamıyorsa anlamı,

yazılınca biraz da yitirmişsek yaşananı.

Bir yol bulmalı beyinden beyine ya da

gönülden gönüle. Gözler taşımalı yükü,

bütün anlam yüzümüzde ışımalı.

Belki o zaman kavrarız,

kelimelerde solanı.

11/12/2004', 'Eğer söz taşıyamıyorsa anlamı, yazılınca biraz da yitirmişsek yaşananı. Bir yol bulmalı beyinden beyine ya da gönülden gönüle. Gözler taşıma...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Oflazoğlu']::text[], 8.5, '{"poet":"Gökhan Oflazoğlu","poet_slug":"gokhan-oflazoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/solmus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkın Ecelimdir...', 'askin-ecelimdir-ediz-karaoglu-njxqx', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İnsanın eceli bir kez gelir,

Ve analar bir kez ağlar kırk gün,kırk gece,

Ama bunun ne ne zaman olacağı bilinir,

Ne de nasıl olacağı...

Sen benim ecelimsin belki de,

Uykumda geldin,hem de hiç fark ettirmeden,

Elinde ne bir silah var,

Ne de bir ip var incecik boynuma takılacak,

Gözlerin,ellerin,saçların var,

Ama,ama çok uzak...

İşte bu yakıyor ya zaten beni! 

Tamam,tamam,sen benim canımı almaya geldin,

Ellerin de ondan soğuk bu sefer,

Mâdem canımı çok görüyorsun bu bedende,

Niye acı çektiriyor,öldürmüyorsun,

Gözlerinle her dakika vuruyorsun beni? 

İşte bu beni bitiriyor ya zaten...', 'İnsanın eceli bir kez gelir, Ve analar bir kez ağlar kırk gün,kırk gece, Ama bunun ne ne zaman olacağı bilinir, Ne de nasıl olacağı... Sen b...', ARRAY['Türk Edebiyatı','Şiir','Ediz Karaoğlu']::text[], 8.5, '{"poet":"Ediz Karaoğlu","poet_slug":"ediz-karaoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/askin-ecelimdir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kesişme', 'kesisme-erdem-nur-cengiz-nxqr4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Siz ve Ben,

Ayrı çizgilerden gelip

Kesişmeye çalışan noktalar gibiyiz.

Öykülerimiz var; 

Kederli ya da hiç.

Sevilerimiz içtenlikli

Ya da yapay gölgeleri yüzlerimizin...

Buluşabilir miyiz bir anında,

Yaşam sürecimizin? 

Bilinmez! 

Ama öylesi bir savaşım,

Sürekli var olan; 

Eylemlerimizde...

Not: Başlık annesi sevgili dostum Birsen İbrahimhakkıoğlu’na sonsuz teşekkürlerimle ;)', 'Siz ve Ben, Ayrı çizgilerden gelip Kesişmeye çalışan noktalar gibiyiz. Öykülerimiz var;  Kederli ya da hiç. Sevilerimiz içtenlikli Ya da yap...', ARRAY['Türk Edebiyatı','Şiir','Erdem Nur Cengiz']::text[], 8.5, '{"poet":"Erdem Nur Cengiz","poet_slug":"erdem-nur-cengiz","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/kesisme-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ateşböceği', 'atesbocegi-derin-oger-0gnaj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'akşamları zincire takarak

mavi karanlıklar üstüne dört kol

ateş püskürdü ateşböceği...

bir sürahi acı yudumlayarak

gidecekti biryerlerden geri dönmeden

fuzuli sayarak sokak dönemeçlerinin hikâyelerini...

buraları bizdenmiş pembeciğim

say ki kıyılar toplamış hırçın rüzgârın kara suyunu

yaprakların hışırtılarındaki ninnili dalgalar misali...

buraları bizdenmiş pembeciğim

emek avuntuları küçük bir yol çantası içinde

şimdi umutların enlemesine can çekişme dönemi..........', 'akşamları zincire takarak mavi karanlıklar üstüne dört kol ateş püskürdü ateşböceği... bir sürahi acı yudumlayarak gidecekti biryerlerden ge...', ARRAY['Türk Edebiyatı','Şiir','Derin Öger']::text[], 8.5, '{"poet":"Derin Öger","poet_slug":"derin-oger","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/atesbocegi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşlerdeki Sevgili', 'duslerdeki-sevgili-mehmet-lutfu-aydin-3bao4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Oydu işte karşımda; sapsarı saçlarıyla 

Asırlar var ki özlemle yolunu gözlediğim

Ya ben kimdim? 

Beklenen miydim umutların ardında gizli? 

Cesaretim yok sormaya… 

Neden ıslak sayın bayan, neden paslı gözleriniz? 

Bilin ki, aksa da sicim gibi yaşlarınız 

Kulunuz amadeyim; paspas edip dilimi

Silmek isterdim

Gözlerimin hapsindeydi bir çift göz

Hüzünle gölgelenmiş 

Bürünmüştü yedi renge, gökten ödünç alınmış 

Mavi… Sarı…  Lâcivert…

Sahi, ne renkti sayın bayan, ne renkti gözleriniz? 

Bilmek isterdim

Duruşu ne de güzel, gönlümdeki eceydi

Gülüşü ömre bedel, bakışları eceldi

Belki sisli bir gece, belki bir bilmeceydi

Düş müydü, gerçek miydi? 

Bildiğim…

Onca eza cefadan, görmediğim vefadan

Ne tat aldım ne de haz; yaşamak işkenceydi

Yine de sayın bayan, ölmek için erkendi

Sormanızı beklerdim, “Son arzun nedir? ” diye

Bana kalsa nanik derdim hayata, hayatı ti’ye alıp

Gülmek isterdim

Ne hoştu solumak aynı rengi 

Buluşmak gülüşlerde, sımsıcak ve acımtırak

Erimek gözlerinde, yumuşak ve usulcacık

İzin verseydi bir de ah! ...

Dokunabilseydim tenine

Yazık ki farkında değil benim 

Adını bile bilmediğim sevgilim

Biliyorum

Gidecek birazdan hüzünleri bana satıp

Gerçi koymaz; alışkınım hüzünlere

Ne ki, her ayrılış ölümden beter

Tanrım! Bu son olsun; yeter artık, yeter… 

Bağışlayın! Ne size ne sizsizliğe isyanım 

İsyanım içimdeki sessizliğe sayın bayan

Çığlıklar atmak oysa, sevdiğimi haykırmak

Dağıtıp çılgınlar gibi -gözüm aksın ki - 

Son kez…

Ölmek isterdim', 'Oydu işte karşımda; sapsarı saçlarıyla  Asırlar var ki özlemle yolunu gözlediğim Ya ben kimdim?  Beklenen miydim umutların ardında gizli?  C...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Lütfü Aydın']::text[], 8.5, '{"poet":"Mehmet Lütfü Aydın","poet_slug":"mehmet-lutfu-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/duslerdeki-sevgili-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Odak', 'odak-guler-ilgaz-98lg8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dönüyoruz duruyoruz

Tekerleğin çemberinde

Merkez ortada

Odak orada

Koy ortasına

Dön etrafında

........................

Ben sevinç koydum ortasına

Ya sen? ...', 'Dönüyoruz duruyoruz Tekerleğin çemberinde Merkez ortada Odak orada Koy ortasına Dön etrafında ........................ Ben sevinç koydum ort...', ARRAY['Türk Edebiyatı','Şiir','Güler Ilgaz']::text[], 8.5, '{"poet":"Güler Ilgaz","poet_slug":"guler-ilgaz","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/odak-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alışmak', 'alismak-nazmi-sengezer-ecknq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gülebilmek, hüznün en tatlı yerinde

Ya da hüzünlenmek; gülüşün bittiği yerde

Ne fark eder ey sevgili! 

İnsan alışmışsa derde! ... 

Sen gittin diye söndü lambalar

Sen gittin diye bitti, dualar! 

Ve sen gittin diye, görülmüyor rüyalar...

Ya hüzün getir bana; 

Ya gülüş......

Alışmak kolay değilmiş derde; 

GİTME.....', 'Gülebilmek, hüznün en tatlı yerinde Ya da hüzünlenmek; gülüşün bittiği yerde Ne fark eder ey sevgili!  İnsan alışmışsa derde! ...  Sen gitti...', ARRAY['Türk Edebiyatı','Şiir','Nazmi Şengezer']::text[], 8.5, '{"poet":"Nazmi Şengezer","poet_slug":"nazmi-sengezer","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/alismak-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tek Hüzünlü Göç', 'tek-huzunlu-goc-nazmi-sengezer-xvbtw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gitmeni izlemiştim kapı eşiğinde, 

Sessizce...

Çaresiz minik gözlerimde hüzün; 

Ellerimde gidişine inat tuttuğum gün! ..

Eteğine sarılıp sürüklemek istemiştim kaderine,

Gün döndü, ay döndü

Yıl döndü; habersizce! ..

Çok geç anladım.

Ölüm, tek kişilik, tek yönlü,

Tek hüzünlü bir GÖÇMÜŞ.', 'Gitmeni izlemiştim kapı eşiğinde,  Sessizce... Çaresiz minik gözlerimde hüzün;  Ellerimde gidişine inat tuttuğum gün! .. Eteğine sarılıp sür...', ARRAY['Türk Edebiyatı','Şiir','Nazmi Şengezer']::text[], 8.5, '{"poet":"Nazmi Şengezer","poet_slug":"nazmi-sengezer","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/tek-huzunlu-goc-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güneş ve Işık', 'gunes-ve-isik-caglar-akarsu-ai93h', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '...... 

Kışın güneşe koşardık,

Yazın güneşten, hep kaçardık,

Çelişkilerle dolu yaşamda,

Benim, güneşimsin,ısığımsın.

...

Ağustos un yakıcı ateşinde,

Kavrulup da,köz olurken,

Kırmızının, beyaza döndüğü,

Mevsimlerin içinden, çıkıp da gelen,

Güneşimsin,ışığımsın.

...

Uçuşurken beyaz kar taneleri,

Işıklar,saklanacak yer ararlar,

Soğuk kış gecelerinde,

Bozkırın ortasında kurulmuş çadır,

Otağımızın,ortasına dikmişler,

Arşa doğru, yükselen bir direk,

Sığındığımız sıcak bir yuvanın,

Güneşisin, ışığısın.

...

Her gün batışında,renkten renge giren,

Gökkuşağının, içinden süzülen,

Muştuların en güzeli,

Huzurun doğuşun bulduğum,

Güneşimsin,ışığımsın.

...', '......  Kışın güneşe koşardık, Yazın güneşten, hep kaçardık, Çelişkilerle dolu yaşamda, Benim, güneşimsin,ısığımsın. ... Ağustos un yakıcı a...', ARRAY['Türk Edebiyatı','Şiir','Cağlar Akarsu']::text[], 8.5, '{"poet":"Cağlar Akarsu","poet_slug":"caglar-akarsu","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/gunes-ve-isik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu beden seni bekler', 'bu-beden-seni-bekler-osman-sarar-zpl38', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'hatirlarmisin ilk bulustugumuz gunu,

o sicak sevgi dolu gunleri,

simdi ise soguk ruzgarlar esiyor,

buz tutuyor bu bedeni...

Soguk donduruyor aramizdaki sicakligi,

kis mevsiminden cikamaz olduk,

soyle sevdigim,

yoksam biz sonumuzu mu bulduk...

Hata bende mi bilemem,

zamani geri dondure bilsem,

eski gunlerimizi tekrar yasiya bilsem,

seninle yine tekrar mutlu ola bilsem...

Atesler icinde yansam bile baska birsey istemem,

bu beden seni bekler tek carem,

don gel mahsum bakislim,

cunki ben sana alistim...', 'hatirlarmisin ilk bulustugumuz gunu, o sicak sevgi dolu gunleri, simdi ise soguk ruzgarlar esiyor, buz tutuyor bu bedeni... Soguk donduruyor...', ARRAY['Türk Edebiyatı','Şiir','Osman Sarar']::text[], 8.5, '{"poet":"Osman Sarar","poet_slug":"osman-sarar","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bu-beden-seni-bekler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beyinsizler Yüzünden!', 'beyinsizler-yuzunden-kadir-soyturk-fhucd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Severim der,asla sevmez özünden

Bir damlacık yaş dökülmez gözünden

Neler geldi bu milletin başına

İçindeki beyinsizler yüzünden! 

Beyinsizler tüm dertlerin illeti

Halka münasip görüyor zilleti

Helak etme ey Allah''ım milleti

İçindeki beyinsizler yüzünden! 

Bir tarafta garip garip yazanlar

Öbür yanda haram yiyip azanlar

Doğruya darılıp,hakka kızanlar

İçindeki beyinsizler yünden!', 'Severim der,asla sevmez özünden Bir damlacık yaş dökülmez gözünden Neler geldi bu milletin başına İçindeki beyinsizler yüzünden!  Beyinsizle...', ARRAY['Türk Edebiyatı','Şiir','Kadir Soytürk']::text[], 8.5, '{"poet":"Kadir Soytürk","poet_slug":"kadir-soyturk","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/beyinsizler-yuzunden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gurur', 'gurur-ekrem-sama-exxxx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dur,

Gurur

Savurur.

Yere vurur.

Olursun mağdur.

Şeytandı en mağrur,

Bu yüzden oldu menfur.

Gurur   hastalık   doğurur.

Bunun en doğrusu da şudur:

Tevazu...  Kula yakışan budur.

(İstanbul:10.12.2004)', 'Dur, Gurur Savurur. Yere vurur. Olursun mağdur. Şeytandı en mağrur, Bu yüzden oldu menfur. Gurur   hastalık   doğurur. Bunun en doğrusu da ş...', ARRAY['Türk Edebiyatı','Şiir','Ekrem Şama']::text[], 8.5, '{"poet":"Ekrem Şama","poet_slug":"ekrem-sama","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/gurur-30-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman', 'zaman-halil-i-brahim-ozdemir-c824i', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Merhum Abdullah ÜNSAL için                                 

Yitik bir ses, çevremde dolaşıp duran zaman…

Uçarak buharlaşan, gökte gezinen duman.

Kalbimdeki ritimle,  saati kuran  bilir…

Yol biter, zaman durur, tıkların  bittiği an…', 'Merhum Abdullah ÜNSAL için                                  Yitik bir ses, çevremde dolaşıp duran zaman… Uçarak buharlaşan, gökte gezinen du...', ARRAY['Türk Edebiyatı','Şiir','Halil İbrahim Özdemir']::text[], 8.5, '{"poet":"Halil İbrahim Özdemir","poet_slug":"halil-i-brahim-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/zaman-159-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Diyarına', 'ask-diyarina-ali-gencay-2s0j1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Soyunmalıyım gecenin ayazında

Yada yanmalıyım yıldızların narına

Şarkılar dizmeliyim,donmuş dudaklarıma

Olurda düşersem yol ortasında

Kuşlar girin kollarıma 

İki yanımda kırlangıç kanatlar

Uçurun beni aşkın diyarına

Saçları rüzgar sevgili 

Esirgeme ellerini,çal lirini 

Duymalıyım kulaklarımda o eşsiz ezgi

Yaklaştıkça cennetine 

Sabırsızım

Kuşlar,bırakın ellerimi

Bırakın beni aşkın diyarına

Tenimi okşayan ılık rüzgar

Değme bana,tenimi yalnızca yar okşar

İçimde delice koşmak 

Parelenmeli,uçsuz bucaksız uzaklar

İhanet etmemeli yüreğime ayaklar

Miskler,karanfiller,leylaklar

Kesmeyin önümü 

Burnuma yalnızca sevda kokar

Uyku! 

Git gözlerimden

Sabaha az var

Korkarım,güneş benden önce doğar

Korkarım, önce gözlerinde o parlar

Kaybolmayın! 

Yoksa kaybolurum yıldızlar

Geri gelin kuşlar

Tutun kollarımdan

Anladım 

Aşkın diyarına daha çok var', 'Soyunmalıyım gecenin ayazında Yada yanmalıyım yıldızların narına Şarkılar dizmeliyim,donmuş dudaklarıma Olurda düşersem yol ortasında Kuşlar...', ARRAY['Türk Edebiyatı','Şiir','Ali Gençay']::text[], 8.5, '{"poet":"Ali Gençay","poet_slug":"ali-gencay","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/ask-diyarina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tek Başıma Yürüdüm', 'tek-basima-yurudum-fahrettin-ozdemir-12qso', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Tek başıma yürüdüm

Bir güz gecesiydi

Kaskatı kesilmişti zaman

Kelimeler birikmişti boğazımda

Dudaklarım kilitli.

Yürüdüm durdum

Boş yere onca zaman

Elime geçen sadece,

Bir ıslak mendil 

Bir iki boş hece..', 'Tek başıma yürüdüm Bir güz gecesiydi Kaskatı kesilmişti zaman Kelimeler birikmişti boğazımda Dudaklarım kilitli. Yürüdüm durdum Boş yere onc...', ARRAY['Türk Edebiyatı','Şiir','Fahrettin Özdemir']::text[], 8.5, '{"poet":"Fahrettin Özdemir","poet_slug":"fahrettin-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/tek-basima-yurudum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Huzur', 'huzur-pinar-yilmaz-2tvlp', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ey en ulaşılmaz olan huzur! ! ! 

Koş bana yaklaş yanıma.. sar beni her anımda

Küskünlügünü bırak benimle..dokun bana

Sensizlikten yorulan ruhumun ısıgına ısık kat varlıgınla', 'Ey en ulaşılmaz olan huzur! ! !  Koş bana yaklaş yanıma.. sar beni her anımda Küskünlügünü bırak benimle..dokun bana Sensizlikten yorulan ru...', ARRAY['Türk Edebiyatı','Şiir','Pınar Yılmaz']::text[], 8.5, '{"poet":"Pınar Yılmaz","poet_slug":"pinar-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/huzur-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocuksu Mutluluk', 'cocuksu-mutluluk-sirma-mersin-684lg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Çocuksu yalnızlığımın içinde

Soluk alırken

Çocuk düşlerimin başkentinde

Oynadığım mutluluğum oyununda

Yarattığım prensim

Pembe mavi renklerden çaldığım

Sevinçleri dağıtırken etrafa

Masum bi öpücük bıraktı

Yanağıma... 

01.10.04 

                ''Şimdi! çocuk olmak vardı... ;) ''', 'Çocuksu yalnızlığımın içinde Soluk alırken Çocuk düşlerimin başkentinde Oynadığım mutluluğum oyununda Yarattığım prensim Pembe mavi renklerd...', ARRAY['Türk Edebiyatı','Şiir','Sırma Mersin']::text[], 8.5, '{"poet":"Sırma Mersin","poet_slug":"sirma-mersin","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/cocuksu-mutluluk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alfabe', 'alfabe-oguzkan-bolukbasi-g16s5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Nedir

Hayatımıza sözünü geçiren kelimeler

A ile başlayan aşk ile mi başlar

Tutsaklığımız

Yoksa B ile başlayan bela mıdır

Adrenalini ruhumuzun

C ye gelince ceeeeee demeni isterdim

Çenem tutulaydı da söylemeseydim yalnızlığımı

Demem odur ki bir sultanın sultasında

Ecinniler tarar saçlarımdaki dalgaları

Fatiha hangi ruhun duasını okuyorsa dudaklarından

Gemilerin yelken açmaya hazırlandığı limanlarda ben varım

Yumuşak G ye fırsat verilmez öncelikte, sevabım olsun burada

Halbuki ne muhteşemdir, sessizliği

İçimizden zor çıksa da

Ilıman bir iklimde yuva kurar kuşlar uçar gider

Jaledir  o beynimizdeki kuşları kovalar

Kardeşi kardeşe vurduran bunlardır

Laleler koku vermeden bu kadar güzelse güllere tutsaklık niyedir

Mademki gözlerimizin gördüğüne koşuyoruz

Nerede görmediğimiz kokuların umudu kör müyüz? 

O zaman gel

Önümde diz çök saçlarını okşamama izin ver

Parlak bir yansımayla kamaştır beni

Rengini resmedeyim

Sessizliğini anlatayım tuvalde

Şebnemi nasıl konduracağım yapraklarına zor iş

Tam burada işte tam burada anlatacaklarım vardı

Uzak yerlerden getirdiğim sözlerle

Ümidimi tazeleyecektim

Vakit akşamdı

Yarim yanımda, sanki her şey tamamdı ama sustum

Zannımca harf kalmadı', 'Nedir Hayatımıza sözünü geçiren kelimeler A ile başlayan aşk ile mi başlar Tutsaklığımız Yoksa B ile başlayan bela mıdır Adrenalini ruhumuzu...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/alfabe-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hepimiz birer celladız aslında...!', 'hepimiz-birer-celladiz-aslinda-omer-faruk-girgin-leqnr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'hepimiz göklere asılı

birer celladız aslında

ayaklarımız yere değse de

boynumuza acı dolanır 

boğum boğum çelikleşir 

yaşamın can ortasında 

celladı oluruz kendimizin

çekeriz bir gün ipimizi

kendimizden kaçmayıp

göklerde tam kendimiz olunca...', 'hepimiz göklere asılı birer celladız aslında ayaklarımız yere değse de boynumuza acı dolanır  boğum boğum çelikleşir  yaşamın can ortasında ...', ARRAY['Türk Edebiyatı','Şiir','Ömer Faruk Girgin']::text[], 8.5, '{"poet":"Ömer Faruk Girgin","poet_slug":"omer-faruk-girgin","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/hepimiz-birer-celladiz-aslinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Diyemem', 'diyemem-zulfikar-yapar-kaleli-49lqp', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kendime atlastan bir dünya ördüm 

Tül sarayda mutlu oldum diyemem. 

Atılan taşları yaralı gördüm! 

Taşın esrarını bildim diyemem. 

Dosta selâm saldım, olmaz oralı 

Boynum bükük kaldı, ciğer yaralı. 

Felek sillesini vurdu vuralı, 

Hakikate nazar kıldım diyemem 

Gözündeki yara gördü yâr beni 

Sitemliydi, yara sürdü yar beni 

Bir vefasız yâra verdi yâr beni 

Sahrada Leyla’yı buldum diyemem. 

Dünyanın kaç kulaç boyuyla eni? 

Gaye idrak etmek bu serüveni! 

Gecenin zülfünde gündüz güveni 

Ben bendeki pası sildim diyemem 

Dünyanın ahvali kor beni derde 

“Her hale tahammül göster” der bir de 

Yaşamanın yalan olduğu yerde 

Kırk boşaldım, iki doldum diyemem.', 'Kendime atlastan bir dünya ördüm  Tül sarayda mutlu oldum diyemem.  Atılan taşları yaralı gördüm!  Taşın esrarını bildim diyemem.  Dosta sel...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/diyemem-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlat Bana Ask Nedir', 'anlat-bana-ask-nedir-burak-kucukaydin-ttly6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İlk günbatımının hemen ardından söylediklerimiz, bir

yüzyıl sonra da geçerli olabilirdi ve biz, güneşe

boğulmuş bir ilkyaz sabahının ilk saatlerinde, en çalışkan

çiftçilerle yarışarak, zamanı değirmenlerimize çuvallar

dolusu taşıyabilirdik. Bunları düşleyemiyorsak eğer,

anlat bana, nedir aşk? 

İlk mektuplarımızla birlikte okumayı sökerdik ve

ellerimizin tutkusu uğruna en yakıcı özlemleri göze 

alabilirdik. Sonra geleceği müjdelenmiş yokülkelerin

tapınaklarında beklemek yerine, şimdi ele geçirilmiş bir

gecenin saatlerinde eritebilirdik. Yapamamışsak bunları

eğer,

anlat bana, nedir aşk? 

Sabahın ilk dalgaları bizi kumsalda bulmayabilirdi ve

biz,  günah çıkartmak için mavi sığınaklarımızı yeğlerdik.

Köpüklü haritalarda yerimizi arayanlar, bir an sonra

haritalarını yitirirler, sonradan, çok sonradan

söylencelerimizle yetinmek zorunda kalırlardı.

olmamışsa söylencelerimiz eğer,

anlat bana, nedir aşk', 'İlk günbatımının hemen ardından söylediklerimiz, bir yüzyıl sonra da geçerli olabilirdi ve biz, güneşe boğulmuş bir ilkyaz sabahının ilk saa...', ARRAY['Türk Edebiyatı','Şiir','Burak Kucukaydin']::text[], 8.5, '{"poet":"Burak Kucukaydin","poet_slug":"burak-kucukaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/anlat-bana-ask-nedir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ruhumun Esareti', 'ruhumun-esareti-senol-sirin-j1vqt', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Vurulmuşa dönüyorum seni düşününce 

İçimde bir sızı bırak diyor şu arsızı

Yüreğim çarpıyor her nefes alışında

Gözlerin gözlerimde ellerin bağrımda

Düşünüyorsun belki nasıl başladı diye

Bak göreceksin gidecek iyiden iyiye

Diyeceksin daha önce olmadı niye? 

Hasret bitecek dönecek bu beden sevgiliye

Sana yalan söyleyemem, canımsın

Sensiz yaşayamam, damarımda kanımsın

Kim ne derse desin benim aşkımsın

Bu beden sensiz bir hiç benim sevdamsın

Yalnızlığım kavruluyor sensiz geçen her gecede

Ruhum çıldırıyor duramıyor artık bu bedende

Aşk kalbimzde bir yara hem sende hem bende

Sensin benim herşeyim dünümde bu günümde', 'Vurulmuşa dönüyorum seni düşününce  İçimde bir sızı bırak diyor şu arsızı Yüreğim çarpıyor her nefes alışında Gözlerin gözlerimde ellerin ba...', ARRAY['Türk Edebiyatı','Şiir','Şenol Şirin']::text[], 8.5, '{"poet":"Şenol Şirin","poet_slug":"senol-sirin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ruhumun-esareti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırmızı – Beyaz', 'kirmizi-beyaz-guler-ilgaz-rmwh7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Haykırmadan sesini duydun mu 

Sanırsın

Akmadan damarlarından kan

Kırmızı rengi

Gördün mü sanırsın

..........................

İstersen dans et ne çıkar

Solup gider

İz bırakmaz

Bir kare gibi

Merak etmezsen, söylemezsen

Şarkını, tınını hissetmezsen

Ne resmin, ne sesin

Ne kırmızı, ne beyaz kalır

Hissetmezsen....', 'Haykırmadan sesini duydun mu  Sanırsın Akmadan damarlarından kan Kırmızı rengi Gördün mü sanırsın .......................... İstersen dans e...', ARRAY['Türk Edebiyatı','Şiir','Güler Ilgaz']::text[], 8.5, '{"poet":"Güler Ilgaz","poet_slug":"guler-ilgaz","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/kirmizi-beyaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dağlar', 'daglar-altay-taskin-rp4i8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'güvenin

başı bulutlu dağlar

insan ayağı

değmeyeceği için

soğukluğunuz

hissedilir ama

üşütür esintiniz

beşiğindeki bebeği

                                 yeter ki

                                 güneşle dost olun

                                 sıcaklığınızı

                                 hissedelim öğleyin

                                 üşümesin

                                 temiz kalpli

                                 uyuyan bebeğim', 'güvenin başı bulutlu dağlar insan ayağı değmeyeceği için soğukluğunuz hissedilir ama üşütür esintiniz beşiğindeki bebeği                    ...', ARRAY['Türk Edebiyatı','Şiir','Altay Taşkın']::text[], 8.5, '{"poet":"Altay Taşkın","poet_slug":"altay-taskin","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/daglar-37-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gölge', 'golge-altay-taskin-joh7i', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'sabahı kucaklayan kollar

neredesiniz öğleyin

güneşin dikliğine isyan

gölge yaşamayı unutmuş

somutu yansıtamamanın

ezikliği içinde

sabah güneş gülümsemeden

soyutluğunu koruyan gölge

hep var kendince

görünür güneş gülünce', 'sabahı kucaklayan kollar neredesiniz öğleyin güneşin dikliğine isyan gölge yaşamayı unutmuş somutu yansıtamamanın ezikliği içinde sabah güne...', ARRAY['Türk Edebiyatı','Şiir','Altay Taşkın']::text[], 8.5, '{"poet":"Altay Taşkın","poet_slug":"altay-taskin","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/golge-36-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*İskemle üzerinde Hayat**', 'i-skemle-uzerinde-hayat-i-lkgul-celebioglu-g7tmf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hayatın iskemlesine oturmuşuz işte

Kâh oturmaktan yorulup kalkmışız

Kâh oturmaktan  monotanlaşmışız

Ne garip istedikçe istemeye alışmışız

Doyumsuz gibiyiz herşeye....

Neyi ne için yaptığımızın farkındamıyız acaba! 

Hayata hangi gözle hangi çerçeveden bakıyoruz..

Bacağı kırık bir iskemle 

Tamir görmeye alışmış bir yürek

Ve cebinde karın tokluğu diye 3 kuruş

Ne simalar tanıyoruz her geçen gün

Ağlamayı öğrendik bu iskemle üzerinde ve gülmeyi

Varlığı ve yokluğu,

Acıyı, sevinci ve kederi öğrendik

Birde öğrenemidiklerimiz var 

Rafın üzerinde bizi bekleyen

Süslü bir karalama kağıdına sıkıştırmaya çalıştığımız

Birde Ömür....

Hayatı üzerine oturttuğumuz bu iskemleyi

Sağlamlaştırdık mı acaba?', 'Hayatın iskemlesine oturmuşuz işte Kâh oturmaktan yorulup kalkmışız Kâh oturmaktan  monotanlaşmışız Ne garip istedikçe istemeye alışmışız Do...', ARRAY['Türk Edebiyatı','Şiir','İlkgül Çelebioğlu']::text[], 8.5, '{"poet":"İlkgül Çelebioğlu","poet_slug":"i-lkgul-celebioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/iskemle-uzerinde-hayat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umutlar', 'umutlar-altay-taskin-bfr1s', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'yaşamın zincirleri kopmuş salıncağında

                                             sallanan umutlar

örümcek ağı kadar ince basit durağan

yaşlanmış yüz hatlarında sayılan kırışıklıklar

derinliği bilinmeyen bulanıklık

işlenmemiş oniks duvarlarda

yalnız başına dolaşan bulutlar

betimlenemeyen bir varlık

tutunacak bir dal bulamamış

                                               uçsuz bucaksız umutlar', 'yaşamın zincirleri kopmuş salıncağında                                              sallanan umutlar örümcek ağı kadar ince basit durağan ya...', ARRAY['Türk Edebiyatı','Şiir','Altay Taşkın']::text[], 8.5, '{"poet":"Altay Taşkın","poet_slug":"altay-taskin","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/umutlar-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Alkole yenik düşme arkadaş**', 'alkole-yenik-dusme-arkadas-i-lkgul-celebioglu-27jkp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir rakı şişesine satıldı mı duygular

Ve hayaller

Kadeh kadeh yudum yudum giden

Bir rakı şişesine...

vazgeçmek bu kadar mı zordu

Alkole yenik mi düşmeli duygular? 

Alemine takılmış gidiyorsun Arkadaş

Bana huzur veriyor dediğin

''o sirkeli su''

seni nekadar hayata bağlar

Ne kadar hayallerini yaşatır

Ne kadar nereye kadar mutlu eder ki seni? 

Arkadaş ortamı dediğin 3 günlük alem

Oysa bir bilsen

birbilsen arkadaş

Dünyada farkına varamadığın 

Öyle güzellikler var ki....

Bu güzelliklerin

farkına varman dileği ile...', 'Bir rakı şişesine satıldı mı duygular Ve hayaller Kadeh kadeh yudum yudum giden Bir rakı şişesine... vazgeçmek bu kadar mı zordu Alkole yeni...', ARRAY['Türk Edebiyatı','Şiir','İlkgül Çelebioğlu']::text[], 8.5, '{"poet":"İlkgül Çelebioğlu","poet_slug":"i-lkgul-celebioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/alkole-yenik-dusme-arkadas-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece Sesi', 'gece-sesi-altay-taskin-xt3v0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'geceleri bir ses duyardım

işlenirdi nakış nakış güzellik

karanlık ufuklar aydınlanırdı

yorgunluğum şöyle bir kenarda

alır başımı sessizce dolaşırdım

mutluluğun çalgıcısı tepemde

sabah doğan güneşle uyanırdım', 'geceleri bir ses duyardım işlenirdi nakış nakış güzellik karanlık ufuklar aydınlanırdı yorgunluğum şöyle bir kenarda alır başımı sessizce do...', ARRAY['Türk Edebiyatı','Şiir','Altay Taşkın']::text[], 8.5, '{"poet":"Altay Taşkın","poet_slug":"altay-taskin","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/gece-sesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocuk ve Zaman', 'cocuk-ve-zaman-altay-taskin-a36v8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'çekişme çocuk zamanla

zaman da yaşlanır zamanla

sen tomurcuksun 

tomurcuk kal

zamanı bırak

atlı karıncalara

uçan balonlara

kendi dünyanı bulmuşsun

hayallerini kurmuşsun

bizim dünyamız elek gibi

ne koysan dökülüyor

tohum-maya tutmuyor

çocuk sen zamanla 

oyun oynama

tutarsa elinden

seni götürür

ayrılıklara-acılara

dumanlı manzaralara...', 'çekişme çocuk zamanla zaman da yaşlanır zamanla sen tomurcuksun  tomurcuk kal zamanı bırak atlı karıncalara uçan balonlara kendi dünyanı bul...', ARRAY['Türk Edebiyatı','Şiir','Altay Taşkın']::text[], 8.5, '{"poet":"Altay Taşkın","poet_slug":"altay-taskin","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/cocuk-ve-zaman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman', 'zaman-altay-taskin-d17jf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'sudan çıkmış zaman

sırılsıklam

her geçen gün 

çekiyor durmadan

adımlar küçülüyor

zaman şimdi önümde

ip atlıyor...', 'sudan çıkmış zaman sırılsıklam her geçen gün  çekiyor durmadan adımlar küçülüyor zaman şimdi önümde ip atlıyor......', ARRAY['Türk Edebiyatı','Şiir','Altay Taşkın']::text[], 8.5, '{"poet":"Altay Taşkın","poet_slug":"altay-taskin","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/zaman-160-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adını Gül Koymalı', 'adini-gul-koymali-aydogan-yavasli-q1a6k', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '1.

içimde çoğalan kadim sancı

tepelerde söze ersin

gül koymalı bu yaranın

kanayan arsız adını

-ey bozguna tutkun yürek

uzaksa eğer çölde görülen

imgesini saklı yaz

2.

akışa sesini veren

biliyorum bir hoyrat sudur

şimdi gider çizgisiz

acıyı devşirip yollara

büyütsün gayrı sokakları

şalındaki suskun koku

gün yutarken akşamı

-ey kavgaya tutkun yürek

gül koymalı bu sevdanın

yaşanan eskil adını', '1. içimde çoğalan kadim sancı tepelerde söze ersin gül koymalı bu yaranın kanayan arsız adını -ey bozguna tutkun yürek uzaksa eğer çölde gör...', ARRAY['Türk Edebiyatı','Şiir','Aydoğan Yavaşlı']::text[], 8.5, '{"poet":"Aydoğan Yavaşlı","poet_slug":"aydogan-yavasli","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/adini-gul-koymali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elf-i Şehr', 'elf-i-sehr-sukru-ozmen-0vp33', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Saçlarımda sapsarı

Zehirli bir sonbahar

Binicisiz dizginsiz

Gemsiz koşuyor

İçimde atlar

Kadir mi Arefe mi? 

Bayram mı bu hülasa

Ellerimde kıpkızıl

Soysuzların kanı var

Nitekim netice mi? 

Nasılların içinde

Buruyor deli cellat

Sihrimi yeryüzüyle

Dünyayı göğsünün kıllarına

Gömmüş düşünen adam

Yemiş bitirmiş işte

Elinde kalan hazan

Kafiyede kafiye

Bıktırdı döngü artık

Yaşamakta bir şey yok

Göğsüme süngü artık...

Kasım 2004', 'Saçlarımda sapsarı Zehirli bir sonbahar Binicisiz dizginsiz Gemsiz koşuyor İçimde atlar Kadir mi Arefe mi?  Bayram mı bu hülasa Ellerimde kı...', ARRAY['Türk Edebiyatı','Şiir','Şükrü Özmen']::text[], 8.5, '{"poet":"Şükrü Özmen","poet_slug":"sukru-ozmen","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/elf-i-sehr-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayan-Beyan Ziyan...', 'ayan-beyan-ziyan-sukru-ozmen-lkif2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İkliminde bir ömür 

Yanıp tükenmek kolay

Sen beni var etmeden

Beni vasıl etmeden

Ruhumu öteye aç

Derdimi ziyan eyle

Aşkınla nar eyleyip

As beni çarmıhlara

Yüreğimi kavurup 

En şedit ızdırapla

Hakir edip gönlümü

Cezamı beyan eyle

Sevgili ey sevgili

Kat gölgeni cesedime

Kabul et niyazımı

Kulak ver inlememe

Ya çek perdelerini

Ya cemalin ayan eyle

Aralık 2004', 'İkliminde bir ömür  Yanıp tükenmek kolay Sen beni var etmeden Beni vasıl etmeden Ruhumu öteye aç Derdimi ziyan eyle Aşkınla nar eyleyip As b...', ARRAY['Türk Edebiyatı','Şiir','Şükrü Özmen']::text[], 8.5, '{"poet":"Şükrü Özmen","poet_slug":"sukru-ozmen","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/ayan-beyan-ziyan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kedim', 'kedim-altay-taskin-cy65d', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'bir kedim var

gözleri ışıl ışıl yanar

soğuk kış gecelerinde

sobanın yanında yatar

pamuk gibi tüyleri

iri iri gözleri

bıyıkları uzun

işe yaramaz sözleri

çok sever sıcağı

uykuya dalar

bir et koklatınca

hemen gözlerini açar

yumağı da çok sever

onu top zanneder

yuvarlar önünden

yakalamayı düşler', 'bir kedim var gözleri ışıl ışıl yanar soğuk kış gecelerinde sobanın yanında yatar pamuk gibi tüyleri iri iri gözleri bıyıkları uzun işe yara...', ARRAY['Türk Edebiyatı','Şiir','Altay Taşkın']::text[], 8.5, '{"poet":"Altay Taşkın","poet_slug":"altay-taskin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kedim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Adsız', 'bir-adsiz-erdogan-ergin-q8src', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'okudum,

dinledim

ama anlamadım

niçin? 

bu kadar zahmet

değer mi? 

tarih yetmez mi? 

ille de tarih kitaplarında mı okunmalı? 

tekerrürler

fikirler

yazık

milattan önce bilinen

milattan sonra bilinmiyor

yazık

hala sırtlanlardan

kurda dost aranıyor

dinle

bu ses

bir adsızın sesi

diğer adsızlar gibi', 'okudum, dinledim ama anlamadım niçin?  bu kadar zahmet değer mi?  tarih yetmez mi?  ille de tarih kitaplarında mı okunmalı?  tekerrürler fik...', ARRAY['Türk Edebiyatı','Şiir','Erdoğan Ergin']::text[], 8.5, '{"poet":"Erdoğan Ergin","poet_slug":"erdogan-ergin","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bir-adsiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmurlar Asla Yalan Söylemez', 'yagmurlar-asla-yalan-soylemez-galip-sinecikli-nmc4t', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'yağdığı zaman yağmurlar 

ve yüzüne düşünce damlalar 

ıslaklığını hissedince havanın 

yerden yükselen toprak kokusu yakarsa genzini 

anlarsın yalan olmadığını 

rüya olmadığını

yaşamanın 

yaşanmanın 

yaşatmanın gerçekliğini hissedersin 

işte o zaman anla ki

yağmurlar asla yalan söylemez...

www.galipsinecikli.com', 'yağdığı zaman yağmurlar  ve yüzüne düşünce damlalar  ıslaklığını hissedince havanın  yerden yükselen toprak kokusu yakarsa genzini  anlarsın...', ARRAY['Türk Edebiyatı','Şiir','Galip Sinecikli']::text[], 8.5, '{"poet":"Galip Sinecikli","poet_slug":"galip-sinecikli","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yagmurlar-asla-yalan-soylemez-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zalimin Zulmü', 'zalimin-zulmu-hifzi-ozbekmez-4ifzp', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'ZALİMİN ZULMÜ

Mazluma bu zulümde havaleyse Allah’a

Perişanız biliniz mahşerde de billaha 

Hadi kuşan silahı yoksa imanın yeter

O kafiri edelim doğduğuna bin beter

Zalimin zulümleri ne yaralar açıyor

Kudurmuş köpek gibi kanımızı içiyor

İnsanlık unutulmuş haya dersen ne gezer

Uyan artık Müslüman imanın zulmü ezer

Yeter artık bu zulüm yeter artık göz yaşı

Yeter artık zehirse yediğin ekmek aşı

Zalimin zulmüne sen göz yumma uyan artık

El ele ver  omuz ver zorluğa dayan artık

İslamın üzerinde felaket dolanıyor

Örtülü kadınıma kefere sulanıyor

Zalimin zulmü varsa sende getir adalet

Yardım edecek  Allah   gayret etki sen elbet

Al yüreğin eline kartal gibi uç artık

Bu nefsi müdafaadır inan değil suç artık

Müslümanlar birleşsin versinler hep el ele

Artık bahtımız gülsün gönlüm dolsun bir güle 

Ey peygamber ümmeti ey kulları Allah’ın  

Tan ağardı bak artık hayır olsun sabahın

Alınmasın yeter artık kardeşimin canları

Yollarına fedadır latifinin kanları

04  ARALIK  2004 SAAT: 20:00

SAMANYOLU GRUBUNUN 2 KELİME  1 ŞİİR AKTİVİTESİ İÇİN YAZILMIŞTIR 

KELİMELER: ZALİM / MAZLUM

''Aşağıdaki isim linkini tıklayarak, bu haftanın aktivitesine katılan diğer bir arkadaşımızın şiirlerini okuyabilirsiniz.'' 

 ekrem Şama', 'ZALİMİN ZULMÜ Mazluma bu zulümde havaleyse Allah’a Perişanız biliniz mahşerde de billaha  Hadi kuşan silahı yoksa imanın yeter O kafiri edel...', ARRAY['Türk Edebiyatı','Şiir','Hıfzı Özbekmez']::text[], 8.5, '{"poet":"Hıfzı Özbekmez","poet_slug":"hifzi-ozbekmez","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/zalimin-zulmu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kadınıma yemin olsun', 'kadinima-yemin-olsun-neco-erunsal-h6zy7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir gün gelirde, 

Acımtırak tadında kalırsa 

Sana seviyorum çığlıkları atan dudaklarım 

Bil ki bir daha açılmayacak kadar 

Suskulara gömülür dilsiz kalır yüreğim 

_________________sevdaya aşka dair 

Bir gün gelirde 

Kadınını yitirirse tenim 

Hiç gün yüzü görmeyecek kadar derinlere gömerim 

Bir gün sesini duymazsa kulaklarım 

Hiçbir aşka açılmayacak kadar sağırlaşırım 

Bir gün yitirirsem kadınımı 

Ne tenime 

Ne gözüme 

Ne ellerime 

Ne de bu dünyaya 

Minnet borcumu ödemeye yeltenirim 

Ya seninle ya hiç....... 

Her limanında yeniden doğarım ben 

Her vira/ nda asılırım sancak direklerine 

Her mavinde süzülürüm en derinlere 

Her yakamozunda parlarım 

Fırtınan sonrasında sana yanaşırım usulca 

Siyahında al kırmızısına boyarım sevda tomurcuklarımı 

Geceleri dörtnala koşan mavi pelerinli süvari olur sevdam 

Savaşlarımın meydanlarımdaki zafer kırmızısı kadın 

Seni dilek ağaçlarına astım mavi yazmam 

Duyuyor musun? .. 

Bu 

____________________aşkıma yeminim', 'Bir gün gelirde,  Acımtırak tadında kalırsa  Sana seviyorum çığlıkları atan dudaklarım  Bil ki bir daha açılmayacak kadar  Suskulara gömülür...', ARRAY['Türk Edebiyatı','Şiir','Neco Erünsal']::text[], 8.5, '{"poet":"Neco Erünsal","poet_slug":"neco-erunsal","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/kadinima-yemin-olsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'SİBEL''E (akrostiş)', 'si-bel-e-akrostis-muzaffer-erdogan-pvsg0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sarhoş olmuşum bir derdim var

inan beni benden eden birileri var

Ben böyle değildim böylemi oldum

Ellerim bom boş yüreğim bir hoş

Leyla olmuş savrulmuşum ben

Ebed''de liman olmuş durulmuşum ben

not:Mehmet Ali Mızrak''tan alındı', 'Sarhoş olmuşum bir derdim var inan beni benden eden birileri var Ben böyle değildim böylemi oldum Ellerim bom boş yüreğim bir hoş Leyla olmu...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Erdoğan']::text[], 8.5, '{"poet":"Muzaffer Erdoğan","poet_slug":"muzaffer-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/sibel-e-akrostis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Seni Sevdim', 'ben-seni-sevdim-i-nan-alver-n8c6k', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ben seni kusursuz tenin için sevmedim,

Sevginin tenime kattığı ateş için sevdim.

Ben seni güzel gözlerin için sevmedim,

Gözlerinin gönlüme kattığı anlam için sevdim.

Ben seni sıcak dudakların için sevmedim,

Dudaklarından dökülen, sevdanın yankısı sözlerin için sevdim.

Ben seni güzel ellerin için sevmedim,

Ellerine elime değil,yüreğime dokunabildiğin için sevdim.

Ben seni yürüdüğümüz yollar için sevmedim,

Yüreğimizin götürdüğü yere,asla yalnız yürümeyeceğimiz için sevdim,

Ben seni beni öptüğün için sevmedim,

Ilık nefesini içime çekebildiğim,senden bir şeylerin içimde olduğu için sevdim.

Ben seni zamanlarıma mutluluk kattığın için sevmedim,

Tüm zamanları aşıp,özlemleri bir sarılmayla yendiğimiz için sevdim.

Ben seni sevgilim olduğun için sevmedim,

Sevgimin en saf haliyle,sonsuza kadar kalbinde yaşayacağı için sevdim.', 'Ben seni kusursuz tenin için sevmedim, Sevginin tenime kattığı ateş için sevdim. Ben seni güzel gözlerin için sevmedim, Gözlerinin gönlüme k...', ARRAY['Türk Edebiyatı','Şiir','İnan Alver']::text[], 8.5, '{"poet":"İnan Alver","poet_slug":"i-nan-alver","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ben-seni-sevdim-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yarınlara', 'yarinlara-behcet-gulenay-8zhpa', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'bir çocuğun gözlerinden biriktirdim bu yaşları

tüm insanlar içindir kaygım…

aldılar işte gözlerimden gökyüzünü

öfke tütüyor bacalar 

üzerimize salınan kirli maviye el sallayarak

suratına tüküreyim bu ödünç, defolu hayatın

çalıntı bir uykudan her gün 

kâbuslarla uyanıyor çocuklar

yeni mevsimler başlatmalıyım

yağmurlar yağmalı ardı ardına

daha coşkun akmalı nehirler

her yer ıslanmalı iliğine kadar

ateş ki yakacak yer bulamamalı 

güvercinler uçurmalıyım

tutuşmalı vuslat yangınları göğüs kafeslerinde

kanatlanmalı yeniden aşklar

ağıtlar yerine 

gülümseyen şarkılar söylenmeli

peydahlanan düşmanlığa inat

bir rüzgâr esmeli

yenibaharlarda açan badem çiçekleri gibi

özlem(in)  kadar yakın

bu kardeşlik döllenmeli

öyle bir kucaklamalıyım ki 

kaybedilmiş sesine kavuşmalı insanlar

vazgeçmek yok

geceyi uyandıralım uykusundan

aç o pencereyi

gittikçe koyulaşan bu karanlık dağılmalı

                                             Mart 2001

Behçet Gülenay', 'bir çocuğun gözlerinden biriktirdim bu yaşları tüm insanlar içindir kaygım… aldılar işte gözlerimden gökyüzünü öfke tütüyor bacalar  üzerimi...', ARRAY['Türk Edebiyatı','Şiir','Behçet Gülenay']::text[], 8.5, '{"poet":"Behçet Gülenay","poet_slug":"behcet-gulenay","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/yarinlara-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Artık', 'artik-yusuf-cinar-do58s', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'herşey ince bir detay olmaktan çıktı 

ve kanayan bir yarayım artık hayatımda

sen yine çıkmıyorsun köşeden 

ve soğuk bir rüzgar esiyor yüreğimden

ardından buzdan bir ok düşüyor 

saplandığı yüreğimden 

kap katı olmuşum

aldırmıyorum.

yüreğimde ayak izlerin hala saklı duruyor.

ayakların 39 numara ama

izleri sonsuz sayııııııııı

çünkü her kalp atışımda biraz daha

büyüyorlar ve ben yine silemiyorum 

ayak izlerini yüreğimden...

ağlamak istiyorum 

sanki bişeyler boğazıma düğümleniyorda 

ben bağıramıyorum ve ağlayamıyorum 

sadece yutkunuyorum.

hayata dair ne varsa 

hepsini proteste etmek için 

avazım çıktığı kadar susuyorum 

ve sessizliğimle tüm yalancı sesleri protesto ediyorum...

ve sonsuzluga dair ne varsa içimde 

hepsini yarına saklıyorum,

yarını ise bugüne

bugünü ise bu ana

bu anı ise sonsuzluğa saklıyorum 

ve

kahretsin bugünde ölemiyorum.', 'herşey ince bir detay olmaktan çıktı  ve kanayan bir yarayım artık hayatımda sen yine çıkmıyorsun köşeden  ve soğuk bir rüzgar esiyor yüreği...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Çınar']::text[], 8.5, '{"poet":"Yusuf Çınar","poet_slug":"yusuf-cinar","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/artik-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin Gibisi', 'senin-gibisi-necat-necdet-demircan-v5hzm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ne senin gibisi var

Ne taparcasına aşıklar

Yumuşak olsa da yastıklar

Dizlerine hasret uykular

Kolay değil elbet ayrılıklar

Çıngılar ateşler

Sular kar etmez

Aşktır o, sönmeyesi yangınlar

Olmasa ucunda kavuşmalar

Gözlerimden hasretler akar

Sen yoksan yokum

Hayalin ve bir de ben

O kadar çokum

Işık hızı yaşanmışlığın

Devir daim hatıralar

Sensizlik karaborsada

Yetmez gücüm ulaşmaya

Belki bu yüzden umutsuzum...

Ne senin gibisi var

Ne beyaz yağar karlar

Sıcak olsa da sensiz yazlar

Eritir beni sensizlik

Yıkar kum kalelerini

Dalgalar çarpar, çarpar, çarpar

Ve eritir ruhumu azar azar...', 'Ne senin gibisi var Ne taparcasına aşıklar Yumuşak olsa da yastıklar Dizlerine hasret uykular Kolay değil elbet ayrılıklar Çıngılar ateşler ...', ARRAY['Türk Edebiyatı','Şiir','Necat Necdet Demircan']::text[], 8.5, '{"poet":"Necat Necdet Demircan","poet_slug":"necat-necdet-demircan","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/senin-gibisi-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Sana', 'seni-sana-necat-necdet-demircan-zdfw2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Seni sana benzetiyorum

Kimi zaman bir müzik; 

Son anda radyoda yakalanan

Bir klasik

Ezelden ebede uzanan

Bir tablo; 

Kimi zaman pastelde hüzün

Kimi zaman ateş kırmızısı rengin

Mehtap; 

Ya siyah bulutlar arkasında

Yalnızca adı bilinen

Ya yakamoz

Kıpır kıpır yürekte hissedilen

Seni sana benzetiyorum

Gözyaşı, ama akmayan

Bir eşi daha yok

Her şeyiyle, güzelliğiyle

Bazen yalnızca benim

Çok alımlı kimi zaman

Hani hayatı hiç takmayan...

Seni tanımlıyorum

Şıpsevdi yaşamların hovarda çiçeği

Görür kalbin elbet gerçeği

Başka türlü betimliyorum

Bildiğin gibi

Seni sana benzetiyorum...', 'Seni sana benzetiyorum Kimi zaman bir müzik;  Son anda radyoda yakalanan Bir klasik Ezelden ebede uzanan Bir tablo;  Kimi zaman pastelde hüz...', ARRAY['Türk Edebiyatı','Şiir','Necat Necdet Demircan']::text[], 8.5, '{"poet":"Necat Necdet Demircan","poet_slug":"necat-necdet-demircan","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/seni-sana-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Döşeğim', 'dosegim-altay-taskin-ovug0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ne güzeldir döşeğim

titrerken ben

altı da sıcak üstü de

sevgiyle sarar beni

kış gecelerinde', 'ne güzeldir döşeğim titrerken ben altı da sıcak üstü de sevgiyle sarar beni kış gecelerinde...', ARRAY['Türk Edebiyatı','Şiir','Altay Taşkın']::text[], 8.5, '{"poet":"Altay Taşkın","poet_slug":"altay-taskin","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/dosegim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kim İster', 'kim-i-ster-altay-taskin-37wpp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'kim ister görmeyi

bir ağaç kesilirken

akmayan bir çeşmeyi

kim ister görmeyi

uçamayan bir kuş

yüzemeyen bir ördeği

zıtlıklar ümit ateşlerini

söndüren suya benzer

acı verir insana

kim ister acı çekmeyi', 'kim ister görmeyi bir ağaç kesilirken akmayan bir çeşmeyi kim ister görmeyi uçamayan bir kuş yüzemeyen bir ördeği zıtlıklar ümit ateşlerini ...', ARRAY['Türk Edebiyatı','Şiir','Altay Taşkın']::text[], 8.5, '{"poet":"Altay Taşkın","poet_slug":"altay-taskin","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/kim-ister-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mutlu Bir Gün', 'mutlu-bir-gun-necat-necdet-demircan-57i0k', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sabah güneş doğduğu zaman

Mutluluk ışığıyla dolacak her yer

Neşeyle geçecek bütün günüm

Sevgimle çıkacağım odamdan

Adımlarım bile seni düşünecek

Yürünen hedefin adı: ''Mutluluk''

Çam ağaçlarının yaprakları hayalin

Usulca bir rüzgar esecek, üşüyeceğim

Ve kokuna gülümseyeceğim

Gün batarken dağların ardında

İlk kez bestelenen bir melodi

Hep benimle, seninle

Yanında

Yanımda

Tek bir parça

Öylesine mutlu bir gün

İsmin ebedi bir yanıt taş anıtlarda

Sevgi olup dolaşacaksın kanımda...', 'Sabah güneş doğduğu zaman Mutluluk ışığıyla dolacak her yer Neşeyle geçecek bütün günüm Sevgimle çıkacağım odamdan Adımlarım bile seni düşün...', ARRAY['Türk Edebiyatı','Şiir','Necat Necdet Demircan']::text[], 8.5, '{"poet":"Necat Necdet Demircan","poet_slug":"necat-necdet-demircan","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/mutlu-bir-gun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen', 'sen-necat-necdet-demircan-srzfx', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kadife yanaklım

İpek tenli al dudaklım

Saçlarının hissi saadet

Ezelden beyaz püru pak duvaklım

Gök mavisi düşlerim

Pamuk bulut öpücüklerim

Araladığım kapı

İşte benim hislerim

Bu bir gen

Kötü duygulardan men

Soru benim

Benim problem

Cevapsın kainata

Analizsin

Yanıtsın

Sonuçsun...

Bu sensin Sen...', 'Kadife yanaklım İpek tenli al dudaklım Saçlarının hissi saadet Ezelden beyaz püru pak duvaklım Gök mavisi düşlerim Pamuk bulut öpücüklerim A...', ARRAY['Türk Edebiyatı','Şiir','Necat Necdet Demircan']::text[], 8.5, '{"poet":"Necat Necdet Demircan","poet_slug":"necat-necdet-demircan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sen-482-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kötü Anlar', 'kotu-anlar-necat-necdet-demircan-vcimf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sıkıştırma beni iki dudak arasına

Karıştırma

Dedikodu olmasın

Özetleme beni

Bırakma laf arasına

Öylesine bahsetme

Yaşandı, bitti deme

Geldiğin gibi uzun olsun kalışın

Ansızın çarpma kapıları, gitme

Sıkıştırma beni günlüklerine

Yapraklar yetse de anlatmaya

Bir kalem karası olmasın

Basitse sende kalsın anlatacakların

Kıyma bana

Değer bul üzülmeye

Çizme üzerimi

Yeltenme bir kalemde silmeye

Filizlenir

Birden büyümez tohumlar

Büyür

Hemen kırılmaz yapraklanan dallar

Sus

Sessizliği zerk et damarlarına

Bir gün için olsun çiçekleri giyin

O kötü saydığın anların hatırına...', 'Sıkıştırma beni iki dudak arasına Karıştırma Dedikodu olmasın Özetleme beni Bırakma laf arasına Öylesine bahsetme Yaşandı, bitti deme Geldiğ...', ARRAY['Türk Edebiyatı','Şiir','Necat Necdet Demircan']::text[], 8.5, '{"poet":"Necat Necdet Demircan","poet_slug":"necat-necdet-demircan","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/kotu-anlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşasaydın Halbuki', 'yasasaydin-halbuki-burcu-alpaslan-guvenli-trdle', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kapalı   kutunda   imzaladın

__________mahkumluğunu

