INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Galanthus Nivalis (Kardelen)', 'galanthus-nivalis-kardelen-ahmet-hakan-yilmazturk-nw50g', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'mecazına gençlik çağının, kar vursa da 

aşkına kuvvet, başkaldırsın kardelenler

verdiği coşkuyla bu aşırılığı baharımın

çiçeklerini densizce yaysın kardelenler 

nazenin tarifidir, bir elif ki pek kırılgan

buzda kayan yürek yongası kardelenler

mevsimi şaşıp seven gönüllere taşmada

gökten düşmüş opalin sırça kardelenler

mecazına gençlik çağının, kar vursa da 

aşkına kuvvet, başkaldırsın kardelenler

16.12.2004', 'mecazına gençlik çağının, kar vursa da  aşkına kuvvet, başkaldırsın kardelenler verdiği coşkuyla bu aşırılığı baharımın çiçeklerini densizce...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Hakan Yılmaztürk']::text[], 8.5, '{"poet":"Ahmet Hakan Yılmaztürk","poet_slug":"ahmet-hakan-yilmazturk","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/galanthus-nivalis-kardelen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ee Uuu Brüksel Lahanası', 'ee-uuu-bruksel-lahanasi-akin-akca-8r0xd', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Buğu

Eski binalarıyla 

övünen tuhaf yaratıklar; 

ne diyeyim, 

onlar, bu yapılar 

 da yüceltirler.

Fakat, garip çünkü,

olur mu insan ünlü; 

sahip çıktığı eserlerin

 çürütürken çok çok azını? 

(Gerçek sorundur bu

çözülmesi zorunlu; 

nefes veren ormanları

denizleri...

korumak kadar....)

Ya da yukarıdaki

Mir''in Çariçe dansı 

yapan gölge etkisi

 bile işler dururken

...

*

16Aralık

Fakat,

En güzelidir yeni bir şeye başlamak

ve yeni kalarak eskimekse en zoru.

Bundan daha teleşlıdır ama 

eskidiğini, büzüldüğünü görmek.

ve bedbinlerin ortasında yaşamak

bunu, bir önceki denilenin getirisi,

en berbatıdır herhalde.

Hepsinin ötesinde, yeni olan 

en güzeldir, ışık veren, her zaman.

Eskirkense savunmak bir deli

mücadeleyi fakat daha mükemmeldir:

Hemzemin tünellerinde güneşin

kilometre taşlarının umut eri,

baki barındırdığı ancak çabaladığı.

Ama onur dolu bu, içtiğindir su.

Yaşlanırken bir değil birkaç kıta,

eğer verebiliyorsan siyasetin 

suratına hoş musikiden değer nota; 

o zaman işte şafaklar tan ağarışıyla

günbatımlarıdır da: eminsindir -

istikbalden- ilelebet yükseltecek

muhabbet; havadaki kanat, şiir, 

resim, hayal gücü yaratıdır elbette; 

fidan, ağaç ağaç olduğunda, sanat.

Güç ordadır, duy ilhama sadakat.

Buna inanıyorsan, kıpırdıyorsun; 

Dinazor yumurtası yiyerek 

beslenen kemirgen memelinin yerini 

tek hücreliye tekrar devredişi

pek de bir şey ifade etmez o zaman

-

2004', 'Buğu Eski binalarıyla  övünen tuhaf yaratıklar;  ne diyeyim,  onlar, bu yapılar   da yüceltirler. Fakat, garip çünkü, olur mu insan ünlü;  s...', ARRAY['Türk Edebiyatı','Şiir','Akın Akça']::text[], 8.5, '{"poet":"Akın Akça","poet_slug":"akin-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":55,"source_url":"https://www.antoloji.com/ee-uuu-bruksel-lahanasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Devinmek', 'devinmek-gokhan-oflazoglu-et9wi', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İnsan kendinde olmayanı özler.

Olan vardır zaten, devinmez.

Sıkılırız durağanlıktan, uçurum

kenarında bekleriz; bir başdönmesine

özlem. Bilensin isteriz duyularımız.

Tehlike de olsa imkan sayarız; 

devinsin diye kaynaklarımız.

Dönüşürüz sonunda özlediğimize,

ne dönüştüğümüz var artık, ne biz varız.

16/12/2004', 'İnsan kendinde olmayanı özler. Olan vardır zaten, devinmez. Sıkılırız durağanlıktan, uçurum kenarında bekleriz; bir başdönmesine özlem. Bile...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Oflazoğlu']::text[], 8.5, '{"poet":"Gökhan Oflazoğlu","poet_slug":"gokhan-oflazoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/devinmek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayır Ve Şer', 'hayir-ve-ser-ekrem-sama-6sp3y', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İlahi bir hüküm var, şöyledir:

“Hayrın kaybolmaz zerresi bile,

Şerlerin durumu da böyledir,

Beraber gider yapanlar ile...“

(İstanbul:15.12.2004)', 'İlahi bir hüküm var, şöyledir: “Hayrın kaybolmaz zerresi bile, Şerlerin durumu da böyledir, Beraber gider yapanlar ile...“ (İstanbul:15.12.2...', ARRAY['Türk Edebiyatı','Şiir','Ekrem Şama']::text[], 8.5, '{"poet":"Ekrem Şama","poet_slug":"ekrem-sama","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/hayir-ve-ser-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öleyim mi', 'oleyim-mi-gonul-ozdemir-qj20t', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Öleyim mi

Kalem tutan ellerim titrer oldu,

Ağlamaktan göz pınarlarım kurudu,

Birazcık ümidim vardı,oda yok oldu,

Söyle bana bir tanem öleyim mi.

Kaybolan ümitlerimin içinde teksin,

Dokunacak kadar yakın,ama hayalsin.

Yalnız gecelerimde tek gerçeksin

Söyle bana aşkım,öleyim mi.

Bir gün çok çok uzaklara gideceğim,

Kalbimde unutulmaz,aşkını götüreceğim

Teselli olmuyor artık kalbim,

Söyle bana can yoldaşım,öleyim mi.

Ne sigaram ne kahvem

Keyif vermiyor artık,eskisi gibi,

Geceler bile,avutmuyor artık beni,

Ömrünce,hiç kimse sevemez benim gibi seni.

Sonsuza kadar istemesende, seveceğim

Gönlüm söz dinlemiyor suç benim mi.

Yoluna bütün ömrümü feda edeceğim,

Dört kişinin omzunda,ölüme senin aşkınla gideceğim.

16.12.2002.    Gönül özdemir,  Almanya', 'Öleyim mi Kalem tutan ellerim titrer oldu, Ağlamaktan göz pınarlarım kurudu, Birazcık ümidim vardı,oda yok oldu, Söyle bana bir tanem öleyim...', ARRAY['Türk Edebiyatı','Şiir','Gönül Özdemir']::text[], 8.5, '{"poet":"Gönül Özdemir","poet_slug":"gonul-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/oleyim-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yol Uzun', 'yol-uzun-oguzkan-bolukbasi-967s8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Çok fazla olmadan elimize bulaşan kiri çıkarmakta yarar var

Sokaklar

Hafiye dolu

Zindanları boşaltmamakta ısrar eden

Tam ümidimi kesmişken gözlerinden

Sokağın sonundaki lambada karşıma çıktın

Aydınlattın

Beni saran karanlığı

Ne desem sana bilmem ki

Teşekkür edebilirim

Bir kez daha

Yürümeme sebep oluyorsun

Çünkü yol uzun aşkı yeniden bulmak için

Kahramanım yok benim

Ya da resmini astığım bir güzellik odalarıma

Sadece hayallerim

Benim yol gösterenim

Yol arkadaşım

Sen dediğim tüm ışıkların altından geçiyorum

Her yıldızı sen diye seyrediyorum

Olmuyor

Sen olmuyorsun

Benim hayallerim uzaklarda mı? 

Ya da hayallerim bile hayal mi? 

Hangi yaratılmışta göreceğim seni

Hangi sende beni bulacağım

Yol uzun

Ben uykusuzum', 'Çok fazla olmadan elimize bulaşan kiri çıkarmakta yarar var Sokaklar Hafiye dolu Zindanları boşaltmamakta ısrar eden Tam ümidimi kesmişken g...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/yol-uzun-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yek yek Memo...', 'yek-yek-memo-yusuf-ziya-leblebici-dde5l', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yalpalaya yalpalaya

Gidiyorsun düşe kalka

Bir o yana bir bu yana

Yürüyorsun ite kaka

Üç kadehte yıkılırsın

Sonra dünyayı yakarsın

Adımların karışınca

Çiftetelliye başlarsın

Zulalarda tek tek attın

Kazancını bir bir saçtın

Sen demirden korkar iken

Tepelerde tüfek attın

Bu ne hava bu ne civa

Ne oluyor yek yek Memo

Meydan okuma dağlara

Yıkamazsın sek sek Memo

Balona basarsak hava

Dolduruşa gelirsin ya

Zorluğu gördükten sonra

Dolmuşlardan inersin ya

Neredesin yek yek Memo

Buraya gel sek sek Memo

Ne yaptıysan sen bizimsin

Sahtekar da bilsek Memo', 'Yalpalaya yalpalaya Gidiyorsun düşe kalka Bir o yana bir bu yana Yürüyorsun ite kaka Üç kadehte yıkılırsın Sonra dünyayı yakarsın Adımların ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ziya Leblebici']::text[], 8.5, '{"poet":"Yusuf Ziya Leblebici","poet_slug":"yusuf-ziya-leblebici","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/yek-yek-memo-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tanıdığım Kadın Bir Hanımefendiydi', 'tanidigim-kadin-bir-hanimefendiydi-huseyin-erdogan-82crn', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'yıllar önceydi

belki de 

bana öyle geldi

tanıdığım kadın 

bir hanımefendiydi

bu güne değin 

hiç görmedik birbirimizi

arada bir olsa da 

duyardık sesimizi

ben onu sevmiştim 

o da beni

anladığım kadarıyla 

zarif biriydi

çok bakımlıydı 

şık giyinirdi

yaşını hiç mi hiç 

göstermezdi

belki de bütün maaşını 

giysiye verirdi

demek ki parasını 

kısa sürede bitirirdi

iyi ki onun babası vardı

beyefendi bir insan 

zengin bir adamdı

kızının 

harcamaları yüzünden

bazen de 

üç aylığına kalırdı

ama yine de 

ona dayanamazdı

ne bileyim işte 

kendisini bu güne kadar

hiç görmedim ki

zarafetli ve  güzel 

biri olduğu besbelliydi

benim özel hayatım 

hiç olmadı deyiverdi

bir gün 

istemeyerek de olsa 

beni terk ediverdi

neden diye sormadım 

o da bir şey söylemedi

ben de uzaktan da olsa 

kendisine diyorum ki

inan ki  hiç solmayacak 

bir gülsün sen

dilerim mutlu olur 

sen de gülersin 

hem de ebediyen

                                       16.12.2004', 'yıllar önceydi belki de  bana öyle geldi tanıdığım kadın  bir hanımefendiydi bu güne değin  hiç görmedik birbirimizi arada bir olsa da  duya...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Erdoğan']::text[], 8.5, '{"poet":"Hüseyin Erdoğan","poet_slug":"huseyin-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":50,"source_url":"https://www.antoloji.com/tanidigim-kadin-bir-hanimefendiydi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hamam çıkarmaz kirini ...', 'hamam-cikarmaz-kirini-yusuf-ziya-leblebici-gtibo', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Uğraştırma keseciyi

Hamam çıkarmaz kirini

İlif seni temizlemez

Atamazsın bu lekeyi

Fiyonk miyonk lacilerle

Hava buldun meclislerde

Yetim hakkı garip hakkı

Çeşit oldu mezelerde

Yıkan yıkanabilirsen

Günahı silebilirsen

İster sabun ister kille

Kazın kazınabilirsen

Uğraştırma keseciyi

Hamam çıkarmaz kirini

Zemzem dolsa kurnalara

Temizlemez tek elini

Parti dernek siyasette

Suçu örttün maskelerle

Utanmayı cebe koyup

Sırıttın hep vitrinlerde

Kalbin fesat dilin yalan

İnmiyor ki şişmiş havan

Etrafında yalamalar

Dürüst kalmış arta kalan

Uğraştırma keseciyi

Hamam çıkarmaz kirini

Bir bildiğin vardır senin

Hamamı da götür bari', 'Uğraştırma keseciyi Hamam çıkarmaz kirini İlif seni temizlemez Atamazsın bu lekeyi Fiyonk miyonk lacilerle Hava buldun meclislerde Yetim hak...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ziya Leblebici']::text[], 8.5, '{"poet":"Yusuf Ziya Leblebici","poet_slug":"yusuf-ziya-leblebici","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/hamam-cikarmaz-kirini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüzüne ayaz vursun', 'yuzune-ayaz-vursun-denizhan-solmaz-3ch4w', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hayata hangi pencereden bakarsan onu görürsün

ama sen hep güneyde kalki

yüzüne güneş vursun

ne kadar soğuk olursa olsun 

aradabir pencereni aç

yüzüne Ayaz vursun', 'Hayata hangi pencereden bakarsan onu görürsün ama sen hep güneyde kalki yüzüne güneş vursun ne kadar soğuk olursa olsun  aradabir pencereni ...', ARRAY['Türk Edebiyatı','Şiir','Denizhan Solmaz']::text[], 8.5, '{"poet":"Denizhan Solmaz","poet_slug":"denizhan-solmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/yuzune-ayaz-vursun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgiliye mektuplar', 'sevgiliye-mektuplar-denizhan-solmaz-d1dbx', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'ben... 

cığlık oldum 

sokağından geçen hırcın martılarda

ben... 

dalga dalga köpüklerine karıştım okyanusların 

yakomoz oldum 

sen 

albatrosumdun 

acık denizlerde...

fırtınalı havalarında 

ve hiç sürmedik şüphe  tarlalarını

hiç ekmedik kibir sevdamıza 

denizo', 'ben...  cığlık oldum  sokağından geçen hırcın martılarda ben...  dalga dalga köpüklerine karıştım okyanusların  yakomoz oldum  sen  albatros...', ARRAY['Türk Edebiyatı','Şiir','Denizhan Solmaz']::text[], 8.5, '{"poet":"Denizhan Solmaz","poet_slug":"denizhan-solmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sevgiliye-mektuplar-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rakamların Evrimsel Tarihi', 'rakamlarin-evrimsel-tarihi-evrim-nisan-ugw8h', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'masalın içinde keskin bir gerçeklik kokusu…her sesinde küllerinden yeniden doğuyordu zümrüdü anka kuşu..üzerini silkeleyerek parlak mavi tüylerini gösteriyordu güneşe.hiç yanmamış gözlerinin parıltısıyla titriyordu..artık başka yaşantılarımız var gerçekliği olmayan.. sesinin irkilttiği o yıllar kadar geçti zaman.. zümrüdü anka kuşu masallar kentine döndü...artık başka yaşantılarımız var kimsenin bilmediği.. ki kimse ikimiz(değil) dir ne zamandan beri.. di li geçmiş zamanda kalalı beri sakin sessiz ve artık savaşmayan o savaşçılar..o kırılan vazo.. yere çarptığında her tanesi bir sağanak yağmur yaratmıştı..kimi batıya kimi güneye inmişti parçalarının …bir yenik yelkenli gibi fırtınaya boyun eğmiş/aşağılanmış..oysa kendi ülkesinin sınırlarını nasıl kuşatmıştı (kendi olan sınırlarını)  artık başka sınırlarımız var..ve artık o sınırlarda biz yokuz..biz dediğin (sen dedin)  kim ki..o denli olamadığımız üç harf.. hep üçlerle çevrildiğimiz o günleri anımsa.. anımsayım..rakamların gizli ve bilinmez bedesteninde sihlerle bulmuş olmalıyız kendimizi..ve onlar da  sıfırı buldular.. sıfırı bulduklarında ne kadar yalnızdı düşünsene? bir sıfır ne kadar yalnız olabilir? dahası bir sıfır ne kadar yalnız olmayabilir? bir gün onu buldukları için kendi içine kapandı işte..ne kaldım? sıfırın o kocaman gözünden baktık kendimize.ne kaldım? bu soru gizli bir işleviydi ‘avucumdaki ne’ sorusunu sorduğumuz o günlerinden kalma çocukluğumuzun.o kadar –o çocuklar kadar mı o çocukluk kadar mı- mutluyduk demek ve o kadar hüznü taşıyorduk delik ceplerimizde.o ormanı anımsıyor musun? şimdi anımsamışsındır.şimdi anımsıyor musun diye soracağım ne varsa anımsatacak sana yitirdiklerini..oysa sorguda söylemeyeceklerin aklına gelmeli..ya! öyle! ben seni sevmişim ve sanki başkası yaşayıp bana söylemiş! sıfır dukalığı..krallığı..ben seni sevmişim..kaç sıfır koyarsın bunun içine? neresine koyarsın? peki şeyi anımsıyor musun? ya şeyi? onu da mı? tanrım! –adının ilk harfini küçük yazdığım için bağışla- demek her şeyi anımsıyorsun..oysa ikimiz bir türk filminden geçerken çarpan kamyon belleğimizi sırtlayıp  patlayan freniyle bir denize dökmüştü.ve sadece bunun için yalnızca o anı anımsardık.sadece o anı:tanrım! –adının her harfini küçük yazdım diye…-bir tüketim nesnesi olarak rüzgarda fotoğraflar..hiç cepte taşınmayan telefonların sessiz halini.. işe bak.. sen.sen..biraz sonra ağlayacaksın.ne komik..ağlamak gülünç değil mi? ..mi? bu ses benim.teselli akordu çekilmiş yankısı üç kişiyle konuşuyor.yalnız kendisi inanıyor sözlerine.çünkü tılsımlı karışımda yara kabuğu eksik.çünkü karşımda bağlanmış duran ve yalnızca gözleri açık hali sırlı cama yansımış biri var.çünkü ayakizlerini korku izliyor..çünkü görüyorsun bir cümleyi çünkü bağlamamalı…

Çünkü yaşıyorduk.. saçlarından dökülen altın tozuna hiçbir şampuan çare bulamıyordu.çaresiz bir zenginlik..uzakta başka ellere dökülen tozların olduğunu söylüyordun.uzakta- başka eller- söylüyordun! tanrım! -şimdi hiç sırası değil-sen! gözlerim sendeyse eline bak! 

ben hiç ilk yaşamadım hem biliyor musun? tanrım! –ikide bir araya girme-hiç ilk yaşamadım! her yaşadığımı sanki daha önce yaşamıştım ya da yaşamıyordum yaşadıklarımı.. yani ya sıfır ya iki..ondalıklı sayılar icat edilmemişti henüz biz tanıştığımızda...bölümler hep tam çıkıyordu...bizim masalımıza uyumuyordu çocuklar..içinden kaça kadar sayar ki gözlerin şimdi...hiç ilk yaşamadım ben...seni kaçıncı görüşümdü.eskizler getirmiştin.eski izler.her gün bir nokta konmuş bir mona liza eskizi..saçları uzun:porsuk deltasına yayılmış ve içine sonbahar yaprakları düşmüş.sararmış çarşafıyla altında bir yatak.evde kimse yoktu! sayılar bile! 

ben hiç ilk yaşamadım! bunu ilk kez mi söylüyorum sana..sıfırı bulduklarında sen yanımdaydın. arkamdaydın hatta.. önümdeydin.. çünkü sıfırı buluyorlardı ve sen olmaman gerektiğini hep düşünmüştün. giydiğin bulutlar gözyaşlarının habercisiydi.öyle kadınsı giyiniyordun.öyle bulutsu çıkarıyordun üzerindekileri.öyle rakamları vardı saatlerin porsuk deltasında seni çıplak bırakan..sen rakamları soyunuyordun..tüm doğal sayı/lırdı güzelliğin..

sonra geriye doğru ne kadar sayabilirdik ki? onu bulduklarında her şey bitmişti..her şey onu bulduklarında bitmeliydi çünkü...çünküyle bağlanmamalı hiç bir cümle anlıyor musun? ben seni sevmişim ve bunu bana..! geriye doğru kaça kadar sayabiliriz ki? nerden başlasak onu bulduklarında bitecekti..onu buldular..onu tükettiler..

sıfırı…', 'masalın içinde keskin bir gerçeklik kokusu…her sesinde küllerinden yeniden doğuyordu zümrüdü anka kuşu..üzerini silkeleyerek parlak mavi tüy...', ARRAY['Türk Edebiyatı','Şiir','Evrim Nisan']::text[], 8.5, '{"poet":"Evrim Nisan","poet_slug":"evrim-nisan","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/rakamlarin-evrimsel-tarihi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yabancı oldum şimdi', 'yabanci-oldum-simdi-mehmet-ali-suzen-ejcfr', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dün üşütüp hastamı oldunuz gece

İsmin harflerden içimde bir hece

Sen istedin bu ayrılığı hayat boyunca

Sevenler hüzünlü gün boyunca

Çok aradınmı sırtında sıcak bir el

Gece camda açık değildi

Ne bu soğuk bu yel

Bu gönül önünde sevda ile eğildi

Değermiydi tüm bunlara

Bak geçmişte olanlara

Unuttun sevdiğim dedin beni

Alsın deryalar bu bedeni

Umarım iyisindir.', 'Dün üşütüp hastamı oldunuz gece İsmin harflerden içimde bir hece Sen istedin bu ayrılığı hayat boyunca Sevenler hüzünlü gün boyunca Çok arad...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Süzen']::text[], 8.5, '{"poet":"Mehmet Ali Süzen","poet_slug":"mehmet-ali-suzen","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yabanci-oldum-simdi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rabbe Yakarış', 'rabbe-yakaris-bayram-tunca-1k2ma', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hiç olmadı olamaz ki zalimlerle aram

Geçmedi geçmez boğazımdan haram

Kanayıp dursa da ezelden beri yaram

Yersem haram huzuruna nasıl varam

En çok elim/dilim/belimden korkarım

Çünkü onlar suça daha çok meyillidir

Nasıl korkmayım ki yoksa maf olurum

Bu kulun haram yememeği yeminlidir

Yok ki başka da bir tabip yaramı sarsın

Şair yerse haram huzuruna nasıl varsın

Ya Rab hakiki dostum bir tek sen varsın

Bu mücrim kulun, başka kime yalvarsın

Eğer ki varsa param, alırım ihtiyaçlarımı

Yoksa sıkarım dişimi tuz basarım yaramı

Geçit veremem asla boğazımdan haramı

Huzuruna nasıl varırım ki yersem haramı

Ey Rabb’im, ne vereceksen helalinden ver

Yar vereceksen, helal süt emmişinden ver

Mal/mülk, evlat vereceksen, hayırlısını ver

Kulun Bayram bu duasını ta özünden eder

15.12.2004-12.15', 'Hiç olmadı olamaz ki zalimlerle aram Geçmedi geçmez boğazımdan haram Kanayıp dursa da ezelden beri yaram Yersem haram huzuruna nasıl varam E...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/rabbe-yakaris-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgiliye mektuplar3', 'sevgiliye-mektuplar3-denizhan-solmaz-gvty3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen ağlama yine

güzel gözlüm

kıyamam sana

yine yüzüne güneş vursun hep

asla gölge düşmesin sacının birteline

bütün bunlar sıradan şeyler

sende özel sende güzel

yoksa neye yanar bu yürek kor kor..

her ne kadar bir yanım çocuk kalmışsa

seni düşünüp ağlayaçak kadar

diğer bir yanımda bir o kadar büğüdü

acılarla yoğrula yoğrula

senin uğruna olsa bile

koruyabilmekte beni...

yoksa ben nasıl var olurum

sende biliyorsunki

sabah güneş herkes için doğar ve yine herkes için batar

ama ona ançak bilenler başka bakar...

doğarkende batarkende

ve herkes için birde üztündeki şebnem için konmuştur çiy

ama ona sadece aşık olanlar bakarken ağlar', 'Sen ağlama yine güzel gözlüm kıyamam sana yine yüzüne güneş vursun hep asla gölge düşmesin sacının birteline bütün bunlar sıradan şeyler sen...', ARRAY['Türk Edebiyatı','Şiir','Denizhan Solmaz']::text[], 8.5, '{"poet":"Denizhan Solmaz","poet_slug":"denizhan-solmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sevgiliye-mektuplar3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '- - - - A ş k, Ş a i r i S ö y l e t i r....!', 'a-s-k-s-a-i-r-i-s-o-y-l-e-t-i-r-metin-eser-67nwe', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bugün de akşam olup, ufku kızıllık sarmış,

İçre düşen hüznümün, tek sebebi o yârmış,

Küçük bir veda ile, geçip gitti önümden,

Pusulamsa şaşırdı, haberim yok yönümden.

Gecenin kollarında, sabah ola hayrola,

Allah nasip ederse, yine düşte seyrola,

Bir kerecik duysaydım, aşklı meşkli kelâmı,

Sonra hiç vermeseydi, nazlı dilde selâmı.

Yüreğimin sesini, hiç duymaz mısın be yâr,

Dudağın busesini, bir tatmaz mısın ne hâr,

Yazdığım her dizede, hecede adın saklı,

N’olur birkez duyayım, değil mi gönlüm haklı.

Sensiz alınmış nefes, yoktur göğsüm içinde,

Herbir saniyem kafes, sorularsa niçin de,

Senli dakikaları, gül kokulu yıl saydım,

Keşke senin karşına, on yıl hafif çıksaydım.

Efkârına düşünce, ketum sorular bir bir,

Sonra o bakışların, üşütür beni tir tir,

Dalıp gider gözlerin, kurduğun hayâline,

Ben de dalar giderim, senin masum hâline.

Bakışımın ilk raksı, ellerine çakılır,

Yüzüne geldiğimde, bakar bakar takılır,

Gözgöze gelişimiz, doyumsuz bir bahardır,

Ahh dokunsan tenime, bilir misin ne hârdır.

Ürkek kaçışım varya, değdiğinde gözüne,

Hani o “Ne” deyişin, gelir hemen sözüne,

Dudağıma tebessüm, kısacık bir taht kurar,

Sonra gönül bu hali, yine bir hayra yorar.

Hani sana demiştim, “Aşk, şairi söyletir”,

Sana olan bu aşkım, bana neler eyletir,

Uyku gözüme haram, helâl olan yüzündür,

Eğer gönlünde yoksam, bu en büyük hüzündür.

Bugün de Güneş batıp, göğü yıldızlar sardı,

İçimdeki her hâlin, tek sebebi o yârdı,

Küçük bir buse ile, geçseydi ya önümden,

Pusulam yine şaşsın, kime ne ki yönümden.

14.12.04 / Frankfurt', 'Bugün de akşam olup, ufku kızıllık sarmış, İçre düşen hüznümün, tek sebebi o yârmış, Küçük bir veda ile, geçip gitti önümden, Pusulamsa şaşı...', ARRAY['Türk Edebiyatı','Şiir','Metin Eser']::text[], 8.5, '{"poet":"Metin Eser","poet_slug":"metin-eser","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/a-s-k-s-a-i-r-i-s-o-y-l-e-t-i-r-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kokumu unutma', 'kokumu-unutma-mehmet-ali-suzen-b4b1y', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sevmek güzeldi ayrılıktan önce

Kokunu duydum o an demiştiniz

İçimi hiç göremediniz

Uyumak çok zor artık bu gece

Zamanından önce bitmeseydi

Hissedebilseydiniz hüznü kanımca

Ümit bu mutluluğa varırdık

Önüm deniz deryalar koskoca', 'Sevmek güzeldi ayrılıktan önce Kokunu duydum o an demiştiniz İçimi hiç göremediniz Uyumak çok zor artık bu gece Zamanından önce bitmeseydi H...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Süzen']::text[], 8.5, '{"poet":"Mehmet Ali Süzen","poet_slug":"mehmet-ali-suzen","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kokumu-unutma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Kendime İnandırdım', 'seni-kendime-i-nandirdim-nur-elif-yilmaz-8bbv7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'seni gördüm 

seni gün geçtikçe içime attım

kimseye söyleyemedim

kimseleri inandıramadım

seni her zaman içime attım 

bundan sonra 

kimseleri inandırmayacağım

bundan sonra 

kimselere söylemeyeceğim çünkü

seni ancak bi kişiye 

kabul ettirdim

kendime.....', 'seni gördüm  seni gün geçtikçe içime attım kimseye söyleyemedim kimseleri inandıramadım seni her zaman içime attım  bundan sonra  kimseleri ...', ARRAY['Türk Edebiyatı','Şiir','Nur Elif Yılmaz']::text[], 8.5, '{"poet":"Nur Elif Yılmaz","poet_slug":"nur-elif-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/seni-kendime-inandirdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Sildim', 'seni-sildim-nur-elif-yilmaz-1vkr2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'üzüldüm 

çünkü seni silmeye karar verdim

seni silmek 

dünyada  en yapılması zor  iştir

üzüldüm

çünkü seni sildim

seni sildim

çünkü 

inanılmaz çok özledim', 'üzüldüm  çünkü seni silmeye karar verdim seni silmek  dünyada  en yapılması zor  iştir üzüldüm çünkü seni sildim seni sildim çünkü  inanılma...', ARRAY['Türk Edebiyatı','Şiir','Nur Elif Yılmaz']::text[], 8.5, '{"poet":"Nur Elif Yılmaz","poet_slug":"nur-elif-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/seni-sildim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şairler', 'sairler-mehmet-karli-xjqhc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Şairler tanıdım yorulmadan pasa şiir yazardı

Bazıları dalgalanır köpürür eser eser tozardı

Kimileri cevap vermez en sonunda çoşardı

Bazen de şair gibi geçinen ne hıyarlar vardı...

Şairler okudum herşey bana göreydi

Bazıları nane ıspanak bazıları tereydi

Kimileri hasret kokar kimileri sılaydı

Bazen de beni hüngür hüngür ağlatan vardı...

Şairler gördüm ben ilham verir ışık saçardı

Bazıları konar göçer bazıları habire kaçardı

Kimileri çok mükemmel  güzel işler yapardı

Bazen de edepsiz hayasız adi olanlar vardı...

Şairler şiirler yazarlar eserler tonla yığınla

Hayallerim sana yüzer yakalandım ağında

Hamur edip pişirseler beni şimdi fırında

Çok güzel çok tatlı gülümseyen satırlar vardı...

Şairler geliyor bak bak peşpeşe sıralanmışlar

Bazıları her nedense yalpa yapmış aralanmışlar

Kimileri hain puşt satılmış kişiliksiz karalanmışlar

Bazende hep vatan kokan üstatlar duygular vardı...

Şairler ararım güler yüzlü anlatacak öğretecek

Bazıları duygu yüklü olsun ki öğütlerle gidecek

Kimileri için mücadele ömür bitse bile sürecek

Bazende ipe sapa gelmez yazılar şiirler vardı...

Şairler ölümsüz eserler bırakmış anılır olmuşlar

Bazıları kötü yazmış hakarete maruz kalmışlar

Kimileri altüst olmuş bu vatana küfür kusmuşlar

Bazen de Çanakkale Sakarya gibi olanlar vardı...

Şairler Mehmet Akif Necip Fazıl Karakoç gibi

Bazıları çekemiyor kıskanıyor tabi erişemez ki

Kimilerini yazmıycam buralara değmiyor çünkü

Bazen de bayraklaşan ne şairler ne şiirler vardı...

Şairler şiir yazar fakat biryerlerde aciz kalırlar

Bazıları gönlü ile Yunus Emre gibi aşkı bulurlar

Kimileri durdurulmaz  göçer Karacaoğlan olurlar

Bazende Safahat Çile Bakiler Mevlanalar vardı...

Şairler aklımda yanımda yöremde kuşatılmışım

Bazıları alıp gitmiş nerelerden geri gelmişim

Kimileri tökezlemiş kaybolmuş da arar olmuşum

Bazen de kül olan tozan ozan gibi ozanlar vardı...

Şairler var mükemmel eli öpülesi saygıdeğer

Bazıları lağım kokuyor karaktersizmiş meğer

Kimileri ölçülü alçakgönüllü işine gelirse eğer

Bazen de kaybolan yok olan ufak tefekler vardı...

Şairlere kifayetsiz yetmiyor satırlar anlatmak için

Bazıları gücenmesin küsmesin hiç sığmadı ismin 

Kimilerine gerek yok derim bunu  herkesler bilsin

Bazen de ilimi irfana sığmayan ne cümleler vardır....', 'Şairler tanıdım yorulmadan pasa şiir yazardı Bazıları dalgalanır köpürür eser eser tozardı Kimileri cevap vermez en sonunda çoşardı Bazen de...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Karlı']::text[], 8.5, '{"poet":"Mehmet Karlı","poet_slug":"mehmet-karli","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/sairler-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir İnsan Severse Eğer', 'bir-i-nsan-severse-eger-huseyin-erdogan-1lkaq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'sizin olduğunuz yerde

hiç olur mu gece? 

bir insan severse eğer

sürmeli ömrünce

siz bir prensessiniz bence

herkes adınızı ezberlemeli

gündüz ve de gece

hem de hece-hece

dalgalar adınızı kazımalı

sahildeki kayalıklara

rüzgarlar isminizi yazmalı

ovalara dağlara taşlara

herkes her yerde sizi anmalı

güzelliğiniz ve zarafetinizle

dilden dile dolaşmalısınız

dünya durdukça da

gönüllerde kalmalısınız

                16.12.2004', 'sizin olduğunuz yerde hiç olur mu gece?  bir insan severse eğer sürmeli ömrünce siz bir prensessiniz bence herkes adınızı ezberlemeli gündüz...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Erdoğan']::text[], 8.5, '{"poet":"Hüseyin Erdoğan","poet_slug":"huseyin-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/bir-insan-severse-eger-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şehvet degildi bu', 'sehvet-degildi-bu-mehmet-ali-suzen-v0rwo', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Elimden tuttun korkmuş ve ürkek

Sessiz sabahlarda sır gibi geldin

O efsun bakışlarınla söylenerek

Tadımı geri getirdi dudakların

Hissettirdin o dolgun güzelliğini

Yandım ki öylesine sıcak

Çılgınca bir şehvet anladım ki

Hayatta bir kez yaşanır ancak', 'Elimden tuttun korkmuş ve ürkek Sessiz sabahlarda sır gibi geldin O efsun bakışlarınla söylenerek Tadımı geri getirdi dudakların Hissettirdi...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Süzen']::text[], 8.5, '{"poet":"Mehmet Ali Süzen","poet_slug":"mehmet-ali-suzen","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sehvet-degildi-bu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Soru Sordular Bende Cevap Verdim...', 'soru-sordular-bende-cevap-verdim-tulay-sustam-ebreu', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bana dediler ki; 

sevdiklerin için ne yaparsın? 

bende dedim ki; 

sevdiğim kim olursa olsun gözümün nuruna değişmem

onların mutluluğu benim için her şeyin üstündedir.

gerekirse onlar için her şeyi göze alırım

hele sevdiğimse uğrunda düşünmeden ölürüm 

sonra dediler ki! ...

farzet ki namlunun ucunda abin var ne yaparsın? 

eğer yüreği yürek, bileği bilek abimse namlunun ucunda olmaz.

ola ki oldu namluyu kendime çeviririm dedim

tekrar sordular! ...

farzet ki namlunun ucunda ablan var ne yaparsın? 

eğer benim gibi gözü kara, yürekli ise namlunun ucunda olmaz.

ola ki oldu namluyu kendime çeviririm dedim

yine sordular! ...

farzet ki namlunun ucunda kardeşin var ne yaparsın? 

eğer benim kardeşim ise korkusuzdur, namlunun ucunda olmaz.

ola ki oldu namluyu kendime çeviririm dedim

durdular bir daha sordular! ...

farzet ki namlunun ucunda sevdiğin adam var ne yaparsın? 

düşündüm durdum, onlar şaşırdı benim tepkime...

kızarak sordular ya kızım bu adam senin sevdiğin değil mi? 

evet haklısınız bir zamanlar sevdiğim adamdı...

ama bir gün bana dost dedi

bende onu kaybetmemek için

yüreğime taş basarak ona dost dedim

kusura bakmayın! ...

ben işine geldiğinde dost olanlar için...

hele habersiz çekip giden dostum için...

namlunun ucunu kendime çevirmem...

ben canımı yolda bulmadım hele eloğlu için hiç bulmadım...

(otantik cafe / istanbul)', 'bana dediler ki;  sevdiklerin için ne yaparsın?  bende dedim ki;  sevdiğim kim olursa olsun gözümün nuruna değişmem onların mutluluğu benim ...', ARRAY['Türk Edebiyatı','Şiir','Tülay Sustam']::text[], 8.5, '{"poet":"Tülay Sustam","poet_slug":"tulay-sustam","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/soru-sordular-bende-cevap-verdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zülüflerin', 'zuluflerin-can-ozcan-ozkan-g20au', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir deniz düşlüyorum

Bir kıyısında sen

Diğerinde ben

Bir sandal oluyorum

Kıyındaki yeşilim koyda

Aglarımı atıyorum

Zülüflerinin değdiği yere...

Yüreğindeki seni çekiyorum

Usul

Usul

Dilimdeki 

Sevda türküsünde

Açıyor

Bahar gülleri

Zülüflerinde...', 'Bir deniz düşlüyorum Bir kıyısında sen Diğerinde ben Bir sandal oluyorum Kıyındaki yeşilim koyda Aglarımı atıyorum Zülüflerinin değdiği yere...', ARRAY['Türk Edebiyatı','Şiir','Can Özcan Özkan']::text[], 8.5, '{"poet":"Can Özcan Özkan","poet_slug":"can-ozcan-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/zuluflerin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mükemmel Olan..?', 'mukemmel-olan-engin-ozdel-q3b65', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '''her şeyin ilki güzeldir'' derler,ama; 

ikincisi muhteşem olmalı.

konusu ne olursa olsun 

yeterki ilkten sonra,

sadakatla dolsun.

ilki, ikincisi.............

ömrü boyunca sonuncusu,

mükemmel olan 

sondan bir önceki.', '''her şeyin ilki güzeldir'' derler,ama;  ikincisi muhteşem olmalı. konusu ne olursa olsun  yeterki ilkten sonra, sadakatla dolsun. ilki, ikinc...', ARRAY['Türk Edebiyatı','Şiir','Engin Özdel']::text[], 8.5, '{"poet":"Engin Özdel","poet_slug":"engin-ozdel","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/mukemmel-olan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüdai Baba', 'hudai-baba-selma-vural-pmikk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hiçbir ozan dolduramaz yerini 

Ozanlar içinde birdi Hüdai

Ozanlık yoluna verdin serini

Bütün gönüllere girdi Hüdai

Kuru ekmek ile çorba içerdi 

Bir evi var idi başa uçardı

Minnetsizdi, dostu iyi seçerdi

Muhabbet sofrası serdi Hüdai

Kurudu Dikmen’in bağı-bahçesi

Dünyanın malında yoktu hevesi 

Yavru Ali yuvasında neşesi

Bir tanede fidan verdi Hüdai

“Divane-derbeder” gezer dediler

Hem içer, hem bade süzer dediler

Elinde kalemi yazar dediler

Sevdiği Hakkına erdi Hüdai

Pîre, evliyaya, benzer âlimdi

İnsanı ayırmaz akli selimdi

Sevgisiz sohbetler O''na zulümdü

Her şeyi sevgide gördü Hüdai

Yakutlar, elmaslar dağıttı eli

İlim, irfan sundu o güzel dili

Muhabbet bağında açınca gülü

Okşadı gülünü, derdi Hüdai

Dediler “Hüdai komada yatar”

Kara toprak açtır çok canlar yutar

Yetmiş iki millet yasını tutar

Dünyada er gibi erdi Hüdai

KARACAKIZ O''nun manevi kızı

Alnına yazılmış kara bir yazı

Gayri çalınmıyor bu aşkın sazı

O sazı çaldıran yârdi Hüdai

21.11.2004', 'Hiçbir ozan dolduramaz yerini  Ozanlar içinde birdi Hüdai Ozanlık yoluna verdin serini Bütün gönüllere girdi Hüdai Kuru ekmek ile çorba içer...', ARRAY['Türk Edebiyatı','Şiir','Selma Vural']::text[], 8.5, '{"poet":"Selma Vural","poet_slug":"selma-vural","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/hudai-baba-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eylül Rapsodisi', 'eylul-rapsodisi-rezzan-kafali-l55kp', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'sessizim 

ıssızım

ışık kanar gibi yüreğim

güneşte yanmış gibiyim

sağnaklarım

ah

düşüyor gözlerime

sesimde titreşiyor

yalnızlığı kentin

uzakta bir düş

sevdalı

şiir ülkem

büyütebilir misin

umutlarımı

yağmalanmış 

şarap rengi zamanlarımı

kucaklayabilir misin

yaralarıma 

şiirlerime karşın

sever misin

gelir misin

en yağmurlu günde

çoğalır mısın gözlerimde

en sıcak sabahlarda

en

   en

      en

sevebilir misin

yüreğimde her zerre düş olur musun

dokunuşların yaprak sessizliğinde

yangınlarım en masum kavga

olur mu

erteleyebilir misin yarınlarımı

yarınım olur musun', 'sessizim  ıssızım ışık kanar gibi yüreğim güneşte yanmış gibiyim sağnaklarım ah düşüyor gözlerime sesimde titreşiyor yalnızlığı kentin uzakt...', ARRAY['Türk Edebiyatı','Şiir','Rezzan Kafalı']::text[], 8.5, '{"poet":"Rezzan Kafalı","poet_slug":"rezzan-kafali","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/eylul-rapsodisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bensiz', 'bensiz-i-smet-barlioglu-49sn2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir gün bensiz kalacak bu ıslak sokaklar

Belki yine çiseleyen yağmur altında,

Bu sonbahar rüzgarı, bu şimşek,

Bu ıslanmış yapraklar,

Bu çınar dalları

Bensiz kalacak.

Ben ölüp gitmeyegöreyim bir kez,

Neler olacak.

Kimbilir yorulup şu taşlara oturduğumu,

Ellerimi yalayan bir köpekle dost olduğumu,

Bir dilim ekmeği paylaştığımızı

Candan-gönülden,

Kimbilir.

Bensiz yaşamak zor iştir, anlatılmaz; 

Öğrenilir.

Bir gün bensiz kalacak bu ıslak sokaklar,

Şu yüzüme sımsıkı kapanmış kapılar,

Bu beni dışlayan ışıklı pencereler,

Bir gün bensiz kalacak bu bekçi düdükleri,

Bu adım sesleri; taşlarda yankılanan,

Bir gün bensiz kalacak bu acılar; 

Yüreğime bıçak gibi saplanan.

(BİR ŞARKI SÖYLE BANA İsimli Serbest Şiirler ''inden > 43-44/100)', 'Bir gün bensiz kalacak bu ıslak sokaklar Belki yine çiseleyen yağmur altında, Bu sonbahar rüzgarı, bu şimşek, Bu ıslanmış yapraklar, Bu çına...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/bensiz-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilirsin', 'bilirsin-i-smet-barlioglu-3jo6j', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İstesen ülkeler bağışlayabilirsin bana

Kaf Dağı arkasından,

Masallar diyarından ülkeler,

Yüzünü göklerin mavisine vermiş masmavi göller,

Zora-mora girmeden

Tek bir gülüşünle.

İstesen tacımı tahtımı elimden alabilirsin

Beni iplere çekip

Elinle.

İstesen abad edersin beni

Deryaya bakan saraylarda yangelmiş gibi,

Bulutlar serersin ayaklarımın altına,

Yorulduğum menzillere han yaparsın istersen

Ve altın leğenlere kan kusturursun

İstemesen.

Başımı kütüklere koymuşum senin önünde,

Hem de yılın her gününde,

Keskin satırlar altına, seve seve.

İstesen öldürürsün,

İstesen güldürürsün,

Zira; ölüme de razıyım, yaşama da

Bilirsin.

(BİR ŞARKI SÖYLE BANA İsimli Serbest Şiirler ''inden > 45-46/100)', 'İstesen ülkeler bağışlayabilirsin bana Kaf Dağı arkasından, Masallar diyarından ülkeler, Yüzünü göklerin mavisine vermiş masmavi göller, Zor...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/bilirsin-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sabahı Unutur Hayaller...', 'sabahi-unutur-hayaller-sirma-mersin-ho708', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ürkek gece kuşları öterdi

Zamansız karanlığın sessizliğinde...

Susan yaşamın sınırsızlığında

Hudut çizilmemiş yalnızlığa

Yoldaş olmuş çaresizliğin

Adım boyu mesafesinden daha çok uzardı,özlem...

Yolların kesişen acılarında

Gözyaşlarına teslim olmuş ruhun kaybolması ile

Sabahı unutur, hayaller...

15.12.04', 'Ürkek gece kuşları öterdi Zamansız karanlığın sessizliğinde... Susan yaşamın sınırsızlığında Hudut çizilmemiş yalnızlığa Yoldaş olmuş çaresi...', ARRAY['Türk Edebiyatı','Şiir','Sırma Mersin']::text[], 8.5, '{"poet":"Sırma Mersin","poet_slug":"sirma-mersin","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sabahi-unutur-hayaller-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Şimdi Asker (Oğlum''a)', 'o-simdi-asker-oglum-a-yunus-guzel-tom5k', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Uzaktasın yıldızlar kadar

Oysa hasret ne kadar yakın

Karda üşüyen yağmurdan masum

Bulutundan gökyüzü kadar uzaksın

Başı dumanlı bir güney akşamında

Kaybolan yıldız gibi aranmaktasın

Sen, haki gölgelerin düştüğü 

Bembeyaz gecelerde 

Donmuş şafakları saymaktasın…

Bense, bazen geçmişi,

Bazen  geleceği yaşayarak,

Hasretin sıcaklığıyla ısınmaktayım…', 'Uzaktasın yıldızlar kadar Oysa hasret ne kadar yakın Karda üşüyen yağmurdan masum Bulutundan gökyüzü kadar uzaksın Başı dumanlı bir güney ak...', ARRAY['Türk Edebiyatı','Şiir','Yunus Güzel']::text[], 8.5, '{"poet":"Yunus Güzel","poet_slug":"yunus-guzel","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/o-simdi-asker-oglum-a-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yokların efendisi', 'yoklarin-efendisi-hekim-coskun-qp48p', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'çiğnediğimiz toprak 

soluduğumuz hava

çektiğimiz ahlar

çekinip de söyleyemedik onca dileklerimiz

gecelerimde kabus

ben bağırıp uyandığımda

korkularım bende saklı kalır

sevgim kalkan olsun istedim

tüm kötülüklere

farz et ki sığınmak istedim

soğuk kış gecelerinde

ya da serinlemek için bir dal ol

istedim

gölgeni üstümü düşürdüğün

ya da gün ısısıyla ten ısını birleştirip

karıştırıp-barıştırdığımızda

sen de ol istedim

eksilerime yenik düştüğümde 

beni tamamlayan

bir bütün olmaya çalışıp

ayırdıgım parçaları birleştirirken

ki kalbim tüm olanlara yenik

sen üstüne yıktığım onca duvarlar

bizler var olmayan

yokların efendisi

bir gün seveceksem seni

tüm kitapları üst-üste koyup

erişeceksem yüceliğine 

onu da yaparım

yetir ki kulak ver sevgime', 'çiğnediğimiz toprak  soluduğumuz hava çektiğimiz ahlar çekinip de söyleyemedik onca dileklerimiz gecelerimde kabus ben bağırıp uyandığımda k...', ARRAY['Türk Edebiyatı','Şiir','Hekim Coşkun']::text[], 8.5, '{"poet":"Hekim Coşkun","poet_slug":"hekim-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/yoklarin-efendisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Seviyorum', 'seni-seviyorum-mustafa-yagmur-0nlps', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'kapıyorum gözlerimi ve yazıyorum sonra dayanamayıp açıyorum ne yazmışım diye sana. Bunları sana yazan kalbimdi  kalbim seni incitecek, üzecektek tekbir kelimeye bile izin vermezdi. Bu yüzden Tekrar Huzur içinde kapıyorum gözlerimi ve yazıyorum haykırarak tüm çıplaklığıyla (SENİ SEVİYORUM)   

Aşkım Deniz''e', 'kapıyorum gözlerimi ve yazıyorum sonra dayanamayıp açıyorum ne yazmışım diye sana. Bunları sana yazan kalbimdi  kalbim seni incitecek, üzece...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Yağmur']::text[], 8.5, '{"poet":"Mustafa Yağmur","poet_slug":"mustafa-yagmur","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/seni-seviyorum-226-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgiliye Sevgiler...', 'sevgiliye-sevgiler-i-brahim-ethem-bingul-y1n4t', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kalbimdeki yetim kalan duygular

Diş ağrısı gibi beynimde zonklar

Heykel olmuş donuk halde dururlar

Sevgime cevapsız kalan sorular...

Aşk yoksa kişide bitmiş nefesi

Sevgisiz saygının yeri neresi? ..

Robotların metal kokulu sesi

Bîzar eder, kulağımı tırmalar...

Samimiyet, sevgide ana direk

Sevgilere maya sevmek, sevilmek

Sevgiliye sevgiler dolu dilek

Gönderenler elbet sevgi bulurlar...

www.iebingul.com', 'Kalbimdeki yetim kalan duygular Diş ağrısı gibi beynimde zonklar Heykel olmuş donuk halde dururlar Sevgime cevapsız kalan sorular... Aşk yok...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sevgiliye-sevgiler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Beni Seviyorsun', 'sen-beni-seviyorsun-atil-kesmen-a44ls', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sen......

Beni seviyorsun

Bana bakan, nem tutmuş gözlerinden akan sevgin

Boşuna,sevgi şarkıları söylemiyor

Gözlerin nehir olmuş,ben akıyorum

Gönlünü sevgi ateşi sarmış,ben tütüyorum

Sen......

Beni seviyorsun

Güneşe aşık topraklar gibi ben''de yanıyorsun

Nehirlerin suya susadığı gibi ben''de çağlıyorsun

Hayatın sevgi olmuş ben''de ağlıyorsun

Sen

Beni seviyorsun

İnanmıyorsan

İnanmıyorsan beni sevdiğine

Ne olur bir defa olsun gönlüne sor

Bana bakan nem tutmuş gözlerine sor

Sen

Beni seviyorsun

Ben''de tek bir nefes gibi sevgini yaşıyorsun

Kalp yarasıdır

Seni çok iyi anlıyorum,bir tanem

Laflar sözler geçersizdir seven gönülde

Sevgi acısıdır

Dinmez bakan gözlerinde

Sen

Beni seviyorsun

Sevgini gizleyemediğin gözlerinle

Ben olmuş,bana bakan,ben yanan gözlerin

Ben''de gülüyor

Beni canında can gibi seviyor

Vurdukça,sevgi diye gönlüne

Ben damlıyorum, ben kokan yüreğine

Sen

Beni seviyorsun

Yalnızlıklarımda, terleyip üşüdüğüm bedeninle

Kor ateşe dönüşmüş gönlünle

Sen

Beni seviyorsun

Bana, aşkım aşkımsın,tek sevdiğimsin

Demeni istiyorum

Sevgi özünde ben olan sözlerinle

Ben''de yeşerip

Sen''de, sevgi diye açan gözlerinle

Sen

Beni seviyorsun

Gönlünde hiçbir zaman ölmeyecek

Ve bir ömür boyu sürecek

Bana olan sevginle.', 'Sen...... Beni seviyorsun Bana bakan, nem tutmuş gözlerinden akan sevgin Boşuna,sevgi şarkıları söylemiyor Gözlerin nehir olmuş,ben akıyorum...', ARRAY['Türk Edebiyatı','Şiir','Atıl Kesmen']::text[], 8.5, '{"poet":"Atıl Kesmen","poet_slug":"atil-kesmen","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/sen-beni-seviyorsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'KalabalıktıR BeniM YalnızlığıM', 'kalabaliktir-benim-yalnizligim-arslan-arslan-9zu6k', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Aşkın; narının koru az gelir

Düştüğüm bu çıkmaz her gün canımı alır

Sevdiğimle; başım hep darda kalır

Onsuz kalabalıktır benim yalnızlığım

Bir umut olup hep içimde beslenir

Günü gelince kıyamette de olsa seslenir

Gönül bu; zalim olsa da hislenir

Onsuz kalabalıktır benim yalnızlığım 



Arslan ARSLAN..........15.12.2004', 'Aşkın; narının koru az gelir Düştüğüm bu çıkmaz her gün canımı alır Sevdiğimle; başım hep darda kalır Onsuz kalabalıktır benim yalnızlığım B...', ARRAY['Türk Edebiyatı','Şiir','Arslan Arslan']::text[], 8.5, '{"poet":"Arslan Arslan","poet_slug":"arslan-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/kalabaliktir-benim-yalnizligim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmurlarda Ağlarım', 'yagmurlarda-aglarim-galip-sinecikli-7kedt', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'senin olduğun şehre

şimdi yağmurlar yağıyor

her yağan yağmurda

sensizliğe ağlıyorum ben

çünkü,

en son yağmurlu bir günde

seninle birlikte ağlamıştım

uzaklara sen gidiyordun

ben kalıyordum buralarda

“ararım canım, haber veririm sana” dedin ve gittin

gittiğin o günden beri

hiç aramadın beni

gittiğin gün

bir sağanak yağdırıyordu

gökyüzünde bulutlar, yeryüzünde iki çift göz

sen gittin 

uzaklaştın

belki bir daha

adımı bile anmadın

oysa ben

gittiğin günden beri

tek başıma

iki kişilik ağladım....

[email protected]', 'senin olduğun şehre şimdi yağmurlar yağıyor her yağan yağmurda sensizliğe ağlıyorum ben çünkü, en son yağmurlu bir günde seninle birlikte ağ...', ARRAY['Türk Edebiyatı','Şiir','Galip Sinecikli']::text[], 8.5, '{"poet":"Galip Sinecikli","poet_slug":"galip-sinecikli","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/yagmurlarda-aglarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Zaman Simsiyah Olan Saçlarım', 'bir-zaman-simsiyah-olan-saclarim-tayyip-sag-159c0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir zaman simsiyah olan saçlarım,

Kar yağmış dağlara döndü bak oğlum,

Umutlar içinde gülen gözlerim,

Kurumaz çaylara döndü bak oğlum.

Dağlarım çok kışlar görüpte geçti,

Baharda her türlü çiçekler açtı,

Buz gibi pınarlar çağladı coştu,

Bir türlü efkarım dinmedi oğlum.

Bir ateş ki sönmek nedir bilmiyor,

Felek inat etmiş aman vermiyor,

Garip gönlüm yıllar yılı gülmüyor,

İçimdeki yangın sönmedi oğlum.

Hiçbir zaman doğruluktan şaşmadım,

Şerefsiz namerde avuç açmadım,

Vicdan terazime hile katmadım,

Kötüler kadrimi bilmedi oğlum.

Tayyip der ne bilsin kötüler halden,

Çok şeytanlar gelip geçti bu yoldan,

Allah sevgisini saklamaz kuldan,

Sevgisiz gönüller görmedi oğlum.

   01.12.2004', 'Bir zaman simsiyah olan saçlarım, Kar yağmış dağlara döndü bak oğlum, Umutlar içinde gülen gözlerim, Kurumaz çaylara döndü bak oğlum. Dağlar...', ARRAY['Türk Edebiyatı','Şiir','Tayyip Sağ']::text[], 8.5, '{"poet":"Tayyip Sağ","poet_slug":"tayyip-sag","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bir-zaman-simsiyah-olan-saclarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Git Artık...', 'git-artik-gulay-yildiz-7ki4x', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'içimde biriken 

iki katilin lanetli iki yüzü 

Arsızlıktan suçlu kanım gizli 

Damarlarım büzüşmüş, hislerim kilit 

Sesini kulağımdan al 

Al ki gün güneşe dönsün... 

Ya da fısılda... 

Orda benden bi haber olanları 

Kimlerin elinde adın 

kimlerin sesinde tını dudakların 

Bir küçük gamzeyse başlatan her şeyi 

Suçlu; 

ben değilim aynaya küs 

Git artık! 

______ona anlat derdini....', 'içimde biriken  iki katilin lanetli iki yüzü  Arsızlıktan suçlu kanım gizli  Damarlarım büzüşmüş, hislerim kilit  Sesini kulağımdan al  Al k...', ARRAY['Türk Edebiyatı','Şiir','Gülay Yıldız']::text[], 8.5, '{"poet":"Gülay Yıldız","poet_slug":"gulay-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/git-artik-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Böyle Bir Dünyaya Anne Olmak!', 'boyle-bir-dunyaya-anne-olmak-ayse-birgul-yilmaz-e1zua', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'En güzel duygudur anne olmak! 

Acıdır bu duygudan yoksun kalmak! 

…………………………………...; 

Bitmeyen hırsların, şiddetin, kavgaların

Acımasızca, silahların rast gele sıkıldığı

Masum beyinlerin çıkarlar uğruna yıkandığı

Çığlıkların sesinde, kimyasallar gölgesinde

Ne acıdır anne olmak, yüreği acıyla yanmak! 

Bu çaresizliği yaşamak, çocuklara anlatmak! 

		………….

Sevginin, barışın ve güzelliklerin kaybolduğu,

İnsan olmanın, insanca yaşamanın unutulduğu,

Dağların, taşların, balıkların, kuşların, çiçeklerin,

Renklerin karıncaların bile huzurunun kalmadığı,

Gözü dönmüş hain ellerce, hayallerin, değerlerin, 

Umutların zalimlerce yağmalanıp, yıkılıp-yakıldığı,

Böyle bir dünyada anne olmak; 

Acımasızlığın, kahpeliğin çığ gibi büyüdüğü

Tekmelenmiş yüzlerin, buz kesilmiş gözlerin

Biçilmiş ellerin-ayakların, körpecik bedenlerin

Çaresizliğin, genceciklerin her yerde görüldüğü

Vicdanların çürüdüğü…ruhsuzluğa gömüldüğü

Umutların ve geleceğin bir bataklığa dönüştüğü

Uyuşturucunun kol gezdiği, kanların döküldüğü

Böyle bir dünyada çocuk doğurmak; 

Savunmasız insanların, bebeklerin hunharca öldürüldüğü,

Özgürlüklerin, uygarlıkların trajediye bayalığa dönüştüğü,

Göz yaşlarının sel olduğu, umursamazlığın, adaletsizliğin, 

Bölücülüğün hüküm sürdüğü, onca haksızlığın, yalnızlığın,

Bataklığın dünyasında bu kötü zamanda yada baba olmak da, 

Zor.. çocuklara iyi bir gelecek vermek iyi örnek olmak gerek.

İşlenen suçların, savaşların, ihtirasların takvimlere tarih diye,

Tarih adı altında anlatılacağı ve kanlı katliamların yazılacağı,

Vahşetin-dehşetin, barbarlığın çocuklara zafer diye okutulacağı, 

Bütün kitapları reddediyorum..

Ben böyle bir dünyaya anne olmak ve böyle bir dünyaya 

Çocuk doğurmak istemiyorum..

Nasıl? 

Korkuyor muyum? 

Elbet! ..

Korkutuyor muyum? 

Gerçek! .. 

                       

İnsan, insanlar, insanlık! .. her geçen gün daha hoyrat! 

Bu gidişe, bu dilsizliğe, bu sessizliğe, bu belirirsizliğe; 

Bu yaralı, yorgun dünyaya imdat Allah’ım imdaaaattt! 

21.12.2004', 'En güzel duygudur anne olmak!  Acıdır bu duygudan yoksun kalmak!  …………………………………...;  Bitmeyen hırsların, şiddetin, kavgaların Acımasızca, si...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Birgül Yılmaz']::text[], 8.5, '{"poet":"Ayşe Birgül Yılmaz","poet_slug":"ayse-birgul-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/boyle-bir-dunyaya-anne-olmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ama...Sen Gittin.', 'ama-sen-gittin-zulfikar-yapar-kaleli-csstk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Seslenseydin ardım sıra, 

Bir haykırsaydın! ... 

Dokunabilirdim çığlıklarına... 

Hissedebilirdim duygularını

Konuşabilirdim hayalinle

Tutabilirdim düşlerini ellerimle… 

Kucaklayabilirdim seni 

Saygı buketli, sevgi kokulu 

Büsbütün benliğimle.... 

Sen gittin! 

Sarabilirdim yaralarını 

Yan etkisi olmayan merhemle. 

Susturabilirdim gözyaşlarını 

Mavi gülümsemeyle,

Akmaya hazır göz yaşlarımla! 

Dindirebilirdim kalp sancılarını 

Sancılı kalbimi verip 

Sen gittin! 

İlham verir miydi sözlerim bilmem? 

Ama yatıştırabilirdim korkularını 

Korkulu yüreğimden sızan 

Reçetesiz bir teselli ile. 

Sen gittin! 

Sevebilirdim seni sorgusuz, sualsiz 

Pencerenin isli camında, 

Sigaramın dumanında, 

Sol kulağımın yanında 

Görebilirdim. 

Görebilirdim baktığım her yerde. 

Sen gittin! 

Tek seni sevdim sevgilim 

Koy bu hayat senin olsun 

Kararı ben vereceksem 

Seni öldürmek niye? 

Hiç vakit kaybetmeden 

Yanına geleceğim 

Ve ben seni sevgilim 

Ömrümce seveceğim.', 'Seslenseydin ardım sıra,  Bir haykırsaydın! ...  Dokunabilirdim çığlıklarına...  Hissedebilirdim duygularını Konuşabilirdim hayalinle Tutabi...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/ama-sen-gittin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geriye Kalan', 'geriye-kalan-hil-l-kucuk-ozdamar-688bz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ellerime dök gölgeni,ellerime, 

kanayan yaralarıma gül düşsün. 

Dikenler yaramı acıtsa da, 

saksıdan gözlerime aşk düşsün.

*** 

Sev pencere önlerini, 

sakladığın çeyizlere can düşsün. 

Ceviz sandığın kapağından, 

kıyamadığım gözlerine an düşsün. 

*** 

Bileklerimdeki ve ayaklarımdaki yangını, 

söndürmek için aklıma ilk kan düşsün. 

Sersem sabahları yudumlasam da, 

özlemler içine sabahtan düşsün. 

*** 

Balkondan sarkıttığın sepetin içine, 

sıcacık ekmek buğusundan düşsün. 

Yürüyüveren kervanın ardına, 

bırak da geriye kalan düşsün...', 'Ellerime dök gölgeni,ellerime,  kanayan yaralarıma gül düşsün.  Dikenler yaramı acıtsa da,  saksıdan gözlerime aşk düşsün. ***  Sev pencere ...', ARRAY['Türk Edebiyatı','Şiir','Hilâl Küçük Özdamar']::text[], 8.5, '{"poet":"Hilâl Küçük Özdamar","poet_slug":"hil-l-kucuk-ozdamar","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/geriye-kalan-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Mahkumu', 'ask-mahkumu-sukru-dikbiyik-9x92n', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Aşkımı itiraf etsem sana inanır mıydın

leyla ile mejnun arasında kalır mıydın

sana bir gül veripte aşkımı hatırlarmıydın

Aşkımızın parayla satılacağın şimdi anladım

neyazıkki aşklarda satılırmış 

sevenlerde aldatılırmış

elime aldığım zaman kalemi

hatırlardım seni,dağlardaki çiçekleri

kırmızı ila sarı gülleri mor gülleri

senden bana kalan çerçeveli bir fotoğrafın

yüzündeki gülen o,gülücükler

hepimizi ağlatan gözler elimizdeki kalemler

şairim hayatından menmun deyildi

parayla satılan aşkların yerine

bir dal çiçek yeterdi.', 'Aşkımı itiraf etsem sana inanır mıydın leyla ile mejnun arasında kalır mıydın sana bir gül veripte aşkımı hatırlarmıydın Aşkımızın parayla s...', ARRAY['Türk Edebiyatı','Şiir','Şükrü Dikbıyık']::text[], 8.5, '{"poet":"Şükrü Dikbıyık","poet_slug":"sukru-dikbiyik","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ask-mahkumu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geceden Farkını Söyle', 'geceden-farkini-soyle-orhun-basat-fl2xr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'güç olan kalmaktı

kıskanç yalnızlığımın çağrısını duymazdan gelip

küskün bir sevdanın atığıyken gecenin karanlığı

adet olduğu üzre giderken birileri tükenip..

hüznü resmediyordum çıplak toprağa 

esen rüzgara asi kuru yaprak misali 

geride kalan üşüyen sesti..

evet / geride kalan 

çarpık çiftleşmesinde tün ile günün

geçmiş hikayesi yitik ve kahramanı olmayan

renkleri acıya çalan anlamsız bir bütünün 

laf olsun diye aldığı nefesti..

uçuşan tozlarında düşlerin 

gece içre kanayan ..

işte böyle..

kör gardiyanı duygularımın 

usulca eğil kulağıma / geceden farkını söyle....

bir isim daha eksildi / kadehimin buğusundan..', 'güç olan kalmaktı kıskanç yalnızlığımın çağrısını duymazdan gelip küskün bir sevdanın atığıyken gecenin karanlığı adet olduğu üzre giderken ...', ARRAY['Türk Edebiyatı','Şiir','Orhun Basat']::text[], 8.5, '{"poet":"Orhun Basat","poet_slug":"orhun-basat","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/geceden-farkini-soyle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Maniler (21) ''filizlenen hüzünler''', 'maniler-21-filizlenen-huzunler-abdullah-atay-qvh8b', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'aşk peşinde yorgunum

hep sana ben vurgunum

sen gittiğin günden beri

bu gönlümle dargınım...

bu gönül seni ister

yarim gözümde tüter

yanımda yoksan bile

sesini duysam yeter...

hüzünler bana konar

yüreğim sana yanar

bu benim garip gönlüm

niye seni hep anar...

dağlar geçit vermiyor

yar hatırım sormuyor

inan senden başkası

sen gibi yar olmuyor...

dağlar karsız olmazmış

yiğit yarsız olmazmış

sensiz olan dünyada

gönül huzur bulmazmış...

sönmüş ocak tüter mi

gülsüz bülbül öter mi

yardan ayrı kalanın

yangınları biter mi...

gönül bahçem soluyor

ruha hüzün doluyor

yarsız geçen yıllarda

baharım kış oluyor...

susuz dere akmıyor

yar yüzüme bakmıyor

nice güller gördüm ben

senin gibi kokmuyor...', 'aşk peşinde yorgunum hep sana ben vurgunum sen gittiğin günden beri bu gönlümle dargınım... bu gönül seni ister yarim gözümde tüter yanımda ...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Atay']::text[], 8.5, '{"poet":"Abdullah Atay","poet_slug":"abdullah-atay","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/maniler-21-filizlenen-huzunler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Mavi Çocuk - Sarı Bebek', 'mavi-cocuk-sari-bebek-yildiz-yildiz-070l0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gülümsemişti sanırım son bakışın! ! ..

Nereden çıktı şimdi

Hangi yaradan aktı 

O incecik hüzün

Kirpiğinde asılı duran? 

Her bakışın maviydi oysa

Ne zaman sızdı şiirin mürekkebine 

O erguvan kan? 

Ben biliyorum 

Sarıydı, çilliydi, masumdu aslında..

Çelik bir zırh içinde gizlediğin,

Büyümüş de küçülmüş halleri yüzünden

Bebek olduğunu senin bile bilmediğin,

O mavi çocuktan kalan', 'Gülümsemişti sanırım son bakışın! ! .. Nereden çıktı şimdi Hangi yaradan aktı  O incecik hüzün Kirpiğinde asılı duran?  Her bakışın maviydi ...', ARRAY['Türk Edebiyatı','Şiir','Yıldız Yıldız']::text[], 8.5, '{"poet":"Yıldız Yıldız","poet_slug":"yildiz-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/mavi-cocuk-sari-bebek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalplerdeki Prenses (Leydi Dianaya Atfen)', 'kalplerdeki-prenses-leydi-dianaya-atfen-i-brahim-necati-gunay-6nwx0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Es güzel es saçların savrulsun,

Sana kem bakan gözler kavrulsun,

Hızlı giden çabuk yorulsun,

Aşkınız iki cihanda yoğrulsun,

Akan gözyaşları zalimlere dokunsun,

O iki delikanlı anaları ile övünsün,

Sana bunu yapanlar dövünsün,

Tüm insanların kalbindesin sen,

İmkanım olsa da gelip seni yanakların dan öpebilsem,

Kalplerimizin prensesini son bir kez görebilsem.', 'Es güzel es saçların savrulsun, Sana kem bakan gözler kavrulsun, Hızlı giden çabuk yorulsun, Aşkınız iki cihanda yoğrulsun, Akan gözyaşları ...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Necati Günay']::text[], 8.5, '{"poet":"İbrahim Necati Günay","poet_slug":"i-brahim-necati-gunay","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/kalplerdeki-prenses-leydi-dianaya-atfen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir nefes', 'bir-nefes-hekim-coskun-y67v0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'sevgimizi anlatırken bile

kekeme kaldık

sonlandırdığımızda kelimeleri

avucumuzda bir nefes sıcaklık kaldı

içimizi ısıtan şefkatle açtık gözlerimizi

yanı başımızda bizi bekleyen zebaniler

cehennem ateşi sandı

biz sevgiyle bakarken

gördüklerimiz bize zindan

yaşadıklarımızsa  sayılmadı

sayılanlarsa hapsedildi

bir volta atımlık zamanlarda bile

sevgimizi haykırdık

duyulmadı.

tüm anlatımlarımızda

boğazımıza takılı kaldı hıçkırıklar

topladık tüm zamanlarımızı

kağıttan bir torbaya koyduk

bir elimizde ekmek

bir elimizde torba

ve tüm geleceğimizle

yarınlara yürüdük

ağır aksak adımlarımızla

sağlam basmaya çalıştık toprağa

bir kuş kadar hafifliğimizle.

ellerimiz sevgi alkışladı

sırtımız okşandı 

sıvazlandı

başımız gövdemizden büyük

meselelerse içinden çıkılmaz bir hal aldı

ne kimsenin yardımına koşabildik

ne de yardım dileklerimiz cevap buldu

karanlık 

karanlık olduğu kadar derin

bir o kadar patlarcasına sıkıldık', 'sevgimizi anlatırken bile kekeme kaldık sonlandırdığımızda kelimeleri avucumuzda bir nefes sıcaklık kaldı içimizi ısıtan şefkatle açtık gözl...', ARRAY['Türk Edebiyatı','Şiir','Hekim Coşkun']::text[], 8.5, '{"poet":"Hekim Coşkun","poet_slug":"hekim-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/bir-nefes-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tereddütler-3', 'tereddutler-3-hasan-sun-igxgt', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '6.

dönerim karanlık sokaklardan

gece sorgulamaya başlar

felsefenin kadim sorularını

sakinleşmeye meyl eder

umudun ve direnişin ezgileri

7.

kabuk bağladıkça kimlikteki yara

ötekilerin sinekleri aç kalacak

cenazesi musallada olanların öfkesi

işverenin işinde donacak

gizli sevişmeleri başlayacak gecede

özgürlüğün tutsaklıkla

8.

özgürlük tutsaklığa mecbur

gece şahit

köy, şehire

9.

şeyler dönüyor kafamda

bir denklem elde edilmez

bilineni çok bir denklem olurmu acaba? 

10.

sonra bir nakarat:

''analar ağlamasın''; 

babalar ölsün,anaları ağlatılsın

                            (kasım/2004/göksun)', '6. dönerim karanlık sokaklardan gece sorgulamaya başlar felsefenin kadim sorularını sakinleşmeye meyl eder umudun ve direnişin ezgileri 7. k...', ARRAY['Türk Edebiyatı','Şiir','Hasan Sun']::text[], 8.5, '{"poet":"Hasan Sun","poet_slug":"hasan-sun","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/tereddutler-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir sigara daha', 'bir-sigara-daha-sair-shimalwest-hot2g', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'bir sigara daha istedi canım

bitenle yaktım yenisini

uc uca ekledim hepsini

saçmalık kederi sigarayla atmak

bir parça nikotinden medet ummak

sabrediyorum sadece

sanki var mı başka çare

günler hızla akıp gitsin

çektiğim bu cefa bitsin

bir sigara daha istedi canım

bitenle yaktım yenisini

küllüğümde yer kalmamış

etrafa kül saçılmış

berduş gibi hissettim kendimi

ortalık dağınık

ben dağınık

hayatım dağınık

ne çekip alabilir beni

bir sigara daha istedi canım

bitenle yaktım yenisini

seyrederken üflediğim dumanda

senelerin uçup gitmesini

bir sigara daha istedi canım

bitenle yaktım yenisini

her sigaramın bitişinde

diğer elimde yenisi', 'bir sigara daha istedi canım bitenle yaktım yenisini uc uca ekledim hepsini saçmalık kederi sigarayla atmak bir parça nikotinden medet ummak...', ARRAY['Türk Edebiyatı','Şiir','Şair Shimalwest']::text[], 8.5, '{"poet":"Şair Shimalwest","poet_slug":"sair-shimalwest","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/bir-sigara-daha-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalanmış Meğer', 'yalanmis-meger-i-brahim-necati-gunay-pzcmo', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Zalim vurdun beni felekten,

Nice güzeller geçti bu elekten,

İlk aşkı sende buldum gerçekten,

Gönül seni sevdi yürekten,

Çok zalimsin vurdun beni yürekten,

Sevdan asla çıkmaz bu yürekten,

Bir rüyaydı sanki o yıllar,

Bizi birbirimizden ayırdı onlar,

Harap etti beni geçen yıllar,

Çok önceden planlanmış bunlar,

Sani sevmek günahmış meğer,

Bu sevgi sevene bir ömür''e değer,

Sevmek sevilmek boşaymış meğer,

Beni sevmek bir ömre değer,

Senin her şeyin YALANMIŞ MEĞER.', 'Zalim vurdun beni felekten, Nice güzeller geçti bu elekten, İlk aşkı sende buldum gerçekten, Gönül seni sevdi yürekten, Çok zalimsin vurdun ...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Necati Günay']::text[], 8.5, '{"poet":"İbrahim Necati Günay","poet_slug":"i-brahim-necati-gunay","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/yalanmis-meger-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonsuzluk', 'sonsuzluk-sair-shimalwest-zrkcb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'sonsuzluk nasıl bir kavram

kim görmüş ki sonunu

kim bilir ki varlığını

niye sevgiler mutluluklar

hep sonsuzlukla anlatılır

sonsuz olsun istemiyorum

sevgim mutluluğum

ben yokum sonsuzlukta

ömrümce olsun güzellikler

benimle yaşasın 

benimle bitsin

geride kalanlar sonsuzu beklemeden

yaşamaya devam etsin

eğer görünüyorsa gidilen yerden

burada bıraktıklarım

bensiz de olsa mutlu göreyim', 'sonsuzluk nasıl bir kavram kim görmüş ki sonunu kim bilir ki varlığını niye sevgiler mutluluklar hep sonsuzlukla anlatılır sonsuz olsun iste...', ARRAY['Türk Edebiyatı','Şiir','Şair Shimalwest']::text[], 8.5, '{"poet":"Şair Shimalwest","poet_slug":"sair-shimalwest","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sonsuzluk-29-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Yiğit', 'bir-yigit-mustafa-gokcek-p9hc0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'BİR YİĞİT

Bir garip oturmuş derlerse

Yıllar öncesine gittim, geldim

Yıllar sonrasında bir düş gördüm

Muştumudur ki ölümüm sizlere

Yiğit oldum bir kez

Sevdalandım yarınlara

Gül ektim, diken biçtim

Ayağım kanarken, ben ölmedim ki

Benden gittin ama, yaşıyorum işte

Susuzluğumu ararken, suya muhtaç

Tenim kurudu, ama sen gittin işte

Ve belki de kuşa, kurda kul oldun…



(Şükran KURDAKUL’UN anısına…)', 'BİR YİĞİT Bir garip oturmuş derlerse Yıllar öncesine gittim, geldim Yıllar sonrasında bir düş gördüm Muştumudur ki ölümüm sizlere Yiğit oldu...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Gökçek']::text[], 8.5, '{"poet":"Mustafa Gökçek","poet_slug":"mustafa-gokcek","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/bir-yigit-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yiğidin Arkasından', 'yigidin-arkasindan-mustafa-gokcek-uo0z3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yiğidin Arkasından

Bir garip oturmuş derlerse

Yıllar öncesine gittim, geldim

Yıllar sonrasında bir düş gördüm

Muştumudur ki ölümüm sizlere

Yiğit oldum bir kez

Sevdalandım yarınlara

Gül ektim, diken biçtim

Ayağım kanarken, ben ölmedim ki

Benden gittin ama, yaşıyorum işte

Susuzluğumu ararken, suya muhtaç

Tenim kurudu, ama sen gittin işte

Ve belki de kuşa, kurda kul oldun…



(Şükran KURDAKUL’UN anısına…)', 'Yiğidin Arkasından Bir garip oturmuş derlerse Yıllar öncesine gittim, geldim Yıllar sonrasında bir düş gördüm Muştumudur ki ölümüm sizlere Y...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Gökçek']::text[], 8.5, '{"poet":"Mustafa Gökçek","poet_slug":"mustafa-gokcek","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/yigidin-arkasindan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cehennem Ateşi..', 'cehennem-atesi-hayrettin-orak-e9t79', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ben güzelim diye övünme, bilki yaşlanacaksın,

Gül gibisin, narinsin, kibirlenme elbet solacaksın,

Kırdığın kalplerin ahını bir bir alacaksın,

Vebalini çeke çeke eriyip yok olacaksın.

İşvenle, nazınla girdin temiz kalplere,

Acımadan zehir kattın saf yüreklere,

Yetmedi kabus oldun tatlı düşlere,

Söyle bunların hesabını nasıl vereceksin.

Gün gelecek yanında tek seven kalmayacak,

Bu çektirdiklerin elbet bir son bulacak,

Sevenin kalmaz, sana açılmaz hiç bir kucak,

Seven bir dost eli ararsın bucak bucak.

Günah defterin olacak binlerce yaprak,

Günahkar bedenini kabul etmiyecek toprak,

Bu yaptıkların yanına kar kalmayacak,

Cezan cehennem ateşinde yanmak olacak....! 

16.12.2004', 'Ben güzelim diye övünme, bilki yaşlanacaksın, Gül gibisin, narinsin, kibirlenme elbet solacaksın, Kırdığın kalplerin ahını bir bir alacaksın...', ARRAY['Türk Edebiyatı','Şiir','Hayrettin Orak']::text[], 8.5, '{"poet":"Hayrettin Orak","poet_slug":"hayrettin-orak","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/cehennem-atesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '.Nerdesin', 'nerdesin-sinan-dayan-8m0i9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yolcu ederken seni,

Sarılıp kucakladıgımdan beri,

Yirmi yıl...

Hasretim genç bir delikanlı,

Neredeyse sana denk...

Sen bedenimdeki can...

Yüregimdeki heyecan...

Agam...

Canım yanıyor... neredesin? ..

Gülerken,sevinçliyken

Burukturya yüreğim...

Sen...

Sen yoksun hani! ..

İç çekerken,

Ahh derken tüm benliğim,

Sen...

Sen yoksun,

Yüreğim acıyor...

Neredesin?', 'Yolcu ederken seni, Sarılıp kucakladıgımdan beri, Yirmi yıl... Hasretim genç bir delikanlı, Neredeyse sana denk... Sen bedenimdeki can... Yü...', ARRAY['Türk Edebiyatı','Şiir','Sinan Dayan']::text[], 8.5, '{"poet":"Sinan Dayan","poet_slug":"sinan-dayan","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/nerdesin-98-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bizim Yazgımız', 'bizim-yazgimiz-haydar-turan-9f7pg', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bize yazgıdır anadan, yardan ayrılık,

Ölüm bekler bizi gençliğimize doyamadık,

Çatlamış yanaklarımız gözlerde kuraklık,

Ölüm bir uykuysa öldük ve uyandık...', 'Bize yazgıdır anadan, yardan ayrılık, Ölüm bekler bizi gençliğimize doyamadık, Çatlamış yanaklarımız gözlerde kuraklık, Ölüm bir uykuysa öld...', ARRAY['Türk Edebiyatı','Şiir','Haydar Turan']::text[], 8.5, '{"poet":"Haydar Turan","poet_slug":"haydar-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/bizim-yazgimiz-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Siz Seksen Yaşında Çocuk Gördünüz Mü?', 'siz-seksen-yasinda-cocuk-gordunuz-mu-erdogan-ergin-5vkep', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'siz seksen yaşında çocuk gördünüz mü? 

eline elma şekeri verilen

bunu ye, yenisini vereceğim sana deninen

siz seksen yaşında çocuk gördünüz mü? 

babasının kim olduğunu unutan

kendisini üç paraya satan

siz seksen yaşında çocuk gördünüz mü? 

başında yıldızlar

kendi yıldızını

ayını unutan

siz seksen yaşında çocuk gördünüz mü? 

elinde elma şekeri,

kendisini üç paraya satan

dertliyim, efkarım çocuğa

çocuğu alıp kandırana', 'siz seksen yaşında çocuk gördünüz mü?  eline elma şekeri verilen bunu ye, yenisini vereceğim sana deninen siz seksen yaşında çocuk gördünüz ...', ARRAY['Türk Edebiyatı','Şiir','Erdoğan Ergin']::text[], 8.5, '{"poet":"Erdoğan Ergin","poet_slug":"erdogan-ergin","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/siz-seksen-yasinda-cocuk-gordunuz-mu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zamanın Aracı', 'zamanin-araci-altay-taskin-dsv9a', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'bana anlat kendini

zaman kardeş

ne yer ne içersin

uykun gelmez mi

hiç senin

o kadar hızlı

gidiyorsun ki

durağın yok

sohbet edelim

neye bindin

gidiyorsun

bizden kaçıyorsan

kime yetişeceksin

kulağıma fısılda

biz de bilelim', 'bana anlat kendini zaman kardeş ne yer ne içersin uykun gelmez mi hiç senin o kadar hızlı gidiyorsun ki durağın yok sohbet edelim neye bindi...', ARRAY['Türk Edebiyatı','Şiir','Altay Taşkın']::text[], 8.5, '{"poet":"Altay Taşkın","poet_slug":"altay-taskin","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/zamanin-araci-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkıma', 'askima-safak-kilinc-2ryc6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kimbilir kaçıncı kere

Göç ediyor turnalar,

Kaç kere geldiler acaba.

Zemherinin ayazı kaç kere esti yüreğimde

                                                      saymadım

                                                       yoktun......

Düşüncelerin bittiği yerdesin hep.

Hangi vakit yitirdi anlamını düşünceler

                                         ordasın sen...

Üç bayramdır

Dalsız ağaç gibiyim.

Çiçeksiz toprak.

Balıksız deniz

Kumsuz çöl gibiyim

Kaçıncı gündür

Aysız gece 

Güneşsiz gün gibiyim.

KIsacası güzel aşkım

Yağmursuz bahar gibiyim

Yoksun,yokum.....

                        05,01,2003', 'Kimbilir kaçıncı kere Göç ediyor turnalar, Kaç kere geldiler acaba. Zemherinin ayazı kaç kere esti yüreğimde                                ...', ARRAY['Türk Edebiyatı','Şiir','Şafak Kılınç']::text[], 8.5, '{"poet":"Şafak Kılınç","poet_slug":"safak-kilinc","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/askima-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur', 'yagmur-safak-kilinc-0calg', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yağmur yağıyor

Havada hep beğendiğim toprak kokusu

Hafif puslu bir gökyüzü

Balkona çıktım

Tuttum yüzümü,avuçlarımı

                           Yağmura....

Nasılda sımsıcak bir serinlikti O....

Evet,evet bak

Güneş çıktı çıkacak

Gözkırpıyor gri bulutlar arasından

Yağmur 

          ve

               Güneş....

İşte,işte oldu pırıl pırıl renkleriyle

Gökkuşağı

Şimdi

Gözlerimde

Yağmur ve saçlarında tacı....

                           01,02,2002', 'Yağmur yağıyor Havada hep beğendiğim toprak kokusu Hafif puslu bir gökyüzü Balkona çıktım Tuttum yüzümü,avuçlarımı                          ...', ARRAY['Türk Edebiyatı','Şiir','Şafak Kılınç']::text[], 8.5, '{"poet":"Şafak Kılınç","poet_slug":"safak-kilinc","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/yagmur-154-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beşi Birlik', 'besi-birlik-mehmet-halil-2iudd', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İlk, seksen eylülünde tanıdık,

bizde, beşi birlik denildi.

küresel merkez sahip çıktı,

yoksa piç kalacaklardı. 

Bir ipe sıralanmış gibi,

Yan yana düzülmüşlerdi.

yerine gelmişti 

küresel merkezin keyfi

Sonra öğrendim altın olduğunu,

Beşibirlik denilen şeyin.

beşi birlik baş köşeye oturdu.

Bir kısmı nefret etti altından,

Altının hastasıydı, çoğunluğu.

Beşibirlik çıkınca ekrana, 

Askeri eşya satan.

konfeksiyon mağazasını andırıyordu,

Yandakiler put gibi duruyor,

Ortadaki konuşuyordu.

Halka giydirilecek kıyafeti,

Ve kumaşı tanıtıyordu.

Ben bunu giymem diyenler çok azdı,

Çoğunluk susuyordu.

o günlerde konuşmak cesaret istiyordu.

Beşibirlik, demokrasi adına,

Dolunay görmüş kurt gibi uluyordu.

Cinayetler ve kayıplar kabarıyordu.

baş kaldıracak başımız yoktu.

Mevsime göre giyinenler,

Hemen haki renklere büründüler.

Beklemedikleri ilgi karşısında,

Onlar da kendilerine güvendiler.

Daha çok konuşup, 

daha çok kükrediler.

Zamanla çoğunluk anladı,

Beşibirlik sözü yalanmış.

Hepsi çöpe atıldı.

Hepsi kapkara! 

Hepsi paslanmış.

Geriye, 

dibi kireçlenmiş çaydanlık gibi...

Bir hurda bıraktılar.

Kireçler kazındıkça, delikler açılıyor.

Bu gün,

Delikleri kapatmaya güç yetmiyor, 

O gün, baş kaldıracak başımız yoktu,

Bugün, karnımızı doyuracak aşımız yok.

Ve hala, laf çok ama...

doğrulacak güç yok.', 'İlk, seksen eylülünde tanıdık, bizde, beşi birlik denildi. küresel merkez sahip çıktı, yoksa piç kalacaklardı.  Bir ipe sıralanmış gibi, Yan...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Halil']::text[], 8.5, '{"poet":"Mehmet Halil","poet_slug":"mehmet-halil","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/besi-birlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umut', 'umut-safak-kilinc-94bbr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kimbilir,

Kaç zemheri ayazı yaladı yüreğimizi

Keskin bir bıçak gibi.

Oltu taşından keder siyahı

Tesbih misali çektiklerimiz.

Taş duvarlara vurulmuş

Kıbaç gibi patlar yüzümüzde

Hüzün başlangıçları.

Kaç hazanda 

Baharlara gebe kalmıştı hayallerimiz.

Ve

Kısır bir kadın gibi 

Doğurmaktan aciz.

Mevsimsiz açtı belki

Baharda kardelen 

Kış ortasında gelincik.

Evet

Kelebek ömürlü oldu hayallerimiz

Ama umutlar yüreğimizde 

Engin bir deniz....

                                   07,01,2003', 'Kimbilir, Kaç zemheri ayazı yaladı yüreğimizi Keskin bir bıçak gibi. Oltu taşından keder siyahı Tesbih misali çektiklerimiz. Taş duvarlara v...', ARRAY['Türk Edebiyatı','Şiir','Şafak Kılınç']::text[], 8.5, '{"poet":"Şafak Kılınç","poet_slug":"safak-kilinc","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/umut-153-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mum ışığı', 'mum-isigi-safak-kilinc-bqqnc', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hiç

Mum ateşinde ısındınmı

                                  Sen...

Hiç

Mum ışığında üşüdünmü

FM''de bir radyoda

Şarkı dinlerken.

Hiç

Karanlıkta yolunu buldunda

Gün ışığında kaybettinmi.

Hani düşerya palamut

Ardından sincap

Öyle düştün yüreğimden

Ardından hayallerim...

                     20,01,2002', 'Hiç Mum ateşinde ısındınmı                                   Sen... Hiç Mum ışığında üşüdünmü FM''de bir radyoda Şarkı dinlerken. Hiç Karanlı...', ARRAY['Türk Edebiyatı','Şiir','Şafak Kılınç']::text[], 8.5, '{"poet":"Şafak Kılınç","poet_slug":"safak-kilinc","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/mum-isigi-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hadi', 'hadi-suleyman-yavuz-hki31', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hadi eğilme dik dur 

Yıkılma diren 

Bu hayat denen sınavı 

Bir sen birde ben olayım yenen 

Bir de efsane sevdam 

Ağlama sevinçten bile olsa 

Sakın akıtma gözünün yaşını 

Hadi eğme kaldır başını 

Yürü o dikenli acı kaplı ıssız yoldan 

Bak sonunda ben olacağım 

Sevdamız olacak 

Birde ikimizi bekleyen

O güllerle kaplı bahçesiyle küçük evimiz', 'Hadi eğilme dik dur  Yıkılma diren  Bu hayat denen sınavı  Bir sen birde ben olayım yenen  Bir de efsane sevdam  Ağlama sevinçten bile olsa ...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Yavuz']::text[], 8.5, '{"poet":"Süleyman Yavuz","poet_slug":"suleyman-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/hadi-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen ki', 'sen-ki-suleyman-yavuz-vf0n8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sesim Haykırış Olmuş

Nefesim Fırtına Olmuş

Göz Yaşlarım Sel Olmuş

Kimse Ölmemiş 

Kimse Duymamış 

Kimse Kaybolmamış Bende

Bir Tek Sen Yok Oldun Bu Halimden Sonra

Sen Ki Vefasız Sen Ki İnsafsızsın 

Sen Ki Sen Ki...

Seni Çok Sevdim Gerisi 

Yalan Ki....

Ey Vicdansız Sevgili', 'Sesim Haykırış Olmuş Nefesim Fırtına Olmuş Göz Yaşlarım Sel Olmuş Kimse Ölmemiş  Kimse Duymamış  Kimse Kaybolmamış Bende Bir Tek Sen Yok Old...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Yavuz']::text[], 8.5, '{"poet":"Süleyman Yavuz","poet_slug":"suleyman-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sen-ki-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ararken', 'ararken-ozkan-sahin-u8jru', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ararken

Hayat az birşey yaşamak

Çok bir şeyde ölmektir

Aslımda gömülen bizler değil

Yaşanan acılardır zevk ararken', 'Ararken Hayat az birşey yaşamak Çok bir şeyde ölmektir Aslımda gömülen bizler değil Yaşanan acılardır zevk ararken...', ARRAY['Türk Edebiyatı','Şiir','Özkan Şahin']::text[], 8.5, '{"poet":"Özkan Şahin","poet_slug":"ozkan-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/ararken-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki Şart', 'i-ki-sart-ozkan-sahin-x661q', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İKİ ŞART

Yaşamak agir basar, 

Ölüm olur bir hafiflik. 

Can sevgiye koşar, 

Tatmak için bir nefeslik. 

Sebeb değilmi hepsi, 

Tükenen binlerce nefes 

Tatmak için bir o nefsi, 

Yırtar dağları şu heves. 

Ne demek olduğunu, 

Öğrenmeye başlarsın sabrın 

Zaman dört nala koşarken, 

Farkına varmazsın yaşamın. 

İki seçenek vardır ortada, 

Ya kendini kandırırsın, 

Yada herkezi sen kandırırsın,

O zaman umutlarını yaşarsın.', 'İKİ ŞART Yaşamak agir basar,  Ölüm olur bir hafiflik.  Can sevgiye koşar,  Tatmak için bir nefeslik.  Sebeb değilmi hepsi,  Tükenen binlerce...', ARRAY['Türk Edebiyatı','Şiir','Özkan Şahin']::text[], 8.5, '{"poet":"Özkan Şahin","poet_slug":"ozkan-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/iki-sart-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaçmak', 'kacmak-ozkan-sahin-1gbip', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'KAÇMAK

Kendinden, 

Aşkindan, 

Umuttan, 

Komuttan, 

Paradan, 

Vardan, 

Yoktan,

Ya! 

Ölümden.', 'KAÇMAK Kendinden,  Aşkindan,  Umuttan,  Komuttan,  Paradan,  Vardan,  Yoktan, Ya!  Ölümden....', ARRAY['Türk Edebiyatı','Şiir','Özkan Şahin']::text[], 8.5, '{"poet":"Özkan Şahin","poet_slug":"ozkan-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/kacmak-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unuturum Ölünce', 'unuturum-olunce-ozkan-sahin-pkw5k', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'ÖLÜNCE

Unuturum ben seni, 

Unuturum her şeyini, 

Bir gün ihanetinide, 

Unuturum ölünce...', 'ÖLÜNCE Unuturum ben seni,  Unuturum her şeyini,  Bir gün ihanetinide,  Unuturum ölünce......', ARRAY['Türk Edebiyatı','Şiir','Özkan Şahin']::text[], 8.5, '{"poet":"Özkan Şahin","poet_slug":"ozkan-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/unuturum-olunce-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dilim Pas', 'dilim-pas-ozkan-sahin-c3hhj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'DİLİM PAS

Öyle günler olur ki, 

Acıları eş ölmeye. 

Yalnızlığı sen bil ki, 

Muhtaçtır sevilmeye. 

Gözlerimdeki yaş kim, 

Dilim pas söylemeye. 

Çarem susmaktır belki. 

Zaman en büyük çare 

Unutmuş beni, 

Sevgimi 

Herşeyi 

Ona dilim varmıyor 

Söylemeye 

O kadar zaman, 

Ruhuma 

İşlemiş, 

Unutmak 

Kolay mı kolay mı ki; 

Söylesene! 

Bu bir sevgi...', 'DİLİM PAS Öyle günler olur ki,  Acıları eş ölmeye.  Yalnızlığı sen bil ki,  Muhtaçtır sevilmeye.  Gözlerimdeki yaş kim,  Dilim pas söylemeye...', ARRAY['Türk Edebiyatı','Şiir','Özkan Şahin']::text[], 8.5, '{"poet":"Özkan Şahin","poet_slug":"ozkan-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/dilim-pas-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Gün', 'o-gun-ozkan-sahin-93a5q', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'O GUN

gun gelir o gün 

gul belirir 

sarımı dersin 

kirmizimi 

beyazmi yoksa 

karami! 

gun gelince goreceksin 

daha elimde degil 

bil yüregimde 

ama ne renk 

gun gelir elimde belirir 

secme hakkin dortte iki 

tahmin ettin belkide 

ama olsun be canim 

yüregimdeki elimde bitecek ya 

sonra senin elinde 

yureklere karişip 

islak gözlerde 

sulanacak ya 

yuregimizdeki 

gulumseyislerle :)', 'O GUN gun gelir o gün  gul belirir  sarımı dersin  kirmizimi  beyazmi yoksa  karami!  gun gelince goreceksin  daha elimde degil  bil yüregim...', ARRAY['Türk Edebiyatı','Şiir','Özkan Şahin']::text[], 8.5, '{"poet":"Özkan Şahin","poet_slug":"ozkan-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/o-gun-36-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Emişir', 'emisir-yusuf-ter-8zh29', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Iraktan gelir çay kokusu

Geceleri öten çırçır böcekleri

Kil kokulu toprak

Unutamadığım adın

Soğuk düş sokaklarında

Kuru ayaz ürpertici ısıtmaz

Türküler söylenir gecelerinde

Yalın bakışlıdır sevginin

Kırlara düşer yüz bin kere izi kalır

Yumuk titreşen dudaklarda

Avazın tutkular geride

Emişir-emişir  sarıldığında

Yusuf Ter 15.12.04

Saat 18:53 İsviçre', 'Iraktan gelir çay kokusu Geceleri öten çırçır böcekleri Kil kokulu toprak Unutamadığım adın Soğuk düş sokaklarında Kuru ayaz ürpertici ısıtm...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ter']::text[], 8.5, '{"poet":"Yusuf Ter","poet_slug":"yusuf-ter","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/emisir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim Cennetim', 'benim-cennetim-yusuf-ter-95s69', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben bende değilim

Ben senin baktığın yerdeyim

Güneşi içimde erittim

Ay gibi kömür karası

Kuyruklu yıldız

Ve hava 

Dilleri kem,lâl

Kor düşmüş

Ak olmuş sacları

Gönlümün ıssız yerinde gizledim

Kalemimin en uç noktasında

Bakışların uslanmaz

Gözlerin yırtıcı

Seni sen olduğun için sevmiştim

Şu gurbet ellerde

Benim cennetim…

Yusuf  Ter 15.12.04

Saat 18:35 İsviçre', 'Ben bende değilim Ben senin baktığın yerdeyim Güneşi içimde erittim Ay gibi kömür karası Kuyruklu yıldız Ve hava  Dilleri kem,lâl Kor düşmüş...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ter']::text[], 8.5, '{"poet":"Yusuf Ter","poet_slug":"yusuf-ter","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/benim-cennetim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Salınım', 'salinim-yusuf-ter-o5r43', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'isyanım

duygularım

aşkım

karanlıkta sevişmelerimdir …

yaz gülümdür sokaklarda

düşlerimin sevdası

dünyamın nefesi

gecenin yıldızıdır…

içimde  akan nehir

dağların sevdalı doruğu

benim türküm olur

kapalı kutum…

yarınların çığlığı

ölümün izi

gök ile yerin arasında

bir çocuk düşü bende…

elle tutulmaz gözle görülmez 

deprem 

gözdeki damla 

denizler okşayan ellerini  bulur…

bulanık suyun durgun yüzü

yarin zülfü teli

avuçlarımın nasırı

duvarlara türkü söyleyen rüzgar

Salınım sarı sıcak  şiir bahçesi…

Yusuf Ter 06.12.04

Saat 00:22 İsviçre', 'isyanım duygularım aşkım karanlıkta sevişmelerimdir … yaz gülümdür sokaklarda düşlerimin sevdası dünyamın nefesi gecenin yıldızıdır… içimde ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ter']::text[], 8.5, '{"poet":"Yusuf Ter","poet_slug":"yusuf-ter","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/salinim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dansa Davet', 'dansa-davet-gokhan-oflazoglu-8jq2r', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'O güzeller güzeli, davetiye göndermiş.

Bu gece dans var, sen de gelseydin diye.

Hayır demek mümkün mü, eğlenmek

benim de hakkım. Yalnız yeri belli değil.

Adresini vermemiş.

12/12/96', 'O güzeller güzeli, davetiye göndermiş. Bu gece dans var, sen de gelseydin diye. Hayır demek mümkün mü, eğlenmek benim de hakkım. Yalnız yeri...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Oflazoğlu']::text[], 8.5, '{"poet":"Gökhan Oflazoğlu","poet_slug":"gokhan-oflazoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/dansa-davet-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yabancı', 'yabanci-gokhan-oflazoglu-95uri', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bak bu konuşan ben değilim,

koşulların zorladığı, bir de sen.

Nasıl kendim olayım....? 

Dönerim bakarım da

olmadığımı yaşadım.

Olduğumsa hep derinlerde.

Çıkarım ya... onlar, bir de sen.

Olmadığımı yaşarım.

1978', 'Bak bu konuşan ben değilim, koşulların zorladığı, bir de sen. Nasıl kendim olayım....?  Dönerim bakarım da olmadığımı yaşadım. Olduğumsa hep...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Oflazoğlu']::text[], 8.5, '{"poet":"Gökhan Oflazoğlu","poet_slug":"gokhan-oflazoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yabanci-37-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sona Doğru', 'sona-dogru-gokhan-oflazoglu-f0e24', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kapandı kapılar.

Boğulmaktayız ha.

Çöküyor yapılar,

yıkılmaktayız ha.

Son hızla doğsa da güneş

ona kılıf örmekteyiz ha.

1978', 'Kapandı kapılar. Boğulmaktayız ha. Çöküyor yapılar, yıkılmaktayız ha. Son hızla doğsa da güneş ona kılıf örmekteyiz ha. 1978...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Oflazoğlu']::text[], 8.5, '{"poet":"Gökhan Oflazoğlu","poet_slug":"gokhan-oflazoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/sona-dogru-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ali imran 103', 'ali-imran-103-kadir-soyturk-q7mbm', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ali İmran 103 ü,okuyun kardeşlerim

Yapın vazifenizi, gerisine Hak kerim! 

Hepiniz kardeş olun; ne küsün ne darılın; 

Yüce İslam Dinine hep birlikte sarılın.

Nimet kadri bilmeyen nankörlerden olmayın,

Şımarıp-sapıtıp da,belanızı bulmayın! 

Biraz akıllı olun; çekmeyin ipinizi...

Yoksa ateş çukuru,yutatacak hepinizi!', 'Ali İmran 103 ü,okuyun kardeşlerim Yapın vazifenizi, gerisine Hak kerim!  Hepiniz kardeş olun; ne küsün ne darılın;  Yüce İslam Dinine hep b...', ARRAY['Türk Edebiyatı','Şiir','Kadir Soytürk']::text[], 8.5, '{"poet":"Kadir Soytürk","poet_slug":"kadir-soyturk","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ali-imran-103-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son gülüş', 'son-gulus-gulden-karabudak-arjae', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sormadan geçti ellerimden hayat

Sağıldı mazisi gülücüklerin

Vurgulanan yalnız ben,

Son virgülle sığ bir anı düşer içimden

Mahrumuyum kardelenlerin

Beyazıyla yarenliği süslenen 

Masal misali sürüklenir deli ömür

Geçip gidene bir türkü yaktıramam 

Sebebi aranmaz 

Ağladığım yerde çürür zaman

Kelamsız  kalır duvarlar

Kırılır da../

Ben “o son gülüşe”

Bir kalem kırdıramam…', 'Sormadan geçti ellerimden hayat Sağıldı mazisi gülücüklerin Vurgulanan yalnız ben, Son virgülle sığ bir anı düşer içimden Mahrumuyum kardele...', ARRAY['Türk Edebiyatı','Şiir','Gülden Karabudak']::text[], 8.5, '{"poet":"Gülden Karabudak","poet_slug":"gulden-karabudak","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/son-gulus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Enfal, Ayet:46', 'enfal-ayet-46-kadir-soyturk-ox68o', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Enfal Ayet 46, bakınız ne buyurur ? 

Allah ve Rasulüne itaatı duyurur! 

Kardeşin,kardeş ile vuruşması nasıl iş? 

Selamete götürmez,Hakka aykırı gidiş! 

Parça parça olmayın; kuvvetiniz kaybolur.

Düşman sizi ezmeğe; zulmetmeğe yol bulur! 

Allah''dan gayrısına, yalvarıp-yakarmayın; 

Sabır silahınızdır; sakın ha çıkarmayın!', 'Enfal Ayet 46, bakınız ne buyurur ?  Allah ve Rasulüne itaatı duyurur!  Kardeşin,kardeş ile vuruşması nasıl iş?  Selamete götürmez,Hakka ayk...', ARRAY['Türk Edebiyatı','Şiir','Kadir Soytürk']::text[], 8.5, '{"poet":"Kadir Soytürk","poet_slug":"kadir-soyturk","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/enfal-ayet-46-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgin Yüreğimde', 'sevgin-yuregimde-i-brahim-necati-gunay-gu1vz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Nasıl geçti habersiz ah o gençlik yıllarım,

Mazide kaldı ah o mutlu anlarım,

Gelmez yinede gelmez ah o yıllarım,

Mazide kaldı ah o mutlu anlarım.

Çalar sazlar ah söyler kızlar,

Düşündükçe ah kalbim sızlar,

Nazende sazlar ah güzel kızlar,

Düşündükçe ah kalbim sızlar.

Apansız uyanınca ah gecenin bir yerinde,

Düşündüm bir tek seni ah geçmedi sevgin yüreğimin içinde,

Günler geldi geçti ah yıllar deldi geçti sevgin yıllar içinde,

Düşündüm bir tek seni ah geçmedi sevgin yüreğimin içinde.', 'Nasıl geçti habersiz ah o gençlik yıllarım, Mazide kaldı ah o mutlu anlarım, Gelmez yinede gelmez ah o yıllarım, Mazide kaldı ah o mutlu anl...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Necati Günay']::text[], 8.5, '{"poet":"İbrahim Necati Günay","poet_slug":"i-brahim-necati-gunay","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sevgin-yuregimde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tereddütler-4', 'tereddutler-4-hasan-sun-iq8j7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '(6.

geceler! 

(kutsal gecelerde dahil)

ku(r)  tsal açlık başlayınca

ülkenin yarısı dilenci durumunda

başlar sömürdükleriyle merhamet dağıtmaya

sevap kolleksiyoncuları

7.

yaşanan dünya fareler ayı

sonra yine lağamlara,kedilerden kaçmaya

8.

kapanırmı bir gün bu yalancı okul

çıkarmıyım geceden ekmek buğusuna

yeşersinmi bu coğrafyada da bilinç

erişirmiyiz insan olmanın onuruna

değermi yüzlerimize özgürlük alazı

 gömülsünmü yalancı tarih evrim ışığında) 

                                            (kasım/2004/göksun)', '(6. geceler!  (kutsal gecelerde dahil) ku(r)  tsal açlık başlayınca ülkenin yarısı dilenci durumunda başlar sömürdükleriyle merhamet dağıtma...', ARRAY['Türk Edebiyatı','Şiir','Hasan Sun']::text[], 8.5, '{"poet":"Hasan Sun","poet_slug":"hasan-sun","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/tereddutler-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeter Artık..', 'yeter-artik-hulya-arisan-aja7c', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yeter artık!

seni yanımda hissetmeliyim.

Bir mahkûmun gün ışığına hasreti gibi

seni bekliyorum.

Çöllerde susuz kalan yolcu misali

''sen'' diye inliyorum.

Adını benliğime ektim yerini beğendi

her an canlı ve taze.

AŞKını kilim motifi,

nakış gibi yüreğime işledim.

O kadar yakıştı ki

dokudukça büyüyor süsleniyor!

İstanbul, 16 Aralık 2004', 'Yeter artık! seni yanımda hissetmeliyim. Bir mahkûmun gün ışığına hasreti gibi seni bekliyorum. Çöllerde susuz kalan yolcu misali ''sen'' diye...', ARRAY['Türk Edebiyatı','Şiir','Hülya Arısan']::text[], 8.5, '{"poet":"Hülya Arısan","poet_slug":"hulya-arisan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yeter-artik-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yemin', 'yemin-derin-oger-t6scy', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'göğün suya düşen mavi kızıl aksi

sıradan sarhoş bir gün ile

gölgelere karışıp kaldırımlara dökülüşü

ah yitik zamanların har ateşi nar ateşi

uykunun koyna sessizce süzülüşü 

gönlü ağır hafif burkup büküşü

karmaşık rüyaların çığırtkan dudaklarında

yarınlara sonsuzca susayıpta susmaya yeminli..........', 'göğün suya düşen mavi kızıl aksi sıradan sarhoş bir gün ile gölgelere karışıp kaldırımlara dökülüşü ah yitik zamanların har ateşi nar ateşi ...', ARRAY['Türk Edebiyatı','Şiir','Derin Öger']::text[], 8.5, '{"poet":"Derin Öger","poet_slug":"derin-oger","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yemin-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Maya', 'maya-guler-ilgaz-bvv4z', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sevgili Özdemir Asaf’a

Sisler sarmıştı her yanımı

Sarmaşık misali

Ne ben ben olabiliyor

Ne sen sen olabiliyordun

...........................................

Gözüm gözünü görmüyordu ki

Kaybolmuştum içimizde

Bir örtü kaplamıştı

Her yanımı

Kapana sıkışmış gibiydim sanki

..............................................

El yordamı misali

Seni benden

Ah bir ayırabilsem diyordum

Her yanımdan ter

Her yanımdan kan akıyordu sanki

...............................................

Bir ışık, bir ışık diyordum

Ve de bir kristal olsun istiyordum elimde

Ayırsam, görsem diyordum

Sisler sarmışken her yanımı

Dallar budaklar kaplamışken

Nasıl da çaresiz

Nasıl da yürekliydim

Bir bilebilsen ahhh...

...................................................

Bir öykü mü yürürdü

Senden bana

Benden sana baktığımda

Sadece ayrılık anlarımız mı yazılırdı yoksa

Evrende

...................................................

Yine de her şeye rağmen

Güzeldi biliyorum yaşadıklarımız

Renkler oluştu ya etrafımızda

Işıkla

Bilgi doğdu ya belleğimize

Işıkla

Adı ne olursa olsun

İşte buradayız ya

İşte görüyoruz ya birlikte

.....................................................

Sen ben, ben sen

Olmuşsak ne çıkar

Birlikteyiz ya

Işıkla sarılıp

Sarmalanmışız ya

Sisleri yırtıp ta

Akmışız ya

Şu ana

........................................

Kısır döngüden çıkmışız ya

Şimdi anlatsınlar

Yürekleri yetiyorsa

Seni bana, beni sana....', 'Sevgili Özdemir Asaf’a Sisler sarmıştı her yanımı Sarmaşık misali Ne ben ben olabiliyor Ne sen sen olabiliyordun ..............................', ARRAY['Türk Edebiyatı','Şiir','Güler Ilgaz']::text[], 8.5, '{"poet":"Güler Ilgaz","poet_slug":"guler-ilgaz","theme":"Türk Şiiri","is_hero":false,"total_lines":56,"source_url":"https://www.antoloji.com/maya-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ay Kayboluyor', 'ay-kayboluyor-ahmet-ozturk-lley6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'ay kayboluyor bu gece

dev deryanın dev dalgaları

beklemek ömür boyu sıcak suları

bu gece ay kayboluyor

o kadar mı uzak

kayalar yuvarlanacak buraya

yüreklerin gözesinden bir sızıntı

buraya akamayacak mı

uzak mı o kadar

yalın ayaklar dağları yürüyor

leşimi bekliyorlar etraflıca

buradan orası bir nefes

yüreklerin gözesinden bir sızıntı

vuslata rüzgar ol es

(23:20) 

(05 EYLÜL 2004)', 'ay kayboluyor bu gece dev deryanın dev dalgaları beklemek ömür boyu sıcak suları bu gece ay kayboluyor o kadar mı uzak kayalar yuvarlanacak ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Öztürk']::text[], 8.5, '{"poet":"Ahmet Öztürk","poet_slug":"ahmet-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ay-kayboluyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kubbealtı', 'kubbealti-ahmet-ozturk-1ed9s', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'kör, zehir ve balçık kubbealtı

eninden boyuna iğreti ve uzak

yanıbaşında uzak

içimden ağlayan bir taş parçası

tanıyanlardan bilinmeyen sabahsız günler

kubbealtı göçük, terlere boğulmuş

kaybolmuş gözler yığını izliyor etrafı

yolumu bulamıyorum gördükleriyle

allah diyorum ama hecesi bile ağır

yüreğime nefesi bile geniş

bekliyorum kubbenin altında

bulutlar kartal gibi süzülüyorken

beklenen gelecekse hafakanlarıma

beni kaybolmuş gözlerle bulmasın

(21:23) 

(06 EYLÜL 2004)', 'kör, zehir ve balçık kubbealtı eninden boyuna iğreti ve uzak yanıbaşında uzak içimden ağlayan bir taş parçası tanıyanlardan bilinmeyen sabah...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Öztürk']::text[], 8.5, '{"poet":"Ahmet Öztürk","poet_slug":"ahmet-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kubbealti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oltada Balık Gibi', 'oltada-balik-gibi-ahmet-ozturk-fbvs3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'süzülüyordum uzak zamanlara doğru

yere yaklaşmadım desem yeridir

göğüdür

gözlerimi  beride bıraktım biliyorum

isyanınız bundan mı

takibiniz bundan

oltada balık gibi ileriye uğraşıyorum

ben... insanoğlu ahmet

öteye değemiyorum

kurulmadım ki bunun için

mücadelem bundan mı acep

beklenen fırtına anıyım

sessiz ve gergin

bir  gün bin güne değeceğim

(14:33) 

(02 EKİM 2004)', 'süzülüyordum uzak zamanlara doğru yere yaklaşmadım desem yeridir göğüdür gözlerimi  beride bıraktım biliyorum isyanınız bundan mı takibiniz ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Öztürk']::text[], 8.5, '{"poet":"Ahmet Öztürk","poet_slug":"ahmet-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/oltada-balik-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Esin', 'esin-abdullah-belen-tm5us', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hani bazen aşk şiirleri yazıyorum ya

İlham diyorlar, gelmezse olmuyor

Elimin kaleme yabancılaştığı

Dilimin şarkılardan uzaklaştığı 

Gönlümde kocaman oyukların oluştuğu bir zamandı 

Sen  geldin tatlım

Sen açıktan ağladın 

Ben gizli gizli 

Sen anlattın derdini

Aldın istediğini

Ben duyuramadım sesimi

Bazen dumanlı dağlarda gördüm kendimi

Bazen düşen yapraklara bindim

Açan çiçek benim değil

Hep senin umudun oldu

Üzülmedim, kıskanmadım

Sen güldükçe ben de güldüm

Sarılıp her öpüşünde 

İnan senden mutlu oldum

İşte kızım onun için 

Ben adını Esin koydum', 'Hani bazen aşk şiirleri yazıyorum ya İlham diyorlar, gelmezse olmuyor Elimin kaleme yabancılaştığı Dilimin şarkılardan uzaklaştığı  Gönlümde...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Belen']::text[], 8.5, '{"poet":"Abdullah Belen","poet_slug":"abdullah-belen","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/esin-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bende Kalan', 'bende-kalan-derin-oger-ta0bd', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'gün güneşini uğurladı

dar bu yürek

kucak kucak dalgalar misali

hayaller ıslak

hüzün sinmiş rüzgarın sesi

sarı kuru bir yaprak

gözlerim acı da durdu

tanıyabilirmisin gülüşümü gün ışımadan

saatler kum yığını

bulutların denize dökülüşü yalan

hapsedilmiş iki damla yaştı

seni bende bırakan

rüzgâr göğe yol aldı

biraz sisli biraz sessiz

bakışlarım özlemle ardından salındı

gözlerimde iki damla yaş olasın geldi

ve ben sana iplik iplik

yanağımdan süzülen sen değildi

sen değildi..................', 'gün güneşini uğurladı dar bu yürek kucak kucak dalgalar misali hayaller ıslak hüzün sinmiş rüzgarın sesi sarı kuru bir yaprak gözlerim acı d...', ARRAY['Türk Edebiyatı','Şiir','Derin Öger']::text[], 8.5, '{"poet":"Derin Öger","poet_slug":"derin-oger","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/bende-kalan-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Tek Beni Sevemedin', 'bir-tek-beni-sevemedin-cafer-yilmaz-gwhjc', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'bir tek beni sevemedin bu şehirde…

hep takılıp giderdin 

boğazdan geçen her geminin peşinden

ve sonra geri gelirdin

herkesi severdin…

bir tek beni sevemedin…

ufacıktı bu şehir… bir bebeğin avucu kadar…

sen her geçişimde önümden

gözlerim dalar,

yüreğim kanar…

sen beni hep elimde köpek öldürenle bildin

ağzımda Bafra cigara.

Üstüm başım yırtık

Yani anlayacağın yakışmazdım aslında sana…

Bazen sabahları gelir iskeleden ekmek atardın martılara

Martılar seni severdi ve beklerdi her sabah gelmeni…

Hani dikip şu elimdekini sonuna kadar

Martı oluveresim gelirdi…

Ama sen beni öyle de sevmezdin…

Bir tek beni sevemedin bu şehirde…

Bazen kırıta kırıta geçerdin önümden

Laf atanlar olur, sen sadece gülüverirdin…

Oysa bana ait bir gülüşüne ben…. Neyse! 

Simitçi Osman’a, jetoncu Kamil’e

Her sabah ezip beni “günaydın! ” derdin

Gün ayardı…

Bense içtiğim şu meretten midir nedir

Hiç ayamazdım.

Sorsalar sana adım; iskelede bir deli…

Kaldırımda bir sonbahar yaprağı…

Birazdan çöpçüler gelecek

Ve süpürecek beni…

Bir tek beni sevemedin bu şehirde…

Sen her sabah hayallerine gidersin,

Ben her akşam seni hayal ederim.

Bilsen kudurursun lodos dalgaları gibi

Keşke bilsen... ve vursan kıyılarıma...

Daha ne isterim..

Oysa ben, senin için batık bir tekne,

Sen, benim için yep yeni elbise...

Daha yazacaktım şarap bitti...

Hadi neyse...', 'bir tek beni sevemedin bu şehirde… hep takılıp giderdin  boğazdan geçen her geminin peşinden ve sonra geri gelirdin herkesi severdin… bir te...', ARRAY['Türk Edebiyatı','Şiir','Cafer Yılmaz']::text[], 8.5, '{"poet":"Cafer Yılmaz","poet_slug":"cafer-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/bir-tek-beni-sevemedin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızca Ben OlayımYeter', 'yalnizca-ben-olayimyeter-huseyin-erdogan-ftw9l', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bilmem ki 

sende var mıyım canım?

sevgili orkidem günaydın

söyle güzelim

bu sabah sen nasılsın? 

yer yüzünde 

binlerce çiçek olsa da

benim gönül bahçemde 

sen teksin

sen bu dünyadaki 

tek barbi bebeksin

kanatlarında alıp götür 

beni de 

gittiğin her yere 

sen mutluluktan uçan 

bir kelebeksin

havalar öyle soğudu ki 

artık sahiller bile buz gibi

ne gündüzleri ne de geceleri

üşümek istemiyorsan eğer

ne olur  o güzel ellerinle

titreyen ellerimi tutuver

hayalinde düşünde yüreğinde 

yalnızca ben olayım yeter

                        17.12.2004', 'bilmem ki  sende var mıyım canım? sevgili orkidem günaydın söyle güzelim bu sabah sen nasılsın?  yer yüzünde  binlerce çiçek olsa da benim g...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Erdoğan']::text[], 8.5, '{"poet":"Hüseyin Erdoğan","poet_slug":"huseyin-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/yalnizca-ben-olayimyeter-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vefalı dostlar', 'vefali-dostlar-bayram-tunca-82urz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ah nerede vefalı dostlar vefalı dostlar

Ne vakit dara düştümse hep koştular

Sanki her biri bir melekti çok hoştular

Kötülükten kaçıp, hep hayıra koştular

Akar sular gibi coştular ve coşturdular

Gemileri yakarak Hızır gibi koşturdular

Önlerine çıkan engelleri tek tek aştılar

Nerede bir yangın varsa, hep koştular

Öyleleri vardı ki her biri iffet abidesiydi

Öyleleri vardı ki sanki bir melek gibiydi

Ne vakit yüzlerine baksam, içim açılırdı

Adeta, güneş ışı gibi etrafa nur saçılırdı

Doyamadım doyamazdınız onları görmeye

Kıyamadım kıyamazdınız inan ki incitmeye

Çünkü onlar atide beklenen altın nesliydiler

Peygamberimiz tarafından müjdelenmiştiler

16.12.2004-12.16', 'Ah nerede vefalı dostlar vefalı dostlar Ne vakit dara düştümse hep koştular Sanki her biri bir melekti çok hoştular Kötülükten kaçıp, hep ha...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/vefali-dostlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sorma Beni', 'sorma-beni-funda-sag-xjz29', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sorma beni

Kelimeler çok gelir kulaklarına

Beynin almaz

Beynin anlamaz

Karışır 

Başkalarıyla karıştırırsın beni

Sorma beni

Uzağım

İçimdedir herşey,

En yakındakine bile uzağım

En göz önündeki

Ya da en sinsi tuzağım

Sorma beni

Bilenler sağ çıkmadı hiç ertesi güne

Pişman olursun

Düşman olursun…

Öldürmezsen kendin ölürsün…

Sorma beni 

Sadece iyiyim

Sadece çok iyi…

Sorma beni

Sadece öyle bil yeter…', 'Sorma beni Kelimeler çok gelir kulaklarına Beynin almaz Beynin anlamaz Karışır  Başkalarıyla karıştırırsın beni Sorma beni Uzağım İçimdedir ...', ARRAY['Türk Edebiyatı','Şiir','Funda Sağ']::text[], 8.5, '{"poet":"Funda Sağ","poet_slug":"funda-sag","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sorma-beni-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bıkkın', 'bikkin-dogan-sahin-cv0bi', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Pes yani tanrım,

Var mısın yok musun diye

Dünya gözüyle göremeden öleceğim ya,

sanki neden yani? 

Ölüm böylesine korkutur,

sanki neden sorgular ölümü

Ben? 

20.04.2002', 'Pes yani tanrım, Var mısın yok musun diye Dünya gözüyle göremeden öleceğim ya, sanki neden yani?  Ölüm böylesine korkutur, sanki neden sorgu...', ARRAY['Türk Edebiyatı','Şiir','Doğan Şahin']::text[], 8.5, '{"poet":"Doğan Şahin","poet_slug":"dogan-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bikkin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeni Yıl', 'yeni-yil-aynur-baydar-ntttj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İnsanoğlu zamana ayak bastı

Varoldu

İyi ve kötü yan yana durdu

Yeryüzü yok olmayı

Açgözlülüğü, vahşeti

Merhameti, yardımlaşmayı

Yan yana gördü

Bir canlı hem iyi hem kötü

Bu nasıl öykü

Erdemlerle yüksek

Bencillikle alçak

Tek bir canlıda

İnsanda oluştu

Parçalayan yok eden düşman insan

Koruyan güzellik için kendi cinsiyle 

Savaşan gene insan

Aynı türün kıyamete uzanacak 

Bitmeyecek savaşı

Akıl, bilgi, güç, hile

İlk den beri kullanılan araçları

Her gelişme

İyi ile kötüyü büyütme silahları

Ve insanoğlu 2006 ya ayak bastı

Yeryüzünde kanlı, insanın ayak izleri

Kurumuş izler ve tazeler 

Zamanda ilerlemekteler

İyiler yılmış, yorulmuş 

Umutsuzluk kötülüklerle dinazor olmuş

Toz umutlar her zamanda var olmuş

Tek bir kıvılcım

Yenildi, bitti yok edildi 

Denilen anda

Yeniden insanlığın 

Erdemli direnişinin kıvılcımı olmuş 

Ey insan zamana bastığın ilk anda

Zayıf İyi, güçlü kötü rolünden birini seç amma

Dön zamana bak ardına

Her zaman zayıf olan iyiler

Neden asla yok edilemediler

Ve insanoğlu 2006 ya ayak bastı

2006 da minik kıvılcımlar

Yangın umutlar gene vardı

Kötülük karşısında savaşa hazırdı

Not: Bütün antoloji üyelerinin yeni yılını kutlar, dünyaya, insanlığa iyilik güzellik, mutluluk getirmesini dilerim. Saygılarımla', 'İnsanoğlu zamana ayak bastı Varoldu İyi ve kötü yan yana durdu Yeryüzü yok olmayı Açgözlülüğü, vahşeti Merhameti, yardımlaşmayı Yan yana gör...', ARRAY['Türk Edebiyatı','Şiir','Aynur Baydar']::text[], 8.5, '{"poet":"Aynur Baydar","poet_slug":"aynur-baydar","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/yeni-yil-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Masumdular', 'masumdular-dogan-sahin-8gjd4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ne kadar masumdular,

Özgürce uçuşuyorlardı

Yağmur çiseliyordu, Ocak sonu

500 W lık lamba ışığı çiçekleri aydınlatırdı, 

Okuduğum kitabımı aydınlatarak düşüyor yağmur damlaları

yaprağa çarpan tek damla 

binlerce  küçük ışığa dönüşüyordu,

pamuk sineklerini hatırlattılar bana birden, 

ağırlıkları ve yoğunlukları ışık dalgasında..

Serserice yüzüyordu

Ve ben

Şiir muhabbetlerinde

Ve yanıbaşımda dost şarap

Ve tercüme ilk denemeleri

yapiyordum.', 'Ne kadar masumdular, Özgürce uçuşuyorlardı Yağmur çiseliyordu, Ocak sonu 500 W lık lamba ışığı çiçekleri aydınlatırdı,  Okuduğum kitabımı ay...', ARRAY['Türk Edebiyatı','Şiir','Doğan Şahin']::text[], 8.5, '{"poet":"Doğan Şahin","poet_slug":"dogan-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/masumdular-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Muzır Şiir', 'muzir-siir-dogan-sahin-zv8ki', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gözyaşlarım 

Boncuk boncuk

Sidik olmuştu artık

Ve ben daha

Gözlerindeki ışıltının rengini keşfedemeden,

yavrum,

bir yıldız gibi Samanyolu’nun kuyruğundan

Patladı bir baloncuk. 

Kaydı,

Gerdanından aşağı

Soğuk seramiğin

sifonunu çekince....

12. 04. 2002.', 'Gözyaşlarım  Boncuk boncuk Sidik olmuştu artık Ve ben daha Gözlerindeki ışıltının rengini keşfedemeden, yavrum, bir yıldız gibi Samanyolu’nu...', ARRAY['Türk Edebiyatı','Şiir','Doğan Şahin']::text[], 8.5, '{"poet":"Doğan Şahin","poet_slug":"dogan-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/muzir-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yarınlar', 'yarinlar-dogan-sahin-tht4w', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gelecek

Neredeydi? 

Özlemler doğuran

Ve sonra uzun bir aradan sonra

Dörde bölünmüş bir adam

Yargılan, sehven aklan

Sonra huzur

Sana vaat edilen? 

Ey göçmen ruhlu adam

Nerede? 

O çok özlediğin gelecek? 

Ne zaman gelecek,

gelecek', 'Gelecek Neredeydi?  Özlemler doğuran Ve sonra uzun bir aradan sonra Dörde bölünmüş bir adam Yargılan, sehven aklan Sonra huzur Sana vaat edi...', ARRAY['Türk Edebiyatı','Şiir','Doğan Şahin']::text[], 8.5, '{"poet":"Doğan Şahin","poet_slug":"dogan-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yarinlar-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Allahım', 'allahim-dogan-sahin-fsctg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Şimdi; Allahım.

Sen özlemi yaratmışken,

neden? 

Allahım Yani, 

ben,

cevaba muhtaç? 

Neden muhtacım? 

sana ben?', 'Şimdi; Allahım. Sen özlemi yaratmışken, neden?  Allahım Yani,  ben, cevaba muhtaç?  Neden muhtacım?  sana ben?...', ARRAY['Türk Edebiyatı','Şiir','Doğan Şahin']::text[], 8.5, '{"poet":"Doğan Şahin","poet_slug":"dogan-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/allahim-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Yoksan Bu Hayatı Ben Neyleyim?', 'sen-yoksan-bu-hayati-ben-neyleyim-huseyin-erdogan-9okxb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'neden böyle suskunsun dünden beri? 

istemezsen bana hiç dönmeyebilirsin geri

razıyım tebessüm et yeter uzaktan da olsa

ısınsın İstanbul bu soğuk havalarda

bakışlarından mahrum etme beni buralarda

zaman zaman dön yüzünü Marmara''ya

aydınlansın her yer,korkuyorum karanlıklarda

sensizlik her gün öldürüyor beni bin kere

ne olur şairini hasret bırakma sevgilere

bak günlerden bu yana yazdığım şiirlere

sen kokunu vermemiş misin bütün dizelere? 

düşlerimde,hayallerimde,şiirlerimde seninleyim

söyle bana sen yoksan bu hayatı ben neyleyim? 

