INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boşa Gururlanma', 'bosa-gururlanma-ali-kilic-kakiz-m94ld', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dünyada hatıra dokunup yıkıcı olma.

Çabuk gecen bir zevkle gururlanma.

Basiretli insanlar, kaygılanmaz aldanmaz.

Asla, bu yolda dönüp arkaya  bakılmaz.

Maneviyat önderlerinden ilhamı alıp koşmalısın.

Sen bu ulvi zevki gönlünde yaşatıp, tatmalısın. 

..................

Brüksel /2004', 'Dünyada hatıra dokunup yıkıcı olma. Çabuk gecen bir zevkle gururlanma. Basiretli insanlar, kaygılanmaz aldanmaz. Asla, bu yolda dönüp arkaya...', ARRAY['Türk Edebiyatı','Şiir','Ali Kılıç Kakiz']::text[], 8.5, '{"poet":"Ali Kılıç Kakiz","poet_slug":"ali-kilic-kakiz","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bosa-gururlanma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yunus Gibi', 'yunus-gibi-dursun-elmas-zwhaa', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yunus''ça sevdalanır,yine O''nca yanardı

Islak mavi gözleri,zannederdin pınardı.

Yemende deve güder,Veysel sanır kendini

Muhammed''in aşkından tutuşurdu bedeni.

Adı gibi Hamiddi,hamdederdi Rab''bine,

Özünü çevirmişti,O''nun kıblegâhına...

Nerde bir garip görse,hemen orda ağlardı,

Çalışmayı ibadet,hemide farz sayardı...

Çevirmezsin bilirim,sana uzanan eli

Senden başka söylemez,bilmezdi onun dili...

Aksatmadı namazı,hep durdu divanına,

En sonunda secdede kavuştu Rahmanına...

Hiç birimiz bilmedik dedemin kıymetini

Esirgeme Allah''ım dedemden rahmetini...

Sen Rahimsin,Kerimsin muhtacız rahmetine,

Cennetinde komşu et Muhammet ümmetine.', 'Yunus''ça sevdalanır,yine O''nca yanardı Islak mavi gözleri,zannederdin pınardı. Yemende deve güder,Veysel sanır kendini Muhammed''in aşkından ...', ARRAY['Türk Edebiyatı','Şiir','Dursun Elmas']::text[], 8.5, '{"poet":"Dursun Elmas","poet_slug":"dursun-elmas","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yunus-gibi-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doğu Türkistan - Berzah Kitabından', 'dogu-turkistan-berzah-kitabindan-omer-ekinci-micingirt-cimb4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İhtiyar dünyanın dehşet günleri

asırları hep ağu hep hüzün

ölümü özgürlük suçu hürriyet

yüzyılları zindan ve hicran

sokakları kan kokan

matemine siyahlar kuşandığım

yaslı Türkistan

Erenleri yiğitleri devrilmiş

teker teker

çocuklar serpilmiş kızıl karlara

ve sancısı içimde gerilmiş

cesetler toprağa hasret

sarsıntılı susuşlar 

Kızıl Çin yamyamlar pembe yalanlar

ve analara bırakılan vahşi hatıra

analar ağlar kızanlar ağlar

babalarsa acılar içinde

belli etmez asil kanından

Berat Hacim Yusuf Alptekin ve niceleri

onlar gittiler

ya biz

Zulüm püskürtüyor toplama kampları 

kursaklarda prangalar

cesetler toprağa hasret

dağlarına zulüm yağan Türkistan

ve insanlığa arsızca gülümseyen

arsız cüce adam unutma

bir set daha mutlak bir gün

bir set

Vahşet saçıyor mahpushaneler 

ibadethaneler dehşet

duydum ki sürülmüş yine

darağacına kaç fidan', 'İhtiyar dünyanın dehşet günleri asırları hep ağu hep hüzün ölümü özgürlük suçu hürriyet yüzyılları zindan ve hicran sokakları kan kokan mate...', ARRAY['Türk Edebiyatı','Şiir','Ömer Ekinci Micingirt']::text[], 8.5, '{"poet":"Ömer Ekinci Micingirt","poet_slug":"omer-ekinci-micingirt","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/dogu-turkistan-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi Merhamettir', 'sevgi-merhamettir-dursun-elmas-5aazo', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sevgi hissedilir,sevgi yaşanır

Güldeki kokular dile bulaşır.

Sevgiyle dağlanan göğe ulaşır,

Sevmeyi bilmeyen murada ermez.

Sevgi merhamettir,imandan gelir

Onu rehber eden gönül eridir.

Huyu güzel ise edep ehlidir

Mansur''ca yanmayan ölmeye gülmez.

Yunus demiş; Elif üstün ötürü

Kulunu sev Yaradandan ötürü,

Tamiri yok,kırma gönül hatırı

Sevgiye ermeyen Mevla''yı bilmez! ..', 'Sevgi hissedilir,sevgi yaşanır Güldeki kokular dile bulaşır. Sevgiyle dağlanan göğe ulaşır, Sevmeyi bilmeyen murada ermez. Sevgi merhamettir...', ARRAY['Türk Edebiyatı','Şiir','Dursun Elmas']::text[], 8.5, '{"poet":"Dursun Elmas","poet_slug":"dursun-elmas","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sevgi-merhamettir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Açıl ya Susam', 'acil-ya-susam-i-smet-barlioglu-z69nu', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gel bir ‘Açıl ya Susam…’ diyelim

Yolumuza uğru gibi dikilenlere,

Uçurum kesilenlere, attığımız her adımda,

Ayırmak isteyenlere bizi birbirimizden,

‘Açıl ya Susam…’ diyelim,

Sevmenin ne demek olduğunu bilmeyenlere

Sevmesini öğretelim.

Tek bir kere ‘Açıl ya Susam…’ dedinmi

Candan-gönülden

En bir katmerli kayalar bile açılır ardına kadar,

Kim neylesin inciğini-boncuğunu

Ali Baba ‘nın,

Ne demek olduğunu öğrenmeden

Sevdanın.

Samanlıklar seyran olur biz bize kalsak,

Dünya-alem bir bitmeyen bahar olur,

Ne yerde kalır dama çıksak pabucumuz,

Ne arkamız geri çeker,

Ne de el-avuç açarız erenlere,

Gel bir ‘Açıl ya Susam…’ diyelim

Bizi bize çok görenlere.

(Hikmet BARLIOĞLU (1933-2003)  ''nun

BİR ŞARKI SÖYLE BANA İsimli Serbest Şiirler ''inden > 49-50/100)', 'Gel bir ‘Açıl ya Susam…’ diyelim Yolumuza uğru gibi dikilenlere, Uçurum kesilenlere, attığımız her adımda, Ayırmak isteyenlere bizi birbirim...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/acil-ya-susam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizlik', 'sensizlik-i-smet-barlioglu-bs4l9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dün gece sensizlikle boğuştum yine

Sabahlara kadar,

Bir devle bir cücenin boğuşması gibiydi,

Gözlerim yaş içinde kaldı, yüreğim kan,

Feryatlarım vurup vurup yankılandı

Duvarlardan.

Çelikten bir pençe gibi çökmüştü sensizlik

Gırtlağıma,

Elime-ayağıma paslı zincirler vurulup durdu

Güneş doğana kadar,

Ne aşa-ekmeğe uzanabildim,

Ne uykuya,

İnsan sensiz ne çabuk düşüveriyormuş

Kaygıya.

Dün gece sensizlikle boğuştum

Sabahlara kadar,

Karanlıkta ocak dumanı gibi tüttü yüreğim,

Seni içimden çıkarıp avuçlarına aldı ellerim

Ve ben bütün umudumu kestim

Bir güzel geçecek geceden,

Anladım ki bir sen kurtarırsın zincirden kollarımı

Ve ellerimi kelepçeden.

(BİR ŞARKI SÖYLE BANA İsimli Serbest Şiirler ''inden > 51-52/100)', 'Dün gece sensizlikle boğuştum yine Sabahlara kadar, Bir devle bir cücenin boğuşması gibiydi, Gözlerim yaş içinde kaldı, yüreğim kan, Feryatl...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/sensizlik-151-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umudun Kayığı Yoktur', 'umudun-kayigi-yoktur-selim-bayrak-7qho7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Umudun kayığı yoktur

Yüzmesini sen bileceksin

Uğurun adresi çoktur, yoktur

Kısmetine güleceksin

Adı konmuş şiirler 

Gerisini boş ver

Kendine ne vakit ayırdın

Yarini boya ver, ser', 'Umudun kayığı yoktur Yüzmesini sen bileceksin Uğurun adresi çoktur, yoktur Kısmetine güleceksin Adı konmuş şiirler  Gerisini boş ver Kendine...', ARRAY['Türk Edebiyatı','Şiir','Selim Bayrak']::text[], 8.5, '{"poet":"Selim Bayrak","poet_slug":"selim-bayrak","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/umudun-kayigi-yoktur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Resmini Yapıyorum', 'resmini-yapiyorum-i-smet-barlioglu-nq1py', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Biryerde ressam olmuş resmini yapıyorum,

Heykeltıraş olmuş, heykelini,

Pürüzsüz mermerlerde tuta tuta elini,

Öylesine bir resim ki; 

Daha artık ne biter, ne tükenir,

Öylesine bir heykel ki; 

Heykeller imrenir.

Taklar kurup duruyorum içimdeki sokaklara,

Sen gelip geçesin diye altlarından,

Ebemkuşakları yapıyorum

Akıllara durgunluk verecek ölçüde

Görkemli

Ve üstüne etek dolusu renktir ki yağdırıyorum

Nemli.

Denizler doldurdum yüreğime

Ucu-bucağı görünen,

Yalılar ıturttum kıyılarına aralıksız,

Hangisini beğenirsen onda oturasın diye,

Duvarlarda resimlerin,

Bahçelerde heykellerin

Tüm hediye.

(BİR ŞARKI SÖYLE BANA İsimli Serbest Şiirler ''inden > 53-54/100)', 'Biryerde ressam olmuş resmini yapıyorum, Heykeltıraş olmuş, heykelini, Pürüzsüz mermerlerde tuta tuta elini, Öylesine bir resim ki;  Daha ar...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/resmini-yapiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Bayrağı Sana Bıraktılar', 'bu-bayragi-sana-biraktilar-ali-kilic-kakiz-qf1nz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Vakurlu, görkemli yelkenleri atlasdan diken.

Kırılmaz halatları ibrişimden büken sendin. 

Krallara tac giydiren, zalimlere baş eğdiren, 

Görkemli gemileri karada yürüten sendin. 

Bu gün muzdarip, boynu bükük sensin. 

Fakat yarın, mutlaka mutlaka, muzaffersin. 

Asırlar boyu gerçek ilmi üstün ahlakı taşıdılar, 

Şu mubarek ay yıldızlı bayrağı, sana bıraktılar. 

İstikbalimizin güneşi devletimiz yaşıyacak. 

Ezan seslerinin yükseldiği bu vatan batmayacak. 

Brüksel 17/12/2004', 'Vakurlu, görkemli yelkenleri atlasdan diken. Kırılmaz halatları ibrişimden büken sendin.  Krallara tac giydiren, zalimlere baş eğdiren,  Gör...', ARRAY['Türk Edebiyatı','Şiir','Ali Kılıç Kakiz']::text[], 8.5, '{"poet":"Ali Kılıç Kakiz","poet_slug":"ali-kilic-kakiz","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/bu-bayragi-sana-biraktilar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gün Batımlarında Doğarım', 'gun-batimlarinda-dogarim-dursun-elmas-v6v5h', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gün batımlarında doğar,

Ay ışığında bulurum kendimi.

Yıldızlar toplarım

Demet demet

Dökmek için eteklerine...

Seni yaşarım sensizliğimde

Seni,sensiz yaşamak var ya; 

Dokunur erkekliğime,

Şafak vakitlerinde ölürüm...', 'Gün batımlarında doğar, Ay ışığında bulurum kendimi. Yıldızlar toplarım Demet demet Dökmek için eteklerine... Seni yaşarım sensizliğimde Sen...', ARRAY['Türk Edebiyatı','Şiir','Dursun Elmas']::text[], 8.5, '{"poet":"Dursun Elmas","poet_slug":"dursun-elmas","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/gun-batimlarinda-dogarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur Sonrası...', 'yagmur-sonrasi-zulfikar-yapar-kaleli-7xzjp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'font face=''Comic Sans MS'' color=''black'' size=''0,5''

Sicim gibi yağmur, hafif güneş var 

Hafif bir sarhoşluk sarar ya dağı 

Gönlümde gam ile kedere eş var 

İçimde kırılır aşkın bardağı 

Bir tuhaflık olur, burkulur içim 

Ölümün kokusu sarar ovayı! 

Gözümle gönlüme yapamam seçim 

O anda terk eder kuşlar yuvayı 

Bulutlar sildiler yüzünü ayın 

Ağlaması bitmiş bir çocuk gibi 

Yıkadılar on dördünde bir ayın 

Gülümsedi gökyüzünün habibi 

Tatlı bir kokuyla ortalık güldü 

Bir hüzün çöktü ki yürek başına 

Bu koku ruhumu ikiye böldü 

Bakmadı gönlümün tıfıl yaşına 

Bir ürperti aldı içimi birden 

Ebem kuşağını görmedim bile 

Bir sevda yükseldi yedi kat yerden 

Gönlüme yüklendi bu kutlu çile 

Dağa gölge düştü, tepe terledi 

İçimdeki bir el beni burgular 

Bir yitik ses işte O''nu birledi 

Bırakın yakamı sisli duygular', 'font face=''Comic Sans MS'' color=''black'' size=''0,5'' Sicim gibi yağmur, hafif güneş var  Hafif bir sarhoşluk sarar ya dağı  Gönlümde gam ile k...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/yagmur-sonrasi-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çay', 'cay-mehmet-demirkapi-ortso', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir bardak çay,

Ve hayat

Ne güzel şey

Senle olmak,..', 'Bir bardak çay, Ve hayat Ne güzel şey Senle olmak,.....', ARRAY['Türk Edebiyatı','Şiir','Mehmet Demirkapı']::text[], 8.5, '{"poet":"Mehmet Demirkapı","poet_slug":"mehmet-demirkapi","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/cay-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saçmasapan', 'sacmasapan-sair-shimalwest-l5h13', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'dış kapının kilidi

kilitli pencerenin kolu

kolu kırık bir adam

adamın suratında sakal

sakalı seyrek bakışı keskin

keskin fikir dolu beyin

beyni koruyan sağlam kafa

kafa kaplı uzun saçla

saçlar benzemez bıyıklara

bıyık kızıl saç sarı

sarımsı ten ela göz

gözler kısık burun sıradan

saçma geldi değilmi bunlar

düşün bak altından ne çıkar

kısa,sığ,dar bir anlatım

belki herhangi biri

belki kendim', 'dış kapının kilidi kilitli pencerenin kolu kolu kırık bir adam adamın suratında sakal sakalı seyrek bakışı keskin keskin fikir dolu beyin be...', ARRAY['Türk Edebiyatı','Şiir','Şair Shimalwest']::text[], 8.5, '{"poet":"Şair Shimalwest","poet_slug":"sair-shimalwest","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sacmasapan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dal', 'dal-sair-shimalwest-p78y9', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'direnelim fırtanaya

dayanalım akan suya

hortum misali dönerken dünya

tutunalım sağlam bir dala

bir dilek bu herkes için

hep endişeliyiz niçin', 'direnelim fırtanaya dayanalım akan suya hortum misali dönerken dünya tutunalım sağlam bir dala bir dilek bu herkes için hep endişeliyiz niçi...', ARRAY['Türk Edebiyatı','Şiir','Şair Shimalwest']::text[], 8.5, '{"poet":"Şair Shimalwest","poet_slug":"sair-shimalwest","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/dal-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağrılı', 'agrili-aydogan-yavasli-ixgkm', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'yaramaz çocuk kalbim! 

sen şimdi yüksekçe bir yerden bakıp kendine

(birer dizkanamasını andıran

ve kendilerini ancak akşam hüzünlerinde çağrıştıran) 

şarkılar söyleyebilirsin:

kürdîli hicazkâr ya da acemaşîran

bir top fesleğeni andırır(dı) 

kendini kahırlarda ele veren yüzünü

iğreti bir fotoğraf gibi taşıyan başın

kaşların

hırçın bir sağanağın

hırpaladığı sarmaşık yaprakları kadar

ürkek ve yılgın gözlerini saklar(dı) 

yaşamak (elbet)  ezberden bildiğin bir şiir(di) 

                     uyakları cinaslı

oysa sana çılgın kahramanlı

hikâyeler yazılmış ve sen

o tozlu topraklı yolları

nasılsa sulayıp bulutlara salmıştın

alacakaranlık aklını

çocuk yaramaz kalbim! 

mayısta çiçek açar iğde dalları

canlar ölür

kırılan camların sorulur hesabı

iyisi mi ne sen başlamış ol bu şiire

ne ben bulmuş olayım

yerden göğe yağan suların beslediği

o derin ve unutkan ırmakları', 'yaramaz çocuk kalbim!  sen şimdi yüksekçe bir yerden bakıp kendine (birer dizkanamasını andıran ve kendilerini ancak akşam hüzünlerinde çağr...', ARRAY['Türk Edebiyatı','Şiir','Aydoğan Yavaşlı']::text[], 8.5, '{"poet":"Aydoğan Yavaşlı","poet_slug":"aydogan-yavasli","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/agrili-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güler Ağlarım Şimdi', 'guler-aglarim-simdi-huseyin-sigirtmac-3rl3m', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yollara sürdüğüm hasretim bitmez.

Tutulduğum duygu serimden gitmez.

Bin hayal gerçeğin birini etmez.

Yine de hayale dalarım şimdi.

Duyguma sardığım özlem kar değil.

Hasretler yüreğe gizlendi her yıl.

Başımın belası, gam bana  meyil.

Yürek teli gergin çalarım şimdi.

Benim bu hasretim neşedir kime? 

Hayal aleminde zarar kendime.

Kavuşsam tutuşup yanmazdım ama.

Ayrılık benimle yanarım şimdi.

Arzular hasrette, gönül gam çeker.

Sığırtmaç gün gelir menzile yeter.

Yar hayalin neşem, dünyaya değer.

Onunla gülerim ağlarım şimdi.', 'Yollara sürdüğüm hasretim bitmez. Tutulduğum duygu serimden gitmez. Bin hayal gerçeğin birini etmez. Yine de hayale dalarım şimdi. Duyguma s...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Sığırtmaç']::text[], 8.5, '{"poet":"Hüseyin Sığırtmaç","poet_slug":"huseyin-sigirtmac","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/guler-aglarim-simdi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Giderayak Kanatlanır İmgeler', 'giderayak-kanatlanir-i-mgeler-bir-mim-kemal-ertugrul-cbtr4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Uçmasını bekleme

Tek kanatlı bir kuşun

Kanadını eşlesin

Yardıma koşun..! 

Sesine değmek isterdi

Eğilip içmek 

_________dudaklarından...

Neler neler isterdi

Hazır ve nazır

Sesini içmek isterdi

Öptüyse özür..!', 'Uçmasını bekleme Tek kanatlı bir kuşun Kanadını eşlesin Yardıma koşun..!  Sesine değmek isterdi Eğilip içmek  _________dudaklarından... Nele...', ARRAY['Türk Edebiyatı','Şiir','Bir Mim Kemal Ertuğrul']::text[], 8.5, '{"poet":"Bir Mim Kemal Ertuğrul","poet_slug":"bir-mim-kemal-ertugrul","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/giderayak-kanatlanir-imgeler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağsaydın,Susmasaydın', 'yagsaydin-susmasaydin-oner-bagceci-lk60p', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Payındaki cehennemi suya çekebilseydin,

Ayrılığı alınterine sayardın

Ve yetişebilirdin giderken kendine.

Ama artık bilirsin ki keşkeydi.

Keşke hayatı çıkartsaydın,

Bütün sonrasına eşittirlerin.

Sohbeti kavgaya bilendin.

Mutlaka birini çağıracaktın duldana.

Hatırlar mısın, ne güzel ''dostum'' derdin,

Koynunda yatana-çocukluğuna.

Baş harfini kazıdın en sote ağaca.

Sonra adı kanadı  gövdende,

Daldan aşağı bahar bildin.

İntihar söz olunca sen ölendin.

Bir turna süzüldü göğe görseydin.

Tavlaya misafir gelse, yanında şiir,

Söze bulanırdın. Acırdın yağmura bile.

Sonra zar atardın,

Bütün kapıları kapamaya dair.

Kışa bir mektup yazdın,

Mektubundan önce gittin.

                           

                                      27 Ekim 1999', 'Payındaki cehennemi suya çekebilseydin, Ayrılığı alınterine sayardın Ve yetişebilirdin giderken kendine. Ama artık bilirsin ki keşkeydi. Keş...', ARRAY['Türk Edebiyatı','Şiir','Öner Bağçeci']::text[], 8.5, '{"poet":"Öner Bağçeci","poet_slug":"oner-bagceci","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/yagsaydin-susmasaydin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Macera...', 'bu-macera-kadir-soyturk-jwcny', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Geliyorsa masaya, rum – ermeni  sorunu

Hayırlı görünmüyor, bu maceranın sonu!', 'Geliyorsa masaya, rum – ermeni  sorunu Hayırlı görünmüyor, bu maceranın sonu!...', ARRAY['Türk Edebiyatı','Şiir','Kadir Soytürk']::text[], 8.5, '{"poet":"Kadir Soytürk","poet_slug":"kadir-soyturk","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/bu-macera-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Severken', 'severken-suleyman-yavuz-3daba', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Seninle Ayrıldığımızda

Mevsim Yazdı

Aşıklar Ayrılışımızı Yazdı

Benim Sana Olan Aşkım

Ne Duvardaydı Nede Bir Kenarda

Benim Sevgim Sol Yanımdaydı Sol Yanımda

Sen Sevgimi Silah ettin Bana

Esir Ettin Beni Kendine

Bende Şikayetçi Değildim Hani

Ama Dayandı Bıçak Kemiğe

Aldattın Beni Seni Severken Böyle

Arkama Bile Bakmadım Terk Edip Giderken', 'Seninle Ayrıldığımızda Mevsim Yazdı Aşıklar Ayrılışımızı Yazdı Benim Sana Olan Aşkım Ne Duvardaydı Nede Bir Kenarda Benim Sevgim Sol Yanımda...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Yavuz']::text[], 8.5, '{"poet":"Süleyman Yavuz","poet_slug":"suleyman-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/severken-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgiliye mektuplar4', 'sevgiliye-mektuplar4-denizhan-solmaz-qhcqz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'şimdi yaşamın kıyısındayım 

o korkunç gerçekle başbaşayım

yaşam...

ölüm..

ve ikisi yanıbaşımda üstelik aynı anda

geberiyorum canım anlıyormusun GEBERİYORUM

ölemiyorum bile anlayaçağın 

çünkü hayvan olan yanıdır seven insanın

kalbalık içinde yapa yanlızım

sadece ben..

bir başıma kalışım

bir adım ötemde ölüm

hiç bukadar yakın olmamıştım..

vurulduğumda bile

cudide,dargeçitte,çehennemderesinde...

o korkunç karanlık geçelrde bile 

ne bukadar yanlız 

nede bukadar yakındım ölüm

şimdi bostancı köprüsü altında asvaltta

hemen yanı başımda

bir adım ötemde ölüm

anlıyormusun ölemiyorum bile 

kahretsin 

GEBERİYORUM....', 'şimdi yaşamın kıyısındayım  o korkunç gerçekle başbaşayım yaşam... ölüm.. ve ikisi yanıbaşımda üstelik aynı anda geberiyorum canım anlıyormu...', ARRAY['Türk Edebiyatı','Şiir','Denizhan Solmaz']::text[], 8.5, '{"poet":"Denizhan Solmaz","poet_slug":"denizhan-solmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sevgiliye-mektuplar4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kurt mu kuzu mu?', 'kurt-mu-kuzu-mu-kadir-soyturk-84rqv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İçerdeki kuzu mu; yoksa azgın kurt mudur? 

İyi hesap etmeli kapıyı açıyorken! 

Rahmetin kıymetini bilmeyen zavallılar; 

Doluya yakalanır; yağmurdan kaçıyorken!', 'İçerdeki kuzu mu; yoksa azgın kurt mudur?  İyi hesap etmeli kapıyı açıyorken!  Rahmetin kıymetini bilmeyen zavallılar;  Doluya yakalanır; ya...', ARRAY['Türk Edebiyatı','Şiir','Kadir Soytürk']::text[], 8.5, '{"poet":"Kadir Soytürk","poet_slug":"kadir-soyturk","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/kurt-mu-kuzu-mu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saklan Birtanem Saklan', 'saklan-birtanem-saklan-murat-demir-pssq3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Atlılar geliyor atlılar

Dörtnala doludizgin

Sırtlarında tüfekler

Ellerinde kırbaçlar

Saklan güzelim saklan

Saklan ki bu adamlar

Acımadan benimle

Seni de vuracaklar

Ben ölmeden sakın ha

Saklan, çıkma yerinden

Ben ölmeden unutma

Seni hiç kimse benim

Alamaz ellerimden

Ben ölmeden el değil

Yel vursun saçlarına

Ölürsem de göm beni

Göm sevda silahımla

Dağın yamaçlarına

Atlılar geliyor atlılar

Şehirden dağlara doğru

Gözlerine kan dolmuş

Ellerinde ferman var

Saklan birtanem saklan

Saklan ki bu adamlar

Acımadan benimle

Seni de vuracaklar

Ben ölmeden üzülüp

Gözlerinden yaş dökme

Ben ölmeden kimsenin

Karşısına çıkıpta 

Sakın boynunu bükme

Ben ölmeden el değil

Yel vursun saçlarına

Ölürsem de göm beni

Sen sevda silahımla

Dağın yamaçlarına.', 'Atlılar geliyor atlılar Dörtnala doludizgin Sırtlarında tüfekler Ellerinde kırbaçlar Saklan güzelim saklan Saklan ki bu adamlar Acımadan ben...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/saklan-birtanem-saklan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '...Sandık...', 'sandik-naime-erlacin-cjto7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'içine açılan kuyu ve 

paslı anahtar deliğinde döllenir 

yaşamak gibi

aşk gibi esrik bir heves 

kimi gün kükrer gökyüzü

kiminde metafizik bir yağmur

mülkiyetsiz surlarda

istinat duvarına 

asıldığı yerde kelâmın 

durma kışkırt kendini 

sandığını aç şiirin! 

sözün harında dinsin yürek ateşi

saçılsın meydana soy kütüğün 

derin bir gön yanığı sinsin mısraa

sıyrılsın kemik o saat etinden

kökünden çürüsün diller

sözle sevişerek kanıtlanır varoluş

hükmüm kadar ey yüreğim 

vaadim var sana yazmak üstüne

bırak doğum sancısıyla dönüşsün 

sızıntı devinime

yaz ki 

sürsün dalında şiirin 

bir sevda masalı gibi yeniden sürgünler

(17 Aralık 2004)', 'içine açılan kuyu ve  paslı anahtar deliğinde döllenir  yaşamak gibi aşk gibi esrik bir heves  kimi gün kükrer gökyüzü kiminde metafizik bir...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/sandik-35-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstiridye', 'i-stiridye-naime-erlacin-hl67u', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'neye yarar inci

insana bırakılan 

bir hayal olmaktan başka

nasıl da yalnızdır 

kırılgan deniz yosunu

ve istiridyeler

koyu bir inzivada

düş büyütürler

(17 Aralık 2004)', 'neye yarar inci insana bırakılan  bir hayal olmaktan başka nasıl da yalnızdır  kırılgan deniz yosunu ve istiridyeler koyu bir inzivada düş b...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/istiridye-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '...Gölge...', 'golge-naime-erlacin-7usk6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'denedik

gül kadar gülmeyi

sevmeyi aşk kadar

emirler vardı

''yaz'' diye buyuran

ezberlendi tüm koşuyolları

avcıydık böyle

sinsi

iz sürdük kendimize

ne terk edildi gölge

ne yakalandı

o ki 

bizden sonra

karşılayandı her varılan yerde

(17 Aralık 2004)', 'denedik gül kadar gülmeyi sevmeyi aşk kadar emirler vardı ''yaz'' diye buyuran ezberlendi tüm koşuyolları avcıydık böyle sinsi iz sürdük kendi...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/golge-38-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsanlık Hikayesi :)', 'i-nsanlik-hikayesi-erdal-gisi-xvntc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Adamın mağarası bile yoktu

Doyduğu, yorulduğu yerde yatıp kalkar

Ağaçlarla-böceklerle konuşur

Hayvanlarla anlaşır

Her akşam şükrederdi

Kış için hazırlığı kafasındaydı

Neyi nerde bulacağını öğrenmişti

Bir gün yolu dünyaya düştü

Ne güzelmiş… yıllardır neden burada değil

Saraylar, sofralar… yataklar, halılar…

Birde hizmetçiler! 

Hem ilginçti hem de gülünç

Zaten onlarda kendisine gülmüştü

Atlar, silahlar da ilginç…

Bir de askerler…

Pazar da, kiler de ilginç…

Sultanın sarayı var, olsun da

Köleleri de insan…

Hem saray hem zindan

Atlar silahlar olsun… da

Asker… kimin için, kime karşı…

Kilerler dolu… da

Herkese kapalı…

Aynı dünyada farklı farklı

Kimin hakkı, kim haklı…

Adam… iyice karıştı

Kalsa nerden başlayacak

Gitse nasıl dayanacak…

Bir de aşk tutar

Bitirir aklı…

Zorda olsa hizmetçisi olur bir zenginin

Bir lokma ekmeğe

Terini siler, yükünü taşır…

Derken öğrenir bu felsefeyi

Söyler kendi kendine

…bunların medeniyetine….

Tek düşü aşktır…

Şükrü de unutur

Zaten efendisi

İliğini kurutur…

Nihayet evlenirler

Bir süre sonra efendisi ölür…

Vasiyete göre her şey kendine kalır

Birde karısından çokça miras…

İlk dönem mirasın tadına varır…

Sonra düşmanlar çıkar karşısına

Kapısına bir sürü asker alır

Bir dizi de köle…

Bu kadar insan için bu kadar da hizmetçi…

2 si erkek dört de çocuk…

kervanları vardır malını satar

kışlık şeyler için depolar yapar

…

rakipleri ki… çok tecrübeli

hatta yanlarında danışmanları..

adamda öyle yapar…

danışmanlarla plan ha plan…

askerlerine öğüt ha öğüt

çocuklarına titre ha titre

eşine sabır ha sabır…

adam öyle usanır

öyle usanır

döşekler batar

kadın adamın kucağında

adam uçurumlarda yatar…

sorar ki ne bu…

bilgin der; 

 “-dünya hali

-bu senin dünyanl

-senin medeniyetin değil

-başka bir hayata gömüldün

-çocukların belki alışır…

-senin dünyanda kiler yoktu

-Pazar yoktu

-Öyleyse ne askere ne köleye

-Ne de hizmetçiye yer yoktu

-Herkes kendisinin efendisi

-Herkes kendisinin kölesi

-Herkes kendisinin askeri-avcısıydı

-Zaten de düşman yoktu..

-Nasiple kalkardınız

-Şükürle yatar

-Bir insan bir insanı köle yaparsa

-Mutlaka bir şeylerin kölesi olur

-Emek mutluluk için

-Mal mutluluk için

-Emek ve mal çalınca

-Huzurda kaçar

-zaten,

-Sahibi ölen mal ruhen ölüdür

-Belki de o yüzden

-Miras, sahibini ruhsuzlaştırır

-Miraslar olmasaydı…

-İnsanlar ölü bir medeniyete mahkum  olur muydu…''

kim bilir...

Mart 2004', 'Adamın mağarası bile yoktu Doyduğu, yorulduğu yerde yatıp kalkar Ağaçlarla-böceklerle konuşur Hayvanlarla anlaşır Her akşam şükrederdi Kış i...', ARRAY['Türk Edebiyatı','Şiir','Erdal Gişi']::text[], 8.5, '{"poet":"Erdal Gişi","poet_slug":"erdal-gisi","theme":"Türk Şiiri","is_hero":false,"total_lines":96,"source_url":"https://www.antoloji.com/insanlik-hikayesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Meramım Bir Gece', 'meramim-bir-gece-oguzkan-bolukbasi-hpkco', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Seni sevmeye teşebbüsten

Ağırlaştırılmış müebbede mahkum bir yürekten

Beklenen

Ne varsa yerine getireceğim

Desem

Hafifletici sebep midir 

Şartlı salıverilmem için

İşte böyle çocukçasına duyguların ortasındayım

Adın ne senin

Mecnun’un sorduğu soru bu

Leyla’yı gördüğünde

Nerede öldü Mecnun

Nerede süründü Leyla

Var mıdır hala

Böyle bir aşkın tefekkürü alemde

Veya zulasında özlemin

Bir gece

Yanında kalacağım dediğinde

Bin gecenin mutluluğunu yaşamaya ne dersin

Mecnun gibi bin gecenin yalnızlığına değmez mi bu

Bir gece

Binlerce hecenin

Binlerce hayalin

Ve binlerce çiçeğin balında meşk eder

Ve sonrasında neler neler

Ne şiirler…………………', 'Seni sevmeye teşebbüsten Ağırlaştırılmış müebbede mahkum bir yürekten Beklenen Ne varsa yerine getireceğim Desem Hafifletici sebep midir  Şa...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/meramim-bir-gece-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çorumun Geceleri', 'corumun-geceleri-sukru-dikbiyik-kgkea', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Çorumun geceleri bir başka oluyor,

Ne sabahı nede günü doğmak bilmiyor

Arı gibi sokan sinekleri at gibi kelpleri

Geceler seyrine hayran kalıyor

İlerden bir ışık birde ay parlar,

Gözüm gözüne bakar,kalbim dağları aşar

Birde yar gelir ferman dinlemez taşar

Geceler seyrine hayran kalırlar,

Vadinin nesi,ırmağın sesi

Kurbağalar yılanlar hepsi

Işıkla parlıyor gölgesi

Ah şu çorumun geceleri

Kapanına sıkışmış fare gibi,

Kafese konulmuş bülbül gibi

Hep onu düşler habibi gibi

Ah şu çorumun geceleri.', 'Çorumun geceleri bir başka oluyor, Ne sabahı nede günü doğmak bilmiyor Arı gibi sokan sinekleri at gibi kelpleri Geceler seyrine hayran kalı...', ARRAY['Türk Edebiyatı','Şiir','Şükrü Dikbıyık']::text[], 8.5, '{"poet":"Şükrü Dikbıyık","poet_slug":"sukru-dikbiyik","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/corumun-geceleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiir De Ne?', 'siir-de-ne-sirma-mersin-5doxh', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Söz anlam ile buluştuğunda

İmgenin gücü haykıracak sesini…

Bir şiirin içine sıkıştırılmış

Yalnızca duygular değil! 

Düşüncelerin sessizliği ile

Kuvvetlenmiş satırlar da

Dizeleri bir başka renge boyacak

Sayfaları…

Yazılanları okurken yazılanları hisset

Diye altını çizerek söylüyorum sana! 

Okumak değil,

Yazmak değil …

Paylaşmak paylaşırken de 

Dokunmak önemli yüreklere…

02.12.04', 'Söz anlam ile buluştuğunda İmgenin gücü haykıracak sesini… Bir şiirin içine sıkıştırılmış Yalnızca duygular değil!  Düşüncelerin sessizliği ...', ARRAY['Türk Edebiyatı','Şiir','Sırma Mersin']::text[], 8.5, '{"poet":"Sırma Mersin","poet_slug":"sirma-mersin","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/siir-de-ne-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ramazan Arefesiydi… Harem’de', 'ramazan-arefesiydi-harem-de-erdal-gisi-0qit3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Günlerdir gergindi… kucaklaşamadık

Hakkını helal et derken otobüs gidiyordu

Aramızda bir cam birde elleri

Allah’a ısmarladım… boynu bükükdü… gidiyordu

Durunca arayacak, inince arayacak

Kolunda, parmağında hatıralarım,

Tez gelecek, bayram biter bitmez…

Tesellim, avucumdaki sıcaklığıyla gidiyordu…

Ramazan arefesiydi… Harem’de

Dışımda damlalar içimde fırtına gidiyordu

O gitti de sanki kaldım mı… 

Düşe kalka bittim… o düz gidiyordu

...

22,11,03', 'Günlerdir gergindi… kucaklaşamadık Hakkını helal et derken otobüs gidiyordu Aramızda bir cam birde elleri Allah’a ısmarladım… boynu bükükdü…...', ARRAY['Türk Edebiyatı','Şiir','Erdal Gişi']::text[], 8.5, '{"poet":"Erdal Gişi","poet_slug":"erdal-gisi","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ramazan-arefesiydi-harem-de-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her An Kanar İnsanlığım', 'her-an-kanar-i-nsanligim-vedat-koparan-dksqq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '-Yaşam yıldızınız ışıldasın, demircinin örsünde-

Bu sıralar hava raporları 

Sibirya soğuğu geliyor demekte 

Bu gün serinliğin içinden 

Alaycı  güneş nasılda aldatıyor

Temiz havaya ihtiyaç duyarak

Kapıyı her açışımda 

İçeri dolan soğuk hava 

Geceden kalan yanık kokusunda

Güz üşümesinde mum alevi

Git gel de titreyen sarı ışık

Ürperiyorum,üşüyor bedenim

Kendimi kendime dar ederken 

Kendimde seni bana getiren 

Bir sıcaklık doluyor zihin pergelime

Açıların uçları bir türlü birleşmiyor

Balığın etine saplanan zıpkın gibi 

Bir sıcaklık yakalamak adına 

Dalıyorum açlığımla istenç doruklarında 

Güneşin aldatıcıda olsa ışıltılarına

Karşımda dalları çıplak küçük bir ağaç

Üzerinde hala düşmemiş bir kaç yaprak

Kent bir öğle telaşında 

Acıktı öğrenciler, işçiler, memurlar 

Bende açım hem de nasıl.

Ortalıkta ne bir kuş, ne kedi, nede bir köpek 

Soğuk onları da vurmuş, biliyorum onlarda aç

Mesai saatinin gelmesini bekliyorum

Üstelik esnaf siftah bile etmemişken

Resmi  işim gereği  cebime uzanan ele 

Maliye’ye gideceğimde.

Gözüme ilişiyor öğrencilerin gülüşleri 

Çoğunlukla grup halinde gelip geçiyorlar

Nede güzel gülüyorlar 

Yüzlerinde bahar gönenci 

Çiçekler donanmış  gün aydınlığı

Arıyorum kendimde o gülüşleri

O gülüşlerde bir de seni

Hani mavi bir güldü ya gülüşün

Vuruyor yaşam duvarına 

Söylenen ezgide kuşların çığlığı 

Bir gündü hesapsız,gece içi bakışı

Güneş yoksunu kaybolan gölgeler 

Benliğimde geleceğin gün aydınlığı

Dalıyorum yine günün telaşında düşüncelere

Neden bu kadar kanar,kanatılır  insanlığım

Bir yanda şiirler bir yanda geçmişin izi

Ve gün be gün yaşananlar, içim acıyor

Düşürüyor yine gün buruk bir hüzün

Acının sağrısında aklımda yarım kalan 

Orduları tarumar olmuş direnci yitik 

Savunmasız korunaksız bağ bozumu sevda

Bir yıl daha yaprak döküyor  ramak kala

Yoksunlara vuran  insan hallerinde

Ben yine kanıyorum insanlık denizinde.. 

-Yoksun ya be gözüm yoksun ya dağlar elbet iner düze

Öfkeyle bilenen isyan ateşi yanar hep yüreğimde-

15.12.2004', '-Yaşam yıldızınız ışıldasın, demircinin örsünde- Bu sıralar hava raporları  Sibirya soğuğu geliyor demekte  Bu gün serinliğin içinden  Alayc...', ARRAY['Türk Edebiyatı','Şiir','Vedat Koparan']::text[], 8.5, '{"poet":"Vedat Koparan","poet_slug":"vedat-koparan","theme":"Türk Şiiri","is_hero":false,"total_lines":58,"source_url":"https://www.antoloji.com/her-an-kanar-insanligim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O günü hatırlar mısın söyle?', 'o-gunu-hatirlar-misin-soyle-huseyin-erdogan-wdrjx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'sürüler halinde,

diğer kuşlar gibi

martılar da 

göç edip gitmişler

çok uzaklara

onlar da 

dayanamamışlar hasretine 

geceler boyunca 

göz yaşı dökmüşler

benim halime 

bu nedenle

bir sabah erkenden 

çekip gitmişler

bana haber vermeden

tutamadım kendimi

 çatıda göremeyince hiçbirini

bakınca penceremden

ben erkeklik merkeklik dinlemem

birdenbire ağlayıverdim işte öyle

bundan önce de 

bir kez daha ağlamıştım

beni terk edişine

o günü hatırlar mısın söyle? 

                        17.12.2004', 'sürüler halinde, diğer kuşlar gibi martılar da  göç edip gitmişler çok uzaklara onlar da  dayanamamışlar hasretine  geceler boyunca  göz yaş...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Erdoğan']::text[], 8.5, '{"poet":"Hüseyin Erdoğan","poet_slug":"huseyin-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/o-gunu-hatirlar-misin-soyle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeter ki ''Sevgiye''', 'yeter-ki-sevgiye-abdullah-atay-e8h32', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'çiçek ben dal sen

bülbül ben gül sen

hüzün olmasın

yeter ki gül sen...

yolcu ben yol sen

yağmur ben sel sen

kapılarım açık

yeter ki gelsen...

damar ben kan sen

beden ben can sen

beni her daim

yeter ki an sen...

bulut ben yel sen

vaha ben çöl sen

gönül bağımda

yeter ki kal sen...

duman ben köz sen

hazan ben yaz sen

aşkın yolunda

yeter ki gez sen...

alev ben kor sen

kolay ben zor sen

gönül gözünle

yeter ki gör sen...

gece ben gün sen 

canan ben can sen

bekler bu gönül

yeter ki dön sen...

ırmak ben göl sen

gönül ben dil sen

seni sevdiğimi

yeter ki bil sen...

Marmaris-aralık.2004', 'çiçek ben dal sen bülbül ben gül sen hüzün olmasın yeter ki gül sen... yolcu ben yol sen yağmur ben sel sen kapılarım açık yeter ki gelsen.....', ARRAY['Türk Edebiyatı','Şiir','Abdullah Atay']::text[], 8.5, '{"poet":"Abdullah Atay","poet_slug":"abdullah-atay","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/yeter-ki-sevgiye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mazi ve Hüzün', 'mazi-ve-huzun-erdal-gisi-3st0c', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Maziden beslenen aşk

İçinde akrebi gizleyen güldür..

Meyhaneye benzer

İlk kadeh senin

Sonra dizgin mazinindir

Gerisi hüzün..

...

Aşkların hazan ayı

Sevgilerin kırk haramisi

Evliliklerin akrep kıskacıdır mazi

Gerçeklerin de kezzabı 

Çukurova’da en iyi pamuk yetişir

Ege’de üzüm,

Kara denizde çay

Mazide hüzün…

2003', 'Maziden beslenen aşk İçinde akrebi gizleyen güldür.. Meyhaneye benzer İlk kadeh senin Sonra dizgin mazinindir Gerisi hüzün.. ... Aşkların ha...', ARRAY['Türk Edebiyatı','Şiir','Erdal Gişi']::text[], 8.5, '{"poet":"Erdal Gişi","poet_slug":"erdal-gisi","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/mazi-ve-huzun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Toplantı', 'toplanti-aynur-baydar-7vf9e', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yarım saat hazırladığım sunuyu anlattım

Bir sürü grafik çıkarıp

Sorunları ve çözümleri vurguladım

Esneyenlere, belek belek bakanlara

Dikkatlerini toplasınlar diye müzik bile ayarladım

İşim bitince gelecek mantıklı sorulara hazırlandım

Gelmeye başladı sorular

Yav bu sunu çok profosyonel siz mi hazırladınız

Teşekkür edip, ben hazırladım dedim

Peki müziği sunuya nasıl eklediniz

Onu da anlattım

Renkleri nasıl şey ettiniz

Onu da size daha detaylı sonra göstersem

Aylık olarak şunları yaparsak daha iyi olur kanaatindeyim

Düşüşlerimizi engellemek için…

Uyuyanlardan biri bağırdı, 

Hakkat ya bu iyi olmuş renkli menkli

Başkada soru gelmedi

Sabrım tükendi

Dilimi çıkardım

İşaret parmağımla burnumu kaldırdım

Sol elimle gözlerimi aşağıya kaydırdım

Şebek şebek diye bağırdım

Masada oturanların arkalarına dolanıp

Tek tek enselerine patlattım

Gerçi bunları hayalimden yaptım

Ama epey rahatladım

İçimden geberin diye bağırırken

Beni dinlediğiniz için teşekkür ederimi

Sırıtmaya çalışarak sıraladım

Bilgisayarımı topladım

Kös kös toplantıdan çıktım', 'Yarım saat hazırladığım sunuyu anlattım Bir sürü grafik çıkarıp Sorunları ve çözümleri vurguladım Esneyenlere, belek belek bakanlara Dikkatl...', ARRAY['Türk Edebiyatı','Şiir','Aynur Baydar']::text[], 8.5, '{"poet":"Aynur Baydar","poet_slug":"aynur-baydar","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/toplanti-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beyaz', 'beyaz-hil-l-kucuk-ozdamar-auy8c', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'kirlendi sayfalarım

bir hüzün eşliğinde

gölge düşmüşken saçlarıma

güneş ısıtmaz olmuşken

gökyüzünün senfonisi

usul usul gelir durur kapıda.

ölü toprağı serpilmiş 

aşklar üstüne

yazılan ve kimi zaman

yazılamayan yazılar üstüne

kocaman sözler söyler kimileri.

boyundan büyük laf etmek 

böyle bir şey besbelli.', 'kirlendi sayfalarım bir hüzün eşliğinde gölge düşmüşken saçlarıma güneş ısıtmaz olmuşken gökyüzünün senfonisi usul usul gelir durur kapıda. ...', ARRAY['Türk Edebiyatı','Şiir','Hilâl Küçük Özdamar']::text[], 8.5, '{"poet":"Hilâl Küçük Özdamar","poet_slug":"hil-l-kucuk-ozdamar","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/beyaz-30-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Teşekkür', 'tesekkur-aynur-baydar-m3yhg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Harfler, cümleler, dizeler

Zavallılar 

Yıllardır kahrımı çekerler

Duyarım okurum kızarım

Onlarla kuşanır 

Kötülükle savaşırım

Bazen kendimle 

Bazen yüzsüzlerle

Dalga geçer rahatlarım

Özlemimi, sevgimi, duygularımı 

Yazılarıma 

Şiirlerime döker 

Sığınırım

Bazen küçük bir kız 

Bazen ukala

Bazen de 

Kötülere nara atanım

Yazıp... 

Yaradana yalvaranım

Kar tanesi, tespih, damlacık 

Kılığındayım

Onlarsız ne yaparım

Güzel Türkçeye İmlaya 

İstemeden çokca 

Haksızlık yaparım

Türkçe öğretmenlerini 

Ustaları görünce 

Kaçar, saklanırım

Yüzsüzce de... 

Yazmaya çalışanım

Galiba... 

Afacan ve yaramazım

Okuyanlarımın, dinleyenlerimin

Sabırlarına hayranım

Not:İlk katıldığımdan beri desteğinize teşekkür ederim. Saygılarımla', 'Harfler, cümleler, dizeler Zavallılar  Yıllardır kahrımı çekerler Duyarım okurum kızarım Onlarla kuşanır  Kötülükle savaşırım Bazen kendimle...', ARRAY['Türk Edebiyatı','Şiir','Aynur Baydar']::text[], 8.5, '{"poet":"Aynur Baydar","poet_slug":"aynur-baydar","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/tesekkur-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Kimliğin Suskunluğu..', 'bir-kimligin-suskunlugu-aygul-ece-3cquu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Cinnet geçirmiş, 

Bir kimliğin suskunluğunda 

Boğulurken arzular

Kimsesiz yalnızlıkta

Başlıyordu,

…………Mutlu olmak

Aynı Kadehte buluşup, 

Kahkaha savuruyorduk

Gökyüzüne,

Sonra 

Yankısını arıyorduk

Gülüşlerimizin

Bizi sarhoş eden asıl şey

Özlemlerimizdi

Ve en güzel yanı da

Acemi bir telaşla sevişmemizdi…..

Yoksun şimdi…

Yalnızlık kimsesizdi artık…

Sarhoşluk kadehlere 

Sevişmelerde bedenlere

Dönmüştü.

Peki gülüşlerimiz 

Onların yankısı kime

Kalacaktı.', 'Cinnet geçirmiş,  Bir kimliğin suskunluğunda  Boğulurken arzular Kimsesiz yalnızlıkta Başlıyordu, …………Mutlu olmak Aynı Kadehte buluşup,  Kah...', ARRAY['Türk Edebiyatı','Şiir','Aygül Ece']::text[], 8.5, '{"poet":"Aygül Ece","poet_slug":"aygul-ece","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bir-kimligin-suskunlugu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidiyor Kuşlar', 'gidiyor-kuslar-hil-l-kucuk-ozdamar-mpoc9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'duyun beni! 

ben bir çığlığım,

başlı başına bir çığlık.

susuyorsunuz ya, onun için haykırıyorum

semaya sarılıyorum küçücük ellerimle.

yıldızlara tutunuyorum...

yağmurlarım kızıl kıyamet

önce annem bir kuş olup uçtu,

sonra,

Felluceli bir kuş uçtu gökyüzüne

sonra  Kudüslü bir kuş...

kuşlar gidiyor...

peki ya,

ne zamandır bu dünyanın ilkbaharı? 

ne zaman konar ağaçlara umut? 

hazan ile  hüzün müdür nasibim? 

duyun beni! 

ben bir çığlığım,

Felluceli, Kudüslü bir çığlık...

siz susuyorsunuz ya, 

onun için haykırıyorum...', 'duyun beni!  ben bir çığlığım, başlı başına bir çığlık. susuyorsunuz ya, onun için haykırıyorum semaya sarılıyorum küçücük ellerimle. yıldız...', ARRAY['Türk Edebiyatı','Şiir','Hilâl Küçük Özdamar']::text[], 8.5, '{"poet":"Hilâl Küçük Özdamar","poet_slug":"hil-l-kucuk-ozdamar","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/gidiyor-kuslar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Niye', 'niye-murat-sayim-efi6x', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ne karanlıklar nurunda yaşlandı

Gözlerim

Ne de lal çaçaronluk yaptı dilim.

Ilık bir şarkıdayken ruhum,

Avareliği yok oldu

İçimdeki öfkenin.

Zindan odacık içimde

Soruyor nedenini

Kendi kendine

Tahtına kurulmuş bende 

En üst tepeye

O benden habersiz ben ondan.', 'Ne karanlıklar nurunda yaşlandı Gözlerim Ne de lal çaçaronluk yaptı dilim. Ilık bir şarkıdayken ruhum, Avareliği yok oldu İçimdeki öfkenin. ...', ARRAY['Türk Edebiyatı','Şiir','Murat Sayım']::text[], 8.5, '{"poet":"Murat Sayım","poet_slug":"murat-sayim","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/niye-33-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gam Çekme Bari', 'gam-cekme-bari-huseyin-sigirtmac-8whrg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ne durursun bu efkarla.

Ayrıl da gam çekme bari.

Madem sıkıntın hep yarla.

Darıl da gam çekme bari.

Yola gider hep diz yorgun.

Görür görmez hep göz yorgun.

Aciz dilde hep söz yorgun.

Sevil de gam çekme bari.

Sevilmek en büyük servet.

Düşüneni alır her dert.

Aşka düşen yanar elbet.

Ayıl da gam çekme bari.

Aklı erenler hep zorda.

Buz içinde yanar korda.

Sığırtmaç rahat yok burda.

Sürül de gam çekme bari.', 'Ne durursun bu efkarla. Ayrıl da gam çekme bari. Madem sıkıntın hep yarla. Darıl da gam çekme bari. Yola gider hep diz yorgun. Görür görmez ...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Sığırtmaç']::text[], 8.5, '{"poet":"Hüseyin Sığırtmaç","poet_slug":"huseyin-sigirtmac","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gam-cekme-bari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gittin Sevgili', 'gittin-sevgili-ali-gencay-gw4rc', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gittin 

lila giydi gece

Siyahtı gözleri 

Buzdan da soğuk elleri

Dönüp sokağın köşesinden

Gittin,sevgili

Uzun olacaktı dönüşün

Say diye verdiğin

Cebime doldurduğum inciler

Döküldüler birer,birer

Bitti beklemeler

Gittin,sevgili

Öyle güçlüydün ki

Ve öyle mağrur

Kırıkları battı kalbinin 

Kanadı seni tutan eller

Şehir geldi üzerime

Usulca yaklaştı yanıma 

Ağır kokulu fahişeler

Gecenin içinde ben

Şehrin içinde ben

Benim içinde sen

Uzun bilmece

Gittin,sevgili', 'Gittin  lila giydi gece Siyahtı gözleri  Buzdan da soğuk elleri Dönüp sokağın köşesinden Gittin,sevgili Uzun olacaktı dönüşün Say diye verdi...', ARRAY['Türk Edebiyatı','Şiir','Ali Gençay']::text[], 8.5, '{"poet":"Ali Gençay","poet_slug":"ali-gencay","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/gittin-sevgili-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir de Seni Görelim', 'bir-de-seni-gorelim-kadir-soyturk-rk2h1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Beğenmeyen dostuma...

Ortaya dök biraz da, sen yoğunu – varını; 

Biz de bir kez görelim, senin yazdıklarını!', 'Beğenmeyen dostuma... Ortaya dök biraz da, sen yoğunu – varını;  Biz de bir kez görelim, senin yazdıklarını!...', ARRAY['Türk Edebiyatı','Şiir','Kadir Soytürk']::text[], 8.5, '{"poet":"Kadir Soytürk","poet_slug":"kadir-soyturk","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/bir-de-seni-gorelim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sınama', 'sinama-i-brahim-tig-ibn12', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'gölgelerimizle yaşamıştık

karışırken gün batımlarına

atamıyorum kendimi

bir aman

yıldızlar üşüşüyor saçlarıma

baldıranlar deliriyor

sarhoş zaman

-her şey sıradan-

tenin hariç', 'gölgelerimizle yaşamıştık karışırken gün batımlarına atamıyorum kendimi bir aman yıldızlar üşüşüyor saçlarıma baldıranlar deliriyor sarhoş z...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Tığ']::text[], 8.5, '{"poet":"İbrahim Tığ","poet_slug":"i-brahim-tig","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sinama-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Görmüyorsun', 'gormuyorsun-melek-ozgoz-1ekye', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gözlerimdeki ışıltının çoktandır kaybolduğunu

Zorunlu kahkalarımla oynadığım oyunu

Böyle yaparak hazırladığını sonumu

Görmüyorsun

Çok şey mi istemiştim senden

Bir gün bile farkın oldu mu elden

Anlamadın söylenenleri  bu dilden

Cayır cayır yanıyorum

Görmüyorsun

Gidiyorum diyorum ben hey! 

Duymuyor musun?', 'Gözlerimdeki ışıltının çoktandır kaybolduğunu Zorunlu kahkalarımla oynadığım oyunu Böyle yaparak hazırladığını sonumu Görmüyorsun Çok şey mi...', ARRAY['Türk Edebiyatı','Şiir','Melek Özgöz']::text[], 8.5, '{"poet":"Melek Özgöz","poet_slug":"melek-ozgoz","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/gormuyorsun-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşayan Yarın', 'yasayan-yarin-ahmet-agdere-jsdrb', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yitirmemek için yarını,

Aldık arkamıza rüzgarı,

Şafak vakti çıktık yola.

Ayışığı ışıttı yolumuzu,

Yandı dizeler varlığında,

Aşklarımız yandı ard arda,

Nicesi tanışmasalar da..

Yokuş yukarı yolumuz var,

Aşkımız gibi kârımız var.

Razıysan sen de katıl arkadaş,

Ilgaz''dan büyük gönlümüz var,

Nice Yarın için yerimiz var! ..', 'Yitirmemek için yarını, Aldık arkamıza rüzgarı, Şafak vakti çıktık yola. Ayışığı ışıttı yolumuzu, Yandı dizeler varlığında, Aşklarımız yandı...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ağdere']::text[], 8.5, '{"poet":"Ahmet Ağdere","poet_slug":"ahmet-agdere","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yasayan-yarin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Bilinmezle..', 'bir-bilinmezle-melek-ozgoz-b785y', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir bilinmezle çıktım yola

Sana gelen yollarıma dikenli gül dikmişler

Topuklarım kanarken ulaşılmazlığınla

Seni benden vazgeçirmişler

Ben sana gelmek istedim

Koşarak yalınayak tüm saflığımla

Kollarında yaşlanmak

Sana seninle dokunamadım

Seni hayallerimden söküp atmalıydım

Çok farklıydı senin dünyanın iklimi

Ayazına dayanamadım

Biraz sıcaklık vermedinki bana

Sana herşeyimle bağlanayım

Ne demek istersin bana söyle

Hiç hissettinmi beni içinde

Bakışlarımdaki solan yaprakları

Biriktirdin mi  ki yüreğinde

Hiç farklı olamaz aramızdaki yalan

Bendim saçmasapan hayallere dalan

İfade etmiyor bana artık taşarak bakman

Bilinmezleri dost edindim 

Bir bilinmez aşk olup bittin..', 'Bir bilinmezle çıktım yola Sana gelen yollarıma dikenli gül dikmişler Topuklarım kanarken ulaşılmazlığınla Seni benden vazgeçirmişler Ben sa...', ARRAY['Türk Edebiyatı','Şiir','Melek Özgöz']::text[], 8.5, '{"poet":"Melek Özgöz","poet_slug":"melek-ozgoz","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/bir-bilinmezle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vazgeçmişim', 'vazgecmisim-melek-ozgoz-uj1ei', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Vazgeçmişim gelmişinden geçmişinden

Vaad’ ediyor gibi yaptığı geleceğinden

Yaprak yırtığına döndürmüşler yüreğimi

Mevsimimi hep sonbahar seçmişler 

Ben sevgi anlayış beklerken 

Taşlar Kayalar koyulmuş yollarıma

Onlar beni kahraman şeçmişler 

Başrole koymuşlar bu oyunda

Herşey hata herşey suç olmuş

Bir sevince bin ah işitmiş kulaklarım

Yaşamak hiç değerin hiç

Bir yastığa yaraşmış gözyaşlarım

Utanır oldum gözlerimin gördüklerine

Ne hatrım kalmış mazide

Ne bir iz

Yaşandığı belli olsun diye

Hepsini toplamış ben almışım 

Ne kadar ders varsa beynimde toplamışım

Mutluluk eksi acı, kederi götürmüyormuş

Sevilmek için sevmek yetmiyormuş...', 'Vazgeçmişim gelmişinden geçmişinden Vaad’ ediyor gibi yaptığı geleceğinden Yaprak yırtığına döndürmüşler yüreğimi Mevsimimi hep sonbahar seç...', ARRAY['Türk Edebiyatı','Şiir','Melek Özgöz']::text[], 8.5, '{"poet":"Melek Özgöz","poet_slug":"melek-ozgoz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/vazgecmisim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönlü-me İşlemiş Gözlerinin Haresi', 'gonlu-me-i-slemis-gozlerinin-haresi-melek-ozgoz-qj4zd', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sabahına uyandığım yalan yanlış bir aşkın

Küflenmiş ekmeğiyle kahvaltı yapıyorum

Kapkara akmış gözlerimden yaşlar

Demledim birde onu çay diye içiyorum

Sahte gibi biraz izlediğim türk filmindeki sevda

Başka biri girmiş yine bu aşka da

Tıpkı senle ben gibi

Gazetenin gri sayfalarını çevirirken usulca

Aklıma düşüyor aşkının hapishanelerine düşüşüm

Orada masum aşkımla çürüyüp ölüşüm

Gözlerimden bir hain damla çığlık atıyor

En başına dönmek için

En başına

Hani seninle tanışmış gibi yapıp

Aşık olduğumuzdaki

O tertemiz hayata

Unutmamışken ben hala seni

Başkası sarıp seviyor artık sende başka biri

Silinirmi hiç ne yaparsan yap

Gönlüme işlenmiş gözlerinin haresi

Ağlamadan yaşanır mı ardından

Gökyüzü gibi gözlerimdeki mavilik

Bulutu çok,  buğulu çok şimdi...', 'Sabahına uyandığım yalan yanlış bir aşkın Küflenmiş ekmeğiyle kahvaltı yapıyorum Kapkara akmış gözlerimden yaşlar Demledim birde onu çay diy...', ARRAY['Türk Edebiyatı','Şiir','Melek Özgöz']::text[], 8.5, '{"poet":"Melek Özgöz","poet_slug":"melek-ozgoz","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/gonlu-me-islemis-gozlerinin-haresi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Macuncu Dede', 'macuncu-dede-husamettin-gunacti-60hli', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'macun şekerini bilir misiniz? 

renksiz çocukluğumun rengiydi onlar.

macuncu dedenin hünerli ellerinde

renk cümbüşü içinde dansedip,

tahta çubuklar üzerinde görkemle yükselerek

midemize inecekleri ânı sabırsızlıkla bekler,

sarı,mavi,pembe,yeşil,kırmızı renkleriyle

birbirlerine nazire yaparlardı.

en önemli işimiz saat üç''te gelen

macuncu dedenin yolunu gözlemekti.

son derece dakik olan macuncu dede,

bembeyaz kasketi ve önlüğüyle uzaktan göründüğünde,

bir lirayı hazır etmiş vaziyette yokuş aşağı hızla koşardık.

yufka yürekli macuncu dedemiz,

elli kuruş denkleştirebilmiş çocukları da kırmaz,

onları da sevindirirdi.

şimdilerde ne macun şekeri kaldı,

ne de iyilik ve hoşgörü timsali

macuncu dedeler.

ne yazık ki 

elde kalanlar,

bu temiz hatıralar...

17-12-2004', 'macun şekerini bilir misiniz?  renksiz çocukluğumun rengiydi onlar. macuncu dedenin hünerli ellerinde renk cümbüşü içinde dansedip, tahta çu...', ARRAY['Türk Edebiyatı','Şiir','Hüsamettin Günaçtı']::text[], 8.5, '{"poet":"Hüsamettin Günaçtı","poet_slug":"husamettin-gunacti","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/macuncu-dede-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hanisin? ..', 'hanisin-bulend-b-ki-j24iq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bu kaçtır elimden düşüyor tesbih..

Bu kaçtır dilime dolanık ismin..

Hanisin...

Zaman mı sancı, yoksa,

gene bendemi sancılık...

Ölüm ayrılığa yakışır mı a gülüm? 

Ölüme yakışmazsa ayrılık! ..

Cuma`daydım...

Dertli başa derman aradım.

Ferman aradım kalleşliklerin infazına.

Ve düşerken enkazına gecenin...

Hanisin...

Bozmalı mı kafayı bilmem ki! .

Gezmeli mi berduşça...

Yoksa çıkarıpta belimdekini

Vurmalı mı kansızlıkları zaaflarından...

Kandırılmışlığın,

Kaldırıp-atılmışlığın adıdır adım.

Krizantem kokusundayken tadım

Bozulup gittim ellerine yaslanıp...

Belki de bu ``son`` du

Puşt gecelere seslenip kaldım..

Hanisin...

Gene de uslanamadım...', 'Bu kaçtır elimden düşüyor tesbih.. Bu kaçtır dilime dolanık ismin.. Hanisin... Zaman mı sancı, yoksa, gene bendemi sancılık... Ölüm ayrılığa...', ARRAY['Türk Edebiyatı','Şiir','Bülend Bâki']::text[], 8.5, '{"poet":"Bülend Bâki","poet_slug":"bulend-b-ki","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/hanisin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
