INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pervane böcekleri', 'pervane-bocekleri-dogan-sahin-pq1x1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Havada Kaos kokuyordu

Hangi yöne süzüleceklerini biliyorlardı

Sonra 

Daha yere erişmeden eridiler, buhar oldular

Uçtular

Dil üzerine düşen kar kristaliydiler

Eridiler

Aydınlıkta uçabilmek için

Sanki bilgisayar oyunlarının matematiğini

Sevmiyordu

Odamdaki kara delikler

Ve lakin ışığa aşık

-Toprak onlarındı-

Kucakladılar birbirlerini

Işığa aşık

Pervane böcekleri', 'Havada Kaos kokuyordu Hangi yöne süzüleceklerini biliyorlardı Sonra  Daha yere erişmeden eridiler, buhar oldular Uçtular Dil üzerine düşen k...', ARRAY['Türk Edebiyatı','Şiir','Doğan Şahin']::text[], 8.5, '{"poet":"Doğan Şahin","poet_slug":"dogan-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/pervane-bocekleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korku', 'korku-dogan-sahin-0jfb7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yaşam acımasız; 

Ona direnemediğinde, 

daha da acımasız.

Ne zaman ki ölümü anlar insan

işte o zaman 

korkmayacaktır yaşamdan.', 'Yaşam acımasız;  Ona direnemediğinde,  daha da acımasız. Ne zaman ki ölümü anlar insan işte o zaman  korkmayacaktır yaşamdan....', ARRAY['Türk Edebiyatı','Şiir','Doğan Şahin']::text[], 8.5, '{"poet":"Doğan Şahin","poet_slug":"dogan-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/korku-69-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sat', 'sat-dogan-sahin-2r3xe', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sat

Sat da,

Al yeni bir şey

Sıkıştığında

Kolayca satabileceğin bi şey olsun..

Sat sat', 'Sat Sat da, Al yeni bir şey Sıkıştığında Kolayca satabileceğin bi şey olsun.. Sat sat...', ARRAY['Türk Edebiyatı','Şiir','Doğan Şahin']::text[], 8.5, '{"poet":"Doğan Şahin","poet_slug":"dogan-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/sat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olası', 'olasi-gokhan-oflazoglu-lmx3h', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Haz uçurumlarında

enerji birikir; 

sıçrar benliğimiz,

bir yanda tükenir.

İşte bu gel-git akıntısında,

dört bir yan hem engel,

hem olası geleceğimiz.

Yeni varoluşun yuvası

sarsılan ve silkinen

derinliklerimiz.

18/12/2004', 'Haz uçurumlarında enerji birikir;  sıçrar benliğimiz, bir yanda tükenir. İşte bu gel-git akıntısında, dört bir yan hem engel, hem olası gele...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Oflazoğlu']::text[], 8.5, '{"poet":"Gökhan Oflazoğlu","poet_slug":"gokhan-oflazoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/olasi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bizden Geriye Kalanlar,', 'bizden-geriye-kalanlar-caglar-akarsu-38ku4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '....

Anılara sarılırdık bazı demlerde,

Zaman sorumsuzça,  akar  gider,

Geçmiş saatin, yelkovanları arkasında,

 Gelecek akrep gibi zehirini akıtırken,

Düşer dururduk yollara,

....

Düşlediğim  her güzel anılar,

Bizimle beraber yaşarken,

Çilekeş günlerin içinde,

Kaybolarak, giderdik.

..

Dağ gibi yüreği vardı,Mehmedin,

Yıllardır çektiği sıkıntılar,

Yakasını hiç bırakmamıştı,

Bu gece,

Elimde ki bir damla suyu,

Kor olmuş, yüreğine döktüm.

Çelikten bir irade, yüklenmişti,

Sevecen hali, gözlerine yansımıştı.

...

Ne olursan,olsan bile,

Binbir hata, yapsan bile,

Dönüpde,  geldiğin zamanlar,

Kapısını hep,sonuna kadar,

Açık bulduğum bir dost,gibiydi.

...

Yıllar,

Yılllar..diye

Derinden bir iç çekerken,

Çok küçük yaşta kaybetmişti,

Anne sevgisi ve özlemini.

Gurbet yollarında, uzar giderdi,

İzi belirsiz kalmış,anılar.

...

Anadan ayrı kalmaya,dayamazdık.

Her gece ayrı,isyan ederken.

Ne de çok ortak yönlerimiz, varmış.

Bazı demler, onun arkasından,

Bir ''anne '' koruması gibi,

Ellerimi uzatmak gelirdi,

Babasız kalmış,''yetim'' bir kızın,

Masumluğuna sarılırdı,geceler.

....

O yıllarda,nice ıstıraplı günler,

Dolup da taşıp, gelmişti.

İki büklüm olmuş, çilekeş bedenin,

İsyankar havalarında,

Derin türküleri savururduk.

Soğuk ülkelerin, buzla kaplı,

Sokaklarında,  sürüklenerek,

Ayak seslerimizi, duyardım.

Göndermek,gelirdi içimden,

Akdenizin sıçak akşamlarını.

...

Bu gece,rüzgarlar ne kadar acımasız,

Delice, dört yandan esti ve durdu.

Gençlik yıllarında perdeler,

Sisler altında kalmış, örtüler,

Bir ayrı aralanıp durdu.

...

Onu görmüştüm bir gün,

Kalın parke paltosuna sarılmış,

Güçlü bedeni ile emin, yürüyordu.

Yüzüne bir ifade yerleşmişti,

Kararlı ve cesaretli olduğunu,

Her köşesinden anlatıyordu.

Siyah  kalın,gür kaşlarına

Gizlenmişti temiz duyguların,

Akarak getirdiği,safiyet.

...

Ne kadar da uzak gibi kalsa,

Anarşist ruhunda,'' baş kaldırma'' gördüm.

Paraya tapanlara,

Sisteme ve düzene,

Kocaman bir '' set'' çekmişti.

İnsanlığı arıyorduk, yerde sürünen.

Bulduğumuz anlarda, kucaklıyorduk.

Onu böyle bir gece de,

Yanı başımda görünce,

Gemileri yakmak  geldi içimden.

...

Siyasal Fakültesinin duvarlarına

Asılmıştı,kocaman harfli afişler,

Ellerinde sobalar ve taşlarla,

Gençlik coşkusu,  yüreklerinde,

Dış ülkelerden gelen piyonların,

Onları kullandığını,idrak edemeden,

Sağ ve solun çarkları, ezip geçiyordu.

O şiddet eylemlerini bizzat yaşadılar,

Geriye bıraktıkları, kaybolmuş yıllar,

Kitapsız kalmış, sömürülmüş beyinler,

Terk edilmiş, bir çok okullar,

Şimdi, buruk hikayeleri kalmıştı.

Bırakıp da gitmişlerdi,

Delice rüzgarlar... savurulurken.

...

Hala içlerinde, dalından kopmuş,

Taze çiçekler,

Vatan özlemi içinde,

Bir ayrı gurbet köşesinde,

Yeni filizlerini veriyordu.

...

Şimdi anarşist düşüncelerin,

Var olan düzene dikilmiş,

Dar gelen elbiseleri, çıkarırken,

Mükemmeliyete  yürümeği,

İdeal olarak görüyorlardı.

Düzenin bekçilerine, rest çektiler,

Savunmasız bırakılmış kişiler,

Ezici sözlerin,altında,

Daha da güzele,

Taşımak,

Yakalamak.

Sistemin çarklarına,

Kalkınma güçünü katarak,

Yıkım değil! 

Yakmak ve yağmalamak,

Hiç değil! 

Yenilenmek ve yeni oluşumlara,

Gebe kalmış bir bebeğin,

Doğum sancılarını çekiyorlardı.

...

Sevgi ne kadar da verilse,

Alınmak da,isteniyordu.

O seçimini yapmıştı,

Minik bebeği kucaklarken,

Sonsuz gülücükleri dudaklarında,

Gür siyah kaşlarına gizlediği,

Gözleri, aldı başını uzaklara gitti.

...

Kocaman yüreğine doldu,

Anne Sevgisi.

Sardı ve sarmaladı.

Nasırlaşmış irice elleri,

Bedenine yasladığı,

Korunmaya muhtaç bebeğine,

Bir yaşam iksiri olmuştu,

Tüm hücrelerinde çoğalan.

Zorlu bir mücadele bile olsa,

Hakkını vermeyi çok severdi.

..

Katı ve cüretkar görüntüsünde,

Kadife gibi yumuşak bir örtünün,

İç dünyasını sardığı görülüyordu.

Ölüme paylaştığımız,

Sonsuza kulaç attığımız,

Derinden dalarak bulduğumuz,

Herşeyde,

O ''toprak '' derdi.

Ben ise,

''rahmet'' diye,

Koşarak,gelirdim.

...

Gönül tellerimizden,

Sazlarımız ayrı, çalınırken,

İnançın bir zerresini,

Buz tutmuş yüreğine,

Akıtmak isterdim.

..

Dönüp geriye bakmadan,

Ayaklarını sürümeden,

O anarşist, sevecen,

Baba gibi, mert yüreğine,

Seher vakitlerinde topladığım,

Ruhani kokularla dolu,

Solmayacak çiçekleri,

Ekmek için beklerdim.

..

Nice gemiler kalkardı,

Bu limanda kalakalmış,

Gemiciler,

Taşırlar dururlardı,

Yaşam hikayelerini.', '.... Anılara sarılırdık bazı demlerde, Zaman sorumsuzça,  akar  gider, Geçmiş saatin, yelkovanları arkasında,  Gelecek akrep gibi zehirini a...', ARRAY['Türk Edebiyatı','Şiir','Cağlar Akarsu']::text[], 8.5, '{"poet":"Cağlar Akarsu","poet_slug":"caglar-akarsu","theme":"Türk Şiiri","is_hero":false,"total_lines":174,"source_url":"https://www.antoloji.com/bizden-geriye-kalanlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmalananlar', 'yagmalananlar-caglar-akarsu-9wr11', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İnsanlar ahlaki değerleri yitirince,

Sapıklar sarmıştı  bir anda,

Dünyanın her köşesinde bir çirkef,

Yerlerde sürünen insanlar,

Hayvani duyguların kılıfı içinde,

İnsanlıktan uzaklaştılar.

..

Her devleti sarmışsa hastalık,

Biçare orta yerde kalakaldık.

..

Kaldırmak istedik tüm kuralları,

Yıkmak istedik ''sadakat'' duygularını,

 hiç düşünmeden ''sevgiyi''atarak,

İnsanlık duygusu,sömürülmüş,

Herşey yanıp-kavrulup-yok olurken.

Bakakaldık arkasından,bir anda.

..

Bulmak istedik,insanca değerli taşı,

Ocak başlarında bekledik.

Geceler boynunu, bükmüştü,

Bir çocuğun yüreğini sardı.

Korku ve öfke dolu haykırışlar,

Sistemin koruyucularını  özledi,

Son noktaya kadar, bir çözüm,

Siddet   kurallarını,düğümledi,

Düzenin acımazsızlığını düşününerek,

Gün doğarken,umut gemilerine,

Güven kırıntılarını, yükleyerek,

                                                         Bekledi,

Yine bekledi.

...

17/aralık/2004

....

İnsanlar ahlaki değerleri yitirince,

Sapıklar sarmıştı  bir anda,

Dünyanın her köşesinde bir çirkef,

Yerlerde sürünen insanlar,

Hayvani duyguların kılıfı içinde,

İnsanlıktan uzaklaştılar.

..

Her devleti sarmışsa hastalık,

Biçare orta yerde kalakaldık.

..

Kaldırmak istedik tüm kuralları,

Yıkmak istedik ''sadakat'' duygularını,

 hiç düşünmeden ''sevgiyi''atarak,

İnsanlık duygusu,sömürülmüş,

Herşey yanıp-kavrulup-yok olurken.

Bakakaldık arkasından,bir anda.

..

Bulmak istedik,insanca değerli taşı,

Ocak başlarında bekledik.

Geceler boynunu, bükmüştü,

Bir çocuğun yüreğini sardı.

Korku ve öfke dolu haykırışlar,

Sistemin koruyucularını  özledi,

Son noktaya kadar, bir çözüm,

Siddet   kurallarını,düğümledi,

Düzenin acımazsızlığını düşününerek,

Gün doğarken,umut gemilerine,

Güven kırıntılarını, yükleyerek,

                                                         Bekledi,

Yine bekledi.

...

17/aralık/2004', 'İnsanlar ahlaki değerleri yitirince, Sapıklar sarmıştı  bir anda, Dünyanın her köşesinde bir çirkef, Yerlerde sürünen insanlar, Hayvani duyg...', ARRAY['Türk Edebiyatı','Şiir','Cağlar Akarsu']::text[], 8.5, '{"poet":"Cağlar Akarsu","poet_slug":"caglar-akarsu","theme":"Türk Şiiri","is_hero":false,"total_lines":65,"source_url":"https://www.antoloji.com/yagmalananlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Davudi Seda', 'davudi-seda-i-smet-barlioglu-jnaam', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir davudi seda gibisin kulaklarımda,

Görkemli minarelerden yayılmış

Seher vaktinde sabahın,

Saba makamında,

Yüreğimin içine içine işlemişsin,

Damarlarıma damarlarıma,

Kanıma,

Kanımın en küçük zerrelerine,

Ben biraz da bunun için kapanıyorum ya

Ellerine.

Seninle birlikteyim engin kubbeler altında,

Bazen bir Saltuk kümbetinin işlemelerinde,

Bazen taş kemerlerinde bir Selçuk sarayının,

Seninle birlikteyim

Çeyiz sandıklarından çıkarılmış bir mendilde,

Bazen fıçıya ekilmiş bir gülde,

Yağmurlu yamaçlardaki sümbülde,

Seni ben işte böyle kararsız etmişim

Gönülde.

Mızrak saplanamaz toprağa

Böylesine gaddarca,

Senin kalbime yırta yırta saplandığın gibi,

Ne hançer saplanabilir,

Ne kargı,

Ne kılıç,

Onun için bana derin bir sevgi olmuş

O hınç.

(Hikmet BARLIOĞLU (1933-2003)  ''nun

BİR ŞARKI SÖYLE BANA İsimli Serbest Şiirler ''inden > 55-56/100)', 'Bir davudi seda gibisin kulaklarımda, Görkemli minarelerden yayılmış Seher vaktinde sabahın, Saba makamında, Yüreğimin içine içine işlemişsi...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/davudi-seda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tek Derdim', 'tek-derdim-i-smet-barlioglu-eytoy', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Senden öte ne amacım var

Bu dünyada,

Senden öte ne derdim? 

Ekmekse; yiyecek bir dilim ekmeğim var,

İçecekse; bir kaşık ayran aşım,

Senden gayrı her şeyde dertsiz başım,

Güneşler doğar benim için,

Aylar doğandan batana dek benim,

Senden öte ne derdim var,

Ne derdim? 

Gün olur bir patikayım toz-duman içinde,

Bir ıslak tahta köprüyüm; basılıp geçilen,

Çam olukta berrak suyum; içilen,

Biryerlerde bir barınak sazdan-samandan,

Köşebaşlarında sana umutlanan dilenci,

Hem de seni senden önce beğenen

Erkenci.

Senden öte ne derdim, ne amacım var dünyada? 

Ne dağları kalburla elemem isteniyor,

Ne denizleri damla damla aktarmam,

Ne içini dışına çevirmem çukurların.

Sıyrılıp kurtulmuşum tüm dertlerimden,

Benim tek derdim sensin; 

Kurtulmak istemediğim

Ellerinden.

(BİR ŞARKI SÖYLE BANA İsimli Serbest Şiirler ''inden > 57-58/100)', 'Senden öte ne amacım var Bu dünyada, Senden öte ne derdim?  Ekmekse; yiyecek bir dilim ekmeğim var, İçecekse; bir kaşık ayran aşım, Senden g...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/tek-derdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz Şarkılar', 'sensiz-sarkilar-i-smet-barlioglu-maztu', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sensiz şarkılar ne kadar anlamsız,

Ne yüreğimde en küçük bir kıpırtı,

Ne başımda beni benden alıp giden rüzgarlar,

Ne ruhumda bir büyüleniş,

Ne içimde heyecan.

Sensiz şarkılar ne kadar anlamsız,

Sanki karşıma bir bayram günü çıkıyor

Zamansız.

Sen olunca bana büyülü bu şarkılar,

Sen varsan şarkılarla başım belada,

Varsa da o zaman şarkılar,

Yoksa da.

Özlemler gelip gelip yüreğimi yoklasa da,

Bilirim ki; tek işim yok özlemle,

Sevdiğim yanımda, ben kendi yanımdayım,

Bir yere gitmemişim, duruyorum,

Dünyamdayım.

Ben yoğurdu böyle yerim yiğit olarak,

Zira; seni şarkılarda arıyorum,

Şarkıları sende,

Sen bunu görmesen, bilmesen de,

Aşkın ne demek olduğunu bilirsin ya en azından,

Sensiz şarkıların aşkı bir başka aşk,

Sensiz şarkıların aşkı bir masal,

Çünkü; bir sen olup gidiyorsun bana şarkılar için

Emsal.

(BİR ŞARKI SÖYLE BANA İsimli Serbest Şiirler ''inden > 59-60/100)', 'Sensiz şarkılar ne kadar anlamsız, Ne yüreğimde en küçük bir kıpırtı, Ne başımda beni benden alıp giden rüzgarlar, Ne ruhumda bir büyüleniş,...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/sensiz-sarkilar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağız', 'agiz-gokhan-oflazoglu-s4fzy', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bilincin altın damlaları

toplansa karanlık bir kuyuda; 

salsam kovayı, çıksa renk renk,

çeşit çeşit cümbüş varlıkları; 

kahreden bir dansın esrimiş ağızları,

hep birden konuşmaya başlasa.

Değişimin izlenmesi güç sıkıntıları

dağılsa, bu yeni ağızlardan çıkan

ezgilerle dönse başımız; toplar

duyularımızı kavranması güç engelleri

aşarız. Deniz deniz boşalır, ırmak ırmak

çağlarız. Ses ses yükselir algılarımız,

tuhaf bir genişlikte daracık evler kurarız.

İnsan soyunun hep birlikte barındığı.

Ve tek bir ağız.

18/12/2004', 'Bilincin altın damlaları toplansa karanlık bir kuyuda;  salsam kovayı, çıksa renk renk, çeşit çeşit cümbüş varlıkları;  kahreden bir dansın ...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Oflazoğlu']::text[], 8.5, '{"poet":"Gökhan Oflazoğlu","poet_slug":"gokhan-oflazoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/agiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Marifet...', 'marifet-zulfikar-yapar-kaleli-t0fd6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'font face=''Comic Sans MS'' color=''black'' size=''0,5''

Görünene bakmak marifet değil, 

Marifet gizliyi görebilmektir. 

Vücudun şehrine göç edip il il 

Örümcek misali örebilmektir

Soluğu ensemde, bitmiyor takip 

Nefsim, irademe, aklıma rakip 

Nefsine palanga, kelepçe takıp 

Gönül diyarından sürebilmektir 

Saniye göz kırpar yaşlıya, gence 

Ne sona bırakır, ne alır önce 

Hesaplayıp şöyle inceden ince 

Bir mahzun gönüle girebilmektir 

Hatasız, günahsız olunca Nebi 

Yolların düğümü, yer ona tabi! 

Acıdan bal yapan arılar gibi 

Çiçeğin özünü derebilmektir 

Ölüm kurtuluştur, buz tutan çağda 

Uyku rezalettir, terleyen dağda 

Derman da, hasta da, ölü de, sağda 

Varlığın sırrına erebilmektir.', 'font face=''Comic Sans MS'' color=''black'' size=''0,5'' Görünene bakmak marifet değil,  Marifet gizliyi görebilmektir.  Vücudun şehrine göç edip ...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/marifet-51-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Derdimi Yazdım', 'derdimi-yazdim-suleyman-yavuz-cwaty', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yalnızım yapayalnız 

Hayatta tek başıma ben arkadaş

Arkamda ne ana ne baba

Nede gardaş 

Koca dünyada bulamadım 

Yanımda duranı

Hep geldi sırtımdan vuranı

Bulamadım koca dünyada bana yoldaş olanı

Yar var dedim 

Yar dan attı beni

Aşıma zehir kattı bırakıp gitti beni

Şimdi ben dertli ben kederli

Yaşıyorum yazıyorum işte böyle şiirleri

(Bilenler bilir bilmeyenler öğrenir bizi

Duyan duymuş namımızı deli olan admızı 

Mersinden bir Süleyman çıkmış

Çıkmış ta ne olmuş dünyada gülmedikten sonra)', 'Yalnızım yapayalnız  Hayatta tek başıma ben arkadaş Arkamda ne ana ne baba Nede gardaş  Koca dünyada bulamadım  Yanımda duranı Hep geldi sır...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Yavuz']::text[], 8.5, '{"poet":"Süleyman Yavuz","poet_slug":"suleyman-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/derdimi-yazdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Artık', 'artik-oguz-yirmibes-np17c', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Artık geçmiyor hayatım eskisi gibi

Akıp geçmiyor zaman

Hatırlayamıyorum senin için unuttuğum yüzleri

Sevgi geçmiyor artık damarlarımdan

Mutlu bitmiyor hikayelerimin sonu 

İyiler kazanmıyor artık savaşları

Kimse savaşmıyor bulmak için aşkını

Herkes mutsuz artık benim şehrimde 

Sanki ülkem işgal halinde 

Barajlar kurmuşlar gözlerime

Doluyorum,doluyorum sürekli 

Ama ağlamak bile isteyemiyorum artık', 'Artık geçmiyor hayatım eskisi gibi Akıp geçmiyor zaman Hatırlayamıyorum senin için unuttuğum yüzleri Sevgi geçmiyor artık damarlarımdan Mutl...', ARRAY['Türk Edebiyatı','Şiir','Oğuz Yirmibeş']::text[], 8.5, '{"poet":"Oğuz Yirmibeş","poet_slug":"oguz-yirmibes","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/artik-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekleyeceğim', 'bekleyecegim-oguz-yirmibes-hfj3l', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ölümü tercih ettim ben mutsuzluğuma 

Ağlatmak en büyük hakaretti bana

Güzelliğinin arkasındaki gizemi

Çözemedim ben yıllarca

Bana bakan gözlerinin ardındaki gizem

Sözüm sana, yok başka çarem

Gecenin gündüze gündüzün geceye döndüğü vakit 

Seni unutulmuş bir şehirde sonsuza dek bekleyeceğim', 'Ölümü tercih ettim ben mutsuzluğuma  Ağlatmak en büyük hakaretti bana Güzelliğinin arkasındaki gizemi Çözemedim ben yıllarca Bana bakan gözl...', ARRAY['Türk Edebiyatı','Şiir','Oğuz Yirmibeş']::text[], 8.5, '{"poet":"Oğuz Yirmibeş","poet_slug":"oguz-yirmibes","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bekleyecegim-29-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ruh', 'ruh-oguz-yirmibes-k7h88', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Artık kuşlar alçak uçmuyor bana

Bazen kafam çarpıyor bulutlara

Kim demiş uzay çok uzaklarda

Ellerimle değebiliyorum yıldızlara

Değmiyor yere, toprağa ayaklarım

Sanki ben uçuyorum havadayım

İnsanlar küçük sorunlar çok küçük artık

Çünkü ben ölmüşüm sadece bir ruhum artık', 'Artık kuşlar alçak uçmuyor bana Bazen kafam çarpıyor bulutlara Kim demiş uzay çok uzaklarda Ellerimle değebiliyorum yıldızlara Değmiyor yere...', ARRAY['Türk Edebiyatı','Şiir','Oğuz Yirmibeş']::text[], 8.5, '{"poet":"Oğuz Yirmibeş","poet_slug":"oguz-yirmibes","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ruh-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arkadaşım', 'arkadasim-gokhan-oflazoglu-6622r', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Serin bir sabaha terkettiğimiz

ölülerin çırpınmasıydı hayat.

O çıkamadı işin içinden,

ben başardım; üstüm başım kan.

Aynı cinnetin ateşlerinde yandık,

katlanılmaz bir ihanetti önümüzde

gülümseyen yaşam. Algılarımızın

cehenneminde isyan; her yanda

bekleşenlerden usandık.

Bir trenin karanlık tünele girmesi gibi,

tutuldu güneşimiz. Çıkmalıydık bu

bu bataklıktan. Zordu işimiz, aydık.

Ölüler bile daha gayretliydi bizden,

tükenmişti damarlarımız, ama, çıkmalıydık.

Son bir hamle kalmıştı, ben sürüdüğüm canımla

dikeldim. Her taraf pırıl pırıl aydınlık.

O sinsi bir gazla zehirlenmiş, yanlış

bir iddiaya kapıldı. Şimdi ne yapıyor

bilmem, uzun zamandır görüşmedik.

Şimdi aklın kıyılarını, uzak bir sahilden

seyrediyorum. Sözümona çıktım işin içinden.

Üstüm başım kan.

18/12/2004', 'Serin bir sabaha terkettiğimiz ölülerin çırpınmasıydı hayat. O çıkamadı işin içinden, ben başardım; üstüm başım kan. Aynı cinnetin ateşlerin...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Oflazoğlu']::text[], 8.5, '{"poet":"Gökhan Oflazoğlu","poet_slug":"gokhan-oflazoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/arkadasim-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık', 'ayrilik-elcin-orhan-mm4c0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'dudağının arasından çıkan her ses 

canımı acıtıyor 

ne çok yanılmışım 

bırak seni, 

ben bile kendimi aldatmışım 

bent olurdu ya erkekliğin 

kızarır, dolar boşalmazdı gözyaşın 

gidişinin ardından 

içimdeki “er” müsaade etmiyor 

ilk kez 

akmıyorum 

doluyorum, kızarıyorum 

o çok sevdiğim gözlerine bakmıyorum 

ensemden uyuşmaya başladım 

ayrılığın sarhoş adımları 

yön bulamıyor 

kokun, 

hadi doku diyor, 

duruyorum 

kararsız...... 

ve karar 

git gözüm görmesin....! 

her defasında 

kolayca çözdüğün düğüm 

görüyorsun çözülmüyor, 

yanlış ipi çektin 

içli şarkılarda doyasıya ağlayabilirim artık 

adını yazarım sayfalarca 

bir ateş..... 

yakarım sonra 

seni, beni 

kül, duman 

bitti sevda 

kaldı ayrılık....', 'dudağının arasından çıkan her ses  canımı acıtıyor  ne çok yanılmışım  bırak seni,  ben bile kendimi aldatmışım  bent olurdu ya erkekliğin  ...', ARRAY['Türk Edebiyatı','Şiir','Elçin Orhan']::text[], 8.5, '{"poet":"Elçin Orhan","poet_slug":"elcin-orhan","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/ayrilik-212-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Munzur''a', 'munzur-a-eyup-hanoglu-tvxml', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yüreğinden iki damla yaş düşmüş

Sordum; nereye? 

Dedi; Munzur’a...

Ait olduğum gözlere varmak için.

Dedim; bakar mısın semaya? 

Dedi; sema benim içimde,

                              İçim Munzur’dadır.

Dedim; Munzur nedir? 

Dedi; Munzur benim,

          Yürekten dökülen iki damla yaştır Munzur,

          Yaşlar döküldüğü yeri yeşertir su gibi,

          Munzur bir su’dur...

Dedim; Munzur neredir? 

Dedi; kalbimin doğusudur

          Yüreğinin baktığı yerdedir

          Munzur bir dağ’dır...

Dedim; neden her zaman gözyaşı? 

Dedi; her zaman değil,

          Tarih yeniden yazılana kadardır ömrü gözyaşının.

Dedim; ömür nedir? 

Dedi; su’yun dağ’a hayat vermesidir,

          Ömür bir Munzur’dur...

Dedim; gurbet neredir? 

Dedi; karnının doyduğu yerdir.

Dedim; gurbet nereye kadar? 

Dedi; karnın Munzur’da doyana kadar.

Dedim; Munzur nereye kadar? 

Dedi; gözyaşı son bulana kadar.

Dedim; sen bir göz yaşısın,

             Sen de son bulursun.

Dedi, ben gurbette başlarım, Munzur’da son bulurum,

          Munzur bir efsanedir...

31 Ocak 2001, Sofra Restaurant, AKSARAY', 'Yüreğinden iki damla yaş düşmüş Sordum; nereye?  Dedi; Munzur’a... Ait olduğum gözlere varmak için. Dedim; bakar mısın semaya?  Dedi; sema b...', ARRAY['Türk Edebiyatı','Şiir','Eyüp Hanoğlu']::text[], 8.5, '{"poet":"Eyüp Hanoğlu","poet_slug":"eyup-hanoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/munzur-a-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tereddütler-5', 'tereddutler-5-hasan-sun-c2jy0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'gördüğüm şuydu:

-gece kapatınca kapıları sevdalara

başlardı silahlar yağlanmaya

en inançlı mermiler dizilirdi namluya

her sevdalı gözü yaşlı olurdu,

özlem olurdu,

onur olurdu

olurdu

ka-

til olurdu

olurdu,ölürdü

(bir ölüm tarifiyim aslında)

gördüğüm şudur:

dağınık yatak üzerinde peçeteler

peçeteler üzerinde kardeşlik türküsü

türküde yaram,''uzun yaram''

manşetlerde

-ben sana mecburum sömürgem

sen allaha...

göreceğim:

acelesiz, öfkesiz bir türkü gibi

mecbur olunanların, olanların evrileceği

bir sigara dalmışlığında anılan acılar

bütün çiçekleri açan koca bir bahar

                                      (kasım/2004/göksun)', 'gördüğüm şuydu: -gece kapatınca kapıları sevdalara başlardı silahlar yağlanmaya en inançlı mermiler dizilirdi namluya her sevdalı gözü yaşlı...', ARRAY['Türk Edebiyatı','Şiir','Hasan Sun']::text[], 8.5, '{"poet":"Hasan Sun","poet_slug":"hasan-sun","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/tereddutler-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '.Sen Ben Gibi Ben Sen Gibi', 'sen-ben-gibi-ben-sen-gibi-hulya-karaca-gt3fo', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Karanlık dünyadan aydınlığa çıkmak gibi

Akşama doğan eşsiz güneş gibi

Gönülden gönüle konana bir kuş gibi

Ve bir de keremin aslıya duyduğu aşk gibi

Sende sensizliğime doğ güneş gibi

Uzun bir yolun sonu gibi

Bir dağ yamacından sonra önüme çıkan kasaba gibi

Açan bir goncanın son yaprağı gibi

Ve bir de sana kavuşma dileğim gibi

Sende bana hasret duy sıla özlemi gibi

Gecenin karanlığında çıkan yıldızlar gibi

Gerçek olmasını istediğin bir dilek gibi

Sonsuzluğa giden yollar gibi

Ve bir de sevdanın ateşinde yanan yürek gibi

Sende bana yan benim sana yandığım gibi

Ayın gölgesinden kaçan çehren gibi

Gözlerinde biriken yaşlar gibi

Susuz toprağa düşen tek damla gibi

Ve bir de çölün ortasında serap gören abdal gibi

Sende beni bul kendinde benim sende bulduğum gibi

Seherde esen rüzgar gibi

Sensizliği getiren o günler gibi

Senden kopmayı istemeyen aşık gibi

Ve bir de kıyamet olacak sensizliği tattırmak gibi

Sende benden ayrılığı isteme ölüm gibi

Denizlere açılan tekneler gibi

Sensizliğe alışamayacak bendim  gibi

Gülüşüne kavuşamayacak körpe ruhum gibi

Ve birde sözlerini unutmayacak şair gibi

Sende beni unutma gözyaşların gibi

Kalp atışını hissettiğin an gibi

Ölümün yaklaştığını bildiğin gibi

Sana anlatmayı başaramadığım tutkum gibi

Ve bir de sensizliğin ölüm olacağını bildiğim gibi

Seninde beni bırakıp gitmemen göçmen kuşlar gibi', 'Karanlık dünyadan aydınlığa çıkmak gibi Akşama doğan eşsiz güneş gibi Gönülden gönüle konana bir kuş gibi Ve bir de keremin aslıya duyduğu a...', ARRAY['Türk Edebiyatı','Şiir','Hülya Karaca']::text[], 8.5, '{"poet":"Hülya Karaca","poet_slug":"hulya-karaca","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/sen-ben-gibi-ben-sen-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yokluk', 'yokluk-necat-necdet-demircan-uxg25', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Varsa ceketin

Düğme iliklerinin içinden eser rüzgar

Döndürür saçlarının rengini beyaza

Eser

Kalp kapılarının menteşelerini zorlar

Delik yorgan altında rüyadır

Duyulmaz midenin feryadı haykırışlar

Kırmızı alarm verir titreyen dişlerin

Dermansız, mecal arar

Bükülür çaresizce dizlerin

Topuksuz çorapların

Samimi arkadaşı

İnce, siyah lastik tabanlı ayakkabılar

Sokak kiri sular

Kucaklar

Kimsesiz yüzer parmaklar

Yüksekçe bir apartmanın

Kileri dolu mutfağıdır tokluk

Ne Yaz gelir

Ne İlkbahar

Yalnızdır

Kimsesizdir

Bitmez bir Kış mevsiminin adıdır yokluk...', 'Varsa ceketin Düğme iliklerinin içinden eser rüzgar Döndürür saçlarının rengini beyaza Eser Kalp kapılarının menteşelerini zorlar Delik yorg...', ARRAY['Türk Edebiyatı','Şiir','Necat Necdet Demircan']::text[], 8.5, '{"poet":"Necat Necdet Demircan","poet_slug":"necat-necdet-demircan","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/yokluk-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir köpek kulübesi ve çocuk', 'bir-kopek-kulubesi-ve-cocuk-firat-oncu-p9w9g', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sahteliğn ve karanlığın ardından,

İki damla gözyaşı

Ve köpeklerin bile barınmadığı bir kulübe

Yani; köpeklerin beğenmediği terk ettiği,

Bir kulübe...

Bende derin iz bırakan o gece,

Kendimi yollara vurmuş

Tenhalığın,sessizliğin ve yanlızlığın verdiği,

O hazla,

Sokak sokak,mahalle mahalle geziyorum

Yine dedemden tek hatıra,

O şapkayı takmışım

Düşünüyorum...

Sabah ezanı okunmuştu.

Yüce bir camiinin önünden,

Minaresine bakarak geçtim.

Sonra bir kulübe gördüm

Bir köpek kulübesi...

İçerden bir çocuk ağlaması

Hava ayaz,her yer don tutmuş

Beş yaşlarında yalın ayak bir çocuk uzanmış,

Ağlıyor...

Yüzü bembeyaz

Durdum,düşündüm

O titreyen küçük ellerini gördüm

Konuşamaya çalıştım

Olmadı,beceremedim...

Paltomu,atkımı ona verdim 

Onu sardım,ağladım

Ve bir sigara yaktım

Açtı belliydi,titremişti,üşüyordu,

Kimdi,kimin nesiydi? 

Anası ölmüştü,

Babası sürtük bir üvey ana almıştı yanına

Herşey apaçık ortadaydı...

Ne yapmalıydı şimdi? 

Açtı...

İnadına bütün lanet,dükkanlar,fırınlar

Kapalıydı...

Sabah ezanı okunmuş...

Sözde yiyecek bir şey alacaktım,

Cebimdeki son kuruşu sigaraya verdiğimi unutmuşum

Sinirlendim,yumruğumu sıktım ve ağladım

İlkez sigaramdan

Yani; dostmdan tiksindim ve ayrılmak istedim

Yine de beceremedim

Bir tane daha yaktım

İtlerin şerefine...

Ellerim titredi sinirden,

Yüreğim birden çatladı

İçimi bir sızı aldı,beni götürdü

Bir köpek kulübesi ve bir de çocuk...

Acıdım,ağladım,bağırdım

Ve düşündüm

Benim durumum onunkinden farklımıydı? 

Bende viradım acınacak,durumdaydım

Kahvaltımı,yemeğimi sigarayla yapan ben,

Ağzımın açlık kokusu her yanı saran ben,

Utancımdan zemheri gecelerde volta atan ben,

Acıdım ama nafile

Güçsüzdüm,boynum büküktü

Gücüm yetmezdi fermana

Eğer yetseydi

İstediğim tek şey olurdu

Benim yok olup

Tarihin sayfalarında,

O,bir tek satırlık yer edinme

Ve bütün çocukların,boynu büküklerin

Boyunlarının bükülmemesi 

Ve güçlü olmaları...

Sonra,

Haykırdım

Nerde o köşeyazılarında,meyadanlarda,radyolarda

Nutuk çekenler? 

Nerde yavrusunu bir çöplükte bile değil,

Bir köpek kulübesinde bırakan,

Para,zevk düşkünü olan o babalar

Asıl o kulübe o babaların,o nutuk çekenlerin

Tapulu mekanları,kulübesi

Burdan selam olsun onlara,o itlere...', 'Sahteliğn ve karanlığın ardından, İki damla gözyaşı Ve köpeklerin bile barınmadığı bir kulübe Yani; köpeklerin beğenmediği terk ettiği, Bir ...', ARRAY['Türk Edebiyatı','Şiir','Fırat Öncü']::text[], 8.5, '{"poet":"Fırat Öncü","poet_slug":"firat-oncu","theme":"Türk Şiiri","is_hero":false,"total_lines":80,"source_url":"https://www.antoloji.com/bir-kopek-kulubesi-ve-cocuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Derbeder', 'derbeder-necat-necdet-demircan-8h5ob', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Halen avucundaysa ''TİK TAK''ların

Umursama boşver

Kimileri yaşar, kimileri seyreder

Seyirci olma

Silkin, etme kendini heder,

Kalma zaman tükendiğinde Derbeder...', 'Halen avucundaysa ''TİK TAK''ların Umursama boşver Kimileri yaşar, kimileri seyreder Seyirci olma Silkin, etme kendini heder, Kalma zaman tüke...', ARRAY['Türk Edebiyatı','Şiir','Necat Necdet Demircan']::text[], 8.5, '{"poet":"Necat Necdet Demircan","poet_slug":"necat-necdet-demircan","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/derbeder-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özgür Kız', 'ozgur-kiz-firat-oncu-o1jqf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Selam gökyüzüne ismini; göğü yırtarcasına yazdığım özgür kız

Biliyorum; beni seviyorsun

Sus söyleme sev beni ama belirtme sende kalsın

Ben bir fırtınaya kapılmış gidiyorum

Dallara tutunmayarak; dallara tutunmayı içime yediremediğimden

Belki bu fırtına bir sürgünde,zindanda,gurbette son bulur

Beni alır atar bir köşeye

Ama sen hiç ağlama her zaman gül

Gülmek sana yakışıyor; yüreğime kendime tarif edemediğim özgür kız

Belki beni tekrar görürsün

Beden dibinde cigaramı tüttürürken

Bir zindanda bitli bir zindanda bitlerimle boğuşurken

Gurbette; çok uzaklarda özlem duyarken

Sürgünümde; dağlarda,ovalarda,köylerde

Maceramda Piramidlerde,okyanuslarda,Nemrud''ta,Evereste

Biliyorum; özgür kız en çok sen beni anlıyorsun

Biliyorum senin devletini

Senin devletinde nehirler,dağlar,ovalar ve tarihler devleti

Çok severim seni ve Diyarbekir''i

Beni en çok siz anlıyorsunuz

Belki de bana öyle geliyor

Biliyorum; Diyarbekir''in ağzı olduğu gibi dili olsaydı

Dertleşirdi benimle,anlatırdı kendini,şanını,sırlarını

Zaten Diyarbekir''in dili olsaydı fırtınaya kapılmazdım

Biliyorsun özgür ve esmer kız; Diyarbekir benim için çok önemli

Kendimi orda buluyorum sen de bulduğum gibi

Sıkılma buradan,ayrılma Diyarbekir''den zamanı gelene kadar

Üzme beni,ağlatma beni

Diyarbekir''in dili yok haykıramaz evrene

Kimsenin gelip sormadığı kadim kent

Yok olmaya terk edilmiş kentim

Terk edenlerin inadına o bizi terk etmiyor

Ey kadim kent! Neden bu kadar sessizsin? Neden? 

Artık tüm evreni sarsarcasına haykır,konuş yeter ki susma

Evet özgür ve esmer kız; 

Bir yanımda sen bir yanımda Diyarbekir

Ben daha ne isterim...', 'Selam gökyüzüne ismini; göğü yırtarcasına yazdığım özgür kız Biliyorum; beni seviyorsun Sus söyleme sev beni ama belirtme sende kalsın Ben b...', ARRAY['Türk Edebiyatı','Şiir','Fırat Öncü']::text[], 8.5, '{"poet":"Fırat Öncü","poet_slug":"firat-oncu","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/ozgur-kiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Başlamak Güzeldir Bitirmekten', 'baslamak-guzeldir-bitirmekten-yunus-guzel-u2q1i', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir yavru kuş havalandığında gökyüzüne

Tomurcuklar yardığında ağacın gövdesini

İlk gülüşünde bebeğin 

Bir bakıştan atlayan kıvılcım

Yaktığında yüreğini

Başlayan bir şeyin 

Hiç bitmeyeceğine inanırsın

Küllenmeye başlayınca yüreğindeki ateş

Kalp kırıklarını toplamaya başlarsın yerden

Güzün rengi düşer yaprağa

Düşene gülünmeyeceğini anlarsın

Ve bir bebeğin dünyaya geldiğinde 

Önce ağladığını anımsarsın…

Başlamak güzeldir elbet

Bitirmesini de bilmek  gerek...', 'Bir yavru kuş havalandığında gökyüzüne Tomurcuklar yardığında ağacın gövdesini İlk gülüşünde bebeğin  Bir bakıştan atlayan kıvılcım Yaktığın...', ARRAY['Türk Edebiyatı','Şiir','Yunus Güzel']::text[], 8.5, '{"poet":"Yunus Güzel","poet_slug":"yunus-guzel","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/baslamak-guzeldir-bitirmekten-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşlerim seni', 'duslerim-seni-firat-oncu-cangg', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hergün seni düşlerim gece gündüz demeden

Kevoklar içinde

Düşlerim surlarını

Melekler içinde

Düşlerim seni

Mazide; insanoğlunun tarih yapraklarının en başında

Düşlerim senin 

Aşklarını,savaşlarını,barışlarını,görkemini ve herşeyini

İsterim seni 

Çiçekler içinde

Barış ve aşk içinde

İsterim senden

Kendi belğini evrene haykırmanı

İsterim senden 

Karanfillerini,zümbüllerini,evlerini; gerçek Diyarbekir''i

İstersin benden 

Seni koruyup asırlara inat yaşatmayı

Bunu da bil; 

Beni kimse anlamaz bari sen anla 

Ey kadim kent! 

Diyarbekir...', 'Hergün seni düşlerim gece gündüz demeden Kevoklar içinde Düşlerim surlarını Melekler içinde Düşlerim seni Mazide; insanoğlunun tarih yaprakl...', ARRAY['Türk Edebiyatı','Şiir','Fırat Öncü']::text[], 8.5, '{"poet":"Fırat Öncü","poet_slug":"firat-oncu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/duslerim-seni-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Diclem', 'diclem-firat-oncu-9pil9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İnadına ak cennet ve barış nehrim Dicle

Nazik ve kibarca

Zalimleri ve ön yargılıları tokatlarcasına

Yaşat medeniyetlerin beşiğini ve sebebini

Yaşat ki şenlensin

Yaşat Mezo''yu,Diyarbekr''i,Hasankeyf''i

Yaşat benim Diyarımı

Orda benim aşklarım,anılarım ve geleceğim var

Anıların hatrına ak Diclem ak

Surlar ve Hasankeyf mazlum duruşlarıyla sana selam eder

Mezo; bereketli topraklarıyla sana dua eder

Bunun için ak barış ve cennet nehrim Diclem ak

Unutmaki Diclem! 

Mezo seni kalbinin derinliklerinde taşır

Ak diclem ak bedbahtları tokatlarcasına...', 'İnadına ak cennet ve barış nehrim Dicle Nazik ve kibarca Zalimleri ve ön yargılıları tokatlarcasına Yaşat medeniyetlerin beşiğini ve sebebin...', ARRAY['Türk Edebiyatı','Şiir','Fırat Öncü']::text[], 8.5, '{"poet":"Fırat Öncü","poet_slug":"firat-oncu","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/diclem-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yapraklar Sarardığında', 'yapraklar-sarardiginda-necat-necdet-demircan-jr36x', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Üzüldüm Sevgili! "Benden gittiğinde, ruhundaki son mutluluğu da kurban vermişsin ilk gördüğüne…"

Kallavi bir hüzün çöreklenir 

yüreğimin otağına,

Yapraklar her sarardığında,

Salına salına,

Sen yağarsın aklıma…

Siyaha boyadığında ressam tuvalini 

Gökyüzü küskün bakışlarla karardığında,

Kuzey rüzgârları güneşe darıldığında,

Yağmurlar sebepsiz sızlanmaya başladığında 

Şıpsevdi yüreğinin hazinesi boşalıp 

Hiç ümidin kalmadığında…

Senaryosuz oynadığın filmin 

Minnacık bir karesinde beni canlandırdığında,

Göz kapakların ağırlaştığında 

Akşamla sabah arkadaş olduğunda… 

Çiçek açamaz ormandan ırak ağaçlar, 

Kanat çırpamaz yaşam çömezi kuşlar 

Feryat, figan, öylesine suspus, öylesine hazin 

Döneceksin birileri ağladığında 

Yapraklar sarardığında...

"Kızıl bir korsana benzer Sonbahar rüzgarı, yıllanan zamanlarımızı çalıp hüzün denizlerine yelken açan..."', 'Üzüldüm Sevgili! "Benden gittiğinde, ruhundaki son mutluluğu da kurban vermişsin ilk gördüğüne…" Kallavi bir hüzün çöreklenir  yüreğimin ota...', ARRAY['Türk Edebiyatı','Şiir','Necat Necdet Demircan']::text[], 8.5, '{"poet":"Necat Necdet Demircan","poet_slug":"necat-necdet-demircan","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/yapraklar-sarardiginda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayal Bahçesi', 'hayal-bahcesi-necat-necdet-demircan-s7cgk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Çok beklersen büyür rüyaların

Hayal; 

Ya kurur tamamen umut bahçen

ya da 

Kıyamadan

Koklar,

Kapatırsın gözlerini

Ağlarsın sevinçten...', 'Çok beklersen büyür rüyaların Hayal;  Ya kurur tamamen umut bahçen ya da  Kıyamadan Koklar, Kapatırsın gözlerini Ağlarsın sevinçten......', ARRAY['Türk Edebiyatı','Şiir','Necat Necdet Demircan']::text[], 8.5, '{"poet":"Necat Necdet Demircan","poet_slug":"necat-necdet-demircan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/hayal-bahcesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arama', 'arama-necat-necdet-demircan-xgxct', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Vazgeçmek yaşamdır

Durdun, gün batımının ötesisin şimdi

Kapkaranlık esen rüzgârdın 

Sustun 

Arama nedenini

Sabırsızdım

Sensiz olmaz sandım

Korktum

Ama unuttum...

Hep kibirle bakarsan hayata,

Sana ihtimamla yaklaşanlara,

Ayaz yağmaya başlar 

Hiç solmaz sandığın umutlarına

Sıcak bir ele hasret kalırsın,

Takvim yaprakların bir bir sarardığında…', 'Vazgeçmek yaşamdır Durdun, gün batımının ötesisin şimdi Kapkaranlık esen rüzgârdın  Sustun  Arama nedenini Sabırsızdım Sensiz olmaz sandım K...', ARRAY['Türk Edebiyatı','Şiir','Necat Necdet Demircan']::text[], 8.5, '{"poet":"Necat Necdet Demircan","poet_slug":"necat-necdet-demircan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/arama-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Var?', 'ne-var-necat-necdet-demircan-wfcrw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Batıda yağmur

Doğuda kar

Umutsuz bekleyişlere eser rüzgar

Söyle yar

Sende ne var? 

Binbirle çarpılan geceler

Bitmez sükunet

Serzenişe mahkum

Dilsiz sende heceler

Ne tırmanmaya değer

Sarp dağlar

Ne de içten gülümsemeler

Nedensiz bir vakar

Bomboş sendeki masallar

Sende

Başkasında olmayan ne var? 

Siyah saçlar

Her buklesinde ayrı hüzün

Durmaz ha bire can yakar

Tadını bilmediğin suyu anlatma

Laf olsun diye boşuna bakma

Lav sıcağı yaşlarla akma

Göğe bak

Kendini tanı

İşte yeryüzü ayaklarının altında

Söyle yar

Sende olmayan ne var?', 'Batıda yağmur Doğuda kar Umutsuz bekleyişlere eser rüzgar Söyle yar Sende ne var?  Binbirle çarpılan geceler Bitmez sükunet Serzenişe mahkum...', ARRAY['Türk Edebiyatı','Şiir','Necat Necdet Demircan']::text[], 8.5, '{"poet":"Necat Necdet Demircan","poet_slug":"necat-necdet-demircan","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/ne-var-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur Senfonisi', 'yagmur-senfonisi-necat-necdet-demircan-o5jfy', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Söyle Sevgili! 

Niye,

Gün ortasında,

Kara bulutların hüzünlerini

Gözlerime bırakıyorsun,

Yoksa,

Beni hep yağmurlarda mı anıyorsun…

İlk pıt pıtları ritm tutar

Damlalar birikir saçlarında

Süzülür keman çığlığı ince tellerinden

Yavaş bir melodiye dönüşür yanaklarında

Bas gökgürültüsü haykırır

Azar sonra şiddeti

Çarpar göz kapaklarına

Arya olur kulaklarına

Teneke damların

Tenorları eşlik eder

Katılır derinden

Bu mucizevi koroya

Fagot rüzgar başlar

Flütün cılız sesini bastırırcasına

Fırtınanın sesi haykırır

Delinir gökyüzü bardaktan boşanırcasına

Zengini, fakiri, kimsesizi

Yıldızlar izleyemez

Ay ışığı derin uykuda

Sarmalar yürekleri

Kırmak ister kimsesiz pencereleri

Hüzün dolu bir yağmur senfonisi...', 'Söyle Sevgili!  Niye, Gün ortasında, Kara bulutların hüzünlerini Gözlerime bırakıyorsun, Yoksa, Beni hep yağmurlarda mı anıyorsun… İlk pıt p...', ARRAY['Türk Edebiyatı','Şiir','Necat Necdet Demircan']::text[], 8.5, '{"poet":"Necat Necdet Demircan","poet_slug":"necat-necdet-demircan","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/yagmur-senfonisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Denli', 'ne-denli-necat-necdet-demircan-l97up', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ne denli bilirsen

El yangınını

Odun dolu

Teneke sobalardan hatıra kalan

Ne denli düştüysen

İlk seferinde

Dikiş atılası diz kapaklarının acısı

Ne denli üşüdüysen

Donmuşsa göz kapakların

Kısılmışsa sesin yalvarmaktan

Ne denli sarhoşsan

Arkadaşsan kuru otlarla

Ne kadar bakmışsan

Boş gözlerle duvarlara

O denli

Aşk yangını

O kadar ''Ah'' dedirten

Suskun kere suskun

Kimsesiz oğlu kimsesiz

Çılgına çeviren

Delirten...', 'Ne denli bilirsen El yangınını Odun dolu Teneke sobalardan hatıra kalan Ne denli düştüysen İlk seferinde Dikiş atılası diz kapaklarının acıs...', ARRAY['Türk Edebiyatı','Şiir','Necat Necdet Demircan']::text[], 8.5, '{"poet":"Necat Necdet Demircan","poet_slug":"necat-necdet-demircan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ne-denli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Beklerim', 'seni-beklerim-necat-necdet-demircan-c91f5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Cik cik dolusu seslerin

Anlaşılmazı

Küçük dilsizim

Sevenim

Dünyayı kendine benzetenim

Gözyaşsızım

Mükemmelim

Kurallar kraliçesi

Hayalperestim

Kum şatolum

Dalgakıranım

Dümensiz gemim

Kendini eşsiz sanan

Zavallı sevdiceğim

Ceylanım

Büyülüm

Kara gözlüm

Özdeyişlim

Dudak bükenim

Kendini beğenenim

Güzel sensin

Ahmak ben

Kalp bu ya

Hatta teklerim

Sen de öyle san

Ben hep seni beklerim...', 'Cik cik dolusu seslerin Anlaşılmazı Küçük dilsizim Sevenim Dünyayı kendine benzetenim Gözyaşsızım Mükemmelim Kurallar kraliçesi Hayalperesti...', ARRAY['Türk Edebiyatı','Şiir','Necat Necdet Demircan']::text[], 8.5, '{"poet":"Necat Necdet Demircan","poet_slug":"necat-necdet-demircan","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/seni-beklerim-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Emrine Amade', 'emrine-amade-necat-necdet-demircan-yc4r4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Durdurdum dünyayı

Artık hiç dönmeyecek

Güneş sensin, ateşi sönmeyecek

Masmavi boyadım bir uçtan bir uca

gökyüzü solmayacak

Sadece sen varsın başkası olmayacak...

Değersin kullanılmaya

Uzun uzun bakılmaya

Öyle tatlı sözlerin

senin gibi minicik

Şarkı sensin, ayna sen 

Sensin biricik...

Belli ki saatler yok güzelim

Yok işte miladı takvimlerin

Sensizlik sarar her yanı, kavurur ateşin

Varsa başka bir emrin

Parmaklarını şıklat

Emrine amadeyim (!)', 'Durdurdum dünyayı Artık hiç dönmeyecek Güneş sensin, ateşi sönmeyecek Masmavi boyadım bir uçtan bir uca gökyüzü solmayacak Sadece sen varsın...', ARRAY['Türk Edebiyatı','Şiir','Necat Necdet Demircan']::text[], 8.5, '{"poet":"Necat Necdet Demircan","poet_slug":"necat-necdet-demircan","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/emrine-amade-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Yazık', 'sana-yazik-necat-necdet-demircan-96xlp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Başarısızlıkların gölgesi olsaydı

Yeryüzü karanlıktan kurtulmazdı

Küçük başarılar bu kadar abartılmasaydı

Güneş asla yeniden doğmazdı

Beceremediklerimize giydirdiğimiz kılıf

Hep aynı süslü elbise

Yalan değil mi bunlar

Bundan değil mi yerimizde saydığımız aheste? 

Delemediğimiz dağlar

Aşamadığımız engeller

Bölemediğimiz topraklar

Nedense

Hep ayrı düşer uşaklar

Vah sana yazık olmuş

Heyben hep riya ile dolmuş

Taşıyamadığın yükler

Dönmüş sana yeniden

Akılsız başın yüzünden

Ayakların köle olmuş

Batarsa bacakların

Gövden kaybolur yavaşça

Başsın

Başın yüksekte

Yüksek yetmez

Hatta burnun gökte

Bataklık çekerse içine

Unutma

Beynin kalır en dipte...', 'Başarısızlıkların gölgesi olsaydı Yeryüzü karanlıktan kurtulmazdı Küçük başarılar bu kadar abartılmasaydı Güneş asla yeniden doğmazdı Becere...', ARRAY['Türk Edebiyatı','Şiir','Necat Necdet Demircan']::text[], 8.5, '{"poet":"Necat Necdet Demircan","poet_slug":"necat-necdet-demircan","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/sana-yazik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bak Gör', 'bak-gor-necat-necdet-demircan-tun9i', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bakıyorsun

Göremiyorsun

Oysa ayrıntıda gizlidir mutluluk

Maalesef

Sezemiyorsun

Altı his

Beş duyu

Ne kadar soğuk değil mi

Kör kuyunun karanlık suyu? 

Okumazsan haritayı

Bulamazsın patikayı

Bak, ama gör

Şaşırma pusulayı

Ne sağdadır

Ne de solda

Gör gün ışığını

Her şeysenin gibi tam ortada

Cansın

Canansın

Minnacık bir insansın

Göremezsen doğruyu

Zerresin

Tozsun

Hiç bir işe yaramazsın...', 'Bakıyorsun Göremiyorsun Oysa ayrıntıda gizlidir mutluluk Maalesef Sezemiyorsun Altı his Beş duyu Ne kadar soğuk değil mi Kör kuyunun karanlı...', ARRAY['Türk Edebiyatı','Şiir','Necat Necdet Demircan']::text[], 8.5, '{"poet":"Necat Necdet Demircan","poet_slug":"necat-necdet-demircan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bak-gor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tümden Sev', 'tumden-sev-necat-necdet-demircan-lnzdj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Taksitli sevip

Borç kaygısında olmaktansa

Tümden sev

Bir çırpıda

Ya batarsın

Ya yüzmeyi öğrenir

Kıyıya çıkarsın

Azar azar bölme kalbini

Topla

Toplardamardan yakala

Pervasızca

Atardamardan çık

Takma kimseleri

Umursama

Sevgiden başka kapı arama

Habersiz örülen duvarları yık

Bekleme

Bekletirler

Tümden öde hesabını

Özeti gelmesin adresine

Uzat ayaklarını

Okşa saçlarını...', 'Taksitli sevip Borç kaygısında olmaktansa Tümden sev Bir çırpıda Ya batarsın Ya yüzmeyi öğrenir Kıyıya çıkarsın Azar azar bölme kalbini Topl...', ARRAY['Türk Edebiyatı','Şiir','Necat Necdet Demircan']::text[], 8.5, '{"poet":"Necat Necdet Demircan","poet_slug":"necat-necdet-demircan","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/tumden-sev-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Silinir İzler', 'silinir-i-zler-necat-necdet-demircan-vooga', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Issız

Ağaçların ortasında

Çam çıraları yanmakta

Siluetleri düşer

Elele bir çiftin

Mahsur kalmış yürekleri

İçinde

Binlerce bilinmeyen engelin

İs kokusu parfümleri

Buram buram yayılır uzaklara

Göl kıyısı akşamlar

Sular vurur yavaşça ayaklara

Parmaklar uzaklaşır

Gün ışığı resimlerini çizmez

Ortadan bölünür bir aşk ikiye

Yavaşça kaybolur

Suçlu hisseder kendini kelebek

Narin bacaklar koşar tepelere

Ezilmekten usanmış çimler

Papatya kendince boynunu büker

Usulca bir karanlık çöker

Silinir aniden tüm izler...', 'Issız Ağaçların ortasında Çam çıraları yanmakta Siluetleri düşer Elele bir çiftin Mahsur kalmış yürekleri İçinde Binlerce bilinmeyen engelin...', ARRAY['Türk Edebiyatı','Şiir','Necat Necdet Demircan']::text[], 8.5, '{"poet":"Necat Necdet Demircan","poet_slug":"necat-necdet-demircan","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/silinir-izler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Farkına Vardığında', 'farkina-vardiginda-banu-aka-msb51', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hala farkında değilsin, değil mi? 

Yüzüme baktığında

Gördüğünün

Ben olmadığımın.

Oysa 

Ben uzaklara gittim

O gece.

Gözlerim kaybettiğinde gülüşünü

Cam kırıkları dolduğunda kalbime

Ve sen içinde kaybolduğunda.

Sessizce, hep yaptığım gibi 

Senin zamanının gelmesini beklerim

Yeniden gözlerim gözlerine gülümser 

Adını söylerken içim titrer 

Sanıyorsun değil mi? 

Farkına vardığında

Yanıldığının 

Benden daha çok şaşıracaksın.', 'Hala farkında değilsin, değil mi?  Yüzüme baktığında Gördüğünün Ben olmadığımın. Oysa  Ben uzaklara gittim O gece. Gözlerim kaybettiğinde gü...', ARRAY['Türk Edebiyatı','Şiir','Banu Aka']::text[], 8.5, '{"poet":"Banu Aka","poet_slug":"banu-aka","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/farkina-vardiginda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bad-ı Sabaya Sorsunlar', 'bad-i-sabaya-sorsunlar-kul-himmet-7lydc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bad-ı sabaya sorsunlar

Canan illeri kandedir

Görenler haber versinler

Canan illeri kandedir

Zikrederim aklım ermez

Yürek kaynar taşar durmaz

Görenler de haber vermez

Canan illeri kandedir

Bir bahrım kaynayup taştım

Mevce vurup hadden aştım

Diyar-ı gurbete düştüm

Canan illeri kandedir

Derviş Himmet eder ahi

Göz yaşı döker günahı

Acap görür mü ol mahı

Canan illeri kandedir', 'Bad-ı sabaya sorsunlar Canan illeri kandedir Görenler haber versinler Canan illeri kandedir Zikrederim aklım ermez Yürek kaynar taşar durmaz...', ARRAY['Türk Edebiyatı','Şiir','Kul Himmet']::text[], 8.5, '{"poet":"Kul Himmet","poet_slug":"kul-himmet","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bad-i-sabaya-sorsunlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bizi Bu Sevdaya Salan', 'bizi-bu-sevdaya-salan-kul-himmet-pmidv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bizi bu sevdaya salan

Kendi cenab-ı Allah''tır

Bu sevdaya gönül veren

İşi gücü eyvallahtır

Eyvallahı bilen kişi

Her dem artar aşkı cuşu

Rasül''ün bindiği taşı

Hala durur muallaktır

Bir sözüm vardır tutana 

Er odur Hak''tan utana

Kul olmuşuz Pir Sultan''a

Eşiği de kıblegahtır

Er odur ki Hak''tan öğe 

Desti damanına değe

Benzemez ağaya beye

Alı şah bir utu şahtır

Dest-ü dameni salmanam 

Cevhersiz göle dalmanam

Kırklar saili Selman''am

İşim gücüm şey''ullahtır

Kul Himmel''im okur yazar 

Şu cihanı ele gezer

Hak''tan bize oldu nazar

Bu bir sırr-ı sırr''ullahtır', 'Bizi bu sevdaya salan Kendi cenab-ı Allah''tır Bu sevdaya gönül veren İşi gücü eyvallahtır Eyvallahı bilen kişi Her dem artar aşkı cuşu Rasül...', ARRAY['Türk Edebiyatı','Şiir','Kul Himmet']::text[], 8.5, '{"poet":"Kul Himmet","poet_slug":"kul-himmet","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bizi-bu-sevdaya-salan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çünkü Yandı Aşk Odu Kül Olmaktır Muradım', 'cunku-yandi-ask-odu-kul-olmaktir-muradim-kul-himmet-aqgq2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Çünkü yandı aşk odu kül olmaktır muradım

Düşüp ayak altına yol olmaktır muradım

İşbu kesretten geçip vahdet iline uçup

La-mekana yol açıp çöl olmaktır muradım

Sa''y ile duruşunca yar ile görüşünce 

Ummane erişince göl olmaktır muradım

Bakmam nefsin alına aldanmam akvaline

Gülzar-ı aşk dalına gül olmaktır muradım

Himmeti''ye sorana dost yoluna varana 

Hak''tan haber verene kul olmaktır muradım', 'Çünkü yandı aşk odu kül olmaktır muradım Düşüp ayak altına yol olmaktır muradım İşbu kesretten geçip vahdet iline uçup La-mekana yol açıp çö...', ARRAY['Türk Edebiyatı','Şiir','Kul Himmet']::text[], 8.5, '{"poet":"Kul Himmet","poet_slug":"kul-himmet","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/cunku-yandi-ask-odu-kul-olmaktir-muradim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dün Gece Seyrimde Bir Şara Vardım', 'dun-gece-seyrimde-bir-sara-vardim-kul-himmet-q3zon', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dün gece seyrimde bir şara vardım

Niyaz ile kapıları açılır

Laleli sünbüllü bağını gördüm

Bülbül öter gonce güller seçilir

Pazarında gül alırlar satarlar 

Koklaşuban canı cana katarlar

Gerçekleri bir kıl ile yederler

Mü''minlere hulle donu biçilir

Dallarında baharları yazılı 

Yaprakları bir sıraya dizili

Meleşirler kurbanları kuzulu

Canlar bağışlanır kandan geçilir

Gül kokusu Muhammed''in teridir 

Gönlü saf olanlar Hakk''ın yaridir

Aşıka ma''şukun bergüzarıdır

Sevdalar nasipler nurlar saçılır

Bu şar Kul Himmet''im erenler şarı 

Bu şarda satarlar erenler varı

Bu şarın adı var gönül pazarı

Engurlar ezilir meyler içilir', 'Dün gece seyrimde bir şara vardım Niyaz ile kapıları açılır Laleli sünbüllü bağını gördüm Bülbül öter gonce güller seçilir Pazarında gül alı...', ARRAY['Türk Edebiyatı','Şiir','Kul Himmet']::text[], 8.5, '{"poet":"Kul Himmet","poet_slug":"kul-himmet","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/dun-gece-seyrimde-bir-sara-vardim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düştüm Yine Bir Derde', 'dustum-yine-bir-derde-kul-himmet-egrm1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Düştüm yine bir derde

Gönlüm niçin eğlenmez

Kararım yok bu yerde

Gönlüm niçin eğlenmez

Yarabbî sen kıl yari

Cemalin görsem bari

Dün ü gün edip zari

Gönlüm niçin eğlenmez

Zînet sevdası değil

Şöhret gavgası değil

İzzet davası değil

Gönlüm niçin eğlenmez

Müminim şükrederim

Daima fikrederim

Her zaman zikrederim

Gönlüm niçin eğlenmez

Himmet bir aşık kuldur

Bu yol bir acep yoldur

Halimi bilen oldur

Gönlüm niçin eğlenmez', 'Düştüm yine bir derde Gönlüm niçin eğlenmez Kararım yok bu yerde Gönlüm niçin eğlenmez Yarabbî sen kıl yari Cemalin görsem bari Dün ü gün ed...', ARRAY['Türk Edebiyatı','Şiir','Kul Himmet']::text[], 8.5, '{"poet":"Kul Himmet","poet_slug":"kul-himmet","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/dustum-yine-bir-derde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nazlı ya', 'nazli-ya-hekim-coskun-hgcsv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'bir anlıkta olsan

sana baktığımda bir bütün

arkamı döndüğümde hüzün

yüzünü asma 

sana gülücükler çok yakışıyor 

seni mutlu gördüğüm de 

ayaklarım yerden kesilir

bir kuş hafifliğiyle uçmak isterim

bazen de balık olur

özgürce dolaşırım hülyamda

sen nazlım

uzaklarda bir yerde de olsan

kalbimin en tatlı kızısın

beni sevdiğini söyle ne olur

kızma bana

çok yakın oldum yaşama

ve de ölüme

kollarımda ölüm izleri

her an gidebilmek korkusuydu

beni vurdumduymaz yapan

sorumsuzsam

sorumsuzca yaşadıysam

biraz da tembellikten mi ne? 

sana zaman ayıramadım

aslında bende bilmiyorum

bir çok soru işaretleriyle uğraşmaktan bıktım

çok bencilde davrandığım oldu

çok yalanlarda söyledim

seni kaybetmemek uğruna

sen inanmasan da dinledin

yetmedi

bin dereden su taşıdım

seni inandıramadım ya

olsun

yine de sen her şeye inanma

gördüklerin değil

duyduklarında yetsin sana

sen yaşamı sorguladıkça

ve beni

senden gurur duymaktan başka ne yapabilirim

seni çok seviyorum

sevgim seni taciz etse de

yanımda olsan

seni mıncıklamaya devam edecek

tüm öfkeni seveceğim

kalbimin en tatlı fitnecisi

güzellikle olmazsa da

özellikle seni çok ama çok seviyorum', 'bir anlıkta olsan sana baktığımda bir bütün arkamı döndüğümde hüzün yüzünü asma  sana gülücükler çok yakışıyor  seni mutlu gördüğüm de  ayak...', ARRAY['Türk Edebiyatı','Şiir','Hekim Coşkun']::text[], 8.5, '{"poet":"Hekim Coşkun","poet_slug":"hekim-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/nazli-ya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eğer Dosttan Belli Haber Sorarsan', 'eger-dosttan-belli-haber-sorarsan-kul-himmet-y6l56', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Eğer dosttan belli haber sorarsan

Sana haber versin seher yelleri

Dost illeri kande deyu ararsan

Sana haber versin seher yelleri

Baharı açıldı mı güllerinin

Feryadı var mıdır bülbüllerinin

Doğru yolun bilir dost illerinin

Sana haber versin seher yelleri

Aşkımın ateşi tutuşup yandı

Dud-i ahım feleklere boyandı

Kandedir der isen güzel efendi

Sana haber versin seher yelleri

Derviş Himmet kendin hayran eylemiş

Yıkıp suret mülkün vîran eylemiş

Canan illerini seyran eylemiş

Sana haber versin seher yelleri', 'Eğer dosttan belli haber sorarsan Sana haber versin seher yelleri Dost illeri kande deyu ararsan Sana haber versin seher yelleri Baharı açıl...', ARRAY['Türk Edebiyatı','Şiir','Kul Himmet']::text[], 8.5, '{"poet":"Kul Himmet","poet_slug":"kul-himmet","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/eger-dosttan-belli-haber-sorarsan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gül Bittiği Yeri Bilirim Dersin', 'gul-bittigi-yeri-bilirim-dersin-kul-himmet-zh27e', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gül bittiği yeri bilirim dersin

Bilir misin benlik şeytana düştü

Cevahir madenin bulurum dersin

Cevahir bulanlar ummana düştü

Ben Ali''yi gördüm mahbub çağında 

Selman''ın çiğninde yolun sağında

Cennetten içeri firdevs bağında

Bülbül figan eyler gülşene düştü

Selman''ın çiğninde bir oğlan geldi 

Destur dedi ele bir deste aldı

Muhammed terini gül ile sildi

Ol zaman kokusu insana düştü

Muhammed''i gören canlar ağladı 

Sel sel oldu çeşmim yaşı çağladı

Cebrail Habib''in belin bağladı

Kırkların cem''inde erkana düştü

Kırklar geldi her çiçekten derdiler 

Koklayıban yüzlerine sürdüler

Her destesin bir güzele verdiler

Gül Muhammed nerkis Selman''a düştü

Cennetin kapısın kırklar açtılar 

Tohumunu yeryüzüne saçtılar

Bir üzümü şerbet edip içtiler

Size mescid bize meyhane düştü

Kul Himmet üstadım dilek diledi 

Seyyah olup şu alemi eledi

Arafat dağında bir koç meledi

İsmail önünce kurbana düştü', 'Gül bittiği yeri bilirim dersin Bilir misin benlik şeytana düştü Cevahir madenin bulurum dersin Cevahir bulanlar ummana düştü Ben Ali''yi gör...', ARRAY['Türk Edebiyatı','Şiir','Kul Himmet']::text[], 8.5, '{"poet":"Kul Himmet","poet_slug":"kul-himmet","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/gul-bittigi-yeri-bilirim-dersin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Mecnun Gibi', 'bir-mecnun-gibi-tayyip-sag-kg50c', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Mazinin yıpranmış sayfalarında,

Kendimi aradım bir mecnun gibi,

Gördüm ki dünümden çok şey değişmiş,

Oturup düşündüm bir mecnun gibi.

Sorsan beni o seneler hatırlar,

Alıp bu günlere getiren yıllar,

İçinde ne gerçek ne yalanlar var,

Oturup düşündüm bir mecnun gibi.

Doğru söze bağlamışım özümü,

Yalan dersem kör etsinler gözümü,

Bir gün kara toprak örter üstümü,

Oturup düşündüm bir mecnun gibi.

Dost dediğin yalan dolan çıkmaz mı,

Böyle dosttan gönül erken bıkmaz mı,

Dost hançeri çok acıdır yakmaz mı,

Oturup düşündüm bir mecnun gibi.

Tayyib''in ettiği ne sitem ne naz,

Baharı görmedim kışlarım ayaz,

Genç yaşımda oldu, saçım bembeyaz,

Oturup düşündüm bir mecnun gibi.

    06.01.2003', 'Mazinin yıpranmış sayfalarında, Kendimi aradım bir mecnun gibi, Gördüm ki dünümden çok şey değişmiş, Oturup düşündüm bir mecnun gibi. Sorsan...', ARRAY['Türk Edebiyatı','Şiir','Tayyip Sağ']::text[], 8.5, '{"poet":"Tayyip Sağ","poet_slug":"tayyip-sag","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bir-mecnun-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül Kuşu Eski Yuvadan Uçtu', 'gonul-kusu-eski-yuvadan-uctu-kul-himmet-0x96h', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gönül kuşu eski yuvadan uçtu

Giden gelsin bizimle dost iline

Katerler bağlandı kafile göçtü

Giden gelsin bizimle dost iline

Aşk eseri olan karar bağlamaz 

Yüreğinde derd olmayan ağlamaz

Bizi bu yerlerde kimse eğlemez

Giden gelsin bizimle aşk iline

Bir garibim adım sanım anılmaz 

Yüreğimde yaram vardır onulmaz

Aşk deryası cuş eyledi yenilmez

Giden gelsin bizimle aşk iline

Leyl-ü nehar akar çeşmimin yaşı 

Dost yoluna koyup can ile başı

Aşk ile geçelim dağ ile taşı

Giden gelsin bizimle aşk iline

Derviş Himmet aydır onu bilenler 

Medhin okur anda varıp gelenler

Delilimiz oldu pirler erenler

Giden gelsin bizimle aşk iline', 'Gönül kuşu eski yuvadan uçtu Giden gelsin bizimle dost iline Katerler bağlandı kafile göçtü Giden gelsin bizimle dost iline Aşk eseri olan k...', ARRAY['Türk Edebiyatı','Şiir','Kul Himmet']::text[], 8.5, '{"poet":"Kul Himmet","poet_slug":"kul-himmet","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gonul-kusu-eski-yuvadan-uctu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seyran Edip Şu Alemi Gezerken', 'seyran-edip-su-alemi-gezerken-kul-himmet-h6j2i', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Seyran edip şu alemi gezerken

Uğradım gördüm bir bölük canları

Cümlesinin erkanı bir yolu bir

Mevla''m bir nurdan yaratmış anları

Cümle bir mürşide demişler beli 

Tesbihleri Allah Muhammed Ali

Meşrebi Hüseyni ismi Alevi

Muhammed Ali''ye çıkar yolları

Durakları irfan bağıyla bostan 

Silinmiş kalbleri gümandan pastan

Cümlenin muradı bir fidan dosttan

Arı gibi sadalaşır ünleri

Sıratı mizanı bunda geçmişler

Varlık benlik kal''asını yıkmışlar

Al giymişler yas donundan çıkmışlar

Gece kadar gündüz bayram günleri

Cennet istemezler azm-i didare

Ne korku çekerler tamuya nare

Secde kılmaktan geçmişler divare

Didare karşı tutmuşlar yönleri

Bir nefeste bir imana uymuşlar 

Birinin niyazın bine saymışlar

Kaynayıban kaptan kaba konmuşlar

Şah Hüseyn uğruna akmış kanları

Kul Himmet''im gerçeklerin bu meydan 

Özün kurtarmışlar sıfat-ı şerden

Hep içmişler Kırklar içtiği meyden

Haber duymuş dost ilinden canları', 'Seyran edip şu alemi gezerken Uğradım gördüm bir bölük canları Cümlesinin erkanı bir yolu bir Mevla''m bir nurdan yaratmış anları Cümle bir m...', ARRAY['Türk Edebiyatı','Şiir','Kul Himmet']::text[], 8.5, '{"poet":"Kul Himmet","poet_slug":"kul-himmet","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/seyran-edip-su-alemi-gezerken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uyan Be Hey Gaafil Hab-ı Gafletten', 'uyan-be-hey-gaafil-hab-i-gafletten-kul-himmet-l8xei', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Uyan be hey gaafil hab-ı gafletten

Ömrün geldi geçti haberin var mı

Bir haber aldın mı sırr-ı vahdetten

Murg-ı canın uçtu haberin var mı

Bu dar-ı rıhlettir bunda kalınmaz 

Hem sonu fenadır murad alınmaz

Kafile kalkıcak geri dönülmez

Kervanbaşı göçtü haberin var mı

Azığın var mıdır yola gitmeğe 

Döşeğin hazır mı varıp yatmağa

Ejderler gibi dem çekip yutmağa

Yerler ağzın açtı haberin var mı

Ma''sıyet yükünü aldın boynuna 

Hiç ölüm korkusu gelmez aynına

Felek birkaç arşın bezi eğnine

Yakasız don biçti haberin var mı

Derviş Himmet senden evvel gelenler 

Kimisi kul kimi sultan olanlar

Dünya benim mülküm deyip yelenler

Ecel canım içti haberin var mı', 'Uyan be hey gaafil hab-ı gafletten Ömrün geldi geçti haberin var mı Bir haber aldın mı sırr-ı vahdetten Murg-ı canın uçtu haberin var mı Bu ...', ARRAY['Türk Edebiyatı','Şiir','Kul Himmet']::text[], 8.5, '{"poet":"Kul Himmet","poet_slug":"kul-himmet","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/uyan-be-hey-gaafil-hab-i-gafletten-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tiryaki', 'tiryaki-tayyip-sag-u4bit', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Nefes nefes savurduğun dumanla,

Sağlığını yakıyorsun tiryaki,

Soluğun kesilmiş rengin sararmış,

Derin derin bakıyorsun tiryaki.

Canından çok kıymetlimi içtiğin,

Sinsi bir düşmandır paha biçtiğin,

Bir zaman koşarak gelip geçtiğin,

Yollarda düşersin bir gün tiryaki.

İçkiyi tütünü sakın dost sanma,

Bir anlık keyfine kanıp aldanma,

Bir çare diyerek sarıldın amma,

Kendini elinle yaktın tiryaki.

    25.02.2003', 'Nefes nefes savurduğun dumanla, Sağlığını yakıyorsun tiryaki, Soluğun kesilmiş rengin sararmış, Derin derin bakıyorsun tiryaki. Canından çok...', ARRAY['Türk Edebiyatı','Şiir','Tayyip Sağ']::text[], 8.5, '{"poet":"Tayyip Sağ","poet_slug":"tayyip-sag","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/tiryaki-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vakt-i Seherde', 'vakt-i-seherde-kul-himmet-mtp9h', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Vakt-i seherde

Açılıp perde

Düştüğüm yerde

Derman sendendir

Düşmüşüm kaldır

Minnetim oldur

Ağlarım güldür

Derman sendendir

Benim bîçare

Kaldım avare

Yürek pür yare

Derman sendendir

Nefs-i zalimi

Gözle halimi

Sundum elimi

Derman sendendir

Derviş Himmet''e

Çare vuslata

Derd ü firkate

Derman sendendir', 'Vakt-i seherde Açılıp perde Düştüğüm yerde Derman sendendir Düşmüşüm kaldır Minnetim oldur Ağlarım güldür Derman sendendir Benim bîçare Kald...', ARRAY['Türk Edebiyatı','Şiir','Kul Himmet']::text[], 8.5, '{"poet":"Kul Himmet","poet_slug":"kul-himmet","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/vakt-i-seherde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yine Bir Sevdaya Düştüm', 'yine-bir-sevdaya-dustum-kul-himmet-2v9mm', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yine bir sevdaya düştüm

Aşkın elinden elinden

Yine umman olup taştım

Aşkın elinden elinden

Ateş-i aşk ile yandım

Fani cihandan usandım

Gûyiya Mecnun''a döndüm

Aşkın elinden elinden

Seherlerde ağlayalım

Dertli sînem dağlayalım

Sular gibi çağlayalım

Aşkın elinden elinden

Özümü deryaya saldım

Ona gavvâs olup daldım

Pîrlikte hayrette kaldım

Aşkın elinden elinden

Derviş Himmet biçaredir

Cihan içre avaredir

Hem yüreği pür yaredir

Aşkın elinden elinden', 'Yine bir sevdaya düştüm Aşkın elinden elinden Yine umman olup taştım Aşkın elinden elinden Ateş-i aşk ile yandım Fani cihandan usandım Gûyiy...', ARRAY['Türk Edebiyatı','Şiir','Kul Himmet']::text[], 8.5, '{"poet":"Kul Himmet","poet_slug":"kul-himmet","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yine-bir-sevdaya-dustum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eğer Din Bâbından Haber Sorarsan', 'eger-din-b-bindan-haber-sorarsan-kul-himmet-ri2u4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Eğer din bâbından haber sorarsan 

Söyle kelâmını bildir efendim 

Sual eyle ihsân olsun kelâmlar 

Bilemezsem hâlim nedir efendim 

Bir günün farzını on yedi bildim 

Yiğirmi sünneti üç vitir kıldım 

Sualine cevap vermeye geldim 

Veremezsem döv de öldür efendim 

Sabah dört öğlen on belli beyândır 

İkindi sekizdir deme ziyândır 

Akşam beş yats''on üç vitir tamamdır 

Bunu da böylece kıldım efendim 

Altmış altı er kaleyi boyladım 

Altı yüz teravihi hesap eyledim 

Ben bir divaneyim böyle söyledim 

Buncağız kusura kalma efendim 

Kıyas et meydandan geri kalırım 

Aç gözünü sana hoca olurum 

Bir yıllık namazı ezber bilirim 

Var senden kaçan kördür efendim 

Beş bin yüz yirmi farzıdır heman 

Yedi bin iki yüz sünnettir tamam 

İncil''le Zebur Hak delili Kur''an 

O da bir sırdır ermen efendim 

Seyyid gibi sen secdeye oturmuş 

Köylü sana yağlı pilav getirmiş 

Bana sen de neden sual sorarsın 

Balı kıymağı da yersin efendim 

Sözü m''olur sencileyin özü çürüğün 

Yüzün görme yüzü gözü buruğun 

La bak aşağı indirmişsin sarığın 

Korkarım başında güldür efendim 

Herhalde ilerü gelemez deyü 

Sualime cevap veremez deyü 

Kul Himmet ile baş edemez deyü 

Korkarım el sana güler efendim', 'Eğer din bâbından haber sorarsan  Söyle kelâmını bildir efendim  Sual eyle ihsân olsun kelâmlar  Bilemezsem hâlim nedir efendim  Bir günün f...', ARRAY['Türk Edebiyatı','Şiir','Kul Himmet']::text[], 8.5, '{"poet":"Kul Himmet","poet_slug":"kul-himmet","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/eger-din-babindan-haber-sorarsan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey Aşıki Saramadın Yaremi', 'ey-asiki-saramadin-yaremi-kul-himmet-l2p3n', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ey âşıki saramadın yâremi 

Yâreme em olup merhem çalasın 

Yarem deşilmiştir sarılmaz madem 

Arayıp da hekimini bulasın 

Dört kapı açıldı hangisi vardır 

Bu manaya ermek hayli hünerdir 

Deryanın dibinde kaç şehir vardır 

Çarşısını pazarını bilesin 

Mehdî çıkmış diye tellâl bağırdı 

Bir teknesi vardır kırklar yoğurdı 

On iki kız sekiz oğlan doğurdu 

Onların ne olduğunu bilesin 

Âşıkların sözlerine has derim 

Muhammed''i gördüm Ali dost derim 

Yedi bin yedi yüz âyet isterim 

Yüz on daha vardır onu bilesin 

Benim sevdiceğim Takî Nakî''dir 

Dost bağında bülbüller şakıtır 

Yüz kardaşın hocası var okutur 

Onlarıñ da ne olduğun bilesin 

Düzüm düzüm olmuş yüzünün beni 

Açılmıştır gül benzinde yanağı 

Sar''öküzün alnındaki beneği 

Kanadında ne yazılı bilesin 

Var bul bir delilin yaka fenerin 

Kaç hamail vardır şems ü kamerin 

Sar''öküzün bastıcağı mermerin 

Direğinde ne olduğun bilesin 

Âriflerin sözü hilaf yazılmaz 

Güher olmayınca hatem düzülmez 

Bir kız vardır hergiz kuşağı çözülmez 

Anasının kande olduğun bilesin 

Dinleyeyim Kul Himmet''in sözlerin 

Onda gördüm yedilerin izlerin 

Muhammed''in koynundaki kızların 

Huri midir peri midir bilesin', 'Ey âşıki saramadın yâremi  Yâreme em olup merhem çalasın  Yarem deşilmiştir sarılmaz madem  Arayıp da hekimini bulasın  Dört kapı açıldı han...', ARRAY['Türk Edebiyatı','Şiir','Kul Himmet']::text[], 8.5, '{"poet":"Kul Himmet","poet_slug":"kul-himmet","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/ey-asiki-saramadin-yaremi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu son gecem', 'bu-son-gecem-mehmet-ali-suzen-7cgl1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Senin ile bu son gecem

Alfebemde ki ilk hecem

Beynimdeki tek düşüncem

Seni asla bırakamam derken

Elveda diyerek çekip giderken

Bu benim son gecem

Tüm varlığa ve yokluğa,

seninle ve sensizliğe elveda

Seni seviyorum deyişin 

Bu yalandı söyleyişin

ELVEDA

Sevmek sevdim diyebilmek her zorluğa göğüs germek

yolunda'' onu kazanmak uğruna her düşünceye her fikre

her duruşa açlığa,tokluğa ve sensiz olunmayan yokluğa

katlanmayı bilmektir istemektir,derinden, en içerden 

yanarcasına şimdi sende yanarsın eğer doğruysa

DÜŞLERİM', 'Senin ile bu son gecem Alfebemde ki ilk hecem Beynimdeki tek düşüncem Seni asla bırakamam derken Elveda diyerek çekip giderken Bu benim son ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Süzen']::text[], 8.5, '{"poet":"Mehmet Ali Süzen","poet_slug":"mehmet-ali-suzen","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bu-son-gecem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gaipten Haber Getirdin', 'gaipten-haber-getirdin-kul-himmet-omfty', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gaipten haber getirdin

Mihman hoş geldin hoş geldin

Bizi sohbete kandırdın

Mihman hoş geldin hoş geldin

İki bade birden içtik

Muhabbet kapısın açtık

Çok şükür didar görüştük

Mihman hoş geldin hoş geldin

Erliğini ispat ettin

Gevher alıp gevher sattın 

Üstümüze yoluğ attın

Mihman hoş geldin hoş geldin

Kur''ağaçta güler biter

Dalında bülbüller öter

Efendim birgüzar yeter

Mihman hoş geldin hoş geldin

Eyle Kul Himmet''im eyle

Pirim destur versin söyle

İn eşiğe niyaz eyle

Mihman hoş geldin hoş geldin', 'Gaipten haber getirdin Mihman hoş geldin hoş geldin Bizi sohbete kandırdın Mihman hoş geldin hoş geldin İki bade birden içtik Muhabbet kapıs...', ARRAY['Türk Edebiyatı','Şiir','Kul Himmet']::text[], 8.5, '{"poet":"Kul Himmet","poet_slug":"kul-himmet","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gaipten-haber-getirdin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel Gönül Kimsenin Aybına Bakma', 'gel-gonul-kimsenin-aybina-bakma-kul-himmet-tydfc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gel gönül kimsenin aybına bakma 

Hazer kıl sevdiğim değme gönüle 

Arif ol cihanda bir gönül yıkma 

Hazer kıl sevdiğim değme gönüle 

Daim aşk atına bin de atlı gez 

Edep öğren erkan öğren otlu gez 

Gönül yıkma halk içinde tatlı gez 

Sakın ey sevdiğim değme gönüle 

Yoldaş eyle iman gibi dostunu 

Amel kazan aramazlar aslını 

Turap ol ki çiğnesinler üstünü 

Hâk ol ey sevdiğim değme gönüle 

Cihad eyle ki günahların tartasın 

Bir amel kazan ki Hakk''a yetesin 

Şar gibi her gördüğün örtesin 

Pir ol ey sevdiğim değme gönüle 

Kul Himmet dilimde zikrim Muhammed 

Aşk dolusun içtim Hüda''ya minnet 

Dinar ile satın alınmaz cennet 

Hazer kıl sevdiğim değme gönüle', 'Gel gönül kimsenin aybına bakma  Hazer kıl sevdiğim değme gönüle  Arif ol cihanda bir gönül yıkma  Hazer kıl sevdiğim değme gönüle  Daim aşk...', ARRAY['Türk Edebiyatı','Şiir','Kul Himmet']::text[], 8.5, '{"poet":"Kul Himmet","poet_slug":"kul-himmet","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gel-gonul-kimsenin-aybina-bakma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eğer Ben Fakire Haber Sorarsan (Gelirim)', 'eger-ben-fakire-haber-sorarsan-gelirim-kul-himmet-uvcn7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Eğer ben fakire haber sorarsan

Ya ben nerde idim nerden gelirim

Yok değildim şu cihanda var idim

Pire hizmet ettim pirden gelirim

Addürrezzak gibi Hızır''a yettim

Selman gibi eski dini terkettim

Doksan bin küffarı Müslüman ettim

Tecella dağından Tur''dan gelirim

İsa ile bile idim havada

Musa ile bile idim duada

Ferhat ile külünk çaldım kayada

Attım külüngümü zordan gelirim

Nuh Peygamber gibi gemiler çattım

İletip deryayı ummana kattım

Yusuf ile bile kuyuda yattım

Yakup ile ah u zardan gelirim

Kul Himmet''im bir olalım er ile

Belki bizim kısmetimiz verile

Üçler makamında yediler ile

Kırkların olduğu yerden gelirim', 'Eğer ben fakire haber sorarsan Ya ben nerde idim nerden gelirim Yok değildim şu cihanda var idim Pire hizmet ettim pirden gelirim Addürrezza...', ARRAY['Türk Edebiyatı','Şiir','Kul Himmet']::text[], 8.5, '{"poet":"Kul Himmet","poet_slug":"kul-himmet","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/eger-ben-fakire-haber-sorarsan-gelirim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hey Gaziler Şunda Günâhkâr Oldum', 'hey-gaziler-sunda-gun-hk-r-oldum-kul-himmet-iqvhe', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hey gaziler şunda günâhkâr oldum 

Medet pirim imdat eyle talibe 

Aradım günâhım özümde buldum 

Medet pirim imdat eyle talibe 

Varıp kırklar kapısından çağıram 

Hem çağırıp hemi lebbeyk diyen 

Posttan kalkıp mührü önüne koyan 

Medet pirim imdat eyle talibe 

Arza yetip enbiyaya erenler 

Yemen''de taç vurup hırka giyenler 

Zulmette kalmaz sizi sevenler 

Medet pirim imdat eyle talibe 

Çağırak doksan bin ere şehide 

Mağripten maşrıka cümle işite 

Hacı Bektâş Velî''den imdat yetişe 

Medet pirim imdat eyle talibe 

Sen Ali sırrısın himmetin yete 

Fatıma kızındır Muhammed atan 

Onları ayırmak yine bir hata 

Medet pirim imdat eyle talibe 

Eyyüb''ün kurdunu döküp sağ eden 

İbrahim''in yerin çayır su eden 

Kara don giyip de ağ deveyi yeden 

Medet pirim imdat eyle talibe 

Hasan Hüseyn şebber-şubber kulaktır 

İmam Zeynel İmam Bakır yanaktır 

İmam Caferhüsn hecesinde ayandır 

Medet pirim imdat eyle talibe 

Musa Kâzım Rıza kalemdir kaştır 

Takî Nakî çeşmi onlara eştir 

Hasanü''l-Askerî dehanda diştir 

Medet pirim imdat eyle talibe 

Mehdî dedim masum pake yetirdim 

Mürvet dedim el pençeye oturdum 

On ik''İmamlar''a iman getirdim 

Medet pirim imdat eyle talibe 

Kul Himmet''''im eydür var özün öldür 

Cümle eksikliğin mürşîde bildir 

Engür şerbetini tuttuğum eldir 

Medet pirim imdat eyle talibe', 'Hey gaziler şunda günâhkâr oldum  Medet pirim imdat eyle talibe  Aradım günâhım özümde buldum  Medet pirim imdat eyle talibe  Varıp kırklar ...', ARRAY['Türk Edebiyatı','Şiir','Kul Himmet']::text[], 8.5, '{"poet":"Kul Himmet","poet_slug":"kul-himmet","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/hey-gaziler-sunda-gunahkar-oldum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalk Karındaş Yola Gidek', 'kalk-karindas-yola-gidek-kul-himmet-m6m0i', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kalk karındaş yola gidek 

Hak yoldan öte mi dersin 

Murad u maksuda erincek 

Bu söze hata mı dersin 

Ârif olan kalleş olan 

Bellidir meyli boş olan 

Vefâsız yoldaş olan 

Menzile yeter mi dersin 

Sırrını verme kalleşe 

Kalbi çürük meyli boşa 

kapabilmem düşse taşa 

Yetmeden tutar mı dersin 

Sırrını verme hayrata 

Senden alır gider yada 

Damızlık koysan çiğ süde 

Pişmeden tutar mı dersin 

Kul Himmet der çoşmayan 

Aşk kazanında pişmeyen 

Burada Hakk''a ulaşmayan 

Orada yanar mı dersin', 'Kalk karındaş yola gidek  Hak yoldan öte mi dersin  Murad u maksuda erincek  Bu söze hata mı dersin  Ârif olan kalleş olan  Bellidir meyli b...', ARRAY['Türk Edebiyatı','Şiir','Kul Himmet']::text[], 8.5, '{"poet":"Kul Himmet","poet_slug":"kul-himmet","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kalk-karindas-yola-gidek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pare Pare Yalan Dünya', 'pare-pare-yalan-dunya-kul-himmet-how71', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Pare pare yalan dünya 

Yalan dünya değil misin 

Hasan ile Hüseyin''i 

Alan dünya değil misin 

Ali bindi Düldül ata 

Âşık dayanır firkate 

Boz kurt ile kıyamete 

Kalan dünya değil misin 

Ali''nin Düldül''ünü alıp 

Arslanını dağa salıp 

Yedi kere üste kalan 

Dolan dünya değil misin 

Ah şu kaşa ah şu göze 

Ciğer kebap oldu köze 

Muhammed''i bir ham beze 

Saran dünya değil misin 

Yetik Kul Himmet''im yetik 

Gerçeğin eteğin tutup 

İnsan gül ot gibi bitip 

Dolan dünya değil misin', 'Pare pare yalan dünya  Yalan dünya değil misin  Hasan ile Hüseyin''i  Alan dünya değil misin  Ali bindi Düldül ata  Âşık dayanır firkate  Boz...', ARRAY['Türk Edebiyatı','Şiir','Kul Himmet']::text[], 8.5, '{"poet":"Kul Himmet","poet_slug":"kul-himmet","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/pare-pare-yalan-dunya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Derim Be Hey Sofi', 'sana-derim-be-hey-sofi-kul-himmet-1sk55', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sana derim be hey sofi 

Evvel imamınız kimdir 

Selâvat indi şanına 

Hak Muhammed Ali diyendir 

Evvelkisi İmam Hasan 

İkincisi İmam Hüseyn 

Üçüncüsü İmam Zeynel 

Dördüncüsü İmam Abidin''dir 

Beşincisi İmam Bakır 

Altıncısı İmam Cafer 

Yedincisi Musa Kâzım 

Sekizincisi Rıza''dır 

Dokuzuncu İmam Takî 

Onuncusu Ali Nakî 

On birinci Hasanü''l-Askeri 

On ikinci Mehdi sahib-zamandır 

Kul Himmet''im bakışına 

Böyle mi girdi düşüne 

İki cihân güneşine 

Pâk eyleyen Kur''an''dır', 'Sana derim be hey sofi  Evvel imamınız kimdir  Selâvat indi şanına  Hak Muhammed Ali diyendir  Evvelkisi İmam Hasan  İkincisi İmam Hüseyn  Ü...', ARRAY['Türk Edebiyatı','Şiir','Kul Himmet']::text[], 8.5, '{"poet":"Kul Himmet","poet_slug":"kul-himmet","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sana-derim-be-hey-sofi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aritmetik', 'aritmetik-hekim-coskun-7p01r', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'bir gülücükle maskeledik kinimizi

politik bir duruş uğrana

artı-emek

artı-değer

artı-sevdalarımız oldu

bir çok şey eksilse de yaşamımızdan

aritmetik

ya da matematik tüm hesaplamalar

aynı kapıya çıktı

yüzümüze kapatılan.

formülleri doğru bilsek de

sonuç hep sıfır oldu

dağ gibi birikmiş problemlerimiz uğruna

öğrendiklerimizle sınıfta kaldık

koca bir sıfırla sonlandırırken yaşamı

her şeyin bir amaaaa sı oldu

sonuçta amaa  ben ne yapabilirdim? 

bir duvarında sen

bir duvarında giz

iki duvarın birinde üstüme kapatılmış bir kapı', 'bir gülücükle maskeledik kinimizi politik bir duruş uğrana artı-emek artı-değer artı-sevdalarımız oldu bir çok şey eksilse de yaşamımızdan a...', ARRAY['Türk Edebiyatı','Şiir','Hekim Coşkun']::text[], 8.5, '{"poet":"Hekim Coşkun","poet_slug":"hekim-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/aritmetik-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeter ki GİTME', 'yeter-ki-gi-tme-tevfik-karinca-v7gss', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'bir kadın değildin sen benim için,sadece

hayatın tüm anlamlarını yüklemiştim üstüne

çok ağırdı belki sorumlulukların

belki seni öyle görmekti umudum

öyle inandırmıştım ki kendime

vazgeçmezdin sen benden

sevmiştik ve mutluyduk

gidebileceğini gördüm dün gece

sarı gülüm olsun be

bir kadın değildin sen benim için,sadece

sevdiğimsin

hem yanımda hem çok uzakta

mutluluk gülüşünde

hüzün gözlerinde

yemin ettim kendimce

ne ölüm ne ayrılık olmayacak dilimde

yeter ki gitme', 'bir kadın değildin sen benim için,sadece hayatın tüm anlamlarını yüklemiştim üstüne çok ağırdı belki sorumlulukların belki seni öyle görmekt...', ARRAY['Türk Edebiyatı','Şiir','Tevfik Karınca']::text[], 8.5, '{"poet":"Tevfik Karınca","poet_slug":"tevfik-karinca","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yeter-ki-gitme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlasam Çiçek Ağlamasam Sen..', 'aglasam-cicek-aglamasam-sen-zeynep-orcanel-dt25h', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ben üzüm bağlarından öğrendim

Kocaman bir çocuk olmasını! 

Ve ellerim bir yaprak sarmasında

Gözlerin tek başına ağlamasını! 

Ben bir pencere çiçeğiydim

Fesleğen ve yahut sardunya

Ve ellerin okşarken toprağımı

Öylece susup kalmasını! 

Ben sokak aralarında öğrendim

Yalnız çocukların,

Açılmayan pencerelerin önündeki

Ağlamayan çiçekler gibi erkenden solamasını..', 'Ben üzüm bağlarından öğrendim Kocaman bir çocuk olmasını!  Ve ellerim bir yaprak sarmasında Gözlerin tek başına ağlamasını!  Ben bir pencere...', ARRAY['Türk Edebiyatı','Şiir','Zeynep Orcanel']::text[], 8.5, '{"poet":"Zeynep Orcanel","poet_slug":"zeynep-orcanel","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/aglasam-cicek-aglamasam-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizim o saat', 'sensizim-o-saat-mehmet-ali-suzen-mr202', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kurulmuş bir saat gibi

Beni hep arayışın

İçinde bensiz zamanlaradır

Bu haykırışın

Üzülme ben hep seninleyim

Sensiz olan zamanın ötesindeyim

Terkedip gitmedim sonsuzluğa

Nedir bu haykırışın.

Hayalinde değilim

Bak gecelere gerçeğindeyim', 'Kurulmuş bir saat gibi Beni hep arayışın İçinde bensiz zamanlaradır Bu haykırışın Üzülme ben hep seninleyim Sensiz olan zamanın ötesindeyim ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Süzen']::text[], 8.5, '{"poet":"Mehmet Ali Süzen","poet_slug":"mehmet-ali-suzen","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sensizim-o-saat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pazar...', 'pazar-zeynep-orcanel-oqrl5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yine bir Pazar ve ben ilk günaydınımı 

Bir tokat gibi duvarlardan alıyorum! ..

Tanrım ellerim neden kırmızı,

Tanrım ben her pazar niye kanıyorum?', 'Yine bir Pazar ve ben ilk günaydınımı  Bir tokat gibi duvarlardan alıyorum! .. Tanrım ellerim neden kırmızı, Tanrım ben her pazar niye kanıy...', ARRAY['Türk Edebiyatı','Şiir','Zeynep Orcanel']::text[], 8.5, '{"poet":"Zeynep Orcanel","poet_slug":"zeynep-orcanel","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/pazar-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Paris, Bense Helena..', 'sen-paris-bense-helena-zeynep-orcanel-pcv0i', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yüreğim gidemezdi başka hiçbir yere,

Yangın yeriydi dalları! 

Alev topu gibi düştün

Duygularımın tam ortasına! 

Sana her gelişim bir uçurumdu! 

Anlayamazdın! 

Mutluluk hangi dağın arkasında gizliydi

Bilemiyordum! 

Bilemiyordum,

Umutlarımın tam adresini! 

Bir yangın yeri yarattın

Duygularımın tam ortasında! 

Yerle bir olmuştu hüzünlerim,

Senden öncesi sanki hiç yaşanmamış,

Yalnız senden sonrası vardı! 

Yeni bir medeniyet kurulmuştu sanki

Kalbimin bir yarısına

Sen Paris

Bense Helena! ..', 'Yüreğim gidemezdi başka hiçbir yere, Yangın yeriydi dalları!  Alev topu gibi düştün Duygularımın tam ortasına!  Sana her gelişim bir uçurumd...', ARRAY['Türk Edebiyatı','Şiir','Zeynep Orcanel']::text[], 8.5, '{"poet":"Zeynep Orcanel","poet_slug":"zeynep-orcanel","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sen-paris-bense-helena-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hazan... ''''Alex Hazan''''', 'hazan-alex-hazan-zeynep-orcanel-scwq9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gün bitti soğudu güneş,

Geldi hazan mevsimi yavaş yavaş! ..

Gökte mavi griye dönüştü

Dönüştü her şey bir puslu serinliğe! 

Bak ellerim üşüyor

Üşüyorum bu hazan mevsiminde! 

Yağmurlar hep kurudu dudaklarımın arasında,

Yaşamak neydi

Neydi ki ben yaşamak istiyordum

Üşüdüğümü bile bile! ..

Al ellerimi avuçlarına

Kader çizginin üstünde gezdir beni! 

Hayatımın en hoş manzarası

Sisli ama bozuk mavi! 

Doğur güneşleri hayat çizgimde,

Parmak uçlarıma şekerler dök! 

Tutarken bendeki seni

Sisli ama tatlı mavi! .

                                                  '''' Alex Hazan''a...''''', 'Gün bitti soğudu güneş, Geldi hazan mevsimi yavaş yavaş! .. Gökte mavi griye dönüştü Dönüştü her şey bir puslu serinliğe!  Bak ellerim üşüyo...', ARRAY['Türk Edebiyatı','Şiir','Zeynep Orcanel']::text[], 8.5, '{"poet":"Zeynep Orcanel","poet_slug":"zeynep-orcanel","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/hazan-alex-hazan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rıza Dayıcığım..', 'riza-dayicigim-zeynep-orcanel-p827w', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Nasılsa her gün yeni bir şey eriyor ellerimizde,

Yeni bir zaman,

Yeni bir yalan,

Yeni bir aşk falan! ..

Yaşlandıkça değeri artıyor yılların,

Yıllandıkça güzelleşiyor

Dilimizde şarabın,

Sende yattığın yerde güzelleşiyorsun be,

Rıza Dayıcığım! ..

İlk günaydını sen söylemişsin,

İlk yaşanan sevda da seninmiş! 

Sen varken yazılmış en güzel şarkıları zamanın,

Ve sen söylemişsin onları öylece güzel.

Kimi milatla kardeş diyor sana,

Kimi daha güneş yokken o vardı! 

Ben biliyorum be Rıza Dayı

Yirmi yediden bir çıkarınca

Geriye yirmi altı kaldı! 

İlk güzel yaş senin yaşın

Son güzel ömür senin ömrün...', 'Nasılsa her gün yeni bir şey eriyor ellerimizde, Yeni bir zaman, Yeni bir yalan, Yeni bir aşk falan! .. Yaşlandıkça değeri artıyor yılların,...', ARRAY['Türk Edebiyatı','Şiir','Zeynep Orcanel']::text[], 8.5, '{"poet":"Zeynep Orcanel","poet_slug":"zeynep-orcanel","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/riza-dayicigim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilinmeyen gün', 'bilinmeyen-gun-mehmet-ali-suzen-dsw5j', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bizi bize bırakmadın

Bizi bizden ayırdın

        Ne zalimsin be felek

        Anlımızın yazısımı

Dalımızı kopardın

Baharın göz yaşları döküldü üzerimize

Yinede yetmedi aşkımızın kuraklığına

Kızgın çöl misali yanıyor ellerin dudakların

Bozalım yazğımızı uzat ellerini

Buselerinle dön bana içsin kana kana

Kurumuş dudaklarım', 'Bizi bize bırakmadın Bizi bizden ayırdın         Ne zalimsin be felek         Anlımızın yazısımı Dalımızı kopardın Baharın göz yaşları dökül...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Süzen']::text[], 8.5, '{"poet":"Mehmet Ali Süzen","poet_slug":"mehmet-ali-suzen","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/bilinmeyen-gun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdamın Ayazında', 'sevdamin-ayazinda-huseyin-ciplak-pa9fm', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sevdiğim...

O gün geldiğinde,

Umuda dönüşecek o güzelim düşlerimiz,

El ele tutuşup,halayın zılgıtında,

Bizlere yüzlerce sevdalı eşlik edecek.

Umutlarımız,parçalayacak karanlığı...

Düşlerimiz aydınlığın zaferi olacaksa,

Coşkuya dönüştürecekse herkesi,

Dalgalanırız  o an sevda türküleri mırıldanarak.

Halaya tutuşacağız barbarlığa karşı...

Bizler sevdalandık baharın uyanışına,

Bir kara kış günü.

Özgürlüğe,özgürlüğe susamışız.

Dudaklarım kanamaya hazır yara,

Elimde bir demet kızıl gül.

Koşuyorum sana bütün inancımla,

Aç kaldım o büyük sevda ustasına.

Kuru ayazın  soğukluğu titretiyor bedenimi,

Her yanım sancır....

Vurulmuşum sana bir bahar sabahı,

İliklerimi ısıtan sevdam....', 'Sevdiğim... O gün geldiğinde, Umuda dönüşecek o güzelim düşlerimiz, El ele tutuşup,halayın zılgıtında, Bizlere yüzlerce sevdalı eşlik edecek...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Çıplak']::text[], 8.5, '{"poet":"Hüseyin Çıplak","poet_slug":"huseyin-ciplak","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sevdamin-ayazinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deli gönlüm', 'deli-gonlum-mehmet-ali-suzen-olvum', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dur dedim durmadı

Durmak nedir sormadı

Deli gönlüm sana aşık olmalı

Gel dedim gelmedi

Gelmek nedir bilmedi

Bu yanan gönlüm sönmek nedir bilmedi

İstedim aradım bulamadım

Kimselere sesimi duyuramadım

Haykırdım hıçkırdım ağladım

Susmak nedir bilmedim', 'Dur dedim durmadı Durmak nedir sormadı Deli gönlüm sana aşık olmalı Gel dedim gelmedi Gelmek nedir bilmedi Bu yanan gönlüm sönmek nedir bilm...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Süzen']::text[], 8.5, '{"poet":"Mehmet Ali Süzen","poet_slug":"mehmet-ali-suzen","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/deli-gonlum-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Diriliş', 'dirilis-orhan-turhan-pa0vy', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yürek akışı,

Göz teması,

Duyuların telaşı,

Birden var etti insanı.

Sıcaklığını kaybetmiş atışları,

Kurumaya yüz tutmuş dokunuşları,

Anlama hasret bakışları,

Bir süre için,

Uyandırıverdi  derinlerdeki  insanı.', 'Yürek akışı, Göz teması, Duyuların telaşı, Birden var etti insanı. Sıcaklığını kaybetmiş atışları, Kurumaya yüz tutmuş dokunuşları, Anlama h...', ARRAY['Türk Edebiyatı','Şiir','Orhan Turhan']::text[], 8.5, '{"poet":"Orhan Turhan","poet_slug":"orhan-turhan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/dirilis-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İkilem', 'i-kilem-orhan-turhan-kid06', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sessizlik…

Mutluluğa alkış olan yani,

Kimi zaman boğar insanı huzurun arifesinde,

Saadet bezeli bir tebessüm kostümüyle.

Keser ayaklarını yerden ankalara inat.

Dünyalara sahipken yani.

Sessizlik…

Konuşmaya muhtaç olan yani,

Çınlatır kulaklarını duymak istediklerin

Yok oluşun çığlıkları eşliğinde.

Sözsüz bırakır süresiz çığlıklara inat

Dünyalar başına yıkıkken yani.

Sessizlik…

Sonsuzluk yani.

Parçalar içini zamansız gidişin hıncı

Yaşanamayanların özlemiyle.

Soluksuz bırakır sonun başlangıcı

Dünyaya veda ederken yani.', 'Sessizlik… Mutluluğa alkış olan yani, Kimi zaman boğar insanı huzurun arifesinde, Saadet bezeli bir tebessüm kostümüyle. Keser ayaklarını ye...', ARRAY['Türk Edebiyatı','Şiir','Orhan Turhan']::text[], 8.5, '{"poet":"Orhan Turhan","poet_slug":"orhan-turhan","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ikilem-34-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İtiraf Et...', 'i-tiraf-et-zeynep-orcanel-u8jy5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dön demeyeceğim ardından ilk defa,

Bakışlarının altında ezileceğimi sanma! 

Gurbet gönlümün masum gözyaşlarını koynumda biriktiriyorum,

Seninle öldürmek için kalbimde seni! ..

Ben seni adam gibi adam bilirdim be,Ahmet..

Aslan parçasıydın gönlümde,

Aynı yolda yürüyen yolcuyduk kaderin elinde

Ne oldu bize böyle,

Söyle ne yaptın bize,birlikte yazdığımız kaderimize! ..

Seni acılar içimdeyken tanıdım,

Sevginin tohumlarını neden ektin içime,

Neden büyüttün ümitleri kalbimde

Mertçe sevmişken seni böyle! 

Bir kuşun kalbini bile taşımıyorsun o heybetli bedeninde! 

Korkuyorsun çocuk gibi

Korkuyorsun be,Ahmet.....

İtiraf et! ..

Musallat ettin gönlüme kederi

Öldürmek istiyorum içimde seni! 

Arama artık çıkma karşıma

Kör bir silahsın elimde,

Öldüremiyorum böyle seni içimde! ..

Can çekişiyorsun ama ölemiyorsun be,Ahmet..... 

Bardağında su yerine kanlı gözyaşı iç

Aldığın her yaranın sebebini acılar içinde bana biç,

Koynunda sevişirken gece yarısı gözlerimi gör bir anda,

Yaralan..

Sen beni böyle terk etmezdin hiç! ..

Çok seviyordum seni bu dibi olmayan dünyada,

Dibini çıkardın be sevgimin,

Artık hüznümün Allah''ısın sen,

Erkekçe gitmedin be utanmıyor musun kendinden! 

Utanmayı bilir misin sen be, Ahmet....

Hadi,

Hadi kendi benliğinle,

Utanmaz aynanla hayatına böyle devam et! ..', 'Dön demeyeceğim ardından ilk defa, Bakışlarının altında ezileceğimi sanma!  Gurbet gönlümün masum gözyaşlarını koynumda biriktiriyorum, Seni...', ARRAY['Türk Edebiyatı','Şiir','Zeynep Orcanel']::text[], 8.5, '{"poet":"Zeynep Orcanel","poet_slug":"zeynep-orcanel","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/itiraf-et-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anılar', 'anilar-mehmet-ali-suzen-j1ozu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Baş ucunda bülbülün

Elinde solmamış bir demet gülün

Olsa ne fayda... olsa ne fayda

Sen benim değilsin artık

Sen ellerin yarisin

Sen yoksun yanımda baş ucumda

Yalvarma bana gülüşünle alaylı alaylı

Çek uzanan ellerini

Kopmuşsun bütünüyle benliğimden

Uzakta kaldı hayaliyle yaşadığım günler

Hatırlayıpta mutlu olmak bile güzel

ANILARI........................................', 'Baş ucunda bülbülün Elinde solmamış bir demet gülün Olsa ne fayda... olsa ne fayda Sen benim değilsin artık Sen ellerin yarisin Sen yoksun y...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Süzen']::text[], 8.5, '{"poet":"Mehmet Ali Süzen","poet_slug":"mehmet-ali-suzen","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/anilar-29-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tercih', 'tercih-orhan-turhan-ock8o', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sonsuzluk bir hiçti 

Issızda kendiyle yüzleşmeye hasret bir candan önce.

Sınırları parçalara ayırdım kıymık kıymık.

Ve kaybolmayı yeğ tuttum,

Orada mutluluğu görünce.', 'Sonsuzluk bir hiçti  Issızda kendiyle yüzleşmeye hasret bir candan önce. Sınırları parçalara ayırdım kıymık kıymık. Ve kaybolmayı yeğ tuttum...', ARRAY['Türk Edebiyatı','Şiir','Orhan Turhan']::text[], 8.5, '{"poet":"Orhan Turhan","poet_slug":"orhan-turhan","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/tercih-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ali İhsan Tuncalı', 'ali-i-hsan-tuncali-selma-vural-xr1yu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Adım adım yöremizi dolaştın

Emlek’i taşlara kazdın Tuncalı

Ozanları nakış nakış işledin

Emlek''i tarihe yazdın Tuncalı

Ali Tuncalı’mız gönül adamı

Dürüstlük ilkesi onun planı

Bilgi ve ilmine muhtaç olanı

Bize bu gizleri çözdün Tuncalı

Muhammet-Ali’nin yoluna girdik

Hüseyin, Agahi, Hıdır’ı bildık

Veysel’i, İzzet’i bizlerde gördük

Pek çok ozan ile gezdin Tuncalı

Saraç, Şeme dağı ziyaret yeri

Topaç köyüde ırmaktan beri

Sivas’ın incisi, bizlerin gülü

Yüreklerimize sızdın Tuncalı

Her kişi anlar mı kulun halinden

Uzak kaldık sohbetinden dilinden

Muğla’da değilim tutam elinden

Hasret koydun bizi üzdün Tuncalı

Hakka aşık olup bu aşkla coşan

Emlek  dağlarını durmadan aşan

SELMAİ dedemle bu yolda koşam

Yolumuzu bize çizdin Tuncalı', 'Adım adım yöremizi dolaştın Emlek’i taşlara kazdın Tuncalı Ozanları nakış nakış işledin Emlek''i tarihe yazdın Tuncalı Ali Tuncalı’mız gönül ...', ARRAY['Türk Edebiyatı','Şiir','Selma Vural']::text[], 8.5, '{"poet":"Selma Vural","poet_slug":"selma-vural","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ali-ihsan-tuncali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kısmetse sen benimsin', 'kismetse-sen-benimsin-mehmet-ali-suzen-iqfal', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bakışların öylesine derinki

Beni bakışların ile götürdün uzaklara

Bazen yanımdasın gerçekler gibi

Hiç bir zaman yoksun hayallerimdeki gibi

Yalnız iken avutuyorum kendimi

Senin ile olduğum anlar gibi

İçime nefes diye çektiğim

Hayatım diye yaşadığım

Esmer güzelim bak gözlerime

Ancak bakışlarımla anlatabiliyorum

Sana olan hayranlığımı

Başka türlü anlatmak mümkün değil diye

Gözlerimden akan damla damla yaşları

Dizeliyorum şimdi içime

Sevgi dolu bakışların eritiyor beni diyor

Avutuyorum kendimi güzel hayalin ile

İçimdeki sevgim taşarcasına

Sıralıyorum aşkımı konuşturan satırlarıma', 'Bakışların öylesine derinki Beni bakışların ile götürdün uzaklara Bazen yanımdasın gerçekler gibi Hiç bir zaman yoksun hayallerimdeki gibi Y...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Süzen']::text[], 8.5, '{"poet":"Mehmet Ali Süzen","poet_slug":"mehmet-ali-suzen","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/kismetse-sen-benimsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Kazanacaksın', 'sen-kazanacaksin-mehmet-aslan-1lp5m', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sen kazananı olacaksın, yaşadığımız bu savaşın,

Kaybedense kurnaz geçinen saf, aptal arkadaşın,

Hayatının boyu huzurunu yaşayacaksın bu barışın,

Başın dik, sevgi gözyaşlarıyla olacak ayrılışın.

Senide satacak bir gün, ceylan bakışlarıyla,

Düşecek tuzağa yaşadığı mevsimlik aşklarıyla,

Pişman olacak bir gün yaşadığına başkalarıyla,

Utanç içinde gidecek, vedalaşamadan dostlarıyla.

O kaybedecek bir gün en değerli varlığını,

Saklasa da yürüyüşü belli edecek laçkalığını,

Sen ise silip atacaksın, onunla arkadaşlığını,

Anlatamasa da gözünden okuyacaksın pişmanlığını. 

Bir arkadaşım vardı, oda yaptı aynı hatayı,

O kurnazdı, yamayınca kendini kurtardı paçayı,

Bilmiyorum seninki ne sanıyorsa bu sevdayı,

Eloğlu unutacak onu, mezun olup terk edince burayı.

Senin bu gurbetin huzur içinde bitecek,

O ise arkasına bile bakamadan gidecek.

Bir ömür boyu hatasının acısını çekecek,

Onun savaşıysa asla zaferle bitmeyecek.

Sende buralardan ayrılırken ağlayacaksın,

Ama utanç değil, sevinç gözyaşları akıtacaksın,

Unutmayacaksın bizi, zaman zaman arayacaksın,

Sana olan sevgimizi fazlasıyla kazanacaksın.

Döneceksin sılaya, ama beni çözemeden,

Bir gün olsun güldüğümü göremeden,

Kim olduğumu, ne olduğumu öğrenemeden,

Gideceksin, ama benimde ağladığımı bilmeden.', 'Sen kazananı olacaksın, yaşadığımız bu savaşın, Kaybedense kurnaz geçinen saf, aptal arkadaşın, Hayatının boyu huzurunu yaşayacaksın bu barı...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Aslan']::text[], 8.5, '{"poet":"Mehmet Aslan","poet_slug":"mehmet-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/sen-kazanacaksin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sarraflar Bilmez Seni', 'sarraflar-bilmez-seni-mehmet-aslan-fbe2c', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Çok düşündüm, her gün her gece,

Çözemedim anlayamadım seni.

Senin içinse, ben zaten bir bilmece,

Uğraşma, ömrün yetmez anlamaya beni.

Bazen gülüyorsun, ne gerçek nede içten,

İhtiyacım yok senin sahte gülücüğüne.

Bazen güzel bir söz çıksa bile ağzından,

Anlam veremiyorum hiçbir sözcüğüne.

Bazen çok sıcak, samimi yaklaşıyorsun,

O zaman sana dokunmak istiyorum.

Yaklaştığımda ise hemen kızıyorsun,

Bu davranışına da bir anlam veremiyorum.

Özleniyorsun gelmediğin zamanlarda,

Gözüm kapıda kalıyor belki gelirsin diye.

Anlatsam da sana kendimi ekranlarda,

Anlamak istemiyorsun söyle niye? 

Değerini yalnızca sarraflar bilir elmasın,

Seninkini ise bir ben birde ben bilirim.

Kilitle kalbini kimseler çalmasın,

Oraya bir tek ben girmek isterim.', 'Çok düşündüm, her gün her gece, Çözemedim anlayamadım seni. Senin içinse, ben zaten bir bilmece, Uğraşma, ömrün yetmez anlamaya beni. Bazen ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Aslan']::text[], 8.5, '{"poet":"Mehmet Aslan","poet_slug":"mehmet-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sarraflar-bilmez-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duymazmısın', 'duymazmisin-mehmet-aslan-ylqq9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Seni sevdiğimi söylesem alınırmısın,

Yoksa koşup ta sarılırmısın.

Ellerini tutmak istesem darılırmısın,

Yoksa sende tutup kucaklarmısın.

Sana biraz daha yaklaşsam kaçarmısın,

Yoksa dönüp te beni yakalarmısın.

Sana kalbimi versem alırmısın,

Yoksa alarak atıp ta kırarmısın.

Sana sevgimi sunsam bağlanırmısın,

Yoksa dostluğumuzu koparırmısın.

Sana aşk ateşimi versem yanarmısın,

Yoksa yalnız beni yakarmısın.

Sana yazdıklarımı kendine sorarmısın,

Yoksa boş ver deyip sallarmısın.

Sana bu yakarımı duyarmısın,

Yoksa kulaklarını tıkarmısın.

Sana bu çağrıma bir cevap yazarmısın,

Yoksa sıktın deyip silip atarmısın.

Sen sevgiden hiç anlamazmısın,

Yoksa anlayıp ta duymazmısın.', 'Seni sevdiğimi söylesem alınırmısın, Yoksa koşup ta sarılırmısın. Ellerini tutmak istesem darılırmısın, Yoksa sende tutup kucaklarmısın. San...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Aslan']::text[], 8.5, '{"poet":"Mehmet Aslan","poet_slug":"mehmet-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/duymazmisin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kimsin Sen', 'kimsin-sen-mehmet-aslan-ud4w4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kimsin sen, neden değişken ve anlaşılmazsın,

Bazen kardan soğuk, bazense kordan sıcaksın.

Nasıl olurda ikisini birden yüreğinde barındırırsın,

Çözemedim seni, yoksa karışık bulmacamısın.

Bazen öyle sıcak, öyle cana yakın oluyorsun,

İnsana güler yüzle, samimiyetle yaklaşıyorsun,

Bende aynı duygularla yaklaşınca kızıyorsun,

Nesin sen, peri kızımı beni sürekli şaşırtıyorsun.

Bazen sevinçlerini paylaşmak istiyorsun,

Ama paylaşmak için kendine yaklaştırmıyorsun,

Paylaşalım deyince de hemen bozuluyorsun,

İşte o zaman inan ki beni çok üzüyorsun.

Çok günlerin var buralarda yaşayacağın,

Çok günlerinde olacak bizimle çalışacağın,

Bekliyorum o günü benimle barışacağın,

Hasretle, özlemle konuşup anlaşacağın.', 'Kimsin sen, neden değişken ve anlaşılmazsın, Bazen kardan soğuk, bazense kordan sıcaksın. Nasıl olurda ikisini birden yüreğinde barındırırsı...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Aslan']::text[], 8.5, '{"poet":"Mehmet Aslan","poet_slug":"mehmet-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kimsin-sen-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkımızı Onlara Sorduğunda', 'askimizi-onlara-sordugunda-mehmet-aslan-vjy1e', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Anlayamadım beni nasıl kandırdığını,

Bilemezdim senin böyle kurnazlığını,

Kızamadım hissedince sıcaklığını,

Anlayamadım o kitabı nasıl aldığını.

Okudun onu içinde sen yoksun,

Bunu iyi oku içinde çoksun,

Bulupta darılırsan sana aşk olsun,

O zaman bu ilk ve son olsun.

Darılıp anlayamazsan dostluğumu,

Anlarsın o zaman hayaller kurduğumu,

İstersen eğer seninle mutluluğumu,

Görürsün o zaman yeniden doğduğumu.

Sende ellerimi severek tuttuğunda,

Olacaksın o zaman zevkin doruğunda,

Aşkımızı onlara sorduğunda,

Karışacak her yer kıyamet koptuğunda.

Dert etme sonra her şey düzelecek,

Onların değil bizimdir bu gelecek,

Önce ağlayacak sonra gülecek,

Üzsekte sonunda hepsi sevinecek.', 'Anlayamadım beni nasıl kandırdığını, Bilemezdim senin böyle kurnazlığını, Kızamadım hissedince sıcaklığını, Anlayamadım o kitabı nasıl aldığ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Aslan']::text[], 8.5, '{"poet":"Mehmet Aslan","poet_slug":"mehmet-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/askimizi-onlara-sordugunda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sende Sunmalısın', 'sende-sunmalisin-mehmet-aslan-ec6ye', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gülücüklerine tutuldum,

Büyülendim vuruldum,

Koşmaktansa yoruldum,

Eriyip bittim mahvoldum.

Tek can damarımsın,

Canlandıracak aşkımsın,

Hayat verecek kanımsın,

Çünkü benim canımsın.

Yeter artık anlamalısın,

Aşkıma inanmalısın,

Bir yolunu bulmalısın,

Sende aşkını sunmalısın.

Seni çok seviyorum,

Sebebini bilmiyorum,

Nazlısın anlıyorum,

Bir cevap istiyorum.', 'Gülücüklerine tutuldum, Büyülendim vuruldum, Koşmaktansa yoruldum, Eriyip bittim mahvoldum. Tek can damarımsın, Canlandıracak aşkımsın, Haya...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Aslan']::text[], 8.5, '{"poet":"Mehmet Aslan","poet_slug":"mehmet-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sende-sunmalisin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Gece', 'bir-gece-mehmet-aslan-bxy5f', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Çalışıyordum gece ve gündüz yazarak,

Hiç durmadan, uyumadan, dinlenmeden,

Bir kız çıktı karşıma gülücükler saçarak,

Bir gülüşünle kalbimi çaldı hiç bilmeden.

Bir kız çıktı karşıma çaldı kalbimi,

Farkında olmadan, bilmeyerek,

Anlattırmadı bana derdimi,

Gülücükler saçıp dinlemeyerek.

Söyleyince doğum günü olduğunu,

Bıraktım o gece bütün yazı işlerimi,

Fark edince yorgunluktan gözlerimin uyuduğunu,

Başladım ona yazmaya kutlama şiirlerimi.

Okuduğunda onun için yazdığım şiirini,

Kalabalıktı belli edemedi duygularını,

Fark etmişti benim için değerini,

Seyrettiğinde hazırladığım sunularını.', 'Çalışıyordum gece ve gündüz yazarak, Hiç durmadan, uyumadan, dinlenmeden, Bir kız çıktı karşıma gülücükler saçarak, Bir gülüşünle kalbimi ça...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Aslan']::text[], 8.5, '{"poet":"Mehmet Aslan","poet_slug":"mehmet-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bir-gece-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Suskun Kalma', 'suskun-kalma-volkan-yoruc-qpbyi', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Suskun kalma

Böyle gelmiş böyle gitmez hayat

Dışarda kar yağıyor belkide

Soğuk olabilir üşüyebilirsin

Güz sabahı güz akşamı gelir geçer ömrümüzden

Yine gelir baharlar 

Yine açar renkli çiçekler bahçenden

Suskun kalma

Bakar kör kalan gözler gibi olma

Bir ses bir ışık bir nefes ver hayata

Doğrult ellerini gökmaviye

Sarıl toprağın kahverengi rengine

Suskun kalma

Hayat devam eder sessizce

Bazen ümitlice bazende bir çiçek kadar narince', 'Suskun kalma Böyle gelmiş böyle gitmez hayat Dışarda kar yağıyor belkide Soğuk olabilir üşüyebilirsin Güz sabahı güz akşamı gelir geçer ömrü...', ARRAY['Türk Edebiyatı','Şiir','Volkan Yoruç']::text[], 8.5, '{"poet":"Volkan Yoruç","poet_slug":"volkan-yoruc","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/suskun-kalma-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Sıcak Bakışların', 'o-sicak-bakislarin-mehmet-aslan-947na', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İlk kez karşılaştığımızda seninle,

Acaba konuşur mu diye benimle,

Aklımdan çıkaramadım seni yeminle,

Akşamları avundum senin hayalinle,

Rüyalarımdaydın o masum gözlerinle.

Büyüledi beni çatılmayan kaşların,

Şaşırttı beni dostça yaklaşımların,

Aklımı aldı o sıcacık bakışların,

Yaktı beni samimi davranışların,

Bağladı beni yanımda duruşların,

Belkide yine boş hayaller kuruyorum,

Şimdi kendi kendime soruyorum,

Galiba her zamanki gibi aldanıyorum,

Yinede kendimi senden alamıyorum.

Sensizken hiç bir şeyle avunamıyorum.

Kapatmışken herkese karşı sevgi defterimi,

Hiç kimseye vermeyecektim artık sevgimi,

Nasıl anlatırım bilemem şimdi sana derdimi,

Aşmak istemesem de sana karşı haddimi,

Sen anla beni, cevap ver kırmadan kalbimi.

Anlat bana ne olacak şimdi halimiz,

Bitmeyecek mi hiç bizim derdimiz

Karşılıksız mı kalacak bu sevgimiz,

Tek yürek atamayacak mı kalbimiz,

Biliyorsan söyle var mı başka çaremiz.

Darıltırsa eğer seni bu yazdığım dizelerim,

İşte o zaman yıkılır bu yüzden biterim,

Kesilir seni görmek için oraya gelişlerim,

Unutma ki karşılıksız olsa bile sevgilerim,

Yinede her zaman dost kalmanı isterim.', 'İlk kez karşılaştığımızda seninle, Acaba konuşur mu diye benimle, Aklımdan çıkaramadım seni yeminle, Akşamları avundum senin hayalinle, Rüya...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Aslan']::text[], 8.5, '{"poet":"Mehmet Aslan","poet_slug":"mehmet-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/o-sicak-bakislarin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeniden Filizlenen Dostluk', 'yeniden-filizlenen-dostluk-mehmet-aslan-3nvej', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Döndük yeniden bir tek seninle eski günlere,

Başladık tekrar doyamadığımız sohbetlere,

Sen tam isyan etmek üzereyken gurbet ellere,

İsyanın bitti, inanmadığın için yalan sözlere.

Cesaretliymişsin tınlamıyorsun artık koalisyonu,

Şimdi çok sevdim seni, olmadın onların piyonu,

Felç olmak üzereyken, biraz düşürdün tansiyonu,

Sende üzme sakın beni, sevmem hiç ispiyonu.

Onların küskünlüklerini inan hiç anlayamadım,

Nedir onların dertleri diye sana da soramadım,

Hatamda yoktu ama dinlemediler anlatamadım,

Beni çok ağlattılar, o akıttığım yaşları unutamadım.

Okuduğunda çözersen eğer, bu şiirimin konusunu,

Asla sorma onlara, nedir darılmanın sebebi sorusunu,

Onlara ben bile öğretemediysem dostluk coşkusunu,

Bırak anlamasınlar, bozma onların cehalet uykusunu.

Bir gün anlarlarsa eğer benim dostluğumu,

O zaman bilsinler kapımı her zaman açık tuttuğumu,

Oysa görüyorlar her gün nasıl kahrolduğumu,

Sanmasınlar sakın seninle kendimi avuttuğumu.

Sende sakın yanlış anlamayasın, sana olan sevgimi,

O zaman hepten yıkılırım affedemem asla kendimi,

Çıldırmak üzereyim zaten, anlatamıyorum derdimi,

Yok olur giderim, bu dertler üzüntüler beni yendimi.', 'Döndük yeniden bir tek seninle eski günlere, Başladık tekrar doyamadığımız sohbetlere, Sen tam isyan etmek üzereyken gurbet ellere, İsyanın ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Aslan']::text[], 8.5, '{"poet":"Mehmet Aslan","poet_slug":"mehmet-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/yeniden-filizlenen-dostluk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözünüz Körmüki', 'gozunuz-kormuki-mehmet-aslan-er6ev', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dünyanız öyle küçükmüş ki,

İçine sığdıramadınız beni.

Kalbiniz öyle taşmış ki,

İçine sindiremediniz beni.

Aklınız öyle kıtmış ki,

Yanlış anladınız sevgimi.

Bende enayiymişim ki,

Sizler sanmışım dengimi.

Öyle cahilmişsiniz ki,

Okuyup anlamadınız.

Benimki öyle sevgiydi ki,

Sizler onu tadamadınız.

Gözleriniz körmü ki,

Beni yanlış gördünüz.

Tuttuğunuz kinmi ki,

Bana çorap ördünüz.

Siz hırsızmışsınız ki,

Kalbimi çaldınız.

İşe yaramazmıydı ki,

Onu çöpe attınız.', 'Dünyanız öyle küçükmüş ki, İçine sığdıramadınız beni. Kalbiniz öyle taşmış ki, İçine sindiremediniz beni. Aklınız öyle kıtmış ki, Yanlış anl...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Aslan']::text[], 8.5, '{"poet":"Mehmet Aslan","poet_slug":"mehmet-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gozunuz-kormuki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aydınlanacak Karanlık', 'aydinlanacak-karanlik-mehmet-aslan-d1mq3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Suçluysam söyleyin bende bileyim,

Sizleri bir daha hiç dert etmeyeyim,

Yüzlerinizi de görmek istemeyeyim,

Bitsin  artık, bu acıları çekmeyeyim.

Nedendir, çektiğim bu ızdıraplarım,

Sizleri sevmek ise benim günahım,

Dostluk kurmaksa suçum dostlarım,

Sizlere karşı, değişmez duygularım,

Ruhumuza işlemiştir, bizim insanlık,

Geri dönmeyiz, duymayız pişmanlık,

Her ne kadar besleseniz de düşmanlık,

Sabredeceğim, aydınlanacak karanlık.

Ne yaparsanız yapın, kopamazsınız,

Sevgimiz değerlidir, onu atamazsınız,

Sıcaksınız sizler, asla kin tutamazsınız,

İçinizde yok, düşmanlık yapamazsınız.

Eminim, bir gün kendinize geleceksiniz,

O zaman eskisi gibi, bizi seveceksiniz,

Kendinize, hata yapmışız diyeceksiniz,

O zaman, buralardan mutlu gideceksiniz', 'Suçluysam söyleyin bende bileyim, Sizleri bir daha hiç dert etmeyeyim, Yüzlerinizi de görmek istemeyeyim, Bitsin  artık, bu acıları çekmeyey...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Aslan']::text[], 8.5, '{"poet":"Mehmet Aslan","poet_slug":"mehmet-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/aydinlanacak-karanlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Yalnız Kartanesi', 'bir-yalniz-kartanesi-volkan-yoruc-ipfyb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Anılar sahilinde bir garip kum tanesiyim

Sevdiğini düşleyen her sevgilinin

Gözyaşlarıyla yıkadığı bir zaman hanesiyim

Gülümsemenin unutulduğu özlem rüzgarlarının estiği

Soluk yapraklı kavakta bir yalnız kartanesiyim', 'Anılar sahilinde bir garip kum tanesiyim Sevdiğini düşleyen her sevgilinin Gözyaşlarıyla yıkadığı bir zaman hanesiyim Gülümsemenin unutulduğ...', ARRAY['Türk Edebiyatı','Şiir','Volkan Yoruç']::text[], 8.5, '{"poet":"Volkan Yoruç","poet_slug":"volkan-yoruc","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/bir-yalniz-kartanesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman', 'zaman-bulent-ahmet-alp-pa7qd', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Tükeniyor zaman...

Değmeden hiçkimseye geçip gideceğim...

Sevgililer geçiyorlar, elele...

Umrunda değil hiç onların...

Yaşamak dediğin nefes alıp vermekmiş...

Özlemsiz, sevgisiz...

Her ağlamamda daha da ölüyorum...

Ne zaman bir düş görsem hep hayatla uyanıyorum...

Herşeyi bıraktım artık...Herşeyi...

Bir tek şu sigarayı bırakamadım...

Herkes beni bıraktı...

Ne ağlayabilecekleri bir omzum,

Ne de tutabilecekleri bir elim kaldı...

Yürek kalmadı artık bende sevecek...

Ağlamayan bir çift gözüm var şimdi...

Yaşayabileceğim bir zaman...

Hep ardımdan beddua edilmiş sanki...

Hiçbirşey eskisi gibi değil ki...

Ne zaman...

Ne yürek...

Ne de ben...

Tıkandı tüm damarlarım...

Tamamlandım artık ben...

Tüm eksik yerlerimi acılarla tamamladılar...

Ilık bir rüzgar döndürüyor başımı...

Bir yaprak usul usul süzülüyor...

Başımın ucundan geçip gidiyor.

Renkleri dökülüyor gökyüzünün...

Neyin habercisi bunlar? 

Nereye gidiyor bu insanlar...

İmkansızlıkları varken...

Anlaşılmaz bir kuyudan sesleri geliyor...

Batıyor yine güneş kızıla boyuyor her yanı.

Ölümdür sana yaklaşan...

Batan güneş yarın doğar mı?', 'Tükeniyor zaman... Değmeden hiçkimseye geçip gideceğim... Sevgililer geçiyorlar, elele... Umrunda değil hiç onların... Yaşamak dediğin nefes...', ARRAY['Türk Edebiyatı','Şiir','Bülent Ahmet Alp']::text[], 8.5, '{"poet":"Bülent Ahmet Alp","poet_slug":"bulent-ahmet-alp","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/zaman-162-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelmedin', 'gelmedin-fatih-konuk-ln1g2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '8 heceli

GELMEDİN

Seni beklediğim kadar 

Azrail’i bekleseydim 

Şimdiye çoktan gelmişti

Çoktan canımı almıştı

Ben bekledim seni bekledim

Ama sen sen hiç gelmedin

Gelmedin sen,sen gelmedin

Gelmedin neden gelmedin

Şimdi seni özlüyorum

Gelir diye bekliyorum

Gözlerimi yollarına

Hergün hergün dikiyorum

Seni dilendiğim kadar

Günahımın affı için

Yaradan’a dilenseydim

Şimdiye kabul etmişti', '8 heceli GELMEDİN Seni beklediğim kadar  Azrail’i bekleseydim  Şimdiye çoktan gelmişti Çoktan canımı almıştı Ben bekledim seni bekledim Ama ...', ARRAY['Türk Edebiyatı','Şiir','Fatih Konuk']::text[], 8.5, '{"poet":"Fatih Konuk","poet_slug":"fatih-konuk","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/gelmedin-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gün Olur Belki', 'gun-olur-belki-fatih-konuk-zkod6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sana yazdığım bu şiir masanda kalsın 

Gün olur belki beni özlediğinde okursun

Şiirimin yanında duran gülümde kalsın

Gün olur belki beni özlediğinde koklarsın

Ben gidiyorum her şeyim sende kalsın

Isterim o gözlerin bensizkende gülsün

Boynum bükük,kalbim kırık olursa olsun

Gün olur belki beni andığında yanarsın

Ben yokken resmim duvarda asılı kalsın

Bakar bakar o güzel mazimizi anarsın

Bedenim cehennem ateşlerinde yansın

Gün olur belki beni yandığımda anlarsın', 'Sana yazdığım bu şiir masanda kalsın  Gün olur belki beni özlediğinde okursun Şiirimin yanında duran gülümde kalsın Gün olur belki beni özle...', ARRAY['Türk Edebiyatı','Şiir','Fatih Konuk']::text[], 8.5, '{"poet":"Fatih Konuk","poet_slug":"fatih-konuk","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gun-olur-belki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Memleketim, Ah...Memleketim! ...', 'memleketim-ah-memleketim-mustafa-gokcek-1k8oh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'MEMLEKETİM, AH… MEMLEKETİM! ...



Gözümün yağıydın, çapağı oldun

Bana değil ama,

Ocaksız, dumanı tütmeyen köylerime koşaydın

Ve çıkınımda bir parça tayın, zulamda peynir olaydın

Bulmasam da olur ama,

Tencerelerinde taş kaynatan

Ana sütüne helâl diye yüklenen

Nice bebelerin solmuş tenini acıtan

Fırtına öncesinde hakim, sessizlik

Ölü bir afet gibi dirilmişliğin boranı

Bir dolu rüzgâr ve kıtlık, kıran

Yıl 2004, köy yolundaki aracımızın çamurlukları hâlâ çamurlu! ...



04.07.04                                                           Mustafa Gökçek', 'MEMLEKETİM, AH… MEMLEKETİM! ... Gözümün yağıydın, çapağı oldun Bana değil ama, Ocaksız, dumanı tütmeyen köylerime koşaydın Ve çıkınımda bir ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Gökçek']::text[], 8.5, '{"poet":"Mustafa Gökçek","poet_slug":"mustafa-gokcek","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/memleketim-ah-memleketim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ya adam gibi', 'ya-adam-gibi-denizhan-solmaz-ulgdv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sanmakla 

sanmışımla 

koca bir hayat geçmez böyle

ya bunun adam gibi bir tarifini yapın

yada her esintiye kapılmayalım

...........

kalmamış söylenmemiş söz

gün ışığıda 

kalmamış hiçbir biçimi anlatılmayan

kimi susarak anlatmaya çalışmış

ama hangisi gerçekten aşık olmuş

ya adam gibi tarifini yapsınlar

yada boşa yormasınlar', 'Sanmakla  sanmışımla  koca bir hayat geçmez böyle ya bunun adam gibi bir tarifini yapın yada her esintiye kapılmayalım ........... kalmamış ...', ARRAY['Türk Edebiyatı','Şiir','Denizhan Solmaz']::text[], 8.5, '{"poet":"Denizhan Solmaz","poet_slug":"denizhan-solmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ya-adam-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çabuk Olalım', 'cabuk-olalim-fatih-konuk-4t3l0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İşte koskoca bir gün daha bitti

Güneş dünyayı terk etmek üzere

Kısa ömürden bir gün daha gitti

Azrail bizleri bulmak üzere

Kızıllaştı masmavi berrak deniz,

Masmavi gökyüzü,beyaz bulutlar

Acele edelim,çabuk olalım

Ecel kapımızı çalmak üzere

Tövbe edelim daha vakit varken

Mevla’nın huzuruna çıkmamışken

Ateşte cayır cayır yanmamışken

Melekler hesabı sormak üzere

Acele edelim,çabuk olalım

İsrafil sur’unu üflememişken

Acele edelim,çabuk olalım

Daha sorgu,sual sorulmamışken', 'İşte koskoca bir gün daha bitti Güneş dünyayı terk etmek üzere Kısa ömürden bir gün daha gitti Azrail bizleri bulmak üzere Kızıllaştı masmav...', ARRAY['Türk Edebiyatı','Şiir','Fatih Konuk']::text[], 8.5, '{"poet":"Fatih Konuk","poet_slug":"fatih-konuk","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/cabuk-olalim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönlüme Şiirler 1', 'gonlume-siirler-1-erdogan-ergin-9qwjo', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'serseri gönlüm mü var? 

neden ağlatıyor tüm ağıtları? 

yazgılar aynı

yazıtlar aynı

çareler hep acemde

acemi gönlümde

gönül işcisi değilim

kalp hırsızlığı yapamadım

ama

niçin çaldırdım tüm anılarımı', 'serseri gönlüm mü var?  neden ağlatıyor tüm ağıtları?  yazgılar aynı yazıtlar aynı çareler hep acemde acemi gönlümde gönül işcisi değilim ka...', ARRAY['Türk Edebiyatı','Şiir','Erdoğan Ergin']::text[], 8.5, '{"poet":"Erdoğan Ergin","poet_slug":"erdogan-ergin","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/gonlume-siirler-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin Yanında', 'senin-yaninda-fatih-konuk-e0gtz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sözcükler manasız

Kelime yetersiz

Zamansa değersiz

Kalır senin yanında

Senin yanında,senin yanında

Ahh senin yanında,senin yanında

Senin yanında,senin yanında 

Off senin yanında,senin yanında

Güneş sönük,sönük

Aşkım büyük,büyük

Boynum bükük,bükük

Olur senin yanında', 'Sözcükler manasız Kelime yetersiz Zamansa değersiz Kalır senin yanında Senin yanında,senin yanında Ahh senin yanında,senin yanında Senin yan...', ARRAY['Türk Edebiyatı','Şiir','Fatih Konuk']::text[], 8.5, '{"poet":"Fatih Konuk","poet_slug":"fatih-konuk","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/senin-yaninda-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çinganem', 'cinganem-mustafa-gokcek-2a7ie', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'ÇİNGANEM



Zulamda hayın toprak

Çıkınımda üç kepek ekmek

Ve ben ekmeğimi yer

Katıksız, karnımı doyurduktan sonra…

Sedef kakmalı bir zurnam var nasıl olsa

Alt deliğinde gümüş bir işleme, üst deliğinde sedef kakma

Oturursun ağlar, ağlarsın oturur

Ve kalkarsın bir gün koltuğundan

Ama sana kalan, birazcık da olsa sedef kakmadır…



20.04.04                                         M.Gökçek

(Bu şiire şu açıklamayı yapmak zorunluluğunda kaldım...     ''TDK'' nun 1989 yılında yayımladığı Kâmus-î Tûrk-î ''sinde ÇİNGANEM ''in karşılığı; aşırı kıskanç...'' sanırım bu açıklama yeterli olur. Yani ÇİNGENEM ''le lütfen karıştırılmasın.)', 'ÇİNGANEM Zulamda hayın toprak Çıkınımda üç kepek ekmek Ve ben ekmeğimi yer Katıksız, karnımı doyurduktan sonra… Sedef kakmalı bir zurnam var...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Gökçek']::text[], 8.5, '{"poet":"Mustafa Gökçek","poet_slug":"mustafa-gokcek","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/cinganem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman Ve Mekana İnat', 'zaman-ve-mekana-i-nat-sirma-mersin-eul0m', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Olur da bir gün

Yaşadığım kentin sokaklarına düşerse gölgen

Sürerse ayakların caddelerimi yüreğinin izinde

Olursan eğer

Ardına yüklenip mavi bulutla

Ufkunda rüzgar kaçağı yıldızlar

Sana bir merhaba demek isterim

Mesafelere, zamana  inat

Benle bir şeyler paylaşabiliyorsan

Demek ki yüreğin doğru adreste...

Sözün bittiğinde

Yarım kalan duyguların konuşursa benimle

Daha soluk alacak nefes var demektir yüreğinde...

Geceyi günden koparıp

Sesleri yalnızlığa itersen

Sana cevap verecek paylaşımlar çıkar karşına

Benden sana …

özleyiş  akan bir ırmak ufkumda

18.12.04 '' Bu şiir can yürek dediğim,dostumla beraber yazdığım ortak bi

                  şiirdir...', 'Olur da bir gün Yaşadığım kentin sokaklarına düşerse gölgen Sürerse ayakların caddelerimi yüreğinin izinde Olursan eğer Ardına yüklenip mavi...', ARRAY['Türk Edebiyatı','Şiir','Sırma Mersin']::text[], 8.5, '{"poet":"Sırma Mersin","poet_slug":"sirma-mersin","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/zaman-ve-mekana-inat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönlüme Şiirler 2', 'gonlume-siirler-2-erdogan-ergin-e27m5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'hesaplaşma günüdür hey ben

baktığın aynalar niçin eski

kuruyup çürüyecek elbet beden

ruhun bu ıstırabı nasıl seçti

eyvah etme, kendin,senden saklı

		/değil ki gönül

kırdığın, kendi kalbin, 

sızısı....	

		/bende değil gönül

bırak şimdi kendini, bir gözyaşı üstüne

aksın gözden, dudağa, dudaktan yüreğe

hisler ki, gerçeği yansıtmakta

çektiğin acı bende değil gönül', 'hesaplaşma günüdür hey ben baktığın aynalar niçin eski kuruyup çürüyecek elbet beden ruhun bu ıstırabı nasıl seçti eyvah etme, kendin,senden...', ARRAY['Türk Edebiyatı','Şiir','Erdoğan Ergin']::text[], 8.5, '{"poet":"Erdoğan Ergin","poet_slug":"erdogan-ergin","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/gonlume-siirler-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öyle Birisini Sevki', 'oyle-birisini-sevki-fatih-konuk-j1d8q', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Öyle birisini öyle bir sev ki; o da seni sevsin

Sevsin ve senden ayrılmaya,seni unutmaya 

Imkan olmasın

Öyle birisini öyle bir sev ki; taparcasına,ölürcesine

Ve delicesine sev ki başka birisini sevmeye gerek kalmasın

Seviyorum diye aldanam bir yarin güzellğine

Kendi güzel olabilir ama kalbi güzel olmayadabilir

Öyle birisine kalbini ver ki kırmasın,parçalamasın 

Kalbinde yer verdiğini bilsin ve anlasın

Öyle birisine öyle bir değer ver ki

Değer verdiğine deysin

Değer bilene değer ver

Değer bilmeyene verme sakın değer

Bir gün olur

Seni umursamada,

Arkasına bakmadan

Seni satıp gidebilir

Öyle birisine gönlünü verki; pişman olmayasın,

Kendi kendine isyan etmeyesin,üzülmeyesin

Gönül verme fazla yara 

Bir gün şımarır seni kullanmaya başlar

Seninle alay eder ve hor görür

Öyle birsine öyle bir değer ver

Güzeliğine aldanama sakın! ..........', 'Öyle birisini öyle bir sev ki; o da seni sevsin Sevsin ve senden ayrılmaya,seni unutmaya  Imkan olmasın Öyle birisini öyle bir sev ki; tapar...', ARRAY['Türk Edebiyatı','Şiir','Fatih Konuk']::text[], 8.5, '{"poet":"Fatih Konuk","poet_slug":"fatih-konuk","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/oyle-birisini-sevki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaralıyım Yaralı', 'yaraliyim-yarali-fatih-konuk-rirqi', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Çok zarar ettim ben aşkta çok mağlup oldum,çok yenildim

Bir kez olsun kavuşamadım,eremedim mutlu sona 

Hep benimi bulur kalpsiz,vefasız,hayırsız yarlar

Bir tek ben miyim sevip,sevilip sonrada terk edilen

Bir tek ben miyim sevmeyi,sevilmeyi hak etmeyen

Bu dünyada bir tek ben miyim,bir tek ben miyim

Yıkıldım,yoruldum ben kayboldu gitti bu benliğim

Bitkinim,yorgunum,çaresizim,yalnızlığa mahkumum

Bir aşkın çıkmaz sokağında gibiyim,yaralıyım yaralı

Her gece dua ediyorum Yaradan’a alnımın yazısı değişsin diye 

Çektiğim yalnızlıklar,yaşadığım ayrılıklar bir daha olmasın diye

Bir daha dünyaya gelme ihtimali olmayacağından

Yüzüm gülsün diye,mutlu bir gün yaşayayım diye 

Her gece dua ediyorum Yaradan’a,her gece dua ediyorum

İçimde öyle bir yara var ki yıllar geçmesine rağmen hala geçmedi

Aradım,aradım yıllarca aradım ilacını,merhemini ama bulamadım

Doktorlar bu iş bizden çıkar dedi,çaresi çaresi bu yarayı açan kişi dedi

Şimdi sende yoksun ben ne yapacağım,bu yarayla bir ömür yaşayacak mıyım

Ne vardı gitmeseydin,beni terk etmeseydin,bu yarayı açmasaydın gönlüme

Ne vardı bu günlere kadar getirseydik,bu günlerde de yaşasaydık aşkımızı

Ne olurdu yani ellerin olacağına benim olsaydın

Şimdi mutlu musun gittiğin yerde,benim olmadığım yerde

Hani senden ayrılamam,senden kopamam,sensiz hiçbir yerde mutlu olamam derdin

Hani her şeyden vazgeçerdin ama bir tek benden vazgeçemezdin,

Hani bensizlik ölüm gibiydi,hani bensizlik ışığı sönmüş bir oda gibiydi 

Şimdi hatırlıyor musun,unuttun mu bilmem ama bir zamanlar bu sözleri bana söylemiştin

Her gün gözlerini arayan,biran olsun hiç gülmeden ağlayan bir çift göz var geride

Her şarkıda o uzaklara dalan,geleceksin ümidiyle yollarını gözleyen gözler var geride

Yaşanılmış maziyi hatırlamakla,düşlemekle yaşayan birisi var gülüm birisi var geride

Yaşadığımız aşk bir masal,bir roman,bir rüya,bir düş gibi sanki

Keşke her şey böyle olacağına bir rüya olsaydı,keşke bir rüya olsaydı

İşte o zaman bu aşk hiç bitmesin diye bir ömür boyu hiç uyanmazdım', 'Çok zarar ettim ben aşkta çok mağlup oldum,çok yenildim Bir kez olsun kavuşamadım,eremedim mutlu sona  Hep benimi bulur kalpsiz,vefasız,hayı...', ARRAY['Türk Edebiyatı','Şiir','Fatih Konuk']::text[], 8.5, '{"poet":"Fatih Konuk","poet_slug":"fatih-konuk","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/yaraliyim-yarali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalanmıydı', 'yalanmiydi-fatih-konuk-049nr', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hani en sevdiğin bendim

Sözlerin yalan mıydı

Hani bakmaya doyamadığın bendim

Gözlerin yalan mıydı

Yalan mıydı

Yaşanılan o güzel aşkımız

Yalan mıydı

Beraber geçen yıllarımız

Yalan mıydı

Birbirimize verdiğimiz umutlarımız

Her şey yalan mıydı rüya mıydı yoksa

Dillerimizden dökülen sözcükler

Mektuplara döktüğümüz kelimeler

Uykusuz kaldığımız geceler

Hepsi yalan mıydı masa mıydı yoksa 

Ellerinin ellerimi tuttuğu günler

Gizli gizli mektuplaştığımız günler

Konuşmanın yerini bakışmaların aldığı günler

Bunlar yalan mıydı hayal miydi yoksa

Bitmeyecek sandığımız sevdamız

Yediklerimizi,içtiklerimizi paylaştığımız

Yıllar sonra olacak çocuklarımız

Söyle yalan mıydı roman mıydı yoksa', 'Hani en sevdiğin bendim Sözlerin yalan mıydı Hani bakmaya doyamadığın bendim Gözlerin yalan mıydı Yalan mıydı Yaşanılan o güzel aşkımız Yala...', ARRAY['Türk Edebiyatı','Şiir','Fatih Konuk']::text[], 8.5, '{"poet":"Fatih Konuk","poet_slug":"fatih-konuk","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/yalanmiydi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz Olmaz', 'sensiz-olmaz-fatih-konuk-lgr5m', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen gittiğin günden beri

Hayatı yaşayamadım

Sensizlik kalbime öyle dokundu ki

Sensiz olamadım

Ayrılığına can dayanmaz

Bu beden bedende durmaz

Sensiz olmaz sensiz olmaz

Dünyama güneş doğmaz

Odama ışık vurmaz

Sensiz olmaz sensiz olmaz

Bilemedim kıymetini

Sensizliği şimdi anladım

Sevmenin anlamını

Yokluğunda anladım', 'Sen gittiğin günden beri Hayatı yaşayamadım Sensizlik kalbime öyle dokundu ki Sensiz olamadım Ayrılığına can dayanmaz Bu beden bedende durma...', ARRAY['Türk Edebiyatı','Şiir','Fatih Konuk']::text[], 8.5, '{"poet":"Fatih Konuk","poet_slug":"fatih-konuk","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sensiz-olmaz-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzel Kızısın', 'guzel-kizisin-fatih-konuk-htbv1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sen masmavi denizlerin

Rengarenk dünyanın

Baharda açan çiçeklerin

Kızısın güzel kızısın

Sen sapsarı güneşlerin

Rengarenk gökkuşağın 

Meyve veren ağaçların

Kızısın güzel kızısın

Sen tatlı hayatın

Yeni açmış ağaçların

Yaşanacak aşkların

Kızısın güzel kızısın

Ben bulanık denizlerin

Kapkaranlık dünyanın

Baharda solan çiçeklerin

Çocuğum bahtsız çocuğum

Ben yüce dağların

Kayaların,taşların

Ben karanlık sokakların

Çocuğum şanssız çocuğum

Ben anlamsız hayatın 

Açmadan solmuş yaprakların

Yaşanacak ayrılıkların

Çocuğum umutsuz çocuğum', 'Sen masmavi denizlerin Rengarenk dünyanın Baharda açan çiçeklerin Kızısın güzel kızısın Sen sapsarı güneşlerin Rengarenk gökkuşağın  Meyve v...', ARRAY['Türk Edebiyatı','Şiir','Fatih Konuk']::text[], 8.5, '{"poet":"Fatih Konuk","poet_slug":"fatih-konuk","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/guzel-kizisin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdim İşte', 'sevdim-i-ste-fatih-konuk-cb4c9', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Nasıl olduğunu bilemedim

Bir anda kaptırdım kendimi sana

Aklımı aklımda tutamadım

Bir anda tutuldum ben sana

Sevdim işte dünyalar kadar

Sevdim işte canımdan çok

Sevdim işte sorgusuz,sualsiz

Sevdim işte başka çarem yok', 'Nasıl olduğunu bilemedim Bir anda kaptırdım kendimi sana Aklımı aklımda tutamadım Bir anda tutuldum ben sana Sevdim işte dünyalar kadar Sevd...', ARRAY['Türk Edebiyatı','Şiir','Fatih Konuk']::text[], 8.5, '{"poet":"Fatih Konuk","poet_slug":"fatih-konuk","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sevdim-iste-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doğmuyor Güneş Olmuyor Sabah', 'dogmuyor-gunes-olmuyor-sabah-fatih-konuk-q3g4x', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Doğmuyor güneş,olmuyor sabah

Benliğimi sardı,sardı bu günah 

Gözlerim gibi bahtımda siyah

Eyvah eyvah yandım eyvah

Alsa da benim canımı Allah 

Kurtulsam şu fani dünyadan

Ben aşklara etmem eyvallah

Ölsem de kurtulsam aşklardan', 'Doğmuyor güneş,olmuyor sabah Benliğimi sardı,sardı bu günah  Gözlerim gibi bahtımda siyah Eyvah eyvah yandım eyvah Alsa da benim canımı Alla...', ARRAY['Türk Edebiyatı','Şiir','Fatih Konuk']::text[], 8.5, '{"poet":"Fatih Konuk","poet_slug":"fatih-konuk","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/dogmuyor-gunes-olmuyor-sabah-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin Sayende', 'senin-sayende-fatih-konuk-f5ch9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bak sen Allah''ın işine

Senin sayende şiirler yazdım

Eğer ki sen beni sevip terk etmeseydin

Böyle aşk dolu,yalnızlıklı şiirler yazamazdım

Senin sayende güzelim senin sayende

Eğer ki mavi gözlerine,sarı saçlarına

Ve sana vurulmasaydım

Ben böyle şiirler yazamazdım

Eğer ki ellerim ellerini tutmasaydı

Gözlrim gözlerine bakmasaydı

Bu kalbim sana sana tapmasaydı

Imkanı yok böyle şiirler yazamazdım

Eğer ki acımı,aşkımı,mutluluğumu

Kağıda dökmeseydim

Sen bana bu güzel aşkı yaşatmasaydın

Mümkünü yok böyle şiirler yazamazdım

Senin bana dünyamı karartan

Ayrılığı yaşatmasaydın

O acı günü yaşamasaydım

Bu günleri yaşamazdım

Senin sayende güzelim 

Yokluğunu,yalnızlığımı

Hasretimi,özlemimi

Vazgeçilmezliğimi,beklentilerimi

Geri dönmeyişlerini

Anlatan şiirler yazamasaydım

Imkanı yok böyle şiirler olmazdı

Senin sayende güzelim

Kimse benim gibi yalnızlığını anlatan

Kimse benim gibi muhtaçlığını anlatan

Kimse benim gibi ayrılığı anlatan

Şiirler yazmamıştır

Kimse benim yaşadığımı yaşamamıştır

Senin sayende güzelim', 'Bak sen Allah''ın işine Senin sayende şiirler yazdım Eğer ki sen beni sevip terk etmeseydin Böyle aşk dolu,yalnızlıklı şiirler yazamazdım Sen...', ARRAY['Türk Edebiyatı','Şiir','Fatih Konuk']::text[], 8.5, '{"poet":"Fatih Konuk","poet_slug":"fatih-konuk","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/senin-sayende-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Türkü Yüreklim -7', 'turku-yureklim-7-gonul-ozdemir-xxlig', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Türkü Yüreklim– 7

Dağların ardında ceylanın ağlıyor

Aşkın yüreğimi  kor gibi yakıyor

Bak aylar geçti yıllar ise tuzak gibi bekliyor

Yüreğim seni gecelerime istiyor

Geleceksen gel ertık sevda yüreklim türkü yüreklim

Fırsat vermeyelim araya yıllar girmesin

Karlar yere düşmeden geleceksen gelesin

Sakın kışın bitmesini baharı beklemeyesin

Dağların ardında ceylanın ağlıyor

Geleceksen gel artık sevda yüreklim türkü yüreklim..

25.11.2003    Gönül Özdemir     -Almanya', 'Türkü Yüreklim– 7 Dağların ardında ceylanın ağlıyor Aşkın yüreğimi  kor gibi yakıyor Bak aylar geçti yıllar ise tuzak gibi bekliyor Yüreğim ...', ARRAY['Türk Edebiyatı','Şiir','Gönül Özdemir']::text[], 8.5, '{"poet":"Gönül Özdemir","poet_slug":"gonul-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/turku-yureklim-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocuk', 'cocuk-erdogan-ergin-f187b', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '''Uzun zamandır  çocuk olmak istiyorum, çocukca şeyler yapmak istiyorum. Belki aşağıdaki mısralarla başarmışımdır. Ne dersiniz, sizce başar mışmıyım? ''

Bir türkü versinler eline

Sen ondan, halka yap

Çevir kendince

Kendin ol, çocuk ol

Söyle tüm türküleri

Sessizce

Bir oyuncak versinler eline

Karşılıklı alma, 

Oyuncaksız ol

Ama bensiz olma

Çocuk', '''Uzun zamandır  çocuk olmak istiyorum, çocukca şeyler yapmak istiyorum. Belki aşağıdaki mısralarla başarmışımdır. Ne dersiniz, sizce başar m...', ARRAY['Türk Edebiyatı','Şiir','Erdoğan Ergin']::text[], 8.5, '{"poet":"Erdoğan Ergin","poet_slug":"erdogan-ergin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/cocuk-90-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaprağın Dönüşü', 'yapragin-donusu-altay-taskin-6ggu5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'atmosferi soluyan yeşil

kapında bir konuk

aç kapını

boyacı geldi

tenekesinde kahverengi

boyayacak seni

aylarca seyrettin yerleri

rüzgarla dans

yağmurla banyo

güneşle sessiz gülüş

ayla uyku

bitti şimdi

hepsine elveda

zil çalınca

boyan kuruyunca

bize de haber ver

bahar son bulunca

uğurlayalım seni', 'atmosferi soluyan yeşil kapında bir konuk aç kapını boyacı geldi tenekesinde kahverengi boyayacak seni aylarca seyrettin yerleri rüzgarla da...', ARRAY['Türk Edebiyatı','Şiir','Altay Taşkın']::text[], 8.5, '{"poet":"Altay Taşkın","poet_slug":"altay-taskin","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/yapragin-donusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Buna Gücün Yetmez', 'buna-gucun-yetmez-nurcan-yildirim-0sup8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gözlerin ayın hilali idi 

Her bakışın yeni başlangıçları müjdeledi 

Ve yeni umut tomurcukları atıldı yüreğime 

Senin tarafından hiç esirgenmeden 

Ve tomurcuklar yüreğimin en derinine 

Kök saldı, zamanla filizlendi, gonca verdi 

Yürekteki sevda çiçeği

Bizim sevda çiçeğimiz 

Yaban gülü kadar ilkel

Papatya kadar temiz 

Gül kadar asil 

Kasımpatı kadar hüzünlü 

Uyku çiçeği kadar mahzun

Kardelen kadar titrek 

Kaktüs kadar dikenli 

Orkide kadar sıcaktı 

Ama sevdam çiçeğimdi

Bizimkisi, 

Sen fideleri attın 

Ben büyüttüm

Adı olmayan sevdamın çiçeği bu 

Gözlerin dolan ayın gizeminde

Her bakışın hüznün habercisiydi 

Bakışların ürkek, tedirgin 

Gözlerin, gözüme deymedi bile 

Gözlerinin hilalini çalmışlar 

Yeni başlangıçlarını, ümitlerini almışlar

Ayrılık kurşununu sıktı güllerin yüreğine 

Hemde sevda çiçeğimizin üstüne 

Sen ne yaptın, bu yalan 

Bir bir öldürebilirmisin

Sevda çiçeğini, beslediğim bütün duyguları

Gücün yeter mi, öldürebilirmisin beni

Unuttun koca adam, unuttun 

İlk sevda çiçekleri, asla solmaz 

Ve asla ölmez

Buna gücün yetmez 

Unuttun koca adam, unuttun 

Beni unuttun, dünleri unuttun

Yaşanmışlıkları da unuttun

Beni unutma dedim. Beni unuttun

Unuttun koca adam, unuttun

İlk sevda çiçekleri, asla solmaz 

Ve asla ölmez

Buna gücün yetmez 

Beni unuttuğunu haykırma

Biliyorum bunların hepsini 

Rahat bırak beni çek git içimden

Sevda çiçeğimle bırak beni 

Unuttun koca adam, unuttun

İlk sevda çiçekleri, asla solmaz 

Ve asla ölmez

Buna gücün yetmez 

Sana değmez

Unuttun koca adam, unuttun

İlk sevda çiçekleri, asla solmaz 

Ve asla ölmez

Buna gücün yetmez', 'Gözlerin ayın hilali idi  Her bakışın yeni başlangıçları müjdeledi  Ve yeni umut tomurcukları atıldı yüreğime  Senin tarafından hiç esirgenm...', ARRAY['Türk Edebiyatı','Şiir','Nurcan Yıldırım']::text[], 8.5, '{"poet":"Nurcan Yıldırım","poet_slug":"nurcan-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":58,"source_url":"https://www.antoloji.com/buna-gucun-yetmez-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Murat''ım', 'murat-im-murat-aydindag-gtyrt', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'M_urat''ım yüreğim yorgun yüreğinde, 

U_kuları kaçıyor sensizliğin içinde, 

R_uyalarım sensiz bir kabus olmuş, 

A_şikın içimde kanıyor sensizliğin içinde, 

T_arihler yazıyorum aşkımızın her gününe, 

A_şkını yaşıyorum sensizliğin yokluğunda, 

Y_ağan yamurla ağlıyorum geceleri, 

D_ayanmak zok biliyorum sensizliğe bu, 

I_lık ilkbahar,aşkını arıyorum şu yağan, 

N_isan yağmurunda,bende sevmek istiyorum, 

D_oyasıya seni,ve bulmak istiyorum, 

A_şkını yeniden,bir ılık ilkbahar yağmuruyla, 

Ğ_önlü kapalı Murat''ın sevmeye bu gece de.', 'M_urat''ım yüreğim yorgun yüreğinde,  U_kuları kaçıyor sensizliğin içinde,  R_uyalarım sensiz bir kabus olmuş,  A_şikın içimde kanıyor sensiz...', ARRAY['Türk Edebiyatı','Şiir','Murat Aydındağ']::text[], 8.5, '{"poet":"Murat Aydındağ","poet_slug":"murat-aydindag","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/murat-im-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mustafa Kemal', 'mustafa-kemal-altay-taskin-nmjtf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Mustafa Kemal

                         sıcak sıcak güneş üstümüzde

Mustafa Kemal

                         pırıl pırıl ay gecelerde

Mustafa Kemal

                         ışık ışık şimşek gökyüzünde

Mustafa Kemal

                         ılık ılık rüzgar ovalarda

Mustafa Kemal

                         damla damla yağmur topraklarda

Mustafa Kemal

                         avuç avuç barış dünyada

Mustafa Kemal

                         kucak kucak sevgi insanlarda

Mustafa Kemal

                         al al bayrak kalplerde

Mustafa Kemal

                         seve seve anılır her yerde', 'Mustafa Kemal                          sıcak sıcak güneş üstümüzde Mustafa Kemal                          pırıl pırıl ay gecelerde Mustafa K...', ARRAY['Türk Edebiyatı','Şiir','Altay Taşkın']::text[], 8.5, '{"poet":"Altay Taşkın","poet_slug":"altay-taskin","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/mustafa-kemal-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kanıyor yürğim', 'kaniyor-yurgim-murat-aydindag-qupuj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'kanıyor yüreğim,gecenin karanliğindayım, 

yine sensizliğin ardından kalan, 

son ay ışığının vurduğu bir gece bitmek üzere, 

ve yeni bir gün doğuyor ardından, 

zamanın gectiği hızla batan günaşin ardından anlıyarum. 

Kara geceler benim tek sırdaşım, 

senin yokluğunu paylaşa bildiğim, 

ve gözyaşlarıma,hırcın rüzgarın ardından, 

yağan yamurla cevabı gelir, 

çılığıma çılığıyla garşılık verir. 

şimdi senden çok uzaktayım belki, 

ama aklımın her saniyesi kalbimin her atışı 

seninle carpıyor,ama kara geceler bile durdurmuyar, 

kanayan yüreğimi,şimdi sensiz bir dünya var önümde, 

sana kavuşmak bir hayale benziyor şimdi, 

ama ben seni düşlüyorum kanayan yüreğimle.......', 'kanıyor yüreğim,gecenin karanliğindayım,  yine sensizliğin ardından kalan,  son ay ışığının vurduğu bir gece bitmek üzere,  ve yeni bir gün ...', ARRAY['Türk Edebiyatı','Şiir','Murat Aydındağ']::text[], 8.5, '{"poet":"Murat Aydındağ","poet_slug":"murat-aydindag","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kaniyor-yurgim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnce Çizgi', 'i-nce-cizgi-nurcan-yildirim-hzf6m', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sevişme sonrası yorgunluk gibidir hüzün 

Cilveli bir aşifte gibi, oynar eğlendirir seni 

O ne 

Sonra maske düşer, 

Hüzündür o 

Daha biraz önce eğlendiren oyuncu 

Yüreğin kilitlenir hüzünde, kalırsın öylece

Ne yaptığını bilmezsin 

Ve anlarsın ki hüznü seviyorsun 

Ne garip dudaklarında tebessüm olmuş hüzün 

Bir o kadar çekici ve bir o kadar ürkütücüdür

Ama ne olursa olsun yaşatırsın kendini 

Sevgili hüzün, sen kimi zaman 

Gözümde yaş, Kimi zamanda 

Dudaklarımın tebessümü

Çoğu zamanda, çürüten oldun sol yanımı 

Aslında düpedüz gerçeksin, işte bu yüzden 

Kimi zaman ağlatıp, kimi zamanda güldürdün

Gerçekleri haykırdığın için bizlere 

Adını hüzün koyduk 

Sen ihanete uğrayan sevgilide

Oyuncağı elinden alınan çocukta 

Evladını toprağa veren ananın yüreğindesin

Sen herkestesin, hep yanımızda 

O hüznün habercisi gecelerde beklerim seni 

Süzülür girersin koynuma 

Beni benden alırsın 

Seninleyim istediğin olmuştur. 

Ve birden yok olursun yanımdan 

Ne geldiğin anlaşılır, ne gittiğin 

Hangi seviştiğin kadın kaldı ki yanımda sen kalasın 

Sevdim ulan seni 

Hiç kimsenin sevmediği kadar çok 

Çünkü sen benim tek gerçeğimsin', 'Sevişme sonrası yorgunluk gibidir hüzün  Cilveli bir aşifte gibi, oynar eğlendirir seni  O ne  Sonra maske düşer,  Hüzündür o  Daha biraz ön...', ARRAY['Türk Edebiyatı','Şiir','Nurcan Yıldırım']::text[], 8.5, '{"poet":"Nurcan Yıldırım","poet_slug":"nurcan-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/ince-cizgi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mavi Çılgınlık', 'mavi-cilginlik-altay-taskin-9pa5n', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'deniz/ elinde bir kadeh

masasında mezeler

karabulutlar/ doldurur şarabı

şişeler boşalır

içer içer doymaz deniz

çılgınlığa başlar

döner başı/ ayakları dolaşır

vurur kıyıya başını

canı yanmaz/ mutluluğunu paylaşır

sevincini ulaştırır göklere', 'deniz/ elinde bir kadeh masasında mezeler karabulutlar/ doldurur şarabı şişeler boşalır içer içer doymaz deniz çılgınlığa başlar döner başı/...', ARRAY['Türk Edebiyatı','Şiir','Altay Taşkın']::text[], 8.5, '{"poet":"Altay Taşkın","poet_slug":"altay-taskin","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/mavi-cilginlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sallantıda', 'sallantida-altay-taskin-0rr3m', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bir gidiş var ayrılığa karanlıklardan

hüznün şarkısı duyulur uzaklardan

çorak toprağın üstünde adımlar atılırken

doğanın eliyle ittiği yerler mi buralar

akıl düzeninin dengesi sallantıda

giriyoruz karanlıklara unutulmuş artık aydınlıklar', 'bir gidiş var ayrılığa karanlıklardan hüznün şarkısı duyulur uzaklardan çorak toprağın üstünde adımlar atılırken doğanın eliyle ittiği yerle...', ARRAY['Türk Edebiyatı','Şiir','Altay Taşkın']::text[], 8.5, '{"poet":"Altay Taşkın","poet_slug":"altay-taskin","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/sallantida-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adam Gibi Yazamadım', 'adam-gibi-yazamadim-nurcan-yildirim-qp9gw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Adam gibi sevdalanamadık 

Sevdaların boynu bükük 

Aşka borçluyuz 

Nice sevda türküleri söyledikte, hissedemedik

Sevdalarımız gibi yarım kaldı türküler 

Adamakıllı yaşatamadık aşkı 

Aşk hakikatli yürek arıyor

Sevdaları yaşatmak için 

Hiç öldürmeden, incitilmeden, özgürce 

Sınırsız dolu dizgin 

Yaşatabileceği bir yürekti isteği aşkın 

Aşk çıkarsız olmaktır

Her şeyi göze almak demektir

Adam gibi kızdık sevdiklerimize

Adamakıllı haykırdık isyanlarımızı 

Bir tek adam gibi sevmeyi beceremedik 

Adamakıllı bir şiir yazamadık 

Paylaşmadık güzel duyguları 

Bencilce hapsettik güzellikleri içimize 

Suçlumuz oldu aşk

Bizlere acı verdi dedik hep 

Oysa aşkı türkü tadında 

Sevda dilinde yaşayamadık 

Ve biliyorum adam gibi yazamadım yine', 'Adam gibi sevdalanamadık  Sevdaların boynu bükük  Aşka borçluyuz  Nice sevda türküleri söyledikte, hissedemedik Sevdalarımız gibi yarım kald...', ARRAY['Türk Edebiyatı','Şiir','Nurcan Yıldırım']::text[], 8.5, '{"poet":"Nurcan Yıldırım","poet_slug":"nurcan-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/adam-gibi-yazamadim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzde kaldım', 'guzde-kaldim-nurcan-yildirim-dzvtw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Akşam üstü, hüznü gözlerinde

Benim içimde kanayan yara, bakışların 

Ellerim üşüyor, tedirgin yarınlara sarılmakta

Kendi içimde mezarımı kazdım ellerimle 

Dudakların ateş parçası, eritirdi kutupları 

Benim buzuldan dudaklarımı çözemedin 

İçinde yeni baharın kıpırtıları 

Yazın şenliği üstünde 

Bense güzde kaldım', 'Akşam üstü, hüznü gözlerinde Benim içimde kanayan yara, bakışların  Ellerim üşüyor, tedirgin yarınlara sarılmakta Kendi içimde mezarımı kazd...', ARRAY['Türk Edebiyatı','Şiir','Nurcan Yıldırım']::text[], 8.5, '{"poet":"Nurcan Yıldırım","poet_slug":"nurcan-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/guzde-kaldim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dünya Dümeni', 'dunya-dumeni-altay-taskin-wnyud', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'kızma bana dümenim

acı oluyorsun

kayboluyoruz

tatlı oluyorsun

kayboluyoruz

sen bir köşede

ben bir köşede

düşünelim kendi kendimize

senin acın senindir

benim acım benim

senin tatlın benimdir

benimki de yine benim', 'kızma bana dümenim acı oluyorsun kayboluyoruz tatlı oluyorsun kayboluyoruz sen bir köşede ben bir köşede düşünelim kendi kendimize senin acı...', ARRAY['Türk Edebiyatı','Şiir','Altay Taşkın']::text[], 8.5, '{"poet":"Altay Taşkın","poet_slug":"altay-taskin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/dunya-dumeni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güller', 'guller-altay-taskin-ol4l8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'ben bir kelebek

kanatlarım renk renk

bir güneşli günde

girdim gül bahçesine

sevgilimin ikramı

çiçek tozları

doyamadım o güzel güne

uğruyorum sevgilime

aklıma gelince...', 'ben bir kelebek kanatlarım renk renk bir güneşli günde girdim gül bahçesine sevgilimin ikramı çiçek tozları doyamadım o güzel güne uğruyorum...', ARRAY['Türk Edebiyatı','Şiir','Altay Taşkın']::text[], 8.5, '{"poet":"Altay Taşkın","poet_slug":"altay-taskin","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/guller-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Paylaştıkça Seninle / Sessiz Aşkı Oynadık', 'paylastikca-seninle-sessiz-aski-oynadik-nurcan-yildirim-jlk2h', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Perde açıldı ve oyun başladı 

Senaryoyu ne ben biliyordum 

Nede sen

Baş rolü paylaştım seninle 

Farkında bile değildin oysa 

Oyunum tümü sana dahil idi 

Ben seveni sen sevmeyeni oynadın 

Çoğu zaman amatörce acemiliklerim oldu

Konuşmam, gereken her bölümde sustum 

Sessiz aşktı oynadığım 

Sufle  veren biriside yoktu 

Öylece kaldım, sessizliği oynadım 

Koca sahnenin bir ucunda sen 

Bir ucunda ben uzakları oynadık', 'Perde açıldı ve oyun başladı  Senaryoyu ne ben biliyordum  Nede sen Baş rolü paylaştım seninle  Farkında bile değildin oysa  Oyunum tümü san...', ARRAY['Türk Edebiyatı','Şiir','Nurcan Yıldırım']::text[], 8.5, '{"poet":"Nurcan Yıldırım","poet_slug":"nurcan-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/paylastikca-seninle-sessiz-aski-oynadik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Evet', 'evet-nurcan-yildirim-yvrly', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Öyle bir sevda olmalı ki bizimkisi 

Herkes şaşırmalı, öylece kalmalı

Utanmalı Leyla Leylalığından

Mecnun mecnunluğundan 

Öyle büyük şeyleri göze almalıyız ki 

Ferhat deldiği dağlardan, 

Şirin aşikar sözlerinden utanmalı 

Öyle farklı olmalıyız ki biz 

Herkes “vay be” demeli 

Göze alacağımız en basit şey ölüm olmalı 

Aşkı yüreğimizde öylesine yüce yaşatmalıyız ki 

Ayrılık ayrı düşmeli bizden 

Hüzün yanımıza yaklaşmamalı 

Her anı seninle paylaşmalıyım ki 

Yalnızlık yalnız kalışından utanmalı 

Evet şimdi 

Beni olduğum gibi kabullenip 

Her şeyi göze almaya razıysan 

Gerçek aşk için ver elini', 'Öyle bir sevda olmalı ki bizimkisi  Herkes şaşırmalı, öylece kalmalı Utanmalı Leyla Leylalığından Mecnun mecnunluğundan  Öyle büyük şeyleri ...', ARRAY['Türk Edebiyatı','Şiir','Nurcan Yıldırım']::text[], 8.5, '{"poet":"Nurcan Yıldırım","poet_slug":"nurcan-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/evet-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamak değilmidir aşk', 'yasamak-degilmidir-ask-murat-aydindag-kuscm', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Şimdiler sensiz geçiyor artık.

anlam veremiyorum günlerime,

ama hala seni düşlüyorum içimde,

ve seni sensizliğin içinde arıyorum,

karanlıklar benim tek sırdaşım olutor sensiz,

ve iştahla gülümsüyorum hayata,

ama yaşamak değilmidir aşk? 

bir dokunuş ellerine,bir öpüş dudaklarını,

sıcaklığını hissetmek,paylaşa bilmek birşeyleri,

ve hayatı kucaklamak yeni bir günde,

seninle yaşaya bilmek yanlızlıkları,

ama yaşamak değilmidir aşk? 

hayaller kurmak gece yarıları,

uyurken ismini sayıklamak,

uyandığında iyiki varsın diye bilmek,

söle bana bunların hapsi,

yaşamak değilmidir aşk?', 'Şimdiler sensiz geçiyor artık. anlam veremiyorum günlerime, ama hala seni düşlüyorum içimde, ve seni sensizliğin içinde arıyorum, karanlıkla...', ARRAY['Türk Edebiyatı','Şiir','Murat Aydındağ']::text[], 8.5, '{"poet":"Murat Aydındağ","poet_slug":"murat-aydindag","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yasamak-degilmidir-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Lanetlenmiş gibi', 'lanetlenmis-gibi-nurcan-yildirim-umssc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Geçmiş kahpece vurdu yüzüme 

Lanetlenmiş gibi ürkütücüydüm 

Tükürdü yarım kalan anılar yüzüme 

Her şey silindi birden aklımdan 

Birden gözlerin gözlerime aksetti 

Kanıyorlardı

Yaş değildi bunlar kandı damlayan gözlerinden 

Lanetlenmiş gibi ürkütücüydüm 

Kendimden korktum 

Senin gibi isyanda edemedim kadere

Çünkü bütün suç bendeydi 

Biliyorum ihanetin affı olmaz 

Ama inan pişmanım 

Ve sokak çocukları gibi korumasız 

Ve yalnız 

Geceden karanlık gözlerim 

Sana beni affet demeyeceğim 

Bana geri dön demeye yüzüm yok 

Ben aynalarda lanetlenmiş gibi yüzümü bırakacağım

Birde bu satırlar kalacak arkamdan 

Lanetlenmiş bedenim 

Buz gibi ceset olacak

Ceset Kalacak 

Ne olur bu satırlarımı okurken 

Gözlerin kanamasın artık 

Ve gül lanet büyü bozuldu artık 

Sana çok acı çektirdim 

Ben seni hiç hakketmedim

Ben yolumu seçtim 

Ve gül artık 

Lanet büyü bozuldu', 'Geçmiş kahpece vurdu yüzüme  Lanetlenmiş gibi ürkütücüydüm  Tükürdü yarım kalan anılar yüzüme  Her şey silindi birden aklımdan  Birden gözle...', ARRAY['Türk Edebiyatı','Şiir','Nurcan Yıldırım']::text[], 8.5, '{"poet":"Nurcan Yıldırım","poet_slug":"nurcan-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/lanetlenmis-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adımız Serseri', 'adimiz-serseri-galip-karabatak-7czug', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yanlış zamanlarda doğmuş yanlış adamlardık! 

Adımız bile yanlış yazılmıştı hüviyetimize

Ama onurluyduk

Ne bir karıncayı incittik ne de bir kavgadan kaçtık

En fazla şehrin duvarlarını kirlettik sevgilinin ismiyle

Hani yetmişliği devirdiğimiz o sarhoş gecelerde

Oysa bu yaptığımız bile

Tertemizdi bizim gözümüzde...

Toplanınca biraraya 

hep söverdik bu şehre

oysa,

şehir onlarındı, sokaklar bizim

dünya onlarındı,

sevdalar bizim! 

elinden şekeri alınmış ağlayan bir çocuk gibi,

avutulmak isteyen yüreğimize

hep deli dediler deli! 

anamızdan başka kimsenin bilmediği adımızaysa serseri! 

Oysa,

nerde bir kuşun kanadı kırılsa,

ilk bizim canımız acırdı

nerde bir ana ağlarsa

bizim gözlerimiz dolardı...

yani adamdık adam gibi! 

Ağlamasını da bilirdik sevmesinide

mahallenin kızlarının camlarda beklediği gençlerden de öte

sabahı camlarda bekleyen gençlerdik...

ölürdük ulan ölürdük! 

bir çift gözün hatrına ölürdük! 

kimseler görmezdi güneşin gözlerini

yalnızca biz görürdük! 

Dedim ya,

Yanlış zamanlarda doğmuş yanlış adamlardık

Ondandır heralde,

Herkesi bizim gibi “ADAM” sandık!', 'Yanlış zamanlarda doğmuş yanlış adamlardık!  Adımız bile yanlış yazılmıştı hüviyetimize Ama onurluyduk Ne bir karıncayı incittik ne de bir k...', ARRAY['Türk Edebiyatı','Şiir','Galip Karabatak']::text[], 8.5, '{"poet":"Galip Karabatak","poet_slug":"galip-karabatak","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/adimiz-serseri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bütün Zaferlerinin Bedeli Bu Kaybediş', 'butun-zaferlerinin-bedeli-bu-kaybedis-nurcan-yildirim-mkcdo', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sevmem artık, beklememde

Ne halin varsa gör 

Yana, yana dönen sen olacaksın 

Pişman olacaksın, sol yanın acıyacak 

Bu sefer  mağlup olacaksın 

Kazandığın tüm zaferlerin 

Bedeli olacak, bu kaybediş

Kapandığını sandığın, bütün yaralar açılacak 

Kanacaksın acıyacak içindeki bana ait o ufacık yer.

Vicdanın seslenecek, kendini suçlu hissedeceksin.

Ama hiç gerek yok

Senden bir karşılık beklemedim ki ben

Ne ah ettim, ne de kızdım.

Ben senin özgürlüğünü sevdim, dürüstlüğünü. 

Ama gerçeği anlayınca iş işten geçecek. 

Bana dönüşün geç kalan adaletin olacak. 

Ve mağlubiyetinle ezileceksin 

İşte o zaman Zafer benim  olacak

Çünkü sana cevabın

“Küllenen aşk, asla alevlenmez

Ey koca adam

İlk sevda çiçekleri asla solmaz

Ve asla ölmez

Buna gücün yetmez

Seni sevdim hala seviyorum 

Yarın sevebilir miyim 

Bilmiyorum? “', 'Sevmem artık, beklememde Ne halin varsa gör  Yana, yana dönen sen olacaksın  Pişman olacaksın, sol yanın acıyacak  Bu sefer  mağlup olacaksı...', ARRAY['Türk Edebiyatı','Şiir','Nurcan Yıldırım']::text[], 8.5, '{"poet":"Nurcan Yıldırım","poet_slug":"nurcan-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/butun-zaferlerinin-bedeli-bu-kaybedis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Utanma Erkekliğinden', 'utanma-erkekliginden-nurcan-yildirim-i9tkk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Benim şehrimden biliyorum 

Yok öyle bir anda çekip gitmek 

Beni terk etsen de bu şehri terk edemezsin 

En uzaklara kaçsan da

Düşer ruhum yollara bulur seni 

Yok, Yok öyle bir anda unutamazsın 

Zaman ister, bensizliğe alışmak

Önce seninle birlikte söylediğimiz 

Bütün şarkıları susturmalısın 

Hicaz makamından yalnızlığı

Dinlemeli, söylemelisin 

Beni sana soracak bütün eş, dosttan

Uzaklaşmak, kopmalısın

Sonra

Sana aldığım müzik kutusunu fırlatıp atmalısın

Paramparça olmak yüreğin gibi

Gök semayla anlaşma yapmalısın 

Yağmurlar benden sonra asla yağmamalı 

Her yağmurda yüreğine düşeceğim, eriyeceksin 

Benim şehrimden biliyorum 

Yok öyle bir anda çekip gitmek 

Beni terk etsen de bu şehri terk edemezsin

En uzaklara kaçsan da

Düşer ruhum yollara bulur seni 

Yok, Yok öyle bir anda unutamazsın 

Zaman ister, bensizliğe alışmak

Önce gözlerinden silmelisin, yıldız gözlerimi

Kulaklarından silinmeli gülüşüm, sesim 

Tenine mühür olan dokunuşlarım 

Uçup gitmeli, öylece kalmalısın

Beni her şeyimle hayatımdan çıkarmalısın 

Yani kendinden vazgeçmelisin

Buna cesaretin var mı? 

Yok, yok öyle benden vazgeçemezsin 

En uzaklara gitsen de 

Düşer yollara ruhum bulur seni 

Unuttum yalanına inandırmışken kendini

Gerçekler yüreğinde bir tokat gibi vuracak 

Kapandığını sandığın bütün yaralar kanayacak 

Anlayacaksın ki unutmak sadece koca bir yalandan ibaret.

Bu yalanla yüzleşmen en büyük gerçeğini ortaya çıkaracak.

Beni sevdiğini.

Ve şimdi ağla, ağlayabildiğin kadar 

Senle dolu ve senin için atan bu 

Yüreği kaybettiğin için 

Ağla ağlayabildiğin kadar 

Ağla erkeğim ağla', 'Benim şehrimden biliyorum  Yok öyle bir anda çekip gitmek  Beni terk etsen de bu şehri terk edemezsin  En uzaklara kaçsan da Düşer ruhum yol...', ARRAY['Türk Edebiyatı','Şiir','Nurcan Yıldırım']::text[], 8.5, '{"poet":"Nurcan Yıldırım","poet_slug":"nurcan-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/utanma-erkekliginden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ay', 'ay-altay-taskin-u0gfi', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'beni gözleyen

unuttuğum gecelerde

                         kırılmasın yanan lambam

                         ben unutsam da

                         gecelerim onunla geçiyor

ne yazık ki

o çok büyük

insan seçmiyor

bir kuytuda olsam da

                         gülüyor gülüyor gülüyor', 'beni gözleyen unuttuğum gecelerde                          kırılmasın yanan lambam                          ben unutsam da                  ...', ARRAY['Türk Edebiyatı','Şiir','Altay Taşkın']::text[], 8.5, '{"poet":"Altay Taşkın","poet_slug":"altay-taskin","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ay-27-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gün Yüzü Görmedim', 'gun-yuzu-gormedim-i-brahim-necati-gunay-v6cto', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Adın nedir sormadım

Sana gönül koymadım

Boşa koydum olmadı

Gönül sana doymadı

Sevdim olmadı

Övdüm olmadı

Adın nedir sormadım

Sana gönül koymadım

Devran döndü

Aşkımız söndü

Sözemi geldik

Gözemi geldik

Adın nedir sormadın

Sana gönül koymadım

Aşkta başa dönmedim

Seninle gün yüzü görmedim

Gözyaşlarımı silmedin

Bana sevgi vermedin

Adın nedir sormadım

Sana gönül koymadım.', 'Adın nedir sormadım Sana gönül koymadım Boşa koydum olmadı Gönül sana doymadı Sevdim olmadı Övdüm olmadı Adın nedir sormadım Sana gönül koym...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Necati Günay']::text[], 8.5, '{"poet":"İbrahim Necati Günay","poet_slug":"i-brahim-necati-gunay","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gun-yuzu-gormedim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yorgunum Deme....', 'yorgunum-deme-kadir-soyturk-jdchm', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Genç Kardeşime....

Hayırlı  evlat ol, ana - babana,

Açlıktan ölsen de, haramı yeme! 

Yakışmaz bu sözler, seninle bana; 

Kırgınım, dargınım, yorgunum deme! 

Bahane üretme, vurgunum deme! 

Kırgınım, dargınım, yorgunum deme! 

Bu vatan bekliyor bizden vazîfe

Kimimiz dadaştır,kimimiz efe

Kardeşine sarıl ve sev aşk ile

İnancına uymaz, dargınım deme! 

Bahane üretme, vurgunum deme! 

Kırgınım, dargınım, yorgunum deme! 

İlimle, irfanla, faziletle dol; 

Sabırlı, vefakar ve azimli ol! 

Daha kaç adım ki, kat ettiğin yol; 

Irmaklar hep akar; durgunum deme! 

Bahane üretme, vurgunum deme! 

Kırgınım, dargınım, yorgunum deme!', 'Genç Kardeşime.... Hayırlı  evlat ol, ana - babana, Açlıktan ölsen de, haramı yeme!  Yakışmaz bu sözler, seninle bana;  Kırgınım, dargınım, ...', ARRAY['Türk Edebiyatı','Şiir','Kadir Soytürk']::text[], 8.5, '{"poet":"Kadir Soytürk","poet_slug":"kadir-soyturk","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/yorgunum-deme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Al Beni Kelebek Yanına -Erdem Nur Cengiz''in Şiirine Nazire-', 'al-beni-kelebek-yanina-erdem-nur-cengiz-in-siirine-nazire-erdogan-ergin-mp92l', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '''Erdem Nur Cengiz Hanımın izin verdiği sürece yayınlanacaktır.''

Al beni kelebek yanına, 

nakış, nakış işlenmiş kanatlarına 

taşı beni, 

sevgiyi götürebileceğin 

en uzak şehre 

al beni kelebek yanına 

senin gibi 

doya doya yaşayayım 

bir günümü 

çiçek çiçek dolaşayım 

her çiçeğe 

bir gönül bırakayım 

al beni kelebek yanına', '''Erdem Nur Cengiz Hanımın izin verdiği sürece yayınlanacaktır.'' Al beni kelebek yanına,  nakış, nakış işlenmiş kanatlarına  taşı beni,  sevg...', ARRAY['Türk Edebiyatı','Şiir','Erdoğan Ergin']::text[], 8.5, '{"poet":"Erdoğan Ergin","poet_slug":"erdogan-ergin","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/al-beni-kelebek-yanina-erdem-nur-cengiz-in-siirine-nazire-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dünya Döner', 'dunya-doner-ramazan-ece-5w0x4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Şu dünya döner döndükçe

Çürütür bizi sürdükçe

Necât yok nefsi sevdikçe

Şu dünya döner döndükçe

Öğütür bizi  gittikçe! 

İbret almaz pek insanlar

Hakka dönmez inkârcılar

Tövbe etmez günâhkarlar

Şu dünya döner döndükçe

Öğütür bizi  gittikçe! 

Ecel bir gün gelir mutlak

Can çekilir dosttan ırak

İşte sonu kara toprak

Şu dünya döner döndükçe

Öğütür bizi  gittikçe! 

Salih âmel varsa felâh

Âmel kötü ise ey vâh

Büyük âzap görür billâh

Şu dünya döner döndükçe

Öğütür bizi  gittikçe! 

Zor günler gelmeden önce

Düşünelim biz güzelce

Dönelim Hakka erkence

Şu dünya döner döndükçe

Öğütür bizi  gittikçe! 

Mazlumların kurtuluşu

İnsanlığın mutluluğu

Müjde işte Hakkın yolu

Şu dünya döner döndükçe

Öğütür bizi  gittikçe! 

‘‘Ece’’ söyler yer geldikçe

Dinimiz İslâm dedikçe

Yaşayalım hep kardeşçe

Şu dünya döner döndükçe

Öğütür bizi  gittikçe! 

   Ramazan Ece  Danimarka / Odense', 'Şu dünya döner döndükçe Çürütür bizi sürdükçe Necât yok nefsi sevdikçe Şu dünya döner döndükçe Öğütür bizi  gittikçe!  İbret almaz pek insan...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Ece']::text[], 8.5, '{"poet":"Ramazan Ece","poet_slug":"ramazan-ece","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/dunya-doner-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaç mumluktu?', 'kac-mumluktu-gencay-coskun-b8gik', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kaç mumluktu 

Tavanımdaki ampul

Cılız odamı

Güneş tadında doldururdu

Yeterdi artardı bana 

Zaten kendini bilen için bu ışık 

Oysa bu ışığı 

Hiç gönlü görmeyenlerde vardı 

Umutla oynanırdı 

Hayat oyunu

Her yerine bir çentik atılırdı

Falanca tarihte ben buradaydım 

Unutulmak korkusundan yazılan 

Aslında bir zamanlar vardım mesajıydı

Sonra mı? 

Silinirdi mesajlar zamanda

Sabahı akşamı karışsa da hayatın 

Sonu karışmıyordu 

Hep aynı yere akıyordu 

Yalandan güçler bulup 

Peşine kurtarıcımız olur diye 

Üşüşen balıklardık 

Yar kollarında ölümü beklerken 

Otobüs duraklarında kalanlar olduk kimi zaman 

Kimi zaman 

Küstük 

Kimi zaman 

Coştuk

Hayatımı? 

Sonuna kadar 

Yaşadık 

Bir biçimde

Çok biçimde 

Başka bir biçimde

Ama tek bir biçimde 

Aynı yere gittik.', 'Kaç mumluktu  Tavanımdaki ampul Cılız odamı Güneş tadında doldururdu Yeterdi artardı bana  Zaten kendini bilen için bu ışık  Oysa bu ışığı  ...', ARRAY['Türk Edebiyatı','Şiir','Gencay Coşkun']::text[], 8.5, '{"poet":"Gencay Coşkun","poet_slug":"gencay-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/kac-mumluktu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Bekliyorum', 'seni-bekliyorum-zeynep-nilgun-gokceoz-sldm7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bana gelmelisin bir gece.

Seni beklerken kalbim yerinden fırlamalı.

En güzel kıyafetlerimi giymeliyim,

En güzel kokularımı sürmeliyim senin için.

Son bir kez daha bakmalıyım aynaya,

Kır çiçeklerini saçmalıyım heryere.

Vücudum alev alev yanarken kapı çalmalı.

Çocukça bir coşkuyla açmalıyım kapıyı.

Tıpkı suyun toprağa kavuşması gibi sarılmalıyım sana.

Kavrulan dudaklarımı öpmelisin,

Kollarında kaybolmalıyım.

Gözlerinle soymalısın beni.

Tek beden olmalıyız,

Kölesi olmalıyız duygularımızın.

Belki ilk ve son demeliyiz.

Yaprak gibi titreyip, nehirler gibi coşmalıyız.

Gözlerimizle konuşmalıyız.

Bulutların üstüne bir kuşun kanadında çıkmalıyız.

Yıldızlar yoldaşımız olmalı.

Kır çiçekleri yağmur gibi akmalı üstümüze,

Rüzgarın eşliğinde fısıldamalısın seni seviyorum diye.

Evet sevgilim bir gece gelmelisin bana.

Hayallerim bozulmadan, 

Yeni düşlerle yorulmadan,

Bir gece mutlaka gelmelisin bana.

18.12.2004', 'Bana gelmelisin bir gece. Seni beklerken kalbim yerinden fırlamalı. En güzel kıyafetlerimi giymeliyim, En güzel kokularımı sürmeliyim senin ...', ARRAY['Türk Edebiyatı','Şiir','Zeynep Nilgün Gökçeöz']::text[], 8.5, '{"poet":"Zeynep Nilgün Gökçeöz","poet_slug":"zeynep-nilgun-gokceoz","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/seni-bekliyorum-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son yaprak dökülüyordu', 'son-yaprak-dokuluyordu-gencay-coskun-329qa', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Son yaprak dökülüyordu 

Sonbaharın kollarında 

Geride kalacak 

Kuru bir hışırtı 

Islak kaldırımlardan başka 

Kayda değer hiçbir şey olmayacaktı

Zaten kayıt edenler 

Asla ortalıkta bulunmazdı 

Donuk yüzler cumhuriyetinde 

Yürümekte çok can sıkıyordu 

İçi içine sığmayan 

Dışı bu dünyaya hapsedilen 

Cezalı bedenlerdik 

Nereye ait olduğumuz 

Hiç belli değildi 

Tam benim dediğin yere 

Vaktin gelince gömülüyordun

Son yaprak dökülüyordu 

Sonbaharın kollarında

Biri gidiyordu 

Ellerinde yapraklarla', 'Son yaprak dökülüyordu  Sonbaharın kollarında  Geride kalacak  Kuru bir hışırtı  Islak kaldırımlardan başka  Kayda değer hiçbir şey olmayaca...', ARRAY['Türk Edebiyatı','Şiir','Gencay Coşkun']::text[], 8.5, '{"poet":"Gencay Coşkun","poet_slug":"gencay-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/son-yaprak-dokuluyordu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rekabet', 'rekabet-altay-taskin-6ovpw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'kıran kırana

suda iki çubuk

suyun kucağında

yarışıyorlar

biz insanlar

barutla ateş gibi

karşı karşıya

rekabet içinde

doğanın cömert kollarında

yarışıyoruz

dilimiz beynimiz ve adımlarımızla', 'kıran kırana suda iki çubuk suyun kucağında yarışıyorlar biz insanlar barutla ateş gibi karşı karşıya rekabet içinde doğanın cömert kolların...', ARRAY['Türk Edebiyatı','Şiir','Altay Taşkın']::text[], 8.5, '{"poet":"Altay Taşkın","poet_slug":"altay-taskin","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/rekabet-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Birazda Sen Çırpın Aşk', 'birazda-sen-cirpin-ask-ozkan-sahin-daqya', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Aşkı ben sevmedim

yok karşılığı

büyüğünede

küçüğünede

lanet olsun

kahrolsun

hiç olmasın

öl artık

yada

çık git

 yüreğimden

anlamam gerek

Aşk sen hiç olmadın

varmışın gibi

beni bitirdin

Aşk! çek git

hikayesin

kibirlenme

birazda

sen çırpın aşk

çok eğlendin...

 17-8-2000', 'Aşkı ben sevmedim yok karşılığı büyüğünede küçüğünede lanet olsun kahrolsun hiç olmasın öl artık yada çık git  yüreğimden anlamam gerek Aşk ...', ARRAY['Türk Edebiyatı','Şiir','Özkan Şahin']::text[], 8.5, '{"poet":"Özkan Şahin","poet_slug":"ozkan-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/birazda-sen-cirpin-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaygan Zemin', 'kaygan-zemin-altay-taskin-idzm8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'geri dönüşü olmayan

labirentin

kaygan zemininde

uçuyoruz sevinçten

kışın kızaklı çocukları gibi

ama biz sevinmeyelim

onlar dönüyorlar

başladıkları yere

aynı yerleri yeniden görüyorlar

biz ne başımızı

çevirebiliriz

ne de çevirmeye

fırsat bulabiliriz

zamanın kaygan 

ve acımasız zemininde...', 'geri dönüşü olmayan labirentin kaygan zemininde uçuyoruz sevinçten kışın kızaklı çocukları gibi ama biz sevinmeyelim onlar dönüyorlar başlad...', ARRAY['Türk Edebiyatı','Şiir','Altay Taşkın']::text[], 8.5, '{"poet":"Altay Taşkın","poet_slug":"altay-taskin","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/kaygan-zemin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eşime', 'esime-gulsah-suder-uzunmehmetoglu-lqkh5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Seni seveceğim

Sevgimi sana vereceğim

Seni seninle yaşarken

Sevgimi büyüteceğim

Seninle varolup 

Seninle biteceğim.

Seni seveceğim

Sensizliğe yemin ettim

Sevgini hak edeceğim', 'Seni seveceğim Sevgimi sana vereceğim Seni seninle yaşarken Sevgimi büyüteceğim Seninle varolup  Seninle biteceğim. Seni seveceğim Sensizliğ...', ARRAY['Türk Edebiyatı','Şiir','Gülşah Süder Uzunmehmetoğlu']::text[], 8.5, '{"poet":"Gülşah Süder Uzunmehmetoğlu","poet_slug":"gulsah-suder-uzunmehmetoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/esime-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İftira', 'i-ftira-erol-dal-gjp3m', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yüzündeki çamuru

Fırlatma...

Sil.....', 'Yüzündeki çamuru Fırlatma... Sil........', ARRAY['Türk Edebiyatı','Şiir','Erol Dal']::text[], 8.5, '{"poet":"Erol Dal","poet_slug":"erol-dal","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/iftira-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece Alemi', 'gece-alemi-altay-taskin-3f10t', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'doyulmuyor çığlıklarına şu gece aleminin

hep çağırıyor uykumda beni odasına

öğütleri dizi dizi koluma giren hayal kardeşimin

belki beş on saniyelik o toz pembelik

hiç mi hiç gerçekleşmiyor uyandığımda

güç ister gece ile gündüzleri değiştirmek için

o da biz de olamayacağına göre

gecelerim hayallerle gündüzlerim gerçeklerle

tek birşey varsa o gerçekleşmeyen

düşleri de kaybetmemek kısa gecelerde', 'doyulmuyor çığlıklarına şu gece aleminin hep çağırıyor uykumda beni odasına öğütleri dizi dizi koluma giren hayal kardeşimin belki beş on sa...', ARRAY['Türk Edebiyatı','Şiir','Altay Taşkın']::text[], 8.5, '{"poet":"Altay Taşkın","poet_slug":"altay-taskin","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/gece-alemi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur', 'yagmur-altay-taskin-tx79i', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'yalayarak gelir boşluğu

kara gözlü çatık kaşlı pamuklardan

kendiyle yarışarak

şaşırmadan yolunu

paraşütsüz yere çakılarak', 'yalayarak gelir boşluğu kara gözlü çatık kaşlı pamuklardan kendiyle yarışarak şaşırmadan yolunu paraşütsüz yere çakılarak...', ARRAY['Türk Edebiyatı','Şiir','Altay Taşkın']::text[], 8.5, '{"poet":"Altay Taşkın","poet_slug":"altay-taskin","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/yagmur-155-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni Anlat', 'beni-anlat-zeynep-nilgun-gokceoz-7evlp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Eski bir tanıdığı görürsen yolda,

Benden selam söyle ona.

Deki; 

Bir deniz ülkesinde yaşıyor.

Dalgalarla rüzgarlar yoldaş oluyor.

Hergün bir umutla uyanıp,

Güneşin doğuşuna bakıyor.

Her akşam umutlarını

Bir ertesi güne bırakıyor.

Ama onları beklemekten

Asla vazgeçmiyor.

16. 12. 2004', 'Eski bir tanıdığı görürsen yolda, Benden selam söyle ona. Deki;  Bir deniz ülkesinde yaşıyor. Dalgalarla rüzgarlar yoldaş oluyor. Hergün bir...', ARRAY['Türk Edebiyatı','Şiir','Zeynep Nilgün Gökçeöz']::text[], 8.5, '{"poet":"Zeynep Nilgün Gökçeöz","poet_slug":"zeynep-nilgun-gokceoz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/beni-anlat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanılma', 'yanilma-altay-taskin-qho52', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'sıcağım güneş renginde okşayan sözlere

kalbim dolar taşar sevgi köpükleriyle

dümenimde usta kaptan selam vererek maviliklere

uzar gider arkasında dost çizgileri

savunmasızdır gönül karşı konmadıkça

mahzundur duru su gibi gölde

gözümde barış kuşları uçar gider göklere

yansır göle çırpınan kanatların renkleri', 'sıcağım güneş renginde okşayan sözlere kalbim dolar taşar sevgi köpükleriyle dümenimde usta kaptan selam vererek maviliklere uzar gider arka...', ARRAY['Türk Edebiyatı','Şiir','Altay Taşkın']::text[], 8.5, '{"poet":"Altay Taşkın","poet_slug":"altay-taskin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yanilma-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşüyorum Kendime', 'dusuyorum-kendime-gencay-coskun-wcp3c', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Vuruldum 

Düşüyordum kendime 

Gül kurusu bir mevsimde

Vazgeçtim herşeyden 

Sonlarımı özlettiler 

İç kanaması akşamlarda 

Sonuna kadar 

Hüznü İçmediğim 

Hiçbir gece olmadı 

Gök yüzümde 

Yıldızlara hasrettim 

Soldum belki 

Kırıldım daha çok 

Hangi şiddet yıkabilirdi 

Ufacık yüreğimi 

Bir kainata sığdırmamışken

Bir söz 

Vuruverdi 

Acımadan 

Düştüm kendime 

İçimden ağladım 

Seller aktı yüreğime 

Alev alev yandım 

Cevap vermedim 

Günlerime 

Vazgeçtim Gidiyorum 

Vazgeçtim Soluyorum 

Vazgeçtim Kendimden 

Silin benden ne kalırsa 

Hiç düşünmeden iki kere 

Vuruldum 

Düşüyorum Kendime', 'Vuruldum  Düşüyordum kendime  Gül kurusu bir mevsimde Vazgeçtim herşeyden  Sonlarımı özlettiler  İç kanaması akşamlarda  Sonuna kadar  Hüznü...', ARRAY['Türk Edebiyatı','Şiir','Gencay Coşkun']::text[], 8.5, '{"poet":"Gencay Coşkun","poet_slug":"gencay-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/dusuyorum-kendime-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Lou''ya', 'lou-ya-murat-berk-3fzvw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben bir bulutum,

                                                                         Seni İçime alıp 

                                                                         Uçuracağım,

                                                                         Ve buharlaştırıp

                                                                         Yine

                                                                         Yatağıma Konduracağım.

                                                                         Islatacaksın beni

                                                                         Nisan yağmurları gibi,

                                                                         Ve sonbahar 

                                                                         Yağmurları gibi

                                                                         Ağlatacaksın,

                                                                         Şaşırtacaksın,

                                                                         Bir sevinip

                                                                         Bir düşüneceğim,

                                                                         Nerden geldiysen

                                                                         Oralara gidip şükredeceğim.', 'Ben bir bulutum,                                                                          Seni İçime alıp                                   ...', ARRAY['Türk Edebiyatı','Şiir','Murat Berk']::text[], 8.5, '{"poet":"Murat Berk","poet_slug":"murat-berk","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/lou-ya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öğretmenlerim', 'ogretmenlerim-altay-taskin-f7ogh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'doğa ders çalışma masam

zil çalınca derse girerim

rüzgar yağmur dolu sis kar

gerçek öğretmenlerim

sevinç hüzün düşünce

bunlardan öğrendiklerim

kahkahalar gözyaşları derine dalış

sorulara cevap verdiklerim

güneş ay ve yıldızlar

masamda gördüklerim

her zerre ses ışık

ömür boyu hep öğretmenlerim', 'doğa ders çalışma masam zil çalınca derse girerim rüzgar yağmur dolu sis kar gerçek öğretmenlerim sevinç hüzün düşünce bunlardan öğrendikler...', ARRAY['Türk Edebiyatı','Şiir','Altay Taşkın']::text[], 8.5, '{"poet":"Altay Taşkın","poet_slug":"altay-taskin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ogretmenlerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dolaşanlar', 'dolasanlar-altay-taskin-vyqbk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'gökyüzü doldursun boş torbalarına

ortalıkta dolaşan iblisleri

yeryüzünde görünmesin onlar kahpece

girmesinler temiz kalplere gölgeleriyle

çatal dilli mahluğun soğukluğu

yüce varlığın değmesin tenine

gerilmesin gölgeleri tatlı dile

güneşi ayı kapatmasın

gerçek görüntüsüyle

gündüz ve gece', 'gökyüzü doldursun boş torbalarına ortalıkta dolaşan iblisleri yeryüzünde görünmesin onlar kahpece girmesinler temiz kalplere gölgeleriyle ça...', ARRAY['Türk Edebiyatı','Şiir','Altay Taşkın']::text[], 8.5, '{"poet":"Altay Taşkın","poet_slug":"altay-taskin","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/dolasanlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benekli', 'benekli-altay-taskin-if6ml', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'kırmızı siyah benekli

üzüm bağları arasında

elma dallarında

uçar gelir konar elimize

dinlemek için ninnisini

''ali uç uç

şeytan kaç kaç''

uğur getirir

parmağımızın ucunda

açar kanatlarını

uçar gider

kendince uzaklara', 'kırmızı siyah benekli üzüm bağları arasında elma dallarında uçar gelir konar elimize dinlemek için ninnisini ''ali uç uç şeytan kaç kaç'' uğur...', ARRAY['Türk Edebiyatı','Şiir','Altay Taşkın']::text[], 8.5, '{"poet":"Altay Taşkın","poet_slug":"altay-taskin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/benekli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sarmaşık', 'sarmasik-altay-taskin-zpipl', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'yemyeşil sarmaşık

dolanır yukarıya

dolanmaya alışık

göklere doğru

kıvrıla kıvrıla

alımlı şık

seyreder yeryüzünü

yükseklerden

o sarmaşık', 'yemyeşil sarmaşık dolanır yukarıya dolanmaya alışık göklere doğru kıvrıla kıvrıla alımlı şık seyreder yeryüzünü yükseklerden o sarmaşık...', ARRAY['Türk Edebiyatı','Şiir','Altay Taşkın']::text[], 8.5, '{"poet":"Altay Taşkın","poet_slug":"altay-taskin","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sarmasik-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Az Kaldı...', 'az-kaldi-kadir-soyturk-kh30l', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ne arı var, ne de bal; ben nasıl edeceğim? 

Kalmışım tek başıma; yakında gideceğim !', 'Ne arı var, ne de bal; ben nasıl edeceğim?  Kalmışım tek başıma; yakında gideceğim !...', ARRAY['Türk Edebiyatı','Şiir','Kadir Soytürk']::text[], 8.5, '{"poet":"Kadir Soytürk","poet_slug":"kadir-soyturk","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/az-kaldi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zar Kanatlı', 'zar-kanatli-altay-taskin-w4jan', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'konma elimdeki demete

canını yakacaksan onların

sen uzakların sevgilisi

ayaklarında titreyen bir tutam

çiçektozu

kanatlarında da çöllerin acı öyküsü

korkuttu beni görünüşün

ne gezerdin o diyarda

en insancıl göstern

kon deseydim demetime

sanki bana bal mı getirirdin

yoksa o acı dikenini mi', 'konma elimdeki demete canını yakacaksan onların sen uzakların sevgilisi ayaklarında titreyen bir tutam çiçektozu kanatlarında da çöllerin ac...', ARRAY['Türk Edebiyatı','Şiir','Altay Taşkın']::text[], 8.5, '{"poet":"Altay Taşkın","poet_slug":"altay-taskin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/zar-kanatli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anneme', 'anneme-zeynep-nilgun-gokceoz-ig4fy', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bugün yine duygularım taşıyor yüreğimden,

Bugün yine hüzün dağıtıyorum anne.

Sıcak bir el arıyorum,

Özlemin ruhumun derinliklerinde anne.

Neden seni her düşündüğümde, aklıma düştüğünde

Gözyaşlarım beni dinlemez.

Onlarda biliyorlar seni çok özledim anne.

Dün rüyamda gördüm seni,

Mutluydun, aydınlıktın.

Gözlerime bakınca söylemek istediklerini anladım anne.

Bugün yine aklımdasın. 

Sanki bir yerden bana sesleneceksin,

Beni kucaklayıp öpeceksin.

Bazen seni yanımda hissediyorum,

Anne diye fısıldamak geliyor içimden.

Arkamı döndüğümde seni görmek,

Sıkıca sarılıp seni özledim demek istiyorum.

Beni anlıyorsun değilmi anne.

Şimdilik hoşçakal deyip başka rüyalarda,

Başka dünyalarda buluşmak üzere anne.

04.12.2004', 'Bugün yine duygularım taşıyor yüreğimden, Bugün yine hüzün dağıtıyorum anne. Sıcak bir el arıyorum, Özlemin ruhumun derinliklerinde anne. Ne...', ARRAY['Türk Edebiyatı','Şiir','Zeynep Nilgün Gökçeöz']::text[], 8.5, '{"poet":"Zeynep Nilgün Gökçeöz","poet_slug":"zeynep-nilgun-gokceoz","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/anneme-47-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vermek', 'vermek-ergun-terzioglu-itvru', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Vermek; 

En iyisi olsa gerek...

Vermek,

Vermek,

Vermek,

Son kez vermek; 

Boş vermek...', 'Vermek;  En iyisi olsa gerek... Vermek, Vermek, Vermek, Son kez vermek;  Boş vermek......', ARRAY['Türk Edebiyatı','Şiir','Ergün Terzioğlu']::text[], 8.5, '{"poet":"Ergün Terzioğlu","poet_slug":"ergun-terzioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/vermek-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Ulus Onunla Uyanıyor', 'bir-ulus-onunla-uyaniyor-i-brahim-necati-gunay-7h6bp', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Atamız Türk,Ceddimiz Türk

Önderimiz yüce ATATÜRK

Millet olarak verdik el ele

Vatanın sınırını cizdik şehitlerle

Sakarya,Anafartalar,Çanakkale

Ulu önderimizle hepimiz verdik el ele

Aç demedik,yok demedik,yürüdük yolları

Adsız kahramanların gözü yaşlı şehit ANALARI...

(www.ultrailan.com şairin özel şiir sitesi)

01.10.2005 tarihli Posta Gazetesinde yayımlanmıştır.', 'Atamız Türk,Ceddimiz Türk Önderimiz yüce ATATÜRK Millet olarak verdik el ele Vatanın sınırını cizdik şehitlerle Sakarya,Anafartalar,Çanakkal...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Necati Günay']::text[], 8.5, '{"poet":"İbrahim Necati Günay","poet_slug":"i-brahim-necati-gunay","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/bir-ulus-onunla-uyaniyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşüm''e!', 'dusum-e-erdem-nur-cengiz-v471b', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Perdelenmiş gençliğin,

Çocuksu iç geçirişlerin,

Gizil bir masumiyete teslim

Küllenmiş

Ama

Zaman zaman kor

Erkekliğinle

Sen

Ne derin

Ne ürkek ve

Ne çok

Sevgilisin,

Yazık ki 

Bende değilsin!', 'Perdelenmiş gençliğin, Çocuksu iç geçirişlerin, Gizil bir masumiyete teslim Küllenmiş Ama Zaman zaman kor Erkekliğinle Sen Ne derin Ne ürkek...', ARRAY['Türk Edebiyatı','Şiir','Erdem Nur Cengiz']::text[], 8.5, '{"poet":"Erdem Nur Cengiz","poet_slug":"erdem-nur-cengiz","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/dusum-e-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hedefim Belli Olsa...', 'hedefim-belli-olsa-kadir-soyturk-rnqhx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hedefim belli olsa, ziciri kıracağım; 

“Hürriyet benim hakkım “ diye haykıracağım!', 'Hedefim belli olsa, ziciri kıracağım;  “Hürriyet benim hakkım “ diye haykıracağım!...', ARRAY['Türk Edebiyatı','Şiir','Kadir Soytürk']::text[], 8.5, '{"poet":"Kadir Soytürk","poet_slug":"kadir-soyturk","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/hedefim-belli-olsa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bitti Artık', 'bitti-artik-ahmet-kurt-ew1j8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sevdiğim ardından bakar dururum,

Yıllar bitti, aylar bitti, gün bitti.

Sensiz geleceği nasıl görürüm,

Umut bitti, hayal bitti, düş bitti.

Zihnimi yokladı amansız yarış,

Gezdim zamanları sor karış karış,

Dediler yokluğa var sen de alış,

Yarın bitti, bugün bitti, dün bitti.

Yokluğa bir çare arar gözlerim,

Yavaş yavaş tutuluyor dizlerim,

Yüreğimden yüreğine sızlarım,

Ateş bitti, alev bitti, köz bitti.

Deryayı ararım, bu hasret bitmez,

Kapılar ses vermez dumanım tütmez,

Yazmaya mecalim ve gücüm yetmez,

Kağıt bitti, kalem bitti, söz biti.

Kurdoğlu bitmedi henüz hayatta,

İsyana yanaşmaz, ömrü sebatta,

Taşlarda, toprakta, bütün nebatta,

Nergis bitti, sümbül bitti, gül bitti.', 'Sevdiğim ardından bakar dururum, Yıllar bitti, aylar bitti, gün bitti. Sensiz geleceği nasıl görürüm, Umut bitti, hayal bitti, düş bitti. Zi...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Kurt']::text[], 8.5, '{"poet":"Ahmet Kurt","poet_slug":"ahmet-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bitti-artik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Akşam Güneşle Batayım Gitsin', 'bir-aksam-gunesle-batayim-gitsin-murat-nail-guney-2usre', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Şu kahpe dünyanın kaba yerine

Bir tekme de benden atayım gitsin,

Canım dediklerim hep beni sattı,

Tozunu dumana katayım gitsin…

Hep kara günümde,yalnız başıma

Yıkılmadan dudum,biteyim gitsin.

Bir lokma ekmeği zehir ettiler,

Bir zehir de kendim yutayım gitsin…

Sevgiye köleydim,dostluğa da kul,

Şu gönlümü azat edeyim gitsin.

Alev-alev yandım kimse bilmedi,

Şimdi duman-duman tüteyim gitsin…

Yıkıldı gönülde nice saraylar,

Kalan enkazında yatayım gitsin.

Bana yar olmadı,benden olanlar,

Ben de anasını satayım gitsin…

Muradım,deştiler gönül yaranı,

Gurbet elde koymadılar çareni,

Azrail’ im olsun,ahret yareni,

Bir akşam güneşle batayım gitsin…

18/12/2004   Bodrum    Murat Nail Güney', 'Şu kahpe dünyanın kaba yerine Bir tekme de benden atayım gitsin, Canım dediklerim hep beni sattı, Tozunu dumana katayım gitsin… Hep kara gün...', ARRAY['Türk Edebiyatı','Şiir','Murat Nail Güney']::text[], 8.5, '{"poet":"Murat Nail Güney","poet_slug":"murat-nail-guney","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bir-aksam-gunesle-batayim-gitsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüce İnsan Sen Bir Meleksin', 'yuce-i-nsan-sen-bir-meleksin-i-brahim-necati-gunay-68keb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Aşım''da aşın var

Herşeyim''de izin var

Ne güzel sözlerin var

Hamurum''da mayan var

Bana söylediğin iki çift sözün var

Doğru ol,herşeyi sev

Gezdin Anadoluyu

Her yanın''da terin var,

Yolların''da,okulların''da,camilerin''de emeğin var

Ey yüce insan hiç birin''de adın yazılı değil

Yunus Emre misali (yoktur senin emsalin)

Dünyaya az gelir senin gibisi

Bir baba desem değilsin

Bir arkadaş desem değilsin

Bir dost desem değilsin

Sen kelimelerle anlatılacak bir insan değilsin

Sen bizlerin kalbin''de,benliğin''de,yüreğin''de

Adeta bir Meleksin

Sen babalar günün''de hatırlanacak bir insan değil

Nefes alışım''da her şeyim''de her yerdesin

Sen koklanmakla bitmez,sen öpülmekle solmazsın

Ey yüce insan sen bir Meleksin

Çünkü sen:Torosların en güzel yerindensin

Seni sevmeyen ölsün,sürünsün.      

                                            16/06/1997 saat:21.45                                       Şiirin tüm hakları saklıdır.şairin izni olmadan iktibas edilemez.

Canım babacığım bizleri 21/05/2001 günü saat 09.30 da bırakarak bu fani dünyadan ayrılman  bizleri üzmekle, sana bu şiiri yazarak şahsının nazarın''da tüm babaların babalar gününü candan kutlarım. 15 / 06 / 2001.CUMA.', 'Aşım''da aşın var Herşeyim''de izin var Ne güzel sözlerin var Hamurum''da mayan var Bana söylediğin iki çift sözün var Doğru ol,herşeyi sev Gez...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Necati Günay']::text[], 8.5, '{"poet":"İbrahim Necati Günay","poet_slug":"i-brahim-necati-gunay","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/yuce-insan-sen-bir-meleksin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocuk Sen Gel', 'cocuk-sen-gel-bekir-mutlu-gokcesu-c4efl', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gel çocuk gel

Ağlasan da gel

Buna bile değer

Dünya güzel...

Yürü çocuk

Oyna, koş çabuk

Badem gözler

Ağlamasın

Boncuk, boncuk

Doy çocuk doy

Oy, oy, oy...

Gül çocuk...', 'Gel çocuk gel Ağlasan da gel Buna bile değer Dünya güzel... Yürü çocuk Oyna, koş çabuk Badem gözler Ağlamasın Boncuk, boncuk Doy çocuk doy O...', ARRAY['Türk Edebiyatı','Şiir','Bekir Mutlu Gökçesu']::text[], 8.5, '{"poet":"Bekir Mutlu Gökçesu","poet_slug":"bekir-mutlu-gokcesu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/cocuk-sen-gel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Gittin Karanlık Çöktü', 'sen-gittin-karanlik-coktu-barbaros-emre-eww7l', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ay ışığı vuruyor pencereme 

Tıpkı gözlerinin beni vurduğu gibi

Ben ne zaman aya baksam yüzünü 

Ne zaman yıldız görsem gözlerini anımsıyorum

Sen gözlerinle geceme ışık oldun 

Bir gece pencereme kondun

Seni tutup almak istedim 

Ama sen uçtun yok oldun 

Sen gittin gideli

Bir daha da gecelerim hiç aydınlık olmadı', 'Ay ışığı vuruyor pencereme  Tıpkı gözlerinin beni vurduğu gibi Ben ne zaman aya baksam yüzünü  Ne zaman yıldız görsem gözlerini anımsıyorum ...', ARRAY['Türk Edebiyatı','Şiir','Barbaros Emre']::text[], 8.5, '{"poet":"Barbaros Emre","poet_slug":"barbaros-emre","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sen-gittin-karanlik-coktu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Ne Zaman Düşünsem Seni', 'ben-ne-zaman-dusunsem-seni-barbaros-emre-4bpg8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ne zaman ay ışığı vursa odama

Ben yüzünü görür, sıcaklığını hissederim

Anlaşılmaz, garip bir huzur sarar beni

Seni düşündükçe rüyalarım şenlenir, sen kokar

İşte o an biteceğini bildiğim 

Bir anlık mutluluğu yaşamak için çırpınır

Bu tatlı hayal bitince yine

Kederlenir, yıkık yaşantıma dönerim', 'Ne zaman ay ışığı vursa odama Ben yüzünü görür, sıcaklığını hissederim Anlaşılmaz, garip bir huzur sarar beni Seni düşündükçe rüyalarım şenl...', ARRAY['Türk Edebiyatı','Şiir','Barbaros Emre']::text[], 8.5, '{"poet":"Barbaros Emre","poet_slug":"barbaros-emre","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ben-ne-zaman-dusunsem-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çok Uzaklardayım', 'cok-uzaklardayim-barbaros-emre-w6jgd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gayri öyle uzaktayım ki sana

Ne sesim gelir ne nefesim

Ne kadar uzak olsan da kokun gelir buram buram

Bana seni,sensizliği,hasreti getirir biraz

Ama seni, gülümü getirmez 

Gayrı bu hasret kor bana dayanamam

Yaşlı kalbim dayanmaz fazla göçer giderim', 'Gayri öyle uzaktayım ki sana Ne sesim gelir ne nefesim Ne kadar uzak olsan da kokun gelir buram buram Bana seni,sensizliği,hasreti getirir b...', ARRAY['Türk Edebiyatı','Şiir','Barbaros Emre']::text[], 8.5, '{"poet":"Barbaros Emre","poet_slug":"barbaros-emre","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/cok-uzaklardayim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Menzilsiz bir yoldayım', 'menzilsiz-bir-yoldayim-barbaros-emre-dkq80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Menzilsiz bir yoldayım 

Rota belli değil 

Işık yok karanlık 

Işığımı kaybetmişim

Sana gelen bu yolda umutsuzluğa gidiyorum(yürüyorum)', 'Menzilsiz bir yoldayım  Rota belli değil  Işık yok karanlık  Işığımı kaybetmişim Sana gelen bu yolda umutsuzluğa gidiyorum(yürüyorum)...', ARRAY['Türk Edebiyatı','Şiir','Barbaros Emre']::text[], 8.5, '{"poet":"Barbaros Emre","poet_slug":"barbaros-emre","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/menzilsiz-bir-yoldayim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutturamazsınız', 'unutturamazsiniz-barbaros-emre-vyskm', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ey dağlardan çağlayan nehirler

Hepiniz bir olsanız

Aksanız gönlüme

Söndüremezsiniz yanan ateşi

İçime oturan koru

Ey gökte uçan kuşlar

Bir olsanız uçsanız yarime

Erişip getiremezsiniz geriye

Sevdiğim kadını

Ey dağları saran sis 

Silemezsin onun hayalini aklımdan 	

Siz ne yapsanız da unutturamazsınız onu bana', 'Ey dağlardan çağlayan nehirler Hepiniz bir olsanız Aksanız gönlüme Söndüremezsiniz yanan ateşi İçime oturan koru Ey gökte uçan kuşlar Bir ol...', ARRAY['Türk Edebiyatı','Şiir','Barbaros Emre']::text[], 8.5, '{"poet":"Barbaros Emre","poet_slug":"barbaros-emre","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/unutturamazsiniz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutturamazsınız bana', 'unutturamazsiniz-bana-barbaros-emre-q6olz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ey dağlardan çağlayan nehirler

Hepiniz bir olsanız

Aksanız gönlüme

Söndüremezsiniz yanan ateşi

İçime oturan koru

Ey gökte uçan kuşlar

Bir olsanız uçsanız yarime

Erişip getiremezsiniz geriye

Sevdiğim kadını

Ey dağları saran sis 

Silemezsin onun hayalini aklımdan 	

Siz ne yapsanız da unutturamazsınız onu bana', 'Ey dağlardan çağlayan nehirler Hepiniz bir olsanız Aksanız gönlüme Söndüremezsiniz yanan ateşi İçime oturan koru Ey gökte uçan kuşlar Bir ol...', ARRAY['Türk Edebiyatı','Şiir','Barbaros Emre']::text[], 8.5, '{"poet":"Barbaros Emre","poet_slug":"barbaros-emre","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/unutturamazsiniz-bana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vurulmuş Yağmur Damlasıyım', 'vurulmus-yagmur-damlasiyim-yasar-yildiz-o2bfi', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Burgaçlara tutulmuşum maviyle yeşilin ortasında.

Sürükleniyorum sana, yelkenlerim paramparça.

Gözlerinle vurulmuş yağmur damlasıyım,

yıldızlarla, yakamozların arasında.

Aç avucunu, aç, düşüyorum..! 

Yalnızlık ormanda tekbaşınalıkta.

Fırtınalarında kırılmış dalucunda,

kuruyup düşemeyen tek yaprak olmakta.

Sarı soğuklarda yanıp, sana dokunamamakta.

Sarıl bana, sarıl, üşüyorum..!', 'Burgaçlara tutulmuşum maviyle yeşilin ortasında. Sürükleniyorum sana, yelkenlerim paramparça. Gözlerinle vurulmuş yağmur damlasıyım, yıldızl...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Yıldız']::text[], 8.5, '{"poet":"Yaşar Yıldız","poet_slug":"yasar-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/vurulmus-yagmur-damlasiyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nergis Çiçeği', 'nergis-cicegi-suskun-resital-btyjw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Çiçek kokusu gönderiyorum sana,

Senin gibi kokan.

Nergis çiçeği olsun adı,

Kokusunu senden çalan...

Bükük boynuyla,narin,zarif

Senin gibi masum duran

Serin kokusuyla usulca,hafif,

Seni en güzel sabahlara uyandıran

Bu sabah pencerenden içeri,

Süzülsün tarifsiz bir mutluluk,

Bil ki gittiğin günden beri

Kalmadı bende sevinç bak! 

Ne de umut,inan bir yudumluk...', 'Çiçek kokusu gönderiyorum sana, Senin gibi kokan. Nergis çiçeği olsun adı, Kokusunu senden çalan... Bükük boynuyla,narin,zarif Senin gibi ma...', ARRAY['Türk Edebiyatı','Şiir','Suskun Resital']::text[], 8.5, '{"poet":"Suskun Resital","poet_slug":"suskun-resital","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/nergis-cicegi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Esselâmüâleyke', 'essel-mu-leyke-ali-riza-unal-b5ef9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Esselâmüaleyke, o deryayı gönül püryânına

Esselâmûaleyküm, o sırrı lêdünün üryânına

Vessêlâmu esselâm, o dürü lisanın sultanına

     

Kalmadı gözümde nur

Gölümde gurur

Dilimde ferman

Dizimde derman

Can bulmuşum bu tende candan içeri

Sen bulmuşum bu bende senden içeri', 'Esselâmüaleyke, o deryayı gönül püryânına Esselâmûaleyküm, o sırrı lêdünün üryânına Vessêlâmu esselâm, o dürü lisanın sultanına       Kalmad...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/esselamualeyke-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocuk Uzak Yok Artık Sana', 'cocuk-uzak-yok-artik-sana-bekir-mutlu-gokcesu-hif3d', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '...

Geldin mi çocuk? 

Bak gördün mü? 

Uzak yok artık sana

Yok çocuk...

Ağlamayı tadıp

Gülmesini bildin

Aferin çocuk...

Düştün yola

Yürü 

En kararlı adımlarınla

Yolların hepsi

Çıkacaktır sana...', '... Geldin mi çocuk?  Bak gördün mü?  Uzak yok artık sana Yok çocuk... Ağlamayı tadıp Gülmesini bildin Aferin çocuk... Düştün yola Yürü  En ...', ARRAY['Türk Edebiyatı','Şiir','Bekir Mutlu Gökçesu']::text[], 8.5, '{"poet":"Bekir Mutlu Gökçesu","poet_slug":"bekir-mutlu-gokcesu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/cocuk-uzak-yok-artik-sana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bazen..', 'bazen-songul-ucar-rknz0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bazen yıldızlara bakıp,

Ne kadarda uzak dersin.

Bazen aynı yıldızlara

..sanki uzansan dokunacaksın!

Oysa yildızlar,

Ne ulaşılamayacak kadar uzak,

Ne de uzanip dokunacagin kadar yakın..

Her şey bir yurek-le/de başlar 

...ve biter...

Sen benim yıldızımsın...

yüreğine dokunmaya çalıştığım...

bazan çok uzak bazan yakın...

....ulaşamadığım! ...

ve belkide....

... hiç ulaşamayacağım.....

Yine de!

Bir gun dokunabilmek ugruna,

Her geceye umutla katlanacagim.

... belki o cansiz işığında 

Bir omur yanıp kavrulacağım...

Yine uzanacagim... yine uzanacagim!', 'Bazen yıldızlara bakıp, Ne kadarda uzak dersin. Bazen aynı yıldızlara ..sanki uzansan dokunacaksın! Oysa yildızlar, Ne ulaşılamayacak kadar ...', ARRAY['Türk Edebiyatı','Şiir','Songül Uçar']::text[], 8.5, '{"poet":"Songül Uçar","poet_slug":"songul-ucar","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bazen-37-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Yerdeyim Ne Gökte', 'ne-yerdeyim-ne-gokte-salih-ozalasan-vmcw1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yine karanlık bir gece

Yıldızlar ağlıyor çaresizliğime gökyüzünde

Yine bi-çareyim  bir köşede gizlice

Gökteki yıldızlar kadar bir yalnızlık gönlümde

Oysa ne hayallerim vardı kendimce

Sen varken sultandım ebedi yüreğimde

Hayallerim hüsrana dönüştü sen gidince

Şimdi arasına aldığım bir başım kaldı ellerimde

Yalnızlık acı tadını anlatamam yetmez cümle

Cehennem ateşleri yer aldı bir anda dilimde

Sıkıyor bedenimi ayaktan yer baştan gök kubbe

Seninle sensizim cismim artık ne yerde ne gökte

Y.tarihi 19-12-04

Salih ÖZALAŞAN', 'Yine karanlık bir gece Yıldızlar ağlıyor çaresizliğime gökyüzünde Yine bi-çareyim  bir köşede gizlice Gökteki yıldızlar kadar bir yalnızlık ...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ne-yerdeyim-ne-gokte-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlık..', 'yalnizlik-songul-ucar-y59k7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Puslu bir yalnızlığın içerisinde,

Ruhum don tehlikesiyle karşıkarşıya yazın ortasında...

Gelincikler kırağıyla solup gitsede

Çınarlar umursamaz neden dersiniz? 

Dolunun ardından baharı yaşıyorsa tabiat,

Donmak bile korkutamaz bu canı bilesiniz! ! ! !', 'Puslu bir yalnızlığın içerisinde, Ruhum don tehlikesiyle karşıkarşıya yazın ortasında... Gelincikler kırağıyla solup gitsede Çınarlar umursa...', ARRAY['Türk Edebiyatı','Şiir','Songül Uçar']::text[], 8.5, '{"poet":"Songül Uçar","poet_slug":"songul-ucar","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/yalnizlik-214-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Can Olmayınca', 'can-olmayinca-ali-riza-unal-f4ydg', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Neylerem bahtı sarayı

Tahtında salınan yar olmayınca...

İstemem narıma şifayı

Buseye can dem olmayınca

Dinlemem faydasız kaalı 

Gönlüme hal olan yar olmayınca

Görmesin dostlar hali viranımı

Açmaz o nur yüzümde

Zülfünü saçan can olmayınca', 'Neylerem bahtı sarayı Tahtında salınan yar olmayınca... İstemem narıma şifayı Buseye can dem olmayınca Dinlemem faydasız kaalı  Gönlüme hal ...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/can-olmayinca-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biz Sensiz Olamayız!', 'biz-sensiz-olamayiz-zulfikar-yapar-kaleli-56fbu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'font face=''TR ProseAntique'' color=''black'' size=''1''

Sen bizsiz olsan da, biz sensiz asla! 

Yavan aşımızın tuzu Ebuzer. 

Kahırlı yaşadık hep buruk, yasla 

Anasından ayrı kuzu Ebuzer.

Uzun gecelerde ensiz uykular 

Bir türlü tutmadı, densiz uykular 

Sattı beni sattı, sensiz uykular 

Yanık yüreğimin közü Ebuzer.. 

Elim varmaz, gücüm yetmez, naçarım 

Ne anadan, ne kuzudan geçerim. 

Kana kana gözyaşımı içerim 

Dizimde dermansız sızı Ebuzer.

Asla olmamalı bir bahanesi 

Ha! kapandı kapanacak hanesi 

Çingene kızında yıldız tanesi 

Hüzünlü gönlümün nazı Ebuzer.

Üç değil, dört değil sadece iki 

Seninle doluyuz kuzum inan ki 

Mevsimlerin acelesi var sanki! 

Hayat gerçeğinin yüzü Ebuzer.

Her şey ayan beyan, her şey açık, net 

Hak yaratır, canı verir emanet 

Der ki: “Yaşamaya biraz gayret et” 

Hadisin, ayetin özü Ebuzer.

Fiske gibi yanar, bir türlü sönmez 

Hovarda hayaller gerçeğe dönmez 

Gönül bu ölür de ağrısı dinmez 

Pembe dünyalarda dizi Ebuzer.

Duygular satarım hiç kimse almaz 

Bugünler de geçer yarına kalmaz 

Yıldızlar uyur da, gözlerim dalmaz 

Muska-ı Kübra’da yazı Ebuzer.

Dededen yadigâr kalan bu adın 

Kiri olmamalı, ne kız, ne kadın 

Zirveyi zorlamak olsun muradın 

Hamiyet ehlinin sözü Ebuzer.

Umut ile hayal sorun yaşamaz 

Baba dede olmaz, torun yaşamaz 

Sen olmazsan eğer yarın yaşamaz 

Mazinin Atiye izi Ebuzer.

Aç karın guruldar,ağız kokarmış 

Sular susuz bir kanaldan akarmış 

Ateş her düştüğü yeri yakarmış 

Boynu bükük koydun bizi Ebuzer.', 'font face=''TR ProseAntique'' color=''black'' size=''1'' Sen bizsiz olsan da, biz sensiz asla!  Yavan aşımızın tuzu Ebuzer.  Kahırlı yaşadık hep b...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/biz-sensiz-olamayiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşığım', 'asigim-saliha-turan-o3n3m', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ben hayata aşığım

Bitipte tükenmeyen özlemlere

Gözlerinin irin noktasında keşfettiğim o dünyaya

Maviye aşığım gökyüzü gibi

Yüregimin Afrikasında yaşarken sevginin susuzluğunu

Bir buluta aşığım yağmur gibi

Bir umuda aşığım kardelenin direnişi misali 

En tuhaf özlemlere sarılmış çocukluğuma

Belki de sevmeye aşığım ben

SEVEREK GÜZELLEŞTİRMEYE...', 'Ben hayata aşığım Bitipte tükenmeyen özlemlere Gözlerinin irin noktasında keşfettiğim o dünyaya Maviye aşığım gökyüzü gibi Yüregimin Afrikas...', ARRAY['Türk Edebiyatı','Şiir','Saliha Turan']::text[], 8.5, '{"poet":"Saliha Turan","poet_slug":"saliha-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/asigim-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kızıma', 'kizima-cem-han-n79rz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Şansın akar sular gibi çağlasın,durmasın.

Sağlığın,asırlık zeytin ağaçları gibi olsun uzun yaşasın.

Gönlün yeni açan çiçek gibi olsun,solmasın.

Yaşamı paylaşmak istediklerin yanında olsun kaybolmasın.

Hayat sana daima gülsün,güldürsün,

Mutluluğun bitmesin hep sürsün 

Hayatın boyunca acıyı görme sevinci yakala

Doğum günü başarı taşısın sevgili kızıma.', 'Şansın akar sular gibi çağlasın,durmasın. Sağlığın,asırlık zeytin ağaçları gibi olsun uzun yaşasın. Gönlün yeni açan çiçek gibi olsun,solmas...', ARRAY['Türk Edebiyatı','Şiir','Cem Han']::text[], 8.5, '{"poet":"Cem Han","poet_slug":"cem-han","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kizima-177-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstiyorum :)', 'i-stiyorum-songul-ucar-nduua', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bazen,

Yetmiyor karanlıkları aydınlatmaya güneş.

Bazen dikenleri, 

Bazen dağları aşmak imkansız...

Bazen ısıtmıyor elleri ateş,

Bazen tüm yollar çıkarsız...

Böyle bir dünyada olmasın insan..! 

Sevdasız,kayıtsız,umarsız...

Olmasın uzak yürekler..! 

Uzak gözler bedenler...

Bakarken gözler gözlere,

Aksın diğerine istiyorum.

Severken birbirini yürekler,

Bir bedende gibi atsın istiyorum.

Tutarken elleri eller,

Duygular, düşünceler ve yürekler orda! 

Tamda oldukları yerde olsun istiyorum.

Büyüyünce farklı olmasın yarınlar,

Çocuk dünyalardaki umutlarda olsun...

Olsun istiyorum..', 'Bazen, Yetmiyor karanlıkları aydınlatmaya güneş. Bazen dikenleri,  Bazen dağları aşmak imkansız... Bazen ısıtmıyor elleri ateş, Bazen tüm yo...', ARRAY['Türk Edebiyatı','Şiir','Songül Uçar']::text[], 8.5, '{"poet":"Songül Uçar","poet_slug":"songul-ucar","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/istiyorum-43-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olduklarımı aradım biraz da sende', 'olduklarimi-aradim-biraz-da-sende-hasan-sun-348ua', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '(merhamet dilenen bir isyancı

ile

yatağından rahatsız bir nehir

bir değil) 

ayinler yapan bir tanrı-

                            tanımazdın

ninniler söyleyen bir bebek

uyu hadi... uyut kendini

ayıklık zor iş

               (14 kasım 2003/ çorum)', '(merhamet dilenen bir isyancı ile yatağından rahatsız bir nehir bir değil)  ayinler yapan bir tanrı-                             tanımazdın ...', ARRAY['Türk Edebiyatı','Şiir','Hasan Sun']::text[], 8.5, '{"poet":"Hasan Sun","poet_slug":"hasan-sun","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/olduklarimi-aradim-biraz-da-sende-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rast Geldin', 'rast-geldin-cem-han-a3z3f', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Niyet tuttuğum,gökteki kayan yıldız mıydın

Gözlerimi kamaştıran,bakamadığım Güneş miydin

Soğuk kış günlerinde solmayan beyaz gül müydün 

Ay ışığının sudaki izi miydin

Yoksa çöldeki bulunamayan bir yudum su muydun

Denizdeki balık mıydın ki bana rast geldin,

Çok bekledim seni,senelerce neredeydin', 'Niyet tuttuğum,gökteki kayan yıldız mıydın Gözlerimi kamaştıran,bakamadığım Güneş miydin Soğuk kış günlerinde solmayan beyaz gül müydün  Ay ...', ARRAY['Türk Edebiyatı','Şiir','Cem Han']::text[], 8.5, '{"poet":"Cem Han","poet_slug":"cem-han","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/rast-geldin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Bari Vurma..', 'sen-bari-vurma-nusret-akbayir-roar1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gelen vurdu.. giden vurdu..bu kula.. 

Ne olursun... sen bari vurma.. 

Kem talihimi.... çıkarıpta karşıma.. 

Çaresiz bıraktın.. gittin..en sonunda.. 

Bir gün olsun çıkıp gelmezken yanıma.. 

Yakıp kül ettin beni.. ümitsiz aşkınla.. 

Bakmayıp.. gözümden akan yaşlara.. 

Kolumu kanadımı kırdın.. son anda.. 

Bir mecnun.. bırakıp gittin... burada.. 

Sahipsiz mezarlar gibiyim uzaklarda.. 

Sevende.. sevmeyende.. unuttu.. 

Ne olursun... sen bari unutma.. 

..

25/08/2003./n.a./ İzmir.

_________________', 'Gelen vurdu.. giden vurdu..bu kula..  Ne olursun... sen bari vurma..  Kem talihimi.... çıkarıpta karşıma..  Çaresiz bıraktın.. gittin..en so...', ARRAY['Türk Edebiyatı','Şiir','Nusret Akbayır']::text[], 8.5, '{"poet":"Nusret Akbayır","poet_slug":"nusret-akbayir","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sen-bari-vurma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sanma', 'sanma-ali-riza-unal-riwoo', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ne beraberlikler var biribirinden uzak

Ne ayrılıklar var her an beraber

Akıl put olmuş gönülden bi haber

Gönül olmaz ise var mı sevgiye durak

O gönül ki akıla miracı Burak

Ne hale getirdi aklı iblisi

Şimdi o garibi laneye bak

Varlık benlik bir garip tuzak

Kin ile hasedin nefsine azap

Sanmaki ölüm resuldan uzak

Ne oldu belkısın tahtı sarayı

Şimdi mülkü Süleyman''a bak', 'Ne beraberlikler var biribirinden uzak Ne ayrılıklar var her an beraber Akıl put olmuş gönülden bi haber Gönül olmaz ise var mı sevgiye dura...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sanma-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Giderken', 'giderken-tevfik-karinca-p4k3c', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'sabahçı kahvesidir gönlüm

gittiğinde hoş bir seda kalır gülüm

beni kurşunlara diz yüreğinde

son kez bakarken gözlerime', 'sabahçı kahvesidir gönlüm gittiğinde hoş bir seda kalır gülüm beni kurşunlara diz yüreğinde son kez bakarken gözlerime...', ARRAY['Türk Edebiyatı','Şiir','Tevfik Karınca']::text[], 8.5, '{"poet":"Tevfik Karınca","poet_slug":"tevfik-karinca","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/giderken-49-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ateşlerde DANS Ettik!', 'ateslerde-dans-ettik-ozan-si-ar-agdasan-x3xr7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir uyandık şafak tandı 

Sevdamızda canan candı 

Pistimizde ‘alev’ yandı 

Köz ateşlerde dansettik 

Gece karanlığı yardık 

Ölümü yaşamla kardık 

Bedeni baruta sardık 

Alev eşlerde dansettik 

Şiar aşkı verdik çarka 

Bileğlendik, aktık ark’a 

Biri böldük ona-kırk’a 

Üçler-beşlerde dans ettik! ... 

Söz ve Müzik: Ozan ŞİAR  Ağdaşan Yorum: Aşık ŞAHTURNA 

Yabancı dillere çeviri: ŞİRİN ŞAFAK AĞDAŞAN Müzik Grubu 

Not: Avrupada Şiir yarışmasında, ''2003 yılında Ödül alan eserimizi''...Siz Sevgili Şiir Dostları ile paylaşmaktan kıvanç duyuyorum. 

Sevgiyle kalın, umudunuz solmasın! ... 

www.siarcan.com [email protected]', 'Bir uyandık şafak tandı  Sevdamızda canan candı  Pistimizde ‘alev’ yandı  Köz ateşlerde dansettik  Gece karanlığı yardık  Ölümü yaşamla kard...', ARRAY['Türk Edebiyatı','Şiir','Ozan ŞİAR Ağdaşan']::text[], 8.5, '{"poet":"Ozan ŞİAR Ağdaşan","poet_slug":"ozan-si-ar-agdasan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ateslerde-dans-ettik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocuk Yakın da Yok', 'cocuk-yakin-da-yok-bekir-mutlu-gokcesu-e9eaw', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '...

Yakında yok çocuk

Yok yakın...

Önce 

Kendini kendinden sakın

Sana en yakın avuçların

Aklın ve vicdanın

Karıştır, yoğur

Senin bu hamur

Hadi artık zamanıdır

İyi bir şeyler yapmanın

Yapamasan bile önemli değil

Yeter ki gayret et, niyetlen

Eğer hak edersen

Yarın sana çok yakın...', '... Yakında yok çocuk Yok yakın... Önce  Kendini kendinden sakın Sana en yakın avuçların Aklın ve vicdanın Karıştır, yoğur Senin bu hamur Ha...', ARRAY['Türk Edebiyatı','Şiir','Bekir Mutlu Gökçesu']::text[], 8.5, '{"poet":"Bekir Mutlu Gökçesu","poet_slug":"bekir-mutlu-gokcesu","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/cocuk-yakin-da-yok-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaralı Kuşum...!', 'yarali-kusum-asik-sahturna-6yy76', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hasret kaldım gül kokuna

Emdiğim sütün akına

Takıldım zulmün okuna

Yetiş kaldım darda anam! ... 

       Nakarat: Ben bir yaralı kuş idim

                       Hasret çekene düş idim

                       Yerlere düştüm üşüdüm

                       Kurtar beni karda anam! 

                                                    Gönülde şahım atlandı

                                                    Gecem gündüze katlandı

                                                     Umutlarım kanatlandı

                                                     Koyma beni zarda anam

   Şah Turna’yım samah çeker

   ‘Bin üzülür, bir ah çeker...

   Her gece bir sabah çeker

   Yetiş kaldım darda anam! 

 Söz ve Müzik: Aşık Şah Turna (Ozan Şahturna)       www.sahturna.com 

 Düzenleme-Yorum: Ozan Şiar Ağdaşan    www.siarcan.com 

 Aranje: Şirin&Şafak AĞDAŞAN Müzik Grubu

''Acılar Bir Gün Bal Olur'' albümü, ''Şakıyan Turna ŞAHTURNA'' Can Yayın', 'Hasret kaldım gül kokuna Emdiğim sütün akına Takıldım zulmün okuna Yetiş kaldım darda anam! ...         Nakarat: Ben bir yaralı kuş idim    ...', ARRAY['Türk Edebiyatı','Şiir','Aşık Şahturna']::text[], 8.5, '{"poet":"Aşık Şahturna","poet_slug":"asik-sahturna","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yarali-kusum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocuk Yılma', 'cocuk-yilma-bekir-mutlu-gokcesu-rr6n9', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yılma çocuk ağlama

Kızıyorum sana...

Görüyorsun işte

Bir çuval dolusu

Hayallerimi çaldılar

Ve bir avuç gökyüzümü

Benim...

Ben ağlıyor muyum? 

Hala gülüyor gözlerim...', 'Yılma çocuk ağlama Kızıyorum sana... Görüyorsun işte Bir çuval dolusu Hayallerimi çaldılar Ve bir avuç gökyüzümü Benim... Ben ağlıyor muyum?...', ARRAY['Türk Edebiyatı','Şiir','Bekir Mutlu Gökçesu']::text[], 8.5, '{"poet":"Bekir Mutlu Gökçesu","poet_slug":"bekir-mutlu-gokcesu","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/cocuk-yilma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elif''in Mahareti', 'elif-in-mahareti-ekrem-sama-l8294', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu günkü harflere şöyle bak,

Kimi keskin kimi yuvarlak,

''Elif''te hiçbir kusur var mı? 

Onunla yazılıp okunur Hak...

(İstanbul:18.12.2004)', 'Bu günkü harflere şöyle bak, Kimi keskin kimi yuvarlak, ''Elif''te hiçbir kusur var mı?  Onunla yazılıp okunur Hak... (İstanbul:18.12.2004)...', ARRAY['Türk Edebiyatı','Şiir','Ekrem Şama']::text[], 8.5, '{"poet":"Ekrem Şama","poet_slug":"ekrem-sama","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/elif-in-mahareti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ziya Paşa', 'ziya-pasa-ekrem-sama-tfcez', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '(Nush ile yola gelmeyeni etmeli tekdir/ Tekdir ile uslanmayanın hakkı kötektir...

Ziya Paşa) 

Paşa! Nush dediğin nasihat mi ola? 

Bu gün nasihatle kim gelir ki yola? 

Sen yine dinden imandan bahsedersin,

Anlayan olur mu bu çağda, ne dersin? 

Tekdir edecek mişsin, hele bir dene; 

Silahlı korumalar, çökerler ensene,

Çekerler bir köşeye verirler cevap,

Niyazi olmak da var, işlerken sevap.

Şu kötek sözü! Sakın ha paşa sakın! 

Kötüye fiske mi, ne haddin ne hakkın? 

Paşa bile düşünce medya diline,

Kapıp verirler yargısız linç seline...

Cunta devrinde miyiz ki, hangi kötek? 

Paşaya yakışır mı insan dövdürmek? 

Sonra sakın  ''paşa''yım da deme bana; 

Devrim kanunları hesap sorar sana.

Bu gün ''general''lik bir mi ''paşa''lıkla? 

Şanını şöhretini kendine sakla.

Sen yüzyılında kal, Osmanlı''da yaşa,

Bu asırda israf olur ''Ziya Paşa''! ! ! ..

(İstanbul:18.12.2004)', '(Nush ile yola gelmeyeni etmeli tekdir/ Tekdir ile uslanmayanın hakkı kötektir... Ziya Paşa)  Paşa! Nush dediğin nasihat mi ola?  Bu gün nas...', ARRAY['Türk Edebiyatı','Şiir','Ekrem Şama']::text[], 8.5, '{"poet":"Ekrem Şama","poet_slug":"ekrem-sama","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/ziya-pasa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Esrarlı düşlerim', 'esrarli-duslerim-dogan-sahin-b45iq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Uzunca bir süredir birlikteydi

(denilebilir) 

Kadınla, o

Hep hayal kurardı bir sonraki 

Kapıyı nasıl yakalayacak

Hiçbir zaman o kapının arkasını

Göremeden.

Ve halı temizlikçisi geldi bir gün

(çağdaş beden köleleri diyelim; batıdan temsilen) 

9 donlu bir kel adam

Aldı temizlikçi adam:

Kazanırım bu gurbette

Din adamı

Üniversite mezunuyum ben

Lakin çocuklar çok para kazanmaktan

Geldiler on beşine

Üniversiteye giremeden para bol

Ama kazanırım binlerce doları bir anda”

Gevşedi parayı hep babasının cüzdanında gören kız kadın

Yanında kocasının, dedi 

“ Bana da öğretsene 

Kazanmak için para 

Parladı gözleri paramparça

O parada” bebeli memelerinin arasından.

Koca, adam,

“Para değildir önemli olan dedi”

Adam, son bir çabayla, 

Ağzını bıçak açmıyordu oysa! 

“Sen şairsin” dedi kadın “ne anlarsın paradan”,

“oysa ben istiyorum onu 

Bilir bunu yaradan

Sen hep korkuttun beni

Korktum senin bu sevgisizliğinden

Ben de faydalanmak 

İsterim

Dedi

Bilir yaradan

Dünya nimetlerinden

“çok gençtim ben” dedi

“Sendin o benim hayatımı karartan”

Baştan beridir mimliydi dul adam:

Akrabalar da demişti ona ya

“Dikkat et! ” 

Yakar seni bu adam.

Kadın yanmıştı oysa 

Bilemezdi kösnül babası

Çoktan bilmekteydi yaradan

Bir sınıftan diğer sınıfa atlamak mı? 

Aman, aman

Dikkat edin

Yapmayın aman

Davul bile çalar dengi dengine 

Sakının seveni paradan.', 'Uzunca bir süredir birlikteydi (denilebilir)  Kadınla, o Hep hayal kurardı bir sonraki  Kapıyı nasıl yakalayacak Hiçbir zaman o kapının arka...', ARRAY['Türk Edebiyatı','Şiir','Doğan Şahin']::text[], 8.5, '{"poet":"Doğan Şahin","poet_slug":"dogan-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":53,"source_url":"https://www.antoloji.com/esrarli-duslerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Namus', 'namus-dogan-sahin-y46eq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ben

Anılarımı paylaşamam

Kadınımı ve dölümü

Güvenemem

Veremem

Hep geciktirmişim anlamayı

Dememeli insan

Çok geç olmadan

Aldanamam', 'Ben Anılarımı paylaşamam Kadınımı ve dölümü Güvenemem Veremem Hep geciktirmişim anlamayı Dememeli insan Çok geç olmadan Aldanamam...', ARRAY['Türk Edebiyatı','Şiir','Doğan Şahin']::text[], 8.5, '{"poet":"Doğan Şahin","poet_slug":"dogan-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/namus-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aslı Bende Saklı', 'asli-bende-sakli-guler-ilgaz-fkdqh', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Biliyordu

Aslı  bende  saklı  diyordu...

Damla  olup  akıyordu.

Doldurmak,boşaltmak   istiyordu

Alemi içinde...

......................

Aslı  bende  saklı

Kerem  bir  yol  bulur  nasılsa..

Yürür  içimde  diyordu...

Bir  Kerem  bir  Aslı  oluyordu...

..............

Aslında Aslı''da   Kerem''de  biliyordu   ya

Saklı sandıklarını   içinde  bulacaklarını

Birbirlerine  yoldaş  olacaklarını...

Bu  yolla

Birbirlerini  bulacaklarını.....! ! ! 

.................

Deldi  ya bu  yüzden  dağları

Kerem  bulmak  için

Aşk yaşıyor  ya  işte

İçimizde  bu  yüzden......

................

Yürüyor  öyküleri   şimdi''de

Yürekleri   körüklüyor  ya  hala..

Aslı  bende  saklı  diyor.

Alem   içinde  dağlara.

Meydan  okuyor  ya  çağlara,,,

Bilemediğimiz..........', 'Biliyordu Aslı  bende  saklı  diyordu... Damla  olup  akıyordu. Doldurmak,boşaltmak   istiyordu Alemi içinde... ...................... Aslı ...', ARRAY['Türk Edebiyatı','Şiir','Güler Ilgaz']::text[], 8.5, '{"poet":"Güler Ilgaz","poet_slug":"guler-ilgaz","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/asli-bende-sakli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Evlat Acısı Şiiri', 'evlat-acisi-siiri-dogan-sahin-osdvu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Avustralya’da bir göçmendi:

Bilemezdiniz

Hiç bir zor onu egemenliğine alacak kadar 

zorlu değildi

Bilir misin? 

Bir yarışçı aygır gibiydi

Kalıbına sığamıyordu

Bir miktar Kürt burnu

Yüzde yirmibeş

En azından

Türk Kırması

Dağlar böylesini basar bağrına

yavrusunun

Katılaşmış ve sinirli bir yiğitti babası

Ve yorgun 

Pes etmeyen cinsinden amma,

İsyankar

Sabırsızdı toprağa soktuğu ayak parmakları

; 

Kara mermere kar yağmış gibi keskindi

Granit bakışları

Gururlu ve korkunçtu, kinli

bakışlarını,

Taşıdığı

başı

2004 sonu/.', 'Avustralya’da bir göçmendi: Bilemezdiniz Hiç bir zor onu egemenliğine alacak kadar  zorlu değildi Bilir misin?  Bir yarışçı aygır gibiydi Ka...', ARRAY['Türk Edebiyatı','Şiir','Doğan Şahin']::text[], 8.5, '{"poet":"Doğan Şahin","poet_slug":"dogan-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/evlat-acisi-siiri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Müslüman', 'ben-musluman-dogan-sahin-u162d', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir ülkede yetiştim 20lerime kadar

mütercimim o tarihten beridir

biline:

17 Aralık 2004 tarihinde 

ABD

Cornell Üniversitesi tarafından, 

yayınlanan araştırma sonucunu tercüme ettim bir önemli kaynağa

atıfta bulundum,

Avustralya’da

Taze taze

Kıvamında..

Buna göre; 

“Amerikalıların yarısı Müslümanların haklarının kısıtlanması gerektiğini beyan etti.”

Kıs kıs güldüm ülkemdeki ağalara

Yazmalıydım, şiirsel güzelliğini,

Boğarken sermaye

Minarelerle

Çoğalan mızrakçasına

Kılçık düzeninde

Müslüman saçıyla,

Uzaklardan

(Yil sonu 2004)', 'Bir ülkede yetiştim 20lerime kadar mütercimim o tarihten beridir biline: 17 Aralık 2004 tarihinde  ABD Cornell Üniversitesi tarafından,  yay...', ARRAY['Türk Edebiyatı','Şiir','Doğan Şahin']::text[], 8.5, '{"poet":"Doğan Şahin","poet_slug":"dogan-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/ben-musluman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çiğ düşerdi dudaklarıma', 'cig-duserdi-dudaklarima-gencay-coskun-6cpuk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Çiğ düşerdi dudaklarıma

Uyanırdım 

Kış güneşinin cılız yüzü 

Vururdu yüzüme 

Üzülürdüm

Erken uyanınca 

Kaçırdığım rüyamı

Özlerdim

Küserdi düşlerim

İç içe öyle bir kapanırdı ki

Kirli gönüller 

Ne söylese 

Bu iç asla açılmazdı 

İçim hiç değişmezdi 

Kırılırdı 

Sızlayarak kanardı

Derinden susardı 

Sadece 

Ama asla pes etmezdi 

Yıkılan bir devir gibi 

Kalkardı ayağa

Gitmek zorunda olduğu 

Yola giderdi

Ölmek zorunda olduğu

Toprağa gömülürdü 

Bir fidanın su yolunda

Bir cemre düşerdi

Yüzüme 

Özlerdim ölmeyi 

İstemezdim tekrar 

Dirilmeyi 

Çiğ düşerdi dudaklarıma 

Uyanırdım 

Hiç uyumamış gibi 

Yorulurdum 

Kırılgan bir düşü 

Yakalamak ne kadar zordu

Peşine en azılı duygularımı salardım

Bulup getirsinler diye 

Getirdikleri garip bir tebessümdü 

İsyanda bir ömür 

Hapisten daha zordu

Yasaklı bir şarkıydı fısıltım 

Sözlerim idamlık fermanlar doğururdu

Her doğumda bir hüzün çiçeği açardı

Hiç solmazdı 

Bu yorgunlukta 

Bulut yatak

Yıldızlar yastık

Ayparçası yorganım olur 

Uyurdum sonsuzluğa 

Çiğ düşerdi dudaklarıma 

Susardım kaderime 

Çiğ düşerdi dudaklarıma 

Uyanmazdım 

Bir tatlı düş içinde kaybolurdum...', 'Çiğ düşerdi dudaklarıma Uyanırdım  Kış güneşinin cılız yüzü  Vururdu yüzüme  Üzülürdüm Erken uyanınca  Kaçırdığım rüyamı Özlerdim Küserdi dü...', ARRAY['Türk Edebiyatı','Şiir','Gencay Coşkun']::text[], 8.5, '{"poet":"Gencay Coşkun","poet_slug":"gencay-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":56,"source_url":"https://www.antoloji.com/cig-duserdi-dudaklarima-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yollar', 'yollar-dursun-elmas-7c0zp', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hey yollar...kıvrılan yollar, 

Sevdiğimi alıp, götüren yollar

Size baka baka geçiyor senelerim

Yüreğimi söküp de bitiren yollar.. 

08.10.1979 / TOKAT', 'Hey yollar...kıvrılan yollar,  Sevdiğimi alıp, götüren yollar Size baka baka geçiyor senelerim Yüreğimi söküp de bitiren yollar..  08.10.197...', ARRAY['Türk Edebiyatı','Şiir','Dursun Elmas']::text[], 8.5, '{"poet":"Dursun Elmas","poet_slug":"dursun-elmas","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/yollar-46-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Tanımadan Önce', 'seni-tanimadan-once-dursun-elmas-gkp5w', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Baharı bilmezdim,anlayamazdım

Seni tanımadan,görmeden önce.

Geceyi gündüze bağlayamazdım

Sen böyle beyazlar giymeden önce...', 'Baharı bilmezdim,anlayamazdım Seni tanımadan,görmeden önce. Geceyi gündüze bağlayamazdım Sen böyle beyazlar giymeden önce......', ARRAY['Türk Edebiyatı','Şiir','Dursun Elmas']::text[], 8.5, '{"poet":"Dursun Elmas","poet_slug":"dursun-elmas","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/seni-tanimadan-once-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yakıcı Düşler', 'yakici-dusler-huseyin-ciplak-if3wf', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yine savruldu,

Gökyüzüne düşen yaprak....

Baharı beklercesine asi! 

Esiyor deli bir rüzgar,

Bekliyorum kaç günden beri.

Ne bir haber...

Ne bir soran...

Acı duyuyorum! 

Kelepçelenmiş sanki dilim,

Cesaret beklercesine.

Yüreğimdeki kıvılcımın ateşi,

Yakıyor çeliğe dönüştüren.

Tatlı bir tebessümün güneşi,

Dimdik duruyor karşımızda,

Yine sevdaları sararcasına...

Asi gülücüklerin çığlıkları,

Sevdalandırdı bizleri.

Yedi verenler üstüne,

Doğacak güneşin ilk ışıklarına doğru,

Yaratıyoruz çelikleşen sevgiyi...

Yarını düşlemenin hayali,

Umut oluyor sevinçlerimize.....', 'Yine savruldu, Gökyüzüne düşen yaprak.... Baharı beklercesine asi!  Esiyor deli bir rüzgar, Bekliyorum kaç günden beri. Ne bir haber... Ne b...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Çıplak']::text[], 8.5, '{"poet":"Hüseyin Çıplak","poet_slug":"huseyin-ciplak","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/yakici-dusler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz Ay, Sensiz Deniz', 'sensiz-ay-sensiz-deniz-i-smet-barlioglu-97p4z', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ne aya sensiz bakabiliyorum, ne denize; 

Soracakmış gibiler neden sensiz olduğumu,

Neden bakınıp durduğumu

Meyve yüklü dallar arasından bir başıma,

Nasıl olup da sağ çıkabildiğimi

Sabahlardan akşamlara,

Pencerelerden süs için mi yansıyor deniz,

Ay süs için mi vuruyor

Camlara? 

Ne güle anlatabiliyorum yalnızlığımı,

Ne dikene,

Ne gelip geçen gemilere parıldayan denizden,

Ne denizin yaladığı kumsallara,

Ne de sulara testekerlek düşen aya,

Onlar ki; bizi tüm birlikte gördüler yıllar yılı,

Elimize, yüzümüze, omzumuza birlikte değdiler,

Bizi birlikte sevdiler,

Ne bensiz seni kabul ederler,

Ne sensiz beni,

Bunları isterdim, beni değilse bile,

Görmeni.

Sen aya bakıyorsundur, biliyorum ve denize,

Kayalıklara oturup vererek rüzgara saçlarını,

Yüzün ve omuzların ışıklar içinde,

Gözlerinde de yine ayni pırıltılar vardır,

Umurunda bile değildir varlığım, yokluğum,

Ne yanında yüreğimin sıcaklığı,

Ne soluğum.

(BİR ŞARKI SÖYLE BANA İsimli Serbest Şiirler ''inden > 63-64/100)', 'Ne aya sensiz bakabiliyorum, ne denize;  Soracakmış gibiler neden sensiz olduğumu, Neden bakınıp durduğumu Meyve yüklü dallar arasından bir ...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/sensiz-ay-sensiz-deniz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yerime', 'yerime-i-smet-barlioglu-of1le', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu dünyada kimin için yaşadığımı sanıyorsun,

Rüyalarımda kimi gördüğümü,

Yanımda kimi yürüttüğümü yağmurlar altında,

Kimi düşündüğümü geceleri sabahlara kadar,

Kime ikramlarda bulunduğumu,

Kimden lütuflar beklediğimi? 

Bilmiyorsan bil artık anam-babam,

Mahşerler içinde yapayalnızım görenlere,

Yanımda bir senin bulunduğun apaçık

Sevenlere.

Aklımı yellere vermişim yıllar yılı,

Varlığımı sellere,

Güllerin, bülbüllerin hakkını bulup

Güllere, bülbüllere vermişim,

Binbir gece masalları içindeyim anlayacağın,

Mağara dolusu evrenler Kırk Harami hazinesi,

Ne mala göz kaydırmışım, ne mülke,

Ne altına el etmişim, ne gümüşe,

Bir seni istiyorum bir tükenmeyen servetten

Bir seni istiyorum gönül dolusu,

Kemikten, etten.

Bu dünyada kimin için yaşadığımı sanıyorsun,

Sen olmayınca hükmü olmadıktan sonra denizlerin,

Tepelerin, dağların; rengi bir türlü yerine oturmayan

Ağaçları dalsız kalan ormanların,

Bu anlamsız toprakların,

Kumların,

Yağlı urgan olup geçmişsin boynuma

Ve kelepçe olup bileklerime,

Benden başka kim yaşasın senin için

Yerime? 

(BİR ŞARKI SÖYLE BANA İsimli Serbest Şiirler ''inden > 65-66/100)', 'Bu dünyada kimin için yaşadığımı sanıyorsun, Rüyalarımda kimi gördüğümü, Yanımda kimi yürüttüğümü yağmurlar altında, Kimi düşündüğümü gecele...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/yerime-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aramasınlar', 'aramasinlar-i-smet-barlioglu-zs0q5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Aramasınlar kimin kementler attığını

Uzak denizlerdeki gemilere,

Kimin çeke çeke dolaştırdığını liman liman,

Kimin demirler attırdığını kıyılarda,

Yolcuları mahşer halinde kimin boşalttığını,

Kimin yüzleri tek tek incelediğini,

Kimin kollarının kırılıp kaldığını yen içinde,

Kimin umutlarını sele verdiğini,

Yolcusu gelenler gelmeyenlere sorsun

Beni.

Ne denli zor olduğunu bir ben bilirim

Karanlık enginlerden gemi çekmenin,

Asılıp asılıp tüm gücüyle ıslak kementlerin ucuna,

İçindeki özlemi köpüklü sulara döke döke.

Bir ben bilirim ne denli acı olduğunu

O kalabalık gemilerin bomboş çıkmasının

Islak sulardan boş çıkan balık ağları gibi

Tüm umutları dalgaların dibinde bırakarak.

Yolcular boşalırken bir ben bakarım yabancı yüzlere

Ağlayarak.

Gemidir çektim denizlerden yıllar yılı,

Sevgiliyi belki birinde bulurum diye,

Ne bileklerimde takat kaldı, ne kementlerimde,

Boşa dikmişim denize gözlerimi,

Dalgalara boşuna baplamışım umutlarımı,

Ne yolcuma rastladım yolcular arasında,

Ne yüzlere karşı yüzüm güldü,

İşte bir yaştır ki dolmuştu gözlerime,

Döküldü.

(BİR ŞARKI SÖYLE BANA İsimli Serbest Şiirler ''inden > 67-68/100)', 'Aramasınlar kimin kementler attığını Uzak denizlerdeki gemilere, Kimin çeke çeke dolaştırdığını liman liman, Kimin demirler attırdığını kıyı...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/aramasinlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şahidim Küllü Leyla''ya', 'sahidim-kullu-leyla-ya-ali-riza-unal-dakm5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'O nefsin maliki, arifan fakrı acizar ise selam olsun o mahluka

Eğer, didar ise malikin o deryayı gönüle, bil ki secdeyi Rahman''ım

O sırrı hilkata ayanız gayrı vakıfım, yetmedi onca beyanım

Sanma ki cüzzi Leyla''dır vaslına, meramım, nazarım Ahadi halıkâ 

Şahidim küllü Leyla''dır, kulda bu mecnune o Mevlâ''yı sultanım', 'O nefsin maliki, arifan fakrı acizar ise selam olsun o mahluka Eğer, didar ise malikin o deryayı gönüle, bil ki secdeyi Rahman''ım O sırrı hi...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/sahidim-kullu-leyla-ya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkı Ondan Öğrendim', 'aski-ondan-ogrendim-umut-ulbegi-2v53i', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Susuz kalmıştı şehir

gün yıldızları uğurlarken bile 

ağlayamadı gökyüzü

kalabalıktı

yalnızlıktan sıkıldıkça doğuruyordu yalnızca

ve ölüm

bir avuç kumdan ibaretti

silindi deniz kabarınca

Şehir

sen hiç 

bensizliği bilmedin ama

ben onsuzluğu ezberledim

yanışıma yağmur bile susuyorken

o köprünün korkuluklarından 

bölünmüş denizi izledim

Gecemi

aydınlık binalarda yaşayan ikizlerime

paylaştırmayı sevdim

''Karanlık özündedir ruhun

kaybetmeden

farketmeden

yok etmeden

aşkı öğrenemezsin''

Onsuz kaldım

-ki gözlerini ruhuma çivilemiştim-

Geçmişi yok ettim

Susuz kalmıştı şehir

fırtına bulutları gezdirirken bile

uyuyamadı deniz

Ansızın patlayan sokak lambasından

süzülen ışıktı

Yemek pişmeden biten tüp

İlk adımında düşen çocuk

Son nefeste söylenen sözdü

hayat

illüzyon ve hipnoz

sihirbazların parmaklarının ucunda

Şehir

sen hiç yalnızlığı bilmedin

ben yalnızlığı içiyorum

içiyordum

içtim

sevdamı kazıdım saç diplerime

ondan başka kimseye göstermedim

adını ezberledim

uydumuzu saran ışığın en parlak yerinde

Gecemi

gözçukurlarımızda biriken yaşlarla

ıslatmayı sevdim

Bir ay sonra ay dönüyor 

''Sonsuzluğun neresindeyiz

Dokunmadan

hissetmeden

sevişmeden

doğmadan

öğrenemezsin''

Sevdim

Yeniden doğdum

yoktan var oldum.', 'Susuz kalmıştı şehir gün yıldızları uğurlarken bile  ağlayamadı gökyüzü kalabalıktı yalnızlıktan sıkıldıkça doğuruyordu yalnızca ve ölüm bir...', ARRAY['Türk Edebiyatı','Şiir','Umut Ülbegi']::text[], 8.5, '{"poet":"Umut Ülbegi","poet_slug":"umut-ulbegi","theme":"Türk Şiiri","is_hero":false,"total_lines":59,"source_url":"https://www.antoloji.com/aski-ondan-ogrendim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Türkü', 'turku-dursun-elmas-kzfl7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hasretin bu canı gurbete saldı

Kendim gurbet,gönlüm sılada kaldı.

Karanlık geceler uykuya daldı,

Yüreciğim taşa döndü,bilmedin.

Sen gideli çiçeklerim açmıyor,

Gökyüzünde turnalarım uçmuyor,

Hayat bana artık neşe saçmıyor,

Gözyaşlarım sele bindi bilmedin.

Uykularımda sen,figanımda sen! 

Türkülerde hep sen,şiirlerde sen! 

Ne hallere düştüğümü bir bilsen,

Saçlarıma karlar sindi bilmedin

Senden ayrılalı seneler oldu,

Bahçede diktiğin fidan kurudu.

Senden başka sevdiceğim yoğudu,

Mezarıma baykuş indi bilmedin', 'Hasretin bu canı gurbete saldı Kendim gurbet,gönlüm sılada kaldı. Karanlık geceler uykuya daldı, Yüreciğim taşa döndü,bilmedin. Sen gideli ç...', ARRAY['Türk Edebiyatı','Şiir','Dursun Elmas']::text[], 8.5, '{"poet":"Dursun Elmas","poet_slug":"dursun-elmas","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/turku-27-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Derbeder', 'derbeder-ali-riza-unal-h8y1u', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bilmediğim garip bir hüzüne, giryanı zar, yanar oldum

Görmedim, nasıldır nazarı yüzü varına, püryanı azar oldum

Kanmışım hal-i dem sandığım kâali sözüne 

Biçare gayrı derbeder üryanı gezer oldum', 'Bilmediğim garip bir hüzüne, giryanı zar, yanar oldum Görmedim, nasıldır nazarı yüzü varına, püryanı azar oldum Kanmışım hal-i dem sandığım ...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/derbeder-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşka Düştüm', 'aska-dustum-mustafa-tanrikulu-utk3p', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'zb''ye...

Bilemem gönül kuşu nasıl bir nâra düştü

Tutuldu dili yalnız bir acı nârâ düştü.

Gönüller bitsin diye beklerken ayrılığı

Manto ihatasında hicran kenara düştü.

Dolunay gececleri gark etmişti yâ nura

Nirengi noktasında aşk aşikara düştü.

Dev diye arkasından koşturulan adamlar

Senle kıyaslanınca hepsi fukara düştü.

Elmas parıltısında titrerdi yalnızlığım

İnilti meclisinde cânân hatıra düştü

savrulan kumaşların hayranım renklerine 

şifrelere muntazır gözler zarara düştü.

libas diyerek giydi kalbim üstüne aşkı

zehirlenip vefayla diyar-ı yâra düştü

elle rimde dua var ve dilimde yakarış

yalvaran sözcüklerle dilim yollara düştü', 'zb''ye... Bilemem gönül kuşu nasıl bir nâra düştü Tutuldu dili yalnız bir acı nârâ düştü. Gönüller bitsin diye beklerken ayrılığı Manto ihata...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Tanrıkulu']::text[], 8.5, '{"poet":"Mustafa Tanrıkulu","poet_slug":"mustafa-tanrikulu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/aska-dustum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutma', 'unutma-meltem-kaya-6bjm4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir tarla kuşunun kanadında

Yakalayabilirsin yaşamı

Kuşlara bakmayı unutma...

Bir varoş çocuğunun

Gazeteden yaptığı uçurtmasının

Ajans haberlerini yazan

Rengarenk kuyuğunda da...

Çocuklara gülümsemeyi unutma...

Yeter ki iste,

Ve gülümse! 

O zaman hoyrat yaşam da 

Sana gülümseyecektir

Bir tomurcuk gülün

	taptaze yaprağından...

Güllere dokunmayı unutma...

Kuşlar, çocuklar ve güller

Sana yaşamı unutturmaz.', 'Bir tarla kuşunun kanadında Yakalayabilirsin yaşamı Kuşlara bakmayı unutma... Bir varoş çocuğunun Gazeteden yaptığı uçurtmasının Ajans haber...', ARRAY['Türk Edebiyatı','Şiir','Meltem Kaya']::text[], 8.5, '{"poet":"Meltem Kaya","poet_slug":"meltem-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/unutma-54-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece Yürüyüşü', 'gece-yuruyusu-huseyin-ciplak-zcplk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sıcak bir temmuz gecesi,

Ay tüm görkemiyle güzellikleri selamlıyor.

Yürüyoruz ağustos böceklerinin,o senfonisi eşliğinde.

Hafif bir rüzgar esiyor ılğıt,ılğıt.

Dallar sallanır ufak,ufak,

Bazen bulutların arasından pırpır eder yıldızlar.

Dağların yamaçlarında top,top yanan çoban ateşleri.

Bir kaval sesi yankılanıyor kulaklarımda,

Çınlar o yanık sesi,

Sevdalısına seslenir kavalın ucunda tüten türkülerle.

Yankılandıkça yükselir,

Tüm dünyayı kucaklar türküler.

Çobanın kavalında berraklaşır,tüm duygular.

Sıcak bir temmuz gecesinde,

Yürüyorum bu tablonun içinde doyasıya..

Ay tüm görkemiyle selamlıyor güzellikleri.

Yürüyoruz,ağustos böceklerinin o senfonisi eşliğinde,

Hafif bir rüzgar esiyor,

Dallar sallanıyor ufak,ufak....', 'Sıcak bir temmuz gecesi, Ay tüm görkemiyle güzellikleri selamlıyor. Yürüyoruz ağustos böceklerinin,o senfonisi eşliğinde. Hafif bir rüzgar e...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Çıplak']::text[], 8.5, '{"poet":"Hüseyin Çıplak","poet_slug":"huseyin-ciplak","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/gece-yuruyusu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Selam', 'selam-meltem-kaya-hslvb', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yüreğimdeki ıssız liman beni hiç 

		yadırgamasın...

Sevdam artık tel örgülere takılmasın! 

Özgürlük neredesin? 

Aşklarımız selamlıyor bizi kuytularda...

Sağanak yağmur, toprak bahar kokuyor

Tutsaklığın karanlığını yırtarak

         bahar bahar geliyorsun! 

Umudum coşkuna katık olsun sevgili,

Hangi duvar sevdamızdan yüce ki! 

Fırtınalar kopar içimde

Yıllar oldu camlar ardında yüzün...

Ama gökkuşağını serdik görüş gününe! 

Yüzün ki,

Her sabah gül gibi açılır yüreğimde...', 'Yüreğimdeki ıssız liman beni hiç  		yadırgamasın... Sevdam artık tel örgülere takılmasın!  Özgürlük neredesin?  Aşklarımız selamlıyor bizi k...', ARRAY['Türk Edebiyatı','Şiir','Meltem Kaya']::text[], 8.5, '{"poet":"Meltem Kaya","poet_slug":"meltem-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/selam-30-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Teslimiyet Bayramı', 'teslimiyet-bayrami-dursun-elmas-af6vs', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '17 Aralık,Kızılay meydanında,

Teslimiyet Bayramı var! ..

Egemenlik hakkımızın

Devir teslim bayramı var! ..

''Egemenlik kayıtsız ve şartsız

Avrupalınındır diyenler,

Papa ''ya ''ekümeniklik ''verenler,

Kıbrıs,bize fazla yük 

Rum''un olsun diyenler

Ermeni''ye kardeşimiz(!) 

Coniye yodaşımız,

Koniye arkadaşımız,

Türkiyelilik aşkımız''zırvasını iyenler...

Hatırlayın 19''u,Samsun''u,

Sivas''ı Erzurum''u.

Çok hırpaladın ruhumu! 

Yetti be! canımıza tak etti! 

''uyan ey ehli vatan! 

Dönme,devşirme güruh

Satıyor toprağını,

Daha ne duruyorsun? 

Ankara''da bayram ediyor vatansızlar,

Şehitler vatanını satıyor bak kansızlar! ..', '17 Aralık,Kızılay meydanında, Teslimiyet Bayramı var! .. Egemenlik hakkımızın Devir teslim bayramı var! .. ''Egemenlik kayıtsız ve şartsız Av...', ARRAY['Türk Edebiyatı','Şiir','Dursun Elmas']::text[], 8.5, '{"poet":"Dursun Elmas","poet_slug":"dursun-elmas","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/teslimiyet-bayrami-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kelebeğin Kanadında', 'kelebegin-kanadinda-huseyin-ciplak-5u0f0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir sen vardın gönlümde,

Bir ben vardım sevdalarda.

Bu gitmeler gitmek değil,

Yıllardan sonra umutlanışlarda...

İlk defa vurulmamışım,defalarca vurulmuşum.

Umutlarıma,sevinçlerime müjdeler olsun candaşım.

Senin yokluğun vardı toz duman ortalıkta.

Bir ben vardım düşleyişlerde,

Birde anılar vardı unutulması zor

Hatıralarımın içinde neler yokki...

Ne hasretler,ne özlemlere vurulmuşum,

Sen yoksun düşlediğim zamanda.

Benim içimdeyse fırtınalar,

Çok aramıştım düşlediğim fırtınaları...

Duyuramamıştım o güzel umutlanışları,

Gözlerin kör,kulakların sağır olmuştu sanki,

Bir görebilseydin umutlara tutunuşumu,

Yanlızlık yakıcıdır,

Senide.benide ve tüm insanlığı kavurur.

Dayan dayanabilirsen...

Ama paylaşımın güzelliğidir.

Renklendirir,umutlandırır yaşama kaynağı olur.

Renk cümbüşüne dönüşen,

Düşlerimi süsleyen kelebeğim,

Sen yarınım olmalısın kirlenmişliğe inat......', 'Bir sen vardın gönlümde, Bir ben vardım sevdalarda. Bu gitmeler gitmek değil, Yıllardan sonra umutlanışlarda... İlk defa vurulmamışım,defala...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Çıplak']::text[], 8.5, '{"poet":"Hüseyin Çıplak","poet_slug":"huseyin-ciplak","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/kelebegin-kanadinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmurların Altında', 'yagmurlarin-altinda-fatih-konuk-4feni', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir başka oluyor yağmurlarda ıslanmak

Şemsiyeyi bir kenara atıp sırılsıklam olmak

Yağmurların altında çocuklar gibi oynamak

Ve üşüyüp sobanın yanında ısınmak bir başka oluyor

Hele birde yanında sevdiğinin olması

İşte bu istenilen duyguların en güzeli

Onunla olmak,içten geldiğice sımsıkı sarılmak 

Ve birlikte yeminler etmek,şarkılar söylemek

Allah’tan istenilen dileklerin biri bu olsa gerek

Yeryüzünü,gökyüzünü,ağaçları,toprakları,kuşları

En önemlisi de yağmurları edilen yeminlere şahit etmek

Bir başka oluyor yağmurların altında ıslanmak

Pencere önünde yağmurun yağışını seyretmek 

Yağmurların söylediği o şarkıyı dinlemek

Gökyüzüne dalıp gitmek ve dalıp gidilen yerde

Yaşanılmış,yaşanılmamış yada yaşanılmak istenilen

Duyguları hayal ederek düşünmek

Bir başka oluyor yağmurların altında ıslanmak', 'Bir başka oluyor yağmurlarda ıslanmak Şemsiyeyi bir kenara atıp sırılsıklam olmak Yağmurların altında çocuklar gibi oynamak Ve üşüyüp sobanı...', ARRAY['Türk Edebiyatı','Şiir','Fatih Konuk']::text[], 8.5, '{"poet":"Fatih Konuk","poet_slug":"fatih-konuk","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/yagmurlarin-altinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çingene', 'cingene-ali-riza-unal-1kien', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir çingene düçar eder varımı

O düştükçe bu fakir gönlüme 

Düşünmedim bugün ile yarını

Bildim düşmüş kâal peşine 

Hesap eder nefsi ile arını', 'Bir çingene düçar eder varımı O düştükçe bu fakir gönlüme  Düşünmedim bugün ile yarını Bildim düşmüş kâal peşine  Hesap eder nefsi ile arını...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/cingene-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevesim Gelir', 'sevesim-gelir-ali-riza-unal-60ykz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hakkımızda dava açmışlar

Anladım ki yoldan kaçmışlar

Bayırı görüp düzde şaşmışlar

Onca garip gülesim gelir..! 

Hazrete gidip gelenleri

Hele nefsini bilenleri

Ölmeden can verenleri

Onca garip övesim gelir..! 

Varını döküp saçmışları

Arını atıp aşmışları

Zarına varıp susmuşları

Onca garip sevesim gelir..!', 'Hakkımızda dava açmışlar Anladım ki yoldan kaçmışlar Bayırı görüp düzde şaşmışlar Onca garip gülesim gelir..!  Hazrete gidip gelenleri Hele ...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sevesim-gelir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kabristan İklimi', 'kabristan-i-klimi-hayati-yavuzer-mfjny', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'dünyanın her derdine, işine gülmek gerek 

o ebedi hayatın düşüne dalmak gerek 

göç zamanı ermeden, can meleği varmadan 

kabristan iklimine aşina olmak gerek 

(1980/Elazığ)', 'dünyanın her derdine, işine gülmek gerek  o ebedi hayatın düşüne dalmak gerek  göç zamanı ermeden, can meleği varmadan  kabristan iklimine a...', ARRAY['Türk Edebiyatı','Şiir','Hayati Yavuzer']::text[], 8.5, '{"poet":"Hayati Yavuzer","poet_slug":"hayati-yavuzer","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/kabristan-iklimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Balam', 'balam-hayati-yavuzer-4ydgu', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '(akrostiş) 

A dın yüreğimde ün gibi balam

S enin aydınlığın gün gibi balam

L utfetti Hak Yirmi Şubat Seksende

I şıklı doğumun dün gibi balam

H ayatım seninle başladı sanki

A dını ezanla koydum inan ki

N e desem... canımda can gibi balam', '(akrostiş)  A dın yüreğimde ün gibi balam S enin aydınlığın gün gibi balam L utfetti Hak Yirmi Şubat Seksende I şıklı doğumun dün gibi balam...', ARRAY['Türk Edebiyatı','Şiir','Hayati Yavuzer']::text[], 8.5, '{"poet":"Hayati Yavuzer","poet_slug":"hayati-yavuzer","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/balam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bolu İçin', 'bolu-i-cin-hayati-yavuzer-v4jlt', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hisar Tepesinden seyrettim seni

Göklere boy vermiş minarelerin

Bir gamlı hazanı yaşarmış gibi

Boynu bükük durur ahşap evlerin

Hangi belde var ki sen gibi güzel

Bir türlü eşini bulamadım ki

Nasıl bırakıp da gideyim seni

Şu Kökez suyuna doyamadım ki

(1991/ Bolu)', 'Hisar Tepesinden seyrettim seni Göklere boy vermiş minarelerin Bir gamlı hazanı yaşarmış gibi Boynu bükük durur ahşap evlerin Hangi belde va...', ARRAY['Türk Edebiyatı','Şiir','Hayati Yavuzer']::text[], 8.5, '{"poet":"Hayati Yavuzer","poet_slug":"hayati-yavuzer","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/bolu-icin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Yürek Rüzgar Bekliyor', 'bir-yurek-ruzgar-bekliyor-meltem-kaya-dvjcb', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Koyu bir karanlıkla kuşatılmış bir gece, ay buluta girdi

İsli bir fener ışığında tepeleme çığlığım ben

Dışarısı şakağında kurşunla boyumca kara teslim...

Çığ gibi uçurumlardan yuvarlanan bu lanet zulmün

Tam orta yerinde kardelenim var...

O yüzden isterim ki; bu çığ bulsun beni! 

Toprağın bu yeni renginde kar, beyaz bir buğu gibi

Dondurucu soğuğun ayrılık ikliminde bir fısıltıyım ben

Yüreğim en çok kendini kanatan bir hançere teslim...

Örsünde dövülen bir aşkla alevleri göğü bulan bu şehrin

Tam orta yerinde çocukluğum var...

O yüzden isterim ki; bu yangın tutsun beni! 

Gurbete büyüyen ömrümde kar, sanki ağrılı sular gibi

Düşlerini hayattan sakınan mavi bir uykuyum ben 

Ellerim gitgide kabaran toprakta susan bir mayına teslim...

Yürek vuruşlarını bir nehirde uyutan bu doludizgin selin

Tam orta yerinde sevinçlerim var...

O yüzden isterim ki; bu sel akıtsın beni! 

Usulca saklandığı barınağında kar, güneşin yorganı gibi

Dargın çocuklar gibi barışmaya hazır sağanağım ben

Gözlerim sabretmeye tahammülsüz uzak yollara teslim...

Tüm ışıklar sönünce gölgemi göreceğin bu amansız serinliğin

Tam orta yerinde düşlerim var...

O yüzden isterim ki; bu ayaz yaksın beni! 

 Tomurcuğunu ayaz çalmış dalın efkarında kar, usul bir özür gibi

Sesinin sustuğu yerde küllerini savurmuş bir uzaklığım ben

Küllerime gitgide sokulan yangın suskunluğuna teslim...

Seller ve yangınlar arasında yorulduğumu bilemediğim bu yürüyüşün

Tam orta yerinde seni bekleyişim var...

O yüzden isterim ki; bu yorgunluk tüketsin beni! 

Sessizce dilimden şiirler düşüren kar, rüzgardan bir kuş gibi

Rüzgarın esmediği yerde son kıvılcımını yitiren bir yığınağım ben

Törpülenen hasretinden çiçekler büyüten rüzgar fırtınaya teslim...

Uğruna kasırgalar büyüttüğüm gözlerine sokulan bu vakitsiz ölümün

Tam orta yerinde bitmeyecek hasretim var...

O yüzden isterim ki; bu ölüm alsın beni! 

Ay sustu, buluta girmiş çıkacakmış ne gam...

Rüzgar sustu...

Karın seranatı bitti.', 'Koyu bir karanlıkla kuşatılmış bir gece, ay buluta girdi İsli bir fener ışığında tepeleme çığlığım ben Dışarısı şakağında kurşunla boyumca k...', ARRAY['Türk Edebiyatı','Şiir','Meltem Kaya']::text[], 8.5, '{"poet":"Meltem Kaya","poet_slug":"meltem-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/bir-yurek-ruzgar-bekliyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sinop Sokakları', 'sinop-sokaklari-nurten-koroglu-06nfv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'yine aynı bu Sinop sokakları

defalarca yürüdüğüm  şu kaldırım,şu taşlar

bir cılız ışık,nihayet tüten bir baca

iç içe girmiş,boş soğuk duvarlar

yine aynı şu Sinop sokakları

aceleci,boş,telaşlı adımlar

bir vapur düdüğü yanlız bir insan

hüznü sevgiyle karıştırmış dünyalar

yine aynı şu Sinop sokakları

boy boy dal veren incir ağaçları

tepede mechul sevgiliye seslenen şu fener

camlardan süzülen begonyaların sarkaçları

yine aynı şu Sinop sokakları

boylu boyunca uzanmış ak liman,tepede bir çay bahçesi

sahile bir fırtınayla kopup gelen dalgalar

çilesi bitmeyen,duvarları gülmeyen kodesi

yine aynı şu Sinop sokakları

Yanlızların ıstırap dolu gecesi

yağmuru,boranı fırtınası

sevgiyle merhametin karışmış garip bir bilmecesi', 'yine aynı bu Sinop sokakları defalarca yürüdüğüm  şu kaldırım,şu taşlar bir cılız ışık,nihayet tüten bir baca iç içe girmiş,boş soğuk duvarl...', ARRAY['Türk Edebiyatı','Şiir','Nurten Köroğlu']::text[], 8.5, '{"poet":"Nurten Köroğlu","poet_slug":"nurten-koroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sinop-sokaklari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Belki Son Anında', 'belki-son-aninda-melih-coskun-xda9n', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Belki son anında gelecek aklına 

En güzel dizeleri ömrünün 

Ne bir kağıt olacak yanı başında 

Ne bir kalem

O gün diyeceğim ki sana 

Ey bakışlarında ırmak serinliği taşıyan güzellik

Çiçekler açarsa bir gün mezarımda 

Bil ki ölmedim 

En güzel şiirimi yazdım sana...', 'Belki son anında gelecek aklına  En güzel dizeleri ömrünün  Ne bir kağıt olacak yanı başında  Ne bir kalem O gün diyeceğim ki sana  Ey bakış...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/belki-son-aninda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüzgarındandır', 'ruzgarindandir-meltem-kaya-hj9wg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu gece duman duman tanımsız, bir garip sis iner düşlerime

Uçurtmam kaçmışsa da ellerimden, dağlar ardına

Ağlama yüreğim, bulur bir başkası elbet

Yahut küçük bir çocuk, uçurur rüzgarınla...

Öyle bakma sevdiğim, kum kaçtı gözlerime

Oysa ki çiçekli dal uçlarını unutmuyorum.

Hele gitsin gözlerimdeki kumlar, hele yıkansın gözlerim

Bir solukta tutsaklığın kıyılarını özgürlüğe boyarım

Mülteci hüzünlerini memleket rüzgarına katarım

Dalar masmavi bir göle, sana güneş toplarım

Umutları ayıklayıp gözlerimden

Bir sürü güvercin gönderirim ellerimden

Unuttun mu sevdiğim; 

Ben bir rüzgarım, senin meltem rüzgarın! 

Bir yürekten bi yüreğe savururum umutları...

Bazen sessizce yitip uzak bir deniz olurum,

En karanlık gecede bile yas tutmaz eteklerim

Bir dağ kırlangıcı bakar gözlerime uçup giderken

Görürüm gözlerinde gözlerinin alasını

O an yüreğimdeki karanfil dirilir, sen olurum.

Haydi sevdiğim benim, bir dal fesleğen kopar saksıdan

Tak saçlarımın arasına, kokunu özledim. 

Suya bir papatya aklığıyla nasıl güzel düşerse,

Öyle güzel in düşlerime, seni özledim.

Gözlerindeki mülteci bulutları toplayıp

İstanbul''da bir bahar sabahını balıkçılarla karşılar gibi

Sabahın ilk ekmek kokusunu martılarla paylaşır gibi

Baharın ilk gülü heyecanıyla yüreğinde açılmak istiyorum...

Unutma ki sevdiğim; rüzgarınım ben senin! 

Yüreğimin gümüş kuşu, limanımsın sen...

Rüzgarın çok iyi biliyor ki; 

Seni sevmek yarınları sevmektir.

Dolu dizgin akan dünyayı, martıları

Alınterini ve insanları sevmektir.

Yüreğim, allı turnam, akça pakça bulutum benim, 

Seni seviyorum, yani dünyayı.', 'Bu gece duman duman tanımsız, bir garip sis iner düşlerime Uçurtmam kaçmışsa da ellerimden, dağlar ardına Ağlama yüreğim, bulur bir başkası ...', ARRAY['Türk Edebiyatı','Şiir','Meltem Kaya']::text[], 8.5, '{"poet":"Meltem Kaya","poet_slug":"meltem-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/ruzgarindandir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkımızın ardında', 'askimizin-ardinda-mehmet-elmacioglu-vn5ae', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Aşkımızın ardındaki gerçek,

Seni sevmeme engel oluyor.

İçimi kemiren o mutsuzluk,

İliklerime kadar sömürüyor.

Sevemiyorum doyasıya,

Açlıktan kıvrandığım günler,

Zehir oluyor hayat bana,

Sana bir çiçek bile alamadığımda.

Aşkımıza zincir vuran,

Fakirlik yokmu sevdiğim,

Beni benden alıp götüren,

Sen değil benim ezilmişliğim.

İsyankar olma desende bana,

Sitem doluyum hayata,

Gücüm kalmadı sevmeye, sevilmeye,

Sırtımdaki yük yetiyor bana.

Unut beni zor olsada meleğim,

Sonunda soldu gönül bahçem,

Gelecek için tek dileğim,

İnsanca yaşamaktır sevgilim.

  1977', 'Aşkımızın ardındaki gerçek, Seni sevmeme engel oluyor. İçimi kemiren o mutsuzluk, İliklerime kadar sömürüyor. Sevemiyorum doyasıya, Açlıktan...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Elmacıoğlu']::text[], 8.5, '{"poet":"Mehmet Elmacıoğlu","poet_slug":"mehmet-elmacioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/askimizin-ardinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haykiris', 'haykiris-oner-aykut-me0ts', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sen orada ben burada, 

Kaliriz biz hep ortada

Dogru aski bulmak icin, 

Savasiriz olum icin

Gelip bana beni sorsa, 

Sözleri hep yalan olsa

Askimida calip kacsa,

Yinede AGLAYAMAM Ki

Seher vakti gunes dogsa

Gozlerimden uzak olsa

Askimida haykirsa

AGLAMADAN DURAMAM Ki...', 'Sen orada ben burada,  Kaliriz biz hep ortada Dogru aski bulmak icin,  Savasiriz olum icin Gelip bana beni sorsa,  Sözleri hep yalan olsa As...', ARRAY['Türk Edebiyatı','Şiir','Öner Aykut']::text[], 8.5, '{"poet":"Öner Aykut","poet_slug":"oner-aykut","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/haykiris-36-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen! !', 'sen-mehmet-elmacioglu-2a7qg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen 

Gül ve eğlen diyen:

Belli tanımamışsın sefaleti.

Ben 

Suyun balığı sarması gibi,

Sarmaşdolaşım açlık ordusuyla.

Sen 

Güneş ve ufkun değişini seyreden:

Gördünmü? 

Saçları pas tutmuş bacıları,

Tarlalarda çift koşulmuş anaları,

Duydunmu? 

Dişlilerde sıkışan kanlı feryadı.

Olasıdır doyasıya gülmek,

Özgür yaşanan dünyada.

Bizde başarabiliriz,

Kırınca emeğimizdeki zinciri.

                    

1977

.', 'Sen  Gül ve eğlen diyen: Belli tanımamışsın sefaleti. Ben  Suyun balığı sarması gibi, Sarmaşdolaşım açlık ordusuyla. Sen  Güneş ve ufkun değ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Elmacıoğlu']::text[], 8.5, '{"poet":"Mehmet Elmacıoğlu","poet_slug":"mehmet-elmacioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sen-486-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnan ki...', 'i-nan-ki-serap-demirturk-r08u0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sevdamı buza yazamam, 

Yazsam da güneşe düşman olurum. 

Bir tek gülü bile koparamam, 

Gül yanağına hayran olurum. 

Irmakların akışına engel olamam, 

Bir damla gözyaşına kurban olurum. 

Sensizliği yaşayamam düşümde bile, 

Senli bir geleceğe ressam olurum. 

Başımı kaldırsam binlerce yıldız, 

Her bir yıldızda seni bulurum. 

Uzağı yakın eden her ne varsa; 

Güle, bülbüle, yola yoldaş olurum. 

Bir gün göreceğimi bilsem seni, 

Yoluna serilir, halın olurum.', 'Sevdamı buza yazamam,  Yazsam da güneşe düşman olurum.  Bir tek gülü bile koparamam,  Gül yanağına hayran olurum.  Irmakların akışına engel ...', ARRAY['Türk Edebiyatı','Şiir','Serap Demirtürk']::text[], 8.5, '{"poet":"Serap Demirtürk","poet_slug":"serap-demirturk","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/inan-ki-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alabora', 'alabora-furkan-ozden-cfcie', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hüznün limanından kırık dökük 

Bir sandalla gece mavisinin aydınlığında

Salıvaedim kendimi uzakların koynuna

Mavilerin üstünde batmaya çeyrek kalmış

Sandalım ve yanımda dünden kalma 

Yarınlarda gerçekleşmesi özlemiyle 

Yaşatmaya çalıştığım düşlerim.

Umutlarıma sarılıyorum sıkı sıkıya

Gecenin ayazında sıcaklığını yüreğimde 

Hissettiğim tek şey yaşayan umutlar

Bu hissin bittiği an

Ben de yolumu bitirmiş sandalım

Alabora olmuş olacak.', 'Hüznün limanından kırık dökük  Bir sandalla gece mavisinin aydınlığında Salıvaedim kendimi uzakların koynuna Mavilerin üstünde batmaya çeyre...', ARRAY['Türk Edebiyatı','Şiir','Furkan Özden']::text[], 8.5, '{"poet":"Furkan Özden","poet_slug":"furkan-ozden","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/alabora-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'H a s r e t', 'h-a-s-r-e-t-ali-seyh-ozdemir-3mby8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Balıkların suya hasreti gibi,

Özledim, özledim, özledim seni! ...

Yüreğimde bir kor ateşi gibi,

Közledim, közledim, közledim seni! ...

Yağmur oldum saçlarından akarak,

Şimşek oldum gürleyerek, çakarak,

Bir gün gelir diye yola bakarak

Gözledim, gözledim, gözledim seni! ...', 'Balıkların suya hasreti gibi, Özledim, özledim, özledim seni! ... Yüreğimde bir kor ateşi gibi, Közledim, közledim, közledim seni! ... Yağmu...', ARRAY['Türk Edebiyatı','Şiir','Ali Şeyh Özdemir']::text[], 8.5, '{"poet":"Ali Şeyh Özdemir","poet_slug":"ali-seyh-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/h-a-s-r-e-t-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutulmuşluğun İsyanı', 'unutulmuslugun-i-syani-mustafa-gokcek-5j57i', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'UNUTULMUŞLUĞUN İSYANI



Hani bazılarınca efkarın derdi unutulmuşluğun anısıdır

Aşkı görmek aşkı yaşamaya yeter mi gözüm

Yaşam girdabı bir oyunsa düşmemeye bakmalı

Bu oyunun mağlubiyeti nedense yaşamımın önceliği 

Kaderci değilim ama feleğe de sözüm yok

Yargılanmadan karalığa ferman verilir

Bu limandan bana fayda yok rüzgarım yetersiz

Yarama merhem olmak zamana düşer

Üşüyorum hırkanı ver dostum titretmeden

Ama bakışlarını yumuşat gülümse biraz

Özgürlüğün caddesinde unutulmuşluğun isyanı

Çırpınan yüreğim hazanda gazel yaprağı

Ayrılığa dayanamıyorum yalan olma

Bırak, bırak artık şu pis bohçalarını

Sarılma artık bana lekeli madam

Unutulmuşluğumun isyanını yaşıyorum



09.10.03                                  Mustafa GÖKÇEK



	

	ALDIRMAMALI	



Beyhude kederlenmemeli dünyada

Kederlenirsek bizi esir eden dünyayla

Yoğrulduğumuzu düşlerim

Çınarlar kadar uzun yaşarsak

Aldırmamalı dercesine kızarak

Zulmetmemeli tene ten sardığınca

Dalda yeşil nehir yeşil ama kurşun 

Kurşunun ucu kızıldır kırmızıya çalar

Söz içten alaylı olursa yaralar

Ayrılık takvim yaprağının sultasında

Nice aşklar vardır aşığı kör eder

Bir güzellik seviyle kapat defterini...





14.10.2003                     Mustafa GÖKÇEK







            DUMANSIZLIK

Bu aralar sigara içmeyenler çoğaldı

Yapılan zamlar mı etkiledi yoksa

Ciğerlerimiz mi iflas etti tahlillerimizde

Velhasıl bir ortam sanki bayram havası

Birde bu şenliğe dumansızlar dahil oldu

Ne güzel şey dumansız olmak

Oysa dumansızlık çürümüş bir elma

Kurtçukları yeşillendiren tütün gibi

Sitemlerin ayyuka çıktığı düzlemde

Bir el tavla oynamak toplantılardan

Toplantı yapmaktan daha iyidir

En iyisi de balkonda oturup sigara molası...



 15.10.2003                          Mustafa GÖKÇEK



	MADAM KONTES

Tırnaklarının cilası gelmiş ojelesene

Bakmıyorsan yazık etme tırnaklarına

Kadınsı olmaya devamsa bil bunları

Bil ki yadsımayalım seni madam kontes

Ne acılara şato kurmuşsundur 

Şatolar yıkıp kaleler yıkmışsındır

Ateşler taşır sevda yüklüyken

Nice yeminlerini yüreğinde saklarken

Sevda düş derken ömür geçti

Saklı olduğun göz yaşlarından

Sen seni saklayamazsın unutma

Yüreğini kanatma artık madam kontes...



15.10.2003	Mustafa GÖKÇEK







	GÖLGELER

Bugün yeniden doğmak istiyorum

Akşamları çağrıştıran gölgeleri kucaklayıp

Gün ışığını kendimce lütuf sayıp

İsyanlarımı biriktirdiğim yüreğimi istiyorum

Usulca nemlenen gözlerim 

Ayrılıklara bağlanan yüreğim

Bir göç taşır yersiz yurtsuz karanlıkta

Gölgem bile olsa doğmalı inadına...	





15.10.2003                     Mustafa GÖKÇEK







	



	ALDIRMADAN YÜRÜ



Aldırmadan yürü ahım kalacak sonra

Rüzgarın olmazsa külün dolaşır ortalıkta

Gün batımı can bedende tükenir belki

Sevmelerimiz bile firari ağlamadan yürü

Mavzerini doğrulttuğunda kanım akmaz

En güçlü yaranın kurşunu yüreğimde 

Atış poligonuna gerek yok on iki için

Kırmızı bir gül yeter be çingenem

İntikam saati yüreğimi sızlatıyor

Duygularımı katledip katilim olma

Gururlu ve onurlu ol daima aldırma

Ama ne olur yüreğimi parçalarcasına yürüme...



20.10.2003	Mustafa GÖKÇEK





     DOKUNAMAM DÜŞLERİME



Serseri bulutlar düşlerimi topladı yine

Beyhude kederlerimden geçtim

Hazinemdir dokunamam düşlerime

Gece olduğunda ve ben üşümezsem belki

Zalimlerin kahyaları çoğaldı 

Yükseklere bakmaktan ayaklarına 

Çorapları giymekten gocunanlar

Başkalarının başına der, ayaklarını unutanlar

Göçebe uykumun yarısı geceye gebe

Şarabın koruğunu aldık bekletmeye

Ateşin közü düşlerimde soğudu

Biriken düşlerimin sandığına kilit vurdum...

		

	

23.10.2003                               Mustafa GÖKÇEK





	BİR GÜZELLİK

Sıcaklığını duyuyorum vuslat yakın

Yumma gözlerini uyumamaya çalış

Sabah olunca bir güzellik ülkemde

İçimde bir ıslaklık yağmurdan sonra

İsyanlarına kucak açtırmayan dostlar

Alçaltın benliğinizi kırılan kalemlere

Seyirci kalmayın küçük bir serzenişe

Tabutsuz, kefensiz yollayın beni...





23.10.2003                      Mustafa GÖKÇEK







RÜZGARLA SUNULAN MELEK SESİ



Bir rüzgar, bir deli rüzgar

Uğulduyor, uğulduyor, uğulduyor

Masamda bir melek, azrailmiş

Kulağıma, ölümden yana bir şeyler fısıldıyor

Mabedimde Tanrıyım ya, sorguluyorum

Cesaretimle siluetine baktığımda

Gözlerimle bıyık altı gülüşünü yakalıyorum

Daha sıran var diyor, merak etme...





26.10.2003                         Mustafa GÖKÇEK

												

	

	





	   AYDINLIĞIN GÜLLERİ

Bana bir şeyler çağrıştıran imgem düşümde

Soluk benizli denizde ve bir takadayım

Yozlaşan parmağımda dikenin kanı

Hiçliğin peşindeyken bir demet gül yüreğimde

Damarda kan durmaz diye boşa akan kanlarımız

Karanlığa çoğalttı aydınlığımıza koşan gülleri

Karalar bağlayıp kıyıcığımıza çöktüğümüzde

Nice ağıtlar ağıt olur şenliklerimizde

Cihan dolaştım esaretimi anlatmaya

Kör dövüşü yapan aydınların güllerine

Topraklarının bile topraksızlığını 

Anlattılar, anladım ama nafile 

İçimi sızlattılar kanayan parmağım gibi

Oysa kanayan yüreğim aydınlığın gülleri 

Alnında ışığı hisseden aydın topraksız

Toprağını güllerle bezeyen aydın, dikensiz olur...



                                               

27.10.2003                                  Mustafa GÖKÇEK    





		

		A-SOSYAL ŞAİR

Dışarıda çöp kamyonlarının gürültüsü

Balkonda hijyenik şiirini yazan şair

Bence içeri girmeli açık hava ilhama zararlı

Hem gürültü, hem okumama a-sosyal şair

Şair kalem tutmalı ekinli ve esinli olduğunca

Çiftçi buğdayını ekmeli sıcak ekmekleri kucaklamalı

Aşık sazının telleriyle esmeli ozanlığını bellercesine

Kalem tutan eller nice şairleri sosyalleştirmeli



01.11.2003                                   Mustafa GÖKÇEK



																																						

																									





	ÇILGIN GÖÇ

Ayrılıkların en çılgını nedir dersiniz

Kuşatılmış yüreğimce göçleri yaşamak

Aşkın son bilmecesi gecekonduda başlar

Gözyaşım bittiğinde yağmur yağar

Çılgınlıklar yiter göçlüğün yittiğinde

Kuraklığın pekiştiği yer sarmadadır insanı

Yıllardır beklediğim güz mevsimi

Yağdırmasa da yağmurunu çocukların üstüne

Balçık gibi yoğrulan çamuruna

Ayrılıklarımı, hüzünlerimi katık ettim

Artık sensiz gelen sabahlara da günaydın

Mülteci yüreğim bedenimden ayrı, yine göç yaşıyor...  

15.12.2003                           m.gökçek   







	ÇALIŞIRKEN

Sana şiirler sunarken Amadeus Mozart kulağımda

Yüreğim lirik bir keman sesiyle isyanlaşıyor

Tuttuğum kalem, yazdığım kağıt şeffaf

Elim, elim değil sanki kayıyor ıslaklığıyla

Yozlaşan dünyada virtüöz  değilim

Sende şiirlerimi kucakla, Amadeus’u dinle

Ve sakın bana, duvarda asılı mavzerimi indirtme

Çünkü meskenim artık evim oldu...



22.12.03                                               Mustafa GÖKÇEK





	





SANCIM İSYANIMA



Kavrulan insanlığıma yanarım					

Sabahlar tez olmalı, içimde isyanım 

Sancılıyım, ocaksız köylerimden yana

Odun yerine yansam ocağınız tüter elbet

Umurunda mıyım memleketim

Hasretin sarıyor ne kadar ıslansam da

Badanasız evimde, kandilin ışığında

Kandilin isini sil çocuğum, iki damla gözyaşınla 



31.12.2003                                       Mustafa GÖKÇEK









		

		KÜLLENDİM

Bir söğüt gölgesinde anılarımı dinliyorum

Ekmek arası sigarama katık

Tuz bulamacında soğuk namlular

Unuttun mu beni anne, öpmeye kıyamadığın oğlunu

Yeryüzündeki acılar yüreğimi kanattı

Savrulan külümle kendimi yarattım

Sarhoş oldum anne, mey sandığım kanımı içtiğimde

Hava puslandı yağmur yağıyor, yoksa söğüt mü ağlıyor

Geceler olunca konar göçerim

Bir göçmen kuşu olurum, suçüstü dağlanmadan

Kabrine gelirim karanlığın bağrında

Küllendim artık anne, geliyorum çam ağacıyla...



03.01.2004                                           m.gökçek







	MUM GİBİ

Gibilerle doldurduk şu yaşantımızı

Karanlık yollardan ırak, mum barındırdık

Hiç yoktan mum iyidir desem de

Yine de ışığı bulanı tanrı affetsin

Ağlaşırken mumun ışığında ve bir köşede

Romantizmi yakalamıştı insanoğlu

Yıllar yılları kovaladı, zavallı Edison

Bir aşık bile olamamıştı, bu dünyadan göçtüğünde...



04.01.04	m.gökçek', 'UNUTULMUŞLUĞUN İSYANI Hani bazılarınca efkarın derdi unutulmuşluğun anısıdır Aşkı görmek aşkı yaşamaya yeter mi gözüm Yaşam girdabı bir oyun...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Gökçek']::text[], 8.5, '{"poet":"Mustafa Gökçek","poet_slug":"mustafa-gokcek","theme":"Türk Şiiri","is_hero":false,"total_lines":204,"source_url":"https://www.antoloji.com/unutulmuslugun-isyani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
