INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nedensiz Göz Yaşı', 'nedensiz-goz-yasi-sevil-oymak-thd1n', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'OLMASI GEREKİRMİ BU YAŞLARIN

NEDENİNİ BİLMEDEN

HEM ÜSTELİK BİR ARTISI YOK Kİ

YADA EKSİLEN YANI HAYATIN

TEK DÜZEYKEN HERŞEY

NEDEN AĞLAMAKLI GÖZLER

AYNADA GÖRÜNCE GÖZ BEBEKLERİNİ

NEDEN SÜZÜLÜVERİR DAMLALAR

ÜSTELİK YOKKEN BİR AYRILIK

YAHUT KAVUŞMUŞLUĞUN ÇOÇUK NEŞESİ

      

                                                              İstanbul, 19/03/1999', 'OLMASI GEREKİRMİ BU YAŞLARIN NEDENİNİ BİLMEDEN HEM ÜSTELİK BİR ARTISI YOK Kİ YADA EKSİLEN YANI HAYATIN TEK DÜZEYKEN HERŞEY NEDEN AĞLAMAKLI G...', ARRAY['Türk Edebiyatı','Şiir','Sevil Oymak']::text[], 8.5, '{"poet":"Sevil Oymak","poet_slug":"sevil-oymak","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/nedensiz-goz-yasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gitmek zamanı', 'gitmek-zamani-sair-shimalwest-hepoa', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'gitmek zamanı şimdi

binip bir otobüse

bilmeden nereye

bakmadan geriye

düşünmeden neden diye

gitmek zamanı şimdi

el sallamadan

el sallanmadan

arkandan kimse ağlamadan

göz yaşını kimde görmeden

gitmek zamanı şimdi

bir kalemde silerek herşeyi

dinlemeden hiçkimseyi

yanına almadan hiçbirşeyi

dönmemek üzere

kendine yenilmeyip

dönmemek üzere

gitmek zamanı şimdi

gülüyorsun değil mi gidemem diye

sorumluluktan kaçamam diye

ama

kaçmak değil bu gidiş

hayata yeni bir geçiş

daha geç kalmadan

daha fazla kaybetmeden

daha fazla üzülmeden

daha fazla üzmeden

gitmek zamanı şimdi

binip bir otobüse

sadece gidiş biletiyle', 'gitmek zamanı şimdi binip bir otobüse bilmeden nereye bakmadan geriye düşünmeden neden diye gitmek zamanı şimdi el sallamadan el sallanmadan...', ARRAY['Türk Edebiyatı','Şiir','Şair Shimalwest']::text[], 8.5, '{"poet":"Şair Shimalwest","poet_slug":"sair-shimalwest","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/gitmek-zamani-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kazandım', 'kazandim-aziz-pinar-rsg52', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sormayın dostlarım neyin var diye

Bakın saçlarıma aklar kazandım

Söğüt gölgesinde geçmedi ömrüm

Alnımdan damlayan terler kazandım...

Gurbeti yaşadım özlemi içtim

Sıla kucağında huzuru seçtim

Nice fırtınayı yelkensiz geçtim

Püfür püfür esen yeller kazandım...

Yağmursuz toprakta başaklar gördüm

Nasırlı ellerde hayatı ördüm

Malımdan yetmedi gönülden verdim

Dikenli olsada güller kazandım...

Gün oldu sarışın güldü yüzüme

Gün oldu kumralı geldi sözüme

Gün oldu esmeri girdi gözüme

En deli,en çılgın aşklar kazandım...

Sevgi sermayemdi her yıl artırdım

Gönül kazancımı bine çıkardım

Kararan kalplere ışık aktardım 

Mutluluk yağdıran düşler kazandım...

Yaratılan cana saygıyla baktım

Barıştan yanaydım savaşta yoktum

Haksızın yanında haklıyı tuttum

Arkamdan vurmayan dostlar kazandım...

Çok şükür Allah''a kulluğu yaptım

Bir tek tanrı diye ben ona taptım

Haramdan uzakta helali tattım

Amin amin diyem diller kazandım...', 'Sormayın dostlarım neyin var diye Bakın saçlarıma aklar kazandım Söğüt gölgesinde geçmedi ömrüm Alnımdan damlayan terler kazandım... Gurbeti...', ARRAY['Türk Edebiyatı','Şiir','Aziz Pınar']::text[], 8.5, '{"poet":"Aziz Pınar","poet_slug":"aziz-pinar","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/kazandim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelip Geçici', 'gelip-gecici-aziz-pinar-twblk', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gönülden gönüle çağlar akarım

Kimi gün umarsız,kimi seçici

Senin gözlerine hayran bakarım

Diğer baktıklarım gelip geçici...

Saatler yaşamdan geçsede hızla

Gönül her güzele baksada hazla

Seni çağırınca gelsende nazla

Diğer sevdiklerim gelip geçici...

Dünya yollarında gezmişte olsam

Her ülkeden bir gül seçmişte olsam

Sunduğun şaraptan içmişte olsam

Diğer içtiklerim gelip geçici...

Hüzünde,neşede geldi ömrüme

Hasrette,vuslatta oldu gönlüme

Yarınım seninle dönmem dünüme

Diğer gördüklerim gelip geçici...

Kendini kalbimde bir tek bilesin

İçime çektiğim o ilk nefessin

Duyup duyacağım en son hevessin

Diğer duyduklarım gelip geçici

Diğer sevdiklerim gelip geçici...', 'Gönülden gönüle çağlar akarım Kimi gün umarsız,kimi seçici Senin gözlerine hayran bakarım Diğer baktıklarım gelip geçici... Saatler yaşamdan...', ARRAY['Türk Edebiyatı','Şiir','Aziz Pınar']::text[], 8.5, '{"poet":"Aziz Pınar","poet_slug":"aziz-pinar","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/gelip-gecici-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seviyorum Seni', 'seviyorum-seni-seyit-nusret-ozturk-8yuwy', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seviyorum seni

..........aşığım sana

Sen gelinceye kadar bana

dört kez çaldı

..........gönül kapımı

Aşk denilen

..........kızıl saçlı ejderha

Püskürttü yüreğimden içeri

yerden göğe doğru

.........................açılan

..............................ağzından

cehennemi alevini

Aşksız yaşayamıyorum

aşk olmadan

..........içimde oluşan

.........................boşluk

sıkıştırıyor beni

Hayat

.....yitiriyor anlamını

Oltadaki balık gibi

...............çırpınıyorum

Seviyorum seni

..........aşığım sana

yüreğim kıpır kıpır

Atıyor

.....bin devirli motor gibi

Hep seni düşünüyorum

Bakışlarım

..........kilitleniyor uzaklara

Azıyor melankolim

Sigaramdan çektiğim nefes

..............................daha bir derin

........................................yakıyor ciğerimi

Gözlerimden akan yaş

ıslatıyor

..........masamın üzerindeki

........................................hayalini

Hüzünden geberiyorum

Seviyorum seni

..........aşığım sana

Nedendir

..........bu hüzün

....................bu melankoli

Halbuki

..........çıkmalıyım

....................İstanbul sokaklarına

Topuklarımı

..........vura vura

....................toprağa

Koşmalı

..........koşmalı

....................koşmalıyım

Ses tellerimi

..........kopartırcasına

avazımın

..........çıktığı

...............kadar

....................haykırmalıyım

Sana olan aşkımı

Peki

nedir beni

..........alıkoyan

Ayaklarımla toprakta

sesimle havada

aşkımın izini

..........bırakmaktan

Leyla’ya Mecnun olmak

aşkıma karşılık

..........bulamamak mı yoksa

Öyle bile olsa

...............ne yazar

Bahşettiğin bu aşkın ateşinde

........................................erirken yüreğim

............................................................azar azar

Tüm varlığımla

..........seni sevmeye

....................devam edeceğim', 'Seviyorum seni ..........aşığım sana Sen gelinceye kadar bana dört kez çaldı ..........gönül kapımı Aşk denilen ..........kızıl saçlı ejderh...', ARRAY['Türk Edebiyatı','Şiir','Seyit Nusret Öztürk']::text[], 8.5, '{"poet":"Seyit Nusret Öztürk","poet_slug":"seyit-nusret-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":77,"source_url":"https://www.antoloji.com/seviyorum-seni-25-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '46-47''Ye uygun bir aşk', '46-47-ye-uygun-bir-ask-engin-ozcan-141kb', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Seni,

Bir deli raporunun izniyle seviyorum...

46-47 ye uygundur diyor akıl sağlığım...

Hani sevmeye yeter babında...

Sevmeye ve sövmeye yetkin kılıyor beni,

Doktorlarım,

Oysaki bir doktor nasıl muayene eder aşkı? ? 

Yani sevmek tanısını nasıl koyarki,

İnsanın yüreğine? ? 

Telaşlı bir SSK kuyruğunda buluyorum gölgeni,

Sade poğoça ve simit gibi.

Sıradan oysa, bildiğim bir tad gibi.

Sıradan ve gösterişsiz seviyorum seni.

Nezle mendili, grip salgını,

Verem mikrobu ve patolojik bir uyuz gibi.

Yeni aids olmuş bir hayat adamı gibi,

Seviyorum...

46-47 raporu yetkin kılıyor sevmemi..

benim suçum ne? ? ? 

15 10 2004

Engin', 'Seni, Bir deli raporunun izniyle seviyorum... 46-47 ye uygundur diyor akıl sağlığım... Hani sevmeye yeter babında... Sevmeye ve sövmeye yetk...', ARRAY['Türk Edebiyatı','Şiir','Engin Özcan']::text[], 8.5, '{"poet":"Engin Özcan","poet_slug":"engin-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/46-47-ye-uygun-bir-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alışkın bir sevgiyi yaşamak', 'aliskin-bir-sevgiyi-yasamak-engin-ozcan-6f4o9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bana, 

sevmelerime alışabilirmi bu yürek? ? 

Alışkın bir aşkı nasıl yaşarız... 

Evcil bir timsahı sevmek gibi... 

Alışkın bir aşk yaşamak...

Mesela...

Alıştırabilirmisin beni içine? 

Kapsanmış bir küme olabilirmiyiz? 

İç kapsar bir aşkı yaşayabilirmisin? ? 

Beni hapsadebilirmisin? ? 

Sonra, kelepçeleri gevsetip,

kendi içinden firar ettirebilirmisin beni? 

Hüküm giydirip infaz edebilirmisin? 

Sana dokunmamı engelleyebilirmisin? 

Sözlerle seni okşamamı,

hayallerini tahrik edebilmemi

saali bir bomba gibi

tehlikeli düşünceler kurmamı engelleyebilirmisin? ? 

Beni ne kadar sevebilirsin nefretinle? 

15/10/2004

Engin', 'Bana,  sevmelerime alışabilirmi bu yürek? ?  Alışkın bir aşkı nasıl yaşarız...  Evcil bir timsahı sevmek gibi...  Alışkın bir aşk yaşamak......', ARRAY['Türk Edebiyatı','Şiir','Engin Özcan']::text[], 8.5, '{"poet":"Engin Özcan","poet_slug":"engin-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/aliskin-bir-sevgiyi-yasamak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kargacık burgacık', 'kargacik-burgacik-gencay-coskun-74ym0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kargacık burgacık 

Bir hayatın

Bırgalanması

Üzerdi insanı 

Hangi akıllı gelip de 

Üstüne vazife olmayarak

Çomak sokardı

Duyguların en gizemli yerine 

En derinden kanardı 

Yaralardan bir acı türkü doğardı

Dağlanan tertemiz yüreği 

Gönderirlerdi kendi öz memleketine 

Geride bir yazı mahkumdu 

Oda silineceği günü beklerdi 

Kargacık burgacık bir umutla', 'Kargacık burgacık  Bir hayatın Bırgalanması Üzerdi insanı  Hangi akıllı gelip de  Üstüne vazife olmayarak Çomak sokardı Duyguların en gizeml...', ARRAY['Türk Edebiyatı','Şiir','Gencay Coşkun']::text[], 8.5, '{"poet":"Gencay Coşkun","poet_slug":"gencay-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/kargacik-burgacik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölene Dek', 'olene-dek-seyfettin-yazar-xksx4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gözlerimi kapatmak istemiyorum, taki ölene dek

Hayalin gözlerimden gitmesin diye

Çünki ben rüya göremem

Sana koşmak, sarılıp öpmek isterim

Ayaklarıma prangaları, ellerime kelepçeleri bilmeden kendim vurmuşum

Olmuyor baksana vakitsizim, zamansızım, kardelenim hayal sevgilim

Seni seviyorum aşığım demek istesemde diyemiyorum

Dilimi kendi dar ağacımda urgan yapıp  boynuma dolamışım

Özüyle gönlüm demir parmaklıklar arkasında

Möhebbet hapse mahkum olmuş, benim

Hayal ötesi hayal sevgilim...', 'Gözlerimi kapatmak istemiyorum, taki ölene dek Hayalin gözlerimden gitmesin diye Çünki ben rüya göremem Sana koşmak, sarılıp öpmek isterim A...', ARRAY['Türk Edebiyatı','Şiir','Seyfettin Yazar']::text[], 8.5, '{"poet":"Seyfettin Yazar","poet_slug":"seyfettin-yazar","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/olene-dek-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Durak olmasın', 'durak-olmasin-gencay-coskun-bmj9p', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bomboş duvarlarda

Bulamadım kendimi 

Duvarlara bakarken 

Çizemedim resmini

Asamadım kendimi 

Bomboş tavana

Bir şey takılsa aklına 

Yapamazsın 

Bir şeye kızsan

Durduk yere çatamazsın 

Birisi çizmeyi aşsa 

Susmak zorundasın 

Hep mazsın mazsın 

Bence artık 

Bu hayatta hiçbir durak olmasın

Birde boş duvarlar', 'Bomboş duvarlarda Bulamadım kendimi  Duvarlara bakarken  Çizemedim resmini Asamadım kendimi  Bomboş tavana Bir şey takılsa aklına  Yapamazsı...', ARRAY['Türk Edebiyatı','Şiir','Gencay Coşkun']::text[], 8.5, '{"poet":"Gencay Coşkun","poet_slug":"gencay-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/durak-olmasin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağzı bozuk bir ozandı', 'agzi-bozuk-bir-ozandi-gencay-coskun-9sz8c', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İstanbul sustu 

Dünya sustu 

Hayat sustu 

Korktular mı  benden 

Tek çıt bile yok 

Zaten iki çıt hiçbir araya gelmedi 

Gelmezdi de 

Ortada yada beride 

Kulaklarda gezinen

Bir ses arıyorum 

Ama bulamıyorum 

Kaçmasalar yakalamam an meselesi 

Çaktırmadan geliyorum 

Ürkütmemek gerek hayatı 

Ürkütmemek gerek insanları 

Canıma 

Kanıma 

Dokunuyor bazıları 

Her halde ağrıyordur

Bazı yanları 

Bir can olarak 

Canım için 

Dindireceğim tüm ağrıları

Birde kaçırmasalar zamanı 

Alacakların en güzeli de

Kalaylı bir Kazandı

Kalaycısı ağzı bozuk bir ozandı', 'İstanbul sustu  Dünya sustu  Hayat sustu  Korktular mı  benden  Tek çıt bile yok  Zaten iki çıt hiçbir araya gelmedi  Gelmezdi de  Ortada ya...', ARRAY['Türk Edebiyatı','Şiir','Gencay Coşkun']::text[], 8.5, '{"poet":"Gencay Coşkun","poet_slug":"gencay-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/agzi-bozuk-bir-ozandi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaldırımlarda', 'kaldirimlarda-gencay-coskun-v4cxt', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yürümek zorundasın  şimdi 

Yalnız başına 

Sap başına 

Taş Başına 

Parke taşlı kaldırımlarda 

Hesabını almak var şimdi 

Her kaldırım taşında 

Akıtılan gözyaşlarının 

Sadece benliğini alıp götüren

Parke taşlı kaldırımlar 

Birde ayak sesleri 

Kaldırıp kafanı 

Diksen semaya 

Bir tek ay vardı yalnızca orada 

Ha gayret yollara 

Ya Allah kaldırımlara

Hadi Yallah kaldırımlara 

Şaka maka gidiyorsun

Dipsiz yıldırımlara

Onu bunu gördüğümü 

Katarak anılara 

Yürümek var şimdi 

Yalnız başına

Yağmurlarda 

Parke taşlı kaldırımlarda 

İliklerine kadar 

Tüm dokuma yada sentetik kumaştan eşyalar 

Sıklam sırıl yada sırıl sıklam 

Suya doyup aşık oldular 

Açıkçası zoraki bir birliktelikti onlarınki 

İç çamaşırına kadar ıslanmak 

Ahmaklık mıydı sabır taşımı hiç bilinmezdi 

Hem yağmurun sesi 

Hem kaldırımın sesi 

Hem kendim sesim 

Çıldırtıyordu  beni 

Sesi kesmek lazımdı 

Yaşamak aşkına 

Kimseye kıyamamak başa bela

Kaldırımlarda sen varmışçasına

Aramak önüme çıkan her şeyde 

Üzülmek var yokluğuna 

Bilsem de bilmesem de', 'Yürümek zorundasın  şimdi  Yalnız başına  Sap başına  Taş Başına  Parke taşlı kaldırımlarda  Hesabını almak var şimdi  Her kaldırım taşında ...', ARRAY['Türk Edebiyatı','Şiir','Gencay Coşkun']::text[], 8.5, '{"poet":"Gencay Coşkun","poet_slug":"gencay-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/kaldirimlarda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söyle', 'soyle-mehmet-ali-suzen-jmdfx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sevmişse zavallı gönlüm

Bulamamışsa karşılığını

Söyle

O sevgi neye yarar? 

Gece rüyalarım

Dolsa da seninle

Gündüzleri yoksan yanımda

Söyle 

Gündüzlerim neye yarar? 

Gözlerim arar da seni

Bulamazsa hemen

Söyle

O gözler neye yarar? 

Kalbimden kaçarsan bir gün

Ve kalbim boşsa artık

Söyle

O kalp neye yarar? 

M.S.ÖZTÜRK', 'Sevmişse zavallı gönlüm Bulamamışsa karşılığını Söyle O sevgi neye yarar?  Gece rüyalarım Dolsa da seninle Gündüzleri yoksan yanımda Söyle  ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Süzen']::text[], 8.5, '{"poet":"Mehmet Ali Süzen","poet_slug":"mehmet-ali-suzen","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/soyle-39-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mecburiyetin Cesareti', 'mecburiyetin-cesareti-gencay-coskun-y15hd', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Aldıklarımı

Yaşadıklarımı

Taşıyordum 

Bir sonraki zamana

Yalan değildi acı 

Öyle gerçek

Öyle can yakıyordu ki 

Gerçekti bu kırılganlık 

Harbiden kırılmıştım 

Elim ayağım buz tutmuştu 

Yargısız infazlarım 

Gece yarıları

İntikam hücrelerine  işlenmişti

Tek taraflı irade beyanları 

Ömür bileyliyordu

Kendi gönlünü kesip 

Kan kokusunu salıyordu geceye 

Öldüresi dudaklardan 

Karanlık bir ferman dökülüyordu 

Beni karanlığa gömen 

Işığımı boğan bir ferman 

Gök yıkılsa üstüme 

Yer yarılsa 

Kalleşlik bana yakışmazdı 

Ellerim dolana uzanmazdı 

Düşürmek için gidersen 

Buğuda kalırdın 

Mecburiyetin hararetli 

Bunalımlı sıkık saatlerinde 

Bu yürek hiç susmazdı 

Özlemle dolu sevdam 

Boynuma sarılırdı 

Binlerce kelime ordusu içindeyken 

Onlarla boğuşup tam adam etmişken 

Bir tanesine takılır boğazıma 

Susar tıkanıp kalırdım 

İçim acırdı 

Tek nefesi aldığım dünyamdı 

Hayallerle dolu boncuklu köprüler

Çaresizlik ve umutsuzlukta son kale 

Bir kalem 

Bir kağıt

Yazılırdı içten içe acı bir destan 

Bilmiyordum 

Ne yaptığımı 

Umut sıkıyordum umut

Kışın çıkardım benim olmayacak yaylalara 

Tırmanıp ağaçlara 

Umut toplardım umut

Sıkacaklara yanaşırım 

Bir hayalin püskülünde 

Umut sıkarım

Sözler kelimeler imparatorluğunda 

Canım dudaklarımın ucunda 

Vurulup parçalanıp ölüyordum 

Hissettirmeden yeniden  dikiliyordum 

Yara izleri ölümlük kalıyordu 

Mecburiyetin hararetli saatleri 

Hiç ama hiç geçmezdi 

Geçen yaşamdan eksilttiklerindi

Mecburiyetin cesareti 

Yalandan olurdu 

Mecburiyetin cesareti 

Ancak ve ancak mecburi olurdu 

Bin dokuz yüz doksan sekizin güzü 

Vuruyordu özü', 'Aldıklarımı Yaşadıklarımı Taşıyordum  Bir sonraki zamana Yalan değildi acı  Öyle gerçek Öyle can yakıyordu ki  Gerçekti bu kırılganlık  Harb...', ARRAY['Türk Edebiyatı','Şiir','Gencay Coşkun']::text[], 8.5, '{"poet":"Gencay Coşkun","poet_slug":"gencay-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":66,"source_url":"https://www.antoloji.com/mecburiyetin-cesareti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yepyeni bir dünya açılırdı', 'yepyeni-bir-dunya-acilirdi-gencay-coskun-f5yz2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yeniye umutla 

Geçmişe hasretle bakarken 

İçinden geçtiğimiz zaman 

Hep bizi alır götürür koynunda 

Yeri zamanı geldiğinde 

Bir alacalıkta bırakacaksa da

Gerçek sahibine 

O günde hazır olmak 

O günde dimdik ayakta durmak 

Yalnızca arada kalmaktı 

O aradan yepyeni bir dünya açılırdı 

Bu sefer hiç kapanmazdı', 'Yeniye umutla  Geçmişe hasretle bakarken  İçinden geçtiğimiz zaman  Hep bizi alır götürür koynunda  Yeri zamanı geldiğinde  Bir alacalıkta b...', ARRAY['Türk Edebiyatı','Şiir','Gencay Coşkun']::text[], 8.5, '{"poet":"Gencay Coşkun","poet_slug":"gencay-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yepyeni-bir-dunya-acilirdi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çırpıntı mevsimiydi', 'cirpinti-mevsimiydi-gencay-coskun-2g2n8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kuş dala kondu 

Dal sevindi, coştu 

Çiçeklerini giyindi 

Yapraklarını açtı 

Rüzgarın delisiydi 

Mevsim öldüren 

Bir esti 

Pir esti

Dal yaprağını, çiçeğini attı 

Yuvasını dağıttı

Kuş uçtu 

Çırpıntı mevsimiydi 

Umudun öze dönmesiydi 

Canımın yangınlarında

Kalplerde çarpıntı 

Serseri kuşların kanadında çırpıntı', 'Kuş dala kondu  Dal sevindi, coştu  Çiçeklerini giyindi  Yapraklarını açtı  Rüzgarın delisiydi  Mevsim öldüren  Bir esti  Pir esti Dal yapra...', ARRAY['Türk Edebiyatı','Şiir','Gencay Coşkun']::text[], 8.5, '{"poet":"Gencay Coşkun","poet_slug":"gencay-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/cirpinti-mevsimiydi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hepsi oyun muydu?', 'hepsi-oyun-muydu-gencay-coskun-4tv0l', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İnsanların yalanlarını 

Vuramam yüzüne 

Kuş gibide uçamam 

Hayallerime dalmışım 

Birde garip bir hüzne 

Kendini

Sakın üzme 

Yalnızlığı 

Sakın çizme

İçimdir 

Beni susturan 

Çaresizliktir

Kan kusturan 

Ezildikçe çoğalan 

Sevdikçe kanayan 

Dinmeyen yaralar 

Hiç Bitmeyecekmiş gibi yasaklar 

Hasret sona ererdi 

Gözlerinde 

Umutlarım yıkılırdı 

Sözlerinde 

Hiç yoktum ben 

Hayallerinde 

Ölmek korkutmuyor beni 

Geçen zaman gibi 

Bende geçiyordum artık 

Devrilen koca çamlar gibi 

Yasak mıydı yaşamak 

Sevmek suç muydu 

Anlayamadan sevdiğim 

Hepsi oyun muydu

Taşı çatlatan

Yüreği dağlayan', 'İnsanların yalanlarını  Vuramam yüzüne  Kuş gibide uçamam  Hayallerime dalmışım  Birde garip bir hüzne  Kendini Sakın üzme  Yalnızlığı  Sakı...', ARRAY['Türk Edebiyatı','Şiir','Gencay Coşkun']::text[], 8.5, '{"poet":"Gencay Coşkun","poet_slug":"gencay-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/hepsi-oyun-muydu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Işıksız bir halkada', 'isiksiz-bir-halkada-gencay-coskun-5z3j1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sevgi biter miydi? 

Gün biterdi 

Aşklar unutulmuştu

Kıpraşmanın baharında 

Yaşanan herşey boş

Her saat anlamsız 

Sonbaharda savrulan 

Yapraklar

Ve ömründen geçen 

Günlerin

Farkı nedir ki 

Dünya yakılırdı 

Sevgisiz odamda

Işıksız bir halkada kalırdım', 'Sevgi biter miydi?  Gün biterdi  Aşklar unutulmuştu Kıpraşmanın baharında  Yaşanan herşey boş Her saat anlamsız  Sonbaharda savrulan  Yaprak...', ARRAY['Türk Edebiyatı','Şiir','Gencay Coşkun']::text[], 8.5, '{"poet":"Gencay Coşkun","poet_slug":"gencay-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/isiksiz-bir-halkada-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her bitişte', 'her-bitiste-gencay-coskun-d25gi', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yalancı şeyler 

Bir gün biter

Sızısı kalırsa da 

Geçer gider 

Son dediğimiz yollar

Elbet bir gün biter 

Her bitişte

Tutmasını bilene 

Yeni bir şey başlar', 'Yalancı şeyler  Bir gün biter Sızısı kalırsa da  Geçer gider  Son dediğimiz yollar Elbet bir gün biter  Her bitişte Tutmasını bilene  Yeni b...', ARRAY['Türk Edebiyatı','Şiir','Gencay Coşkun']::text[], 8.5, '{"poet":"Gencay Coşkun","poet_slug":"gencay-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/her-bitiste-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Baksam', 'baksam-gencay-coskun-hebdi', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Güneşi yakalamak 

Benim işim değildi 

Ne kadar yaklaşsam 

Ellerimi yakar

Uzanamazdım 

Benden çok uzaktı 

Parıldardı ışık saçardı 

Gözlerine 

Bir kez olsun 

Baksam 

Güneşim 

Yüreğimde doğardı', 'Güneşi yakalamak  Benim işim değildi  Ne kadar yaklaşsam  Ellerimi yakar Uzanamazdım  Benden çok uzaktı  Parıldardı ışık saçardı  Gözlerine ...', ARRAY['Türk Edebiyatı','Şiir','Gencay Coşkun']::text[], 8.5, '{"poet":"Gencay Coşkun","poet_slug":"gencay-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/baksam-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Büyüdüm', 'buyudum-adulera-ayza-ntyxf', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Büyüdüm de  ne oldu sanki

Oyuncaksız oyunsuz kaldım

Yaramazlıksız kaldım

Uyandım bunları düşündüm 

Kalbim duracak sandım.

Bir sürü mesuliyet aldım

Büyüdüm de ne oldu sanki

Aç

Susuz

Sensiz

Hissiz

Sebepsiz

Kaldım

Ölüyorum belki şimdi

Ama olsun

Bende bir zamanlar

Çocuktum

Her şeyim vardı

Elimde sermaye

Sevdalarım kaldı', 'Büyüdüm de  ne oldu sanki Oyuncaksız oyunsuz kaldım Yaramazlıksız kaldım Uyandım bunları düşündüm  Kalbim duracak sandım. Bir sürü mesuliyet...', ARRAY['Türk Edebiyatı','Şiir','Adulera Ayza']::text[], 8.5, '{"poet":"Adulera Ayza","poet_slug":"adulera-ayza","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/buyudum-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Terk ettim', 'terk-ettim-sair-shimalwest-di3zi', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'seni dün akşam üzeri terk ettim

bunun için çok zorlandım

çok göz yaşı döktüm

kendimle savaştım

ama doğru olan buydu

seni dün akşam üzeri terk ettim

güneş sanki bizim için battı

rüzgar daha kuvvetli esti

yağmur yüzüme yüzüme yağdı

kendimden nefret ettim

ama doğru olan buydu

seni dün akşam üzeri terk ettim

artık kimseyi sevemem

kimsede seni bulamam

ben yalnızlığı seçtim

ama doğru olan buydu

seni dün akşam üzeri terk ettim

en zor olansa

ben ilk defa terk ettim', 'seni dün akşam üzeri terk ettim bunun için çok zorlandım çok göz yaşı döktüm kendimle savaştım ama doğru olan buydu seni dün akşam üzeri ter...', ARRAY['Türk Edebiyatı','Şiir','Şair Shimalwest']::text[], 8.5, '{"poet":"Şair Shimalwest","poet_slug":"sair-shimalwest","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/terk-ettim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sabır Ve Zaman Ve Sevgi', 'sabir-ve-zaman-ve-sevgi-ayse-birgul-yilmaz-bawka', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bazen kendimi bile anlamıyorum

İçimde eskiden kalma bir ümit taşıyorum

Bir gün anlaşılmanın hasretiyle yaşıyorum

Hayatın acımasızlığını yüklenip gidiyorum

Her zaman ki gibiyim sürüklenip gidiyorum

Hatalarımla yanlışlarımla yorduğum ruhuma

Ne denli acılar çektirdiğimi düşünüyorum da

Hüsranları, burukluğu ne varsa bozgun adına

Acı-tatlı, eğri-doğru yaşadım yada öyle sandım

Meydan okurcasına biraz aykırı davranmak istedim

Her zorluğa göğüs gerebilir üstesinden gelebilirdim

Yanımda sen olsaydın yokluğunu içime sindiremiyorum

Bilmiyorum nereye kadar bütün gücümle direniyorum

Seni aklımdan bir an silip atamıyorum, unutamıyorum

Tam üç yıldır aynı gün aynı saatte odama kapanıyorum

Hep ağlıyorum çok duygusal yoğun günler yaşıyorum

Kayıplarıma, hüzünlerime ve acılarıma gülümsüyorum

Ayakta kalabilmenin, katlanabilmenin tek yolu bu biliyorum

Giderek kendime zararlı oluyorum, galiba ben kayboluyurum

Bazen sıradan, bilgisiz, kuralsız taş kalpli biri olmak isitiyorum

Umursamaz olmalı, belki bende herkes gibi maskeler takmalıyım

Her zaman ki gibiyim... çelişkiler içindeyim, kaderciyim

Her zaman ki gibiyim... hayalciyim, güçlü görünmeliyim

....................................... tek düzeyim, artık değişmeliyim

Başkaları için yaşamaktan, yanlış seçtiğim dostluklardan,

Özveriyle yaklaşıp negatif enerjisini, sıkıntısını çektiğim,

Tozlanmış, eskici dükkanı kafalı örümcekli düşüncelerden,

Ödün verdiğim, değerinin üzerinde değer biçtiğim insanlardan,

Kurtulmalıyım, vazgeçmeliyim onları tutku, kuruntu yapmaktan

Kurtulmalıyım, bu kışkırtıcı durgunluktan bu sıkıcı suskunluktan

Kurtulmalıyım, artık karar vermeli hayır demeyi öğrenmeliyim

Bazı isimleri artık belki hemen fihristimden silmeli, hafiflemeliyim

Hayır... hayır, affetmeli, affedilmenin cezası altında ezilmelerini gör...

Biliyorum..

Yaşam hiçbir zaman hiç kimseye adil değil

lk anda kötüler kazanıyor gibi görünseler de

Ancak; sabır ve zaman ve sevgi kazanacak

Zafer her zaman iyiligin, doğruluğun, güzelliğin olacak

05/12/2004', 'Bazen kendimi bile anlamıyorum İçimde eskiden kalma bir ümit taşıyorum Bir gün anlaşılmanın hasretiyle yaşıyorum Hayatın acımasızlığını yükl...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Birgül Yılmaz']::text[], 8.5, '{"poet":"Ayşe Birgül Yılmaz","poet_slug":"ayse-birgul-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/sabir-ve-zaman-ve-sevgi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ki O...', 'ki-o-bekir-mutlu-gokcesu-osrgo', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Emin oldum

Ki o bir şiir

Düşünebildiğim

Yazmayı düşlediğim

Belki yaklaştığım

Ama hiç yazamayacağım

Emin oldum

Ki o bir aşk

Tutmak

Tutunmak istediğim

Belki yaklaştığım

Ama hiç dokunamayacağım...', 'Emin oldum Ki o bir şiir Düşünebildiğim Yazmayı düşlediğim Belki yaklaştığım Ama hiç yazamayacağım Emin oldum Ki o bir aşk Tutmak Tutunmak i...', ARRAY['Türk Edebiyatı','Şiir','Bekir Mutlu Gökçesu']::text[], 8.5, '{"poet":"Bekir Mutlu Gökçesu","poet_slug":"bekir-mutlu-gokcesu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ki-o-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Soru?', 'soru-oguz-yirmibes-n3iui', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yaşamak dediğin nedir? 

Bezen gülüp bazen ağlamak mı sadece 

Yemek yiyip yatıp uyumak mı her gece

Amaçların için çalışmak mı sonuna kadar

Ölmek mi sonra 

Haksızlıklara karşı savaşma mı el ele

Koşmak mı durmaksızın sonunu bilmediğin bir yere

Söylemek mi herkese duymak istediklerini

Yalnızlığı mı seçmek doğarken

Yada yalnız mıyız gerçekten

Aşkları mı sığdırmak engin denizlere

Tarihler yazıp noktalar mı koymak istediğin yerlere

Yoksa öldürmek mi insanları bir hiç uğruna

Vurmak mı kardeşini paranın yolunda

Alçaltıp küçültmek mi insanları 

Ağlatmak mı açlıktan acı çeken çocukları

Katletmek mi daha doğmamış minik yavruları

Söylemek mi yalanlar batan güneşin ardından

Seyretmek mi sapıkça güzelim kadınları

Çoraklaştırmak mı yoksa verimli toprakları

Söndürüp güneşi bitirmek mi umutları

Diyeceksin ki bana ama aşk var yaşamda 

O mükemmel değimlidir değmez mi yaşamaya

Tabi ki aşk vazgeçilmezlerin ilki

Ama öldüremem onun için masum bildiklerimi', 'Yaşamak dediğin nedir?  Bezen gülüp bazen ağlamak mı sadece  Yemek yiyip yatıp uyumak mı her gece Amaçların için çalışmak mı sonuna kadar Öl...', ARRAY['Türk Edebiyatı','Şiir','Oğuz Yirmibeş']::text[], 8.5, '{"poet":"Oğuz Yirmibeş","poet_slug":"oguz-yirmibes","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/soru-41-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Köşe köşe çizdim dünyayı, hatta pencerenin karanlıkta aynalaşmasını', 'kose-kose-cizdim-dunyayi-hatta-pencerenin-karanlikta-aynalasmasini-lzcramcil-ceyhun-erdem-xtbt6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir yolculuktu iç çekmeler

yolu ıssızlıktan ve demir düdüklerden geçen,

kızılca batmalarında güneşin

bir yolculuk,

derin yüzlerden ayrılıp çıkılan,

saatlerin içinde rastlanılmadan huzurlu bir yüze

Binarlar vardır yolculuklarda

köy içlerinde avluları bataklı ve çamurlu

avlularında uydu antenleri

binarlar ki yeşil ve peşi sıra, ama artık soğuk buz parçaları

ve bir bina hatta kulube

uçsuz bucaksız tarlaların ortasında sade ve kendince

kendini tek başına bırakmış, kendini terk etmiş

Bir bina daha 

soğuk floresan ışığında görünen

sarı sokak lambalarına can veren uzun kabloları kucağında,

ağılı bir ıssızlıkta korkuyu keşfeden.

Uzaktan şehirleri gördüğün, şehirlerin ışıklarını

ama karanlık kompartımanda yalnız, pencereyle kapı arasında

iki ayna arasında kendini gördüğün

İki ters bir düz, la''lar, sol''ler, re''ler ve do''lar

en çok da onlar, kalın re''ler

öyle bir gider ki tren 

ritminde sessizlik, ritminde sesler

gidiyor mu duruyor mu bilemezsin sesinden,

arada arkaya dönüp bakarmış gibi

silermiş gibi ağladıktan sonra gözlerini.

duyamazsın, göremezsin bir zaman sonra,

bir parçadır çünki artık kendinden', 'Bir yolculuktu iç çekmeler yolu ıssızlıktan ve demir düdüklerden geçen, kızılca batmalarında güneşin bir yolculuk, derin yüzlerden ayrılıp ç...', ARRAY['Türk Edebiyatı','Şiir','Lzcramcil Ceyhun Erdem']::text[], 8.5, '{"poet":"Lzcramcil Ceyhun Erdem","poet_slug":"lzcramcil-ceyhun-erdem","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/kose-kose-cizdim-dunyayi-hatta-pencerenin-karanlikta-aynalasmasini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözyaşı', 'gozyasi-ozkan-ozdogan-u1igs', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İnanma,

ağlıyor değilim,

bunlar da gözyaşı değil:

İlk damlaları bir yağmurun,

yeni doğmuş bir çocuğun

ilk yudumları..

Ölmekteki bir adamın son isteğidir; 

yeşermeyi bekleyen tarlalara inen

ilk umuttur,

gökyüzüne uzanmış ellere değen

ilk mucize..

Ağlama sen şimdi de,

inanma her üzüldüğüme..

Yanaklarımdan yüzünün yansıdığı

bu yaşların her biri 

benden başka bir insandır,

bir kere daha ölen

her görüldüğünde..', 'İnanma, ağlıyor değilim, bunlar da gözyaşı değil: İlk damlaları bir yağmurun, yeni doğmuş bir çocuğun ilk yudumları.. Ölmekteki bir adamın s...', ARRAY['Türk Edebiyatı','Şiir','Özkan Özdoğan']::text[], 8.5, '{"poet":"Özkan Özdoğan","poet_slug":"ozkan-ozdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/gozyasi-45-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anadolu', 'anadolu-mehmet-karli-sl91g', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Anadolu '' yu bize emanet edip giden

Kaç şehit var, nerededir, bilir misin? 

Anadolum herşey senin, helal diyen 

Koç yiğitleri, cengaverleri bilir misin? 

Babam derdi ben de Türküm dinle oğlum

Bu ülkeye hizmet eden biri idi benim soyum

Adaletli adım attık doğruluktur sağım solum

Tarihini, geçmişini, ecdadını bilir misin? 

Anadolu emanettir hiçbir kuvvet yıkamaz

Kenetlensek bir araya bizi kimse bölemez

Şehirleri yıkıp karıştırıp haritadan silemez

Koruyacak kollayacak sahipleri bilir misin? 

Anadolum artsın da gürlesin daima sesin

Toprakla arkadaş gibisin ısıtıyor nefesin

Kalplerde tomurcuklanan açan sevgisin

Mehmet sana kul köledir feda olsun bilesin.....', 'Anadolu '' yu bize emanet edip giden Kaç şehit var, nerededir, bilir misin?  Anadolum herşey senin, helal diyen  Koç yiğitleri, cengaverleri ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Karlı']::text[], 8.5, '{"poet":"Mehmet Karlı","poet_slug":"mehmet-karli","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/anadolu-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağıt', 'agit-hidir-cam-fg9m7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'CANIM KIZIM (AĞIT)

	Çeyizin sandıkta kaldı

	Neredesin canım kızım

	Koru komşu seni sordu

	Neredesin canım kızım

		Madem gitmekti muradın

		Ananı niye almadın

		Kartal mısın yok kanadın

		Neredesin canım kızım

	Hangi dağın başındasın

	Daha on beş yaşındasın

	Öldü dirildi kardaşın

	Neredesin canım kızım

                Dil tükettim sora sora

	Taş bağrıma vura vura

	Bak karlar düştü Munzur’a

	Neredesin canım kızım 

                Akşam olup yel esende

	Bağrıma ataş düşende

	Sabır bende, umut sende

	Neredesin canım kızım

	

                Kaderini dağlar yazsın

	Mezarını kuşlar kazsın

	Sen  adama  kıyamazsın

	Neredesin canım kızım

	Bayrağını  bayrak yapam

	Evimin damına takam

	Düğün kuram, kına yakam

	Neredesin canım kızım.

Yetiş ya pirim duvaya				

Ayrılık koma araya	

Bak kuşlar döndü yuvaya

Neredesin canım kızım', 'CANIM KIZIM (AĞIT) 	Çeyizin sandıkta kaldı 	Neredesin canım kızım 	Koru komşu seni sordu 	Neredesin canım kızım 		Madem gitmekti muradın 		A...', ARRAY['Türk Edebiyatı','Şiir','Hıdır Çam']::text[], 8.5, '{"poet":"Hıdır Çam","poet_slug":"hidir-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/agit-50-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hastane', 'hastane-omer-temel-0ggd6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu nasıl bir çelişki, nede tuhaf bir sahne.

Kimi doğuma sevinir, kimi ağlar ölüme.

Doğum cana vesile,ölüm sona bahane.

Burda bunlar normaldir, burası bir hastane.', 'Bu nasıl bir çelişki, nede tuhaf bir sahne. Kimi doğuma sevinir, kimi ağlar ölüme. Doğum cana vesile,ölüm sona bahane. Burda bunlar normaldi...', ARRAY['Türk Edebiyatı','Şiir','Ömer Temel']::text[], 8.5, '{"poet":"Ömer Temel","poet_slug":"omer-temel","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/hastane-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geri Dönüşümlü Şiir', 'geri-donusumlu-siir-i-brahim-elciboga-4r89t', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sıcaktın, sıcaklığımı aldın

daha doğrusu

seve seveydi.

Veresiyeydim,

borçlu kaldın.



Garip bir hal aldım soğuktan

geri dönÜŞÜYORUM.

                                                        

                                                          (06/11/03, Paris)', 'Sıcaktın, sıcaklığımı aldın daha doğrusu seve seveydi. Veresiyeydim, borçlu kaldın. Garip bir hal aldım soğuktan geri dönÜŞÜYORUM.          ...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Elçiboğa']::text[], 8.5, '{"poet":"İbrahim Elçiboğa","poet_slug":"i-brahim-elciboga","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/geri-donusumlu-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yasakmışşşşşş', 'yasakmissssss-i-brahim-elciboga-an4r7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Mavi önlük içine sıkışmış bir ben

hasta yatağında.

Düz beyaz duvarlar

pembe bir dolap karşımda

mutlu mesut bir yuvayı çağrıştırıyor.

Sonra sen geliyorsun aklıma

İster istemez hiç çıkmamak üzere.

Belime bir ağrı saplanmış anlatamam

Gözlerimi kapayıp sayıyorum

Önüm, arkam, sağım, solum

Ne sen çıkıyorsun ne de şu ağrılar...

Hemen karşımda yazılı duran bir ibare.

Bilmem kaç sayılı yasanın 

kaç sayılı maddesi gereğince 

seni düşünmek Yasakmış.

                                                           (01.08.2004, İzmir)', 'Mavi önlük içine sıkışmış bir ben hasta yatağında. Düz beyaz duvarlar pembe bir dolap karşımda mutlu mesut bir yuvayı çağrıştırıyor. Sonra s...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Elçiboğa']::text[], 8.5, '{"poet":"İbrahim Elçiboğa","poet_slug":"i-brahim-elciboga","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yasakmissssss-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bööle İşlere Çocukları Bulaştırmamalı', 'boole-i-slere-cocuklari-bulastirmamali-i-brahim-elciboga-ydiru', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kazandığımda küçük çocuk

sevinciyle boyandım

kaybettiğimde gene küçük çocuk

hüznüyle yıkandım.

Bütün boyalar döküldü

yine bir badana zamanı

bu nasıl badanaysa 

bıktım usandım.', 'Kazandığımda küçük çocuk sevinciyle boyandım kaybettiğimde gene küçük çocuk hüznüyle yıkandım. Bütün boyalar döküldü yine bir badana zamanı ...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Elçiboğa']::text[], 8.5, '{"poet":"İbrahim Elçiboğa","poet_slug":"i-brahim-elciboga","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/boole-islere-cocuklari-bulastirmamali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çilingir', 'cilingir-i-brahim-elciboga-j70ip', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kulaklarınız 

kapının kirişinde

çok abartıyorsunuz

dünyayı değiştirmemden mi

                     korkuyorsunuz? 

Oysa

altı üstü bir çilingirim

şu kilidi de değiştirip

hemen çekip gideceğim.', 'Kulaklarınız  kapının kirişinde çok abartıyorsunuz dünyayı değiştirmemden mi                      korkuyorsunuz?  Oysa altı üstü bir çilingi...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Elçiboğa']::text[], 8.5, '{"poet":"İbrahim Elçiboğa","poet_slug":"i-brahim-elciboga","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/cilingir-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şakacıktan', 'sakaciktan-i-brahim-elciboga-qyc8b', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yakın olayım diye

Arayıp da bulasın diye

En uzağa ben gittim

En derin izler ben bıraktım

Sende kalıp seni aştım

Suda kayan bir taştım

Dedim ya! en uzağa ben gittim 

Battım çıktım

Battım çıktım

Can simidimi de almadım yanıma

Evelallah çıkaracağını bilerekten gerisin geriye

Arkamı bile dönüp bakmadım

Şakacıktan

Yoksa, yanıldım? 

                                                        (2004-11-20 İstanbul)', 'Yakın olayım diye Arayıp da bulasın diye En uzağa ben gittim En derin izler ben bıraktım Sende kalıp seni aştım Suda kayan bir taştım Dedim ...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Elçiboğa']::text[], 8.5, '{"poet":"İbrahim Elçiboğa","poet_slug":"i-brahim-elciboga","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sakaciktan-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılığın Zulmü', 'ayriligin-zulmu-ali-osman-yilmaz-iltef', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir kemend, sarmış boğazım 

Nefes bile alamıyorum, 

Dilim çıkmış bir karış dışarı, 

Biraz daha sürerse bu zulüm, 

Galiba erenler,ben ölüyorum. 

Ey kudreti sonsuz tanrı, 

Görüyorsun işte halimi, 

Düşmüşüm bir sevda ateşine, 

Ha bire yanmadayım, 

Bir de dolanmış boynuma, 

Aşkın yağlı kemendi, 

Sıkar da,sıkar ha, 

Boğacak sanki beni, 

Bir el ver de nefes alayım, 

insaf et de aşkıma, 

Son kez olsun sarılayım, 

Yoksa,hazırla sıratta mahkemeni, 

Ayrılığın bu zulmü, 

Böyle sürerse az daha, 

İnan,sana geliyorum.', 'Bir kemend, sarmış boğazım  Nefes bile alamıyorum,  Dilim çıkmış bir karış dışarı,  Biraz daha sürerse bu zulüm,  Galiba erenler,ben ölüyoru...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ayriligin-zulmu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düğümlü Yollar (Silkelen)', 'dugumlu-yollar-silkelen-zulfikar-yapar-kaleli-yp6wx', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yangın düştü gönül denen bu köşke, 

Senden daha yaman mı var? Silkelen. 

Bülbüller perişan, gül düşmüş aşka, 

Uyumaya zaman mı var? Silkelen. 

Gülü görsem bülbül olur eririm, 

Bin can olsa binini de veririm, 

Yollar dağda düğümlenmiş görürüm, 

Yüce dağda duman mı var? Silkelen. 

Can analar gözyaşını dökmesin, 

Şen olsun yuvalar,elem çekmesin, 

İster gün doğmasın, şafak sökmesin, 

Gönüllerde güman mı var? Silkelen. 

Bel bağlama şunun,bunun savına, 

Döğülmeli demir, geldi tavına, 

Zalimler çıkmışlar bülbül avına, 

Vampirlere aman mı var? Silkelen. 

Dostlar birbirini sormuyor, neden? 

Kimse kafa gönül yormuyor, neden? 

Oklar menziline varmıyor, neden? 

Yüreğinde saman mı var? Silkelen.', 'Yangın düştü gönül denen bu köşke,  Senden daha yaman mı var? Silkelen.  Bülbüller perişan, gül düşmüş aşka,  Uyumaya zaman mı var? Silkelen...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/dugumlu-yollar-silkelen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dip Not', 'dip-not-bayram-tunca-vmqlf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ulusça zengin yatıp/fakir kalktık

Paramızdan altı sıfır birden attık

01.01.2005-01.01', 'Ulusça zengin yatıp/fakir kalktık Paramızdan altı sıfır birden attık 01.01.2005-01.01...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/dip-not-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rantiye', 'rantiye-zafer-mutlu-yh6cu', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'şimdi,

bedeni sessiz dingin,

ruhu serzenişte.

gök uzak, güneşi görmeye.

toprak sipere daha yakın

rantiye...

hal çaresi yok! 

seni bekler

emekçi eller defnetmeye....', 'şimdi, bedeni sessiz dingin, ruhu serzenişte. gök uzak, güneşi görmeye. toprak sipere daha yakın rantiye... hal çaresi yok!  seni bekler eme...', ARRAY['Türk Edebiyatı','Şiir','Zafer Mutlu']::text[], 8.5, '{"poet":"Zafer Mutlu","poet_slug":"zafer-mutlu","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/pay-kapitalizm-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Topuz', 'topuz-hizir-azakli-v1nhv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Çatlamış zevatın edebi, arı,

Kimi Mun’ dan okur, kimi Şaman’dan.

“Protestan zangocu” koca soytarı; 

Ne Musa’dan anlar, ne Süleyman’ dan. 

Bu ne harekettir, bu nasıl gürüz

Avama “gürz, topuz”; ite kılavuz.

Devrimden beslenip, devrimi satan,

Duygusuz ve ruhsuz

                     Alemdar yavuz,

Kırk yılın ısrarı, kırk yılın kârı,

Bir nefret rüzgârı, bir kin duvarı.

Öyle namussuz ki, öyle soysuz ki; 

Kendi mezarına kusar, soytarı.

Ortadoğu kan gölü.

Filistin, Bağdat, Kerkük ve Musul; 

İşgal, saldırı; direniş, intihar…

İstanbul’ da dehşet; 57 ölü,                            

                              yüzlerce yaralı var. 

“Allah’ sız ittifak, kuduz canavar.”

 Kazablanka, Riyad, Bali,  İstanbul… 

Yine aynı resim: faili meçhul? 

 - Güvenlik? 

         -İstihbarat?           

              -Emniyet? 

                   - Milli Kurul? 

Ölüm hep bize mi kabul? Bize mi hep İstanbul? 

Yüreklerde isyan, yüreklerde kan,

Yetmiş milyon tek bir vücut, tek bir can,

Bu utanmaz meşin surat,  küf surat

Ne ipinde bıktı, ne yularından.

Bakın hele,

   medya ile

            bu hergele

     ve malum zevat: 

                “Fırsat bu fırsat.”

- Basın? 

           - Hazır.

- Zerzevat? 

          - Tamam.

“-Selam! 

Bu partinin başı, bakan veya başbakan,                                 

İrticai  bir örgütün üyesi mi neymiş. 

Mamafiiih, 

                bu rejiiim

                    tehlikedeymiş 

                                       vesselam…”

-Be keçi kuyruklu, peynir tulumu.

Bütün birikimin, kültürün bu mu? 

Yetmiş milyar dolar hortumlanırken,

Uyudun mu yoksa uyutuldun mu? 

Be! topuksuz topuz,

Devrim Muhafızı bunak.

Bana bak.

Dumûra uğramış o beyninle

                  devrimi satarak

                 saltanat soytarılığını bırak

                                         ve dinle:

Hep bir deredeniz, hep bir yerdeniz,

Bu nefreti kabul etmez yer, deniz.

Devran döner, keser döner, sap döner, 

Firavun’ u, Karun’ u da yer deniz.

                                              İstanbul, 21.12.2003', 'Çatlamış zevatın edebi, arı, Kimi Mun’ dan okur, kimi Şaman’dan. “Protestan zangocu” koca soytarı;  Ne Musa’dan anlar, ne Süleyman’ dan.  Bu...', ARRAY['Türk Edebiyatı','Şiir','Hızır Azaklı']::text[], 8.5, '{"poet":"Hızır Azaklı","poet_slug":"hizir-azakli","theme":"Türk Şiiri","is_hero":false,"total_lines":62,"source_url":"https://www.antoloji.com/topuz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim Gibi...', 'benim-gibi-kadir-soyturk-jzt9p', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yolda bir iz, bir ışık, bir rehber olmayınca

Çare yok; benim gibi, siz de kaybolursunuz...

Kaybolanı anlamak, işte işin özü bu

Arayanlar bulurmuş, mutlaka bulursunuz!', 'Yolda bir iz, bir ışık, bir rehber olmayınca Çare yok; benim gibi, siz de kaybolursunuz... Kaybolanı anlamak, işte işin özü bu Arayanlar bul...', ARRAY['Türk Edebiyatı','Şiir','Kadir Soytürk']::text[], 8.5, '{"poet":"Kadir Soytürk","poet_slug":"kadir-soyturk","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/benim-gibi-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Komşumun kızı-2', 'komsumun-kizi-2-hidir-cam-80mkd', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Komşumun bir kızı vardı

yaş farkımız sekiz, on kadardı

Kucağına alırdı beni

Önce saçlarımı okşar

sonra yanağımı

sonra….

Sonrasını diyemem abes kaçar

Ama daha sonra

daha sonra

kaçtı gitti İstanbul a

Hem de domuz mu domuz

bekçinin küçük oğluyla

On yıllar geçti aradan

can dayandı bu acıya 

dayandı ama; 

Laf aramızda

Süleyman Efendi duymasın da

koltuktan inmekten de zormuş

kucaktan inmek.', 'Komşumun bir kızı vardı yaş farkımız sekiz, on kadardı Kucağına alırdı beni Önce saçlarımı okşar sonra yanağımı sonra…. Sonrasını diyemem ab...', ARRAY['Türk Edebiyatı','Şiir','Hıdır Çam']::text[], 8.5, '{"poet":"Hıdır Çam","poet_slug":"hidir-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/komsumun-kizi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelin Kızım', 'gelin-kizim-ahmet-mansuroglu-zizss', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ak danteller içinde gelin kızım,

Seher yıldızım,

Beyaz gelinlik içinde

Bir incisin

Alnımızın akı

Yuvamızın sevincisin.

Ak danteller içinde gelin kızım

Seher yıldızım.

Artık senin de yuvan oluyor,

İnan gönlüme sevinç doluyor.

Yuvamda sana çok şey vermek isterdim,

Bütün eksiğimle beni bağışlar dedim.

Canımı iste vereyim kızım.

Ak danteller içinde gelin kızım,

Seher yıldızım.

Kuracağın yuvada çiçek ol kızım,

Sevenlerin gönlüne dol kızım,

İyi günde kocana sevinç, gurur

Kötü günde destek ol kızım.

O senin hayat arkadaşın,

Ekmeğin suyun aşın

Onunla mutlu onunla dik başın,

Mert ve gerçek insan hayat arkadaşın,

Nede yakıştı sana beyaz gelinlik,

Cümle dostlara böyle gün, böyle şenlik.

Ak danteller içinde gelin kızım,

Seher yıldızım.

 Antakya - Hatay                   20. Haziran. 1982', 'Ak danteller içinde gelin kızım, Seher yıldızım, Beyaz gelinlik içinde Bir incisin Alnımızın akı Yuvamızın sevincisin. Ak danteller içinde g...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Mansuroğlu']::text[], 8.5, '{"poet":"Ahmet Mansuroğlu","poet_slug":"ahmet-mansuroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/gelin-kizim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Otuzbir aralık-Bir ocak...', 'otuzbir-aralik-bir-ocak-emirhan-bala-xxx2y', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'her şafak, bir ocak. 

her gün batımı, otuz bir aralık.

bir yılı bir günde yaşamak…

bugün ikibindört, yarın ise ikibinbeş…

bu nasıl garip bir denge,

kulaklarım mahkum yobaz seslere

bakir hırslar gebe avaza küfürlere

kiralık duygular, emanet bedenlere, 

İşim gücüm ruhumun hasat dönemine

satırlarım eskimeyecek yeni yıl eskidiğinde

isyanım, özgür dünyanın eskittiklerine.

yeminim, besbelli kötülere,

her şafak ana rahminden çıkışım,

her gün batımı selvinin dibi çukurum…', 'her şafak, bir ocak.  her gün batımı, otuz bir aralık. bir yılı bir günde yaşamak… bugün ikibindört, yarın ise ikibinbeş… bu nasıl garip bir...', ARRAY['Türk Edebiyatı','Şiir','Emirhan Bala']::text[], 8.5, '{"poet":"Emirhan Bala","poet_slug":"emirhan-bala","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/otuzbir-aralik-bir-ocak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Evlilik Yıl Dönümü', 'evlilik-yil-donumu-ahmet-mansuroglu-ycgqy', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kırk yıl önce,

Sen babasız

Ben babasız,

Bizi analarımız everdi.

İkiside bizi canı gibi severdi.

İkimize bir oda verdiler,

Odamıza bir de halı serdiler.

Çok sevdik odamızı,

Böylece kurmuş olduk yuvamızı

Üç çocuğumuz oldu

Mutluyduk biz,

Kalmamıştı babasızlıktan bir iz

Birimiz anne, brimiz baba olmuştuk biz

Sen azımı çok ettin,

Üzüntülerimi yok ettin

Dağ gibi sorunları omuzladık beraberce

Beraber güldük,

Beraber ağladık,

Hayat çabuk geçiyor

Şimdi anladık

Çocuklarımızı uçurduk yuvadan

Birer birer

Şimdi bir sen bir ben kaldık

Geçmiş günlerin hayaline daldık

Dizlerimizde eski güç,

Gözlerimde fer kalmadı.

Kulaklarımızda duymuyor artık 

Eskisi gibi

Bir sevgimiz var bitmeyen tükenmeyen,

Yine göz gözeyiz,

El eleyiz ilk günkü gibi.

Bize kırk yıl yetmedi

İçimizdeki sevgi

Hiç bitmedi

Bitmeyecek

İnanırmısın karıcığım,

Bize nice kırk yıllar yetmeyecek.

Antakya - Hatay', 'Kırk yıl önce, Sen babasız Ben babasız, Bizi analarımız everdi. İkiside bizi canı gibi severdi. İkimize bir oda verdiler, Odamıza bir de hal...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Mansuroğlu']::text[], 8.5, '{"poet":"Ahmet Mansuroğlu","poet_slug":"ahmet-mansuroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/evlilik-yil-donumu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bağışla Beni', 'bagisla-beni-i-smet-barlioglu-tluc5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bağışla beni; 

Sana amansızca gönül verdiğim için,

Gençliğime say hatamı,

Toyluğuma say.

Hışım gibi işlemiş yüreğime ateşin,

Yüreğim nasıl bilsin ne yaptığını, neylediğini? 

Ne bilsin pervane, ateşin kendisini yakıp kavuracağını? 

Elinden alson ölür, eline versen ölür,

Oyuncağını.

Gençliğime say hatamı,

Genç başımda esen kavakyellerine say,

İçinde sevgiler kaynayan yüreğime say,

Aldırma gençliğime; yüreğim henüz çocuk,

Karayı bilir, sevdayı bilir ama karasevdayı bilmez,

Tutunup sarıldı sevdana,

Bağışla bir körpe, bir toy yüreği

Yaratan ‘a.

Ne büyük umutlar bağlamışım ne büyük yere,

Başım kurtulmaz oldu çilelerden,

Ne gündüzümde tad, ne gecemde lezzet,

Ne beklenen yerden bir küçük rahmet,

Suç olmuş sanki yüreğime karasevdam; 

Gözlerim yaş, dilim özürler içinde,

Bütün bir ömürden nasıl da zararlı çıktım

Bir günde.

Bağışla beni, seni sevdiğim için,

Senden öte şey düşünmediğim için bağışla beni,

Seni soluduğum için hava yerine,

Işık yerine seni gördüğüm için,

Sana hayran olduğum için renk zannederek,

Yangınlar belasına seni istediğim için su yerine,

Hatama karşı bir büyüklük göster, sen de,

Ömür boyu sevdim, seveceğim,

İstesen de,

İstemesen de.

(KAFES isimli Serbest Şiirler ''inden > 61-62/100)', 'Bağışla beni;  Sana amansızca gönül verdiğim için, Gençliğime say hatamı, Toyluğuma say. Hışım gibi işlemiş yüreğime ateşin, Yüreğim nasıl b...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/bagisla-beni-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölebilirim', 'olebilirim-i-smet-barlioglu-i1zff', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Şu anda çay içiyorsundur kirazların gölgesinde,

Yine elinde o ince belli, geniş ağızlı bardak vardır,

Ve beyaz örtülü, yuvarlak masada bir-iki çörek,

Belki beni dinliyorsundur

Gülerek.

Yüreğim kan ağlıyormış, umurunda mı,

Çilelerim dört bir yanımı sarmış,

Kör talih yollarımı tıkamış,

Mecalim, tutarım kalmamış, umurunda mı,

Umurunda mı perişan süründüğüm,

Umurunda mı

Yaşadığım,

Öldüğüm? 

Bir yanıp kül olmadığım kaldı kendi ateşimle

Kerem gibi,

Bir dağlar delmediğim kaldı uğrunda

Ferhat gibi,

Bir, Mecnun gibi çöllere düşmediğim kaldı,

Devir sır tutma devri,

Devir dışa başka, içe başka görünme devri,

Ne yanabilirim,

Ne dağlar delebilirim,

Ne de çöllere düşebilirim.

Benimki onlardan biraz daha ehven bir dert; 

Ölebilirim.

(KAFES isimli Serbest Şiirler ''inden > /63-64100)', 'Şu anda çay içiyorsundur kirazların gölgesinde, Yine elinde o ince belli, geniş ağızlı bardak vardır, Ve beyaz örtülü, yuvarlak masada bir-i...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/olebilirim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Günaydın', 'gunaydin-i-smet-barlioglu-5193m', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Günaydın çilelerim,

Günaydın ayrılığım,

Özlemlerim,

Nasibim, kaderim, günaydın.

Bakın; yine beraberiz ayni yıkık dam altında,

Siz yine gelmişsiniz ama ben artık yaşlandım,

Siz yine dinçsiniz, bense yorgunum biraz daha,

Yine de şükürler olsun Allah ‘a.

Bunlar kim? 

Yeni arkadaşlarınız, ya da yavrularınız mı,

Bir gece içinde bu kadar öoğaldınız mı? 

Yok yok çekinmeyin,

Tümünüze yer var yüreğimde,

Tümünüze yetecek aşım var, ekmeğim var,

Nasıl olsa böyle gelmişti,

Böyle de geçecek

Yıllar.

Ağlamayın çilelerim, ağlamayın,

Sizlere ağlamak düşmez ben varken,

Sabah güneş doğup akşam batarken,

Birlikte uyanır, birlikte başlarız günü yaşamaya,

Sabahlarımız akşam,

Akşamlarımız gece,

Gecelerimiz yine gece,

Nasıl olsa; sizler beni bırakmak zorunda kalacaksınız

O gelince.

(KAFES isimli Serbest Şiirler ''inden > 65-66/100)', 'Günaydın çilelerim, Günaydın ayrılığım, Özlemlerim, Nasibim, kaderim, günaydın. Bakın; yine beraberiz ayni yıkık dam altında, Siz yine gelmi...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/gunaydin-37-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olur mu?', 'olur-mu-kadir-soyturk-cvwja', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Beni yok sayanı, saflık ederek

Var sayarsam, olur dunya dar bana! 

Nice dostlar bile, düşman kesildi

Hainlerden olur mu hiç yar bana!', 'Beni yok sayanı, saflık ederek Var sayarsam, olur dunya dar bana!  Nice dostlar bile, düşman kesildi Hainlerden olur mu hiç yar bana!...', ARRAY['Türk Edebiyatı','Şiir','Kadir Soytürk']::text[], 8.5, '{"poet":"Kadir Soytürk","poet_slug":"kadir-soyturk","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/olur-mu-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gökhan', 'gokhan-ahmet-mansuroglu-tqe1r', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gülen gözlerin dünyayı değer

Özlemek varmış seni hergün meğer

Kalbim kırıktı sen gelmezsen eğer

Haytımın en kıymetli parçası oldun

Aktın çağlayan su gibi gönlüme doldun

Nine eden sen, dede eden sen oldun.

Yüksel ömürboyu, mutluluğun en güzeline

Üzüntülerden sonra seninle sevindik böylesine,

Kısalan ömrüm erişti Gökhan''ın gülmesine

Sevincimizi bir bilsen, sen de sevinçle coşardın

Emeklemeyi beklemeden dedene koşardın

Leylaklar, güller sevindi, görsen şaşardın.

Sen benim Gökhanım Yükselimsin

Ömür boyu düşlediğim gerçeğimsin,

Gül gülüşünde güller açsın,

Sen bizim gönlümüzde sevgi başımızda taçsın.

   (İlk torunum Gökhan Yüksel''e) 

 Antakya - Hatay               15. Haziran. 1984', 'Gülen gözlerin dünyayı değer Özlemek varmış seni hergün meğer Kalbim kırıktı sen gelmezsen eğer Haytımın en kıymetli parçası oldun Aktın çağ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Mansuroğlu']::text[], 8.5, '{"poet":"Ahmet Mansuroğlu","poet_slug":"ahmet-mansuroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/gokhan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İntiharıma Yüklenmiş Suçun Kadınım...', 'i-ntiharima-yuklenmis-sucun-kadinim-mehmet-asim-phbyc', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Zemheri renginde gece

Kasım fırtınaları

Ve

Elleri bağlanmış

Mülteci bir bahar...

Budanmış bir sevda

Kırılmış bir kalem

Masada...

Dökülen insanlar sokakta

Kaldırıma savrulmuş

Hatıralar...

Geçmişe doğru akan zaman

Kabuk bağlamayan yaralar....

Ey kadınım...

İntiharıma ölüm süsü verme..', 'Zemheri renginde gece Kasım fırtınaları Ve Elleri bağlanmış Mülteci bir bahar... Budanmış bir sevda Kırılmış bir kalem Masada... Dökülen ins...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Asım']::text[], 8.5, '{"poet":"Mehmet Asım","poet_slug":"mehmet-asim","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/intiharima-yuklenmis-sucun-kadinim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nezahat', 'nezahat-ahmet-mansuroglu-7vs5a', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Güzeller güzeli Nezahat sen hoş geldin

İnan bize sevinç mutluluk verdin

Güneş yine battı bu akşam,ama sen doğdun

Sen yuvamızı aydınlatan güneş oldun.

Sen bir perisin, gönlümdeki cansın

Solan ömrümde açan baharsın

Yuvamıza sevincin düştüğü ansın

Mutsuzluk uzak bizden çünkü sen varsın.

Sen güzeller güzeli bir meleksin

Gönlümdeki sevinç, içimdeki dileksin

Bahçemizde gül, evimizde çiçeksin

İyi ki doğdun bize bayram yaşatan sensin.

Nezahatım, canım benim sen hoş geldin

Bize sevinç mutluluk verdin

Sevgi çeberi içinde mutluluğa erdin

Nezahatım, canım benim sen hoş geldin.

 (Torunum Nezahat Mansuroğlu''nun doğumu için.) 

 Antakya - Hatay                  13. 07.1988.', 'Güzeller güzeli Nezahat sen hoş geldin İnan bize sevinç mutluluk verdin Güneş yine battı bu akşam,ama sen doğdun Sen yuvamızı aydınlatan gün...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Mansuroğlu']::text[], 8.5, '{"poet":"Ahmet Mansuroğlu","poet_slug":"ahmet-mansuroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/nezahat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yorgun...', 'yorgun-ali-galip-sari-b9wxi', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gel desen, sanma ki çıkagelirim...

Zaman kısa, yollar uzun, yıl yorgun...

Durmadan adını anmaktan mıdır? 

Gönül hasta,umut mecnun, dil yorgun...

Yorgunum sevgili bilmem ki neden? 

Solmakta güllerim daha dermeden...

Daha ''Mecnun''laşıp, daha sevmeden,

Gönül hasta düştü,can harap yorgun...

                                                                 01-01-2005/ Ankara', 'Gel desen, sanma ki çıkagelirim... Zaman kısa, yollar uzun, yıl yorgun... Durmadan adını anmaktan mıdır?  Gönül hasta,umut mecnun, dil yorgu...', ARRAY['Türk Edebiyatı','Şiir','Ali Galip Sarı']::text[], 8.5, '{"poet":"Ali Galip Sarı","poet_slug":"ali-galip-sari","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yorgun-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acı Veren', 'aci-veren-firat-erdogan-4esm0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bugün sana adanmış onlarca şiirim var,

yarın yüzlerce olacak,

 öbür hafta binlerce.

Ve çığ gibi büyüyecek sana sakladığım soluğum.

                   ******************           

Sen hiç unutulmamış şarkısın dudaklarımda.

Yarına beslediğim umudum,

umuda olan inancımsın.

Hep düştüğüm yanılgımsın,

düşmekten zevk aldığım.

Ya hayatın ayrıntısında saklısın,

ya da hayatın ayrıntısısın.

Safsın,

yağmursun,karsın.

Umut verensin,

topraksın,büyütensin.

Ama acı verensin.

Acıtansın,yakansın. 

Gizsin...

Sen; bensin,ben.

Yüreğimin saflaştırdığı,

büyüttüğü.

Ama acı verensin.

Acıtansın,yakansın.

Akan yağmursun toprağa,

toprakta yeşerensin,büyüyensin,

meyve olup düşensin.

Ama acı verensin.

Acıtan,yakan.

Geceyi yakan güneşsin.

Bulutu kovalayan rüzgar.

Çocuksun en masum halinle.

Ama acı verensin.

acıtansın,yakansın.

Aydınlanmak için,

aydınlatmak için 

bedenini ateşe verenlere çok uzaksın.

İdeolojisiz bir coğrafyasın,

ve tarihi kimsesiz.

Acı çekensin.

Acınansın,yanansın.

İmgemsin düşlerimde.

Bir titremesin bedenimde.

Hem yakansın,hem serinleten.

Bir muammasın varoluş nedenimde.

Bahara sakladığım tohumumsun,

büyütmeye can attığım.

Sonbaharda bulduğumsun,

ve hiç unutamadığım.

Ama acı verensin.

acıtan,yakan.

Bir anda kaybolansın,

kaybedensin.

Acıyan yanımsın,

acıtan,acınan.

Yalnızlığa terkedensin,

umursamayansın.

Düşünmeden yalnızlığa itensin.

Hem acı verensin,

hem acı çeken.

Unutuluşumsun

ve

kayboluşum...', 'Bugün sana adanmış onlarca şiirim var, yarın yüzlerce olacak,  öbür hafta binlerce. Ve çığ gibi büyüyecek sana sakladığım soluğum.          ...', ARRAY['Türk Edebiyatı','Şiir','Fırat Erdoğan']::text[], 8.5, '{"poet":"Fırat Erdoğan","poet_slug":"firat-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":63,"source_url":"https://www.antoloji.com/aci-veren-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsanlar', 'i-nsanlar-ahmet-mansuroglu-sxf2r', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hayatta gaye etmedim malı mülkü,

Bırakıp gideceğiz her şey kalacak çünkü

Esefle gördüm doymak bilmeyenler var,

İnsandır değerli olan, aç gözlülük niçin bu kadar.

Hiç bir zaman değer vermedim paraya pula,

Çok az rastladım çıkar düşünmeyen kula,

Aldattım diyene bilerek aldandım,

Aldatmadım, insanların mutluluğundan zevk aldım

Neden bu kadar çıkarcı riyakar bu insanlar? 

Çıkarı olana dost, olmayana düşmanlar.

Dalkavukla elden gidiyor hanlar, hamamlar,

Neden bu kadar çıkarcı riyakar bu insanlar? 

Ender de olsa gerçek insanlara rastladım,

Her türlü insanı izledim adım adım,

İnsanları kötülemek değil maksadım,

Dostlukların çıkar üstüne kurulduğunu anladım.

Antakya - Hatay                   12. 11. 1996', 'Hayatta gaye etmedim malı mülkü, Bırakıp gideceğiz her şey kalacak çünkü Esefle gördüm doymak bilmeyenler var, İnsandır değerli olan, aç göz...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Mansuroğlu']::text[], 8.5, '{"poet":"Ahmet Mansuroğlu","poet_slug":"ahmet-mansuroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/insanlar-37-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdim', 'sevdim-nazife-sener-x4ctc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sevgi gönüller yakan görünmez bir ateştir

Efkarlı günlerimde hayalin bana eştir

Bu öyle bir sevgi ki sönmeyen bir güneştir

Sevdim sevdim ah sevdim seni ben candan sevdim

Neydi benim günahım nolurdu sevmeseydim

Hasret içime çökmüş çıkılmaz bir dağ gibi

Ben bu aşkın yüzünden erimişim yağ gibi

Bu sevda nasıl sarmış gönlümü bir ağ gibi

Sevdim sevdim ah sevdim seni ben candan sevdim

Neydi benim günahım nolurdu sevmeseydim

Bilmiyorum sevgilim bilmem ki bana noldu

Senden ayrı düşeli içim derdinle doldu

Bu hasretin yüzünden rengi ruhsarım soldu

Sevdim sevdim ah sevdim seni ben candan sevdim

Neydi benim günahım nolurdu sevmeseydim

(05.12.1962, İstanbul)', 'Sevgi gönüller yakan görünmez bir ateştir Efkarlı günlerimde hayalin bana eştir Bu öyle bir sevgi ki sönmeyen bir güneştir Sevdim sevdim ah ...', ARRAY['Türk Edebiyatı','Şiir','Nazife Şener']::text[], 8.5, '{"poet":"Nazife Şener","poet_slug":"nazife-sener","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sevdim-35-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '* S e v g i *', 's-e-v-g-i-ali-seyh-ozdemir-6hu20', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sevgi olsaydım eğer; 

Dillere düşmez, yüreklere girerdim.

Adımı kirleten tüm sahtekârlıkları

Yıkardım berraklığımla...

Ve tüm maskeleri, yüzeysellikleri

Eritirdim sıcaklığımla...

Doktor olsaydım eğer; 

Tüm reçetelerim sevgi yazardı benim.

Yemekten evvel sevgi, yemekten sonra sevgi.

Yatarken de almayı unutmayın ha; 

Hele sabahları asla! ...

Çiftçi olsaydım eğer; 

Tüm tarlalara sevgi ekerdim ben.

Dört  mevsim  sevgi demek, dört mevsim hasat.

Sevgi bire bin demek, sevgi bire milyon.

Çiftçiler  uçarlardı sevinçten kanat kanat...

Saatçi olsaydım eğer; 

Sevgiye ayarlardım tüm saatleri.

Sevgiyle uyanır, sevgiyle kalkarlardı insanlar

Kıpır kıpır ederdi yürekleri

Kabına sığmazdı canlar...

Pınar olsaydım eğer; 

Sevgi akardı tüm oluklarımdan.

Doyamazlardı tadıma, içseler de kana kana...

Yürekler buz gibi olurken gönüller sımsıcak; 

Kin, nefret kaybolurdu, insanlar kucak kucak …

Sevgi olsaydım eğer; 

Dillere düşmez, yüreklere girerdim.

Adımı kirleten tüm sahtekârlıkları

Yıkardım berraklığımla.

Ve yüzeysellikleri, maskeleri

Eritirdim tüm sıcaklığımla …', 'Sevgi olsaydım eğer;  Dillere düşmez, yüreklere girerdim. Adımı kirleten tüm sahtekârlıkları Yıkardım berraklığımla... Ve tüm maskeleri, yüz...', ARRAY['Türk Edebiyatı','Şiir','Ali Şeyh Özdemir']::text[], 8.5, '{"poet":"Ali Şeyh Özdemir","poet_slug":"ali-seyh-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/s-e-v-g-i-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oğlum Eşref', 'oglum-esref-ahmet-mansuroglu-8e6xp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Doğruluk rehberin,

Çalışmak azmin olsun.

Mert ol,

Minnet etme kimsenin aşına,

Hatta kalsanda tek başına

Minnetle yaşamaktansa,

Mertçe ölmesini bil oğlum.

Azmin daima yükselmek,

Parolan ileri,

Asla affetmem seni dönersen geri.

Masumları koru,

Zalimlere lanet et.

Küçüğünü sev,

Büyüğüne hürmet et.

Sevmeyi sevilmeyi,

Gülmeyi güldürmeyi bil oğlum.

Eğer bir gün,

Vatan düşerse düşman eline

Korkma,

Göğsünü siper et

Düşman seline.

Esir yaşamaktansa,

Mertçe ölmesini bil oğlum.

 (Oğlum Eşref Mansuroğlu''na)

 Antakya - Hatay', 'Doğruluk rehberin, Çalışmak azmin olsun. Mert ol, Minnet etme kimsenin aşına, Hatta kalsanda tek başına Minnetle yaşamaktansa, Mertçe ölmesi...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Mansuroğlu']::text[], 8.5, '{"poet":"Ahmet Mansuroğlu","poet_slug":"ahmet-mansuroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/oglum-esref-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anneler', 'anneler-ahmet-mansuroglu-q1rop', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Her ulusun temeli aziz varlığı,

Yuvalar onlarla görmez darlığı,

Hastalar şefkatinde bulur sağlığı,

Evlat sevgisiyle yaşar anneler.

Çocukların üzüntüsünü dert edinir,

Onlarla ağlar onlarla sevinir,

Annelere koruyucu melek denir,

Cephede mehmetçikle coşar anneler.

Her cefayı çeker her üzüntüye katlanır,

Böyle büyüklüğe meleklerde ratlanır,

Annesi için çarpmayan yürek paslanır,

Kıymet bilmeyene şaşar anneler.

Yavuzlar Fatihler onun eseri,

Emekle yetiştirdiler huduttaki askeri,

Düşman almak isterse bu güzel yeri,

Evladım, vatanım der koşar Anneler...', 'Her ulusun temeli aziz varlığı, Yuvalar onlarla görmez darlığı, Hastalar şefkatinde bulur sağlığı, Evlat sevgisiyle yaşar anneler. Çocukları...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Mansuroğlu']::text[], 8.5, '{"poet":"Ahmet Mansuroğlu","poet_slug":"ahmet-mansuroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/anneler-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sular Boğulur Gözlerimde...', 'sular-bogulur-gozlerimde-i-mdat-ozcan-f5jjm', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gidersen 

Bütün ışıkları söner bu şehrin 

Talan olur tüm dünya nimetleri 

Zebani ruhlu sokalara takılır adımlar 

Gece yanar 

Güneş kanar 

Gidersen 

Cehennem korları harlanır yüreğimde 

Gece gizeminde pusular 

Tenhalarda tekmelenir umut 

Sancılar, inler zaman 

Kırılır kalamler 

Türküler susar 

Şiirler kan kusar 

Gidersen 

Sabahıma çiy düşer 

Sis çöker odama 

Kapımın önüne çöreklenir tüm acıları hayatın 

Çakmağım yanmaz 

Cigaram dumanlanmaz 

Çayım demlenmez gidersen 

Tesbihim düşer ellerimden 

Tane tane dökülür yere 

Hiçbir tebessümün yolu düşmez 

Çocuksu dudaklara 

Sular boğulur gözlerimde 

Gök yırtılır 

Yer yarılır 

Gidersen 

Saçların ufkumda dolaşıyorken 

İnfazlar kesilir militan yüreğime 

Zemheri, ayaz, tipi, boran, kar 

Gözyaşımda oynaşır intiharlar 

Cellatlar tutsak eder hayallerimi 

Karabasan geceler boğazımı sıkar 

Bu can bu bedenden çıkar 

Gidersen...', 'Gidersen  Bütün ışıkları söner bu şehrin  Talan olur tüm dünya nimetleri  Zebani ruhlu sokalara takılır adımlar  Gece yanar  Güneş kanar  Gi...', ARRAY['Türk Edebiyatı','Şiir','İmdat Özcan']::text[], 8.5, '{"poet":"İmdat Özcan","poet_slug":"i-mdat-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/sular-bogulur-gozlerimde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşığım ya...', 'asigim-ya-ebru-temizkan-khjl5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gözüm yaşlı

Haykırmak istiyorum sana sevdamı

Şarkılar tutuyorum aşkımı anlatsın diye

Ama ne haykırabiliyorum

Ne de radyoda bir aşk şarkısı

Ha bire çalıyor Fidayda

Aslında seviyorum Fidayda’yı

Ankaralı’ya belki ondandır

Ankara’yla ne alakam varsa

Aşığım ya

Tüm memleket benim

Ama şunu hiç unutmayacağım

Bir sana olan aşkımı

Birde her sana şarkı tutuşumda 

Fidaydayı çalan o radyo DJ’ini

Fidayda’da Ankaralı’m Fidayda', 'Gözüm yaşlı Haykırmak istiyorum sana sevdamı Şarkılar tutuyorum aşkımı anlatsın diye Ama ne haykırabiliyorum Ne de radyoda bir aşk şarkısı H...', ARRAY['Türk Edebiyatı','Şiir','Ebru Temizkan']::text[], 8.5, '{"poet":"Ebru Temizkan","poet_slug":"ebru-temizkan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/asigim-ya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tut ki..', 'tut-ki-ebru-temizkan-nqb2t', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Tut ki  sen beni tanımadın bilmiyorsun

Ben seni nerede olursa bulurdum.

Ruhun beni tanırdı ve yine aşık olurdun.

Gözlerimin içine pırıltı yapardım

Deli sevdam olurdun

Tut ki sen benden nefret ettin

En fazla 3 gün sonra unuturdun

Geceleri yalnızda olsan

Mutluluğu gündüz bende arardın

Lambalar akşamları aydınlatırdı seni

Işığın aslında hep ben olurdum...', 'Tut ki  sen beni tanımadın bilmiyorsun Ben seni nerede olursa bulurdum. Ruhun beni tanırdı ve yine aşık olurdun. Gözlerimin içine pırıltı ya...', ARRAY['Türk Edebiyatı','Şiir','Ebru Temizkan']::text[], 8.5, '{"poet":"Ebru Temizkan","poet_slug":"ebru-temizkan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/tut-ki-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdalı bulut', 'sevdali-bulut-ebru-temizkan-ckp47', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'sevdalı bir bulut olsam gökyüzünde 

kar beyaz bir rengim olsa yumuk yumuk

yağmur bulutları dokunmasa saflığımı korusam

dolaşsam özgürce güneş beni ısıtsa

sonra gün yerini geceye bıraksa 

ben yine nazlı bir gelin misali dolaşsam

yıldızlar aydınlatsa yolumu ışık olsa bana

sonra tekrar gece güne dönse ben yine aynı kalsam

martılar uçuşsa etrafımda ağızlarında bir türkü

yemyeşil kırlar üstünde gezinsem gölgem vursa 

kuzular beni yakalamaya çalışsa 

küçük bir çocuğun elinden kaçan uçan balonu tutsam

çocuk şaşırsa tekrar ona dönüşüne 

öylece salınsam parlak mavilikte sessizce

sonra karşıma kar beyaz bir bulut daha çıksa

yoldaşım olsa birlikte dolaşsak günde ve gecede

beraber hayal kursak o bana sarılsa ben ona sarılsam

tek bir bulut olsak bu kocaman dünyada 

hayali bile  güzel...', 'sevdalı bir bulut olsam gökyüzünde  kar beyaz bir rengim olsa yumuk yumuk yağmur bulutları dokunmasa saflığımı korusam dolaşsam özgürce güne...', ARRAY['Türk Edebiyatı','Şiir','Ebru Temizkan']::text[], 8.5, '{"poet":"Ebru Temizkan","poet_slug":"ebru-temizkan","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sevdali-bulut-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öylesine bir şiir işte', 'oylesine-bir-siir-iste-ebru-temizkan-p0f0t', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Öylesine bir şiir bu benim yazmaya başladığım

Her satırı daha baştan karalamalarla dolu 

Ne konusu belli ne de kaç dize kaç kıta oluşu 

Sadece bir dörtlük yeter diye başlayıp

                   Noktayı koyduğumuzda tüm kitabı içine alan

Hadi hayırlısı

Kavganın,öfkenin,kinin ender yer bulduğu

                 (Arada ufak bir serzeniş olsa da! !) 

                       sevgiye,güzelliğe,mutluluğa kapısını ardına kadar 

                                                                       açan şiirlerden biri

Diğer insanlar

Şiir kelimelerle oynama sanatıdır der

Şimdi ben bunu yapamıyorum diye şiir yazmamalıyım? 

Sevdamı nereye anlatacağım? 

                  Peki ya kavgamı,

                                    Heyecanımı,   

                                               Yaşama nedenimi 

                                                               yada yorgunluğumun sebebini? 

Kim yazmamıştır ki nefes aldığı sürece şiir? 

Hepsinin bir öyküsü var

Bazen iki-üç dize dökülmüş kalemlerden

                     Bazen sayfalar yüreklerden

Okuyana anlamsız 

                   Yazan için dudak kenarında gülümseme 

                                                 Gözde tek damla yaş

                                                                  Yüreğinin acısı.

Hangi aşık taptığı kadına 

                         yada

                             hayatının adamına

Şiirlerdeki kadar güzel anlatmıştır sevdasını? 

Hangi düşünür kavgasını,davasını paylamamıştır ki şiirlerinde

Ne zaman

Hey hat! diye başlamamış mıdır

                          Mücadele öyküleri

Yanlış mı oldu? 

Öyle bir şiir yazmak istiyorum ki

                       diyorum kendi kendime

Okuyan bir daha okusun 

                   Hayatının felsefesi olsun

Desin ki ne güzel anlatmış

                   İşte ben böyle olmalıyım

Ama 

O zaman o ben olmaz mı? 

Benim sevdamı,

               kavgamı,

                    mutluluğumu almış

                           beni hapsetmiş olmaz mı? 

Ben kıskancımdır sevdamı vermem

             Bencilimdir mutluluğum benim

                           Bak kavgamı açıkça yaptım

Sen beni esir edemezsin

De ki; 

Sen sende kal istediğim 

       Öylesine bir şiir okumak 

O halde 

Öylesine bir şiir sana

İki çiziktirip üçte kelime oyunu olan

         Felsefi yaklaşımsız

               Senin benim dilimden

                          Benim yüreğimden 

                                    Senin yüreğine

                                              Yolculuğa çıkan

Adı başta konmuş

          Sonu noktasına kadar belli olmayan

                            Öylesine bir şiir işte

                                       Noktasını bir türlü koyamadığımız,

                                                        Sevdaya,kavgaya koyamadığımız gibi....', 'Öylesine bir şiir bu benim yazmaya başladığım Her satırı daha baştan karalamalarla dolu  Ne konusu belli ne de kaç dize kaç kıta oluşu  Sade...', ARRAY['Türk Edebiyatı','Şiir','Ebru Temizkan']::text[], 8.5, '{"poet":"Ebru Temizkan","poet_slug":"ebru-temizkan","theme":"Türk Şiiri","is_hero":false,"total_lines":67,"source_url":"https://www.antoloji.com/oylesine-bir-siir-iste-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeni Yılınız Kutlu Olsun Çocuklar', 'yeni-yiliniz-kutlu-olsun-cocuklar-ahmet-mansuroglu-dbltl', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yeni yılınız kutlu olsun çocuklar,

Gözlerinizden öperim, sizin olsun mutluluklar.

Seviliyorsunuz, sizin olacak aydın ufuklar

Yeni yıl size sıhhat, neşe getirsin çocuklar.

Bu akşam sizlerin gecesi,

Sizi bekliyor alfabenin ilk hecesi,

Okumak olsun aşkınız, okumakta bulun hevesi,

Yeni yılda bir yaş daha büyüdünüz çocuklar.

Yeni yılda büyümenizi kutluyorum,

Sizlere aydılık günler diliyorum,

Size şefkatle uzanan elleri seviyorum

Yarınlar sizin olsun çocuklar...

 (Antakya Çocuk Esirğeme Kurumunda bulunan çocuklar için) 

 Antakya - Hatay', 'Yeni yılınız kutlu olsun çocuklar, Gözlerinizden öperim, sizin olsun mutluluklar. Seviliyorsunuz, sizin olacak aydın ufuklar Yeni yıl size s...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Mansuroğlu']::text[], 8.5, '{"poet":"Ahmet Mansuroğlu","poet_slug":"ahmet-mansuroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/yeni-yiliniz-kutlu-olsun-cocuklar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayatın içinden Merhaba', 'hayatin-icinden-merhaba-yucel-basoglu-rxez2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yine bir gece vakti ve ben yine yalnızlığımla baş başayım…

Sevdiğimi düşünür bir sigara yakarım…

Bazen iyi bazen damar mı damarım…

Severim yine de hayatı

Vazgeçmem onun bu heybetinden

O benden vazgeçer kimi zaman

Ama ben geçmem…

Bazen arar konuşurum sevdiğimle

Sesinde bir bozukluk olduğunda 

Kendimi ölüyor hisseder

Son nefesimle onu mutlu etmek isterim…

Bir şey olsun hep birlikte olalım diye dua ederim

Ama olmaz değil mi hayat? ? 

Bana zor yanlarını göstermeden

Onu tehlikeye atamam 

Rahat ve benim

O benim her şeyim…

Kim mutsuz edebilir ki beni

Onsuz olup onu hissederim…

Onu toplarım bazen rüyalarımda

O yolmakla bitmeyen papatyalarda

Onu arar bir tek onu severim…

Ağlayamam kendim için

Belki kimse için ağlayamam

Ama onun için dünyayı ağlatabilirim…

Beni yanlış anlamayın

Bazen düşündükçe bunalır 

Düşledikçe kararırım

Ama siz içinizi ferah tutun

HER BUNALIM BİR MUTLULUK

HER KARANLIK BİR AYDINLIK YARATIR BENİM GÖNLÜMDE….', 'Yine bir gece vakti ve ben yine yalnızlığımla baş başayım… Sevdiğimi düşünür bir sigara yakarım… Bazen iyi bazen damar mı damarım… Severim y...', ARRAY['Türk Edebiyatı','Şiir','Yücel Başoğlu']::text[], 8.5, '{"poet":"Yücel Başoğlu","poet_slug":"yucel-basoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/hayatin-icinden-merhaba-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hatayda Dün ve Bugün', 'hatayda-dun-ve-bugun-ahmet-mansuroglu-a7jds', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Açmayın çiçekler, kuşlar mahzun ötün,

Yemin ettik, and içtik.

'''' Komam bire fransız seni sağ bütün ''''

Bu bayrak uğruna biz candan geçtik.

Ata son sözünü söyledi.

''''Kırk asırlık Türk yurdu düşman elinde essir kalamaz''''

Yaralı aslandı Hataylı, inledi

Son ferdim düşmeden, fransız burada duramaz.

Göğsümüzü siper ettik fransız kurşununa

Al kanımızla yeniden çizdik haritamızı

İmanla karşı koyduk, düşman hücumuna

Bu gün saygıyla anıyoruz atamızı.

23 Temmuz senin bayramın kardeşim

Kahrından öldüğün günler uzak

Karanlığı boğdu güneşim

Kalmadı ne bir düşman ne bir tuzak.

Kara günler geride kaldı

Kırıldı toprağımda düşman ayağı,

Semalarımda Ay - Yıldızlı gelincik dalgalandı

Kirletemez artık göklerimizi düşman bayrağı.

Bu gün Hatay''da bayram var, Hatay''da düğün

Başın dik Hataylım, yüzün ak

Yarına güven, halkınla övün

Dalgalanıyor göklerinde. uğruna öldüğün bayrak.

 Antakya - Hatay                23. Temmuz.1998

 Tlf: 0 326 2156779', 'Açmayın çiçekler, kuşlar mahzun ötün, Yemin ettik, and içtik. '''' Komam bire fransız seni sağ bütün '''' Bu bayrak uğruna biz candan geçtik. At...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Mansuroğlu']::text[], 8.5, '{"poet":"Ahmet Mansuroğlu","poet_slug":"ahmet-mansuroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/hatayda-dun-ve-bugun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasret', 'hasret-necat-necdet-demircan-vnmpx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Masmavi bir ummanın gözlerinde yelken açmaya niyetlenip, cılız bir dalganın sözlerinde boğulmak gibi hazindir hasret...

Hasret; 

Göç eden sürüsünün ardından ağlayan

Kanadı kırık bir leyleğin

bataklığa düşen gözyaşı damlalarıdır

Hasret; 

Kara bulutların önüne çit ördüğü

Solgun yüzlü günbatımının

duvara yansıyan terkedilmiş ışıklarıdır

Hasret; 

Orta Anadolunun 

unutulmuş küçük bir kasabasında

iki yeni yetmenin umutsuz kaçamak bakışlarıdır

Hasret; 

hayatın tadını geç farketmiş bir ihtiyarın

keşkelerle süslü uykusuz geceleridir

kimi zaman fırtınayla karışık bir tipi

açılmayan kapı

çalmayan telefon...

Koş aynaya ve iyi bak kendine

kim bilir

belki de Hasret

Senin gözbebeğindir...', 'Masmavi bir ummanın gözlerinde yelken açmaya niyetlenip, cılız bir dalganın sözlerinde boğulmak gibi hazindir hasret... Hasret;  Göç eden sü...', ARRAY['Türk Edebiyatı','Şiir','Necat Necdet Demircan']::text[], 8.5, '{"poet":"Necat Necdet Demircan","poet_slug":"necat-necdet-demircan","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/hasret-214-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Böyle Sevda mı Olur', 'boyle-sevda-mi-olur-tevfik-karinca-kxk5c', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Teselli etmiyor gözlerin beni bu gece

Böyle sevda mı olur? 

Sen nerede ben nerede

Umut üretmekten yoruldum

Dar geliyor bu can bu bedene

Böyle aşk mı olur? 

Alışmak zorundamıyım mesafelere? 

Yetmiyor hayallerin yetmiyor bu gece

Sarılıp uyumayı özledim seninle

Dualarımda seni dilendim

Böyle midir ki her sevgi? 

Yetmiyor hayallerin yetmiyor işte', 'Teselli etmiyor gözlerin beni bu gece Böyle sevda mı olur?  Sen nerede ben nerede Umut üretmekten yoruldum Dar geliyor bu can bu bedene Böyl...', ARRAY['Türk Edebiyatı','Şiir','Tevfik Karınca']::text[], 8.5, '{"poet":"Tevfik Karınca","poet_slug":"tevfik-karinca","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/boyle-sevda-mi-olur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevginin Sızdığı Yerden Uzat 1', 'sevginin-sizdigi-yerden-uzat-1-kamil-aydemir-55jx3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'yüreğim ağlar her memleket türküsünde

hiç düşündün mü işim ne sürgünde

kıyafetsiz günlerde

bey gibi gezer acılar

aşkım ancak gözlerinde susar içimdeki sancılar

kiraci olmaktansa yüreğinde

gerdanında gecekondu yaparım

mutluluğun peşinden koşan varoş çocukları gibi

koşarım saçlarının kıvrımında

saçının her telinde farklı sevinç

seninle girdiğim her yolda mutluluğu bulurum

çalım atınca kipriklerine

çıplak gözlerine sokulurum

sevdiğim itme beni bu sevdanın uzağına

hazan yaprakları gibi kururum

eksi kırk derece sıcak kalır

insanın sevdiğinin ayaz bakışlarının yanında

sevmekten başka ne yapıyor ki şu gönlüm sana

neden korkuların beni vuruyor

ayazlarında sevinçlerim umutlarım donuyor

bir senin yanında dokunamıyor hayat bana

sen aşka yer yok desende kalan örümde

yetmeyecek evlilik yüzüğünün ve cüzdanının gücü

yüreğinin kapısını hep kilitli tutmaya

yüreğinin kapısından gireceğim içeri sevgimle

sende demir atıyorsun sevgime

ne zaman öpsem gözlerini gözlerimle

seninle şaha kalkar duygularım

arzularım horon teper

sensiz

serseri bir kuş gibi uçarım zamanın arkasından

payına düşeni alır hayat

yüreğimin acısından

gözlerindir cennetim başka cennet aramam

sen hazranımsın yanında uslu uslu duramam

istemez misin dudaklarında kâmil çiçeği açsam

açsam karanlık dünyan perdelerni

uyatmak için zorla sindirdiğin duygularını

sevgimden ışık sağsam

özgürlüğünü versen yüreğine

bahar kuşları gibi karşılasan yarınlarını

becersem yapacağım şu hayata sevgiden yuralı

duygu insanıyım ben en zengin yanım sevgi

çiçeklere sevgi veririm

bundandır çiçeklerin sıcak gülüşleri

bahardan da güzel sevdiğim

sana gönlümü

bundandır yüreğimin ağırlaması göçmen kuşları

değişti atışları

ah aşkım seninle son buldu kalbimin ağlaması

telinden mutluluk ezgileri asıyor şimdi

içimdeki çocuğun bağlaması', 'yüreğim ağlar her memleket türküsünde hiç düşündün mü işim ne sürgünde kıyafetsiz günlerde bey gibi gezer acılar aşkım ancak gözlerinde susa...', ARRAY['Türk Edebiyatı','Şiir','Kamil Aydemir']::text[], 8.5, '{"poet":"Kamil Aydemir","poet_slug":"kamil-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":52,"source_url":"https://www.antoloji.com/sevginin-sizdigi-yerden-uzat-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevginin Sızdığı Yerden Uzat 2', 'sevginin-sizdigi-yerden-uzat-2-kamil-aydemir-78oqk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'hüzün kaldı hazandan bana

çıkınca sendeki dağlara

onuda savururum uzaklara

bal gülüşlerin öptüğü yerde kalmaz ki yara

yeryüzünün bütün çocukları bayram eder içimde

seviyorum seni bugüne kadar tanımadığın biçimde

pupa yelken dalışım bundan yarınlara

kasımpatiler papatyalar kaktüsler

nilüferler orkideler çiğdemler

kışın kırbacında bile gülen kardelenler

yaşamın kırancında bile 

dağlardaki gerilla gibi yarına yürüyen karanfiller

en çokta yüreğine benzeyen gelincikler

sevgimin heybesi güller

nasıl ağlar bilir misin çiçekler

eylül sarayları gibidir sensiz günler

hasretin yatırınca beni işkence tezgahına

gelde gör çiçeklerin nasıl ağladığını diyeceğim ama

sakın sende ağlama

üzmek için sevmedim seni

mutluluğun için gerekirse

bozuk para gibi harcarım ben kendimi

arzularımı azdıran

duygularımı hep şaha kaldıran

bana yaşamın bayırlarını bile sevdiren

insana ve aşka yakışan kadın

korkmuyorum kaçmandan

korkmuyorum beni unutmaya çalışmandan

nere gidersen git yüreğinde ben olacağım

zulanda soylu sevdam

her aynaya bakışında

gözlerinden sana sevgimle güleceğim

ve uzanıp dudaklarından öpeceğim

kendini mutsuzluğa hapsettiğin o hapisanenin

kapısındaki kilitleri sevgimle kıracağım

kendini unutmandan korkuyorum

korkuyorum kendini unutmandan

yeşermez ki sevda

yaşamayan bir insandan

hayat önüme serer çerçisini

gözüm görmez sevgiden başkasını

kalbimin çiçeği

kirlenmişlerin inadına seviyorum seni

neyse öderim bedelini

açmak için ertelenmişler ambarını

heder etmemek için ömrümüzün geri kalanını

ve sokaklara düşmesin diye aşk

çatlatarak içinedeki korku duvarlarını

sevginin sızdığı yerden uzat

yüreğinin eliyle tut yüreğimin elini', 'hüzün kaldı hazandan bana çıkınca sendeki dağlara onuda savururum uzaklara bal gülüşlerin öptüğü yerde kalmaz ki yara yeryüzünün bütün çocuk...', ARRAY['Türk Edebiyatı','Şiir','Kamil Aydemir']::text[], 8.5, '{"poet":"Kamil Aydemir","poet_slug":"kamil-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":50,"source_url":"https://www.antoloji.com/sevginin-sizdigi-yerden-uzat-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şeytan Karısı', 'seytan-karisi-oguz-sen-9l8rp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'duvarlar zindan oldu

kapılar çalmaz oldu

kimse halım sormaz oldu

şeytan karısı gibi

ne gelen var ne giden

yok mu beni dinleyen

bir lokmacık ekmek veren

şeytan karısı gibi

yalnızlık kaderim mi

kimseler sevmez beni

neden kimse sormaz beni

şeytan karısı gibi

oynamaz elim kolum

yok benim yerim yurdum

kul sesine muhtaç oldum

şeytan karısı gibi', 'duvarlar zindan oldu kapılar çalmaz oldu kimse halım sormaz oldu şeytan karısı gibi ne gelen var ne giden yok mu beni dinleyen bir lokmacık ...', ARRAY['Türk Edebiyatı','Şiir','Oğuz Şen']::text[], 8.5, '{"poet":"Oğuz Şen","poet_slug":"oguz-sen","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/seytan-karisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tutku', 'tutku-sule-oztiryaki-t2bgz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ölmek güzel şey belki

Ama daha da güzeli...

Arkanda seni seven olmalı.

Sevenler olmayınca

Herkes diyecek vah vah zavallı.

Zavallı olduğunu bilerek ölmek ise,

Sonsuza dek dinmeyen acı.

Ruhumun kurtuluşu

Ölümden de güzel olmalı.', 'Ölmek güzel şey belki Ama daha da güzeli... Arkanda seni seven olmalı. Sevenler olmayınca Herkes diyecek vah vah zavallı. Zavallı olduğunu b...', ARRAY['Türk Edebiyatı','Şiir','Şule Öztiryaki']::text[], 8.5, '{"poet":"Şule Öztiryaki","poet_slug":"sule-oztiryaki","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/tutku-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vefalı Dostum', 'vefali-dostum-necmiye-sarpkaya-3ik7b', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Tek başıma kalsam vefalı dostum 

Hep senin adını haykıracağım 

Ömrümce hep senin vefalı dostum 

Ölsem de ismini haykıracağım', 'Tek başıma kalsam vefalı dostum  Hep senin adını haykıracağım  Ömrümce hep senin vefalı dostum  Ölsem de ismini haykıracağım...', ARRAY['Türk Edebiyatı','Şiir','Necmiye Sarpkaya']::text[], 8.5, '{"poet":"Necmiye Sarpkaya","poet_slug":"necmiye-sarpkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/vefali-dostum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlığımı', 'yalnizligimi-sule-oztiryaki-tepvr', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'O kadar yalnızdım ki,

Paylaşmak için yalnızlığı,

Paylaşıp parçalayabilmek,

Parçalayıp yokedebilmek için

YALNIZLIĞIMI

Arayıp durdum hep arkadaşımı.

Her arayışım hüsran, her hüsranım acı,

Parçalanansa kalbim oldu.

Sonra tek tek topladım,

Dağılan herbir parçamı.

Yanımda bulduğum dostum

Yine yalnızlığım oldu.

Kabul ettim onu öylesine,

Hiç sırt çevirmedi yüzüme.

Gülümseyerek sardı kalbimi,

Güç kattı gücüme.

O kadar çok sevdim ki,

YALNIZLIĞIMI.', 'O kadar yalnızdım ki, Paylaşmak için yalnızlığı, Paylaşıp parçalayabilmek, Parçalayıp yokedebilmek için YALNIZLIĞIMI Arayıp durdum hep arkad...', ARRAY['Türk Edebiyatı','Şiir','Şule Öztiryaki']::text[], 8.5, '{"poet":"Şule Öztiryaki","poet_slug":"sule-oztiryaki","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/yalnizligimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaçış', 'kacis-zafer-mutlu-aixis', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yediverenlerde

Kapkaç gönüller..

Koş yakala birer,birer

Gönül hancı

Gelen,gidenden bihaber..

Teslim olur cümbüşün ritmine

Sevgisiz bedenler...', 'Yediverenlerde Kapkaç gönüller.. Koş yakala birer,birer Gönül hancı Gelen,gidenden bihaber.. Teslim olur cümbüşün ritmine Sevgisiz bedenler....', ARRAY['Türk Edebiyatı','Şiir','Zafer Mutlu']::text[], 8.5, '{"poet":"Zafer Mutlu","poet_slug":"zafer-mutlu","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/kacis-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Buraya kadar', 'buraya-kadar-husnu-aytekin-yx9l9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'yalnız geldim buraya kadar 

yine yalnız döneceğim biliyorum 

son kez bende batacağım güneşinle

bir sabahın göremeyeceğim ilk ışıklarını 

bir akşamın aşk yüklü mehtabını 

bir gecenin umut dolu yıldızlarını

bir daha alamayacağım kokunu

bir daha akamayacağım gözlerinden 

kalbinin el değmemiş derinliklerine 

bir daha sarılamayacağım doya doya 

bir daha tutamayacağım pamuk ellerini

bir daha öpemeyeceğim alevsi dudaklarını 

bir daha okşayamayacağım

o hep çekiştirip durduğun saçlarını 

ve artık bir daha gülemeyeceğim

yalnız geldim buraya kadar 

ta ki sana rastlayana kadar

bir sana bir sana takılı kaldım kopamadım

işte o zaman anladım 

yetmeyeceğini zamanın

işte o zaman korkuyu tanıdım 

ayrılık acısını tattım zehir zemberek 

bilmezdim ne korkuyu ne ayrılığı

yalnızlığı bilirdim ben kabulümdü 

onu yakından tanır onunla yaşardım 

ta ki seni tanıyıp seni sevene dek

bitti artık bitti demiştim 

şimdi yalnız değilsin işte 

şimdi yaşa be içinde sakladığın 

bir daha hiç yeşermeyeceğini 

çiçekler açıp güzel kokular

saçamayacağını sandığın duygularını 

şimdi yaşa,mutlu ol 

işte şimdi demiştim

buraya kadarmış,her şey burada bitti 

ve ben gözlerimi geldiğim yerde açtım 

şimdi gözlerim bir daha kapanmalı 

ve bir daha hiç açılmamalı', 'yalnız geldim buraya kadar  yine yalnız döneceğim biliyorum  son kez bende batacağım güneşinle bir sabahın göremeyeceğim ilk ışıklarını  bir...', ARRAY['Türk Edebiyatı','Şiir','Hüsnü Aytekin']::text[], 8.5, '{"poet":"Hüsnü Aytekin","poet_slug":"husnu-aytekin","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/buraya-kadar-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nasıl', 'nasil-husnu-aytekin-awpz9', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'yüreğimde taşıdığım umut

boğazımda düğümlenen bir nefes

ağzımda kuruyan bir söz

atamadığım bir kahkaha

olarak kalacak

varsıl dünyamda

yoksun bir inanç olacak

ve asla sonunu bilemediğim 

bir tapınçla yaşayacağım

sana gelince zavallım

sen hiç bilemeden

hiç anlayamadan

yitip gidecek puslar içinde

bulanık zamanın

acıyorum sana

doğuştan görmeyen biri gibi

göremeyeceksin

mum ışığında şarabın rengini

gözlerimin mutluluk saçan ışığını

dokunamayacaksın mavi,yeşil

pembe,mor yada sarıya 

doğuştan duymayan biri gibi

işitemeyeceksin aşk dolu ezgileri 

dokunduğunda,ürpereceksin

sessiz karanlığında gerçek sevgiye

ve asla göremeyecek

ve asla bulamayacak

asla tadamayacaksın

ve asla rastlayamayacaksın

seni benim gibi

seni benim kadar

sevebilecek bir başka sevgiye

belki bir gün birdenbire 

yüreğinin derinliklerinde 

bir sızı bir yangın başlayacak

işte o zaman ah diyecek

işte o zaman anlayacaksın beni

öyle bir yanacak ki yüreğin

bir damla su bile bulamayacaksın

çatlayıp kuruyan dudaklarına sürecek

işte o zaman anlayacaksın

nasıl yaşadığımı benim

neler çektiğimi senin için

kim bilir belki bir gün

hiç ummadığımız bir anda

hiç beklemediğimiz bir zamanda

ve hiç düşünmediğimiz bir yanda

feci bir kaza gibi feryatlar içinde

çarpışacak yüreklerimiz 

biliyorum ben paramparça olacağım

kanım donacak kalbim duracak

ama son olarak kapanmadan

benim gözlerimde sen

yine aynı sevginin aynı özlemin

gürleyen ateşini göreceksin

biliyorum senin gözlerinde hala

acımazız ihanetinin

burukluğu ve utancı olacak', 'yüreğimde taşıdığım umut boğazımda düğümlenen bir nefes ağzımda kuruyan bir söz atamadığım bir kahkaha olarak kalacak varsıl dünyamda yoksun...', ARRAY['Türk Edebiyatı','Şiir','Hüsnü Aytekin']::text[], 8.5, '{"poet":"Hüsnü Aytekin","poet_slug":"husnu-aytekin","theme":"Türk Şiiri","is_hero":false,"total_lines":58,"source_url":"https://www.antoloji.com/nasil-25-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kolera', 'kolera-bekir-salim-qj40p', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Karamürsel, Hersek’te kamptayız. Gene, kalabalık bir seyirci grubunun karşısında önceden hazırladığımız programı sunarken benim aklıma gazetede o gün okuduğum bir haber geldi. “Afrika’nın bilmem hangi ülkesinde kolera salgını baş göstermiş.” Dayanamadım, aldım sazı elime:

                                                  KOLERA (*)

		Ne işin var Afrika’nın düzünde,

		Gel bizim Hersek’te otur kolera.

		Yemek yapmak bilmez sahte aşçıyı,

		Tepesi üstüne yatır kolera.

		Bir teğmen var, mermer gibi suratı,

		Ciğeri taş gibi, yüreği katı,

		En büyük düşmanım Teğmen Necati,

		Onun da başını batır kolera

		Karargâha uğra, bazen, arada,

		Bizi yorgun düşürenler orada,

		En zorlu rakibin şimdi sırada,

		Mete Binbaşıyı götür kolera.

		Seni gördüm, akar oldu gözyaşım.

		Bana değme, daha küçüktür yaşım.

		Sırada tek kaldı Ferit Yüzbaşım.

		Onun da işini bitir kolera.

              Derken, baktım herkes gülmekten yerleri tırmalıyor, ama Mete Binbaşımın kaşları çatık ve bu işin sonu hiç de iyi görünmüyor. Bir küçük manevra:

		Binbaşımdan bin bir hisse kaparız.

		Yüzbaşısız yanlış yola saparız.

		Biz Onlar olmadan nasıl yaparız? 

		Hepisini geri getir kolera.

                                                                                                                               1979/HERSEK



(*)   O dönemde “kolera“ şiirleri çok yazılıyordu.Üstad Reyhanî‘nin,Âşık Feymanî‘nin de bu tarzda şiirleri vardır.', 'Karamürsel, Hersek’te kamptayız. Gene, kalabalık bir seyirci grubunun karşısında önceden hazırladığımız programı sunarken benim aklıma gazet...', ARRAY['Türk Edebiyatı','Şiir','Bekir Salim']::text[], 8.5, '{"poet":"Bekir Salim","poet_slug":"bekir-salim","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/kolera-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neyin Nesi', 'neyin-nesi-bekir-salim-4qfav', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir ihtiyar gördüm, nurdan halkolmuş,

“Al, şu bade senin, iç! ” dedi bana.

Beş güzel gösterdi, serpilmiş, dolmuş,

“Kendine sevgili seç! ” dedi bana.

Baktım birisine, gözüm kamaştı.

Gönlümün ırmağı köpürdü, taştı.

İhtiyar bir hızla tepeyi aştı.

Uzaktan, “İşin çok güç! ” dedi bana.

Gördüğüm pir değil, şeytandı herhal,

Silkindim; ardına koyuldum derhal,

Belki inanmazsın, çok garip bir hâl,

Aynı ses meçhulden ”Üç! ” dedi bana.

Aradım yarimi, buldum şubatta,

Yüksel apartmanı, “Üçüncü” katta,

Sarıldı boynuma, hatta ve hatta,

“Sevgilim, odama geç! ” dedi bana.

Aşık SALİM aman bu neyin nesi,

Kimin aldatması, kimin hilesi,

Kulağımı yırttı teğmenin sesi,

“Uyan, heeey, gözünü aç! ” dedi bana.(*)

                                                                                                            

                                                                                                                1979/BURSA

(*)    Askerî Lisede bu tür rüyaları çok sık görüyorduk.', 'Bir ihtiyar gördüm, nurdan halkolmuş, “Al, şu bade senin, iç! ” dedi bana. Beş güzel gösterdi, serpilmiş, dolmuş, “Kendine sevgili seç! ” de...', ARRAY['Türk Edebiyatı','Şiir','Bekir Salim']::text[], 8.5, '{"poet":"Bekir Salim","poet_slug":"bekir-salim","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/neyin-nesi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Öldü', 'ask-oldu-yilmaz-tombak-95exh', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gül yağmuru kesildi

berrak sularda yüzmek hayal oldu

hazan vurdu aşk bahçelerini

kelimelerin büyüsü tükendi

şimdi ne olacak

yaralı yüreklerimiz ayrı mecralara akar

basacak tuz bulamayız acılarımıza

o kadar uzak o kadar yakın

ve söylenecek ne kaldı dudaklarda 

yarım kalan hüzün bestesi

tamama erdibir ayrılık denizinde birleşti adımız

göçtü son kuşlarda gönül ülkemizden

kırmızı güllere su haram oldu

bahçe soldu bağ bozuldu

aşk öldü

ışık üşüdü

ve sen

bahçıvan elinde tarumar oldun

yılmaz tombak 03/08/2003 ank', 'Gül yağmuru kesildi berrak sularda yüzmek hayal oldu hazan vurdu aşk bahçelerini kelimelerin büyüsü tükendi şimdi ne olacak yaralı yürekleri...', ARRAY['Türk Edebiyatı','Şiir','Yılmaz Tombak']::text[], 8.5, '{"poet":"Yılmaz Tombak","poet_slug":"yilmaz-tombak","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/ask-oldu-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul´da Hüzün Esiyor Bu Defa...', 'i-stanbul-da-huzun-esiyor-bu-defa-sibel-uygun-3hx9r', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Nasıl da aşk kokar sana hasretimdeki satırlar... 

Öyle çok sevdim ki seni...

Her gelişim coşku, özlem dolu... 

Mutluluk dolu... 

Delirmişcesine koşarım sana… 

Her defasında…

Bu sefer seninle, böylesine sevgi dolu, böylesine kahkahalarla süslü, mutluluklarla bezenmiş buluşamadık… 

Sevişemedik…

Sen hüzün kokuyordun bu defa....

Sanki kara bulutlar kaplamıştı tüm yüreğini. 

Karanlıktın, bir ışık dahi sunamayacak kadar karanlık... 

Oysa bilirsin, severim karanlığı. 

Yıldızları bana ulaştıran karanlık. 

Ama yıldızlar da yok bu defa. 

Yorgansız kalmış üzerin...

Üşümüşsün besbelli... 

Titriyor yüreğin... 

Sevgi dolu gönlümle sarsam seni, ama benimde kanadım kırık. 

“Ya giderse? ” diyorum, “Ya seni terkederse? ”

Biliyorum...

İstanbul, O`nsuz olmaz.

Ama,  ya giderse? ..

Ne olur gitme…

Ne olur, canım babam,

SENİ ÇOK SEVİYORUM…', 'Nasıl da aşk kokar sana hasretimdeki satırlar...  Öyle çok sevdim ki seni... Her gelişim coşku, özlem dolu...  Mutluluk dolu...  Delirmişces...', ARRAY['Türk Edebiyatı','Şiir','Sibel Uygun']::text[], 8.5, '{"poet":"Sibel Uygun","poet_slug":"sibel-uygun","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/istanbul-da-huzun-esiyor-bu-defa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çelişki', 'celiski-semih-zaman-6qr9x', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gizeminle dolan boşluklar

Çok boştular sen gelmeden

Yokluğundan mı 

yoksa hala dönmediğinden midir

bilinmez

çok acıtıyorlar şimdi içimi…

hemen çıksan, gelsen,

dönsen boşluğuma 

doldurabilir misin, kapatabilir misin

yokluğunda çatallanan yaraları…? 

Hayır sevgili çok büyüdü açıklar

Bildiğin gibi değil…

Sensizliğe dair yazılan denklemler

Çok bilinmez oldu…

Ve bu karmaşa öldürür oldu beni..

Gelme sevgili

Ben anlamadan

yokluk nedir boşluk nedir,

kaça ayrılır, 

tekrar birleşir mi? 

Gelme sevgili

Ben iliklerime kadar yokken

Gelsen de bulamazsın

Bulsan da sevemezsin suretimi…', 'Gizeminle dolan boşluklar Çok boştular sen gelmeden Yokluğundan mı  yoksa hala dönmediğinden midir bilinmez çok acıtıyorlar şimdi içimi… hem...', ARRAY['Türk Edebiyatı','Şiir','Semih Zaman']::text[], 8.5, '{"poet":"Semih Zaman","poet_slug":"semih-zaman","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/celiski-32-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlık...', 'anlik-sibel-uygun-r8583', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Güzel olan her şey gibiydi. 

Anlık yaşanan mutluluk misali... 

Gökyüzüne baktığın anda, 

Kayan bir yıldızı farketmek! .. 

İki damla göz yaşının yanaklarından süzülürken, 

Sıcaklığını hissetmek gibiydi, 

Seni sevmek! ..', 'Güzel olan her şey gibiydi.  Anlık yaşanan mutluluk misali...  Gökyüzüne baktığın anda,  Kayan bir yıldızı farketmek! ..  İki damla göz yaşı...', ARRAY['Türk Edebiyatı','Şiir','Sibel Uygun']::text[], 8.5, '{"poet":"Sibel Uygun","poet_slug":"sibel-uygun","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/anlik-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Gideli Çok Oldu...', 'sen-gideli-cok-oldu-sibel-uygun-seq3d', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gecenin karanlığını aydınlatan yıldızlar,

Her günün doğuşunda semaya veda ederken,

Geldiğinde gideceğini biliyordum...

Ölürüm demiştim sensiz! ..

Şimdi yaşadığımı mı sanıyorsun! ..

Ölüm kapımda! ..

Sen gideli çok oldu...

Bir tek gözlerin kalmış aklımda

Her bakışımda tebessümlerle içimi ısıtan  bakışlar

Şimdi bir buz parçası gibi düşmüş yüreğime...', 'Gecenin karanlığını aydınlatan yıldızlar, Her günün doğuşunda semaya veda ederken, Geldiğinde gideceğini biliyordum... Ölürüm demiştim sensi...', ARRAY['Türk Edebiyatı','Şiir','Sibel Uygun']::text[], 8.5, '{"poet":"Sibel Uygun","poet_slug":"sibel-uygun","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sen-gideli-cok-oldu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşık -Vefa-', 'asik-vefa-erdogan-ergin-zf5hi', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ey aşık bekleme, gidenden vefa

Destanlar eskidi, yazılmaz şimdi

Çektiğin dert fazla, yeter bu cefa

Ölsen, aşk mezarın, kazılmaz şimdi

Destanlar değil mi, Aslı ile Kerem

Ben desen aşk için, çekerim her hal

Süremezsin aşka, bir sıkım merhem

Düşündükçe Mecnun, Ah! Leyla’n hayal

Ne beklersin aşık, eyvah etme sen

Düşüp, çıkamadın, bataklıktır aşk

Geçen ömründü hey! , ne güzel  bilsen

Sana bu sürünmek, yakışmaz, yazık

Bu şiiri, Şiir Perisi gurubunun ''Vefa'' konulu etkinlği için yazdım.', 'Ey aşık bekleme, gidenden vefa Destanlar eskidi, yazılmaz şimdi Çektiğin dert fazla, yeter bu cefa Ölsen, aşk mezarın, kazılmaz şimdi Destan...', ARRAY['Türk Edebiyatı','Şiir','Erdoğan Ergin']::text[], 8.5, '{"poet":"Erdoğan Ergin","poet_slug":"erdogan-ergin","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/asik-vefa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Ben Var...', 'bir-ben-var-sibel-uygun-kgstx', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yüreğimdeki şehri sana bıraktım giderken...

Yağan  yağmurlarda gözyaşlarım gizlendi...

Sevdam denizin mavi rengi,

Yosun kokan dalgalar, hırçınlığımı yüklenmiş...

Kıyıya her çarpışında sana isyanımı sunuyor

Sokaklarda gölge misali karamsarlığım...

Hüzünüm, tozun dumanın eşliğinde...

Hasretim bulutlarla, geçip gidiyor üzerinden.

Karanlığın yıldızlarında umutlarım yanıp sönerken...

Sana bıraktım ben herşeyi....

Beni benden alan, bensiz şehir...

Biraz da sen olsun diye....', 'Yüreğimdeki şehri sana bıraktım giderken... Yağan  yağmurlarda gözyaşlarım gizlendi... Sevdam denizin mavi rengi, Yosun kokan dalgalar, hırç...', ARRAY['Türk Edebiyatı','Şiir','Sibel Uygun']::text[], 8.5, '{"poet":"Sibel Uygun","poet_slug":"sibel-uygun","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bir-ben-var-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anne Beni Öldürsene', 'anne-beni-oldursene-sair-nautilus939-uewhs', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Anne bak kanıyor yaralarım

Anne bak acıyor canım

Anne bak ben artık yaşayamıyorum

Anne beni öldürsene

Gözlerimdeki yaşlar dinmiyor

Kabuk bağlamıyor yaralarım

Nefes alamıyorum artık

Anne beni öldürsene

Mezarımı derin kaz

Uçup gitmesin kalbim ellere

Üzerine bir bardak su dök söndürsün beni

Anne beni öldürsene

Buralardan kaçmak isterdim

Senden istemezdim sonumu

Ellerinde ölmek isterdim

Anne beni öldürsene

Kabul etmedi elinde ölmemi

Yaşamamı hiç istemedi 

Sevmek yalanmış meğer

Anne beni öldürsene

Ben başlarken öldüm oysaki

Ne oyuncu oldum ne de yazar

Ne yönettim oyunu küçük bir figürandım

Anne beni öldürsene

Sen getirdin dünyaya beni

Sen attın beni kurtlara

O ise yedi bitirdi beni

Anne beni öldürsene

Elimi uzattım kaçtı benden

Bir adım attım kanatlandı uçtu

Kalbimi çıkardım verdim eline

Anne beni öldürsene

Ben onsuz olamadım

Ama onunla da yapamadım

Artık perde kapandı

Anne beni öldürsene

Son kez onunla güldüm

Son kez onunla ağladım

Burada ben neden kalayım

Anne beni öldürsene

Duygularımı yitirdim önce

Gözlerimi açtım sandım

Onu görünce karşımda meğer ben çok yanıldım

Anne beni öldürsene

Anne vur kafama öldür beni

Al götür bu diyardan beni

Mezarımı derin kaz

Çünkü artık adam olmaz bu enkaz

Anne beni öldürsene

Neden yaşayayım söylesene

Yok artık kalbim benim

Sevgim direncim takatim 

Anne beni öldürsene', 'Anne bak kanıyor yaralarım Anne bak acıyor canım Anne bak ben artık yaşayamıyorum Anne beni öldürsene Gözlerimdeki yaşlar dinmiyor Kabuk bağ...', ARRAY['Türk Edebiyatı','Şiir','Şair Nautilus939']::text[], 8.5, '{"poet":"Şair Nautilus939","poet_slug":"sair-nautilus939","theme":"Türk Şiiri","is_hero":false,"total_lines":53,"source_url":"https://www.antoloji.com/anne-beni-oldursene-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekle Beni Yaylalar', 'bekle-beni-yaylalar-nevzat-sibic-0p9wl', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yolunu gözlüyorum

Şu gelecek ayların

Söz verdim geliyorum

Bekle beni yaylalar

Ne günümüz geçmişti

Soğuk suyun içmişti

Çok hatıra geçmişti 

Bekle beni yaylalar

Yağan yağmurun başka

Hep getirdin sen aşka

Sende aşklar bambaşka

Bekle beni yaylalar

Nevzatım seviyorum

O anı bekliyorum

Kavuşma diliyorum 

Bekle beni yaylalar', 'Yolunu gözlüyorum Şu gelecek ayların Söz verdim geliyorum Bekle beni yaylalar Ne günümüz geçmişti Soğuk suyun içmişti Çok hatıra geçmişti  B...', ARRAY['Türk Edebiyatı','Şiir','Nevzat Sıbıç']::text[], 8.5, '{"poet":"Nevzat Sıbıç","poet_slug":"nevzat-sibic","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bekle-beni-yaylalar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dün Geceki Yamurda Yıkadım Kalbimi', 'dun-geceki-yamurda-yikadim-kalbimi-sair-nautilus939-xvz7w', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dün geceki yağmurda yıkadım kalbimi

Ne kadar da kirliymiş 

Ne kadar da kinliymiş

Senin sevgin aktı gitti

Mazgallardan akarken sevgin

Kalbimden dökülüp 

Kalbimi parçalayan sevgin 

Mazgalları eritti

Akıp giderken sevgin kalbimden

Kendine yol yaptı sanki geri dönecek gibi

Seninle yağmurda ıslanmıştık hatırlar mısın

Ne güzeldi o yağmur oysaki

Ne güzeldi o günler

Sen kollarımdaydın 

Sevgin de bu kadar yıkıcı değildi

Ben hazırdım parçalanmaya biliyordun

Ama Sevgin kalbime muhafız

Şimdi öyle mi paramparçayım 

Sevginse yakıp geçiyor önüne geleni

Ben parçalanamam artık biliyorsun

Ben dün gece yıkadım kalbimi

Senden sadece giderken bıraktığın 

Yol var kalbimde 

Bir sürü tabela koydum kalbime

Hep yanlış yönü gösteren

Hadi gel girmeye çalış kalbime

Sonsuza kadar kaybol o çıkmaz labirentte', 'Dün geceki yağmurda yıkadım kalbimi Ne kadar da kirliymiş  Ne kadar da kinliymiş Senin sevgin aktı gitti Mazgallardan akarken sevgin Kalbimd...', ARRAY['Türk Edebiyatı','Şiir','Şair Nautilus939']::text[], 8.5, '{"poet":"Şair Nautilus939","poet_slug":"sair-nautilus939","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/dun-geceki-yamurda-yikadim-kalbimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gül', 'gul-abdulrizak-kilic-4xlyl', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'GÜL 

Filizlenmiş gül 

yamacına dağların 

Açmış tomurcuklarını 

kayaların üstüne 

Uzayabildiğince selvi 

Dağları ovaları süslemiş 

Cömertçe cennetini sergilemiş 

olabildiğince GÜNEŞ 

Gül… 

Gül ki… 

Üç yüz altmış beş gün gül 

Kaşlar kirpikler gül 

Dili bal dudakları gül 

Yüreği ay gözleri yıldız 

Elleri ayakları gül 

Ruhu gökkuşağı bedeni gül 

Gül ki… 

Tanımsız büyüleyici gül 

Sıcacık bakışları gül 

Dayanamayıp biran güzelliğine 

buz oluverdim eridim', 'GÜL  Filizlenmiş gül  yamacına dağların  Açmış tomurcuklarını  kayaların üstüne  Uzayabildiğince selvi  Dağları ovaları süslemiş  Cömertçe c...', ARRAY['Türk Edebiyatı','Şiir','Abdulrızak Kılıç']::text[], 8.5, '{"poet":"Abdulrızak Kılıç","poet_slug":"abdulrizak-kilic","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/gul-82-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tüm Duygularımı Azad Ettim Bugün', 'tum-duygularimi-azad-ettim-bugun-sair-nautilus939-hnobi', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Tüm duygularımı azad ettim bugün

Beni ben yapan duygularımı

Seni bana bağlayan ne varsa içimde

Nefret, kin, sevgi, fedakarlık

Kurtuluyorum artık

Tüm insanlığımdan

Artık gidiyorum onları bırakıp

Artık uzaklaşıyorum tüm yıkımlardan

Artık yumuyorum gözlerimi

Sevgiye aşka ve beni ben yapan her şeye

Seni bırakıyorum kalbimden

Kaldırdım artık çitlerini kalbimin

Çekip gidebilirsin bu diyardan', 'Tüm duygularımı azad ettim bugün Beni ben yapan duygularımı Seni bana bağlayan ne varsa içimde Nefret, kin, sevgi, fedakarlık Kurtuluyorum a...', ARRAY['Türk Edebiyatı','Şiir','Şair Nautilus939']::text[], 8.5, '{"poet":"Şair Nautilus939","poet_slug":"sair-nautilus939","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/tum-duygularimi-azad-ettim-bugun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Didaktik İlişkiler', 'didaktik-i-liskiler-sair-nautilus939-2qevp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Seninle didaktik bir ilişki yaşadık

Sen hep kabul ettirdin bana düşünceni

Ben hiç savunamadım kendi kalemi

Savaşlarla doluydu benim hayatım oysaki

Ne savaşabildim seninle

Ne kaçabildim, ne sildim seni 

Seni bana anlatan didaktik şiirleri

Ne de üzerine kan damlatıp; 

Yazabildim tüm gerçekliği ile

Kin ve nefret dolu düşüncelerimi

Belki kin ile doldurmalıydım 

Tüm kitaplardaki didaktik şiirleri

Gelmemeliydiler üzerime

Gelmemeliydin üzerime 

Çünkü…

Ben hiç sevemedim didaktik şiirleri

İlişkimizde didaktikti 

Senin bana dikte ettiğin her şey gibi

Ben her söze kabul desem de

Anlayamadım bir türlü gidişini

Beni unut deyişini 

Anlatamaz bana ne şiirler

Ne de ilişkiler senin çekip gidişini

Ben kaçtım hep didaktik şiirlerden

Ben kaçtım hep akıllı gülüşlerden

Ben sana geldiğim zaman bir çocuk kadar çıplaktım

Biz seninle hep didaktik yaşadık

Benim çıplaklığım dahi sorguydu

Benim sevgim olmamalıydı

Didaktik şiirlerde yeri yoktu

Ne sevginin ne de çıplaklığın

Oysa ben seni bir çocuk kadar

Saf duygularla sevdim

Bir çocuk kadar savunmasız

Bir çocuk kadar açtım sana

Muhtaçtım korunmasızdım

Sen hiç görmedin benim yırtıcı yanımı

Sen hiç görmedin kendi kanımla beslendiğimi

Sen hiç görmedin parçalarken kendimi

Sen her git dediğinde bir parça alıyordum kendimden

Sen son kez bana git dediğinde

Sadece kalbim kalmıştı elimde

Ondan koparamazdım 

Onu parçalayamazdım

Artık bittim görmüyorsun

Elimde kalbim kaldı 

Onu da yememi istiyorsun

Özür dilerim

Benim olmayan bir kalbi nasıl 

Parçalarım', 'Seninle didaktik bir ilişki yaşadık Sen hep kabul ettirdin bana düşünceni Ben hiç savunamadım kendi kalemi Savaşlarla doluydu benim hayatım ...', ARRAY['Türk Edebiyatı','Şiir','Şair Nautilus939']::text[], 8.5, '{"poet":"Şair Nautilus939","poet_slug":"sair-nautilus939","theme":"Türk Şiiri","is_hero":false,"total_lines":50,"source_url":"https://www.antoloji.com/didaktik-iliskiler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bırak Ufak Bir Muradım Alayım', 'birak-ufak-bir-muradim-alayim-nevzat-sibic-kcshc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bana sakın sevmediğin söyleme

Bırak ufak bir ümitle kalayım

Bir kez dinle bir daha da dinleme

Bırak ufak bir muradım alayım

Kaçırma bir gül yüzünü göreyim

Hasbıhalin söyle nedir bileyim

Ondan sonra ister isen öleyim

Bırak bir ufak muradım alayım

Öyle bir sevdayla tutuldum bilsen

Açsalar yüreğim kalbimi görsen

Başıma tac ederidim istersen

Bırak bir ufak  ümitle kalayım

Nevzatım derdimi diyemiyorum

Kabul edermiydi bilemiyorum

Senden başkasını sevemiyorum

Bırak bir ufak  ümitle kalayım', 'Bana sakın sevmediğin söyleme Bırak ufak bir ümitle kalayım Bir kez dinle bir daha da dinleme Bırak ufak bir muradım alayım Kaçırma bir gül ...', ARRAY['Türk Edebiyatı','Şiir','Nevzat Sıbıç']::text[], 8.5, '{"poet":"Nevzat Sıbıç","poet_slug":"nevzat-sibic","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/birak-ufak-bir-muradim-alayim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Askerden Anneme Mektup', 'askerden-anneme-mektup-ahmet-mansuroglu-4kezh', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Küçükken uykusuz kaldın beşiğimin başında

Ağladım kucakladın daha küçük yaşımda

Üzüntülü günlerimde seni buldum karşımda

Şimdi sensizim içim yanıyor anne.

Bilirim eziyet ettim üzdüm yaramazlıklarımla

Azmı hırpaladım haylazlıklarımla

Bilirsin bende çok çile çektim alın yazımla

Şimdi senden çok uzaklardayım anne.

Emek verdin büyüttün askere yoladın

Askerin torbasını ellerinle bağladın

Kim bilir kaç geceler benim için ağladın

Üzülme belki bir gün dönerim anne.

Üzütülü günlerinde bizdik gönlünün tesellisi

Ey hasta gecelerimin sadık bekçisi

Ey yorgun günlerimin tek tesellisi

Ağlama belki bir gün dönerim anne.

Şimdi sesleniyorum sana uzaklardan

Belki dönerim, belki dönmem bu topraklardan

Eğer ölüm haberim gelirse uzaklardan

Ağlama yanlız hakkını helal et anne.

 Bandırma - Balıkesir', 'Küçükken uykusuz kaldın beşiğimin başında Ağladım kucakladın daha küçük yaşımda Üzüntülü günlerimde seni buldum karşımda Şimdi sensizim içim...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Mansuroğlu']::text[], 8.5, '{"poet":"Ahmet Mansuroğlu","poet_slug":"ahmet-mansuroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/askerden-anneme-mektup-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Şehir', 'bu-sehir-erkan-arslan-69v2s', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bu şehir sessiz bir sukunet vadisidir.

Burda hayat seslerin,can çekişindedir.

Bir dava arkadaşıydım,bilmezi bilir.

Gireni çıkmaz oldu,gideni gelmez ki.

Bu garip aleme,gizlice gireceğim.

Sır olup,giz olup,ansızın gideceğim.

Yeniden doğmak için,bir kez öleceğim.

Bu göç,ayrılıktan yana bana davettir.

Çok derindir ölülerin uykusu derin.

Ölüm ne ney dinler,ne dert dinler bilin.

Uyuyana seslenmek için,artık uyan.

Burası renkli,suda balık gibi hafif.

bu şehri sessizliğiyle titrer bulmuştum.

Ve şehrin bakaçak,gören gözü olmuştum.

Bu maveraya asılmış,ipler duymuştum.

Hey yıldızlar sizde,düşmeyeçekmisiniz.

Bütün güzelliklerin,esrarı açılır.

İnsan son kez hayata eder elveda,

Ve uzanır doğmak,için mermer kundağa 

Başlar şükür için,Rabbine yalvarmaya.

                         Kasım  1999', 'Bu şehir sessiz bir sukunet vadisidir. Burda hayat seslerin,can çekişindedir. Bir dava arkadaşıydım,bilmezi bilir. Gireni çıkmaz oldu,gideni...', ARRAY['Türk Edebiyatı','Şiir','Erkan Arslan']::text[], 8.5, '{"poet":"Erkan Arslan","poet_slug":"erkan-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bu-sehir-36-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Herşeye Rağmen', 'herseye-ragmen-hasan-can-7hbip', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gel yanıma göster kendini,

Korkma hadi anlat derdini,

Derdin aşksa bırak kalbini,

Korkma acıtmaz hiçbir neden seni.

Aşıksan birşeylere katlanmalısın,

Ayrılık olsa bile kaçmamalısın,

Aşıksan saklamamalısın,

Karşındaki bilmeli anlatmalısın.

Nedeni her ne olursa olsun,

Güzeldir herşeye rağmen aşk.

Gözlerden yaşlar boşalsa da,

Aşk içindir akıp gidenler...', 'Gel yanıma göster kendini, Korkma hadi anlat derdini, Derdin aşksa bırak kalbini, Korkma acıtmaz hiçbir neden seni. Aşıksan birşeylere katla...', ARRAY['Türk Edebiyatı','Şiir','Hasan Can']::text[], 8.5, '{"poet":"Hasan Can","poet_slug":"hasan-can","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/herseye-ragmen-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pişmanlık', 'pismanlik-mehmet-lutfu-aydin-kp6f5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir dilberin peşinden az mı koştum yoruldum

Feleğimi şaşırdım, dinden imandan oldum 

Aklımı aldı baştan, aşk oduyla yoğruldum

Kavuşuruz diyordum, gözyaşına boğuldum 

Yandı gönül tutuştu, kor ateşte kavruldum

Gonca güldüm sarardım, bir kez açmadan soldum

Geç de olsa arlandım, sular gibi duruldum

Kınamayın be dostlar, belamı kendim buldum', 'Bir dilberin peşinden az mı koştum yoruldum Feleğimi şaşırdım, dinden imandan oldum  Aklımı aldı baştan, aşk oduyla yoğruldum Kavuşuruz diyo...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Lütfü Aydın']::text[], 8.5, '{"poet":"Mehmet Lütfü Aydın","poet_slug":"mehmet-lutfu-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/pismanlik-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oğlum', 'oglum-ahmet-mansuroglu-hpgm6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Eğer başarı mutluluk ise,

İşte ilk basamaktır lise,

Her kim çalışmak gerekmez derse,

İnanma o sana dost değil oğlum.

Tembelce başkasının sırtında dereyi aşma,

Sel alıp gitse de azminden şaşma,

Çağlayan su ol, yerinden taşma,

Taşan sular düz ovada kaybolur oğlum.

Hiç bir zaman başarı sarhoşu olma,

Başarı insanın başını döndürür oğlum.

Ümit varken ümitsizlikle dolma,

Ümitsizlik insanı söndürür oğlum.

Gençlikte geçici zevklerin esiri olma,

Bu güzel çağda çiçek açarken solma,

Zevkle zaman aldatır, sonra saçını yolma,

Yarını düşünmek seni güldürür oğlum.

Hiç bir zaman sönmedi umutlarım

Artık lise geride kaldı seni kutlarım

Hayatta çok şey yok sizsiniz umutlarım,

Güçlükler anıtların başını eğemez oğlum.

 (Antakya lisesini bitirdiği yıl oğlum''a)         

 Antakya - Hatay           07. 08. 1984', 'Eğer başarı mutluluk ise, İşte ilk basamaktır lise, Her kim çalışmak gerekmez derse, İnanma o sana dost değil oğlum. Tembelce başkasının sır...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Mansuroğlu']::text[], 8.5, '{"poet":"Ahmet Mansuroğlu","poet_slug":"ahmet-mansuroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/oglum-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şubat Soğuğu', 'subat-sogugu-hasan-can-alkev', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Uzun bir yol buldum kendime,

Yürüyorum subat soğuğunda titrek titrek,

Önümü bir kar yığını kapatmış,

Gözlerim de ellerim gibi titrek bakıyor.

Bir kar yığınını geçiyorum,

Ve yola koyuldum derken,

Önüme o beyaz yığın yine çıkıyor.

Kendime bir yol buldum bembeyaz,

Ama beyazı kapkara bir hüsran.

Çıkar yol bulmak o kadar kolay değilmiş anladım,

Bembeyaz bir yol bile böylesine karayken,

Çıkar yol nerede kimbilir...

Evet, bir yol buldum kendime,

Hani gittikçe uzar ya,

Öylesine uzun işte.', 'Uzun bir yol buldum kendime, Yürüyorum subat soğuğunda titrek titrek, Önümü bir kar yığını kapatmış, Gözlerim de ellerim gibi titrek bakıyor...', ARRAY['Türk Edebiyatı','Şiir','Hasan Can']::text[], 8.5, '{"poet":"Hasan Can","poet_slug":"hasan-can","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/subat-sogugu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağaçlara Yazdım Aşımı', 'agaclara-yazdim-asimi-nijat-ayvaz-fh6rx', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Çocuktum,

İlk aşkımdı

Masum ve saf.

Henüz incinmemiş kalbimde

İnci taneleri.

Sevgi sözcüklerinin

En çocukçasını, 

Ağaçlara kazırdık.

Bir bahar bile gitmeyen sözlerdi onlar,

Yıllar gibi gelen.

Şimdilerde; 

Ağaçlara yazacak saflıkta

Sevgi bulmak; bir düş olması bir yana,

Yazacak ağaç bile bulamıyorum.

Yaşadığım dünyada...

13.06.2001', 'Çocuktum, İlk aşkımdı Masum ve saf. Henüz incinmemiş kalbimde İnci taneleri. Sevgi sözcüklerinin En çocukçasını,  Ağaçlara kazırdık. Bir bah...', ARRAY['Türk Edebiyatı','Şiir','Nijat Ayvaz']::text[], 8.5, '{"poet":"Nijat Ayvaz","poet_slug":"nijat-ayvaz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/agaclara-yazdim-asimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Saatten Sonra', 'bu-saatten-sonra-nijat-ayvaz-37a4c', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bu saatten sonra

Özgürlüğüm olan bu şehir,

Tutsaklığım olur yokluğunda.

Ya nasıl geceler uyuduğum,

Gündüzlerse yaşadığım olur.

İşittiğim şarkılar sen olmadan

Nasıl coşturabilir içimi.

Güldüğüm şeyler azalır yokluğunda,

Ağladıklarım artar.

10,08,2004', 'Bu saatten sonra Özgürlüğüm olan bu şehir, Tutsaklığım olur yokluğunda. Ya nasıl geceler uyuduğum, Gündüzlerse yaşadığım olur. İşittiğim şar...', ARRAY['Türk Edebiyatı','Şiir','Nijat Ayvaz']::text[], 8.5, '{"poet":"Nijat Ayvaz","poet_slug":"nijat-ayvaz","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/bu-saatten-sonra-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşık Olmak', 'asik-olmak-murat-ceylan-jly7a', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Koskoca bir hiç verir sana

İşte böyle bir şeydir aşık olmak

Bir o kadar anlamsız ve boşa

Hayat ölüm olur

Ölüm ise olur yaşamak

Hangisi değer ki gözyaşlarına

Sen değdin mi ki gözyaşlarıma

Murat Ceylan', 'Koskoca bir hiç verir sana İşte böyle bir şeydir aşık olmak Bir o kadar anlamsız ve boşa Hayat ölüm olur Ölüm ise olur yaşamak Hangisi değer...', ARRAY['Türk Edebiyatı','Şiir','Murat Ceylan']::text[], 8.5, '{"poet":"Murat Ceylan","poet_slug":"murat-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/asik-olmak-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söğüt ve Rüzgar', 'sogut-ve-ruzgar-ozlem-sahin-nxnij', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Acımasız rüzgara direnen söğüt ağacı gibiyim.

Ufacık bir esinti,

Sallıyor kocaman gövdemi, dağılıyorum.

Söğüdün yaprakları gibi, uçuşuyor incecik dallarım.

Söğüt dalı gibi sallanıp,

    savruluyorum rüzgarda dört bir yana

Seni seviyorum diyenin, peşinden koşuyorum.

Benim rüzgarım sevgi,

Esince kötü eser.

İçinde nefret, yalan yüklü olanlar,

Sevgi sözcüklerini kullanırlar, amaçlarına ulaşmak için.

Amaçlarına ulaşınca, rüzgar gibi esip giderler.

Geride, söğüt ağacı gibi sallanan

bir ben kalırım, çaresiz.', 'Acımasız rüzgara direnen söğüt ağacı gibiyim. Ufacık bir esinti, Sallıyor kocaman gövdemi, dağılıyorum. Söğüdün yaprakları gibi, uçuşuyor in...', ARRAY['Türk Edebiyatı','Şiir','Özlem Şahin']::text[], 8.5, '{"poet":"Özlem Şahin","poet_slug":"ozlem-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sogut-ve-ruzgar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensin Beni Çağlar Boyu Sürükleyen', 'sensin-beni-caglar-boyu-surukleyen-nijat-ayvaz-50jii', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Görünen o ki,

Sensin her biçimde kapıldığım.

Yılmadan yüzyıllar boyu,

Bir bedenden diğerine koştuğum sensin.

Öptüğüm o boyun senin her seferinde.

Zamanın karanlığından davet ediyor aşkın.

Son nefesimi vermeme engel o bakışların.

Biliyorum.

Sonsuzluğun kollarında sarıldığım sensin.

Sensin beni çağlar boyu sürükleyen.

08,09,2003', 'Görünen o ki, Sensin her biçimde kapıldığım. Yılmadan yüzyıllar boyu, Bir bedenden diğerine koştuğum sensin. Öptüğüm o boyun senin her sefer...', ARRAY['Türk Edebiyatı','Şiir','Nijat Ayvaz']::text[], 8.5, '{"poet":"Nijat Ayvaz","poet_slug":"nijat-ayvaz","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sensin-beni-caglar-boyu-surukleyen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Min Bihêrin', 'min-bih-rin-abdullah-karabag-2fx5u', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Navmaliya şîrîn

           şîrîna navber

Min têxin

     destarê destîbenav

Di tariyê bêriyê de

       hûrik hûrik bihêrin

Bi sibehê re

            berhevkin

Kîsên hevrîşimê

            jê tijekin

Li siya serwiya

               mala we

Bi nexş û nimûş 

             bi cih bikin

Navmaliya şîrîn

            şîrîna şandî

Bila di nav me de

                     bimîne

Hema rûperiya min

                tê taştêyê

Ez ê jê re bibim

      dîwana rawesê.

Sewta Berbangê', 'Navmaliya şîrîn            şîrîna navber Min têxin      destarê destîbenav Di tariyê bêriyê de        hûrik hûrik bihêrin Bi sibehê re      ...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Karabağ']::text[], 8.5, '{"poet":"Abdullah Karabağ","poet_slug":"abdullah-karabag","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/min-biherin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alabildiğine', 'alabildigine-ozlem-sahin-sumql', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kuşsan uçacaksın alabildiğine, 

Gökyüzü senin.

Balıksan yüzeceksin alabildiğine,

Okyanuslar senin.

Gülsen açacsaksın alabildiğine,

Bu toprak, bu güneş senin.

İnsansan sen de seveceksin,

Bu gönül, bu yürek senin.', 'Kuşsan uçacaksın alabildiğine,  Gökyüzü senin. Balıksan yüzeceksin alabildiğine, Okyanuslar senin. Gülsen açacsaksın alabildiğine, Bu toprak...', ARRAY['Türk Edebiyatı','Şiir','Özlem Şahin']::text[], 8.5, '{"poet":"Özlem Şahin","poet_slug":"ozlem-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/alabildigine-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çekilme Vakti Dünyamın Dünyandan', 'cekilme-vakti-dunyamin-dunyandan-nijat-ayvaz-ykz7g', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Seni seviyorum tatlı kalbim.

Biliyorum hep seni bekledim.

Vakti gelince güneş,

Tahtını Ay''a terkeder.

Gitmeyi bilmeli.

Çekilme vakti

Dünyamın dünyandan.

Seni seviyorum.

Aşkımı gözyaşlarımla yazdığım.

Seni Seviyorum.

18.08.2002', 'Seni seviyorum tatlı kalbim. Biliyorum hep seni bekledim. Vakti gelince güneş, Tahtını Ay''a terkeder. Gitmeyi bilmeli. Çekilme vakti Dünyamı...', ARRAY['Türk Edebiyatı','Şiir','Nijat Ayvaz']::text[], 8.5, '{"poet":"Nijat Ayvaz","poet_slug":"nijat-ayvaz","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/cekilme-vakti-dunyamin-dunyandan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Herkes, Kendi Karanlığını Süpürse', 'herkes-kendi-karanligini-supurse-ugur-olgar-ifiru', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'herkes,

kendi karanlığını süpürse

gecesinin önünden

acıları sabaha dönüştürse

haziranda açan manolyanın kokusuyla

depreşse deli sevdalar yürekte

bildik bir deniz tsunami olup

dalgasını geçse hayatla

aramıza giren karakedinin kuyruğuna

yıldız bağlasa küresel dünya çocukları

ellerini soksa kuzgun taşın altına

bugünün büyükleri

yer değiştirse maviyle yeşil gökkuşağında

usulca, kör bir ozan farketse yalnız

ağlasa zamana ilenerek', 'herkes, kendi karanlığını süpürse gecesinin önünden acıları sabaha dönüştürse haziranda açan manolyanın kokusuyla depreşse deli sevdalar yür...', ARRAY['Türk Edebiyatı','Şiir','Uğur Olgar']::text[], 8.5, '{"poet":"Uğur Olgar","poet_slug":"ugur-olgar","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/herkes-kendi-karanligini-supurse-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mezar Taşı', 'mezar-tasi-nijat-ayvaz-aqx10', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sessizliğin mezar taşıdır.

Aralarında aşkın bittiği

İki insanın,

Karşılıklı oturup

Devam etme oyunu...

29.11.2000', 'Sessizliğin mezar taşıdır. Aralarında aşkın bittiği İki insanın, Karşılıklı oturup Devam etme oyunu... 29.11.2000...', ARRAY['Türk Edebiyatı','Şiir','Nijat Ayvaz']::text[], 8.5, '{"poet":"Nijat Ayvaz","poet_slug":"nijat-ayvaz","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/mezar-tasi-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şehit Düşmek', 'sehit-dusmek-yusuf-colak-ln9dj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Şehit düşmek,

Bir uçurum kadar yüksek, 

Bir düş kadar yakın.

Ne düşmek ister, 

Ne de düşlememek.

Binlerce defa şehit düştük,

Bir düştü şehitlik, 

Ölenler için.

Ölmedik,dirildik her seferinde,

Lanet okuyarak,haykırarak,şehadet getirerek,,,', 'Şehit düşmek, Bir uçurum kadar yüksek,  Bir düş kadar yakın. Ne düşmek ister,  Ne de düşlememek. Binlerce defa şehit düştük, Bir düştü şehit...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Çolak']::text[], 8.5, '{"poet":"Yusuf Çolak","poet_slug":"yusuf-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sehit-dusmek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İbrahim', 'i-brahim-ahmet-mansuroglu-28xbn', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İnanıyorum Tanrının büyüklüğüne

Böylesine büyük bir eser ancak ona yaraşır

Renk renk oldu gecenin karanlığı

Aramızda sen vardın, ağıt sesleri vardı.

Hadi artık bırak ağlamayı, ayıp erkekler ağlamaz

İlk ağıdın çok hoştu sen ağladın biz güldük

Mutluluk getiren ağıtların olduğunu senden gördük

Evimizde seninle yükseldi kahkahalar

Aramıza hoş geldin İbrahim, iyiki geldin...

 (Oğlum İbrahim''in doğumu için) 

  Antakya - Hatay             25.08.1966', 'İnanıyorum Tanrının büyüklüğüne Böylesine büyük bir eser ancak ona yaraşır Renk renk oldu gecenin karanlığı Aramızda sen vardın, ağıt sesler...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Mansuroğlu']::text[], 8.5, '{"poet":"Ahmet Mansuroğlu","poet_slug":"ahmet-mansuroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/ibrahim-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mum Alevi', 'mum-alevi-nijat-ayvaz-urg1u', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Her neredeysen

Çık karanlığından.

Dirilt mutsuz aşk düşlerini.

Üflenmeden son mum alevi,

Yeniden dirilt bende

Kendini...

20,08,2001', 'Her neredeysen Çık karanlığından. Dirilt mutsuz aşk düşlerini. Üflenmeden son mum alevi, Yeniden dirilt bende Kendini... 20,08,2001...', ARRAY['Türk Edebiyatı','Şiir','Nijat Ayvaz']::text[], 8.5, '{"poet":"Nijat Ayvaz","poet_slug":"nijat-ayvaz","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/mum-alevi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayna', 'ayna-nijat-ayvaz-c2oiv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sana sadece

Ne kadar güzel olduğunu

Söylemekle yetinmeyeceğim.

Sana,

Güzelliğini sevmemle göstereceğim.

Baktığın aynaların

Yalan sözlerine kanma sakın.

Gönül aynamda,

Asla yaşlanmazsın.

18,06,2001', 'Sana sadece Ne kadar güzel olduğunu Söylemekle yetinmeyeceğim. Sana, Güzelliğini sevmemle göstereceğim. Baktığın aynaların Yalan sözlerine k...', ARRAY['Türk Edebiyatı','Şiir','Nijat Ayvaz']::text[], 8.5, '{"poet":"Nijat Ayvaz","poet_slug":"nijat-ayvaz","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ayna-64-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Firar Edemiyorum Sana Dair Ne Varsa', 'firar-edemiyorum-sana-dair-ne-varsa-murat-ceylan-9acla', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Rakı şişelerine gömmedim seni

Aşkımı üç maket sigaraya satmadım

Tarihteki hiçbir sevgiye benzetmedim sevgimi

Ben senin dışında hiçbir yaratılmışa ağlamadım

Firar edemiyorum sana dair ne varsa

Ben göğsüme canımı değil seni sığdırmışım, sığmasanda

Her şeyi unuturdum her şeyi, yüce Rabbim seni yaratmasa

Al senin olsun mazim, bu günümün, hatta yarınımda

Tarifi mümkün değil aşkımı anlatamam

Seni hiçbir şarkıya hiçbir şiire sığdıramam

Belki bu yüzden derdim, bu yüzden tasam

Sen benim hayata dair çiğnemeyeceğim tek yasam

Yokluğunda kudurmuş mahluklara dönüyorum

Geceyi gündüzü acımadan pençelerimle yırtıyorum

Bırak sensizliği, yokluğunu hissedince çıldırıyorum

Anladım bir tanem anladım ben sensiz nefes bile alamıyorum

Sesine kurban olduğum senden yeryüzünde başka var mu? 

Seni düşünmemek söyle bu kör aşığa kâr mı? 

Söyle yoluna ömrümü serdiğim bu can senden gayrına yanar mı? 

Melekler fısıldadı seni bana meleklerin sözleri yalan mı? 

Canımı vermek isterdim senin saçının teline 

Sana olan aşkıma diyet olsun diye

Seni bestelemek isterdim hayat denen sazın teline

Sana olan muhtaçlığımı anlatır bekli de

Rakı şişelerine gömmedim seni

Aşkımı üç maket sigaraya satmadım

Tarihteki hiçbir sevgiye benzetmedim sevgimi

Ben senin dışında hiçbir yaratılmışa ağlamadım

Firar edemiyorum sana dair ne varsa

Ben göğsüme canımı değil seni sığdırmışım, sığmasanda

Her şeyi unuturdum her şeyi, yüce Rabbim seni yaratmasa

Al senin olsun mazim, bu günümün, hatta yarınımda

                                                                     Murat CEYLAN', 'Rakı şişelerine gömmedim seni Aşkımı üç maket sigaraya satmadım Tarihteki hiçbir sevgiye benzetmedim sevgimi Ben senin dışında hiçbir yaratı...', ARRAY['Türk Edebiyatı','Şiir','Murat Ceylan']::text[], 8.5, '{"poet":"Murat Ceylan","poet_slug":"murat-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/firar-edemiyorum-sana-dair-ne-varsa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Faik Kazancı', 'faik-kazanci-ahmet-mansuroglu-wg982', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Fanidir insanlar gelir geçer,

Aydın insan iyiyi güzeli seçer

İnsan doğar, büyür, yer, içer

Kalıcı olan insanlık, herşey gelir geçer.

Kolay değil güzel insan olmak,

Akan su gibi gönüllere dolmak.

Zor değil iyiyi güzeli bulmak,

Ama güzeldir adam gibi adam olmak.

Nice yıllar sonra seni tanıdım Faik Kazancı,

Cümle güzellikler onun başının tacı

Işıktır o hemde gönüllerin ilacı.

Sana selam sevgi Kazancı,

Hatay''lı şairin sen oldun kazancı.

  (Sevgili dostum Faik Kazancı''ya)



 Lütfen şiirin baş harflerine dikkat ediniz.

 Ankara                    08. 05. 1992', 'Fanidir insanlar gelir geçer, Aydın insan iyiyi güzeli seçer İnsan doğar, büyür, yer, içer Kalıcı olan insanlık, herşey gelir geçer. Kolay d...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Mansuroğlu']::text[], 8.5, '{"poet":"Ahmet Mansuroğlu","poet_slug":"ahmet-mansuroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/faik-kazanci-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül Muhabbetleri (1)', 'gonul-muhabbetleri-1-murat-nail-guney-s4gd7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seni sevmeyip te unutanları,

Söyle sen ne diye anarsın gönül.

Bu dünya üç günlük, dördüncüsü yok,

Sonra mahşere dek yanarsın gönül...

Bozmasın ihanet sevgi kimyanı,

Çocuk yüreğinle yaşa her anı,

Bırak,hasretlerin sıkılsın canı,

Gül dikenlerinden kanarsın gönül...

Neresi vatanın, neresi gurbet,

Bilemedin, hala ararsın gönül.

Seni aldatanlar tutuştu sabret,

Alev-alev yansın, kararsın gönül...

Sevgiden başka bir mucize var mı,

Hayata bağlayan, sorarsın gönül.

Sevdasız baş ile aşık yaşar mı,

Kara toprakları sararsın gönül...

Neden hüzünlere meyledip durdun,

Gençlğimi yasa boyarsın gönül.

Azrail kaç kere affetti beni,

Korkarım canıma kıyarsın gönül...

Muradım, ilacın yok aşk elinden,

Mutluluk özlemi düşmez dilinden,

Ayrılıklar bize, zordur ölümden,

Dilerim fikrinden cayarsın gönül...

01/01/2005     Bodrum   Murat Nail Güney', 'Seni sevmeyip te unutanları, Söyle sen ne diye anarsın gönül. Bu dünya üç günlük, dördüncüsü yok, Sonra mahşere dek yanarsın gönül... Bozmas...', ARRAY['Türk Edebiyatı','Şiir','Murat Nail Güney']::text[], 8.5, '{"poet":"Murat Nail Güney","poet_slug":"murat-nail-guney","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/gonul-muhabbetleri-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaçış', 'kacis-nijat-ayvaz-oxutq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ne kadar uzağa gidebilir insan,

Kaçması en zor kendisi olunca.

Ben senin hayatından kaçarken,

En uzaklar,

Hep en tuzaklar olur.

Gölgem gibi aşkın.

Kaçış yönlerime eklenen.

Ve en uzakta da olsam,

Sıcak bir meltemle esir alan sıcaklığın.

Unutma çabam boşuna biliyorum.

Boşuna rüyalarıma esir ettiğim emanet tenler.

Hala hayattayken sen ve ben.

Silik bir resim karesi gibi

Esiriz zamanın acımasızlığına.

Ne bir tanıdık ses beni teskin eder,

Ne bir sıcak hava neşemi yerine getirir.

Yokluğunda alnıma düşen yağmur damlaları

Eşlik eder gözyaşlarıma.

Ne kadar uzağa gidebilirİm ki aşkından.

Sen yüreğimde oldukça.

Kaçsam kovalarmısın beni eskisi gibi! 

Farkına bile varmadığın bir benim artık.

Göz pınarlarım kurumuş,

Şimdi yabancı ellerin dokunduğu tenin

Ve katlanılır olmaktan çoktan çıkmış,

Kiralık dudaklara emanet dudaklarım.

İsyanların en küçüğünü bile çoktan özleyen yüreğim,

İşitilmezliğin isyanını koparır da,

Yalnız kalır savaşında.

Nasıl bir işkencedir bu böyle.

Nasıl unutamaz olur insan sevince.

Ve neden sen olur gün gün.

Nasıl bir kaçıştır ki bu,

Kaçtıkça uzak kalamadığım

Uzak olduğunu düşündükçe,

Yakınlaştığım...

22,09,2002', 'Ne kadar uzağa gidebilir insan, Kaçması en zor kendisi olunca. Ben senin hayatından kaçarken, En uzaklar, Hep en tuzaklar olur. Gölgem gibi ...', ARRAY['Türk Edebiyatı','Şiir','Nijat Ayvaz']::text[], 8.5, '{"poet":"Nijat Ayvaz","poet_slug":"nijat-ayvaz","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/kacis-29-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül Muhabbetleri (2)', 'gonul-muhabbetleri-2-murat-nail-guney-drug0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu akşam şarkılar seni anıyor,

Boşalan kadehler sarhoş aşkınla,

Gönül, matemlere elveda deyip,

Kavuşmak istiyor ne olur anla...

Karayel esse de yaz ortasında,

Bak melekler bile bunun yasında,

Nihavent şarkımın aşk bestesinde,

Sende özler miydin beni zamanla...

Mor dağlarda bülbül gezer avare,

Haykırsam avazım gider mi yare,

Gurbette sensizim gülüm, ne çare,

Başbaşa her gece son hatıranla...

Sahilde martılar başımda döner,

Sanma ki, bu ateş zamanla söner,

Perişan halime bir çare öner,

Yalnız koyma beni bu deli canla...

Yıldızlar semada, ufkumda hüzün,

Hala kulağımda çınlıyor sözün,

Eğer sevdiğine pişmansa özün,

Beni de kurban et, bu yıl kurbanla...

01/01/2005    Bodrum   Murat Nail Güney', 'Bu akşam şarkılar seni anıyor, Boşalan kadehler sarhoş aşkınla, Gönül, matemlere elveda deyip, Kavuşmak istiyor ne olur anla... Karayel esse...', ARRAY['Türk Edebiyatı','Şiir','Murat Nail Güney']::text[], 8.5, '{"poet":"Murat Nail Güney","poet_slug":"murat-nail-guney","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/gonul-muhabbetleri-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayfer', 'ayfer-ahmet-mansuroglu-1wvb8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ayın feri aydınlıktır

Siz Ayferi gördünüz mü? 

Gülerken gözleri de güler

Siz onunla güldünüz mü? 

Sana Ayfer demişler

Kız sen aydan da güzelsin

Ne güzel de isim vermişler

Seni çok ama çok sevmişler.

Ayfer sen hoş geldin aramıza

Gelişinle renk kattın dünyamıza

Seni koymak istedik canımıza

Ayfer sen hoş geldin aramıza.

  (Torunum Ayfer''in doğumu için) 

 Antakya - Hatay             23.08.1996', 'Ayın feri aydınlıktır Siz Ayferi gördünüz mü?  Gülerken gözleri de güler Siz onunla güldünüz mü?  Sana Ayfer demişler Kız sen aydan da güzel...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Mansuroğlu']::text[], 8.5, '{"poet":"Ahmet Mansuroğlu","poet_slug":"ahmet-mansuroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ayfer-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'UYU(ya) MA(ma) YI', 'uyu-ya-ma-ma-yi-nijat-ayvaz-90vcp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Seni tanısıktan sonra

Gözlerim açık

Uyu(ya) ma(ma) yı öğrendim.

Tatlı kalbim.

14.08.2002', 'Seni tanısıktan sonra Gözlerim açık Uyu(ya) ma(ma) yı öğrendim. Tatlı kalbim. 14.08.2002...', ARRAY['Türk Edebiyatı','Şiir','Nijat Ayvaz']::text[], 8.5, '{"poet":"Nijat Ayvaz","poet_slug":"nijat-ayvaz","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/uyu-ya-ma-ma-yi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Çok Eğlendin', 'ask-cok-eglendin-ozkan-sahin-sj1cc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Aşkı ben sevmedim

yok karşılığı

büyüğünede

küçüğünede

lanet olsun

kahrolsun

hiç olmasın

öl artık

yada

çık git

yüreğimden

anlamam gerek

Aşk sen hiç olmadın

varmışın gibi

beni bitirdin,

Aşk! çek git! 

hikayesin

kibirlenme

birazda

sen çırpın aşk

çok eğlendin.

                             -8-12-2000', 'Aşkı ben sevmedim yok karşılığı büyüğünede küçüğünede lanet olsun kahrolsun hiç olmasın öl artık yada çık git yüreğimden anlamam gerek Aşk s...', ARRAY['Türk Edebiyatı','Şiir','Özkan Şahin']::text[], 8.5, '{"poet":"Özkan Şahin","poet_slug":"ozkan-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/ask-cok-eglendin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haberin Varmı?', 'haberin-varmi-ahmet-mansuroglu-71c1u', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bu ömür bir gün gibi geçecek

Hiç bir güç yok ki sana dur diyecek

Bütün hışmıyla azrail gelecek

Dünya yalan haberin var mı? 

Çıkar için komşu hakkı demezsin

Aç gözlüsün hatır gönül bilmezsin

Doğru yola gel desem gelmezsin

Gidenler gelmiyor haberin varmı? 

Haram, helal demez yersin

Dünya ballı börek yutayım dersin

Doymak bilmeyem gafil, aldanan sensin

Mahşerde hesabı var haberin var mı? 

Güler yüzle bakar, dürüst görünürsün

Aç kurt iken kuzu postuna bürünürsün

Üç kuruş için yerlerde sürünürsün

Karun bile çıplak gitti haberin var mı? 

 Antakya - Hatay             20. Aralık. 1991', 'Bu ömür bir gün gibi geçecek Hiç bir güç yok ki sana dur diyecek Bütün hışmıyla azrail gelecek Dünya yalan haberin var mı?  Çıkar için komşu...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Mansuroğlu']::text[], 8.5, '{"poet":"Ahmet Mansuroğlu","poet_slug":"ahmet-mansuroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/haberin-varmi-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Git', 'git-nijat-ayvaz-sv86p', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Birbiri ardına geçiyor

Çiğnenmeden yutulan günler.

Geçiyor hayatımdan dizi dizi

En gepegenç tenler...

Yüreğimin yamacı kalabalık

Güneşime erişemezsin.

Git.....Git.

Hiç gecikmeden başka aşklara git.

Ölüm kapımı yumrukluyor,

Ben şarkımı ıssızlığa söylüyorum artık.

Aşkına eşlik edemem.

Sen kusursuz gündüz yıldızı gibisin

Bense gece utancı,

Sönmüş yıldız.

Bırak git....Git.

Gecikmeden başka aşklara git.

02.03.1998', 'Birbiri ardına geçiyor Çiğnenmeden yutulan günler. Geçiyor hayatımdan dizi dizi En gepegenç tenler... Yüreğimin yamacı kalabalık Güneşime er...', ARRAY['Türk Edebiyatı','Şiir','Nijat Ayvaz']::text[], 8.5, '{"poet":"Nijat Ayvaz","poet_slug":"nijat-ayvaz","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/git-94-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Git', 'git-ayda-poyraz-3a6rq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İçime akıttığım 

Her bir damla gözyaşım

Minik çakı taşlarına dönüştü

Yanımdayken yoktun

Bu gerçek sandığımız bir düştü..

Şimdi sonsuza dek 

Gönderdim seni yüreğimden

Irak memleketlerin sahte dünyalarına..

Nasıl parçalanıyorum,

Anlatsam anlamazsın.

Çakıl taşları birleşip

Nasıl yaralıyorlar

Kulak ver seslerine desem,

Duymazsın.

Mutluyuz sanıyorsun

Görmezden geliyorsun,

Gerçekler önümüzde duvar olmuş

Enkazında kalacağız

Korkmuyor musun? 

Git artık,

Durma buralarda.

Gönderdim seni yüreğimden

Irak memleketlerin

Sahte dünyalarına...

Benim baharım küstü, güze döndü

Sen git,

Git başka baharlara...

04.01.1999 a.p.', 'İçime akıttığım  Her bir damla gözyaşım Minik çakı taşlarına dönüştü Yanımdayken yoktun Bu gerçek sandığımız bir düştü.. Şimdi sonsuza dek  ...', ARRAY['Türk Edebiyatı','Şiir','Ayda Poyraz']::text[], 8.5, '{"poet":"Ayda Poyraz","poet_slug":"ayda-poyraz","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/git-95-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeter', 'yeter-nijat-ayvaz-e4h9t', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sensizliğin acısı

Esti deli bir rüzgar bu gece

Kadehimi hasretin doldurdu

Kalbimi sıcaklığın.

Özletme yeter

Senle geçen en kötü anı.

Gel,

Gel yeter.

05.06.1994', 'Sensizliğin acısı Esti deli bir rüzgar bu gece Kadehimi hasretin doldurdu Kalbimi sıcaklığın. Özletme yeter Senle geçen en kötü anı. Gel, Ge...', ARRAY['Türk Edebiyatı','Şiir','Nijat Ayvaz']::text[], 8.5, '{"poet":"Nijat Ayvaz","poet_slug":"nijat-ayvaz","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yeter-33-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Gideli', 'sen-gideli-ahmet-mansuroglu-j2kc5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yok artık bülbüldeki eski şevk

Sen gittin o geçmez oldu bahçemizden

Güneş o güneş değil artık

Yıldızlar o yıldız değil

Ben bile ben değilim sen gideli

Ağardı saçlarım bir gecede

Sensizlikte kayboldu gençliğim

Bir gölgeyim şimdi yeryüzünde

Nasibim kalmadı, gecesinde gündüzünde

Senin yanında duymuştum kalbimin vurduğunu

Senden duymuştum ilk defa 

Yanaklarımın al al olduğunu

Şimdi ne kalbim vuruyor artık

Ne yanaklarım öyle al

Sen gideli

İşte böyle bendeki hal...

 Antakya - Hatay                      07.Nisan.1965', 'Yok artık bülbüldeki eski şevk Sen gittin o geçmez oldu bahçemizden Güneş o güneş değil artık Yıldızlar o yıldız değil Ben bile ben değilim ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Mansuroğlu']::text[], 8.5, '{"poet":"Ahmet Mansuroğlu","poet_slug":"ahmet-mansuroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sen-gideli-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölesim Geldi', 'olesim-geldi-ahmet-mansuroglu-zo6fy', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yokluk kurşun oldu sinemi deldi,

Akıbet ne olacak, bilesim geldi.

Gözlerimden akan sanki bir seldi,

Kader kahretti ölesim geldi.

Yazan öyle yazmış neylersin,

Bu kara yazıyı silesim geldi.

Umut fakirin ekmeğiymiş gülesim geldi,

Umudumu yitirdim ölesim geldi.

Yalan söylemedim, haram yemedim,

Vurguncuya sahtekara sövesim geldi.

Namerde asla aman demedim,

Onurum uğruna ölesim geldi

 Antakya - Hatay                  12.09.1982', 'Yokluk kurşun oldu sinemi deldi, Akıbet ne olacak, bilesim geldi. Gözlerimden akan sanki bir seldi, Kader kahretti ölesim geldi. Yazan öyle ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Mansuroğlu']::text[], 8.5, '{"poet":"Ahmet Mansuroğlu","poet_slug":"ahmet-mansuroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/olesim-geldi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayşe''ye', 'ayse-ye-ahmet-mansuroglu-1c7ry', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Mini miniydin ilkokulda

Siyah önlük beyaz yaka,

Aradan yıllar geçti

Değildir şaka

Tek ümidimizsin

Neyim var başka,

Bir sevinç var içimde tarifsiz,

Bir sevinç var bambaşka

Sen ondokuz yıllık emeksin,

Peri desem değil,

Sen bir meleksin

Tanrıdan istediğim dileksin,

İçimizde çarpan yüreksin,

Yuvamızda açan çiçeksin,

Senindir sevinç,

Senindir neşe,

Başarını yürekten kutlarım Ayşe.

 (Lise''yi bitirdiği yıl sevgili kızım Ayşe''ye) 

 Antakya -Hatay                          12. 06. 1984', 'Mini miniydin ilkokulda Siyah önlük beyaz yaka, Aradan yıllar geçti Değildir şaka Tek ümidimizsin Neyim var başka, Bir sevinç var içimde tar...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Mansuroğlu']::text[], 8.5, '{"poet":"Ahmet Mansuroğlu","poet_slug":"ahmet-mansuroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/ayse-ye-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yunus', 'yunus-ahmet-mansuroglu-8t4lp', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Tanrı ve insan sevgisi yüreğine işlemiş

Yunus herşeyi yaradan Allah demiş

Allah''ı sevmiş kendi sevgisini vermiş

Herkesin sevgilisi nur yüzlü derviş.

Ünü ülkeleri aşan büyük ozandır

Tanrı ve insan sevgisine eren insandır

Ümitsizlere ümit, yıkılmışlara candır

Yunus büyük düşünür ünlü ozandır.

 Antakya - Hatay            14. Haziran.1997', 'Tanrı ve insan sevgisi yüreğine işlemiş Yunus herşeyi yaradan Allah demiş Allah''ı sevmiş kendi sevgisini vermiş Herkesin sevgilisi nur yüzlü...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Mansuroğlu']::text[], 8.5, '{"poet":"Ahmet Mansuroğlu","poet_slug":"ahmet-mansuroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yunus-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dostlar ve Fareler', 'dostlar-ve-fareler-tevfik-karinca-mpv9f', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Giydim gariban hırkasını

Çeksem de hataların sancısını

Ölüm mü? kurtuluş

Bunca severken yaşamayı

Umutlar tükense de,zaman herşeye gebe

Deselerde kurtuluşun yok, nafile

Hızır yetişmez mi? zor günde

Batarken gemi önce fareler terkeder

Zor günde dostlar hani nerdeler

Yanıldım, inandım, kaybettim', 'Giydim gariban hırkasını Çeksem de hataların sancısını Ölüm mü? kurtuluş Bunca severken yaşamayı Umutlar tükense de,zaman herşeye gebe Desel...', ARRAY['Türk Edebiyatı','Şiir','Tevfik Karınca']::text[], 8.5, '{"poet":"Tevfik Karınca","poet_slug":"tevfik-karinca","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/dostlar-ve-fareler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşersen', 'dusersen-ali-akceken-z8cm9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Elim kanda olsa koşar gelirim

Bir haber sal yeter zora düşersen

Göklerce kar olur,yağmur olurum

Yağarım üstüne kora düşersen.

Yaprağın dökülür dal yalnız kalır

Mızrabın kırılır tel yalnız kalır

Ben oldukça korkma el yalnız kalır

İki say kendini bire düşersen.

Dostum,arkadaşım daha da çoğu

Sensin göbeğimin sanki tek bağı

Yediğim ekmeği,içtiyim suyu

Nem var paylaşırım dara düşersen.

Karagün kararıp kalmaz be gülüm

Çaresi olmayan tek sondur ölüm

Sabreyle isyankar olmasın dilin

Olur da yıkılıp yere düşersen.

Gelin ya nasip der binip atına

Kul alın yazısı ile yetine

Değersin dünyanın tüm servetine

Yanarım günaha,kire düşersen', 'Elim kanda olsa koşar gelirim Bir haber sal yeter zora düşersen Göklerce kar olur,yağmur olurum Yağarım üstüne kora düşersen. Yaprağın dökül...', ARRAY['Türk Edebiyatı','Şiir','Ali Akçeken']::text[], 8.5, '{"poet":"Ali Akçeken","poet_slug":"ali-akceken","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/dusersen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İmkansızların Esiri', 'i-mkansizlarin-esiri-erdem-nur-cengiz-1mq9w', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Biliyorum yine aldatıyorum kendimi

Sonu olmayan bir denizde

Bitmeyecek bir fırtınaya

Yelken açıyorum

Alamıyorum kendimi bundan

Ne yazık yine yeniğim

Olmuyor, engel olamıyorum

Ben imkansızların esiriyim.

9 Mart 1985 (bu durum bugün de böyle sürüp gitmekte)', 'Biliyorum yine aldatıyorum kendimi Sonu olmayan bir denizde Bitmeyecek bir fırtınaya Yelken açıyorum Alamıyorum kendimi bundan Ne yazık yine...', ARRAY['Türk Edebiyatı','Şiir','Erdem Nur Cengiz']::text[], 8.5, '{"poet":"Erdem Nur Cengiz","poet_slug":"erdem-nur-cengiz","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/imkansizlarin-esiri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeni Yıl', 'yeni-yil-mehmet-lutfu-aydin-it8pu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yeni yıl

Yeni umut

Havada bulut

Geçmişi unut

Yeni yıl 

Yeni bir şans

Yeni şans

Yeni bir aşk

Yeni aşk

Yeni bir mutluluk

Oh be! .. 

Yaşasın yeni hayat

Yeni yıl

Yeni Türk Lirası

Yeni lira

Yeni bir ilk

Yeni ilk

Yeni bir hayal

Yeni hayal

Yeni bir mutluluk

Oh be! ..

Yaşasın yeni hayal

…

Şans; hani, nerde? 

Talih kuşunun pisliğinde

Umut; hani, nerde? 

Umut tacirlerinde

Aşk; hani, nerde? 

Sevenlerin kalbinde

Mutluluk; hani, nerde? 

Kaf  dağının ardında

Ah ulan ah! ..

Nerde o eski yıllar…', 'Yeni yıl Yeni umut Havada bulut Geçmişi unut Yeni yıl  Yeni bir şans Yeni şans Yeni bir aşk Yeni aşk Yeni bir mutluluk Oh be! ..  Yaşasın ye...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Lütfü Aydın']::text[], 8.5, '{"poet":"Mehmet Lütfü Aydın","poet_slug":"mehmet-lutfu-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/yeni-yil-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gecebasan gibiydi', 'gecebasan-gibiydi-gencay-coskun-yfmn3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gecebasan gibiydi 

Dipsiz rüyalarım

Açık bir pencereden 

Hemen içeri dolarlardı 

Haşarı yaramaz çocuklar 

Gibi ortada dolanır 

Gitmek bilmezlerdi 

Sıkılganlık duvarlarımdan 

İnsan bildiğim en içime doğru 

Kanlarım akardı

Canım çok acırdı 

Gözlerim dolardı 

Ağlayamazdım 

Her yerde ten avcıları vardı 

İliklerine kadar günah kokarlardı 

Umursamazlık 

Vurdumduymazlık gülüşlerinde 

Bir çamı tam ortasından devirirlerdi 

Ellerimde cam kırıkları 

Umutlarım kırılması gibi 

Yüreğime batardı 

Karanlığa bulaşmış 

İs kalmış geleceğimin yollarında 

Geleceğe gidiş 

Tek şeritten kontrollü olarak gidilirdi 

Umudun kış mevsiminde 

Tüm köy yolları kapalıydı 

Gecebasan çok soğuktu

Üşürdü içim 

Sokak lambalarına 

Yüreğimi uzatarak 

Isınmaya çalışırdım

Isınabildiğim kadar 

Dost sesi arardım 

Ansızın baskınlarda insan 

Bulabildiğim dost yerine birkaç resim 

Birde ekonominin

Kirlettiği dünyadan 

Arta kalan kırıntılardan 

Başka bir şey değildi 

Yalnızlıklarda

Yüreğe yapılan 

Baskınlar ağırdı 

Hüzün çiçeğimi solduran 

Geleceğimi öldüren 

Gecebasanlar

Acı olsa

Değişmez tek gerçeğimdi', 'Gecebasan gibiydi  Dipsiz rüyalarım Açık bir pencereden  Hemen içeri dolarlardı  Haşarı yaramaz çocuklar  Gibi ortada dolanır  Gitmek bilmez...', ARRAY['Türk Edebiyatı','Şiir','Gencay Coşkun']::text[], 8.5, '{"poet":"Gencay Coşkun","poet_slug":"gencay-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/gecebasan-gibiydi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Günah olmasaydı intihar', 'gunah-olmasaydi-intihar-gencay-coskun-lg30c', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Günah olmasaydı intihar 

Kaç tane iyi yürek kalabilirdi bu dünyada 

Çekip gitmek en doğrusuydu aslında 

Yüreksizlik değildi kaçmak 

Sadece yalan sanallığı 

Heveslilerine bırakabilme cesaretiydi 

Günah olmasaydı 

Gidilecek yol çoktan gidilirdi 

Gösterilecek cesaret çoktan gösterilirdi 

Yaşamaya 

Bu kirlilikte 

İstemeden gönüllüyüz 

Bir zincirin son halkaları gibi 

Sımsıkı bağlıydık geçmişe 

Yaratana en büyük borcumuz 

Sabırdan bir köprüden geçmekti 

Onu da geçecektik bir solukta 

Beklemesi sinir ediyordu insanı sadece 

Bu yalana 

Bu düzene 

Pisliklere küfür etmenin adını 

Günah koyuyorlardı 

İçimden edebildiğimden kadar ediyordum 

Büyük harflerle 

Tartının asla yalanı yoktu 

Benimde kendimden korkum yoktu 

Dosdoğru bir adamdım 

Günahsızlığı özledim 

Hepsi bu', 'Günah olmasaydı intihar  Kaç tane iyi yürek kalabilirdi bu dünyada  Çekip gitmek en doğrusuydu aslında  Yüreksizlik değildi kaçmak  Sadece y...', ARRAY['Türk Edebiyatı','Şiir','Gencay Coşkun']::text[], 8.5, '{"poet":"Gencay Coşkun","poet_slug":"gencay-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/gunah-olmasaydi-intihar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi', 'sevgi-murat-karatekin-8njl2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sekiz basamak

Dokuz basamak

Bir ara boşluk 

Merdiven sonunda

Soluklanmak ve duraksamak...

Bir güzel bakış

Alın alına,burun buruna

Devamı bir heyecan,

Sonsuz bir karmaşa ve mutlulukla

Kenetlenmek ansızın ve arzuyla

Çözülmekse; 

Bir akrep ve yelkovanla

Bir de kapı gıcırtısıyla mümkün

Bu akışta...

Bitmesin istedik,

Böyle kalsak diye düşündük sevgiyle

Bir kapı gıcırtısı ve bir ışık hüzmesi

Teslim aldı ikimizide.

Ne demeli bilmem bu garip geceye

Dudaklarımda dudağının izi kalmışken

Sonsuz bir Sevgiyle...

MK...(Seni Seviyorum...) 

31/12/2005 - 02:44

Bir bina, bir merdiven boşluğu

Bir ben ve Tarifsiz bir güzellik...', 'Sekiz basamak Dokuz basamak Bir ara boşluk  Merdiven sonunda Soluklanmak ve duraksamak... Bir güzel bakış Alın alına,burun buruna Devamı bir...', ARRAY['Türk Edebiyatı','Şiir','Murat Karatekin']::text[], 8.5, '{"poet":"Murat Karatekin","poet_slug":"murat-karatekin","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/sevgi-158-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayalimsin', 'hayalimsin-yavuz-agir-cl1kf', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sensiz günlerim geçmiyor,

Solan güllerim açmıyor.

Yıldızlara seni sordum.

Bade sensiz içilmiyor...

Gece gündüz hayalimsin.

Rüyalarımda gonca gülümsün.

Sen benim sırdaşım,canımsın.

Bade sensiz içilmiyor...

Gönül şarkıları dinlerim

Muziki ile meşk eylerim.

Şarkılara seni söylerim

Bade sensiz içilmiyor....', 'Sensiz günlerim geçmiyor, Solan güllerim açmıyor. Yıldızlara seni sordum. Bade sensiz içilmiyor... Gece gündüz hayalimsin. Rüyalarımda gonca...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Ağır']::text[], 8.5, '{"poet":"Yavuz Ağır","poet_slug":"yavuz-agir","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hayalimsin-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '**Mutluluklar Yarına Ertelenmesin', 'mutluluklar-yarina-ertelenmesin-nurten-altinok-p261h', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'zaman dar

zaman acımasız 

yürekte ayaz bir sevda

özlemi duyulan ve unutulan

heyecanlarımız / gençliğe dair

yedi yamalı bohça gibi gecelerde

karabasan yalnızlığımız

sessiziz

bir o kadar aceleci yürek

bir o kadar SUsuyoruz

zaman dar

zaman acımasız

farkındayız

zor olmamalı 

yeni anın zamanını yakalamak

varsa bir sen yaşayan sen’de

ve o sen ’de sevda kırıntıları

çoktan tükendi sokak satıcıları

kendi aşını kendin yapma zamanı

bir gül sun 

sonsuzluğa

hedefini bulsun...

not:   Thusanami şiirine ithafen yazılmıştır.  Teşekkürler sayın Oğuzkan Bölükbaşı', 'zaman dar zaman acımasız  yürekte ayaz bir sevda özlemi duyulan ve unutulan heyecanlarımız / gençliğe dair yedi yamalı bohça gibi gecelerde ...', ARRAY['Türk Edebiyatı','Şiir','Nurten Altınok']::text[], 8.5, '{"poet":"Nurten Altınok","poet_slug":"nurten-altinok","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/mutluluklar-yarina-ertelenmesin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Garip Babam', 'garip-babam-i-shak-ozlu-bwf0d', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yigit babam.dün seni düşündüm yine,

Bizleri bırakıp gittin ya gayp alemine,

Neler oldu söyleyim mi malına? 

İbret olur belki, ders alan zengine.

Miras payı için toplandık bir bir,

Herkes saatlerce konuştu dır dır,

Ev''de tamam diyen,dışarıda etti hır gür,

Görmeliydin kopan bagları bir bir.

Günler ayları,aylar yılları kovaladı,

Nifak tohumları boy verip dal oldu.

Konuşan kardeşler konuşmaz,

Görüşenler buluşmaz oldu.

Sen gideli tam dokuz yıl oldu.

Bu ayrı gayrılarda sekiz yıl doldu.

Gözün gibi sevdigin sulak tarlayı,

Hiç acımadan verdik Kürdün Amede.

Komşumuz Tot Osman bahçe duvarını yıkmış,

Hayvanlarını bizim bahçede otlatır olmuş.,

Çeşmenin muslugunu söküp almış,

Yerinede takoz niyetine bir odun çakmış.

Evin Dam''ında rüzgardan toprak azalmış,

Yıllardır Yuvak taşı yerinden oynamamış,

Biraz eşelesen  hasır görünür olmuş,

Ev evlikten çıkmış,hayatta kalmaya çalışır.

Ahır''ın köşeside yıkılmaya yüz tutmuş,

Temeli kal,Dam''ı gidelim demiş.

Kapılar komşunun sobasında odun olmuş,

Tencere,Kazan çoktaaan yerini bulmuş.

Çocuklar babaocag''ını merak eder diye,

Gitmez ya belki biri ziyarete gider diye,

Düşündük taşındık ev anı''dır yaşasın diye,

Ev''ide sattık Hasançocugun Eşe''ye.

İnek,Koyun ne oldu bilemiyorum.

Dokuz yıldır mezarınada gelemiyorum.

Büyük kızın Sebahat ayrıldı aramızdan,

Kalanlarda yaprak gibi orda burda.

Sen nasılsın oralarda,belki kızıyorsun,

Kızma baba,mal bizimmi ki bizde dursun,

Bekçiligini sen yaptın,parasını biz yedik.

Şimdide Asaf aga oyalanıyor biraz.

En sona anamı bıraktım,merak ediyorsan,

Korkma yanımızda,duruyor başımızda.

Bundan haberi olaydı selam dermiydi bilmem,

Dünyalar iyisi,babalar babası garip babam.', 'Yigit babam.dün seni düşündüm yine, Bizleri bırakıp gittin ya gayp alemine, Neler oldu söyleyim mi malına?  İbret olur belki, ders alan zeng...', ARRAY['Türk Edebiyatı','Şiir','İshak Özlü']::text[], 8.5, '{"poet":"İshak Özlü","poet_slug":"i-shak-ozlu","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/garip-babam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülde Damla', 'gulde-damla-soner-evran-sg1lp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'geceleri bulutlardayım

gündüzleri gülde damla

sen bana susamışsın

ben sana

süzülüyorum

yaprağından içeri

berrakken 

kırmızı oluyorum

mutluyum tenine değeli

(06 11 2002)', 'geceleri bulutlardayım gündüzleri gülde damla sen bana susamışsın ben sana süzülüyorum yaprağından içeri berrakken  kırmızı oluyorum mutluyu...', ARRAY['Türk Edebiyatı','Şiir','Soner Evran']::text[], 8.5, '{"poet":"Soner Evran","poet_slug":"soner-evran","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/gulde-damla-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Kaybettim Biliyorum', 'seni-kaybettim-biliyorum-erdem-nur-cengiz-gijbm', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Seni kaybettim biliyorum

Sana ulaşmaya çabalamayacağım

Sonsuza dek sürecek ayrılığımız

Ben seni sadece içimde yaşayacağım

Aramızda bir uçurum

Kapatılması mümkün olmayan

Yaşamımız ısırgan otuyla

Bir gelincik zıtlaşan

Seni kaybettim biliyorum

Artık yalnızca büyük amaçlardır

Başarılmış, göz kamaştıran

Senin yanında, sana ulaşan

Bense anı defterinde bir belirsiz nokta

Ardından ışıltılı bir yaşam başlayan

21 Eylül 1987 (İyi bir kehanetti, tuttu)  :)', 'Seni kaybettim biliyorum Sana ulaşmaya çabalamayacağım Sonsuza dek sürecek ayrılığımız Ben seni sadece içimde yaşayacağım Aramızda bir uçuru...', ARRAY['Türk Edebiyatı','Şiir','Erdem Nur Cengiz']::text[], 8.5, '{"poet":"Erdem Nur Cengiz","poet_slug":"erdem-nur-cengiz","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/seni-kaybettim-biliyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Z+/ 01 ÖZLÜ SÖZ/ Bugünün Küçüğü /Çocuk Şiirleri', 'z-01-ozlu-soz-bugunun-kucugu-cocuk-siirleri-fevzi-gunenc-2aniy', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '''Bugünün küçüğü

yarının büyüğüdür''

demiş büyük Atatürk''üm

bunu öğrendim önce...

Ona layık olmak için

büyük adam olacağım

ben de büyüyünce!', '''Bugünün küçüğü yarının büyüğüdür'' demiş büyük Atatürk''üm bunu öğrendim önce... Ona layık olmak için büyük adam olacağım ben de büyüyünce!...', ARRAY['Türk Edebiyatı','Şiir','Fevzi Günenç']::text[], 8.5, '{"poet":"Fevzi Günenç","poet_slug":"fevzi-gunenc","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/z-01-ozlu-soz-bugunun-kucugu-cocuk-siirleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fikrime', 'fikrime-bekir-mutlu-gokcesu-b29z7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gecenin gardiyan zamanları

Örüyorlar hızla

Hücremin taşlarını

Şahiti sen

Hakimi sensin

Bir boşluk aramamın

Manası yok

Maddelerinde gecenin

Artık 

Aldığım nefesin derinliği

Bakışım, duruşum

Hatta ölüşüm bile

Delil aleyhime

Ne duruyorsun

Taksana kelepçeyi

Fikrime...

Bir suçlu lazım zaten

Bu kara gecelere...', 'Gecenin gardiyan zamanları Örüyorlar hızla Hücremin taşlarını Şahiti sen Hakimi sensin Bir boşluk aramamın Manası yok Maddelerinde gecenin A...', ARRAY['Türk Edebiyatı','Şiir','Bekir Mutlu Gökçesu']::text[], 8.5, '{"poet":"Bekir Mutlu Gökçesu","poet_slug":"bekir-mutlu-gokcesu","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/fikrime-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Z+/ 02 ÖZLÜ SÖZ/ Övün çalış/ Çocuk Şiirleri', 'z-02-ozlu-soz-ovun-calis-cocuk-siirleri-fevzi-gunenc-y9g9b', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '''Türk

     övün, 

          çalış,

               güven! ..

demiş büyük Atatürk''üm.

İlkin güveneceğim kendime

çalışacağım 

gece gündüz demeden...

Sanırım o da böyle isterdi

bundan sonra 

övüneceğim anca.

Nasıl öğünebilirim

değil mi ama

öğünmeye layık olmayınca? ..', '''Türk      övün,            çalış,                güven! .. demiş büyük Atatürk''üm. İlkin güveneceğim kendime çalışacağım  gece gündüz demed...', ARRAY['Türk Edebiyatı','Şiir','Fevzi Günenç']::text[], 8.5, '{"poet":"Fevzi Günenç","poet_slug":"fevzi-gunenc","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/z-02-ozlu-soz-ovun-calis-cocuk-siirleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hazan Olur Geceleri Gurbetin', 'hazan-olur-geceleri-gurbetin-semanur-dilek-l1a0y', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hasretinle yüregimi daglarsın

Umudunu vuslatlara baglarsın

Çok kereler uykusuz sabahlarsın

Hazan olur geceleri gurbetin

Göz yasın sel gibi akar dökülür

Öksüz çocuk gibi buynun bükülür

Bayramlarda yollarına bakılır

Hazan olur geceleri gurbetin

Bir selam beklersin belki bir mektup

Eş dost arar sorar zannedip umup

Dersin unutanı sen dahi unut

Hazan olur geceleri gurbetin

Hasret çeker sılanın bagrına

Özlem eker kalbinin topragına,

Umudunu erteler hep yarına,

Hazan olur geceleri gurbetin

Kimseler paylaşmaz yalnızlıgını

Kalbini kanatan derin sızını

Deryalar kandırmaz susuzlugunu

Hazan olur geceleri gurbetin

Can evinde bir kor her daim yanar

DİVANE  yüreğin her daim kanar

Kalbin taa derinden sılayı anar

Hazan olur geceleri gurbetin', 'Hasretinle yüregimi daglarsın Umudunu vuslatlara baglarsın Çok kereler uykusuz sabahlarsın Hazan olur geceleri gurbetin Göz yasın sel gibi a...', ARRAY['Türk Edebiyatı','Şiir','Semanur Dilek']::text[], 8.5, '{"poet":"Semanur Dilek","poet_slug":"semanur-dilek","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/hazan-olur-geceleri-gurbetin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mavi Çağrı', 'mavi-cagri-aydan-yalcin-0np5b', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir mavi çağrım var aşktan yana

özlemin okyanusum oldu

boğuluyorum...

yaz aktı buralara güllerim sevda ister

gökyüzüne maviler taşımak istiyorum...

yıkılası yokluğundayım artık

aşk yoksunuyum

kalbimde yanar güllerim

gözbebeklerini hançerleyip kalbime

aksın uykularıma ıslak öpüşlerin...

bir mavi çağrım var senden yana

ay alnından öper oldu yakamozların

gelirsen! 

deniz dolacak köpüklerine zamanın

gelmezsen! 

asılı kalacak aşk

en olmayacak yerinde zamanın....', 'Bir mavi çağrım var aşktan yana özlemin okyanusum oldu boğuluyorum... yaz aktı buralara güllerim sevda ister gökyüzüne maviler taşımak istiy...', ARRAY['Türk Edebiyatı','Şiir','Aydan Yalçın']::text[], 8.5, '{"poet":"Aydan Yalçın","poet_slug":"aydan-yalcin","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/mavi-cagri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pusulamız ruhlarımız', 'pusulamiz-ruhlarimiz-i-brahim-duskun-5xfrq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'çalan bir geminin sirenleridir

hazırlık tamam yol vaktidir

yaşam tutkusu olunca deniz

okyanuslara yelken yüreklerimiz

korkusuzca açılır gideriz

ne yönleri ne dilleri biliriz

pusulamız ruhlarımız

umudun oluş öyküsüdür bu

elbet bir gün biri döner

gün doğar devran döner

belirince ufukta beklenen gemi 

dünyalar bizim olur

yürek fethimiz gelir', 'çalan bir geminin sirenleridir hazırlık tamam yol vaktidir yaşam tutkusu olunca deniz okyanuslara yelken yüreklerimiz korkusuzca açılır gide...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Düşkün']::text[], 8.5, '{"poet":"İbrahim Düşkün","poet_slug":"i-brahim-duskun","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/pusulamiz-ruhlarimiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senden Başka Yar Sevdiysen', 'senden-baska-yar-sevdiysen-semanur-dilek-0wxy6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sür çıkar beni cennetten

Senden başka yar sevdiysem

İster uzak et rahmetten

Senden başka yar sevdiysen

Türlü bela sar başıma

Merhamet etme yaşıma

Dilersen at ateşine

Senden başka yar sevdiysem

Kabrimde rahat yatırma

Affetme kul hatırına

Yardım eyleme sıratta

Senden başka yar sevdiysem

Kalmasın yeşil yapragım

Hasretin çeksin topragım

Bulmayayım aradıgım

senden başka yer sevdiysem

Kara günüm ak olmasın

Az sevincim çok olmasın

Hayalim gerçek olmasın,

Senden başka yar sevdiysem

Yolum menzile gitmesin

Aglayan yüzüm gülmesin

Ahmet(a.s)  şefaat etmesin

Senden başka yar seversem', 'Sür çıkar beni cennetten Senden başka yar sevdiysem İster uzak et rahmetten Senden başka yar sevdiysen Türlü bela sar başıma Merhamet etme y...', ARRAY['Türk Edebiyatı','Şiir','Semanur Dilek']::text[], 8.5, '{"poet":"Semanur Dilek","poet_slug":"semanur-dilek","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/senden-baska-yar-sevdiysen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çok Yaktı Canımı Dinsiz İmansız', 'cok-yakti-canimi-dinsiz-i-mansiz-semanur-dilek-rw65e', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Düz yolda yürürken yere kapanır

Göremez önünü gözsüz, izansız

Asi nevsin hevesine kapılır 

Çok yaktı canımı dinsiz imansız

Harami misali kesti yolumu 

Gocayken dalımdan yoldu gülümü

Kara etti bana mesut günümü

Çok yaktı canımı dinsiz imansız

Dilerim onunda kurusun dalı

açmadan çürüsün gönlünün gülü

Mevla reva görsün en kötü sünü

Çok yaktı canımı dinsiz imansız

Ne zaman affedip bassam bağrıma

Türlü hile tuzak kurdu yoluma

Zehirli hançeri vurdu sırtıma

Çok yaktı canımı dinsiz imansız

Hakkı inkar eden dili lal olsun,

Canı av avcısı Azrail olsun

Her güzel muradı karnında kalsın,

Çok yaktı canımı dinsiz imansız

Dost sandım düşmanmış domuzun dölü

Başına yıkılsın evinin damı

Bencileyin onunda yansın canı

Çok yaktı canımı dinsiz imansız', 'Düz yolda yürürken yere kapanır Göremez önünü gözsüz, izansız Asi nevsin hevesine kapılır  Çok yaktı canımı dinsiz imansız Harami misali kes...', ARRAY['Türk Edebiyatı','Şiir','Semanur Dilek']::text[], 8.5, '{"poet":"Semanur Dilek","poet_slug":"semanur-dilek","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/cok-yakti-canimi-dinsiz-imansiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Z+/03 ÖZLÜ SÖZ/ Ne mutlu /Çocuk Şiirleri', 'z-03-ozlu-soz-ne-mutlu-cocuk-siirleri-fevzi-gunenc-xpfjc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '''Ne mutlu Türküm, diyene! ''

demiş büyük Atatürk''üm.

Mutluluğumu duyururum hep

elbette Türküm, diyerek...

ama biliyorum o da böyle isterdi

önce ''insan'' olmam gerek.', '''Ne mutlu Türküm, diyene! '' demiş büyük Atatürk''üm. Mutluluğumu duyururum hep elbette Türküm, diyerek... ama biliyorum o da böyle isterdi ön...', ARRAY['Türk Edebiyatı','Şiir','Fevzi Günenç']::text[], 8.5, '{"poet":"Fevzi Günenç","poet_slug":"fevzi-gunenc","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/z-03-ozlu-soz-ne-mutlu-cocuk-siirleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yol Kaygısı Taşıyorum', 'yol-kaygisi-tasiyorum-zulfikar-yapar-kaleli-myf7w', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'font face=''Comic Sans MS'' color=''black'' size=''0,5''

Gözümde nur, gökte ismin 

Gönlümde hayalin, resmin 

Yağmur gözlüm yerde cismin! 

Yara derin kaşıyorum 

Kaşıdıkça şaşıyorum! 

Yorgun yolun neresiyim 

İlk umudun töresiyim 

Kuru sevdanın sesiyim 

Kör talihi boşuyorum 

Boşadıkça coşuyorum! 

“Çıkmak kolay”demek kolay 

Karşılıksız emek kolay 

Bedavadan yemek kolay 

Övüyorlar şişiyorum 

Yanıyorum, pişiyorum! 

Kırıldı sürgünüm dalım 

Bağlı işte elim kolum 

Gelinmeze doğru yolum 

Tepeleri aşıyorum 

Yıldızlara koşuyorum! 

Yüksekten bakan sözünü 

Destursuz çıkan sözünü 

Özledim yakan sözünü 

Çıban başı deşiyorum 

Mezarını eşiyorum! 

Ben beni yere vurmuşum 

Boğazlanmış gönül kuşum 

Dalanlarla oturmuşum 

Sohbet soğuk üşüyorum 

Üşüdükçe düşüyorum! 

Kilit vurulu dilime 

Yaş gözümde lime lime 

Yetir beni sevgilime 

Yol kaygısı taşıyorum, 

Yaşamaksa, yaşıyorum!', 'font face=''Comic Sans MS'' color=''black'' size=''0,5'' Gözümde nur, gökte ismin  Gönlümde hayalin, resmin  Yağmur gözlüm yerde cismin!  Yara der...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/yol-kaygisi-tasiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'A - 05 Aç Yüreğim Kendini', 'a-05-ac-yuregim-kendini-nilgun-yuce-uxziu', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yıllarca, 

Örtsen de üzerini,

Aslında, 

Sevgi senin hasretindi.

Belki,

Vaktidir şimdi.

Haydi,

Aç yüreğim kendini,

Yeniden, 

Dünya''ya gelir gibi.

O İlk haykırış,

O İlk nefes gibi,

Kirletmeden rengini,

Temiz tertemiz, 

Duru su gibi.

Bulursan sevgiyi,

Haydi, 

Aç yüreğim kendini,

Belki,

Zamanıdır şimdi.', 'Yıllarca,  Örtsen de üzerini, Aslında,  Sevgi senin hasretindi. Belki, Vaktidir şimdi. Haydi, Aç yüreğim kendini, Yeniden,  Dünya''ya gelir g...', ARRAY['Türk Edebiyatı','Şiir','Nilgün Yüce']::text[], 8.5, '{"poet":"Nilgün Yüce","poet_slug":"nilgun-yuce","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/a-05-ac-yuregim-kendini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Lades', 'lades-i-brahim-elciboga-54172', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Aceledeyken büyümeye,

başımın üstünden atılan çentikler gibi

Uzadıkça uzuyor

Senli benli olduğum

Dokunulmazlığının boyu

Şikayet etmiyor

Ümitli bir heyecan taşıyor

çantasında postacı

Sabırla beklenen bir lades heyecanı.

Çıkmanı bekliyor kapında

Diyebilmek için “hep aklımdasın”. 

                                                                (2005-01- 03 İstanbul)', 'Aceledeyken büyümeye, başımın üstünden atılan çentikler gibi Uzadıkça uzuyor Senli benli olduğum Dokunulmazlığının boyu Şikayet etmiyor Ümit...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Elçiboğa']::text[], 8.5, '{"poet":"İbrahim Elçiboğa","poet_slug":"i-brahim-elciboga","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/lades-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Görseydin Atam', 'gorseydin-atam-nuri-celik-qzkj1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Adalet kavramı tükenip gitti

Arı,kuş ve çakal,bak öne geçti

Soysuzlar arsızlar ne haltlar etti

Bu günleri keşke görseydin ATAM.

Birliğe kurşun da sıkılır oldu

Düşmana kapılar açılır oldu

Hırsıza hapis de,lüks otel oldu

Mazlumun halini görseydin ATAM.

Ekmeği su ile biz katık yaptık

Sanma dünya ile savaşa çıktık

Beşyüz ellisini doyuramadık 

Açların halini görseydin ATAM.

TL''den geçilip,dolar istenir.

Devletin bütçesi talan edilir,

Doğmamış sabi''ye kefen biçilir,

Şu acayip hali görseydin ATAM.

Gençliğe hitabın hala aklımda

Bir parya olmuşum kendi yurdumda

Hayırmı var şer’mi,bilmem sonunda

Yurdumun halini görseydin ATAM.

                28-11-1999', 'Adalet kavramı tükenip gitti Arı,kuş ve çakal,bak öne geçti Soysuzlar arsızlar ne haltlar etti Bu günleri keşke görseydin ATAM. Birliğe kurş...', ARRAY['Türk Edebiyatı','Şiir','Nuri Çelik']::text[], 8.5, '{"poet":"Nuri Çelik","poet_slug":"nuri-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/gorseydin-atam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oda bendim', 'oda-bendim-tayfun-yilmaz-yqvji', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'umudunu yitirmiş bir garip gördüm

belkide acınacak bir halde degildi

yorgundu argındı anlıyordum halinden

dünyada ümitsiz tek inasan o degildi biliyordum

her nedense bakmadı bile yüzüme

sanki kaçıyordu birşeylerden

yaklaştım yanına soracaktım tam

birden başını kaldırdı bana baktı

anladım sorma diyordu bana bir şey

zaten sormamada gerek yoktu

belliydi halinden

ama merak ettim

nedir dedim senin adın

baktı baktı durdu yüzüme

cevap bekliyordum belliki

hiç bir cavap vermedi bana

ilk önce derinden bir nefes aldı

konuşacak zannettim bekledim

sonra başını yine öne egdi

öylece kapandı köşesinde

düşündüm

dünyada tek çaresiz insan omuydu sanki

belliki o kendini öyle görüyordu

ama bilmedigi bir şey vardı

onun gibi çaresiz ümitsiz

biri daha vardı

oda bendim...

                 (9 ocak 1998 cuma)  yalancı sevdalara', 'umudunu yitirmiş bir garip gördüm belkide acınacak bir halde degildi yorgundu argındı anlıyordum halinden dünyada ümitsiz tek inasan o degil...', ARRAY['Türk Edebiyatı','Şiir','Tayfun Yılmaz']::text[], 8.5, '{"poet":"Tayfun Yılmaz","poet_slug":"tayfun-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/oda-bendim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Argo', 'argo-alim-vedat-suner-0i9kc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'pirensiplerime martılar sçtı...

amorti tuttu 1 tane..

kovaladılar kaçtım hep

bir kerane vitrini oldu dünya

ben en güzel fahişeydim 

aynalara bakarken', 'pirensiplerime martılar sçtı... amorti tuttu 1 tane.. kovaladılar kaçtım hep bir kerane vitrini oldu dünya ben en güzel fahişeydim  aynalara...', ARRAY['Türk Edebiyatı','Şiir','Alim Vedat Süner']::text[], 8.5, '{"poet":"Alim Vedat Süner","poet_slug":"alim-vedat-suner","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/argo-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Bahçe Çiz', 'bir-bahce-ciz-meral-vurgun-i1enj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'bir vaha masalıydın sen

çöllerimi yeşile boyayan

ve beni sana öldüren

yine sende cana getiren

öykümüzün adı hasretti

beni sana, seni bana yetiren

kim bilir

yaşamak güneşi kucaklamaksa eğer

belki de ölüm 

bulutlara kanat vurup düşmesidir kuşların

ya da ses düşümü damardaki kanın

silindiğinde gökyüzünden adımız

çocuklar oynar belki de bizi, kim bilir

bir bahçe çiz göz ucuna

sonra bir rüzgar bulutları aralayan

bir yavru ceylan düşün çöl ortasında 

bakışını doruklara çevir sonra

beni hayalle seni beklerken

umudu ihanete vuranlara inat

tükür yüzüne kirli zamanların

bir şiir kopar yüreğinden 

bir kızıl gül gibi aç sonra bana

içli bir türkü dolansın diline

sesini sesime kat sevgilim

baktığın aynalardan sök al aks’imi

bakışın gözlerimde yansın

bilirsin...

neler konuştuk, neler sustuk seninle

öpüştükçe düşlerimiz ücralarında aklın

nasıl tutuştuk yandık, nasıl kor tuttuk

çözebilmek, saklamak olası değil bu sırrı 

öyle onulmaz bir aşkın koynuna düştük ki

bir çoğaldık, bin azaldık seninle...', 'bir vaha masalıydın sen çöllerimi yeşile boyayan ve beni sana öldüren yine sende cana getiren öykümüzün adı hasretti beni sana, seni bana ye...', ARRAY['Türk Edebiyatı','Şiir','Meral Vurgun']::text[], 8.5, '{"poet":"Meral Vurgun","poet_slug":"meral-vurgun","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/bir-bahce-ciz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kır', 'kir-yasar-dogan-bepnq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kapıyı pencereyi

Sokak kapısını

Sokağı / lambayı

Soluğu kır

Gözyaşlarını

Hıçkırığını 

Otur da

Kalbimde 

Kalbini kır

Tut kıvır

Kıtır kıtır

Çığlığını 

Sancımda

Sancını kır

Ayrılığı

Yalnızlığı

Bağnazlığı 

Yobazlığı 

Sırtımda  kır 

Dişleri

Şişleri

Endişeleri

Gözlerimde

Gözlerini kır

Kanı suyu

Havayı bulutu

Acıyı umudu

Hududu kır

Meydanı ateşe vermeden

Tut bir çay bir sığara içelim

Bir halay çekelim 

Her şeyden önce

Avazı ayazı

Ayı yıldızı

Sonra sazı cümbüşü

Türkümde türkünü kır

Bırak ıvır zıvırı

Tut beni kır

Kanadımı 

Kırlangıcımı kır

Tut

Kır kubbenin pulunu

Her şey

Yeni bir inşa

Yeni bir teşebbüs olsun

Haydi

Her şey fıkır fıkır

Her şey ıtır ıtır

Kırıklardan fışkırıp

Yeniden ayaklansın

Buğulanmasın bir daha

Göz bebeklerimizin aynası

Sınırlar ve sınıflar

Karartmasın hülyamızı

Haydi

Hala ne bekliyorsun

Kır kirini bu dünyanın

Yeni bir gün

Yeni bir evren parlasın

Haydi Kıvır

Dansımızın adı

Her yerde her kese

Mutluluk olsun

Sonra öpeyim anlından

Her kesin elinde yüreğinde

Horhor bir mutluluk olsun

Sonra

Kırık kelimesini

Çıkaralım bütün sözlüklerden

Yaşar Doğan	/ Lolan		3/01/05', 'Kapıyı pencereyi Sokak kapısını Sokağı / lambayı Soluğu kır Gözyaşlarını Hıçkırığını  Otur da Kalbimde  Kalbini kır Tut kıvır Kıtır kıtır Çı...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Doğan']::text[], 8.5, '{"poet":"Yaşar Doğan","poet_slug":"yasar-dogan","theme":"Türk Şiiri","is_hero":false,"total_lines":70,"source_url":"https://www.antoloji.com/kir-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tablolar', 'tablolar-mehmet-sogut-ntdoy', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '1

Eprimiş bedenimle geliyorum kıyısına kuyuların

Sularında tinime nergisler taşıyarak

Ve her gün ellerimi kanatarak

Buğulu rızıklar taşıyorum

Ey yabancısı olduğum inim

Ellerim batık gemi ağıdı

Gözlerimin derinliğinde ölen canlarım

Uçmak ister ak güvercin

Ellerim emeğimle barışmak

Tutanağını tutuyorum hicran zamanının

Her şey boz bulanık

2

Batık gemi ağıdına benzerdi babanın elleri

Gül bitesi nasırlı elleri hayrına

Katık ettin ömrünü

Ürkek cerenler gibi susan aç çocukları ülkemin

Yılan gibi tıslıyan cellatların zulmünden tırsmadın

Bindin direniş atına ve çıktın şaha

Yüce olana semahlar yakışır.

Heyhat ne matrak şey şu zulüm katarı

Dünyayı verilmiş armağandın tüm armağanlara

Ellerinle gülücükler dağıttın.

3

Hırsız zalim esrar, eroinden kararmış

Faili meçhul cinayetler oy de yar

Böylece elleri ikiye ayırıyorum

Dost ve düşman

Baktıkça ellerime onlar o pis zehirlerini

Kusadursunlar işim aşkım

Aşkımı büyütüyorum dağlar kadar

Ellerim, ellerim gülü seçti.', '1 Eprimiş bedenimle geliyorum kıyısına kuyuların Sularında tinime nergisler taşıyarak Ve her gün ellerimi kanatarak Buğulu rızıklar taşıyoru...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Söğüt']::text[], 8.5, '{"poet":"Mehmet Söğüt","poet_slug":"mehmet-sogut","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/tablolar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cinayet', 'cinayet-poyraz-alkin-uxmlg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kadının ötesi kadın, diğerlerine benzeyerek

Çoğalma umudunu yitirmiş, çöreklendiği toprağa kederlenerek

Cinsini hatırlasa varlığını yadırgamayacak

Nafile bu dünyada daha fazla yer kaplamayacak

Uydurulmuş bir hayat kim inansa üstüne kalacak

Yanına yöresine bulaşmadan geçtik, belleğimizde adı yok

Bir adam, lacivert hırkası, uzun sakalı

Ağzından midesine kadar sigara dumanı

Başının üstü milyonlarca yıldız yürüyor

Aynı çoklukta bir başına 

Ve müthiş derecede kızarmış yüzüyle 

Göreceği ilk kadını boğazlamasını bekliyoruz

Ama bulaşmadan, ne olur ne olmaz yüzünü anımsamadan

İlk ayrımda kendi yolumuza gidiyoruz, cebimizde adı yok

Kadın adama yanaşıyor

Adamın yüzünün kızarıklığı kadından toprağa boşalıyor

Resmi bir plakaya havale teknik bir sorun yadırgamıyoruz 

İki bilinmeyeni olmasa bu dünyanın

Neye yarar şu yaşamak dediğimiz işkence 

Üstü kalsın istemiyoruz', 'Kadının ötesi kadın, diğerlerine benzeyerek Çoğalma umudunu yitirmiş, çöreklendiği toprağa kederlenerek Cinsini hatırlasa varlığını yadırgam...', ARRAY['Türk Edebiyatı','Şiir','Poyraz Alkın']::text[], 8.5, '{"poet":"Poyraz Alkın","poet_slug":"poyraz-alkin","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/cinayet-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acar Gelin', 'acar-gelin-yavuz-agir-ukgni', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yar; boynun bükük kalmasın.

Aklın uzaklara dalmasın.

Hasretlik zor şeydir bilirim,

Gözün yaşlı,gönlün buruk olmasın.

Annen de senin gibi,gelin olmuştu

Diyarı gurbette,sararıp solmuştu.

Yaşamanın kanunu bu; güzelim,

Gözün yaşlı,gönlün buruk olmasın.

Bak; denizde dalgalar duruldu,

İçimizdeki fırtınalar durdu.

Limana yaklaşmanın zamanıdır,güzelim

Gözün yaşlı,gönlün buruk olmasın....', 'Yar; boynun bükük kalmasın. Aklın uzaklara dalmasın. Hasretlik zor şeydir bilirim, Gözün yaşlı,gönlün buruk olmasın. Annen de senin gibi,gel...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Ağır']::text[], 8.5, '{"poet":"Yavuz Ağır","poet_slug":"yavuz-agir","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/acar-gelin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dil', 'dil-ahmet-agdere-uwghv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Herşey ne kadar dizmece,

Alfabe sırasındaki harfler gibi.

Farklı dünyalar içinde, farklı hayaller; 

Kimi A''da başlar, Z''de biter,

Kimi Z''de başlar, A''da biter.

Farklıdır her insanın dili! 

Ama bellidir; 

Nerede başlayıp, nerede biteceği...', 'Herşey ne kadar dizmece, Alfabe sırasındaki harfler gibi. Farklı dünyalar içinde, farklı hayaller;  Kimi A''da başlar, Z''de biter, Kimi Z''de ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ağdere']::text[], 8.5, '{"poet":"Ahmet Ağdere","poet_slug":"ahmet-agdere","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/dil-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Köklerin Pınarı', 'koklerin-pinari-halil-i-brahim-ozdemir-ulw71', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hangi saatlerde ve nasıl bilmem 

Trenler kaçı kaç geçe giderler 

Dolmuş binilir mi parasız bisem 

Bu yollar nerede nasıl biterler. 

Kentler boy attıkça yollarımızda 

Sürgünümüz büyür iştahımız açılır 

Bir toprak testi var kollarımızda 

Ve kırılır sayfa sayfa saçılır. 

Hayatları gölgelerle paylaşan 

Atlılar atlarla akına gider 

Aşılmaz denilen dağları aşan 

Süvarinin bir gün yolları biter. 

Ölü değil sahici yüzler gibi 

Seraptan su içer vaha çınarı 

Su yoktur kuyuda görünür dibi 

Dalların köklerin kurur pınarı.', 'Hangi saatlerde ve nasıl bilmem  Trenler kaçı kaç geçe giderler  Dolmuş binilir mi parasız bisem  Bu yollar nerede nasıl biterler.  Kentler ...', ARRAY['Türk Edebiyatı','Şiir','Halil İbrahim Özdemir']::text[], 8.5, '{"poet":"Halil İbrahim Özdemir","poet_slug":"halil-i-brahim-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/koklerin-pinari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'En Kimsesiz Kalbin', 'en-kimsesiz-kalbin-sevtap-ozkahraman-yy3fl', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sana her susuşum 

Bin dokunuştu! 

Eksilten

Eskiten

Geçmiş zaman sevilerimi..

Ya

İsyankar uğultuları içimin! 

Sürgünlüğümün ray tıkırtılarıydı

Yüreğim yüreğinde ağlarken..

Ki

En kimsesiz kalbindi

Seni ben gibi sevdiren..

Oysa,

Hüznümü örtemeyen unutuşlarla

Yargılanıyor

Gözlerim gözlerinde yeniden..

Ve

Yeni düşlere uyuyor artık içimdeki yabancı.

Mahzun..

Kırılgan..

Yalnızlığımın utangaç sessizliğiyle...

(02/01/2005  Ankara)', 'Sana her susuşum  Bin dokunuştu!  Eksilten Eskiten Geçmiş zaman sevilerimi.. Ya İsyankar uğultuları içimin!  Sürgünlüğümün ray tıkırtılarıyd...', ARRAY['Türk Edebiyatı','Şiir','Sevtap Özkahraman']::text[], 8.5, '{"poet":"Sevtap Özkahraman","poet_slug":"sevtap-ozkahraman","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/en-kimsesiz-kalbin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '**AşKoLSuN Be YeNi YıL*', 'askolsun-be-yeni-yil-mine-ozdemirtas-vmon7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'e vallahi aşkolsun...! 

Kadehler kalkarken bensiz

Yine geldin ya habersiz.

Madem ki geldin, / gir içeri

gördüğün gibi,

Tayınım bu yılda bayat 

Çayım ise hala demsiz.

Kısaca,

Ben değişmedim hiç

Doğduğum günden beri

Tek kişilik bu orduda

Terhissiz.........

Er oğlu erim ya

Hizmet sınıfı: Bedelsiz

Güvendiğim dağlarda 

kar var yine

patikalar ıssız

yamaçlarım sissiz.

Susuz çeşmelerin sebiliyim gene.

Çaresiz

Bu yüzden işte

Çam ağacım avuç içimde

Büyümek zorunda

Kırmızı kurdelesiz

Ne diyeyim

Aşk olsun be yeni yıl

Aşk olsun 

“sitemsiz.”

................! 

01/01/2005....çamlıca', 'e vallahi aşkolsun...!  Kadehler kalkarken bensiz Yine geldin ya habersiz. Madem ki geldin, / gir içeri gördüğün gibi, Tayınım bu yılda baya...', ARRAY['Türk Edebiyatı','Şiir','Mine Özdemirtaş']::text[], 8.5, '{"poet":"Mine Özdemirtaş","poet_slug":"mine-ozdemirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/askolsun-be-yeni-yil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Gün', 'bir-gun-ahmet-kaytanci-vq7b6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Biliyorum bir gün gideceksin buralardan

Ardına bile bakmadan

Geldiğin gibi sessiz

Geldiğin gibi habersiz

Biliyorum bir gün gideceksin buralardan

Ben Yemen çölü

Sen göçmen kuşlar misali

Gittiğin gün yangın yerine dönecek yüreğim

Kavrulacak beynimde kum taneleri

Biliyorum bir gün gideceksin buralardan

Bırakıp beni gri kapılar ardında

O kapı her gün kaç defa çalacak

Kaç defa açılıp, kaç defa kapanacak

Her çaldığında sen geleceksin diye bekleyeceğim

Seni bilmem ama ben çok özleyeceğim

Biliyorum bir gün gideceksin buralardan

Güneşin olduğu yerlere

Ben bulutlar üzerinde şiirler yazacağım

Kimsenin okumadığı

Kimsenin duymadığı

Kimsenin bilmediği şeylere

Biliyorum bir gün gideceksin buralardan

Aldırmadan, anlamadan

Defalarca plan kurup

Defalarca dilimin ucuna gelen

Defalarca yuttuğum

Hatta defalarca beni parca parça eden

Bir cümleyi duymadan

Biliyorum bir gün gideceksin buralardan

Geldiğin yerlere

Belki bir gün bir telefon sesi

Titrek ve ürkek

Soğuk ve sert

“Şey” diyeceksin

Sesimden bile beni bilmeyeceksin

Biliyorum bir gün gideceksin buralardan

Haftanın son Cuma günü

Senin gittiğin bir şey değil

Hadi göz yaşlarımı da saklayabilirim

Tutmasa da olur ellerim ellerini

Söyle bana

Ne yapacağım yüreğimi? 

Biliyorum.. biliyorum... biliyorum

Bir gün gideceksin buralardan

Ardına bile bakmadan

Bari al götür bu yüreğimi

Yüreğim beni bırakmadan', 'Biliyorum bir gün gideceksin buralardan Ardına bile bakmadan Geldiğin gibi sessiz Geldiğin gibi habersiz Biliyorum bir gün gideceksin burala...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Kaytancı']::text[], 8.5, '{"poet":"Ahmet Kaytancı","poet_slug":"ahmet-kaytanci","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/bir-gun-91-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Sevmedim Bu Adamı', 'ben-sevmedim-bu-adami-ahmet-kaytanci-u39bl', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ben sevmedim bu adamın

Böyle dalgın

Böyle yorgun

Böyle durgun

Böyle kırgın duruşunu

Ben sevmedim bu adamın

Kahverengi gözlerindeki 

Ölü bakışları

Ben sevmedim 

Ak düşmüş saçlarına özenen

Kırçıl bıyıklarını

Çatık kaşları hiç hoşuma gitmezdi 

Çok bilmiş edasıyla konuşur ya bazen

Onu hiç sevmezdim zaten

Her kelimenin üzerinde saatlerce durması

Tam durgun sandığım anda

Deli çaylar gibi kudurması

Ne varsa önünde

Çığ düşmüş gibi alır götürürdü

Bir beni değil

Kendini de yer 

Kendini de bitirirdi

Ben sevmedim bu adamı

Karşıma zamansız çıkması yok mu? 

Sevimsiz gözleriyle

Gizli gizli bakması yok mu? 

Düşmanı andıran durgun su misali

Engerek yılanı gibi sokması yok mu? 

Deli olurum

Sabahlara kadar kırbaçlamak geçer içimden

Köseleye dönmüş suratını 

Tırnaklarımla kazımak isterim

Sonra birden vazgeçerim 

Dokunmasın ona

Kirlenmesin ellerim

Ben sevmedim bu adamı

Dedim ya

Sevilecek neyi var sanki

Yaş desen ilerlemiş çağında

Omuz desen bükülme kıvamında

Dizlerinde derman

Gözünde fer yok

Saç desen

Beyazı siyahından çok

Şunun yürüyüşüne bak 

Canından beziyor

Bir külüstür araba gibi

Yalpa vurup geziyor

Sen kimsin be kardeşim

Haddini bil hele

Seninle yürünmez ki 

El ele

Şunu aklına sok

Yalnız bülbül konar güle

Sen karga bile olamazsın

Bırak gül dalını

Sen çalıya konamazsın

Anla artık sen saçma sapan birisin

Ya olgunlaşmamış meyve

Ya zır delisin

Bence sen bu dünyada fazlasın

Ölmelisin

Ben sana gülemiyorum

Git bari ölüleri güldür

Sırtımda bir kene gibi 

Geziyorsun 

Kaç yıldır

Bıktım be senden 

Sevimsiz adam

Bir de sevgiden bahsediyorsun

Utanmadan

Sen kim

Sevgi kim

Kışın ilkbahar olur mu iklim

Hayal bile gerçeğe yakın olmalı

Ya yanından geçmeli

Ya hedefi bulmalı

Olmayacak işlerle uğraşmaktasın

Sen yalnız deli değil

Bir de aptalsın

Ben sevmedim bu adamı

Sevmekte istemiyorum

Ne zaman giderse yanımdan 

Onu, işte o zaman özlüyorum', 'Ben sevmedim bu adamın Böyle dalgın Böyle yorgun Böyle durgun Böyle kırgın duruşunu Ben sevmedim bu adamın Kahverengi gözlerindeki  Ölü bakı...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Kaytancı']::text[], 8.5, '{"poet":"Ahmet Kaytancı","poet_slug":"ahmet-kaytanci","theme":"Türk Şiiri","is_hero":false,"total_lines":84,"source_url":"https://www.antoloji.com/ben-sevmedim-bu-adami-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni', 'beni-ahmet-kaytanci-ubc0t', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'O kadar kolay ki kandırmak beni

Bir tatlı dil, birde güler yüz yeter

Büküver boynunu çocuk misali

İçimdeki nefret bir anda biter 

Nefret barınmaz ki gönlümde bir gün

Beynimde çiçek açar tohum her gün

Düşsem yatağa mecalsiz ve yorgun

Dışım karga, içimde keklik öter

Bir yıkılmış hane görsem kenarda

Hafızam kaybolur, nutkum donarda

Tepeden tırnağa her yer yanarda

Gönlüm alev alır, dumanım tüter

Sabır kervanıyla alış-verişim

Kimseyle değil, kendimle yarışım

Bu benim dünyam, bu benim görüşüm

Hedefsiz bir insan ölmüşten beter

Kaytancı dediğin kemikle ettir

Bir yudum su, bir nefes, bir sohbettir

Söylediğim sözüm sade ve nettir

İnsan doğar, büyür, yaşar ve biter', 'O kadar kolay ki kandırmak beni Bir tatlı dil, birde güler yüz yeter Büküver boynunu çocuk misali İçimdeki nefret bir anda biter  Nefret bar...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Kaytancı']::text[], 8.5, '{"poet":"Ahmet Kaytancı","poet_slug":"ahmet-kaytanci","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/beni-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeni Yıl', 'yeni-yil-orhan-tuncay-b2q6h', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gökyüzü, çatıyla kucaklaşan penceremde

Sesleniyor  kutlama coşkusu ve  hevesiyle

Yeni yıl kar olmuş yağıyor lapa, lapa

Sevinç hüzünle  ışıldıyor kar zerrelerinde

Ren geyikleri iz bırakmış olgun bulutlarda

Torbasıyla  kızakta oturan şu Noel baba

Çocuklara kar gibi armağanlar yağdıran

Çıngırakları çınlatarak giren yeni yıla

Ardımızda izler bırakmış eskiyen yıllar

Kar taneleri peşinden uçuşuyor anılar

Hoş gelmiş yeni yıl içten taşan sevgisiyle

Yeşersin barış, esenlik, sağlık ve umutlar', 'Gökyüzü, çatıyla kucaklaşan penceremde Sesleniyor  kutlama coşkusu ve  hevesiyle Yeni yıl kar olmuş yağıyor lapa, lapa Sevinç hüzünle  ışıld...', ARRAY['Türk Edebiyatı','Şiir','Orhan Tuncay']::text[], 8.5, '{"poet":"Orhan Tuncay","poet_slug":"orhan-tuncay","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yeni-yil-29-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Dağlar', 'bu-daglar-ahmet-kaytanci-86i1l', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bu dağlar ne karlar gördü

Ne fırtınalar, ne  yeller

Ne ayazlar, ne seller

Bu dağlar ne depremler geçirdi

Ne geceler geçti üzerinden

Ne güneşler

Ne kokular saldı etrafına bilir misin? 

Kargalar, kartallar, leşler 

Bu dağlar ne yalnızlıklar çekti 

Rüzgarın ıslığından başka ses duymadan

Ne geceler geçirdi

Kimsesiz, soğuk ve yorgun

Bir saniye bile uyumadan

Bu dağlar ne akrepler besledi bağrında

Ne yılanlar, ne çıyanlar

Saymakla bitmez ki 

Sırtından geçinip de böğrünü oyanlar

Bu dağlar ne çiçekler açtı

Menekşe, lale, sümbül kokan

Ne geyikler dolandı üzerinde

Ne katırlar tepindi

Ne akbabalar göründü yamacında

Ne şahinler uçtu

Bu dağlar ne sırlar gizledi

Bazen bir kayanın duldasında

Bazen bir ağacın kovuğunda

Bazen da dumanların içinde

Bu dağlar ne sevdalar gördü

Katıksız

Ne aşklar yaşadı

Karşılıksız

Bakma küheylan gibi kudurduğuna

Bu dağlar sensiz

Bu dağlar kimsesiz', 'Bu dağlar ne karlar gördü Ne fırtınalar, ne  yeller Ne ayazlar, ne seller Bu dağlar ne depremler geçirdi Ne geceler geçti üzerinden Ne güneş...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Kaytancı']::text[], 8.5, '{"poet":"Ahmet Kaytancı","poet_slug":"ahmet-kaytanci","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/bu-daglar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlama Sakın', 'aglama-sakin-ahmet-kurt-7mjb5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ağlama, üzülme sakın,

Duygular örülür, dantele benzer,

Ruhlar her alemde birine benzer,

Hislerin gerçekse gerçeği sezer,

Yüreğini yüreğime koy gitsin,

Elem bitsin, 

Keder bitsin, 

Gam bitsin.

Yalnız düşman değil kendinden sakın,

Toprağına yaprak düşer, dal düşer,

Sirke bulamazken bir zaman,

Bir zaman hissene arı bal döşer,

Eğer anlatmazsan derdi birine,

Ağzının içinde koca dil şişer,

Yüreğimi yüreğine koy gitsin,

Elem bitsin, 

Keder bitsin, 

Gam bitsin.', 'Ağlama, üzülme sakın, Duygular örülür, dantele benzer, Ruhlar her alemde birine benzer, Hislerin gerçekse gerçeği sezer, Yüreğini yüreğime k...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Kurt']::text[], 8.5, '{"poet":"Ahmet Kurt","poet_slug":"ahmet-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/aglama-sakin-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dağların Türküsü', 'daglarin-turkusu-ahmet-kaytanci-73fqt', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Şu dağların doruğuna kar yağar

Bir kasvet çöker ruhuma

Dumanlar ruhumu boğar

Pişman olurum doğduğuma

Kuytulara düşer saçlarımdaki beyazlıklar

Dağ başlarındaki kara inat

Çiğdem toplamak,

Sümbül koklamak isterim

Lalelere uzatırım ellerimi

Akrepler ellerimi sokar

Şu dağların yamacında keklikler öter

Serviler sallanır rüzgarla birlikte

Her kaya kovuğundan bir pınar akar

Her çiçek ayrı çıkar

Her çiçek ayrı kokar

Şu dağların kayaları sert olur

Aşıkları yiğit olur, mert olur

Elvan kuşlar saklar ağaçların gövdesi

Her çalı dibinde bir canlı yatar

Her canlı bir Karaca oğlan 

Her Karaca oğlan bir türkü söyler

Dumanlar üstünde kalır sevdaların hası

Lekesizdir, berraktır bu dağların sevdası

Şu dağlar köpürdü mü göresin

Yıldır yıldır eder deli çayları

Yeşerdi mi yamacında yoncalar

Kır kısraklar kişnedi mi beygire

Görmelisin yaylalarda tayları.

Şu dağlarda bahar hoştur, yaz hoştur

Rüzgar deli olur, duman sarhoştur

Süsledi mi düşlerini yaban  gülleri

Esti mi ayrılığın yelleri

Tutmaz isem  kar beyazı elleri

Sensiz dağlar neye yarar

Sensiz dağlar kimsesiz

Sensiz dünya bile boştur.', 'Şu dağların doruğuna kar yağar Bir kasvet çöker ruhuma Dumanlar ruhumu boğar Pişman olurum doğduğuma Kuytulara düşer saçlarımdaki beyazlıkla...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Kaytancı']::text[], 8.5, '{"poet":"Ahmet Kaytancı","poet_slug":"ahmet-kaytanci","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/daglarin-turkusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çok Arıyorum Seni', 'cok-ariyorum-seni-huseyin-erdogan-m2p2j', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'üşüyünce

arıyorum gözlerini

her bakışında

ısıtırdın beni

her tutuşunda ellerimi

bir ateş alırdı bedenimi

sanki yakardın her yerimi

oysa şimdi

tir tir titriyorum

ne ellerim sıcak

ne düşlerim

ne de hayallerim

inan ki çaresizim

sensiz nefessizim

gidişinle 

darmadağın ettin beni

bil ki o günden beri 

çok arıyorum seni

          03.01.2005', 'üşüyünce arıyorum gözlerini her bakışında ısıtırdın beni her tutuşunda ellerimi bir ateş alırdı bedenimi sanki yakardın her yerimi oysa şimd...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Erdoğan']::text[], 8.5, '{"poet":"Hüseyin Erdoğan","poet_slug":"huseyin-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/cok-ariyorum-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Başka Adın Varmış Aşk(2)', 'baska-adin-varmis-ask-2-nazmi-orsel-8p1rp', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yunus''a Hak olup görünen sensin,

Nazım''ın hasret-i vatanı sensin,

Akif''in nazlanan hilali sensin,

Söyle bana başka adın var mı AŞK.

Kara toprak,Veysel''e sadık yar idin,

Pir Sultan Abdal''a padiŞAH idin,

Vatana bayrak,Mehmet''e silah idin,

Saysam saysam bitmez senin adın aşk.', 'Yunus''a Hak olup görünen sensin, Nazım''ın hasret-i vatanı sensin, Akif''in nazlanan hilali sensin, Söyle bana başka adın var mı AŞK. Kara top...', ARRAY['Türk Edebiyatı','Şiir','Nazmi Örsel']::text[], 8.5, '{"poet":"Nazmi Örsel","poet_slug":"nazmi-orsel","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/baska-adin-varmis-ask-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karışığım', 'karisigim-tulay-sustam-kepwl', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'üzüm gözlüm

ben sana 

gitme kal dedikçe

biliyorum 

sen beni bırakıp

gideceksin

o zaman durma

hadi git! ...

hadi çık git

kapı değil

gözlerim kapansın

gidişinin ardından 

askı da montun yerine

şiir asılı kalsın.

(İstanbul, 01.01.2005  01.40)', 'üzüm gözlüm ben sana  gitme kal dedikçe biliyorum  sen beni bırakıp gideceksin o zaman durma hadi git! ... hadi çık git kapı değil gözlerim ...', ARRAY['Türk Edebiyatı','Şiir','Tülay Sustam']::text[], 8.5, '{"poet":"Tülay Sustam","poet_slug":"tulay-sustam","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/karisigim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Otuzüç Kurşun...', 'otuzuc-kursun-tulay-sustam-d6m1c', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'geceye 33 kurşun sıktım

biri seni vurdu

biri beni vurdu

biri aşkı vurdu

geriye sanma ki bir şey kaldı

30''u vurmaya 3 kurşun kaldı...

(İstanbul, 31.12.2004 23.45)', 'geceye 33 kurşun sıktım biri seni vurdu biri beni vurdu biri aşkı vurdu geriye sanma ki bir şey kaldı 30''u vurmaya 3 kurşun kaldı... (İstanb...', ARRAY['Türk Edebiyatı','Şiir','Tülay Sustam']::text[], 8.5, '{"poet":"Tülay Sustam","poet_slug":"tulay-sustam","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/otuzuc-kursun-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vefa Kalmadı', 'vefa-kalmadi-ertugrul-sakar-qokvz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İçimde bir tel var ince,dokunak

Bazen ağlatıyor yürekten beni

Erkek ağlamazdı bir taş barınak

Erkeği ağlatan destanlar yeni

Sarıldım vefaya,vefa kalmadı

Dost dediğim insan hançer gösterdi

Çile katıklılar sabrı duymadı

Yunus ol diyene buğday ver dedi

Kavga var gurura,hırsa,kibire

Bir tutam güleryüz kantarca ağır

Şatolar,villalar götür kabire

Orayı satın al,keyfince bağır

Erkek söz eriydi,hicap eriydi

Her kelime namus,yemin ve gerçek

Erkek ağlamazdı,sırtı kaviydi

Ne bilsin ihanet dosttan gelecek

                        23.03.1993', 'İçimde bir tel var ince,dokunak Bazen ağlatıyor yürekten beni Erkek ağlamazdı bir taş barınak Erkeği ağlatan destanlar yeni Sarıldım vefaya,...', ARRAY['Türk Edebiyatı','Şiir','Ertuğrul Şakar']::text[], 8.5, '{"poet":"Ertuğrul Şakar","poet_slug":"ertugrul-sakar","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/vefa-kalmadi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Maşa/Paşa', 'masa-pasa-bayram-tunca-vvg4n', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Maşa olanları yapmazlar katiyen paşa

Kalmaya mahkumdurlar ilelebet maşa

Geç gelir maşa olanların akılları başına

İş işten geçince, çabaları gider boşuna

02.01.2005-01:02

NOT:

Zararı kendi rızasıyla girmiş olanları,

Acınacak halde bile olsalar acınmaz', 'Maşa olanları yapmazlar katiyen paşa Kalmaya mahkumdurlar ilelebet maşa Geç gelir maşa olanların akılları başına İş işten geçince, çabaları ...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/masa-pasa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cehennemin En Altı', 'cehennemin-en-alti-taha-nur-r684f', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Alçaklığın en altı var sanırdım.

Yerin bir zemini olduğu gibi.

Gördükçe, duydukça anladım...

Yokmuş alçaklığın en altı.

Baksana adiler işliyor her haltı.

Zaman döner, toplum döner.

Güneşe karşı ayçiçek gibi.

Ahmaklar günaha koşar gider...

İşler utanmadan her haltı.

Yokmuş ahmaklığın en altı.

Esfeli Safilin açık bir gerçek,

Tıpkı Eşrefi Mahlukat gibi.

O adiler ki indikçe inecek...

Bulmaya azmetmişler en altı.

Baksana reziller işliyor her haltı.

Elmasın ve kömürün maddesi bir,

Mü''minin ve Kafirin bedeni gibi.

Bekliyor tüm insanları kabir...

Ey gafil insan işleme her haltı.

Anlasana seni de bekliyor yerin altı.

Cehil’ler, Lehep’ler yesin her haltı.

Onların mekanıdır cehennemin en altı...', 'Alçaklığın en altı var sanırdım. Yerin bir zemini olduğu gibi. Gördükçe, duydukça anladım... Yokmuş alçaklığın en altı. Baksana adiler işliy...', ARRAY['Türk Edebiyatı','Şiir','Taha Nur']::text[], 8.5, '{"poet":"Taha Nur","poet_slug":"taha-nur","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/cehennemin-en-alti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Görüyorsun', 'goruyorsun-dogan-ekdi-ygkwc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'demek  bu günde gelecekti ha

demek beni busefer kurşunsuz vuracaktın

demek hiç değerim yokmuş o bal karası gözlerinde

akşam yağmur yağıyor ve beni terk ediyorsun

haydarpaşa garında ıslak bir sokak köpeğiyle 

baş başa bırakarak olsun be gülüm 

en azından köpeğe değer veriyorsun

giderken yağmurda ıslanmasın,üşümesin diye sakonu 

atıyorsun sokak köpeğinin sırtına

ve saçlarını savuruyorsun rüzgara

demek içinde halen bir insan yanın var terk etsende beni

nice kalabalık yanlızlıklar içinde bırakarak

dilerim üzülmessin,dilerim umudun tükenmez.

ellerin nasır bağlamaz,entarin yırtılmaz,puşin yerlerde sürülmez

dilerim ocağın hep tüterde parasız kalmassın

çünkü inan gülüm 

parasız sevmek zordur sen başaramassın

hele para için terk edilmek hiç sorma

görüyorsun...', 'demek  bu günde gelecekti ha demek beni busefer kurşunsuz vuracaktın demek hiç değerim yokmuş o bal karası gözlerinde akşam yağmur yağıyor v...', ARRAY['Türk Edebiyatı','Şiir','Doğan Ekdi']::text[], 8.5, '{"poet":"Doğan Ekdi","poet_slug":"dogan-ekdi","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/goruyorsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tu Sana Emi', 'tu-sana-emi-i-brahim-bayraktar-s0t6l', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Denizden çıkan her şeyi yeriz dedik ya! 

Sonunda tokadını yemek de varmış.

Hem öyle bir tokat ki; 

Alimallah Osmanlı tokadı gibi; 

Ama yine uslanmadık.

Ölmüşüz biz dostum, ölmüşüz; 

Ölmüşüz de; ağlayanımız yok.

Vicdan kalmamış, acımak hiç yok,

İnsanlıktan nasibimizi alamamışız.

Hani din kardeşliği? 

Hani acıma duygusu? 

Hani insanlık? 

Baksana şu dost bildiklerimizin yaptığına.

Birimiz can çekişirken, birimiz göbek atıyoruz.

Vur patlasın, çal oynasın.

Komşumuz açmış, kimin umurunda? 

Tıka basa doyuruyoruz karnımızı; 

Zıbarıp yatıyoruz.

Utanmaz, arlanmaz…

Tu sana emi!', 'Denizden çıkan her şeyi yeriz dedik ya!  Sonunda tokadını yemek de varmış. Hem öyle bir tokat ki;  Alimallah Osmanlı tokadı gibi;  Ama yine ...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Bayraktar']::text[], 8.5, '{"poet":"İbrahim Bayraktar","poet_slug":"i-brahim-bayraktar","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/tu-sana-emi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Tanımak', 'seni-tanimak-dogan-ekdi-p985q', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'bir ses ver küçüğüm sadece bir ses

ne bileyim can de mesela

yada karşımda dur ve bak,sadece bak

ne bileyim

bir çiçeğe baktığın gibi mesela

yada şekilsiz bir taş parçasına...

gözlerine bir dünya kurdum küçüğüm

kocaman bir evren yaptım minicik kalbine

alıp kalbimin üstüne koydum

sadece bizim olsun diye...

aslı can sen nasıl yaşarsın

neleri seversin kimlerden yada nelerden nefret edersin

kaç yaşındasın ne iş yaparsın

yani anlat işte ne bileyim anlat sadece

çünki seni tanımak istiyorum...', 'bir ses ver küçüğüm sadece bir ses ne bileyim can de mesela yada karşımda dur ve bak,sadece bak ne bileyim bir çiçeğe baktığın gibi mesela y...', ARRAY['Türk Edebiyatı','Şiir','Doğan Ekdi']::text[], 8.5, '{"poet":"Doğan Ekdi","poet_slug":"dogan-ekdi","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/seni-tanimak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neredesin 2', 'neredesin-2-onder-diren-o19vk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Her şeyin hiçbir şey olduğunu,

Ve hiçbir şeyin,

bir şey ifade etmediğini 

Anladım seni ararken,

Olmadığın adreslerimde buldum,

Yoktun yine,

Sen...

NEREDESİN', 'Her şeyin hiçbir şey olduğunu, Ve hiçbir şeyin, bir şey ifade etmediğini  Anladım seni ararken, Olmadığın adreslerimde buldum, Yoktun yine, ...', ARRAY['Türk Edebiyatı','Şiir','Önder Diren']::text[], 8.5, '{"poet":"Önder Diren","poet_slug":"onder-diren","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/neredesin-2-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neredesin 3', 'neredesin-3-onder-diren-knnzj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'ben senin sevdana,

sevdalıyım.

seni sevmeyi seviyorum.

hatta YILMAZ’ ın dediği gibi,

seni sevebilme ihtimalini seviyorum.

hırpalanmış yüreğimin her saatinde,

senin yalnızlığın var.

ve benim yalnızlığımda

senin kalabalık yalnızlığın.

NEREDESİN', 'ben senin sevdana, sevdalıyım. seni sevmeyi seviyorum. hatta YILMAZ’ ın dediği gibi, seni sevebilme ihtimalini seviyorum. hırpalanmış yüreği...', ARRAY['Türk Edebiyatı','Şiir','Önder Diren']::text[], 8.5, '{"poet":"Önder Diren","poet_slug":"onder-diren","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/neredesin-3-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Ayrılık Hikayesi', 'bir-ayrilik-hikayesi-dogan-ekdi-5nyiy', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'birlikte başlamıştık ikimiz

yaşamın yazılı kirli sayfalarına

yaşadıklarımız önceden yazılıydı ve

sonumuzun ne olacağı belliydi ne yapabilirdik ki

oysa biz bütün buynlardan habersiz 

yaşadıklarımızı yeniden işlemeye çalışıyorduk

silmekten yıprattığımız bu sayfaların üzerine

nerden bilebilirdik ki kaderimizin başkalarının istekleri doğrultusunda yönlendiğini

ve...

kıyısını dövüyordu mor dalgalar

kayaların sertliğine kafa tutarcasına

haykırıyordu gece 

sessizliğini çatırdamaya başlamış

sevgimizin üzerine ne yapabilirdik ki

güneş kurutmaya başlamıştı

gül yaprağına benzettiğimiz sevgimizi

ki...

ölüm kokuyordu sayfalar

ölümün nefesi soğuktu

çok yakındaydı ölüm

uzansam elime değecekti sanki ölüm

karamsar bir terk edilişti 

haydarpaşa garında ıslak bir sokak köpeği ile baş başa yapayanlız

ha terk etmişsin ha ölmüşüm 

ha terk etmişim ha ölmüşsün

biliyorum sende benimle aynı fikirdesin

birlikte başlamıştık yaşamın yazılı kirli sayfalarına

ne yapabilirdik ki.

ve...

sanki dakikalar saatleri,saatler günleri, günlerde ayları kovalıyrdu

aylarda yılları ne yapabilirdik ki

o gün gelmişti

kasveti kesiklerde üreyen kahroluşun mecburi saatleriydi

ayrılık saatiydi

serçe gibi havalanacaktın sen

kaçacaktın belkide kurtulacaktın esaretten

fransaya şanzelizeye gidecektin

bende devam edecektim yaşamıma

ki...

aslında yasaklı kitaplar,dergiler okuyacaktım

mazlum halkın haklı sesini duyurmak için

meydanlara çıkacak ve kendimi bir anda 

aslında barış eylemcisiyken bölücü diye

işkence,gözaltı belkide zindanda bulacaktım 

ne yapabilirdik ki

ama seni hep balkonuna hasret  kilim,

penceresine hasret o serçe gibi özleyecektim...

sen benim düşsel prensesimsin', 'birlikte başlamıştık ikimiz yaşamın yazılı kirli sayfalarına yaşadıklarımız önceden yazılıydı ve sonumuzun ne olacağı belliydi ne yapabilird...', ARRAY['Türk Edebiyatı','Şiir','Doğan Ekdi']::text[], 8.5, '{"poet":"Doğan Ekdi","poet_slug":"dogan-ekdi","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/bir-ayrilik-hikayesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Arıyorum', 'seni-ariyorum-dogan-ekdi-oznqn', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'seni arıyorum kendimde

çok uzaklarda yanlızlığımla

başka iklimlerdeyim bilemessin

sevgini kalbime yazdım

seni arıyorum kendimde

biraz daha vurulmak için 

aydınlık sabahlarda,

sevdalanmak için sana

uzaklardan bir dua sesi gelsin

ney ve kanun sesine karışan

ve tanrıya bir yakarış olsun

mistik bir yolculuğa çıkalım senle

varmak için mavi geleceğimize can...', 'seni arıyorum kendimde çok uzaklarda yanlızlığımla başka iklimlerdeyim bilemessin sevgini kalbime yazdım seni arıyorum kendimde biraz daha v...', ARRAY['Türk Edebiyatı','Şiir','Doğan Ekdi']::text[], 8.5, '{"poet":"Doğan Ekdi","poet_slug":"dogan-ekdi","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/seni-ariyorum-25-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yakıp da Geçtin', 'yakip-da-gectin-huseyin-erdogan-cyzkk', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'sen gönlümde 

rengarenk açan 

bir bahardın

dünyama ışık saçan

bir nardın

şiirlerinle ısıtırdın beni

ben de yüreğime kazımıştım

hem seni hem de ismini

neden beni böyle

aşkının ateşiyle

yakıp da geçtin

bilmem ki! benimle

neden ayrılığı seçtin? 

oysa sen benim için

kalbimde tektin

o halde söyle 

beni neden?

terk edip de gittin? 

          03.01.2005', 'sen gönlümde  rengarenk açan  bir bahardın dünyama ışık saçan bir nardın şiirlerinle ısıtırdın beni ben de yüreğime kazımıştım hem seni hem ...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Erdoğan']::text[], 8.5, '{"poet":"Hüseyin Erdoğan","poet_slug":"huseyin-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/yakip-da-gectin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neredesin 4', 'neredesin-4-onder-diren-m04pr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'huzursuz gönlümün,

soğuğu oluyorsun.

Erzurum da kışım,

Ağrıda zirvem,

Sahrada ufuk oluyorsun.

Seni bulamadığım,

Ufkumun ötesi yalnızlığımda...

NEREDESİN', 'huzursuz gönlümün, soğuğu oluyorsun. Erzurum da kışım, Ağrıda zirvem, Sahrada ufuk oluyorsun. Seni bulamadığım, Ufkumun ötesi yalnızlığımda....', ARRAY['Türk Edebiyatı','Şiir','Önder Diren']::text[], 8.5, '{"poet":"Önder Diren","poet_slug":"onder-diren","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/neredesin-4-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalp Hırsızı', 'kalp-hirsizi-nazmi-orsel-zz10t', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu sabah üçüncü sayfadaydın,

Gözlerin siyah bantlı,

Hain bir gülüş var şuranda.

Yalnız onu sevdim demişsin polise,

Amma velakin,

Çok sayıda kalp bulunmuş zulanda.', 'Bu sabah üçüncü sayfadaydın, Gözlerin siyah bantlı, Hain bir gülüş var şuranda. Yalnız onu sevdim demişsin polise, Amma velakin, Çok sayıda ...', ARRAY['Türk Edebiyatı','Şiir','Nazmi Örsel']::text[], 8.5, '{"poet":"Nazmi Örsel","poet_slug":"nazmi-orsel","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/kalp-hirsizi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kendimi Gömdüm Dün Gece...', 'kendimi-gomdum-dun-gece-i-brahim-ethem-bingul-fpfuj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hasret, bir de sensizlik... Bunlarla ben değiştim

Yüreğimi sevdanla temizledim

İnan seni ölesiye sevdim

Lâyık değilim diye aşkımla sana gelemedim...

Yarın gelip kapını çalsam

Kimsin diye ne olur bana sorma

Ve gönül aynanda kendimi bulsam

Bil ki canım fedadır sana...

Sevgimle hep sen bendesin

Aynadaki suretimi sensin diye öptüm dün gece

Bulamazsam seni bu hayat neden çekilsin

Ölmeden kendimi gömdüm dün gece

www.iebingul.com', 'Hasret, bir de sensizlik... Bunlarla ben değiştim Yüreğimi sevdanla temizledim İnan seni ölesiye sevdim Lâyık değilim diye aşkımla sana gele...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kendimi-gomdum-dun-gece-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne yamanmış ayrılık yar', 'ne-yamanmis-ayrilik-yar-yusuf-ziya-leblebici-xaqx5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ne yamanmış ayrılık yar

Senden uzak kayrılık yar

Gün doğmaz hiç günlerime

Her tarafım karanlık yar

Hasret binice tepeme

Ölüm görünür gözüme

Sen olmazsan şu göğsümde

Nefes bile haramlık yar

Çile bitmez günler geçmez

Her gelenden selam yetmez

Sensizlik beş para etmez

Ayrı düşmek pişmanlık yar

Ne yamanmış ayrılık yar

Sensiz bağlar ormanlık yar

Hasret kaldım gül yüzüne

Özledim kaç zamandır yar', 'Ne yamanmış ayrılık yar Senden uzak kayrılık yar Gün doğmaz hiç günlerime Her tarafım karanlık yar Hasret binice tepeme Ölüm görünür gözüme ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ziya Leblebici']::text[], 8.5, '{"poet":"Yusuf Ziya Leblebici","poet_slug":"yusuf-ziya-leblebici","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ne-yamanmis-ayrilik-yar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayyaş', 'ayyas-yusuf-ziya-leblebici-o8ia0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Havanda su döve döve

Her geçene söve söve

Rakı şarap bırakmadın

Meyhanede içe içe

Akıllısın biliyorum

Kullanmazsın şaşıyorum

Adam olamadın ama

Ayyaşlığa sayıyorum

Köpek öldüren ve peynir

Yanına da ekmek gelir

Taşburların eşliğinde

Ağlayan göz hep sendedir

Sonun kötü bile bile

Yarınını göre göre

Azrailin kucağına

Gidiyorsun seke seke', 'Havanda su döve döve Her geçene söve söve Rakı şarap bırakmadın Meyhanede içe içe Akıllısın biliyorum Kullanmazsın şaşıyorum Adam olamadın a...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ziya Leblebici']::text[], 8.5, '{"poet":"Yusuf Ziya Leblebici","poet_slug":"yusuf-ziya-leblebici","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ayyas-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arkadaşım olamazsın', 'arkadasim-olamazsin-yusuf-ziya-leblebici-fpzaq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dost düşmanı ayırmazsan

Doğru yolu bulamazsın

Seni benden sakınırsan

Arkadaşım olamazsın

Avuçlarım sevgi dolu

Uzatmışım sana doğru

Kucaklayıp sarmıyorsan

Arkadaşım olamazsın

Her adımı ben atarsam

Ben gelirken sen kaçarsan

Ürkek ceylan olacaksan

Arkadaşım olamazsın

Paran pulun senin olsun

Bir yerine onbeş dolsun

Bana hava atacaksan

Arkadaşım olamazsın

İki yüzün benzemezse

Kem bakarsan döndüğünde

Ardımsıra vuracaksan

Arkadaşım olamazsın', 'Dost düşmanı ayırmazsan Doğru yolu bulamazsın Seni benden sakınırsan Arkadaşım olamazsın Avuçlarım sevgi dolu Uzatmışım sana doğru Kucaklayı...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ziya Leblebici']::text[], 8.5, '{"poet":"Yusuf Ziya Leblebici","poet_slug":"yusuf-ziya-leblebici","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/arkadasim-olamazsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni seviyorum ey güzel insan', 'seni-seviyorum-ey-guzel-insan-yusuf-ziya-leblebici-y0ar8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ne değişir siyah veya beyazsan

Irkın ne olursa adam ol adam

Seni seviyorum ey güzel insan

Dinin dilin farklı diye ayırmam

Hepimiz toprağa gömülmez miyiz

Bir yar tarafından sevilmez miyiz

Seni seviyorum ey güzel insan

Adem''in evladı biz değil miyiz

Benden uzak olsan sen de bir cansın

Ya doğuran ana, ya da babasın

Seni seviyorum ey güzel insan

Misafir de olsan bu dünyalısın

Muhammed Mustafa, İsa ve Musa

Adem Babamızdan Meryem Ana''ya

Seni seviyorum ey güzel insan

Milattan öncesi, yeni çağlara

İster zenci, ister kızılderili

Kadını erkeği, ihtiyar genci

Seni seviyorum ey güzel insan

Sen de sevmelisin seni seveni', 'Ne değişir siyah veya beyazsan Irkın ne olursa adam ol adam Seni seviyorum ey güzel insan Dinin dilin farklı diye ayırmam Hepimiz toprağa gö...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ziya Leblebici']::text[], 8.5, '{"poet":"Yusuf Ziya Leblebici","poet_slug":"yusuf-ziya-leblebici","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/seni-seviyorum-ey-guzel-insan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her gün bir kıyamet', 'her-gun-bir-kiyamet-yusuf-ziya-leblebici-dx9ai', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Her şey değişiyor taşlar oynuyor

Düşenin yerine yeni konuyor

Kapalı gözünü aç ta bir seyret

Her gün bir kıyamet dünya batıyor

Denizler taşarken kara bitiyor

Ateş sıkışınca dağlar patlıyor

Nefes alıyorsak budur keramet

Her gün bir kıyamet  dünya eriyor

Dost görünen kişi hain çıkarsa

Ardını dönünce hançer vurursa

Bu dostluk değildir, adı ihanet

Her gün bir kıyamet çıkarlar varsa

Can alan zalimler kol geziyorsa

Minicik bebeler aç ölüyorsa

Seyrediliyorsa böyle sefalet

Her gün bir kıyamet  göz görmüyorsa

Kitabın kapağı neden açılmaz

Kara hurafeden neden şaşılmaz

Çökertir bizleri böyle cehalet

Her gün bir kıyamet  bundan kaçılmaz', 'Her şey değişiyor taşlar oynuyor Düşenin yerine yeni konuyor Kapalı gözünü aç ta bir seyret Her gün bir kıyamet dünya batıyor Denizler taşar...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ziya Leblebici']::text[], 8.5, '{"poet":"Yusuf Ziya Leblebici","poet_slug":"yusuf-ziya-leblebici","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/her-gun-bir-kiyamet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalana Bak Sen Hele', 'yalana-bak-sen-hele-nesimi-kecelioglu-sd4wa', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bak şu tsunami nin yaşattığı drama,

Sanki yer gök yarılmış gelene bak sen hele.

Belki bundan daha zor, daha beter var ama! 

Böyle mi can verilir ölene bak sen hele.

Yeni sene takvime bir kaç güne girecek,

Gidenin afatını gelip kendi görecek,

Teselli mi olacak, müjdeler mi verecek? 

Sinsi, sinsi sırıtmış gülene bak sen hele.

Giderken yaraladı hain bizi vurdu da; 

Koca bir yıl küstahça içimizde durdu da; 

Ah vah bile demedik belimizi kırdı da; 

Bak sen şurda sararıp solana bak sen hele.

Çökmüş fakir fukaram çatlamış kalça göbek,

Açlığın sancısıyla uykudan kalkmış bebek,

Daldan dala zıplıyor enflasyon denen şebek,

Nasıl da kıvrılıyor yılana bak sen hele.

Keşke hâl kıymet bilsek, artsa Lira değeri,

Dizgin de sağlam dursa emekçimin eyeri,

Karış, karış süslesek cennet etsek bu yeri,

O zaman kadir kıymet bilene bak sen hele.

Sevinsek mi kızsak mı böyle garip bir hüzün; 

Gece şevkine döndü güzel ülkem gündüzün,

Neden kızarır oldu tebessüm döken yüzün? 

Avrupa lı olmuşuz plana bak sen hele.

Bu maskaralıkta ne, bunlar lükse niyet mi? 

Dini hurafelik mi, yoksa ki cinsiyet mi? 

Şu Avrupa oyunu acep Türk''e diyet mi? 

Bak şu palavracıya yalana bak sen hele.

Kopup, kopup duruyor trenlerin rayları,

Eklem yapmayla savdık haftaları ayları,

ABD jokeyinde Arap''ların tayları,

Bak sen yaslı Irak''ım çilene bak sen hele.

Adalar parsel, parsel Kıbrıs gerçeği birde; 

Bulgar''ı iyi tanı Rum''un gönlünü gör de,

Gelsin orta yerinden ülkemi bölsün dörde, 

Bak işte sen o zaman olana bak sen hele.

Kızmam deme Nesimi daha çok kızacaksın,

Ya ölecek, ya da bu oyunu bozacaksın,

Şanlı Türk''ün adını göklere yazacaksın,

İşte o zaman seyret şölene bak sen hele.', 'Bak şu tsunami nin yaşattığı drama, Sanki yer gök yarılmış gelene bak sen hele. Belki bundan daha zor, daha beter var ama!  Böyle mi can ver...', ARRAY['Türk Edebiyatı','Şiir','Nesimi Keçelioğlu']::text[], 8.5, '{"poet":"Nesimi Keçelioğlu","poet_slug":"nesimi-kecelioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/yalana-bak-sen-hele-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tesadüflerden Teessüfler', 'tesaduflerden-teessufler-i-brahim-elciboga-0bg5g', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kendi kendine konuştuğumuzdur uykularımızda

Ve hiçbir şey hatırlayamadığımızdır; 

Sır kalsın diye beklettiğimiz,

oflayıp puflayıp 

çıkmasından korktuğumuz 

ergenlik sivilceleridir tesadüfler.

Bazen de çok bilindik bir kapı zilidir

akşam saatlerinde baba kokan.

Bir salıncakta sallanmaktır bazen 

ve salladığına inanılan kişidir  bizi üstünde tutan

ve düştüğümüzün halidir desek

tesadüflerden teessüfler

ne kadar yalan.

Arka bahçeye kaçan, alınmayan bir toptur zaman 

Ve kimi zaman

Bir duvardır geçilmesi gereken an.

“Biraz öteye git de tozunu alayım”lardır

Bir bayram temizliğidir 

ya da ak pak giyilen temizlerdir

ve beraberinde

Sırasıyla öpülen ellerden en güzelidir 

en muzur, en güzel öptüğün.

“ Kocaman olmuş oğlunuz ”dur fazlasıyla hak ettiğin

 Mucizeler.

Bir çiçekle saklanıp beklemelerdir 

cama atılan ufak bir taşın ardından 

ve o taştır inan her dönüşünde sana, 

senin ne kadar sevdiğini anlatan.

sonrasında “gel ve al sıkıysa” diye buruk korkutmalardır 

belli ki, sorulmaya ihtiyaç duyulan hal ve hatır.

Parmaklarının üzerinde yükselip de daha önceleri 

Göremediğimiz şeyleri görmeye çalışmaktır yaşam

Yaşam koşup gidebilmektir 

patlak bir topun ardından hiç yılmadan.

Yazdıkça yazılabilir daha neler neler, satır satır

Yaşam bir mucittir, bir çocuktur; büyümeye yatır.

                                                                                                                                                                       (2004-11-27 İstanbul)', 'Kendi kendine konuştuğumuzdur uykularımızda Ve hiçbir şey hatırlayamadığımızdır;  Sır kalsın diye beklettiğimiz, oflayıp puflayıp  çıkmasınd...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Elçiboğa']::text[], 8.5, '{"poet":"İbrahim Elçiboğa","poet_slug":"i-brahim-elciboga","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/tesaduflerden-teessufler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kibrit Çöpü', 'kibrit-copu-cigdem-agbulak-77cco', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir kibrit çöpüyüm ellerinizde,

Canınız sıkılınca,

Yakarsınız olur olmaz,

Yaşamım biraz tahta, biraz parafin,

Ve kül olmaktır sonum...', 'Bir kibrit çöpüyüm ellerinizde, Canınız sıkılınca, Yakarsınız olur olmaz, Yaşamım biraz tahta, biraz parafin, Ve kül olmaktır sonum......', ARRAY['Türk Edebiyatı','Şiir','Çiğdem Ağbulak']::text[], 8.5, '{"poet":"Çiğdem Ağbulak","poet_slug":"cigdem-agbulak","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/kibrit-copu-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neşeli Şiir...', 'neseli-siir-cigdem-agbulak-kx2b3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Denizime kar yağmış

Görsen martı sanırsın

Öyle neşeli bir gün bugün

Duysan kahkahamı öldüm sanırsın...

Sahte sahte basar gibi parayı

Neşenin de sahtesi basılıyor mu? 

Sonra ondan geriye

Biraz kül, biraz ateş

Belki birazda hüzün kalıyor mu? 

Ne zaman düşürsem yüzümü

Bir avuç deniz alıyor gibi

Maviden geriye

Biraz gri, biraz kızıl

Belki birazda beyaz kalıyor mu? 

Bu sabah ağlar gibi

Bir iki damla yaşı düşürdüm dudaklarımdan

Maviye hasret, kızıla aşık

Beyaza tutkun

Kendim kayıp.

İlanlar mı versem bulmak için kendimi

Yoksa zaten olmayanı mı yaşıyorum

Senden az, benden çok.

Cümlelere hapsettim

Biliyorum virgüllerim yok

Kitaplara sığdıramadığım noktalarım var

Zaten herşey güzel olacak değil mi? 

Uyandığında bir sabah

Aslında varolmayanı oynayacağım

Belki sende katılırsın bu oyuna

Bir noktada sen koyarsın.

Bakıyorum

Martılarım yağmış çoktan

Havada kafa bulandıran bir lodos

Kendim kendime sahip çıkamıyorum.

Ellerimi kaldırıyorum

Parmak uçlarım rüzgâra dokunuyor

Canım yanıyor

Kaçıyorum.

Herkesin bildiği terk edişlerden olmayacak gidişim

O gün ne yağmur yağacak deli gibi

Ki arkamdan fazlada küfredemeyin diye

Ne de yakıp kavuracak bir güneş olacak.

Sanırım bir tek annemi özleyeceğim

Ben gideceğim

Siz arkamdan en güzel şarkıları söyleyeceksiniz.

Birileri beni görüp vahlanacak

-Pekte gençmiş biçare.

Oysa ben güleceğim, siz bilmeyeceksiniz.', 'Denizime kar yağmış Görsen martı sanırsın Öyle neşeli bir gün bugün Duysan kahkahamı öldüm sanırsın... Sahte sahte basar gibi parayı Neşenin...', ARRAY['Türk Edebiyatı','Şiir','Çiğdem Ağbulak']::text[], 8.5, '{"poet":"Çiğdem Ağbulak","poet_slug":"cigdem-agbulak","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/neseli-siir-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gezgin', 'gezgin-ozgur-doran-x91k0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Her geçen gün benim oluyorsun

Dudakların tanıdık bir iklimin meltemi

Çöl ıssızlığında varlığın bir serap

Doğumunun kaydı yok

Şehrin karanlığında

Adın tanrıya eş….

Gezgin bir ruhun ışığısın 

Sonsuza dek yanacak.', 'Her geçen gün benim oluyorsun Dudakların tanıdık bir iklimin meltemi Çöl ıssızlığında varlığın bir serap Doğumunun kaydı yok Şehrin karanlığ...', ARRAY['Türk Edebiyatı','Şiir','Özgür Doran']::text[], 8.5, '{"poet":"Özgür Doran","poet_slug":"ozgur-doran","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/gezgin-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '...*H..i..c..r..e..t..*...!', 'h-i-c-r-e-t-serhat-kaya-a0hwe', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '*Sana uzanan kalp* 

sahranın gözbebeğinden süzülürken nur 

medine''nin kalbine sevgiden ilk yağmur 

*** 

bir nokta gelir ufuktan, bir ses duyulur 

en önde Sa''d, firaktan yanan yürek sarar 

*** 

semadan damlar gözyaşı, temizler durur 

sinelerde gizli/ izbelerde cürumlar 

*** 

vuslatımda, kanla kirlenmiş kalbimde tur 

beni kuşatmaya alır, gümrah suratlar 

*** 

beynimin düz aynasında gölgelerden sur 

sokağında gezinen sûratsiz insanlar 

*** 

silinmiş kitabelerin raflarında ur 

mütekâsif düşlerimde kof dağılmalar 

*** 

hicretinden kalan sudaki kızıl kalbur 

dökülür revzeninden yanyana yalanlar', '*Sana uzanan kalp*  sahranın gözbebeğinden süzülürken nur  medine''nin kalbine sevgiden ilk yağmur  ***  bir nokta gelir ufuktan, bir ses duy...', ARRAY['Türk Edebiyatı','Şiir','Serhat Kaya']::text[], 8.5, '{"poet":"Serhat Kaya","poet_slug":"serhat-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/h-i-c-r-e-t-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mavi', 'mavi-ozgur-doran-4wuo0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'En çok kumdan kaleler yakışır sana

Masmavi denizin üzerinde

                  süzülen            

Mavi gelinliğinle

Birde savrulan saçlarının arasında dolaşan 

                                                                          Deli rüzgar.....', 'En çok kumdan kaleler yakışır sana Masmavi denizin üzerinde                   süzülen             Mavi gelinliğinle Birde savrulan saçlarını...', ARRAY['Türk Edebiyatı','Şiir','Özgür Doran']::text[], 8.5, '{"poet":"Özgür Doran","poet_slug":"ozgur-doran","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/mavi-48-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '...*Ben i Düşün*...!', 'ben-i-dusun-serhat-kaya-4vgbp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '-Suyu tanımaz acının örsü- 

Öfkesi törpülenmiş yüzümün 

gözlerini yut(a) madı güneş 

susmalarımda virgül kopmalara sığdırılan 

kırık kelimelerim yol alır isyana 

nokta düşürülmemiş hikayem 

uzar/ uzadıkça kucağımda zaman 

silinmeden kalemimdeki cümle(ler)

yazılır mektubuma 

                              erit taşı gözyaşlar(ın) la 

deryanın kaldırımına ekilen yıllar 

yağdırır gurbeti harabe çergeme 

sütunları çatlak tavanlar gibiyim 

damla çarptıkça tepeme hırçın 

devrilmeye yüztutar her anım 

soluduğum son nefes de 

çağladı ruhumdan yalın 

kırmamışken yazmayan kalemi elimde 

tutulur parmaklarım ürkek bir sesle 

                              usülce bırak elinden kalemi 

dökülür hayat çınarının yaprakları 

hayat nehrinin engin menbaına 

uçurumu kapanmış bu seslerin 

istifleştikçe ezilen ruhlar var en altta 

doğum sancısı duyulmuyor kulaklarda 

yorumsuz raks ederken frekanslar havada 

düşük gelir titreşimi son nefesin 

düşmemişken son yaprak alnıma 

                              hicret eder sonbahar harelerine yüzümün 

günler hayta kasırgalar gibi 

öğütür delişmen gençliğimi 

süzülür değirmenlerden 

un olmuş cesedim yaprak kefenimde 

ısınmaz kemiklerim toprağın karnında 

çürümemişken protez aklım 

düşürülür bir soru dilime 

                              bitti mi yol bu patikada?', '-Suyu tanımaz acının örsü-  Öfkesi törpülenmiş yüzümün  gözlerini yut(a) madı güneş  susmalarımda virgül kopmalara sığdırılan  kırık kelimel...', ARRAY['Türk Edebiyatı','Şiir','Serhat Kaya']::text[], 8.5, '{"poet":"Serhat Kaya","poet_slug":"serhat-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/ben-i-dusun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '...*Karanlık Bir Gecede/ Yağmur Altında Serenat/ Islanan Ruhum Parçalanıyor Düşen Her Damlayla*...!', 'karanlik-bir-gecede-yagmur-altinda-serenat-islanan-ruhum-parcalaniyor-dusen-her-damlayla-serhat-kaya-mtzwv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '-Kimin? Beni yaralayan bu yüz- 

Yolunu tanımadım bu firarî gidişlerimin 

Asıldığımı görmedim de şizofrenik rüyalarda 

Ve başka bir ses değildi bendeki bu gürültü 

Kalp atışıydı sadece ayaklarımın altındaki cansız yerin 

Tükense mürekkebi harelerimi karalayan kalemin 

Bulanık hava kalır bir/ kanımı pıhtılaştıran 

Yüzüme saplanan ayak izleri nerden/ dilim kesilmiş 

Vakur yürüyüşüydü gölgemin süzülüşü alnımdan 

Yavrusunu koruyan bir anne kadar hırçınlaşmamıştım da 

Dört duvarda sallanan ıpıssız gölge bendim oysa! 

Yanılmışım (mı?) / yağma olmuş dünyalarda vuruluduğum 

Kıvranıyordum bir kanadı kırık kuş gibi acının kollarında 

Devişirin bana yüzümü/ varoşların çocuğuyum ben 

Benim değil rüya(m) da görülen bu yüz. 

Bir önceki giden yolcu kadar beklenmemiştim 

Adına esrar sinmiş kartal yuvasındaki “çocuk”um ben 

Gösterilseydi bana düşeceğim yer/ gerek kalmazdı tut(un) manıza 

Yanıbaşımda bir gölge/ yüzünde ısınan mistik bir dua 

Ben miydim? / adını eşkıyalara ödünç veren esir 

Masum da değilim ruhumda sakladığım sır kadar 

Çöle yağmurun düşmesi gibi muhal bir şeydi bu sükût 

Dil varır mı sükûta? / kelimeleri eskimiş sesler(in)  ocağında 

Bir o(r) dunun yanarak tutuşması kadar kolay bir şeydi tebessüm 

Dürülürdü yüzümü buruşturan renklerde ruhum. 

Dudakları perçinleyen/ susuz bir yakarış 

Ağladıkça/ gülmesi istifleşen yalnızlıklar dizilir göz ucuma 

Karla karışık günah yağdıran gökyüzü 

Serinletemez ateş kütlelerinde yanan yüreğimi 

Dolunayı yutan bir dudak/ pencere ardında mahkûm 

Çarpar ellerime/ camı ışık sanıp da öpen kelebek 

Ateşte kıvranması mıydı/ uyuyan denizin horuldaması 

Ayın dördüne kuşanmış enginlere sarkıtılan elvan uçurtmalar 

Boşlukta bir inilti/ kulakları törpüleyen keskin çığlık 

Hançer geninde patlak veren bu ses/ artık parmaklarımın ar(k) asında 

Rüyamda her vurulduğunda bir çocuk/ düşerdi omzuma boynum 

Ki, yutkunduğumda avucumdaki acıya bezenmiş telveyi 

Serperdim yollara kıvrım kıvrım olan bakışlarımı/ gelmemeniz için. 

Mahşere uzanan kelimelerim var/ dudağımda öyle dağınık 

Toplanmasına an kala vurulduğumu varsaysam/ haince 

Yine de aldandığımı sanacak bu ruhsuz ücretli köleler 

Koskoca bir hüsrandı payıma düşen yine! 

Her sarstığımda gök/yüzümü mimiklerimle 

Dökülen bu gözyaşları mizâh mıydı/ gülüşünüze müsebbeb 

En büyük acıydı/ beni çıldırtan kahkahalarınızı duymak 

Sonu gelen bir mahkûmun son sigarası gibi 

Tezcanlı bitiveriş misâli bir şeydi bu ağlayışım 

Âvare gezinir harabe kentler üzerinde cirit atan rüzgârlar 

Sanki bir kitabın son sayfasıydı bu tuttuğum gün. 

Sahipsiz mi? makilere serilen bu hayatlar/ üşüşüyor insanlar 

Garipsenecek ne var ki, aradığım yolculuk bu değil oysa 

Bana urbaları kan toplayan nesil gösterildi/ kan(a)  bulaşmış elleri 

Saz benizli çocukları öptüğüm dudak 

Yarıldı başlattığınız savaşlarda kılıç şakırdamalarıyla 

Tarihe düşülen bir not/ kimin hayatından çalınmış? 

Neresine sığdırayım bu son mehcûr kelimeyi 

Bir destan vardı/ genç asil çocuklar söylüyordu şarkısını 

Bırakılmıştı susmalara/ nakaratlarda kilitlenen diller 

Her okuduğumda devamı mazide kalan bu şiiri 

Karanlık bir gecenin/ rengi solgun yıldızların gölgesinde 

Yağmur altında serenat hüzün mevsimi 

Parçalıyor ruhumu düşen her damlayla 

Kalbime sızan halecan/ köpük saçıyor damarlarıma 

Alnımdan silinen öfkeme ne demeli? ey Sen! 

Bir hüzündü sanki gök/yüzümle buluşan her yıldız kümesi 

Şiirlerimde kurulan mayın tarlasıydı her kafiye(m) .', '-Kimin? Beni yaralayan bu yüz-  Yolunu tanımadım bu firarî gidişlerimin  Asıldığımı görmedim de şizofrenik rüyalarda  Ve başka bir ses değil...', ARRAY['Türk Edebiyatı','Şiir','Serhat Kaya']::text[], 8.5, '{"poet":"Serhat Kaya","poet_slug":"serhat-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":66,"source_url":"https://www.antoloji.com/karanlik-bir-gecede-yagmur-altinda-serenat-islanan-ruhum-parcalaniyor-dusen-her-damlayla-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '...*Siz miydiniz? / Geçen Gözümdeki Sahradan*..!', 'siz-miydiniz-gecen-gozumdeki-sahradan-serhat-kaya-i51dd', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '-sol tarafı kırık katar katar aynalardaki 

                              tanışmalarda unutmuşsunuz ayak izinizi, 

                              almayı deneyin, geri dönmeyi değil...! - 

Divitin geninde neftî korku 

düşer ayak ucuma gök/yüzünüzü delen burgu 

iğreti bozlaklarda üşüyen kurgu 

yanar bir damla suda/ oysa denizlerin ıslatamadığı oydu..! 

yaması sökülmüş rengi uçuk saydam gece 

sızar yüzünüzdeki mavi tebessüme 

yüreğinizde yorgun tekdüze kahır 

kudurtur ruhunuzda dövünen yaranızı..! 

örselenirken ruhunuz acının dişlerinde 

uyanmayı deneyip de uyanamadığınız uyku(nuz) da 

anbean rüyalarınıza giren kâbus 

sızdırır korsenizden vücudunuza boranları 

mum ışığında ısınmaya çalışıp da ısınamadığınız üşümede 

büyümüş gölgenize sığınırsınız naçar bakışınızdan..! 

ardın(ız) dan sürükle(n) diğiniz hayat 

aranır kirişlerinde kızıl ayazın 

kaçmayı denediğinizde, durduracak sizi 

üç-beş noktada birleşen 

rengini bilmediğiniz gölgeler..! 

terketmişti tutunduğunuz sanrılar sizi 

şimdi...kuşatıldı her yanınız surlarıyla hakikatın 

kurtulmayı umduğunuz tek (kişilik)  geçit 

durur göz ucunuzda/ ama göremezsiniz 

hatırlamaya çalışın/ emanet bıraktığınız yerini bakışlarınızın 

tanıdıkça bulmayı/ açılacak hürriyet kapınız 

yürürken boğmayın hıçkırığa ayak izinizi... 

muallakta kalsın muğlak tarifiniz 

almayı deneyeceğim geçerken ben askının altından 

çalıştıkça tanımaya 

yırtılacak iz aynasında duran ruhsuz yüzünüz... 

yoksa siz miydiniz..? ! 

adını bilmediğim kervan 

geçip-giden 

su testisi kırılırken kan yolunda 

gözümde siyaha bürünen sahradan..!', '-sol tarafı kırık katar katar aynalardaki                                tanışmalarda unutmuşsunuz ayak izinizi,                            ...', ARRAY['Türk Edebiyatı','Şiir','Serhat Kaya']::text[], 8.5, '{"poet":"Serhat Kaya","poet_slug":"serhat-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/siz-miydiniz-gecen-gozumdeki-sahradan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beyaz Hüzün (Beyaz Ölüm)', 'beyaz-huzun-beyaz-olum-necmiye-sarpkaya-a7p45', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'ah ah durdurabilse zaman çarkları

kanatlanılabilse uçulabilse varılabilse

Enver Paşanın mağrur kulaklarına

Fısıldanılabilse al paşa al emri dense

Ne olur salma civanlarımı  dense

Dağlar dağlar ölümlü dağlar

Çileli dondurucu dağlar

Yıl 13 ARALIK 1913

Yarbaylıktan Albaylığa

Arkasından paşalık

Başkumandan vekilliği

Henüz 32 yaşında mağrur kumandan

25 ARALIK Mehmetçik çıkar yollara

Marş marş istikamet Sarıkamış

Kışlık parke içlik postal yok

Ayaklarda çarıklar

Yemenden yolculuklar

Açlık yorgunluk yokluk

Ağaç üzerinde geceler

Mehmedim donmuş

Mübarek bedenler 

Dökülür teker teker

Hırsın bürüdüğü

Dengelerin öldüğü

Liyakatın yok olduğu

Tecrübelerin kovulduğu

Yalancı şöhretin sardığı

Beyinler ah o beyinler

Bize yanık türküler bırakır

Mazinin kucaklarında günahlar

Mazinin kucaklarında sevaplar

Karbeyazı elbiseler yiğitlerim

Yanık türküler sesleri keser

Bülbüller susar

Güller ağlar

Dağlar taşlar ağlar

Kurtlar kuşlar yas tutar

Kara buza keser

Beyaz hüzün yürekleri dağlar

Kara haber tez ulaşır

Kalbleri yaralar vicdanları paralar

Ah dağlar ah yürükleri dağlar

mübarek 90 bin can

90 bin Mehmetim

Beyaz kefenlerde

Ruhlar havalanır ak güvercinler

sonsuzluğu saran dağlar

Cepheye çarıkla

Cepheye yelekle

Yollanan Mehmetimin

Askerimin türküsü yankılanır

Dağlar dağlar başı dumanlı

Başı çileli dağlar', 'ah ah durdurabilse zaman çarkları kanatlanılabilse uçulabilse varılabilse Enver Paşanın mağrur kulaklarına Fısıldanılabilse al paşa al emri ...', ARRAY['Türk Edebiyatı','Şiir','Necmiye Sarpkaya']::text[], 8.5, '{"poet":"Necmiye Sarpkaya","poet_slug":"necmiye-sarpkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":53,"source_url":"https://www.antoloji.com/beyaz-huzun-beyaz-olum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölü Kedi', 'olu-kedi-ali-kuruuzum-3tbav', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ölü Kedi.

Canlı kedi.

Kuantum.

Bir kaç meleğin eli.

Yağmurla yıkanmış asfalt.

Gece yürüyüşü.

Eve dönüş yolundaydım.

Bİr kamyonetin arkasından el vermiş iki genç adam,

var güçleriyle aracı canlandırmaya çalışıyorlardı.

İri bir kamyonet ve olasılıklar.

İnsanlara hiç beklemedikleri zamanlarda da yardım etmeliyiz.

''-Yardım lazım mı? ''

Elimdeki şemsiyeyi kot pantolonumun arka bel kısmına sokuşturdum.

İktirmeye başladık.

''-Vur,vur...'' diye bağırdı biri.

Gittikçe hızlanıyorduk.

Şüphesiz bir öncekinden daha fazla şansları vardı.

İyi niyet insanı kahraman yapabilir.

Tüm gücümüzle koşmamıza rağmen  çalışmıyordu.

Daha da hızlandık.

Biraz daha...

Gelip geçen arabaların farları yolumuzu aydınlatıyordu.

Bir on saniye daha iktirirsek gücümüzün biteceğini biliyordum.

Son anlardı.

Ve hiç ummadığımız bir ses geldi; yorgun,eski kamyonetin motorundan.

(16-kasım-2004)', 'Ölü Kedi. Canlı kedi. Kuantum. Bir kaç meleğin eli. Yağmurla yıkanmış asfalt. Gece yürüyüşü. Eve dönüş yolundaydım. Bİr kamyonetin arkasında...', ARRAY['Türk Edebiyatı','Şiir','Ali Kuruüzüm']::text[], 8.5, '{"poet":"Ali Kuruüzüm","poet_slug":"ali-kuruuzum","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/olu-kedi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kimlik', 'kimlik-ali-ziya-camur-dj6cy', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ateşin gölgesinde 

Direnirim buzul çağrılara...

Cebimde şiirlerim,

Kilitlenmiş kapılara anahtar.

Acıya borcum yok,

Kuyudan yıldız çıkarmak

Derdinde hiç değilim...

Yıldızları ekerim şiirimin yakasına,

Kederlerin köşebaşlarına telgraf çekmem.

Acılarıma ve mutluluğuma

Halkın sureti

Düşürülmüştür bir kez.', 'Ateşin gölgesinde  Direnirim buzul çağrılara... Cebimde şiirlerim, Kilitlenmiş kapılara anahtar. Acıya borcum yok, Kuyudan yıldız çıkarmak D...', ARRAY['Türk Edebiyatı','Şiir','Ali Ziya Çamur']::text[], 8.5, '{"poet":"Ali Ziya Çamur","poet_slug":"ali-ziya-camur","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kimlik-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yetmez', 'yetmez-oguzkan-bolukbasi-wq7ai', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Senin sesini duymaktır

Belli günlerin anlamını güzelleştiren içimde

Bir yeni yıl yenilenmek değil “sen”lenmektir nede olsa 

Doğum günü doğmaktan ziyade 

Olmakla ilgilidir hafızanda

En inanılmaz çılgınlığımsın

Kendimi boşluğuna paraşütsüz bıraktığım andan itibaren

Ne gökyüzündeyim

Ne yeryüzünde şimdi

Görmüyorum hiçbir yeri

Değmiyorum  hiçbir yere

Uçsuz bir boşluktayım

Bıraktım kendimi dönmelere

Öykünmem ne pervanelere

Ne değirmenlere

Öykünmem

O bende sakladığın gözleredir

Yelken açamadığım denizleredir

En inanılmaz çılgınlığımsın

Kendimi boşluğuna paraşütsüz bıraktığım andan itibaren', 'Senin sesini duymaktır Belli günlerin anlamını güzelleştiren içimde Bir yeni yıl yenilenmek değil “sen”lenmektir nede olsa  Doğum günü doğma...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yetmez-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalan', 'yalan-ali-gencay-8by5z', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ruhuma üflenen sevda

Kasıp kavurdun,bu mu aşkta sefa

Geceler boyu uyutmayan rüya

Hani yoksun,bu mu gecelere reva

Örtün üzerini,üşümesin anılar

Mil çekin gözlerine,ağlayamasın aşıklar

Dönüp duran dünya,dur artık

Harcanmıyor biriktirdiğim zaman

İhbar var,öfkemi öldürdüm

Yüreğimin en derin yerine gömdüm

Bilinmesin diye katilliğim

Olmadık şeylere güldüm

Yalan,ne desen yalan

Güneştir doğudan doğup batıdan batan

İnsanlar yüzlerinde maske

İnsanlar,riyalar üzerine saltanat kuran

Biten yok,bitmeyecekte yaşam 

Elimde her acıdan arta kalan kavgam

Yüreğimde yaşanmamış sevdam

Yıkılacak bir gün elbet yalan', 'Ruhuma üflenen sevda Kasıp kavurdun,bu mu aşkta sefa Geceler boyu uyutmayan rüya Hani yoksun,bu mu gecelere reva Örtün üzerini,üşümesin anıl...', ARRAY['Türk Edebiyatı','Şiir','Ali Gençay']::text[], 8.5, '{"poet":"Ali Gençay","poet_slug":"ali-gencay","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yalan-124-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saksı mı düştü yoksa başına?', 'saksi-mi-dustu-yoksa-basina-kadir-soyturk-mxz4n', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Duydunuz mu muhterem, neler neler diyormuş? 

Çok üzgünmüş bu sıra, din elden gidiyormuş! 

Zavallının saksımı, düşmüş yoksa başına? 

Belki inanan vardır, bu timsah göz yaşına! 

Allah''a, Peygambere  karşı duran sizdiniz; 

Ilim yuvalarına,  kilit vuran sizdiniz...

Her yerde hor görüyor, hep hakkını yiyordun. 

Daha dün müslümana, pis – gerici diyordun! 

Örtülü bacılara, etmediğin kaldı mı? 

Yoksa ölüm meleği, kapınızı çaldı mı? 

İşine geldiğinde, müslüman kesilirsin. 

Mektebinde okudun, kıvırmayı bilirsin! 

Merakım, gidişiniz  bir  ilahi aşka mı? 

Yoksa din dediğiniz, İslamlıkdan başka mı? 

Din adına yol kesen dünkü yobazın oğlu! .. 

Yine sen kesiyorsun, küfür uğrunda yolu! ..* 



*Necip Fazıl  Kısakürek', 'Duydunuz mu muhterem, neler neler diyormuş?  Çok üzgünmüş bu sıra, din elden gidiyormuş!  Zavallının saksımı, düşmüş yoksa başına?  Belki in...', ARRAY['Türk Edebiyatı','Şiir','Kadir Soytürk']::text[], 8.5, '{"poet":"Kadir Soytürk","poet_slug":"kadir-soyturk","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/saksi-mi-dustu-yoksa-basina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hoşcakal', 'hoscakal-sair-shimalwest-9nu0l', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'zor bunu söylemek herşeyden

ama artık ölüyorum ben

nolurki biraz daha doktor dinlesem

başka ne eklenirki birkaç günden geceden

ömür dediğin elbet bitecek

ama sıralı ama sırasız

ama zamanlı ama zamansız

rolüm bu kadarmış demekki

bu koskoca sahnede

görebilecekmiyim burayı

gittiğim yerden

hiç sevmedim veda etmeyi

bilemedim hoşcakal demeyi

sanki öylesine bir gidiş gibi

dönüp gideyim gelecek gibi', 'zor bunu söylemek herşeyden ama artık ölüyorum ben nolurki biraz daha doktor dinlesem başka ne eklenirki birkaç günden geceden ömür dediğin ...', ARRAY['Türk Edebiyatı','Şiir','Şair Shimalwest']::text[], 8.5, '{"poet":"Şair Shimalwest","poet_slug":"sair-shimalwest","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/hoscakal-51-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hep Seninle', 'hep-seninle-serkan-aytek-j6sk1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ne derlerse desinler,

Ben yine bensem

Ve sen yine sen olacaksan

Yani şimdiki gibi

                Yani şuan gibi

                               Ve gelecekte ki gibi

Yine seni seveceğim.

Ve yine sonsuz seveceğim

Hayatın anlamı gibi

Yaşamın sonsuz hazzı gibi

Bir gül yaprağında

             Bir çiğ damlasında

                         Ve bir özgürlük sabahında

Senin yanına geleceğim

Seni çok seveceğim.

Sensizliğin sessizliğini

Kuşların şen cıvıltısını

Başka bahara bıraktım bu gece

Nasılsa sen hep benimle

                   Ben hep seninleyim

Dünyanın tüm sabahlarında

                       kainatın tüm akşamlarında

Seni çok severken

HEP SENİNLEYİM.', 'Ne derlerse desinler, Ben yine bensem Ve sen yine sen olacaksan Yani şimdiki gibi                 Yani şuan gibi                            ...', ARRAY['Türk Edebiyatı','Şiir','Serkan Aytek']::text[], 8.5, '{"poet":"Serkan Aytek","poet_slug":"serkan-aytek","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/hep-seninle-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Babamı Verin Bana!', 'babami-verin-bana-muharrem-ozturk-x0fme', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ben ölüm ne bilmezdim,

Seni görmeden önce.

Ve Babamı özlememiştim hiç bu kadar.

Şimdi nerde? 

Ben düşman ne bilmezdim,

Seni görmeden önce.

Ve hiç görmek istemezdim seni,

Babamın öldüğü yerde.

Bana Babamı verin! 

Verin canlarımızı.

Kefen o kadar kolaysa,

Kendiniz girin! .', 'Ben ölüm ne bilmezdim, Seni görmeden önce. Ve Babamı özlememiştim hiç bu kadar. Şimdi nerde?  Ben düşman ne bilmezdim, Seni görmeden önce. V...', ARRAY['Türk Edebiyatı','Şiir','Muharrem Öztürk']::text[], 8.5, '{"poet":"Muharrem Öztürk","poet_slug":"muharrem-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/babami-verin-bana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yoruldum', 'yoruldum-mehmet-lutfu-aydin-v99yl', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ağlamaktan yoruldum, yüzüm gülmedi bir gün

Acılarla arkadaş, tasalarla dost oldum

Bir türküyüm dillerde, yad ellerde bir sürgün

Andıkça gül yüzünü, içtim içtim, mest oldum', 'Ağlamaktan yoruldum, yüzüm gülmedi bir gün Acılarla arkadaş, tasalarla dost oldum Bir türküyüm dillerde, yad ellerde bir sürgün Andıkça gül ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Lütfü Aydın']::text[], 8.5, '{"poet":"Mehmet Lütfü Aydın","poet_slug":"mehmet-lutfu-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/yoruldum-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dar Gelir Bedene Can Denilen Elbise', 'dar-gelir-bedene-can-denilen-elbise-fehmi-yakut-cpozw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Göz kırpımı bir zamandır ömür dediğin,

Helalinden olsun kursağında, yediğin.

Yol azığın ancak, elin ile verdiğin,

Malı biriktirip, arşa vursan ne çıkar? 

Ömür Hak''ka varan yolda sırlı basamak,

Aslolan imtihan, bahanedir yaşamak.

Gaye dolu heybe ile menzile varmak,

Yalancı dünyada saray kursan ne çıkar? 

Vakit tamam olup, hak sahibi gelirse,

Dar gelir bedene, can denilen elbise.

Gönlündeki asıl evde dostun yok ise,

Abıhayat iksirini bulsan ne çıkar? 

Ademoğlu Fehmi sen de kendini tanı,

Nankör nefsin için oyalama zamanı.

Teslim ol dostuna, sevindirme düşmanı.

Şu fani dünyada bin yıl kalsan ne çıkar?', 'Göz kırpımı bir zamandır ömür dediğin, Helalinden olsun kursağında, yediğin. Yol azığın ancak, elin ile verdiğin, Malı biriktirip, arşa vurs...', ARRAY['Türk Edebiyatı','Şiir','Fehmi Yakut']::text[], 8.5, '{"poet":"Fehmi Yakut","poet_slug":"fehmi-yakut","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/dar-gelir-bedene-can-denilen-elbise-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boncuk Gözlüm-1-', 'boncuk-gozlum-1-ahmet-kaytanci-52nyj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ne sevda şiirleri yazdım

Ne aşk türküleri besteledim

Ne gözlerimi düşman ettim uykuya

Ne ismini tekrarladım doyasıya

Ama hep seni bekledim Boncuk Gözlüm

Gelirsin diye.

Gelir de bağrıma vurursun diye

Asma kilitlerini söktüm gönlümün

Karanfiller,güller taktım çengeline

Gelmedin Boncuk Gözlüm

Beğenmedin kırmızı karanfillerimi

Almadın beyaz güllerimi,

Pamuksu ellerine.

Yağmur bulutlarına dualar gönderdim

Rahmetine boğulmak için

Bazen gözlerimin önüne gelir

Hilal gibi kaşın,

Zümrüt gibi saçın.

Sen nesin böyle Boncuk Gözlüm? 

Söyle nesin? 

Şakağında kırmızı güller açan

Ceylan gibi erişilmez dağlara kaçan

Benden benliğimi alıp

Beni sensizliğe saçan.

İçimizdeki Ses: Sayfa:70', 'Ne sevda şiirleri yazdım Ne aşk türküleri besteledim Ne gözlerimi düşman ettim uykuya Ne ismini tekrarladım doyasıya Ama hep seni bekledim B...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Kaytancı']::text[], 8.5, '{"poet":"Ahmet Kaytancı","poet_slug":"ahmet-kaytanci","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/boncuk-gozlum-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilinmezler Hakk''ın Sırrı', 'bilinmezler-hakk-in-sirri-engin-namli-xpksu', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Şu kainat uçtan uca

Gizemli boş bir bulmaca

Kul kalbini yorar anca

Bilinmezler Hakk''ın sırrı

Kainatın Yüce yarı

Yaratırken yoğu varı

Ruha sundu aşkı arı

Bilinmezler Hakk''ın sırrı

Çağdan çağa kuşak kuşak

Karış karış zihni oysak

Yeri göğü kurcalasak

Bilinmezler Hakk''ın sırrı

Ne gelen var ne gitmeyen

Yoktur ömrü hiç bitmeyen

Şu alemi terk etmeyen

Bilinmezler Hakk''ın sırrı

Her tarifin anlam gücü

Demle gelir ölçü ölçü

Ebede dek dolmaz içi

Bilinmezler Hak''kın sırrı

Derin hisler sinede kor

Ateşine yanmak çok zor

Katlanmakla kalınmıyor

Bilinmezler Hakk''ın sırrı

ENGİN NAMLI  23:42 01.01.2005', 'Şu kainat uçtan uca Gizemli boş bir bulmaca Kul kalbini yorar anca Bilinmezler Hakk''ın sırrı Kainatın Yüce yarı Yaratırken yoğu varı Ruha su...', ARRAY['Türk Edebiyatı','Şiir','Engin Namlı']::text[], 8.5, '{"poet":"Engin Namlı","poet_slug":"engin-namli","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/bilinmezler-hakk-in-sirri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anneciğim', 'annecigim-selcuk-cosar-8neer', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Başkaların Annesi Anne olmuyor 

Yaksa da kınası girmiyor 

Annesizlik o kadar zor ki 

Senin yokluğun bende ne ben koydu ne de benden bir eser, Anne 

Dünyanın en kötü Annesi bile olsan yine seni isterim 

Yüreğimde kor gibi yanan yarama merhem, 

Dinmek bilmeyen göz yaşlarıma mendil, 

Sonu gelmeyen dizelerime nokta olurdun Anne 

Bir sıkıntım olsa koşardım yanına 

Sarılırdım o hiç sarılmadığım kollarına 

Benim Annem Annem diye bağırırdım avazım çıktığınca semaya 

Sesime şahit olurdu yer ve gökteki hareketli ve hareketsiz 

tüm varlıklar 

Hep bunu isterdim olmadı olmayacak da Anne 

Şunu bilesin ki seni hiç affetmeyeceğim 

Allah''u Taala bütün kullarını affedermiş ama olsun 

Beni benliğimle yaşatmadın, yaşayamadım da 

Yine de diyorum ki cennette mekanın olsun Anne 

20.03.1998 

Nail Selçuk', 'Başkaların Annesi Anne olmuyor  Yaksa da kınası girmiyor  Annesizlik o kadar zor ki  Senin yokluğun bende ne ben koydu ne de benden bir eser...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Coşar']::text[], 8.5, '{"poet":"Selçuk Coşar","poet_slug":"selcuk-cosar","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/annecigim-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Be Sevgili', 'be-sevgili-selcuk-cosar-sllkt', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sensizlik o kadar zor ki 

Ağlaya ağlaya viran oldum 

Gözlerimden akan damlalar göle dönüştü 

Hep böyle mi olacak 

Böyle mi kalacak be sevgili 

Biliyorum hayal perestimsin 

Gönlümde gezer durursun 

Yani rüyalarımın kadınısın 

Kavuşmamız ise Leyla ile Mecnun misali 

Hayat bu be sevgili 

Zor, günler çok zor geçiyor 

Kilometre saati de sona yaklaşıyor 

Ha bugün ha yarın derken 

Zaman galip gelecek 

Bu son hüsranla bitecek be sevgili 

Nail Selçuk', 'Sensizlik o kadar zor ki  Ağlaya ağlaya viran oldum  Gözlerimden akan damlalar göle dönüştü  Hep böyle mi olacak  Böyle mi kalacak be sevgil...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Coşar']::text[], 8.5, '{"poet":"Selçuk Coşar","poet_slug":"selcuk-cosar","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/be-sevgili-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüya', 'ruya-ek-yurek-8as7p', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yokluğun ölüm,

Varlığın rüya,

Ne olur uyandırma...', 'Yokluğun ölüm, Varlığın rüya, Ne olur uyandırma......', ARRAY['Türk Edebiyatı','Şiir','Ek Yürek']::text[], 8.5, '{"poet":"Ek Yürek","poet_slug":"ek-yurek","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/ruya-158-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Döngü', 'dongu-selcuk-cosar-boib7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bu dünyada yaşananlara aklım almıyor! 

Ne tarihler yazıldı bu insanlık için 

Ne ana kuzuları verildi bu topraklara 

Ne ağıtlar yakıldı Ahmet, Mehmet, Hans ve diğerlerine 

Haklı ve haksız nedenler uğrunaydı bu yaşananlar 

Yani; çıkar, açgözlülük, etnik, egemenlik, hürriyet vb… 

Bugün, dünden farklı değil 

Tarihler ise, hep aynı tarih 

Tekrar ede durur 

Bakın yine, 

Bosna-Hersek, Filistin ve Irak’ta yaşatılanlarla; 

Gün yüzü görmemiş yavrucaklar, 

Muradına erememiş gençler, 

Dünyalığı yarım kalmış, ana ve babalar, 

Can, canan ve geleceğini veriyor. 

Hem de içimizi yakarcasına ve de bizlerde iz bırakarak! 

Geçmişini bilemeyenler, geleceğini tayin edemezler 

Hele hıyanet içinde olanlar, 

Bir gün olur hesabını öderler. 

Ama fatura yine bize, size olur 

Yani; tarihler, ana kuzuları ve ağıtların tekrarı yaşanır, durur 

Biz insanlığın acıları ise, unutulmaya bırakılır 

Unutulur unutulur, ve de arkasından tekrarı gele durur 

Nail Selçuk', 'Bu dünyada yaşananlara aklım almıyor!  Ne tarihler yazıldı bu insanlık için  Ne ana kuzuları verildi bu topraklara  Ne ağıtlar yakıldı Ahmet...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Coşar']::text[], 8.5, '{"poet":"Selçuk Coşar","poet_slug":"selcuk-cosar","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/dongu-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen ve Şiir', 'sen-ve-siir-orhan-tez-cwj5s', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sana şiir yazmak istiyorum

Şiir karşı çıkıyor, diyor ki; 

İmge desen o, dize desen o,

Şiir desen o,

Her şeyin şiiri yazılmaz ki, diyor; 

Şiirin ta kendisi o!', 'Sana şiir yazmak istiyorum Şiir karşı çıkıyor, diyor ki;  İmge desen o, dize desen o, Şiir desen o, Her şeyin şiiri yazılmaz ki, diyor;  Şii...', ARRAY['Türk Edebiyatı','Şiir','Orhan Tez']::text[], 8.5, '{"poet":"Orhan Tez","poet_slug":"orhan-tez","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/sen-ve-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçimizdeki Düşman', 'i-cimizdeki-dusman-kadir-soyturk-uagoj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bize bizden gayrı dost yok, deriz de; 

Fakat esas düşmanlar, içimizde!', 'Bize bizden gayrı dost yok, deriz de;  Fakat esas düşmanlar, içimizde!...', ARRAY['Türk Edebiyatı','Şiir','Kadir Soytürk']::text[], 8.5, '{"poet":"Kadir Soytürk","poet_slug":"kadir-soyturk","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/icimizdeki-dusman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geçer', 'gecer-remzi-zengin-73wuf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yaz gelende açar yaylanın gülü

Gül naz eder, ağlatır, şeyda bülbülü

Gizliden sevdası olanın günü

Karşıdan karşıya bakmakla geçer

Küstüysen gel, kara gözlü, barışak

Böyle olmaz, arasıra görüşek

Göremezsem, günler pek zor geçecek

Sonra gözümden yaş akmakla geçer

Vur dediysek sana öldür demedik

Taze açmış gülü soldur demedik

Pir elinden bade doldur demedik

Gönül aşk badesin içmekle geçer

Bülbülün sevdası bilirsin güle

Bülbül bu uğurda çok çekti çile

Eğerki bu sevda düşerse dile

Bu kez ömür kahır çekmekle geçer

Mecnunu çöllere Leyla’sı saldı

Kerem Aslı Han’a tutuştu yandı

Ferhat, Şirin için dağları yardı

Remzi’yi aşk odu yakmakla geçer

(14.10.1987)', 'Yaz gelende açar yaylanın gülü Gül naz eder, ağlatır, şeyda bülbülü Gizliden sevdası olanın günü Karşıdan karşıya bakmakla geçer Küstüysen g...', ARRAY['Türk Edebiyatı','Şiir','Remzi Zengin']::text[], 8.5, '{"poet":"Remzi Zengin","poet_slug":"remzi-zengin","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/gecer-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '-Ocağı Türk,Çeliği Türk,Suyu Türk--', 'ocagi-turk-celigi-turk-suyu-turk-dursun-elmas-lqbmf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '_______________Büyük dâvâ adamı Necdet Sevinç Ağabeyime

Baharı Türkçedir,kışı Türkçedir,

Türküleri Türkçe,marşı Türkçedir,

Sevdaları Türk''çe,düşü Türk''çedir,

Kâğıdı Türk, kalemi Türk, sözü Türk! 

Kırk yıldır,bu yolda savaş veriyor,

Türkçe düşünüyor,Türk''çe görüyor,

Nakış nakış,Türk Ülküsü örüyor,

İlmeği Türk, deseni Türk, yünü Türk! 

Türklük dâvâsına gönül vereli

Turan''a sevdalı o günden beri.

Dönmedi bir adım yolundan geri

Mayası Türk, hamuru Türk, tuzu Türk! 

O''nu tanıyıpta sevmemek olmaz

Dâvâyı,çileyi bilmemek olmaz

Türklüğün uğruna ölmemek olmaz

Kavgası Türk, sevdası Türk, nazı Türk! 

El etek öpmeyi hiç tanımadı

Zindanlar,sürgünler hiç yıldırmadı

Kurşunlar yağdı da hiç aldırmadı

Ocağı Türk, çeliği Türk, suyu Türk! 

Sürgünü istendi altmış seneye

Turancı,Türkçüdür,gerici diye

Beş yılını verdi ''taşmedreseye''

Dâvâsı Türk, devası Türk, hazı Türk! 

Huy kapmış,ırkının soylu huyundan,

Ruhunu kandırmış,Orkun suyundan

Nesli Oğuz nesli,Türkmen boyundan,

Çiçeği Türk, kovanı Türk, balı Türk! 

Zalimlere karşı çelik bilekli

Mazlumun yanında yufka yürekli.

Türk oğlu Türk,hem de Antep''li

Hücresi Türk, genleri Türk, kanı Türk!', '_______________Büyük dâvâ adamı Necdet Sevinç Ağabeyime Baharı Türkçedir,kışı Türkçedir, Türküleri Türkçe,marşı Türkçedir, Sevdaları Türk''çe...', ARRAY['Türk Edebiyatı','Şiir','Dursun Elmas']::text[], 8.5, '{"poet":"Dursun Elmas","poet_slug":"dursun-elmas","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/ocagi-turk-celigi-turk-suyu-turk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahar Geliyor', 'bahar-geliyor-remzi-zengin-nud2a', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dudağın şekerdir, bal mıdır sözün

Asma suratını, hep gülsün yüzün

Yaprağın dökse de ağaçlar güzün

Ardından yemyeşil bahar geliyor

Gurbete gidenler dönecek bir gün

Ağlayanlar elbet gülecek bir gün

Bekleyen murada erecek bir gün

Yeter ki sabreyle bahar geliyor

Daha güz ayında olabiliriz

Kışın soğuğunda kalabiliriz

Ararsak, gönülde bulabiliriz

Yeterki ara sen, bahar geliyor

Kar yağsa, buz olsa, sen çekme tasa

İsterse doğudan güneş doğmasa

Kendine dert etme, düşme hiç yasa

Yarından da yakın bahar geliyor

(9.11.1987)', 'Dudağın şekerdir, bal mıdır sözün Asma suratını, hep gülsün yüzün Yaprağın dökse de ağaçlar güzün Ardından yemyeşil bahar geliyor Gurbete gi...', ARRAY['Türk Edebiyatı','Şiir','Remzi Zengin']::text[], 8.5, '{"poet":"Remzi Zengin","poet_slug":"remzi-zengin","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bahar-geliyor-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Göre Göre', 'gore-gore-kadir-hasirci-95xxz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sana dair ne varsa yüreğimde 

Unuttum gidişinde bilesin.

Sana dair ne varsa dilimde 

tükürüp attım lanet ederek

Sana dair bir tek şey kaldı ise, 

Parmak uçlarımda 

O da buğulu camlara yazdığım adın. 

Vazgeçemiyorum.

Adın eriyip giderken bıraktığı lekeleri göre göre...', 'Sana dair ne varsa yüreğimde  Unuttum gidişinde bilesin. Sana dair ne varsa dilimde  tükürüp attım lanet ederek Sana dair bir tek şey kaldı ...', ARRAY['Türk Edebiyatı','Şiir','Kadir Hasırcı']::text[], 8.5, '{"poet":"Kadir Hasırcı","poet_slug":"kadir-hasirci","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/gore-gore-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüya', 'ruya-remzi-zengin-1823k', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Rüyamda kirpiği batmış gözüne

Kömür gözden yaşlar akmış yüzüne

Koydum da başını iki dizime

O hain kirpiği çıkarıp aldım

Görür müyüm acep yine yüzünü

Gelme, git dedim de üzdüm özünü

Bin kere tartsam da bir çift sözümü

O kaşı karanın gönlünü kırdım

Dilim git dese de, gönül gel diyor

Sözüm doğru değil, böyle bil diyor

Sebebini ara sen de, bul diyor

Ben sebepsiz yere çöllere daldım

Türkiye vatanım, Tokat’tır ilim

O dostu küstürdüm, kurusun dilim

Kimseye diyemem ben kendi halim

Bir kuru dal gibi ortada kaldım

(13.10.1987)', 'Rüyamda kirpiği batmış gözüne Kömür gözden yaşlar akmış yüzüne Koydum da başını iki dizime O hain kirpiği çıkarıp aldım Görür müyüm acep yin...', ARRAY['Türk Edebiyatı','Şiir','Remzi Zengin']::text[], 8.5, '{"poet":"Remzi Zengin","poet_slug":"remzi-zengin","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ruya-159-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Leylâ''dır Söylenir', 'bir-leyl-dir-soylenir-ali-riza-unal-321di', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir  Leylâ''dır söylenir, na  ehilin yoz dilinde

O secdeyi Rahman''dır, vahdeti sır ile ilimde

Vermeyin onu zan-ı şehvete, destan-ı dile

Yetmez  idrâkı takâtin, o sırrı eksik eteğe

Çekemezsin o vebali, heder olur  kudretin

Erseydin o ezeli hilkâtı  gerçeğe

Şaşırırdın, zevki sefâ olduğun o şehveti gerdeğe', 'Bir  Leylâ''dır söylenir, na  ehilin yoz dilinde O secdeyi Rahman''dır, vahdeti sır ile ilimde Vermeyin onu zan-ı şehvete, destan-ı dile Yetme...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/bir-leyla-dir-soylenir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aldanma Sakın', 'aldanma-sakin-cenk-aksal-s9sch', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Aldanma kimsenin sözlerine

Yıkmak istiyorlar

kurduğumuz mutlu dünyayı

Mutluluk vaad eden,

her dost yüz yalancı

Kıskanıyorlar senelerdir süren,

hayat arkadaşlığımızı

Karartmak istiyorlar,dünyamızı

inanma ne olursun,

Dost değil onlar sevginin düşmanı...

12/05/1981', 'Aldanma kimsenin sözlerine Yıkmak istiyorlar kurduğumuz mutlu dünyayı Mutluluk vaad eden, her dost yüz yalancı Kıskanıyorlar senelerdir süre...', ARRAY['Türk Edebiyatı','Şiir','Cenk Aksal']::text[], 8.5, '{"poet":"Cenk Aksal","poet_slug":"cenk-aksal","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/aldanma-sakin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vuslatı Gönül Kapısı', 'vuslati-gonul-kapisi-ali-riza-unal-6opam', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Vardım  kâbe-i gönül bab-ına

Açıldı sırrı Leylâ ten ile canıma

Gayrı  salmışım meylimi masivâya

Teslimi ram-ım takdiri bahtıma

Nuş-u hakikâtim, gayrı vermişim sırrıma

Tövbeler tövbesi hevâyı zannıma

Seyranım zaman içre nefsim ile zatına

Dür ettim Leylâ''yı pinhanı zatıma

Cehline o şehveti Leylâ, vuslatı Mevlâ''dır canıma

Bir deryayı ummandır, sığmaz o cüsseyi Leylâ zanına

Çekmişim na ehile perdeyi, peçesiz hicabıma

Ayandır habibi püryan, her cem ile varıma

Seyrandır o garibi üryân, her dem ile visali arıma', 'Vardım  kâbe-i gönül bab-ına Açıldı sırrı Leylâ ten ile canıma Gayrı  salmışım meylimi masivâya Teslimi ram-ım takdiri bahtıma Nuş-u hakikât...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/vuslati-gonul-kapisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hoşçakal', 'hoscakal-cafer-yilmaz-i5sax', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen gidince yıldızlar mı kaybolacak? 

Ay’ı mı koyup cebine kaçıracaksın benden...

Güneşi battığı yere mi zincirleyeceksin? 

Hoşça kal....

Sen gidince deniz kıpkızıl mı olacak? 

Martılar ekmek yemeyecek mi artık...

Ve vapur götürürken birini

Getirmeyecek mi sanıyorsun bir diğerini...? 

Hoşça kal...

Sen gidince yüreğimde mi gidecek? 

İflas mı edecek tüm bedenim...

Ben ölü mü olacağım sen gidince? 

Hoşça kal...

Kapanmış bir yarayı kaldıracak gidişin.

Üç beş damla kan kadarsın işte...

Nasılsa her bahar yaprak açar dal...

Gidiyorsun, sen bilirsin....

Hoşça kal....', 'Sen gidince yıldızlar mı kaybolacak?  Ay’ı mı koyup cebine kaçıracaksın benden... Güneşi battığı yere mi zincirleyeceksin?  Hoşça kal.... Se...', ARRAY['Türk Edebiyatı','Şiir','Cafer Yılmaz']::text[], 8.5, '{"poet":"Cafer Yılmaz","poet_slug":"cafer-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/hoscakal-52-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alaca şafakta bir gün', 'alaca-safakta-bir-gun-cenk-aksal-h1x05', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Alaca şafakta bir gün 

mavzerler kan kusarken birbirlerine

ellerim nasır tutmuş bedenim kaskatı 

beni bu yerlerden göçüp götürecek

deli bir kurşun bekliyorum

gözlerim nefretlenmiş

kan tutmuyor yüreğim

kardeşi kardeşine düşman eden 

bu insanları lanetliyorum

alaca şafakta birgün

yine ölecek bir kaç kişi

meçhule gidenlerin ardından

yavrucaklar yetim kalacak

analar,bacılar,yarlar

ağıtlar yakacak

alaca şafakta birgün

kimse vurmasın,isterdim kardeşini

yetim kalmasın yavrucaklar

ağıtlar yakılmasın

kan kusmasın mavzerler

ve sussun ağlayanlar..', 'Alaca şafakta bir gün  mavzerler kan kusarken birbirlerine ellerim nasır tutmuş bedenim kaskatı  beni bu yerlerden göçüp götürecek deli bir ...', ARRAY['Türk Edebiyatı','Şiir','Cenk Aksal']::text[], 8.5, '{"poet":"Cenk Aksal","poet_slug":"cenk-aksal","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/alaca-safakta-bir-gun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hamdüsenâlâr', 'hamdusen-l-r-ali-riza-unal-5mnpe', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seyran olurum, iki kaş arasından didârı Mevlâ''ya

Vakıfım baş gözünden o ledünni deryaya

Kalmadı hayvanı şehvetim, visali servetim

Bir garip sır ile vücudu Leylâ''ya

Bulmuşum cevheri yokluk devletim

Her alemi cemde kesret ile halvetim

Olamam ne çoban yıldızı ne Süreyyâ

Alem zatımda zerreyi küre değil münezzehim

Her demde hamdüsenâlar, O vahdeti Mevlâ''ya...', 'Seyran olurum, iki kaş arasından didârı Mevlâ''ya Vakıfım baş gözünden o ledünni deryaya Kalmadı hayvanı şehvetim, visali servetim Bir garip ...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/hamdusenalar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yolcuyuz', 'yolcuyuz-serife-goksel-tdc9u', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'yolcuyuz yolumuz bitermi? 

insaniz insanligimiz bitermi? 

biteriz bitmelerimiz  yitermi? 

aslinda yitigiz her baslangicta...

bitisigiz hayatla oysa

Dünya döndüredursun bizi! 

ufacik bebekler uyuyadursun bihaber

kendinden habersiz yarisadursun millet! 

savasadursun ølümden bihaberler! 

bihaber adalet ugrasadursun onlarla

kosadursun Dünya dan bihaber deliye dokunmayin! ! 

biz hala merdivenlerden cikaduralim

ezedururken bizi onlar! 

biz hala yazaduralim

acliktan øledururken tokluktan bihaberler..

onlar güledursunlar dokunmayin! 

biz de hala yasiyaduralim..

biz  hala üzüduralim kendimizi! 

yarindan bihaber!', 'yolcuyuz yolumuz bitermi?  insaniz insanligimiz bitermi?  biteriz bitmelerimiz  yitermi?  aslinda yitigiz her baslangicta... bitisigiz hayat...', ARRAY['Türk Edebiyatı','Şiir','Şerife Göksel']::text[], 8.5, '{"poet":"Şerife Göksel","poet_slug":"serife-goksel","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/yolcuyuz-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vuslat Yolu', 'vuslat-yolu-ali-riza-unal-u3rq7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Düşmüşem küfrânı küfürden vuslat yoluna

Sel oldu göz yaşlarım, baş edemedim

Söverdim zengine, acırdım fakire

Can ile malı, mülkü hep hakkın imiş

Üç akçeyi pul edip, aş edemedim

Ne akıllı ne deli ne de ermiş veliyim

Düştü ten ile canım sevdayı aşka

Kul Rıza, ayanı Mevlâ bir başka

Şu divane gönlümü baş edemedim..', 'Düşmüşem küfrânı küfürden vuslat yoluna Sel oldu göz yaşlarım, baş edemedim Söverdim zengine, acırdım fakire Can ile malı, mülkü hep hakkın ...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/vuslat-yolu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzay Dünyadan..', 'uzay-dunyadan-serife-goksel-nm33p', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'yillar dagitmis kendini

pejmurde günler

basibos gecip gider kapimin ønü

kaldirimlar eskiyip durur..

bir bardak su gibi

durur gøzümün ønünde hayaller

gelecek tedirgin

umutlar bicare..

Dünya dagitmis kendini

hercai günler

basibos kalemimle

yazip duruyoruz durmadan

bir ask gerek siire

yada hayata bir nefes

ne bileyim der gibi gecip giderken yillar...

serce kanatlariyla

suya vuruyor kabuslarin gülüsü

beklemeler hep ayni duraklarda..

yillar hep daginik..

günler hep pejmurde

aliskanliklar tekerleginde

beyni durur zorun..

bikkin odalar

bitkin yollar..

gøzleri kapali 

saclari darmadagin 

øylesine esen

endamli bir rüzgar..

yaslaniyorum derken yeseren agaclar

anlamsiz yaslar gøzlerinde yapraklarin..

su sessizlikten derinmi uzayin sessizligi diye sorarken 

o kuyu 

her gece 

yildizlara..

yildizlar asik

yildizlar sagir..

Ay kadar kørdür kuyu...

o

bu kadar karanlik

ve o kadar dipsizmi? 

Uzay

Dünya´dan

diye sorarken 

beklemek coktan gitmistir 

o´nu duymadan..', 'yillar dagitmis kendini pejmurde günler basibos gecip gider kapimin ønü kaldirimlar eskiyip durur.. bir bardak su gibi durur gøzümün ønünde ...', ARRAY['Türk Edebiyatı','Şiir','Şerife Göksel']::text[], 8.5, '{"poet":"Şerife Göksel","poet_slug":"serife-goksel","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/uzay-dunyadan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Leylâdır Bilinmez', 'o-leyl-dir-bilinmez-ali-riza-unal-458e8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'O Leylâ''dır bilinmez, hal ehlinin  naz dilinde

O secdeyi Rahman''dır sır ile haz  ilinde

Saçmışım tenden töreyi, zünnâr belimde

Gelsin cehd ile yol bulan, beklerim can evimde

Açayım o bab-ı sarayı, düreyim hicabıma

Alayım o mahremi yar-ı, visali can evimde', 'O Leylâ''dır bilinmez, hal ehlinin  naz dilinde O secdeyi Rahman''dır sır ile haz  ilinde Saçmışım tenden töreyi, zünnâr belimde Gelsin cehd i...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/o-leyladir-bilinmez-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ömre Bedelmiş', 'omre-bedelmis-volkan-yoruc-vzyzq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bilirmisin her saniye bir ömre bedelmiş

Şimdi anlamışım

O geçen mevsimlerde uçan kuşların hepsi tükenmiş

Tüm açan çiçeklerin hepsi soluk kalmış 

Bilirmisin her saniye bir ömre bedelmiş

Yaşamışlığın acısı şimdi yanmakta içimde

Tutkunu olduğum sen bile artık düşlerde

Mavi gökyüzünde bir ufuk gibi görünürsün gözlerimde

Bilirmisin her saniye bir ömre bedelmiş

Anlamışlığın acısı şimdi tırmalar yüreğimi

Ağlamak bile boşuna gelir olmuş 

Gayrı bakamam artık sana,bende vardır artık yeni mazi

Bilirmisin her saniye bir ömre bedelmiş

Şimdi anlamışım,kusura bakma artık unutmuşum seni', 'Bilirmisin her saniye bir ömre bedelmiş Şimdi anlamışım O geçen mevsimlerde uçan kuşların hepsi tükenmiş Tüm açan çiçeklerin hepsi soluk kal...', ARRAY['Türk Edebiyatı','Şiir','Volkan Yoruç']::text[], 8.5, '{"poet":"Volkan Yoruç","poet_slug":"volkan-yoruc","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/omre-bedelmis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yürüyün', 'yuruyun-serife-goksel-6dp54', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'beni bulun yitirdiginiz gibi

kirgin degilim kimseye

vicdani görün birakin kini

hicbirinize kirgin degilim

yeterki kirmayin gülüsleri

kendinizi sevin ki sevin insanlari

sevisin vicdaninizla

døvusmeyin! 

yalani dügümleyin nefrete

asin seytanin yarasir boynuna

onada firsat vermeyin! 

nefsínizi sabrin elleriyle tutun

tutun ki

tuttugunuz yol cennetin kapisindan gecsin...

gecsin gitsin bu yapboz zamanlar

zaman sinavli bu  pilli Dünya´da

sakin nesenizin pili bitmesin..

varsin bitmesin üzüntüler

kederlere sevinin

sevinin ki sansli oldugunuza

Allah c.c nin rahmeti yagarken üzerinize..

her damla gözyasinizda.....

bekleyin nefsiniz avuclarinizda

sabirlardan ørülü köprüden 

huzurun nesesiyle yürüyün

sakin...

huzurlu..

ferahca...

ve insanca...

yürüyün...', 'beni bulun yitirdiginiz gibi kirgin degilim kimseye vicdani görün birakin kini hicbirinize kirgin degilim yeterki kirmayin gülüsleri kendini...', ARRAY['Türk Edebiyatı','Şiir','Şerife Göksel']::text[], 8.5, '{"poet":"Şerife Göksel","poet_slug":"serife-goksel","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/yuruyun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üstün den Acı Keder Kalktımı?', 'ustun-den-aci-keder-kalktimi-ozkan-sahin-mymul', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'yıllardır ertelemiş olduğun aşk,

geliyor du üstüne üstüne,

acı feryat için de pişmanlık,

taşar gözyaşına yüreğine.

anlamış olmansa yılları aldı,

benide onu beklemem yaktı.

mutluyum artık anlamıştı beni,

yeterince çekmiştik seni acı,

gözbebeğim uslandın ağlamaktan,

üstün den acı keder kalktı mı? 

lale bahçesinde olmadan! 

aşkı anladın mı vazgeçilmez miş,

yıllar üstün den geçsede ölmez miş.

               25-9-2002', 'yıllardır ertelemiş olduğun aşk, geliyor du üstüne üstüne, acı feryat için de pişmanlık, taşar gözyaşına yüreğine. anlamış olmansa yılları a...', ARRAY['Türk Edebiyatı','Şiir','Özkan Şahin']::text[], 8.5, '{"poet":"Özkan Şahin","poet_slug":"ozkan-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ustun-den-aci-keder-kalktimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalan...', 'yalan-zulfikar-yapar-kaleli-nn50y', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hakikat bağının çiçeği solmaz,

İnsanı yitiren ol yalan imiş.

Boşa koydum dolmaz, dolusu almaz

Dünya denen kabir, bol yalan imiş.

Aşık biri çıkıp çıra yakmadı,

Denizdeki balık, suya bakmadı,

Dünyayı eledim, deni çıkmadı,

Sağda hakikat yok, sol yalan imiş.

Sanmayın dünyada yan gelip yattım,

Gözümde, çıbanın gözüne battım,

Ay tuttum, yıldıza mızrak uzattım,

Kabe’den öteye, yol yalan imiş.

Dünyayı sırtına vurdum devenin,

Deve ki çamuru, tozu ovanın,

Halini anladım sırlı kovanın,

Sevdasız kovanda bal yalan imiş.

Birbirine kattım şekerle, tuzu

Kurt koyunu sever, emzirir kuzu,

Gönül diyarının. besmele pozu,

Ayak basiretsiz, kol yalan imiş.

Aradım, taradım, dedim, Kaleli’m

Biri mazi, biri atide elim,

Bulutlar edalım, güneş cilvelim,

Marifet tohumda, döl yalan imiş.

Şairler Neslişah1 grubunun ''yalan'' konulu aktivitesi için yazıldı.', 'Hakikat bağının çiçeği solmaz, İnsanı yitiren ol yalan imiş. Boşa koydum dolmaz, dolusu almaz Dünya denen kabir, bol yalan imiş. Aşık biri ç...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/yalan-126-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Birde sen olsan', 'birde-sen-olsan-serife-goksel-evxso', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'gece gelir pencereme

bir tesbih  cikarir cebinden

simsekle kopar sabrinin ipi

dizer yildizlari sakince pencereme...

sessizlik seyreder odalari

odalar beni gøzler

her gece bu saatlerde

bir citirti kopar kalbinde

kücük odanin...

korkutur yalnizligi..

sefkat ister bilirim..

gørmez gøzleri rutubetinden artik...

bilirim..

gece hazirlanir gitmeye..

gitme derim kal biraz daha..

günese kirginim der..

bir telas toplar yildizlari ceplerine

birini birak gözlerimde derim..

sana emanet der gider...

sessizlik misafirdir her gece nefesime

bazen Sezen´de gelir oturur yanima..

minik serce konar cama

efkar efkar cirpinir kanatlari

mutfak caydanlikla fisildasir

ah birde sen olsan derim..

sezen ben ve emanet yildiz 

efkar efkar cirpinan serceyi seyrederiz.

sigaramiz tüter 

gülüsür kelimeler

aklimiz sende

sezen ben ve emanet yildiz

biz hep seni søyleriz..', 'gece gelir pencereme bir tesbih  cikarir cebinden simsekle kopar sabrinin ipi dizer yildizlari sakince pencereme... sessizlik seyreder odala...', ARRAY['Türk Edebiyatı','Şiir','Şerife Göksel']::text[], 8.5, '{"poet":"Şerife Göksel","poet_slug":"serife-goksel","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/birde-sen-olsan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öğrenemedim', 'ogrenemedim-dursun-onal-fg1nq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gecemidir insanı hüzünlendiren

Yoksa insanmıdır hüzünlenmek için geceyi bekleyen

Gecemidir seni bana düşündüren

Yoksa benmiyim seni düşünmek için geceyi bekleyen

Önce düştüğümde kalkmayı öğrendim

Sonra aleve dokunduğumda acıyı

Sevmeyi öğrendim sevilmeyi

Sonra terkedilip beklemeyi

Sayende unutulmayı da öğrendim

Herşeyi öğrendimde

Yalnız unutmayı öğrenemedim

Kimbilir hangi akşam güneşle bende söneceğim

Kimbilir hangi ellerden son suyumu içeceğim

Belki göremeden öleceğim

İnan ki seni ebediyen seveceğim', 'Gecemidir insanı hüzünlendiren Yoksa insanmıdır hüzünlenmek için geceyi bekleyen Gecemidir seni bana düşündüren Yoksa benmiyim seni düşünmek...', ARRAY['Türk Edebiyatı','Şiir','Dursun Onal']::text[], 8.5, '{"poet":"Dursun Onal","poet_slug":"dursun-onal","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ogrenemedim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Masal Çocuk', 'masal-cocuk-volkan-yoruc-k9wi1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ne bir başka ülkedeymiş

Ya da kitapta bir kahraman

Bir masal çocukmuş

Özlemlerle aramızda yaşayan

Onunda hayalleri varmış

Gözlerinde yanan ateşiyle delice bakan

Bulut kadar beyaz düşleriyle

Masal çocukmuş aramızda yaşayan

Ne leylekler getirmiş

Ya da gelmiş pembe rüyalardan

Onunda bir emeli varmış

Masal çocukmuş bizim gibi yaşayan

Ejderhaları yalanmış

Kılıcıda bir kırmızı gül olan

Gülümsemelerle bize uzaklardan bakan

Bir masal çocukmuş dünyamızda yaşayan', 'Ne bir başka ülkedeymiş Ya da kitapta bir kahraman Bir masal çocukmuş Özlemlerle aramızda yaşayan Onunda hayalleri varmış Gözlerinde yanan a...', ARRAY['Türk Edebiyatı','Şiir','Volkan Yoruç']::text[], 8.5, '{"poet":"Volkan Yoruç","poet_slug":"volkan-yoruc","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/masal-cocuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlamın Sözüme Düşer..', 'anlamin-sozume-duser-orhun-basat-5yhzw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '...................................................“ bir şey duydum, yalnızlığım; 

...................................................  yılbaşıymış bu gece..... “

Sen benim eksiğimsin 

Uykularıma egemen tutkum 

Bir ucuna sessizce tutunduğum  / gün kokulum..

Bu gece seni 

Zeytin çiziği gözlerinde çocukların 

Ve sana terleyen yanımda uyuttum..

Gün ışır / uykun düşer yüzüme

İçime /  yüreğime adın

Dudağıma su damlası..

Anlamın sözüme düşer..

Uyanır sevdam / yıkar günün yüzünü

Yanık bir türküye doğar güneş 

Başlar özlemin üçer beşer..

Tutar bir dizesi elimden / yarım kalmış bir şiirin 

Gözlerine sürükler..

Daralırım..

Çarpar bedenime gecenin uykusuzluğu 

Unutup gözlerimi resminde

Uyur kalırım..', '...................................................“ bir şey duydum, yalnızlığım;  ...................................................  yılb...', ARRAY['Türk Edebiyatı','Şiir','Orhun Basat']::text[], 8.5, '{"poet":"Orhun Basat","poet_slug":"orhun-basat","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/anlamin-sozume-duser-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seninle olmak', 'seninle-olmak-dursun-onal-svmkc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Güller dikenler arasında biter

İnciler denizin dibinde

Salıverme kendini kendin için değilki 

Sevgilim yad ellerde bilmem gelirmiki

Ayrı ayrı yerlerde ama birbirimiz için

Hiç bir zaman belki her zaman için

Yaşamak haram bana sen olmadığın için

Varoldum ben her zaman seninle olmak için', 'Güller dikenler arasında biter İnciler denizin dibinde Salıverme kendini kendin için değilki  Sevgilim yad ellerde bilmem gelirmiki Ayrı ayr...', ARRAY['Türk Edebiyatı','Şiir','Dursun Onal']::text[], 8.5, '{"poet":"Dursun Onal","poet_slug":"dursun-onal","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/seninle-olmak-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Annem annenlere ziyarete gitti. Biz dağa giderken', 'annem-annenlere-ziyarete-gitti-biz-daga-giderken-erol-dal-9wdl1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen de isyankardın

Ben de...

İki ayrı mevzinin karşısında bulduk kendimizi.

...

Otlayan koyunlara ateş etmemek gibi  gizli kuralımız vardı.

..

Ben vurulmadım; 

Sende vurulmadın.

Vurulmadık...

...

Çoktuk orada

ellerimizde aynı marka tüfeklerle savaştık.

Mevizlerimizde yatmadık

Aldattık

...

İkimizde aldandık bugün.

...

Sesini duydum yüzünü göremeden ayrıldım.

Aklımdasın.

Birbirimize silahı doğrultunca 

önce seslenelim

Ses tanıdık değilse

Düşünmeden 

Vuralım...

Tanıdıksa ses; 

Düşünelim tetiği.

Öylesine; 

içimize akalım.', 'Sen de isyankardın Ben de... İki ayrı mevzinin karşısında bulduk kendimizi. ... Otlayan koyunlara ateş etmemek gibi  gizli kuralımız vardı. ...', ARRAY['Türk Edebiyatı','Şiir','Erol Dal']::text[], 8.5, '{"poet":"Erol Dal","poet_slug":"erol-dal","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/annem-annenlere-ziyarete-gitti-biz-daga-giderken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ateşi YAKAR Güneşim!', 'atesi-yakar-gunesim-asik-sahturna-oucpy', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ateşi yakar Güneşim

                         Yıldızları AVUÇLARIM

                         Doğmadan bin yıllık yaşım

                         İnsanlığı AMAÇLARIM! ...

                              

                                               Dolu aktım, boşa doldum

                                                Denizlere buhar oldum

                                                Güze kışa bahar oldum

                                                Düze çıkar YAMAÇLARIM

                           ŞahTurna şakır dalında

                           Rengim var gülün alında

                           Mazlum insanlık yolunda 

                           Çekildi tel tel SAÇLARIM! ...

Söz ve Müzik: Halk Ozanı Şah Turna (Aşık ŞAHTURNA)   www.sahturna.com

Düzenleme ve Yorum: Ozan ŞİAR Ağdaşan  www.siarcan.com

Almancaya çeviri, Vokaller:  ŞİRİN ŞAFAK AĞDAŞAN Müzik Grubu', 'Ateşi yakar Güneşim                          Yıldızları AVUÇLARIM                          Doğmadan bin yıllık yaşım                        ...', ARRAY['Türk Edebiyatı','Şiir','Aşık Şahturna']::text[], 8.5, '{"poet":"Aşık Şahturna","poet_slug":"asik-sahturna","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/atesi-yakar-gunesim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '...Aşk Süreci...', 'ask-sureci-naime-erlacin-xqaoe', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'şimdi 

aşka değsem tufan

sana değsem yer yarılacak 

kendime dokunsam

kasırga 

göğüsleriz ipi böyle 

neden masumiyettir ateş

sorunun kırbacında 

yanıtın anlamı ne! 

giyinerek biter gün

kendine “sen” katmakla soyunur sonra

soluğumun sesini dinlersin

bilmeyiz hangi karasulara düşer şafak

acıyı bildiğimizdendir kendimizle buluşmak

“bir gökyüzü bitince öteki başlar”*

sonrası aşkı anlamak 

(*)    Arif Damar

(3 Ocak 2005)', 'şimdi  aşka değsem tufan sana değsem yer yarılacak  kendime dokunsam kasırga  göğüsleriz ipi böyle  neden masumiyettir ateş sorunun kırbacın...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ask-sureci-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '...Rağmen...', 'ragmen-naime-erlacin-t9lps', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'ağladığımı görmediniz hiç

kendimi uğurlayıştı benimki

yakıcı hüzün

salkım saçak bir mezata terk ettim

çarmıha gerdiğim dilsiz düşleri

şiire satıldılar 

usla mitos arası 

şaşkındılar 

aşk kaldı bir tek

post-modern çerçeveye sığmaz

görünmez tufan bir de

sararmış matemlerdi 

payımıza düşen

tutuklu

fişli

yasaklı 

onlar ki onca rağmene rağmen

kül duman bahçelerde 

ağlak ve paslı bir kızıla turkuvaz açtırdılar

maviydi yağmur

(3 Ocak 2005)', 'ağladığımı görmediniz hiç kendimi uğurlayıştı benimki yakıcı hüzün salkım saçak bir mezata terk ettim çarmıha gerdiğim dilsiz düşleri şiire ...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ragmen-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilmiyorum', 'bilmiyorum-kenan-sahbudak-5o1k2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Deli miyim divanemi

Yaptığımı bilmiyorum

Sevmeyene sevene mi

Taptığımı bilmiyorum

Güneşe yoksa aya mı

Sütü bozuk bir soya mı

Yanlışa mı doğruya mı

Saptığımı bilmiyorum

Ben cennetin sahibiyim 

Cehennemin ta dibiyim

Sazımdaki tel gibiyim

Koptuğumu bilmiyorum

Der Şahbudak bugün hoşum

Bazen dolu bazen boşum

Galiba biraz sarhoşum

Öptüğümü bilmiyorum', 'Deli miyim divanemi Yaptığımı bilmiyorum Sevmeyene sevene mi Taptığımı bilmiyorum Güneşe yoksa aya mı Sütü bozuk bir soya mı Yanlışa mı doğr...', ARRAY['Türk Edebiyatı','Şiir','Kenan Şahbudak']::text[], 8.5, '{"poet":"Kenan Şahbudak","poet_slug":"kenan-sahbudak","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bilmiyorum-38-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekliyorum seni', 'bekliyorum-seni-dursun-onal-mqlku', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yine sensiz bir gün daha

Salıveriyorken kendini

Güneş umursuzca batıyorken

Deniz üzerindeki yakamozlar 

Sevgililer için çok şeyler ifade ediyorken

Ben yine yalnızım

Sevgilimden uzakta

Görmüyor gözüm kalkmıyor ellerim

Sen yine yoksun yanımda

Bir gün daha aktı işte

Kimbilir sen nerdesin yine

Belki yalnız belki biriyle

Ama ben hep aynı

Batan güneşle uyuyorum yine

Sabah uyandığımda yeni sayfalar açılıyor ufkumda

Temiz ve berrak değiller her zaman

Dün geceden kalan kabuslar 

Yankılanıyor kulağımda

Gecelerim kabusa dönüşüyor çoğu zaman

Ama beni hayata bağlayan

Sen oluyorsun her zaman

Ama sen yine yoksun yanımda

Her an gelecekmiş gibi

Bekliyorum binbir umutla', 'Yine sensiz bir gün daha Salıveriyorken kendini Güneş umursuzca batıyorken Deniz üzerindeki yakamozlar  Sevgililer için çok şeyler ifade edi...', ARRAY['Türk Edebiyatı','Şiir','Dursun Onal']::text[], 8.5, '{"poet":"Dursun Onal","poet_slug":"dursun-onal","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bekliyorum-seni-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mitoloji Sözlüğü. (.Greko- Romen.)', 'mitoloji-sozlugu-greko-romen-nusret-akbayir-w0fct', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '.(''sözlükçe'' en alt kısımda.) 

.

______ MİTOLOJİ  SÖZLÜĞÜ  (A-Z)  / __ (.GENİŞ KAPSAMLI.) ___

____________________________________________________

____________________________________________________

Abas: Metanize’nin oğlu, su içmesiyle alay ettiği için Demeter, onu kertenkele yaptı. 

Kalkanında büyüleyici bir güç varmış. 

Abaris: İskityalı Apollon rahibi, tanrı, ona kahinlikte öğretmişti. Hiç yemek yemeden yaşar. 

Apollon’un attığı altın bir oka biner, dünyayı dolaşırdı. 

Absyrtos: Kolkhi (Gürcü)   kralının oğlu ve Medea’nın kardeşi. 

Acacallis: Minos’un kızlarından biri. Hermes ve Apollon bu kıza gönül vermişlerdi. 

Acamas: Thesus ile Phedre’nin oğlu. 

Admetos: Thessalia’da Phere şehrinin kralı Alkestis’in babası. 

Admete: Eurystee’nin kızı. 

Adonis: Güzelliği ile meşhur bir delikanlı, hakkında çeşit çeşit rivayetler vardır. 

Adrasteia: Girit adasında yaşayan bir peri kızı. 

Adrastos: Argos kralı, (Adraste) 

Adrogos: Girit kralı Minos’un oğullarından biri. 

Aedon: Bülbül. Bir Attika efsanesine göre Aedon, Atina kralı Pandion’un kızıydı. 

Acetes: (Aietes)   Kafkas dağları ile Karadeniz arasındaki bir bölgenin kralı.

Sihirbaz Circe (Kirke)  ’nin kardeşi ve güneşin oğlu. 

Aegee: (Aige)   Ege Theseus’un babası ve Athena kralı.

Aegina: (Aigina)   Irmak tanrısı Asopos’un kızı. 

Aeson: (Aison)   Thessalia kralı Pelias’ın kardeşi ve Jason’ın babası. 

Aethra: (Aitra)   Trezene kralının kızı, Theseus’un anası. 

Agemedes: Ünlü heykeltraş ve mimar, Delphoi’deki Apollon tapınağını yaptı. 

Agememnon: Yunan krallarının en önemlilerinden biri. Troia savaşında,Yunan ordularının baş komutanı. 

Aganippe: İlham perilerinin yani Musa’ların Hlikon dağındaki mukaddes kaynağı 

Agapenar: Yunan kahramanlarından biri. 

Agathodaimon: Toprağa bereket, şehirlere bolluk veren Lütuf Tanrısı. 

Agathon: Atinalı ünlü bir trajedi yazarı. 

Agave: (Agarie)   Kral Kadmos’un kızı. Dionysos’un annesi, Semele’nin kızkardeşi. 

Agdistis: Eski Anadolu tanrıçalarından. Adını Sivrihisar bölgesindeki Agdos dağından almıştır. Pausanias’ın anlattığına göre, Zeus bir rüya görüyor ve tohumları yeryüzüne saçılıyor bu tohumlardan kendisinde hem dişilik hemde erkeklik vasfı bulunan Agdistis yaratılıyor, tanrılar bu tuhaf mahluku yakalıyorlar. Erkeklik uzvunu kesiyorlar. Kesilen uzvun yerinden bir badem ağacı çıkıyor. Sangrios (Sakarya)   nehrinin kızı, bu ağaçtan bir badem koparıyor, göğsüne koyuyor ve gebe kalarak Attis’I dünyaya getiriryor. Attis çok güzel bir delikanlı oluyor. O sırada, erkekliğini kaybettiği cihetle yal nız kadınlık vasfını muhafaza eden Agdistis, bu güzel genci seviyor. 

Agenor: Finikeliler soyunun atası İo’nun torunu Telephassa ile evlendi Europa adlı bir kızı ile Kadmos, Phoeniks, Kiliks adlarında üç oğlu oldu. 

Aglaia: Üç Kharitlerden biri. 

Aglaures: Kekrops’un kızı. 

Agron: Kos (İstanköy)   adasında Byssa ve Meropis adlşarındaki iki kız kardeşle yaşayan bir delikanlı. Bu üç kardeş toprak tanrıçasından başka hiç bir tanrıya saygı göstermedikleri için ceza olarak kuş şekline sokuldular. Meropis baykuş oldu, Byssa martı, Agron ise yağmur kuşuna çevrildi. Babaları olan Eumelos ise bir kargaya çevrildi. 

Agyieus: Yolların, sokakların, meydanların tanrısı olarak Apollon’a verilen adlardan biridir. 

Aiakos: Zeus ile Aigina’nın oğlu ve Telamon’un babası. İyi kalpli ve adaletsever olduğundan öldükten sonra yeraltı ülkesinin yargıcı oldu. Minos ve Rhadamantys onun yargıç arkadaşları idi.

Aias: Troia savaşına katılmış iki kahramanın adı 

Aias, Salamis kralı Telemon’un oğlu. İlias’ta Akhilleus’tan sonra en yiğit, güzel bir kahraman olarak anılır. 

Aias, Lokri’in oğlu, kırk gemi ile Troia’ya gitti, çok hızlı koşardı. 

Aidoneus: Yeraltı dünyasının tanrısı Hades’in bir diğer adı. 

Aigeus: Atina kralı Theseus’un babası. Theseus Minotauros’a karşı kazandığı zaferden dönerken, gemisine zafer işareti olarak beyaz yelken çekmediği için, babası oğlunun yenildiğini zannederekkendisini denize attı, intihar etti. O günden beri bu denize ege denizi denir. 

Aigisthos: Kral Thyestesİn kendi öz kızı Pelopia’dan kazandığı oğlu. Baba ile kızı arasındaki bir sevginin ürünü olan bu çocuk, halkın ayıplamasından utanıldığı için doğruca ormana bırakılmıştı. Çobanlar, keçi sütü ile bunu beslediler. Sonradan amcası Atreus’u öldüren ve Trobia savaşına giden Agememnon’un karısını ayartan, delikanlı, Agememnon’u da öldürdü fakat kendisi de Orestes tarafından öldürüldü. 

Aigle: Heliades’lerden, yani Phaeton’un kız kardeşlerinden birinin adı. 

Aineias: Kral Ankhises ile Aphrodite’ın Oğlu Troia kahramalarından biri. Aineisas zaptedilen ve yakılan Troia şehrinden, hasta babasını sırtında taşıyarak önce İda (Kazdağı)  ’nda gizlendi. Uzun ve dolanbaçlı yollardan Kartaca’ya oradanda İtalya’ya geldi. Orada yeni bir vatan kurdu. 

Aiolos: Rüzgarların tanrısına verilen ad. Bunu bazıları Zeus’un, bazıları Hippotes ile Menalippe’nin oğlu sayarlar. 

Aisa: Kader tanrısı Moira’nın başka bir adı. 

Aison: İolkos şehrinin kralı. Pelias’ın ağabeyi, İason’un babası. 

Aithalides: Hermes’in oğlu, Arganautlar seferine haberci olarak katılmıştı. Efsaneye göre babası ona öldükten sonra mezarda bile her şeyi hatırlayabilecek bir hafıza vermişti. 

Aithra: Kral Pitteheus’un kızı. Theseus’un anası. Aithra, Dioskur’lar tarafından kaçırılmış, köle olarak Helena’ya verilmişti. Helena ile Troia’ya gelen Aithra, Troia’nın düşmesi üzerine torunları tarafından kurtarıldı. 

Akaman: Alkmanion ile Kallirhoe’nin oğlu 

Akakallis: Girit kralı Minos’uv kızı. Dione adı ile de çağırılır. 

Akastos: Pelias’ın oğlu Medias’ın kardeşi 

Akhaeus: İon’un kardeşi, Helen’in yeğeni, Akhai’lilerin babası sayılmaktadır. 

Akhates: Aineias’ın sadık dostu. Troia’dan kaçarken de onun yanındaydı. 

Akhales: Herakles (Hercul)   ile Omphale’nin oğullarından biri. 

Akheus: Poseidon ile Larides’in oğlu, Pelasgos ile Phtius’un kardeşi. Basitliği ile ün kazanmıştı. 

Akhilleus: Peleus ile Tethys’in oğlu ünlü Yunan Kahramanı. Topuğundan başka hiç bir yerine ok işlemez, kılıç kesmezdi. 

Akhiroe: Ares’in torunu çok güzel bir kız. 

Akhyls: Karanlıklar tanrıçası. 

Akis: Faunus ile Nympha Symaethis’in oğlu

Akrepheus: Apollon’un oğlu. Biotiada, akrephia şehrine kendi adını vermiştir. 

Akragos: Zeus ile Okeanos’un kızlarından Astepore’nin oğlu çıplak gördüğü için geyiğe çevirildi. 

Aktor: Poseidon’un oğlu 

Akuilon: Eos ile Ailos’un oğlu. Doğuştan saçları beyazdır ve yılandan bir kuyruğu vardır. 

Akus: Hephaistos ile Letafet tanrıçalarının en genci Agaia’nın oğlu. 

Alala: Savaş’ın kızı. Kişisel savaş olarak bilinir. 

Alalkomenis: Thebai kralı Ogyges ile Thebe’nin kızı. Telksine ile Aulis’in kızkardeşi. Üç kardeş tanrıça Athena’nın süt anneleriydi. 

Alba Longa: (Albano)   Aimeas’ın oğlu 

Albion: Poseidon’un oğlu olan müthiş bir dev. Heracles ile yaptıkları kavgadan galip çıkınca Zeus kardeşi Bergion ile onun başlarına taş yağdırdı. 

Albunea: Bir peri kızı. 

Alekto: Uranos’un kanından yaratılan öc tanrılarından biri. 

Aleksandros: Kahraman Paris’in bir lakabı. 

Alkaios: Perseus’un üç oğlundan biri 

Alkandros: Tanrıların gözüne girmiş ünlü bir kahin.

Alkathoos: Pelops ile Hiphodemie’nin oğlu. Megara şehrine kral oldu. 

Alkestis: Pelias ile Anaksibia’nın kızı, kral Admetos’un karısı. 

Alkimedon: Troia surlarına merdiven dayayan bir kahraman. 

Alkinoe: Korinthos kralı Polybos’un kızı, Amphilokos’un karısı. 

Alkinoos: Koro adasının eski adı olan Scheria adasında yaşayan bir kral. 

Alkithoe: Minyas’ın kızı, iki kardeşi ile birlikte şarap tanrısının ayinlerine katılmadıkları için çıldırdılar. Artemis onlara acıdı ve üç kardeşi yarasaya çevirdi. 

Alkmene: Mykena kralının kızı. Kral Amphitriyon’un karısı Herakles’in annesi. 

Alkmeon: Amphiaros ile Eriphyle’nin oğlu. Annesini öldürdü. 

Alkyone: Rüzgarların tanrısının kızı ve Keyk’in karısı. Kocası bir deniz kazasında ölünce kendisini denize attı. Birbilerini çok seven bu iki insana acıyan Tethys karı kocayı iki deniz kuşuna çevirdi. 

Aloeus: Gök ile yer’in oğlu olan bir Titan. İphimedia adında bir kadınla evlenmişti ancak Poseidon bu kadını sevmiş ve ondan ikide çocuğu olmuştu. 

Aloadlar: Poseidon ile İmphimedia’nın ikiz çocuklarına verilen ad. Bunlar Ares’I bile aylarca esir tutacak kadar güçlü ve yiğit kahramanlardı. Fakat gökyüzüne saldırmak istedikleri için Apollon onları öldürdü. 

Alope: Korkyon’un kızı Poseidon’dan Hippothous adında bir oğlu olmuştu. 

Alphesibea: Arkadia kralı Phegeus’un kızı, annesini öldüren Alkmeon ile evlenmişti. 

Alphesibia: Diyonysos’un aşık olduğu Asya’lı bir peri kızı. 

Alpos: Sicilyada yaşayan korkunç bir dev. 

Althaia: Melagros’un annesi. 

Althala: Kalydon kralı Peneus’un karısı ve Melagros’un annesi. 

Althemenos: Girid kralı Kereteus’un oğlu. Yalnışlıkla babasını öldürdü ve yer tarafından yutuldu. 

Ameltheia: Zeus’un süt annesi olan keçi. 

Amata: Kral Latinus’un karısı. Lavinia’nın annesi. Kızının Ene ile evlenmesine üzülerek intahar etti. 

Amathus: Herakles’in oğlu. 

Amentes: Hades’in lakabı 

Ambarvalia: Romada Mars şerefine yapılan tören 

Amazonlar: Karadeniz kıyısına yakın bir yerde yaşayan ve müthiş savaşçı olan kadınlar. Aralarında hiç erkek bulunmayan bu kadınlar kendilerine ait bir devlet kurmuşlar. Thermodon(Terme Çayı)   kıyısında Themikyra şehrinde yaşarlardı. Savaş Tanrıçası Ares’e taparlardı. 

Ambrossia: Olymps tanrılarının baldan dokuz kat daha tatlı olan yiyeceği. Bu gıdadan tadanlar ölümsüz oluyorlardı. 

Ammon: Kıbrıs kralı Kynyros’un oğlu, Myrrha’nın kocası 

Amor: Aphrodite’ın oğlu Eros’un bir diğer adı. 

Amphiaros: Zeus ve Apollon tarafından korunan bir kahin. Oikides ile Hypermestra’nın oğlu. 

Amphikttyon: Deukalion ile Pyrrha’nın oğlu. 

Amphilokhos: Amphiaros ile Eriphyle’nin oğlu. Oda babası gibi bir kahin idi. 

Amphion: Zeus ile Antiope’nin oğlu Niobe’nin kocası. 

Amphissus: Apollon ile Dryoge’nin oğlu. Çok kuvvetli idi. 

Amphitrit: Poseidon’un karısı. Nereos ile Doris’in kızı. 

Amphitrion: Triynthe kralı Akaios’un oğlu.Alkmene’nin kocası. Alkmene Zeus’tan hamile kalarak Herakles’I doğurdu. 

Amulius: Albe adasının efsanevi kralı ve Prokas’ın oğlu. 

Amyklos: Apollon’un istemeyerek vurup öldürdüğü daha sonra sümbül çiçeğine dönüştürdüğü delikanlı. 

Amykos: Poseidon’un oğlu.Vahşi tabiatlı bir kral idi. 

Amymone: Donaos’un elli kızından biri..Satyr’dan kaçarken Poseidon yardımına geldi ve ona aşık oldu. Bu aşktan Nauplios adındaki kahraman doğdu. 

Anaksarete: Kıbrıslı çok güzel fakat kalpsiz bir kız. Kendisine aşık olan İphis’in intihar etmesine neden olduğu ve ölümüne aldırmadığı için Aphrodite onu taştan bir heykele dönüştürmüş. 

Ananke: İnsan şeklindeki bir kader tanrısı. 

Androgeos: Girit kralı Minos’un oğlu. Bir zaferden dönerken pusuya düşürülerek öldürüldü. 

Androklos: Ephes şehrinin kurucularından. 

Andromakhe: Hektor’un karısı ve Eetion’un kızıydı. Yedi kardeşi, babası ve annesinin ölümüne tanık olduktan sonra kocasınıda bir savaşta kaybetti. Yunanlılara esir düşerek Akhilleus’un oğlu Neoptolemos’un metresi oldu. 

Andromeda: Kral Kepheus ile Kasiope’nin kızı. 

Anios: Apollonun Delosta yaşayan oğlu. 

Ankhises: Troia kahramanlarından biri. Kapys ile Themiste’nin oğlu. Aphrodite’ten Aeneas (Enee)   adında bir oğlu oldu. 

Ankhores: Phirigia kralı Midas''ın oğlu. Bir uçuruma düşerek can verdi. 

Antaios: Poseidonile Gaia’nın oğlu olan Libyalı dev. 

Antenor: Troia kralı Priam’ın arkadaşı Yunalılarla anlaşıp Troia’ya ihanet etti.

Anteros: Aphrodite’in Ares’ten olan oğlu. 

Antigone: Oidipus’un kızı. 

Antiklea: Odysseus’un annesi. Oğlunun öldüğünü sanarak intihar etti. 

Antiope: Nikteos’un kızı, Zeus ona aşık olmuştu. 

Anubis: Mısırın ölüler tanrısı. 

Antiphates: Sicilyada yaşayan dev cüsseli, insan eti yiyen Laistryon’ların kralı. 

Antiphus: Priamos’un oğullarından biri. Agememnon tarafından öldürüldü. 

Apathe: Hile tanrısı. 

Aphareus: İdas ile Lynkeus’un babası. 

Aphrodite: Aşk ve güzellik tanrıçası. 

Apollon: Zeus ile Leto’nun oğlu, Artemis’in kardeşi güneş ve güzel sanatlar tanrısı. 

Arai: Beddua tanrısı 

Arakne: Lydya’lı güzel bir kız. Kendini tanrıça Athenadan üstün gördüğü için tanrıça tarafından örümceğe dönüştürüldü. 

Ardolos: Hephaistos ile Aglea’nın oğlu. 

Ares: Zeus ile Hera’nın oğlu, harp tanrısı. 

Arge: Apollon’un geyiğe dönüştürdüğü bir peri kızı. 

Argos: Zeus ile Niobe’nin oğlu 

Ariadne: Dionysos’un karısı. 

Ariane: Girid kralı Minos ile Pasiphane’in kızı. 

Arimasp’lar: Tek gözlü efsanevi millet. Altını koruyan yarı kuş yarı arslan olan Gryps’lerle sürekli savaş halindeydiler. 

Arion: Hayatı efsaneleşmiş Kesbos’lu bir çalgıcı 

Arion: Poseidon ile Demeter’in oğlu. 

Aristaios:.Apollon ile Kyrene adlı bir perinin oğlu. Çobanlığın, zeytin yetiştirmenin ve arıcılığın tarısıydı. Orpheus’un karısı Eurydike’ye aşık olmuştu. 

Aristodemos: Messenia kralı, yurdunu kurtarmak için yirmi yıl boyunca Ispartalılarla çarpıştı. Bunun uğruna kızını tanrılara kurban etti ancak genede Ispartalılara yenildi. Ve kızının mezarı başında kendini öldürdü. 

Arkas: Zeus ile peri kzı Kallisto’nun oğlu.Arkadiaların atası, Erato’nun sevgilisi. 

Arkhelaos: Temenos’un oğlu. Herakles’in torunu 

Arkhemoros: Hyripyle’nin İason’dan olan oğlu. Bir yılan sokması sonucu öldü. 

Arkiron: Kentauros’lardan biri. 

Artemis: Zeus ile Leto’nun kızı. Apollon’un kız kardeşi. Kardeşinden bir kaç dakika önce doğup Apollon’un doğumu sırasında annesine yardım etmiş.

Askanios: Aeneas ile Kreuse’nin oğlu 

Askalaphos: Akheron’un oğlu. Tanrıça Demeter’I kızdırdığı için kocaman bir kayanın altına kapatılmıştı. Herakles bu gence acıyıp onu bir baykuşa çevirerek acısına son verdi. 

Asklepios: (Esculope)   Apollon’un oğlu, sağlık, iyi etme ve hekimlik tanrısı. Tanrılara karşı gelip, ölüm döşeğindeki hastaları iyi ettiği, ölüleri hayata döndürdüğü için Zeus tarafından öldürüldü. 

Asia: Okeanos ile Ethys’in kızı. Asya kıtasına adını koydu. 

Assaon: Niobe’nin babası. Kızına aşıktı, kızı bu aşka karşılık vermeyince torunlarını öldürdü. 

Asteria: Titan Kheos ile Phebe’nin kızı. Zeus bu kıza gönül verince onunla birlikte olmak istemeyen Asteria bir bıldırcın olarak Zeus’un elinden kurtuldu. Ve kendini denize atarak yüzen bir ada olan Ortygia’ya dönüştü. 

Asterion: Girit adası kralı. Europa’nın Zeus’tan olan iki oğlu Minos ve Rhadamantys’I o büyüttü ve krallığını Minos’a bıraktı. 

Astraios: Eos’un yani şafak kızıllığının kocasıdır. Yıldızlara hükmederdi. 

Astrea: Zeus ile Themis’in kızı. İnsanlara fazilet ve adalet ilham ederdi. 

Astyanaks: Hector ile Andromakhe’nin oğlu. Troia ele geçirilince Odysseus onu kale duvarından aşağı atarak öldürdü. 

Atalante: Arkadia’lı güzel avcı. Av sırasında Artemis’e eşlik ederdi. 

Ate: Hata ve günah tanrıçası, insanların basiretini bağlardı. 

Athamas: Phtiksos’un babası, İno’nun kocası. 

Athena: Zeka tanrıçası. Bir adıda Pallastır. 

Atlas: Titan İapetos ile Deniz kızlarından Klymene’nin oğlu. Diğer Titanlarla birlikte Olympos’a saldırdığı için Zeus onu gök kubbeyi omuzlarında taşımakla cezalandırdı. 

Atreus: Pelops ile Hippodemia’nın oğlu. Thyestes ile Nikippe’nin kardeşidir. Önce Kleola ile evlendi ve bu evlilikten Pelisthes doğdu. İkinci evliliği dul kalan gelini Aerope ile oldu. Bu evlilikten Agememnon ile Menelaos adlı iki oğlu ve Anaksibia adlı bir kızı oldu. 

Atrides: Atreus soyundan gelenler bu adla anılır özellikle Agememnon ve Menelaos. 

Atropos: Bildiklerinden şaşmayan üç Moria(Park)   lardan biri. 

Attis: Eski anadolu tanrılarından biri. Adonis kadar güzeldi bu yüzden Anadolu tanrılarının anası Kybele ona gönül verdi. Ondan hayat boyu kendisine sadık kalma sözü almıştı ancak Attis Sakarya nehrinin perisi Sagaratis’e gönül verdi. Kybele buna çok öfkelendi ve peri kızının hayatının bağlı olduğu ağacı kesti. Attis’I de delirtti. 

Auge: (Augia)   Aleus’un kızı. Herakles’ten Telephos adında bir oğlu olmuştu. 

Telephos’u doğurduktan sonra Mysia’ya kaçtı. Orada kral Teothras’ın karısı oldu. Daha sonra kim olduğunu bilmeden kendi öz oğlu ile evlendi. 

Augias: Elis bölgesinin efsanevi kralı. 

Aura: Phrygia’lı güzel bir kız. Rüzgar gibi çevikti. Artemis’in av arkadaşlarından biriydi. Dionysos buna aşık oldu ama yakalayamadı. Daha sonra Aphrodite araya girdi ve Aura’nın aklını başından aldı. Dionysos’tan iki çocuğu oldu ama çocuklarını parçaladı sonra kendini Sakarya ırmağına attı. Zeus bu deli anneyi bir kaynağa çevirdi. 

Aurora: Eos’un latince adı. Şafak tanrıçası. 

Auson: Odysseus ile Kalypso’nun oğlu. Latinos adında Latinlaerin babası sayılan bir oğlu vardı. 

Autolykos: Odysseus’un dedesi. Hermes’in oğlu idi. 

Autemedon: Akhilleus’un arabasını sevkeden kahraman

Autonone: Kadmos''un kızı. Aktaion''un anası, Dionysos onu delirttiğinden kız kardeşi Agaue ile birlikte Pentheus''u parçaladı. 

B

Baal: Asur Tanrısı

Bakkhant''lar: Dionysos şenliklerinde tanrının yanında dolaşan kadınlar

Basileia: Uranos''un kızı ve Rhea ile Titanların kızkardeşidir. Kardeşi Hyperion 

ile evlendi Selene(ay)   ve Helios(güneş)   I doğurdu.

Battso: Apollonun öküzlerini çalan Hermes''e yardım eden ihtiyar.

Bauba: Neşeli bir hizmetçi kız, Persophene için üzülen Demeter''I eğlendirmeye çalışırdı.

Baukis: Philemon''un karısı.

Bellerophon: Korinthos''un kurucusu, Glaukos''un oğlu.

Bellona: Romalıların zafer tanrıçası.

Beroe: Adonis ile Aphrodite''in kızı. Poseidon onunla evlenmek istedi ama o Dianysos ile evlendi.

Bia: Dev palas ile Styx''in kızı. Şiddet anlamına gelen Bia, Nike(Zafer)   in kız kardeşidir.

Bianos: Troialı bir komutan. Agememnon tarafından öldürüldü.

Bias: Amythaon''un oğlu. Melanpous''un kardeşi.

Biton: Kydippe''nin oğlu

Bona Dea: Doğurganlık tanrıçası.

Boreas: Kuzey rüzgarı tanrısı. Şafak tanrısı Eos''un oğlu

Bormos: Titias''ın oğlu, çok güzel bir delikanlı olan Bormos''u küçük bir su kaynağının perileri kaçırdılar.

Brankhos: Anadolu''da Miletos''lu çok güzel bir delikanlıydı. Bir gün dağda sürüsünü otlatırken tanrı Apollon onu görüp aşık oldu. Tanrı ona kahinlik sanatını öğretti.

Briareos: Yüz kollu devler, titanlarla savaşında tanrı Zeus''un tarafında yer aldılar.

Britomartis: Girit''li bir tanrıça, Zeus ile Karme''nin kızı. 

Brontes: Gök ile yerin oğlu Kylop''lardan biri.

Brotheus: Yanardağlar tanrısı ile zeka tanrıçasının oğlu. Çok çirkin olduğu için alemin maskarası olmasın diye Etna yanar dağının içine atılmıştı.

Bryte: Ares''in kız Minos''un sevgilisi.

Busiris: Zalim bir Mısır kralı Herakles tarafından öldürüldü.

Byblis: Miletos''un kızı. Erkek kardeş''I Kaunos''a aşıktı Kaunos onun bu aşkından korkup kaçınca kendini öldürdü. Ona acıyan periler Byblis''i çağlayan''a çevirdiler. (Bugünkü Ilıca)

Byzas: Poseidon''un oğlu. Annesi Zeus ile İo''nun kızı idi. Byzans şehrini kurdu

Bassareus: Dionysos''un latince adı

Bendis: Trakyalıların ay tanrıçası.

Bianna: Kıtlık yüzünden Girit adasından kaçan genç bir kız. Viyana şehrine adını verdi.

Boarmia: Pallas''ın bir lakabı. Öküzlerden faydalanmayı öğrettiği için bu lakabı almıştı.

Boreadlar: Kuzey rüzgarının çocuklarına verilen ad.

Bosphoros: Sığır geçidi anlamına gelir. İstanbul boğazınıneski adı.

Botres: Eumelos''un oğlu. Tanrı Apollon''a taktim edilen kurbanın beynini yediği için babası tarafından öldürüldü.

Brankhid''ler: Apollon''un gözdesi Brankhos''un soyundan gelenlere verilen ad.

Briseis: Asıl adı Hippodemie olan Briseis Troia civarında eski bir Anadolu şehri olan Lyrnessos şehrinin rahibinin kızydı. Babasının katili Akhilleus''un sevgilisi oldu.

Brithynoos: Apollon''un adlarından biri.

Brykhia: Aphrodite''in adlarından biri. entheus’u parçaladı. 

Cacus: Herakles tarafından öldürülen bir dev.

Caeculüs: Vulcain''in oğlu

Caelus: Uranos''un latince karşılığı

Camene: Çeşme perileridirler ancak yunanlılar bunların ilham perileri olduklarına da inanırlardı.

Camilla: Volskiler kralı Metabus''un amazonlara benzeyen kızı.

Camenta: Romalı doğum tanrıçası.

Carmenta: Ladon ırmağının efsanevi kızı. Gaipten haberler veriyordu.

Carna: Roma civarında Tiber nehri kenarlarında yaşayan bir peri kızı.

Catanitus: Latinlerin Ganymedes''e verdikleri ad.

Centimaniler: Yüz kollu devler.

Ceres: Toprak ve ürünler tanrıçası Demeter''in bir diğer adı.

Clio: Kahraman destanı Epos ve Tarih Musa''sına Latinlerin verdikleri ad.

Concordia: Romalıların barış tanrıçası.

Concus: Eski Roma tanrılarından biri. Gizlemek, örtmek, saklamak tanrısıydı.

Cubido: Aşk tanrısı Eros''un bir diğer adı.

D

Dada: Namusu uğruna kendini öldüren efsanevi Girit''li bir kadın.

Daedalion: Sabah yıldızı Eoshoros''un oğlu savaşa ve ava çok düşkündü. Kızının ölümünden sonra çektiği acıya üzülen tanrı Apollon bu üzüntülü babayı bir akbabaya çevirdi.

Daimon: İlahi bir kudret taşıdığına inanılan adeta tanrılaşmış insanlara verilen ad.

Daktylos: İda dağında oturan ve madenleri işleyen becerikli cinler. Bu cinleri Rhea doğurmuştur.

Daimos: Ares''in yardımcısı, korku.

Damaster: Poseidon''un oğlu

Dammaneus: Daktylos''lardan biri.

Danae: Argos kralı Akrisios''un kızı.

Danaidler: Danaos''un elli kızına verilen ad.

Danaos: Belos''un iki oğlundan biri, farklı farklı kadınlardn elli kızı olmuştu.

Daphne: Apollon''un aşık olduğu peri kızı, defne ağacına çevirildi.

Daphnis: Çoban şiirlerinin mucidi, sicilyalı bir çoban.

Dardanos: Zeus''un oğlu, Troia kalesini o inşa etti. Çanakkale boğazı eski adını ondan almış.

Dedalos: Yunanlılarca heykeltraşlığın ve mimarinin piri sayılan efsanevi bir sanatkar

Deimos: Korku anlamına gelen Deimos Ares''in en yakın arkadaşıdır.

Deioneus: Dia''nın babası İksiyon onu kızgın kömür dolu bir hendeğe atıp yamıştı.

Deiphobos: Priamos''un oğlu, Hector''un kardeşi.

Delphoi: Gelecek olaylardan haber verme yeri, kehanet tapınağı.

Delos: Yüzen bir ada iken Artemis ve Apollonun doğumu için Zeus onu denizin üzerinde sabit bir ada haline getirdi.

Dejanıra: Herakles''in karısı

Demeter: Toprak ve ürün tanrıçası.

Demodike: Kretheus''un karısı, Phriksos''un kaynanası.

Demodokos: Gözleri kör bir halk şairi. Şiirleri ile efsaneleşmiştir.

Demophon: Theseus ile Phedra''nın oğlu. Elpeor ile Troia savaşına katıldı.

Despoina: Demeter''in Posidon''dan olan kızı Persophene''in bir diğer adı.

Deukalion: Prometheus ile Klymene''nin oğlu, Pyrrha''nın kocası. Tufan da sağ kalanlardan.

Diana: Artemis''in latice adı.

Dido: Karthaca kraliçesi, Aineas''ı sevmişti karşılık alamayınca kendini öldürdü.

Didyme: Brankhid''lerin kahinlik tapınağı

Dike: Zeus ile Themis''in kızı. Adalet sembolü.

Diktynna: Giritte Artemis''in yerini tutan iki tanrıçadan biri.

Diktys: Seriphos adasında yaşayan bir balıkçı. Perseus ve annesi Danae''yi bulmuştu.

Dimoedes: Arezen''in kardeşiydi ve onun kızı Euopis ile evlenmişti ancak Euopis onu kendi 

kardeşi ile aldatıyordu. Durum ortaya çıkınca Euopis kendini öldürdü. Diometes daha sonra sahilde genç bir kadın cesedi buldu ve buna aşık oldu. Ceset çürümeye başlayana kadar onu sakladı daha sonra muhteşem bir törenle defnetti ama bu anlamsız aşkı içinden söküp atamadı ve mezarın başında kendini öldürdü.

Dione: Okeanos''un kızı

Dionysos: Şarap tanrısı

Dioskur''lar: Zeus''un oğullarından Kastor ile Polydenkes''e verilen ad. Anneleri Leda idi. İki kardeş gemicilere yol gösterir tehlikeli anlarda yardımlarına koşarlardı.

Dirke: Epopeus''un karısı

Dodona: Zeus tapınağı, Zeus bu tapınakta sorulan sorulara, dualara cevap verirdi.

Dolion''lar: Bugünkü Kapıdağda yaşayan bir halk.

Dolon: Troia''lı bir genç. Çok hızlı koşardı, savaş sırasında casus olarak Yunanlıların arasına karıştı ancak yakalandı ve Diomedes tarafından öldürüldü.

Doris: Okeanos ile Tethys''in kızı. Kardeşi Nereos ile evlendi. Ondan Nereid''ler diye bilinen elli kızı oldu.

Doros: Apollon ile Phthie''nin oğlu

Dryad''lar: Ormanlarda yaşayan ağaç perileri. Hayatları ağaca bağlıydı. Ağaç çürüdüğü yada kesildiği zaman bunlarında hayatları son bulurdu.

Dryas: Ares''in oğullarından biri.

Dryope: Kral Dryops''un tek kızı. Oeta dağında babasının sürülerini otlatırdı. Apollon bu kıza gönül verdi ve yılan şekline girerek onunla birleşti. Kız bu olaydan kimseye haber vermedi. Andreamon ile evlendi ve bir oğlu oldu. Adını Amphissos koydular. 

Dryops: Apollon ile Dia''nın oğlu. Kızı Hermes ile birlikte olup Pan''ı doğurdu.

E

Eakos: Zeus ile peri kızı Egine''nin oğlu. Dindarlığı ile tanınırdı.

Eetion: Mysia bölgesinde bir şehrin kralı. Andromak''ın babası.

Efhialtes: Gaia ile Uranus''un oğlu olan bir dev.

Egeria: Romalıların doğum tanrıçası.

Egeus: Atina kralı Theseus''un babası. Theseus Minotaure''e karşı kazandığı zaferden dönerken beyaz yelken çekmediği için babası oğlunun yenildiğini zannederek kendini denizew attı. O günden beri bu denize ege denizi derler.

Egestes: (Akestes)   Sicilyada Krimisos ırmağının tanrısının oğlu

Egina: Asapos ırmağı tanrısının kızı, Zeus tarafından kaçırıldı.

Egisthos: Thyeste''nin oğlu.

Egypios: Antheus ile Boulis''in oğlu. 

Egyptos: Mısırın ünlü kahramanlarından, Poseidon ile Nil nehrinin oğlu. Mısıra adını verdi.

Eidothea: Proteus''un oğlu babasına akıl danışmaya gelen Menelaos''a yardım etti.

Eileithyia: Doğum arğrıları tanrısı. Bu tanrı, doğumlarında kadınlara yardım edermiş.

Eirene: Barış sembolü Horalardan biri.

Ekhemos: Aeropos''un oğlu.

Ekhestos: Zalimliği ile tanınan Epir kralı.

Ekhidna: Gövdesi kadına, kuyruğu yılana benzeyen bir ejder. Lerna Hydrası denilen yılanın annesidir.

Ekhion: Kadmos''un ektiği dragonun dişlerinden hortlayan beş adamdan biri.

Ekho: Ormanlarda, dağlarda dolaşan yankı perisi. Her yerde yanlızlığı arıyor insanlardan ve tanrılardan kaçıyordu. Aşkına karşılık vermediği için Pan çobanları ona karşı kışkırttı. Ve çobanlar Ekho''yu parçalayıp, parçalarını her tarafına attılar.

Elektra: Agememnon ile Klytaimenestra''nın kızı. Okeanos ile Tethys''in kızlarından birininde adı Elektra idi.

Elektryon: Perseus''un üç oğlundan biri.

Eleutherios: Zeus''un lakabı

Elysion: Yeraltı cenneti

Elpenor: Odysseus''un arkadaşalarından biri. Kirke onu domuza çevirmişti ama daha sonra tekrar insan şekline döndü.

Empusa: Hekate''nin, insanları korkutmak için yarattığı bir canavar. Her çeşit kılığa girebilirdi. İnsan etiyle beslenirmiş ve kurbanalarını çok güzel bir kadın kılığına girerek avlarmış.

Endymion: Ayışığı Selene''nin aşık olduğu güzel bir delikanlı.

Enyalios: Savaş tanrısı Ares''in adlarından biri.

Enyo: Ares''in en sadık arkadaşlarından biri. Enyo felaket anlamına gelir.

Eolos: Rüzgarların bekçisi.

Eolia: Eolos''un oturduğu ada.

Eos: Şafak

Epaphos: Zeus ile İo''nun oğlu

Epeios: Panopeus''un oğlu Troia savaşına otuz gemi ile gelmişti.

Epeos: Panopee''nin oğlu surları yıkmak için kullanılan aleti icat etti ve Troia savaşındaki tahta atı yaptı.

Ephesos: (Ephes)   Anadolu''nun Ege sahillinde eski devirlerin en ünlü şehri.

Ephialtes: Gaia ile Uranos''un oğlu olan dev.

Epidauros: Asklepios''un en meşhur tapınağının bulunduğu yer.

Eikaste: İokaste''nin diğer adı.

Epimelides: Sürüleri bekleyen perilerin adı.

Epimenides: Giritli bir şair ve kahin. Atinayı Veba salgınından kurtarmıştı. 

Ephimetheus: Prometheus''un kardeşi

Epione: Asklepois''in karısı.

Epiphania: Tanrıların insan şeklinde yada başka şekillerde maddi olarak görülmesi.

Epiros: Ekhion''un kızı

Epopeus: Bir kahramanın adı. Poseidon''un oğlu olduğu söylenir

Erato: Dokuz ilham perisinden biri

Erebos: Khaos ile Nyks''in oğlu. Karanlık yeraltı dünyasının sembolü.

Erekhteous: Atina''nın ünlü kahramanı.

Erginos: Beotia bölgesinde Orkhomenos kralı.

Eridanos: Okeanos ile Tethys''in oğlu. Efsanevi bir nehir.

Erigone: Atinalı İkarios''un kızı. Dionysos''un sevgilisi.

Erikhthonios: Hephaistos''un oğlu. Hephaistos''un yere saçılan tohumlarından meydana gelen yarı insan yarı yılandı. Athena bu çocuğa acıyıp onu bir kutuya koydu ve Kekrops''un üç kızına emanet etti. Erikhthonios büyünce çok akıllı bir insan oldu ve Atina krallığını ele geçirdi. 

Erinona: Namus ve masumiyeti ile ün salan Kıbrıs''lı kız. Zeus bile ona aşık olmuştu. Hera bu aşka engel olmak için Adonis''I Erinona''ya bela etti. Kızlığını kaybeden Erinona tavus kuşuna çevirildi.

Eriny''ler: İntikam saçan tanrıçalar.

Eriphyle: Argos kralı Talaos''un kızı, Adraste''nin kardeşi.

Eris: Nifak, anlaşmamazlık tanrıçası, Ares''in kardeşi ve arkadaşı. Istırab(Ponos) , Unutmak(Lethe) , Açlık(Limos) , Keder(Argos)   çocuklarıdır. 

Eros: Aşka tanrısı, aşk ve güzellik tanrıçası Aphrodite''in oğlu. 

Erymanthos: Apollon''un oğlu. Adonis ile buluşmak için yıkanan Aphrodite''i çıplak gördüğü için tanrıça gözlerini kör etti. Bunun üzerine Apollon oğlunu bir yaban domuzuna çevirdi ve Adonis''i öldürttü.

Erysikhthon: Thesseba kralı Triapos''un oğlu. Dinsiz ve zalim bir adamdı. Demeter''e ait bir ormanı tahrip edince tanrıça onu açlıkla kıvrandırarak cezalandırdı.

Eryks: Aphrodite ile Poseidon''un oğlu.

Erytos: İole''nin babası. Ok atmada kendisini geçene kızını vermeyi vaad etmişti. Herakles yarışmada onu geçtiği halde sözünde durmadı bunun üzerine Herakles onu öldürdü.

Eskulape: Hekimlik tanrısı Asklapios''a latinlerin verdiği ad.

Eteokles: Oidipus ile İokaste''nin oğlu, Thebai kahramanlarından biri.

Ethemea: Artemis''in etrafıdaki perilerden biri. Cos adasındaki kral Merops ile evlenmek için tanrıçadan ayrılınca, tanrıça buna çok sinirlendi ve onu okları ile delik deşik etti.

Euadne: Esir düşen kocasını yakarlarken kendisini kocasını yaktıkları ateşe atan fedakar kadın.

Euandros: Arkadialı bir kahraman, yurdundan ayrılıp İtalya da bir koloni kurdu.

Eukhenor: Kahin Polydos''un oğlu, babası ona iki çeşit ölümden birini seçmesini söyledi.Ya evinde kalıp rahat döşeğinde can vermek yada savaşta çetin fakat şerefli bir ölüm. Troia savaşına katıldı ve yiğitçe öldü.

Eumaios: Odysseus''un sadık çobanı

Eumenid''ler: Attikada ki intikam tanrıçalarına verilen ad.

Eumolpos: Poseidon ile Khione''un oğlu. Herakles''in öğretmeni.

Euneos: İason ile Hypsiplye''nin oğlu.

Eunike: Bir deniz perisi. Nereos ile Doris''in kızı.

Eunomia: Okeanos''un kızları Hora(Saat)   lardan biri. Letafet perilerinin annesi.

Eunomos: Arkhiteles''in oğlu. Herakles tarafından öldürüldü.

Euphemos: Poseidon''un oğlu, Arganaut''lardan biri. Babasının ona verdiği vasıfla su üzerinde yürüyordu.

Euphorbos: Pantheos''un oğlu Troia''lı bir kahraman. Patroklos''u öldürmüştü.

Euphorion: Akhilleus ile Helena''nın çocuğu. Zeus ona aşık oldu fakat Euphorion ondan kaçtı ve Melos adasına sığındı. Çok öfkelenen Zeus yıldırımıyla onu öldürdü.

Euphrosyne: Eurymone''nin üç kızı olan Kharit''lerden biri.

Europa: Finike kralı Agenar ile Telepassa''nın kızı. Boğa şekiline giren Zeus tarafından kaçırıldı. Zeus''tan Minos, Sarpedon, Rhadamnthys adlarını taşıyan üç oğlu oldu. Adını Avrupa bölgesine verdi.

Euros: Eos ile Astraeos''un oğlu. Güney-batı rüzgarı olarak bilinir.

Euryale: Gaia''nın kızkardeşleri olan Gorgon''lardan biri

Euryalos: Aenes''in arkadaşlarından biri. Güzelliği ile ün salan bu delikanlı Nisus ile büyük bir aşk yaşadı.

Eurybie: Yer ile denizin kızı, Astraos''un annesi.

Eurydike: Orpheus''un karısı. Aristeos''tan kaçarken bir yılan tarafından öldürüldü.

Eurygania: Oidipus''un karısı.

Eurylokos: Odysseus''un arkadaşı ve kızkardeşinin kocası.

Eurykleia: Odysseus''un süt annesi.

Eurymakos: Odysseus''un karısına göz koyanlardan biri. Odysseus tarafından öldürüldü.

Eurymeda: Oeneus ile Althea''nın kızı. Kardeşi Meleagros''un ölümüne çok ağladığından Meleagrid denilen kuşa dönüştürüldü.

Eurymedon: Prometheus''un babası. Titanlarla yapılan savaşta Zeus tarafından uçurumdan aşağı atıldı.

Eurynome: Okeanos ile Tethys''in kızı. Zeus tarafından sevildi ve üç Kkari(Letafet perileri)   doğurdu.

Eurynomos: Yeraltı tanrılarından biri. Yere gömülen ölülerin etlerini yer kemiklerini bırakırdı.

Euryphaessa: Hyperion''un karısı. Helios, Selene ve Eos''u doğurdu.

Eurypylos: Tanınmış karamanlara verilen ad.

Eurysakes: Aiaks ile Tekmassa''nın oğlu.

Eurytheus: Herakles''e çeşitli görevler veren Tiryns kralı.

Euterpe: İlham perileri olan Musa''lardan birinin adı, flüt çalmasını öğretirdi.

Eurytion: Kentaur''lardan biri. Hippodemiz''yı kaçırmak isteyince Lapithlerle savaş başladı.

Eurytos: Herakles''e yay bükmesini öğreten ünlü kral İola''nın babası.

Euthymos: Temesa şehrini kurtaran ünlü kahraman.

Evadne: Poseidon ile Pitane''nin kızı.

Evandros: Sarpedon''un oğlu Lykia''lı bir yiğit Troia savaşında yardıma gelmişti.

Evenos: Ares ile Demonike''nin oğlu. Etolia krallarından biri. Marpassa adında ki kızına talip olanları öldürüyordu.

Evippe: Epir kralı Tyrimmas''ın kızı, Odysseus onu baştan çıkarıp sonrada terk etmişti. Bu beraberlikten Euryalos dünyaya geldi. Evippe çocuğun boynuna ''Minnettarlığın İşareti'' yazan bir tabela asıp Odysseus''a yolladı.

Evohe: Dionysos''un lakabı. Cesaret oğlum anlamına gelir.

F

Fama: Halkın sesinin sembolü olan Fama Yer''in kızıdır. Sayısız gözü ve bir çok ağızı vardır. Çok hızlı uçardı.

Fames: Açlığın sembolü.

Fatum: Talih tanrısı.

Fauma: Tanrı Faunuz''un karısı

Faunus: Latinlerin ıssız tabiat tanrısı.

Febris: Hararet ve Sıtma tanrıçası.

Feronia: Çeşmelerin ve ormanların tanrıçası.

Fides: Verilen sözde durma tanrısı

Fors: Tesadüf tanrıçası.

Flora: Yeşeren bitkilerin çiçeklerin tanrıçası.

Furiler: Yeraltı cehenneminin korkunç devleri. Bunlar tanrıların intikam memurları idi ve Poseidon''un kanından olmuş Yer''in kızlarıydı.İnsanların kalplerine korku ve vicdan azbını getirirlerdi.

Fraude: Hile tanrıçası. Yarı insan yarı yılandı.

Furina: Hırsızların tanrısı.

Furrına: Tibet nehri kenarında bir kaynağın ve ormanın tanrısıydı.

G

Gaia: Toprak. Bütün tanrıların soylarının çıktığı en eski ve ilk tanrıça. Kocasız olarak 

Uranus''u doğurdu. Onun hem annesi hem de karısı oldu.

Galateia: Güzel bir peri kız, Kylop Polyphemos ona aşık olmuştu.

Galates: Herakles''in bir prensesten olma oğlu.

Galaotes: Apollon ile Themisto''nun oğlu

Galinthias: Herakles''in annesi Alkmene''nin arkadaşı. Alkmene doğum yapacağı sırada doğum tanrıçaları Hera''nın emriyle doğuma engel olmaya çalışınca Galinthias onları uzaklaştırdı ve Herakles''in doğumuna yardım etti fakat sonunda Hera onu Gelincik''e dönüştürerek cezalandırdı.

Ganges: Bir peri kızı olan Kalauria ile İndos''un oğlu ve Ganj nehrinin tanrısı. Sarhoş olduğu bir zamanda annesini iğfal ettiği için kendine geldiğinde utancından kendini nehre attı. O günden sonra bu nehrin adı Ganj oldu.

Ganymedes: Troia kralı Toros''un oğlu. Zeus onu sevdi ve Olympos''a yanına alarak orada alı koydu.

Geantes: Gaia''nın çocukları, Uranos''un yarasından akan kanlarla yaratıldılar.

Genius: Roma tanrısı. Bir nevi koruyucu melek görevini görüyordu. Her insanın kendine ait bir Genius''u olduğuna inanılırdı.

Gerena: Pygmeler bir nevi cüceler soyundan bir kadın. Tanrılara yüz vermediği için Turna kuşuna çevirildi.

Geras: İhtiyarlık tanrısı. Herakles bütün insanların yaşlandıkları zaman başına musallat olan bu tanrıyı mağlup etti.

Geryoneus: Üç başlı kocaman bir dev, Herakles tarafından öldürüldü.

Gigant''lar: Uranos''un yarasından akan kanlarla yaratılmış devler. Tanrılar bunlardan nefret ederlerdi. Dağ gibi gövdeleri yılan gibi kuyrukları vardı. Titanlarla birlikte Zeus''a karşı savaşmışlardı. Herakles teker teker hepsini mağlup edip Vezüv yanardağının altına hapsetti.

Glaukos: Sisypos''un oğlu. İnsan eti ile beslenen kendi atları tarafından parçalandı.

Gorgon''lar: Phorkos ile Keto''nun üç kızı. Saçları yılandan korkunç bakışlı ifritler. Bunlara bakan taş kesilirmiş. Stheno, Euryale ve Medusa adlarını taşıyan üç kardeşin en kötüsü Medusa idi.

Grazia''lar: Letafet perileri.

Gree''ler: Phorkos ile Keto''nun diğer üç kızı, doğuştan beyaz saçlıydılar.

Griffon''lar: Arslan gövdeli kartal başlı efsanevi kuşlar. Apollon''un hazinelerine bekçilik yapıyorlardı.

Gyges: Titanlardan biri. Uranos ile Gaia''nın oğlu, yüz kolu elli başı vardı.

H

Hades: Kronos''un oğlu. Cehennemlerin karanlık alemlerin ve ölüler diyarının tanrısı.

Haemon: Kral Oidipus''un kızı. Babası nişanlısı Antigone''u ölüme mahkum edince intihar etti.

Haemos: Boreas''ın oğlu Thrakia Tyranlarından biri.

Hagno: Lykea kaynağının perisi.

Halia: Rodoslu güzel bir kız. Poseidonla evlendi ve altı oğlu, birde kızı oldu. Halia''nın altı oğlu Aphrodite''in etkisi ile annelerine büyük bir aşk ve şehvetle bağlanınca babaları Poseidon onları öldürdü. Bu duruma çok üzülen kadın kendini denize atarak intihar etti.

Halirrhotios: Poseidon''un oğlu, Ares''in kızı Altippe''ye saldırdığı için Ares tarafından öldürüldü.

Halkyon: Kral Keyks''ın karısı.

Hamadryad: Ağaç perileri. Bir ağaçla beraber doğup onunla beraber ölen periler.

Harmonia: Aphrodite ile Ares''in kızı, Kadmos''on karısı. Kocası ile birlikte bir yılana dönüştürüldüler.

Hrpalyke: Tkrakia kralının kızı, küçük yaşta annesini kaybettiğinden babası onu kısrak sütü ile besleyip erkek gibi yetiştirdi.

Harminna: Irmak tanrısı Asopos''un kızı, Ares''ten Oenomaos adında bir oğlu vardı.

Harpyi''ler: Thaumas ile Elektra''nın kızları, fırtınanın ve ölümün sembolüydüler. Sirenlere benzerlerdi ve kanatlarıvardı.

Hebe: Zeus ve Hera''nın kızı. Gençliğin ve güzelliğin sembolü idi.

Hekate: Artemis''in yardımcısı iyilik sever bir tanrıça. Bir titan olan Perses ve Asteria''nın kızı idi. Darda kalanlara yol gösterirdi.

Hegeleos: Herakles''in torunu, Omphale ile Herakles''te olan Tyrsenos''un oğlu.

Hektor: Troialıların en büyük kahramanı, Akhilleus tarafından öldürüldü.

Helena: Menelaos''un karısı. Troia prensi Paris onu kaçırdığı için Yunanlılar Troia''ya saldırdılar. Zeus ile Leda''nın kızı olduğuna inanılırdı.

Helenos: Priamos''un oğlu. Troia''lıların kahini. Yunanlılara tahta atı yapmalarını söyleyerek yurduna ihanet etti.

Heliades''ler: Helios ile Klymene''nin kızları. Kardeşleri Phaeton''un ölümünden dolayı duydukları üzüntüden çok fazla ağladıkları için tanrılar onları kavak ağaçlarına dönüştürdüler.

Helike: Çocukken Zeus''u besleyen iki peri kızından biri. Daha sonrada Büyük ayıya çevirildi.

Helikon: İlham perileri Musa''ların kutsal dağı.

Helios: Güneş tanrısı. Hyperion ile Theia''nın oğlu. Deniz perilerinden Perseis ile evlendi. Bir çok çocukları oldu.

Helle: Phriksos''un kardeşi. Çanakkale boğazı eski adı olan Helles Pontos adını ondan almıştır.

Hellen: Deukalion''un oğlu bütün yunanlıların babasıdır. Bu nedenle Yunanlılara Hellenler denirdi.

Hemera: Gündüz. Nyks (Gece)   nin kardeşi. Fani insanlara ışığı getirirdi. Diğer adı Eos (Şafak)   tur.

Hemikynes: Köpek gibi ses çıkaran ve başlarıda köpeğe benzeyen tuhaf yaratıklar. Karadeniz kıyısında yaşarlarmış.

Heosphoros: Eos''un oğlu sabah yıldızı.

Hephaistos: Ateş tanrısı. Latinler Vulcain der.

Hera: Baş tanrıça. Zeus''un kardeşi ve karısı. Latinler Junon der.

Herakles: Zeus''un oğlu kuvvet tanrısı. Latinler Hercule der.

Herakliad''lar: Herakles''in soyundan gelenlere denir.

Hermaphrodite: Aphrodite ve Hermes''in oğlu. Salmikis adlı göl perisi ona aşık oldu, Hermaphrodite kendisi ile ilgilenmeyince tanrılardan ikisini bir bütün haline getirmelerini istemişti. O günden sonra aynı beden içinde hem kadın hemde erkek kişiliğini taşıdı. 

Herme''ler: Yolların koruyucuları

Hermes: Tanrıların ulağı habercisi.

Hermione: Menelaos ve Helena''nın kızı

Hero: Leandros''un sevgilisi olan rahibe. Sevgilisi ölünce, cesedinin başında oda kendini öldürdü.

Herse: Kekrops''un üç kızından biri. Athena Erkhthonos''u bu üç kardeşe emanet etmişti.

Hesione: Troia kralı Laomedon''un kızı.

Hesperidler: Güneşin battığı yerin perileri. Gecenin yani Nyks''in kızlarıdır.

Hesperos: Akşam yıldızı. Atlas''ın oğlu, insanlara yol gösterir iyilik eder.

Hestia: Kronos ile Rea''nın kızı. Romalılar ona Vesta derler. Aile ocağı tanrıçasıdır.

Hiera: Herakles''in oğlu olan Telephos''un karısı. Yunanlılar Troia''ya karşı savaş açtıklarında Hiera kadınlardan kurulu bir orduyla onlara karşı kouymuştu.

Hirodyeller: Tanrıların tapınaklarına ait olan kadın ve erkek köleler.

Hilaeira: Leukippid''lerden biri, Phoebe''nin kızkardeşi.

Hilebie: Karia bölgesi krallarından birinin kızı. Lyrkos adında bir Yunanlıyla evlendi. Kocasının her türlü ihanetine rağmen hep ona sadık kaldı.

Himalia: Bir peri kızı. Zeus''tan üç çocuğu oldu. Bu üç oğlan buğdayın geçirdiği safhaları sembolize eder. Spartaeos(Tohum eken) , Kronios(Buğday yetiştirici) , Kytos(Ekmekçi)

Himeros: Aşk isteğinin sembolü Eros''a arkadaşlık ederdi.

Hippe: Kentaur, Khrion''un kızı.Eole''den hamile kalınca babasının korkusundan Pelion dağına kaçtı fakat babası onu buldu. Bunun üzerine kendisini kurtarmaları için tanrılara yalvardı. Tanrılarda onu at şeklinde bir burç yapıp gökyüzüne kaldırdılar.

Hippios: Poseidon ile Athena''nın lakapları.

Hippo: Skedasos''un iki kızından birinin adı. Kardeşi ile birlikte Ispartalıların saldırısına uğradılar. Bu olaydan sonra intihar ettiler.

Hippodemia: Pisa kralı Oinomaos''un kızı. Pelops onunla zorla evlendi. İki çocukları oldu. Arteus ile Tyestes.

Hippo Kampos: Yarısı at yarısı balık olan deniz hayvanları. Nereidler bunların üzerine binip dolaşırlardı.

Hippolyte: Amazonların kraliçesi. Ares''in kızı olduğu söylenir, Herakles tarafından öldürüldü.

Hippolytos: Thesseus''un Amazonlar kraliçesi Atiope''den olan oğlu.

Hippomedon: Dev cüsseli bir kahraman, Thebai''ye karşı savaşan Yedililerdem biriydi.

Hippomenes: Megeros ile Merope''nin oğlu. Atalante ile evlendi.

Hippotes: Heraklid''lerden biri.

Historis: Kahin Tresias''ın kurnaz kızı. Herakles''in doğumu sırasında, Hera''nın emri ile doğuma engel olmaya çalışan doğum tanrıçalarını kurnazlıkla oradan uzaklaştırıp doğumun olmasını sağladı.

Hora''lar: Zeus ile Themis''in üç kızı. Bunlar zamanların ve mevsinlerin tanrıçalarıdır.

Horkios: Zeus''un lakabı.

Hyad''lar: Atlas''ın kızları. Zeus''u Dodon''da onlar büyüttü

Hyakinthos: Amiklas ile Diomede''nin oğlu. Çok güzel bir delikanlıydı. Thamyris adlı bir erkek ona aşık oldu, Apollon da ona gönül verenlerdendi.

Hybris: Annesi Koros idi. Hayasızlığın, ölçüsüzlüğün sembolü.

Hydne: Skyttis''in kızı. Baba kız çok usta dalgıçlardı.

Hydra: Lerna bataklığında yaşayan onlarca başı olan büyük bir yılan.

Hygieia: Sağlık tanrıçası ve Asklepios''un kızlarından biri.

Hylas: Kral Theiodamas''ın oğlu Herakles Hylas''ın babasını öldürdükten sonra delikanlıyı uşak olarak yanına almıştı. Onu her yere beraberinde taşırdı.

Hyllos: Herakles ile Dejanire''nin oğlu

Hylonome: Kentaur Kyllaros''un karısı. Kocası öldürülünce intihar etti.

Hymenaios: İlham perilerinden birinin oğlu. Gençlik ve evlendirme tanrısı. Düğünlerde söylenen türküleride o ilham eder.

Hymnos: Phrygia''lı bir çoban. Artemis''in arkadaşlarından biri olan Nikaea adlı periye aşık olmuştu. Ama Nikaea ona yüz vermedi ve bir gün kendisine aşkını ilan etmesine sinirlenip onu öldürdü.

Hyperion: Titanlardan biri. Uranos ile Gaia''nın oğlu. Kız kardeşi Heia ile evlendi. Helios, Eos ve Selene''nin babası.

Hypermestra: Danaos''un elli kızından biri. Zorla evlendirilen elli kız evlendikleri gece kocalarını öldürürken kocasına tek zarar vermeyen kardeş Hypermestra idi.

Hypnos: Uyku tanrısı. Ereos ve Nyks''in oğlu.

Hypsipyle: Lemnos adası kralı Thoas''ın kızı. Lemnos kadınları ayaklanıp kocalarını öldürmeye başlayınca Hypsklye yaşlı babasını kaçırdı ve Khios adasına götürdü. Arganaotlar bu adaya çıktığı zaman Jason ''la karşılaştı ve ona aşık oldu. Jason''dan iki çocuğu oldu.

Hyrieus: İhtiyar bir çiftçiydi ancak büyük tanrıları evinde misafir ettiği için tanrılar ona karşı hep iyiydiler bu yüzden yaşlı adam bir karısı olmadı halde erkek çocuğu olmasını istediğinde onun bu isteğini yerine getirdiler.

İ

İarea: İda dağının güzel perilerinden biri.

İakkhos: Eleusis Mysteria''larının tanrısı. Bazıları onun Demeter''in oğlu olduğuna inansalarda, asıl inanış Zeus ile Persephone''nin oğlu olduğu yolundadır. Asıl adı Zagreus olan bu çocuğu Zeus kıskanç karısının Zulmünden kurtarmak için şekilden şekile soktu. Onu bir boğa şekline soktuğu gün Hera''nın takipçileri onu yakaladılar ve kestiler. Zeus oğlunun yardımına yetişemedi. Apollon''a cesedinden arta kalanları Parnassos dağına getirmesini söyledi. Apollon çocuğun halen çarpmakta olan kalbini getirdi. Zeus kalbi emdi ve Zagres''I tekrar yarattı.Bu defa ona İakkhos adını koydu.

İalemos: Apollon ile Kalliope''nin oğlu. Genç yaşta ölenler için söylenen hüzünlü mersiyelerin taratıcısı.

İambe: Pan ile peri Ekho''nun kızı. Hizmetçilik yaparken kızını arayan kederli Demeter''I eğlendirmeye çalışırdı.

İamos: Kahramanlık devirlerinde yetişmiş bir kahin. Apollon ile Evadne''nin oğlu. Kahinliği babası Apollon''dan öğrendi.

İanus: Romalıların inancına göre evlerin kapılarını bekleyen tanrı idi. 

İapetos: Prometheus''un babası.

İasion: (Jasion)   Zeus''un oğlu Demeter''in sevgilisi. Demeter''den Plutos (Zenginlik)   adında bir oğlu oldu.

İdas: Aphareus ile Arene''nin oğlu. Apollon''un sevdiği Marpesse adlı kızı kaçırınca Tanrıyla aralarında büyük bir kavga çıktı. Sonunda seçimi Marpesse''ye bıraktılar. Apollon''un sevgisine fazla güvenemeyen Marpesse İdas''ı seçti.

İdmon: Argonautlardan biri, Apollon''un oğlu. İyi bir kahindi. Hatta kendisinin öleceğini bile bile Arganautlar seferine katıldı.

İdaeos: Paris ile Helene''nin oğlu

İkadios: Lykialı bir peri kızı ile Apollon''un oğlu. Bugünkü Gelemiç''I kurmuştu.

İkarios: 1. Attika bölgesinin efsanevi kralı, Dionysos''u evinde misafir etmiştİ 2.Penelope''nin babası. Güzel kızını almak isteyenler arasında bir spor müsabakası tertip etti. Müsabakayı Odysseus kazandı.

İkaros: Daidalos''un oğlu

İkelos: Phobetor adıylada anılan insana ylnız hayvan şekli ile görünen bir rüya tanrısı.

İksion: Baş tanrının karısı Hera''ya göz koyan ve onu baştan çıkarmaya çalışan Lapith''ler kralı. Zeus tarafından cezalandırıldı.

İllia: Romulus ve Romus''un annesi olan Reasilve''nin bir diğer adı.

İllione: Priamos ile Hekube''nin kızı, Polymestor''un karısı.

İlithya: Zeus ile Hera''nın kızı. Doğum tarıçalığı yapardı. Bazı kadınların doğumlarına engel olarak onlara acılar çektirirdi.

İlos: Dardanos''un oğullarından biri. Bir kahraman ve Palladion şehrini kurdu.

İnakhos: Argos''un efsanevi kralı. Okeanos ile Tethys''in oğlu İo''nun babası.

İno: Bir adıda Leukothea olan İno Kadmos ile Harmonia''nın kızı, Kral Athamas''ın ikinci karısı idi. Athamas''tan Learkhos ve Melikertes adında iki oğlu oldu. Kardeşi Semele''nin ölümü üzerine henüz küçük yaşta olan Dianysos''u yanına alıp bakma isteyince Hera buna çok sinirlenip karı kocanın aklını başından aldı. Çıldıran İno oğlu Melikertes''I kaynar suyun içine attı. Kocasıda Learkhoz''u bir geyik olarak görerek av sırasında oğlunu vurdu. İno ne yaptığını fark edince oğlunun cansız bedenini kucağına alıp saraydan kaçtı ve bir kayalığın üzerinden kendini denize attı. Deniz tarıları bu kadına acıyıp onu Lekothea adında bir deniz tanrıçası oğlunu da Palaemon namıyla bir deniz tanrısı yaptılar. 

İo: İnakhos''un kızı. Hera mağbedinin rahibesiyken Zeus ona görür görmez tutulmuştu. 

İobates: Lykia''nın efsanevi kralı.

İobes: Herakles''in Kerthe''den olan oğlu.

İodama: Beotia mabedinin rahibesi. Bir gece zeka tanrıçası ona kalkanını takmış olarak görününce İodama taştan bir heykel oldu.

İokaste: Oidipus''un annesi. Daha sonradan öz oğlu olduğunu bilmeden Oidipus ile evlendi.

İokastos: Rüzgar tanrısı Eolos''un oğlu.

İola: Oihalia kralı Eurytos''un kızı.

İolaos: İphikles ile Automeduse''nin öğlu. Herakles''in yeğeni. Herakles''e yardım eder onun arabasını sürerdi. Herakles bu kahramanı çok beğendiğinden karısı Magara''yı ona armağan etti. Leipehile (Tekedilmiş aşk)   adında bir kızları oldu. Herakles''in ölümünden sonra İolaos onun çocuklarını himayesi altına alıp baktı.

İon: Ksausthos ile Kreuse''nin oğlu. Hellen''in torunu İonia''lar adlarını İon dan aldılar.

İope: Eolos''un kızı, Kepheos''un karısı.

İoksos: Theseus''un torunu.

İphidamas: Troia''lı Antenor''un oğullarından biri. Agememnon tarafından öldürüldü.

İphigeneia: Agamemnon ile Klytemenstre''nin kızı. 

İphikles: Herakles''in ikiz kardeşi. Babaları ayrı olmasına ve anneleri onlara farklı zamanda hamile kalmasına rağmen tanrı Zeus sevdiği kadın fazla acı çekmesin diye iki doğumun aynı anda olmasını sağladı. İki kardeş birlikte büyüp, gene birlikte bir çok savaşa katıldılar.

İphiklos: Theselia''da bir şehrin kralı olan Phylakos''un oğlu. Çok usta ve hızlı bir koşucuydu. Ekin tarlasında başakları eğmeden koşabilmesi ile ün salmıştı.

İphimedia: Triops''un kızı. Amcası Aloeus ile evlendi ondan iki oğlu oldu. İphimedia deniz tanrısına aşık olmuştu. Bütün günü deniz kıyısında geçiriyordu. Nihayet deniz tanrısı onun bu saf temiz sevgisine karşılık verdi ve onunla beraber oldu.

İphis: 1. Kıbrıslı güzel Anaksareta''nın sevgilisi, Aphrodite onu kayay çevirdi. 2.Girit''li Ligdos ile Telethausa''nın kızı. Babası bir erkek evlet istediğinden, annesi herkese İphis''in bir erkek olduğunu söyleyerek kandırdı. Bir erkek gibi giydirilip erkek gibi yetiştirildi.Yaşı ilerleyipte evlenme çağına gelince kendisine aşık olan İanthe adında bir kızla nişanlandı. Annesi bu durum karşısında telaşa kapılıp bereket tanrıçası İsis''e yalvardı. Tanrıça ona acıyıp İphis''I güzel bir kızken yakışıklı bir delikanlıya dönüştürdü.

İphistos: Oikhalia kralı Eurytos''un oğlu. Arganuatlar seferine katıldı. Herakle tarafından öldürüldü.

İrene: Eirene diye anılan İrene Horalardan biridir. Barış sembolüydü. 

İris: 1. Yeşil ırmağın eski adı.

2.Thaumas ile Elektra''nın kızı. Okeanos soyundan gelmiştir. O gökle yeri birbirne bağlayan ebemkuşağının sembolüdür.

İsis: Güneş tanrısı Horos''un annesi.

İskender: Bir kahraman. Zeus''un oğlu olduğuna inanılırdı.

İskhenos: Gigas''ın oğlu. Olympia şehrinde kıtlık hüküm sürmeye başlayınca tanrılar bu kıtlığın ancak şehrin asıl delikanlısınınkurban edilmesi ile önleneceğini söylediler. Bunun üzerine İskhenos halkının kurtulması için kendi arzusuyla kurban oldu.

İsmene: Oidipus ile Jokoste''nin kızı, Antigone''nin kardeşi.

İsmenos: Niobe ile Amphion''un oğlu. Kardeşleri ile birlikte Apollon tarafından öldürüldü.

İsos: Troia prenslerinden biri Agememnon tarafından öldürüldü.

İssa: Lesbos''lu Makareus''un kızı. Apollondan Prylis isimli bir oğlu oldu. Daha sonradan Prylis ünlü bir kahin oldu.

İstros: Okeanos ile İethys''in oğlu. Bugün Tuna nehri dediğmiz nehrin tanrısı.

İtalos: Girit kralı Minos''un torunu, İtalya''ya adını veren kahraman

İtylos: Aedon ile Zetons''un oğlu. Yalnışlıkla annesi tarafından öldürülünce bülbül oldu.

İtys: Thrakia kralı Tereos ile Prokne''nin oğlu.

İulus: Aeneos''un oğlu Askanius''un bir diğer adı.

İuno: Heranın latince adı.

İupitter: Zeus''un latince adı.

İynks: Pan ile Ekho''nun kızı. Zeus ile İo''nun beraberliklerinde onlara yardımcı olduğu için Hera onu bir kayaya çevirdi.

J

Jasius: Abas''ın oğlu, Dardanos''un kardeşi.

Jaso: Esklapios ile Epinoe''nin kızı. Hastalıklar tanrıçası.

Junon: Romalıların baş tanrıça Hera''ya taktıkları ad.

Jupiter: Romalıların baş tanrı Zeus''a verdikleri ad.

Juturne: Romalıların su kaynakları tanrıçası.

Juventus: Gençlik tanrıçasının adı. Romalılar gençlik çağına giren delikanlılara bu adı koyardı.

K

Kaanthos: Okeanos''un oğlu. Apollon kızkardeşi Melia''yı kaçırınca babası Kaanthos''u peşlerinden gönderdi. Kardeşini Apollon''un kollarının arasında görünce öfkesinden tanrının mabedini ateşe verdi. Bunun üzerine Apollon da onu oku ile öldürdü.

Kabarnos: Demeter''in kızının Hades tarafından kaçırıldığını haber veren Paros''lu genç.

Kaberio: Proteos''un kızı. Hephaistos ile olan evliliğinden Kadmilos adında bir oğlu oldu.

Kabir''ler: Hephaistos ile Kaberio''nun soyundan gelen tanrılar. 

Kabirid''ler: Kabirlerin kardeşi olan üç peri kızı.

Kadmos: Thebia krallarından biri. Agenor ile Telephassa''nın oğlu.

Kadmilos: Finikelilerin tanrılarından biri.

Kaekulus: Yanardağların tanrısı Vulcain''in oğlu. Efsaneye göre annesi ocak başıda otururken göğsüne sıçrayan bir kıvılcımdan ona hamile kalmıştır.

Kaeria: Miletuslu bir çömlekçinin kızı Kahire''ye adını vermiştir. Kadros''un oğlu Nephelus bir şehir kuracak yer ararken tanrılar ona genç bir kızın toprağı su ile karıştırdığı yerde bir şehir kurabileceğini söylediler. Nephelus Miletos''ta geçerken bu çömlekçi kızla karşılaşmış ve şehri kurmuştur.

Kaineus: Lapith''lerden Elatos''un kızı. Poseidon bu kıza gönül vermişti.Güzel kız aşık tanrıdan cinsiyetinin değiştirilmesini ve yaralanmaz bir delikanlı haline sokulmasını istedi ve tanrı Poseidon isteğini kabul edip onu erkeğe dönüştürdü ve adı Kaunos oldu. Lapithlerle Kentaurlar arasındaki meşhur savaşa katıldı. Yaralanmadığı için Kentaurlar onu sopayla dövüp dirir diri toprağa gömdüler.

Kairos: Fırsat tanrısı. Zeus''un en genç oğlu. Omuzlarında ve ayaklarında kanatları vardı 

Kalais: Boreas veOreithya''nın oğlu, çok sert esen rüzgar.

Kalamos: Menderes nehrinin tanrısının oğlu.

Kalkhas: Thestor''un oğlu ünlü bir kahin.

Kalkhos: Sihirbaz Kirke''ye gönül vermiş bir kral. Kirke onu domuza çevirdi.

Kalliope: Şairlere kahramanlık destanları yazdıran ilham perilerinden biri.

Kallirrhoe: Nehir tanrısı Akheloos ile Skamandros''un kızı.

Kallisto: Lykaon''un kızı Artemis''in arkadaşı

Kalypso: Odysseus''a gönül veren bir peri kızı.

Kambles: Lydia kralı. Doymak nedir bilmeyen bu kralkendi karısını bile yedi.

Kampania: İtalya da en eski Yunan kolonisi.

Kanake: Eolos''un kızlarından biri.Kardeşi Makareus''un çocuğunu doğurunca Eolos ona kendisini öldürmesini emretti.

Kapaneus: Thebai''ye hücum edenlerden biri. Dev cüsseli korkunç bir adam.

Kapadokia: Amazonların yaşadıkları bölge 

Karkinos: Lerne bataklığında yaşayan bir yaratık, Herakles tarafından öldürüldü.

Karneios: Dorların eski tanrısı.

Karya: Lakonia''lı güzel bir kız sonradan fındık ağacına çevirildi.

Kassandra: Priamos ile Hekube''nin kızı. Apollon bu kıza aşık olmuş ve kahinlik

öğretmişti.Troia şehri yunanlıların eline geçtiğinde Agamemnon bu kızı cariyesi olarak yanına aldı.

Kassiepeia: Kepheus''un karısı, Andromeda''nın annesi.

Kassotis: Musa ilham perilerinin bir kaynağı.

Kastalia: Güzel bir kız olan Kastalia''ya Apollon aşık olmuştu. Apollondan kurtulmak için kendini bir kaynağa atıp öldürdü.

Katreos: Minos''un Pasiphae''den olma dört oğlundan biri.

Kaunos: Byblis''in ikizkardeşi Miletos''un oğlu. Kız kardeşini sevdiği için kaçtı ve Karia''ya giderek Kaunos şehrini kurdu.

Kaystros: Lydia da akan bir çayın tanrısı. Ünlü Ephesos''un babası.

Kekrops: Attika''nın efsanevi ilk kralı.

Kedalion: Hephaistos''un ustası ve öğretmeni. Hephaistos''a demir dövmesini o öğretti.

Keleos: Eleusis kralı

Kelmis: Zeus''un süt annesinin babası. Baş tanrının insanlar gibi fani olduğunu söylediği için elmas parçasına dönüştürüldü.

Keltos: Kelt''lere adını veren kahraman

Kentaurlar: Dev cüsseli acayip yaratıklar, üst kısmı insana alt kısmıda ata benzerdi.

Kepheus: Andromeda''nın babası, Belos''un oğlu.

Kerambos: Thesselia da bir çoban. Tufan sırasında kanatlı bir yengeç dönüştürülerek kurtuldu.

Keramos: Attika''lı bir kahraman. Çömlekçilerin mucididir.

Kerberos: Ölüler diyarının kapısıı bekleyen köpek.

Ker''ler: Gecenin kızları, ölüm perileri kan emici cinler.

Keres: Demeter''in latince adı.

Kerkaphos: Helios''un yedi oğlundan biri.

Kerkop''lar: Okeanos''un kızlarından Theia''nın iki oğluna verilen ad. İri cüsseli iki hayduttu.

Kerkyon: Yolkesip adam öldüren bir haydut.

Kerkyra: Asopos ırmağının kızlarından biri. Poseidon bu kız gönül verdi.

Keroessa: İo ile Zeus''un kızı.

Keryntos: Altın boynuzlu dişi geyik.

Keto: Denizin kızı. Öz kardeşi Phorkys ile evlendi.

Keyks: Eosphoros''un oğlu. Halkyone''un kocası.

Khaos: Kainat yaratılmadan önce mevcut sonsuz boşluk.

Khariklo: Athena''nın yakın arkadaşı olan bir peri kızı.

Kharit''ler: Letafet perileri.

Kharon: Ölülerin ruhlarını Styx ırmağından geçirip yer altı ülkesine götüren kayıkçı.

Khelone: Bir ırmağın kıyısında yaşayn güzel bir peri kızı. Hera ile Zeus''un düğününe katılmadığı için kaplumbağa''ya çevirildi.

Khimaereus: Prometheus ile Atlas''ın kızı Keleano''nun iki oğlundan biri.

Khimaira: Ağazından ateş püsküren canavar.

Khione: Nil nehri ile Kalirrhoe''nin kızı. Bir çiftçi tarafından tecavüz edilince Zeus onu kar tanelerine çevirdi.

Khiron: Kentaurların en meşhuru, en bilgini, en akıllısı. Kronos ile Philyra''nın oğlu idi.Yarı insan yarı tanrıydı, bu yüden ölümsüzdü, ancak Herakle istemeyerek onun ölümüne sebep oldu.

Khronos: Zamanın göğün sembolü

Khrysaor: Altın kılıç, Poseidon''un oğlu.

Khryseis: Agamemnon''un sevgilisi

Khryseos: Khryseis''in babası

Khrysopelea: Bir ağaç perisi. Arkadia''lı bir meşenin içinde yaşıyordu.

Khthonik: Toprağı temsil eden yer tanrıları.

Kikon''lar: Zone sahil bölgesinde yaşayan vahşi bir halk.

Kimmer''ler: Yeraltı alemine inenlerin geçmek zorunda oldukları karanlık diyarlara ve burada yaşayanlara verilen ad.

Kinyras: Kıbrıs kralı. Öz kızı Hyrra''dan Adonis adında bir oğlu vardı.

Kirke: Ünlü büyücü kadın. Helio ile Perseus''un kızı.

Kithairon: Çok güzel bir delikanlıydı.Tisiphoe''ye yüz vermediği için atlarındn biri yılana çevrildi ve delikanlıyı soktu.

Kleitos: Eos''un aşık olduğu bir delikanlı. Korenos adında bir oğulları oldu.

Kleobis: Hera mabedi rahibesi Kydiphe''nin oğlu.

Kleostratos: Bir ejdere kurban edilen delikanlı. Etrafı çengellerle kaplı bir kürnin içindeyken ejder onu yutunca ejderin içine sağlam olarak girerek onu içten parçalayarak öldürdü.

Klinis: Babilli zengin ve dindar bir adam

Klotho: Baht perilerinden biri. Hayat ipliğini eğirir.

Klymene: Okeanos ile Tethys''in kızı.Apollon bu kıza gönül vermişti. Bu birliktelikten Phaeton doğdu

Klymenos: Arkadia''lı krallardan biri. Kendi kızı Harpalyke''ye aşık olmuştu. 

Klytaimnestra Agememnon''un karısı. Sevgilisi Aigisthos ile birlikte Agememnon''u öldürdüler. Oğlu Orestes sonradan babasının intikamını aldı ve annesi ile sevgilisini öldürdü.

Klytie: Apollon tarafından sevilen güzel bir kız. Apollon bu kızdan çarçabuk bıkarak bu sefer kız kardeşi olan Leukothoe''ye gönül verdi. Kardeşi ile Apollon arasındaki ilişkiyi babasına anlttığında babası tarafından karanlık bir hendeğe atılarak cezalandırıldı.

Kokytos: Ölüler ülkesinde, yer altında akan gözyaşları ırmağının adı.

Komaetho: Teleboen''ler kralı Pterelas''ın kızı. Babası Amphitryon ile savaşırken ona ihanet etti.Çünkü babasının düşmanına aşıktı 

Kombe: Asopos ırmağının tanrısının kızı. Çocukları ile birlikte zalim kocasından kaçtı ve Phrigia''ya yerleşti fakat daha sonradan kendi çocukları tarafından öldürüldü.

Kora: Demeter''in kızı Persophene''in diğer adı..

Korinthos: Zeus''un oğlu.

Koroebos: Poeno canavarını öldüren kahraman.

Koronides: İki kız kardeş, Metiokhe ve Menippe''ye verilen ad. Veba salgınını önlemek için kurban edildiler.

Koronis: Lapith''ler kralı Phleyas''ın kızı. Apollon''dan Asklepios adında bir oğlu oldu. Hamileliği sırasında bir başkasıyla evlşenerek Apollon''a ihanet ettiği için öldürüldü.

Korythos: Zeus ile Atlas''ın kızı Elektra''nın oğlu

Kreon: Korinthos kralı

Kres: Zeus''un bir peri kzından olan oğlu

Kresphontes: Herakidlerden biri.

Kretheus: Eolos ile Enarete''nin oğlu.

Kreusa: Atina kralı Erekhtheus''un kızı. Apollon''dan İon adında bir oğlu oldu.

Kritheis: Anadolu da bir peri kızı. Meles nehri tanrısından Homeros adında bir çocuğu oldu.

Korokos: Çok güzel bir delikanlıydı. Smilaks adında bir peri kızına aşık oldu, aşkına karşılık alamayınca sarardı soldu. Onu Safran çiçeğine dönüştürdüler.

Krommyon: Theseus''un öldürdüğü azgın bir yaban domuzu.

Kronos: Zeus''un lakabı

Krotopos: Argo kralı, Agenor''un oğlu.

Krotos: Pan ile Eupheme''nin oğlu. Eupheme ilham perilerine süt anneliği yapıyordu.

Kuret''ler: Zeus küçükken ağlamasını babası duymasın diye çevresinde gürültü yapıp hoplayıp zıplayan delikanlılar.

Kyane: Syraküze''li bir peri kızı. Hades Persophene''I kaçırdığında bu peri kızı Persophene''i kurtarmaya çalışmış. Bunun üzerine Hades onu göl''e çevirmiş.

Kyanippos: Thesselia''lı Pharaks''ın oğlu. Leukone adlı çok güzel bir kızla evlenmişti.

Kybele: Eski Anadolu da Phrigia''da tanrıların anası sayılır.

Kykhreus: Poseidon ile Salamis''in oğlu. Salamine adasına musallat olan korkunç ejderi yok etti.

Kyklop''lar: Alınlarının ortasında tek gözleri olan devler.

Kyknos: Poseidon''un oğlu. Kuğular tarafından büyütüldü.

Kydnos: Anfiale''nin oğlu, ayrı insan yarı nehir idi.

Kyillene: Arkadia''lı bir peri kızı. Lykon''un annesi.

Kynosura: İda dağında bulunan bir peri kızı. Zeus''a süt annelik etti.

Kyparissos: Telephos''un oğlu, çok güzel bir delikanlıydı. Apollon bu delikanlıya aşık oldu.

Kypris: Aphrodite''in bir lakabı

Kyrene: Lapith''ler kralının kızı. Ormanda vahşi bir hayat yaşıyordu. Apollon onu görüp aşık oldu ve onu Lybia''ya götürerek orada evlendi.

Kyzikos: Ünlü bir kahraman Bugün kapıdağ yarımadası üzerindeki eski ve tarihi bir şehre adını vermiştir.

L

Ladda: Amphion''un kızı, topal ve çirkin olduğundan arkadaşları tarafından hor görülen Ladda Aetion ile evlenmişti. Bu çirkin kadından doğacak çocuğun bir gün Korinthos''a kral olacağını tanrılar haber verdiklerinden, çocuğun öldürülmesi için on seçme katil yollandı. Ancak çocuğun masumiyeti karşısında katillerin hiç biri ona zarar vermeye kıyamamışlardı.

Laddakid''ler: Thebia kralı Labdakos''un soyundan gelenlere verilen ad.

Ladon: Arkadia''da kıyısının güzelliği ve suyunun duruluğu ile meşhur ırmağın tanrısı. Stymphalis ile evlendi ve Daphne adlı güzel bir kızları oldu.

Laertes: Odyseus''un babası.

Laios: Oidipus''un babası.

Laistrogon: İnsan etiyle beslenen korkunç devler.

Lakedaimon: Zeus ile Taygete''nin oğlu. Lakedemonia bölgesine adını verem kahraman.

Lakhesis: Üç Park (Moiora)   dan biri iği tutar insan ömrünü eğirirdi.

Lamia: Poseidon''un kızı. Çocukları çalan ve yiyen iğrenç bir varlık. Zeus''un sevgililerinden biriydi ve ondan bir çok çocuğu olmuştu ancak kıskanç Hera çocuklarını öldürtünce Lamia çıldırdı ve çocuklara düşman kesildi. 

Lampetia: Helios (Güneş)   ile Nere''nin kızı. Bir adada çobanlık yapardı.

Lampetie: Apollon ile Klymene''nin kızı. Kardeşi Phaeon''un (Kıvılcım)   ölümüne öyle üzüldüki tanrılar haline acıyıp onu kavak ağacına dönüştürdüler.

Laodamas: Thebai kralı. Eokles''in oğlu.

Laokoon: Thymbrea şehrinin Apollon mabedi rahibi idi. Troia savaşı sırasında Troialılara ağaç atı şehre sokmamalarını söylemişti ama kimse onu dinlemedi. Yunanlıların dostu olan tanrılarda Troia''lılara akıl öğretmeye kalkıştığından dolayı onu cezalandırdılar. Bir gün deniz kıyısında Tanrı Poseidon''a kurban keserken denizden iki koca yılan çıkıp iki oğlu ve Laokoon''u parçalayarak öldürdüler.

Laodameia: Bellerophon''un kızı ve Zeus''un sevgilisi. Lykia kralı Sarpedon bu aşkın sonucu dünyaya gelmiştir.

Laodemeia: Akastos''un kızı ve Hector''un öldürdüğü Protesillas''ın karısıdır. Kocası öldükten sonra ona benzeyen bir heykel yaptırıp onunla avunmaya çalıştı ancak babası bu durumdan hoşlanmayıp heykeli yaktırdı. Bununüzerine Laodemeia da kendini heykelle beraber ateşe attı.

Laodike: Priamos''un en güzel kızı. Heliakon ile evlenmişti. Daha çok gençken Troia''ya gelen bir elçiden bir oğlu olmuştu. Troia düştükten sonra Laodike galipler önünde kaçarken toprak onu yuttu.

Leomedon: Troia kralı İlos ile Euridike''nin oğlu ve Priamos''un babası. 

Lapith''ler: Thessalia da yaşayan dev cüsseli insanlar. 

Lara: Lauium ırmağının perisi. Zeus''un Juturne adındaki peri kızına olan aşkını Hera''ya anlattığı için Zeus onun dilini kesti ve Hermes''le birlikte cehenneme yolladı.Ancak Hermes bu güzel periye aşık oldu ve buperide Lares adında iki çocuğu oldu.

Lar: Romalıların ocakbaşı tanrısı.

Larv''lar: İnsanlara bela olan habis ruhlar.Ellerinde uğursuzluğu sembolize eden baykuş taşıyan asık yüzlü, beyaz uzun sakallı ihtiyarlardı.

Leandros: Abydos''lu bir genç. Hero''ya olan aşkı dillere destan oldu.

Learkhos: İno ile Athamas''ın oğlu. Hera''nın kinine kurban gitti.Bir çılgınlık anında babası tarafından öldürüldü.

Leda: Etolia kralı Thestios''un kızı, Tyndaros''un karısı.Zeus''tan Kastor ve Pollüks adında ikizleri oldu.

Lemurlar: Ölülerin evlere bela olan hayallerine denir.

Leontikhos: Çok sevdiği nişanlısı ile beraber bir zalim tarafından öldürülen Samos''lu bir genç.

Lerna: Bataklık bir göl. Herakles bu gölde aılı bir ejder öldürdü.

Lethaus: Eos''un lakabı

Lethe: Cehennemde akan nehirlerden biri.

Leto: Apollon ile Artemis''in anneleri

Leukas: Yunan denizinde kıyıya çok yakın etrafı sarp bir ada. 

Leuke: Okeanos ile Tethys''in kızı. Hades''in ölümsüz sevgilisi.

Leukippos: Leukippid''lerin babası, Perieres''in oğlu.

Leukothea: Kadmos''un kızı İno; bir deniz tanrıçası olunca bu adı aldı.

Liber: Dionysos''un latince adı.

Libitina: Roma da ölüler için yapılan merasimi koruyan tanrıça

Libya: Epaphos''un kızı. Poseidon''dan Agenour ile Belu adında iki çocuğu oldu.

Likhas: Herakles''in arkadaşlarından biri.

Linos: Apollon''un oğlu.Efsanevi şair, Herakles''in musiki hocası.

Lita''lar: Yalvarma yakarma dua tanrıçaları.Zeus''un kızlarıdır.

Lityerses: Phrigia''da Kelaene''nin zalim kralı. Midas''ın oğlu. Herakles tarafından öldürüldü.

Lotis: Güzel bir peri kızı.Anadoluda Lampsakos şehrinin tanrısı Priapos Lotis''e aşık olmuştu. Güzel peri sonradan Lotos ağacına dönüştürüldü.

Lukifer: (Lucifer)   Sabah yıldızı Phosphoros''un latince adı.

Luna: Romalıların ay tanrıçasına verdikleri ad.

Lydia: Batı Anadoluda İzmir bölgesinde bir krallık.

Lykaon: Arkadia kralı. Kallistonun babası.

Lykastos: Ares ile Phylonome''nin oğlu.

Lyke: Kır perisi. Daphnis''I sevdi.

Lykeion: Mukaddes bir orman. Aristoteles burada ders verirdi.

Lykia: Eski anadoluda Fethiye, Elmalı, Finike bölgesi.

Lykios: Babilli Klinis''in oğlu. Tanrılara eşek kurban ettiği için kargaya çevirildi.

Lykomedes: Sykros kralı

Lykos: Thebai kralı Nyteus''un kardeşi. Dirke''nin Antiope''ye işkence yapmasına izin verdiği için Antiope''nin oğulları tarafından öldürüldü.

Lykurgos: Dionysos''a kafa tutan Thrakia''lı kral.

Lynkeus: Arganaut''lardan biri Messenia kralı Aphareus''un oğlu. Gözleri rontgen ışığından daha kuvvetliydi ve herşeyi görürdü.

Lyssa: Gecenin kızlarından biri. Hiddet ve kızgı 

M

Maia: Atlas ile Pleione''in kızı. Zeus ona gönül vermişti. Kyllen dağında onunla evlendi ve Hermes doğdu.

Mainad''lar: Dionysos''un yanında gezen Bakkhalar.

Makareos: Eolos''un oğlu. Kendi öz kardeşi ile sevişmiş ve ondan bir oğlu olmuştu. Eolos bu çocuğu köpeklere yedirdi.

Makhaon: Kahramanlık devrinin ünlü hekimi.Asklepios''un oğlu. Podaleiros''un kardeşi.

Magnes: Medea''nın hizmetinde çalışan genç bir adam. Medea tarafından mıknatısa çevirildi.

Manto: Ünlü kahin Teiresias''ın kızı. Kör olan babasını elinden tutarak gezdiren Manto babası gibi gaipten haberler verirdi. 

Markıs: Hera''nın süt annesi.

Marpessa: Ares''in torunu Evenos''un kızı. İdas''la nişanlı iken Apollon onu kaçırınca İdas sevgilisi uğruna Apollonla döğüştü. Fakat Marpessa Apollon''un sevgisine güvenmediği için İdas''ı tercih etti.

Mars: Harp tanrısı Ares''e Romalıların verdiği ad.

Mater Matuta: Romalıların şafak tanrısı.

Meandros: Menderes nehrinin tanrısı. Okeanos ile Tethys''in oğlu.

Medea: Kolkhid kralı Aeites''in kızı. Sihirbaz Kirke''nin yeğeni.

Medos: Medea''nın oğlu

Medusa: Phorkos''un kızları olan üç Gorgon''dan en kötüsüdür. Saçları yılan gibidir. Ve ona bakan taşa dönüşürdü.

Megaira: Uranos''un kanından yaratılan Erinyler denilen kin ve nefret tanrılarından biriydi.

Megara: Thebaİ kralının kızı, Herakles''in karısı oldu.

Megera: Üç hiddet tanrısından biriydi.Nazar değdiren olarak bilinirdi.

Melampus: Efsanevi yunan doktoru ve sihirbazı. Amythaon ile İdomene''nin oğlu.

Melanios: Atalante''yi koşuda yenen kahraman. 

Melanippe: Eolos''un kızı Poseidon''dan iki oğlu olmuştu.

Meleagros: Kalydon kralının kızı.

Meliades: Uranos''un yeryüzüne damlayan kanından yaratılan periler.

Melissa: Girit kralının kızı olan bir peri. Amalthee ile beraber Zeus''u büyüttü.

Melos: Delos''lu bir delikanlı, adonis''in arkadaşıydı. Pelia adlı bir kızdan Melos adında bir oğlu oldu. Adonis''in ölümünden sonra kendini astı.

Melpomene: İlham perielrinden biri, trajedi ilham ederdi.

Memnon: Eos ile Tithonos''un oğlu. Akhilleus tarafında öldürüldü.

Memnonidler: Eos''un oğlu Memnon''un cesedinin yandığı ateşten doğan efsanevi kuşların adı.

Menelaos: Agememnon''un kardeşi, Helena''nın kocası. Paris karısı Helena''yı kaçırınca Troia''ya saldırdı.

Menippe: Orion''un kızı, ve Metiokha''nın kardeşi. Zeka tanrıçası bu iki kardeşe örgü öğretmişti, Aphrodite ise güzellik bahşetmişti. Ülkeleri veba salgınına yakalandığında tanrılar iki kardeşin kurban edilmesi halinde salgının kalkacağını söylediklerinde, iki kardeş kurban edilmeyi kabul ettiler ve kendilerini öldürdüler.

Menestheus: Peleus''un oğlu. Atina kralı Theseus ihtiyarlayınca krallığı onun elinden aldı.

Menoetios: Bir titan oğlu.

Menoikeus: Kreon''un oğlu. Thebai''yi kurtarmak için kendini şehrin surlarından aşağı attı.

Menthe: (Nane)   Cehennemler tanrısı Hades''in gönül verdiği peri kızı. Hades''in karısı Persephone, onu kıkandı ve ayaklarının altında ezdi. Hades sevgilisine acıdı ve onu güzel kokulu naneye çevirdi.

Mentor: Alkimos''un oğlu. Odyseus''un sadık dostu. Athena Mentor''un kılığına girip Telemakhos''a öğüt verirdi. 

Mercurius: Hermes''in latince adı. 

Merope: Pleiadlardan biri. Atlas''ın kızı. Fani bir insanla evlendiği için kardeşleri ile birlikte yıldız olduğunda onlara oranla daha sönük ışık verdi. Mesopothamia Aphrodite''in rahibelerinden birinin kızı. 

Mestra: Erysikhthon''un kızı. Poseidon''un sevgilisi, Mestra''nın babası Demeter''in hışmına uğrayıp sefalete düşmüştü. Poseidon''un kendisine bahşettiği istediği her şekle dönüşebilme yeteneği ile babasını kurtardı. 

Metanira: Eleusis kralı Keleos''un karısı. 

Metis: Hikmet ve tedbirlik tanrıçası. Okeanos ile Tethys''in kızı. 

Midas: Phrigia''nın efsanevi kralı, Apollon Kulaklarını eşek kulağına çevirmişti. 

Miletos: Anadoluda Miletus şehrini kuran kahraman: Apollon ile Deione''nin oğlu. Menderes nehrinin kızı Kyane ile evlendi. Kaunos ve Byblis adında iki çocuğu oldu. 

Milon: Diolimos''un oğlu. Yunanistan''ın en meşhur atletlerinden biridir. 

Minerva: Zeka tanrıçasına romalıların verdiği ad. 

Minos: Girit Kralı 

Minotauros: İnsan vücutlu boğa başlı azılı bir canavar. 

Minyad''lar: Minyas''ın üç kızına verilen ad. Dionysos namına yapılan bayrama katılmadıkları için cezalandırıldılar. Baykuşa dönüştürüldüler. 

Mnemosyne: Uranos ile Gaia''nın kızı. Hatıra tanrıçası. Zeus''tan dokuz tane çocuğu oldu, bunlar ilham perileridir. 

Mnestra: Danaid''lerden biri kocası Egius''u öldürdü 

Moira''lar: Kader tanrıçaları. Zeus ile Themis''in üç kızı. 

Molpis: Elis''li bir delikanlı memleketini kasıp kavuran kıtlıktan kurtulmak için kendini kurban etti. 

Momos: Alay, istihza ve hiciv tanrıçası. Gecenin kızı. 

Mopsos: Manto''nun oğlu 

Moria: Anadolu da Lydia''lı bir kadın. Yılan sokması sonucu ölen kardeşini tekrar diriltti. 

Mormo: İnsanları korkutmak için Hekate''nin emrinde olan korkunç bir kadın hayaleti. 

Morpheus: Rüyaların tanrısı. Hypnos ile gecenin oğlu. 

Moyskhlos: Hephaistos''un çırakları olan Kabir''lerin yeri. 

Musagetes: Apollon''un lakabı, Musalarınrehberi anlamındadır. 

Musaios: Ay''ın oğlu, Orpheus''un hocası ve en yakın dostu idi. İlham perileri tarafından büyütüldü. 

Musa''lar: İlham perileri. 

Mykenai: Samos adasında Perseus''un kurduğu bir şehir. 

Myrmidonlar: Algine adasında yaşayan insanlar. Eskiden karınca oldukları için çok çalışırlardı. 

Myrrha: Kıbrıs adası kralı Kinyras''ın kızı. Kral kendi öz kızı ile evlendi ve bu evlilikten Adonis doğdu. 

Myrtilos: Arabacı Oinomaos yıldızı. Arabacıydı yıldız oldu. 

Mysteria: Açık olmayan gizli yapılan tapınmaya bu ad verilir.

N

Naiadlar: Çeşmelerin kaynakların. Derelerin perilerine verilen ad. Naiadlarda insanlar gibi ölümlüydüler.

Napae: Çayırların perilerine verilen ad.

Nannakos: Phrigia''nın en eski kralı. Tufanın olacağını önceden sezip halkıyla birlikte tanrılara dua edip kurban kesmişlerdi.Ve tanrılar onları tufandan korumuştu.

Narkissos: Aşktan kaçınan bir delikanlı. Nergis çiçeğine çevirildi.

Nauplios: Euboea adası kralı. Poseidon ile Amymone''nin oğlu. Klymene ile evlenip bir çok çocuk babası oldu.

Nausikaa: Skeria adasının kralı Alkinoos''un kızı. Odyseus''a yardım etmişti. Tanrıçalar kadar güzel olan bu prenses, asaletin sembolüdür.

Neanthos: Lesbos tiranı Pittakus''un oğlu

Nektar: İçenlerin ölümsüz olduğu tanrılara mahsus içki.

Neleus: Poseidon ile Tyro''nun oğlu. Karısı Khloris''ten Nestor adında bir oğlu oldu. Herakles ile girdiği bir çarpışma sırasında öldü.

Nemesis: Gece''nin kızı intikam tanrıçası. Aynı zamanda o, dünyada adaleti koruyan, haklıyı haksızdan ayırd eden bir ahlak tanrıçası idi.

Neoptolemos: Akhilleus ile Lykomedes''in kızı Deidamie''nin oğlu. Çok cesur bir savaşçıydı ancak aynı zamanda acımasızdıda. Affetmek duygusundan yoksundu.

Nephele: Athomas''ın karısı, Helle ile Phriksos''un annesiydi.

Neptun: Romalıların Poseidon''a verdikleri ad.

Nereus: Denizler ihtiyarı olan Nereus Pontos(Deniz)   ve Gaia(Toprak)  nın oğlu. Okeanos''un kızı Doris ile evlendi ve bu evlilikten Nereid''ler oldu.

Nerio: Romalılarda harp tanrısının karısı olup, kahramanlığı temsil eder.

Nerites: Nereus ile Doris''in oğlu olup güzelliği ile Aphrodite''I kendine aşık etmişti. Aphrodite tanrılar dağı Olympos''a çıkarken onuda yanında götürmek istedi ancak Nerites anne ve babasının memleketi denizi tanılar dağına tercih etti. Buna çok sinirlenen Aphrodite onu kayaların üzerine yapışıp kalan hareket edemeyen kabuklu bir deniz hayvanına çevirdi.

Nereidler: Nereus ile Doris''in kızları olan deniz perileri. Birbirinden güzel olan bu kardeşler dalgaların sembolüdürler.

Nessos: Kentaur''lardan biri. Herakles''in karısı kaçırmaya çalıştı fakat Evenos''un kabarmış sularını geçince Herakles onu öldürdü.

Nestor: Neleos ile Khloris''in en genç oğlu. Herakles onun onbir kardeşini öldürdüğü zaman sadece o kurtuldu ve babasının yerine Pylos kralı oldu.

Nikaea: Sangarios (Sakarya)   nehrinin kızı. Aşktan nefret ediyor sadece avlanmayı seviyordu. Dionysos onu görünce vurulmuştu ancak Nikaea ona yüz vermedi. Bunun üzerine Dionysos da onu şarap içirerek baştan çıkardı. Telete adında bir kızları oldu başlangıçta bu zoraki evlilikten hiç hoşlanmayan Nikaea daha sonradan şarap tanrısıyla yakınlaştı ve Satyros adında bir de oğulları oldu. 

Nike: (Victoria)   Zafer tanrıçası 

Niobe: Lydia kralı Tantalos''un kızı, Apollon ve Artemis''in annelerini hor gördüğü için oniki çocuğu öldürüldü ve oda kayaya çevirildi. 

Nireus: Helene''yi almak isteyen delikanlının biri çok güzeldi ancak basit bir ailedendi. 

Nisos: Athena kralı Pandion''un oğlu. Syklla adında bir kızı vardı. Syklla Minos''u sevdiği için babasına ihanet etti.Ancak babasına ihanet eden bir kıza güvenemiyeceği için Minos ona yüz vermedi. Bunun üzerine kız kendini denize attı. Onu bir balığa babasının da kartala çevirdiler. 

Nomos: Kanunların koruyucusu. 

Notos: En önemli dört rüzgardan biri. Eos ile Astraeos''un oğlu. Güney rüzgarı Lodos olarak bilinir.

Nyks: Khaos''un kızı gece. 

Nykteus: Poseidon ile Kelene''nin oğlu, Antiope''nin babası.

Nyktime: Lesbos kralı Epopeus''un kızı. Babasına gönül verdiği için tanrılar onu yarasaya çevirdiler.

Nyktis: Nykteus''un kızı. Thebai kralı Labdakos ile evlendi. Laios doğdu.

Nymphe''ler: Dağlarda, kırlarda, ormanlarda, çeşmelerin kaynakların başında, nehirlerde yaşadıkları sanılan peri kızları.

Nysa: Nysa dağına adını veren peri kızı. Dionysos''u bu dağın perileri büyütmüştür.

Nyssia: Phrygia''nın kralı Kandaulos''un karısı. Kral karısının güzelliğine hayran idi. Gözdelerinden Gyges''I gizlice karısını çıplak görmesi için yatak odasına aldı. Nyssia bunu fark edince ''Ya kocamı öldür benimle evlen yada sen ölümü göze al'' diye korkutunca Gyges kralı öldürüp Nyssia ile evlendi. 

O

Odysseus: Meşhur Yunan kahramanı. İthaka kralı. Laertes ile Antikleia''nın oğlu. Çok zeki bir adamdı, düşmanlarını zekası ve kurnazlığı ile yendi. Penelope ile evlendiği sıralarda Troia savaşı başlayınca savaşa gitmemek için çeşitli bahaneler ileri sürdü ancak savaşa gitmek zorunda kaldı. Tahta at fikride Odysseus''a aitti. Zeka tanrıçası tarafından çok sevilen kahraman Poseidon''un kinini kazandığından Troia dönüşü başına bir çok belalar gelmişti. 

Oegipan''lar: Dionysos''un peşinden giden sivri kulaklı varlıklar.

Oiagros: Thrakia kralı ve Orpheus''un babası. İlham perilerinden Kalliope ile evlendi ve Orpheus doğdu.

Oidipus: Thebai kralı Laios ile İokaste''nin oğlu. Bilmeden babasını öldürdü ve özannesi ile evlendi.

Oileus: Lokrisli Aias (Ajax)  ''ın babası

Oineus: Aitolia''da Kalydon kralı. Dionyssos''a hizmette kusur etmediği için şarap tanrısı üzüm suyuna bu kralın adını verdi.

Oinomaos: Ares ile Harpinna''nın oğlu, Pisa kralı. Steroria ile evlenmiş, Hippodameia adında güzel bir kızı olmuştu. 

Oinone: Kebren(Değirmendere)   ırmağının tanrısının kızı. Paris bukızı sevmişti ancak Aphrodite ona Helene''nin aşkını aşılayınca bu peri kızını terk etti. Buna rağmen Troia savaşı sonunda Paris ağır yaralandığında sevdiğinin yanına koştu ve onu iyileştirmeye çalıştı ama elinden bir şey gelmedi ve Paris öldü. Bunun üzerine Oinone kendini öldürdü.

Oinopion: Dionysos ile Ariane''in oğlu, sakız adası kralı idi.

Oinotrop''lar: Delos kralı Anios''un kızlarınaverilen ad. Dionysos bu kızlara neye dokunurlarsa şarap yapma gücünü vermişti. Agememnon bu meziyetleri için kızları kaçırmaya kalkışınca kızları birer güvercine çevirdi.

Oinotros: Lykaon''un oğullarından birinin adı.

Oionos: Alkmene''nin yeğeni.

Okeanid''ler: Okeanos''un kızları. Kaynak dere ve akarsu tanrıçaları.

Okeanos: Uranos ile Gaia''nın oğlu. Denizlerin ve suyun sembolü.

Okhimos: Helios ile Rodus perilerinden birinin oğlu.

Okyrrhoe: Samos perilerinden.Khesias ile Imbrasos ırmağının kızı. Apollon bu kızı sevdiği gemici Pompilos''tan kaçırıp gemicinin teknesinide kayalarda parçaladı. 

Olympos: Thessalai''da ki tanrılar dağı.

Omphale: Lydia''nın efsanevi kraliçesi. Herakles ile olan aşkı ile ün salmıştı. Yunanistan''ın rakipsiz kahramanı bu eşsiz güzel karşısında her şeyi unuttu. Kraliçe onu bir köle gibi kullanıyor aşkını sömürüyordu. 

Oneiros: Rüya Agamemnon''u aldatmak için Zeus tarafından gönderilen uyku cini.

Onkos: Apollon''un oğlu, Arkadia''da kurduğu bir şehre adını verdi.

Opheltes: Nemea kralı Lykurgos ile Eurydike''nin oğlu. Bir yılan sokması sonucu öldürüldü.

Ophieus: Messaniaların kör tanrısına verdikleri ad.

Ophion: Titanlardan biri. Kronos ve Rhea dan önce karısı Eurynome ile birlikte göklerde krallık ediyordu ancak Kronos onu yenip Tartaros''a attı.

Ophioneus: Messania''lı meşhur kahin.

Oread''lar: Dağ perilerine verilen ad.

Oreithyia: Boreas''ın karısı. Kalais ve Zetes adlı iki çocuk doğurdu.

Orestes: Agamemnon ile Klytemenestra''nın oğlu. Babasını öldüren annesi ile sevgilisinden intikam aldı.

Orion: Bolotia''nın ünlü kahramanı. Dev gibi bir vücudu güzel bir yüzü vardı. Poseidon ile Euriale''nin oğlu idi.

Orkos: Hades''in latince adı

Orpheus: Thrakia kralı Oiagros''un oğlu ve Yunanlıların efsanevi şairi.

Orthia: Artemis''in lakabı

Orthopolis: Demeter''in büyüttüğü bir kral çocuğu.

Orthron: Bir çok başı ve yılan gibi bir vücudu olan Geryon''un köpeği Herakles tarafından öldürüldü.

Otos: Aloadlardan biri, Ephialtes''in kardeşi.

Otreus: Dymas''ın oğlu Phyrigia kralı.

Ortygia: Leto''nun kızkardeşi. Kendisine aşık olan Zeus''tan kaçtığı için baş tanrı onu bıldırcına çevirdi.

Otrynteus: Anadoluda Tmolus (Bozdağı)   eteklerindeki bir kasabanın kralı. Nais adlı bir peri kızıyla evlendi. İpsition adında bir oğlu oldu.

P

Paian: Felaketi uzaklaştıran, selamet getiren, iyi eden tanrı.

Palaimon: İo''nun oğlu bir deniz tanrısı. Gemicilerin koruyucusuydu.

Palamedes: Nauplios ile Klymene''nin oğlu. Odysseus tarafından öldürüldü.

Pales: Romalıların koyun sürülerini koruyucusu olduğuna inandıkları tanrı.

Pallas: Zeka tanrıçasının bir diğer adı.

Panakeia: Asklepios gibi hekimlikle uğraşan sağlık tanrıçası.

Pan: Sürülerin ve çobanların tanrısı.

Panagea: Artemis''in bir diğer adı.

Panakea: Asklepios ile Lampetia''nın kızı. Hekimliğin tanrıçalarından sayılırdı, her türlü hastalığa çare bulurdu.

Pandaman: Ateş tanrısı Hephaistos''un bir diğer adı. Her şeyi yenen anlamına gelir.

Pandareos: Miletus''lu Merops''un oğlu. Giritte Zeus tapınağından altın köpek heykelini çaldığı için Zeus tarafından kayaya çevirildi.

Pandaros: Yunanlılara karşı savaşan Troia''lıların yardımına koşan ünlü kahraman Lykaon''un oğlu.

Pandion: Atina şehrinin ünlü krallarından.

Pandora: Yaratılan ilk kadın. 

Pandrosos: Atina kralı Kekrops''un kızlarından biri. Athena küçük Erekhteus''u içine sakladığı kutuyu bu kızlara emanet etmişti.

Panikos: Kır tanrısı keçi ayaklı Pan''ın insanların içine saldığı korku

Pankratis: Tloeus ile İphimedie''nin kızı, dolayısıyla Aloadların başhemşiresi.

Panapa: Theseus''un kızı Herakles ile evlenmişti. Bir kızı olmuştu ona annesinin adını koydu.

Panopa: Nereid''lerden biri, adaletseverliği ile tanınırdı.

Panopeus: Phokos ile Astropea''nın oğlu. Argonautlar seferine katılanlardan.

Panthaos: Priamos''un arkadaşı Troia''lı bir ihtiyar.

Paphia: Aphrodite''in isimlerinden biri.

Paphlagon: Kirke''nin oğlu. Anadoluda Papira (Karaköy)   şehrinin kurucusu.

Paraios: Atinalı bir kahraman, savaş gemisini icat etti.

Paris: En ünlü kahramanlardan biri.Troia kralı Priamos ile Hekabe''nin oğlu. Çok kuvvetli olduğundan onu Aleksandros diye çağırırlardı. Yunanlı Helena''ya olan aşkı onun ve Troia''nın sonu oldu.

Parkae: Romalıların talih tanrıçalarına verdikleri ad.

Parnassos: apollon''a tahsis edilen Parnassos dağına adını veren kahraman.Poseidon ile Kleodora adlı bir peri kıznın oğlu idi.

Parrahasios: Zeus''un oğlu. Arkadia da bir şehrin kurucusu olduğu söylenir.

Parsondes: Yedi yıl Babil valisinin sarayında bir kadın gibi yaşayan tuhaf bir insan.

Parthenius: Bugünkü Bartın çayının eski adı.

Parthenon: Atina Akropolis te bulunan ve Zeka tanrıçası Athena''ya ait olan meşhur tapınak.

Parthenopaieos: Thebai şehrine karşı yürüyen yedi şeften biri.

Parthenopea: Menderes nehrinin kızı Samia ile ankeus''un kızı. Apollon bu kıza gönül vermişti. Birlikteliklerinden Nikomedos doğdu.

Parthenope: Sirenlerden biri. Odyseus''u büyülü sesiyle etkisi altına alamadığından kendini denize attı. Dalgalar bu deniz kızının naaşını İtalya kıyılarına attılar. Naaşının gömüldüğü yerde Napoli şehri kuruldu.

Parthenos: Staphylos ile Khrosthemis''in kızlarından biri.

Pasiphae: Minos''un karısı. Helios''un kızı. Bir boğaya aşık olmuştu. Sevdiği boğadan gebe kalarak Minotauros''u doğurdu.

Pataros: Apollon ile Ksanthos''un kızı olan Lykia''nın oğlu. Patara şehrine adını vermiştir. 

Patroklos: Menoltios''un oğlu. Ünlü yunan kahramanlarından biridir.

Pegasos: Efsanevi kanatlı at. Perseus Okean''ın kaynağında Medusa''nın kafasını kestiği zaman onun kanından doğdu.

Peitho: İkne etme, kandırma tanrıçası. Ate''nin kızı, Aphrodite''in arkadaşıdır.

Peirithoos: Zeus ile Dia''nın oğlu, Lapithler kralı.

Pelasglar: Yunanistanın eski ahalisine verilen ad.

Pelasgos: Yerin oğlu. Pelagların atası oldu.

Peleus: Meşhur yunan kahramanı Akhilleus''un babası. Phthie kralı.

Pelias: İolkos kralı. Poseidon ile Tyro''nun oğlu.

Pelopea: Theste''nin kızı. Kim olduğunu bilmeden babası ile birlikte oldu. Bunu anlayınca kendini öldürdü.

Pelops: Lydia kralı Tantalos''un oğlu. Ganymedes''in babası.

Penat''lar: Romalıların ev tanrılarına verdikleri ad.

Peneios: Thesselia da akan bir nehrin tanrısı. Okeanos''un oğlu.

Penelope: Odysseus''un karısı. Telemakhos''un annesi. Kocası Troia harbine gittikten sonra uzun yıllar tek başına yaşadı ancak kocasına hep sadık kaldı.

Penia: Fakirlik tanrıçası.

Penthesileia: Amazonların kraliçesi.Ares ile Otreranın kızı. Troia savaşı sırasında Akhilleus tarafından öldürüldü.

Pentheus: Thebai kralı. Ekhion ile Kadmos''un kızı Agave''nin oğlu.

Penthos: Keder ve ızdırap tanrısı. 

Peon: Yunan tanrılarını tedavi eden ünlü mısırlı hekim.

Peparethos: Ariane''in Dionysos''tan olan dört oğlundan biri.

Perdiks: Dedalos''un kızkardeşi.

Pergamos: Anadoluda Bergama şehrinin kahrmanı. Neoptolemos ile Andromakne''nin oğlu. 

Periboea: Mağar kralı alkathous''un kızı. Eakos''un oğlu Telemon ile evlendi, Ajaks''ı doğurdu.

Perieres: Eolos''un oğlu.Perseus''un kızı.Gorophone ile evlendi.

Perigoune: Sinis''in kızı.Theseus Sinis''I öldürüp kızı ile birlikte oldu. Bu birliktelikte Melanippos doğdu. Daha sonra Periogoune Deloneus ile evlendi ve İksus''u doğurdu.

Periklymenos: Argonautlardan biri. Neleus''un oğlu. Poseidon bu gence istediği şekle girebilme vasfını vermişti.

Periktyon: Aristo''nun karısı ve meşhur filozof Eflatun''un annesi

Perimele: Admetos ile Alkaste''nin kızı.

Perimelis: Sürülere göcülük eden perilere verilen ad.

Periphas: Atina şehrinin efsanevi kralı. Halkı tarafından çok sevilirdi. Öyleki Zeus bu sevgiyi kızkandı ve onu öldürmeye kalktı ama Apollon babasına engel oldu bunun üzerine Zeus bu kralı bir kartal''a dönüştürdü.

Periphetes: Hephaistos ile Antiklea''nın oğlu olan korkunç dev. Thesseus tarafından öldürüldü.

Peristera: Aphrodite''in yanında dolaşan perilerden biri. Birgün Aphrodite ile Eros çiçek toplama yarışı yaparken Peristera Aphrodite''e yardım ettiği için Eros onu güvercine çevirdi.

Peritanus: Arkadia''lı bir genç Paris Helene''I kaçırdıktan sonra Helen bu gence gönül vermişti. Paris bunu fark edince Arkadia kıyılarını talan etti.

Pero: Neleus ile Khloris''in kızı.Güzelliği ve fazileti ile tanınırdı. Bias ile evlendi.

Persa: Thetys ile Okeanos''un kızı. Güneş ile evlendi.Eetes, Kirke ve Pusiphae''yi doğurdu.

Perseid''ler: Perseus soyundan gelenler.

Perseis: Helios''un karısı

Persophene: Demeter''in kızı. Hades''in karısı.

Perseus: Argos kralı Akrisios''un kızı Danae''nin Zeus''tan olan oğlu.

Persepolis: Odysseus ile Nausikaa''nın oğlu.

Perses: Titan Krios ile Eurybie''nin oğlu. 

Phaeton: Helios''un oğlu.

Phaetusa: Lampetie''nin kızkardeşi. Gençlik tanrıçası Neera ile Güneş''in kızı.

Phaiak''lar: Skheria adasında oturan halk.

Phaidra: Girit kralı Minos ile Pasiphane''nin kızı. Theseus ile evliydi. Üvey oğlu Hippolytos''a aşık oldu. Delikanlı onu red edince Hippolytos''a iftira etti ve ölümüne neden oldu.

Phalaekos: Ambrakia tiranı. Artemis bir gün onu ava götürüp bir aslan yavrusu gösterdi.Phalaekos yavruyu yakalamaya çaılışırken dişi aslan ortaya çıkıp onu parçaladı. 

Phalanthos: Lakonia''ların ünlü kahramanı

Phalanaks: Zeka tanrıçası tarafından örümceğe çevirilen Arakne''nin kardeşi. Buda silah yapımında tanrılardan üstün olduğunu iddia ettiği için yılana dönüştürüldü.

Phalaris: Agrigente tiranı. Zeus''a tapınak yapacağım diye başına topladığı çok kalabalık bir işçi ordusu ile şehrin tiranı oldu. Zulmü ve cımasızlığı ile meşhurdur.

Phaleros: Attika bölgesindeki Phaleros şehrinin kahramanı.Arganautlardan biri.

Phalkes: Temenos''un oğlu. Heraklidlerden biri.

Phaloe: Lykris ırmağının kızı olan bir peri. Buna kanatlı bir ifrit bela olmuştu. Elaatos adında bir delikanlı ifriti öldürdü. Phaloe ile Elaatos''un evlenecekleri gün delikanlı öldü. Peri kzı okadar çok göz yaşı döktüki tanrılar ona acıyp onu bir çeşmeye dönüştürdüler.

Phantosos: Uyku''nun oğlu. Kayaya, toprağa ırmağa ve cansız varlıklara dönüşebilen bir tanrı. Çevresi bir sürü yılanlarla çevrilmiştir.

Phaon: Midilli adasında basit bir kayıkçı iken, bir gün ihtiyar bir kadın kılığına girmiş olan Aphrodite''I kim olduğunu bilmeden adadan karşıya Anadoluya geçirmiş ve yaşlı kadının tüm ısrarlarına rağmen ondan para almamış. Bunun üzerine tanrıça onaalçıdan yapılmış içinde güzel kokulu bir yağ bulunan bir vazo hediye etmiş. Balıkçı güneşten çatlayan cildine bu yağı sürdüğünde çok yakışıklı bir gence dönüşmüş.

Pharmakias: İstanbul boğazında büyükdere''nin ağazında eski bir liman.Rivayete göre Media''yı getiren gemi bu limana sığınmak zorunda kalmış vesihirbaz kadın ilaç dolu sandığı ile buraya ayak basmış.

Phoebe: Uranos ile Gaia''nın kızı. Koios ile evlendi ve Latone ile Asterie''yi doğurdu.

Phebus: Apollon ile Pasiphae''nin kızı, 

Phedra: Girit kralı Minos ilePasiphe''nin kızı, Theseus''un karısı. Üvey oğluna aşık oldu fakat ondan karşılık alamadı bunun üzerine ona iftira etti ve ölümüne neden oldu.

Phegeus: Arkadia da Phegeus şehrinin kurucusu ve kralı.

Phoiniks: Habeş diyarında yaşadığı sanılan efsanevi bir kuş.

Pheniks: Argos kralı Amyntor ile Kleobule''nin oğlu. Babasını üzerek annesinin gözüne girmek için babasının çok sevdiği ve hatta bu yüzden annesini ihmal ettiği genç kız ile sevişti.Bunun üzerine babası onun gözlerini oyup saraydan kovdu.

Phenops: Ksanthus ile Thoon''un babası.

Pheomis: Gaia ile Tartaros''un oğlu.

Pheraea: Zeus ile Eolos''un kızı. Hekate''nin annesi.

Phidippos: Thessalos''un oğlu Herakles''in torunu.

Phillamon: Aslen trakyalı olan efsanevi şair ve kahin.

Philemon: Bucis''in kocası. Kulübelerinde zeus''u misafir ettiler ve bundan dolayı mükafatlandırıldılar.

Philonome: Myktimus''un kızı ve Artemis''in arkadaşı. Ares''ten iki çocuğu oldu bu iki kardeş daha sonradan sırayla Arkadia''ya kral oldular.

Philotis: Romalı bir köle kadın. Zekası ve kurnazlığı ile Roma''yı Gauloi''ların istilasından kurtardı.

Philyra: Okeanos''un kızı. Bir ara Kronos''un metresi oldu.Ondan Kentaur Khiron''u doğurdu. 

Phineus: Salymydessos''un efsanevi kralı. Tanrı Apollon ona falcılık öğretmişti.

Phlegethon: Yunanlıların cehennemlerinde akan ırmaklardan biri.

Phlegyas: Lapith''lerin efsanevi kralı. Ares il Khrysa''nın oğlu. İksion ile Koronis''in babası.

Phlias: Dionysos ile Minyas''ın kızı olan Aracthyrea''nın oğlu.

Phobos: İnsana gelen korkunun simgesidir.Phobos bir kadın olup savaşlarda Ares''in yanında bulunurdu.

Phoibe: Leukippos''un iki kızından biri.

Phoiniks: (Phoeniks)   Agenor''un oğlu. Europa''nın kardeşi.Zeus tarafından kaçırılan kardeşinin peşinden yollara düştü.

Phokis: Orestes''in amcası.

Pholos: İksion ile Silene''nin oğlu olan bir Kentaur.Herakles''e kafa tutmadığı için onun tarafından saygı gördü.

Phorbas: Lapithes ile Orsinome''nin oğlu olan bir halk kahramanı.

Phorkys: Pontos ile Gaia''nın oğlu. Deniz tanrılarından biriydi. Kız kardeşi Keto ile evlenmişti.

Phroneus: İnakhos''un oğlu. Argos ilinde ilk insanın o olduğu söyleniyor.

Phosphoros: Sabah yıldızına verilen ad.

Phrikos: Helle''nin kardeşi. Athamas''ın oğlu.

Phrigia: Eski Anadoluda bir bölgenin adı.

Phryne: Efsanevi bir güzelliğe sahip olan bir Yunan fahişesi.Aphrodite heykellerine ilham kaynağı olmuştur.

Phrygios: Miletus krallarından biri.

Phthonos: Haset tanrıçalarından biri.

Phylios: Etolia''lı bir kahraman. Kyknos adında bir delikanlıya aşık olmuştu. Vefasız sevgilisi için her şeyi yapmasına rağmen ona yaranamadı.

Phyllis: Thrakia kralının kızı. Thesseus''un oğlu Demophon''a aşık olmuştu. Evlenmeye karar verdikleri sırad Demophon geri döneceğine söz vererek şehirden ayrıldı ancak uzun bir süre dönmeyince umutsuzluğa kapılan Phyllis kendini öldürdü.

Piassos: Thesselia krallarından biri Larissa''nın babası.Kızına aşık olmuş ve onunla zorla birlikte olmuştu. Larissa onu bir şarap fıçısında boğarak intikamını aldı.

Pierid''ler: İlham perilerine verilen ad.

Pieros: Pieridlerin babası, Makedon''un oğlu.

Pietas: Acıma duygusunun sembolü.

Pikoloos: Bir dev. Tanrıların devlerle yaptıkları savaşta Kirke adasına kaçmıştı ancak Kirke''nin babası onu öldürdü.

Pikus: Latium kralı Faunus''un babası olan kahin

Pilumunus: Yeni doğan çocukları koruyan Roma tanrıçası.

Pindos: Makadeon''un oğlu. Kardeşleri tarafından öldürüldü.

Pirene: Asopos''un kızı. Poseidon''un sevgilisiydi.

Pirithous: Thessalia kahramanlarından. Zeus ile Dia''nın oğluHippodamia''dan Polypoetes adında bir oğlu oldu.

Pisa: Elis bölgesinin bir şehri.

Pisidike: Monenia şehrinin kralının kızı.

Pitane: Nehir tanrısı Euratos''un kızı. Poseidon ile birlikteliklerinden Evadne adında bir çocukları oldu.

Pittheus: Pelops ile Hippodameia''nın oğlu. Çok iyi bir kahin idi.

Pitho: Kandırma ve inandırma tanrıçası.

Pitys: Çam ağacının sembolü olan bir peri kızı.

Pleiadlar: Atlas ile Pleione''nin yedi kızına verieln ad. Bu kızlar tanrılar tarafından yıldızlara dönüştürüldüler.

Pleione: Pleiadların anneleri kızları ile birlikte onuda yıldız dönüştürdüler.

Pleisthenes: Atreus''un oğlu. Onu amcası Tyestes yetiştirdi ve daha sonra öz babasını öldürtmeye çalıştı.

Ploutos: Zenginlik servet tanrısı. Demeter ile İason''un oğlu.

Pluton: Cehennemler tanrısı Hades''in latince adı.

Podaleirios: Aslepios''un oğlu kahrmanlık devrinin meşhur hekimi.

Podarkes: Priamos''un diğer adı.

Poibos: Apollon''un lakabı

Poine: (Poene)   İntikam ve ceza tanrıçası. Hiddet''in anası olduğu söylenir.

Polhymnie: Dans ilham perisi.

Polias: Athena''nın lakabı

Polites: Priamos ile Hekabe''nin oğlu.Çok hızlı koşardı.

Polluks: Leda''nın oğlu. Kastor''un kardeşi, Diosku''lardan biri.

Poltys: Poseidon''un oğullarından biri.

Polybos: Oidipus''un üvey babası, Khorinthos kralı.

Polbotes: Tanrılarla savaşan devlerden biri. Poseidon tarafından öldürüldü.

Polydamos: Troia kahramanlarından. Panthoos''un oğlu ve Hector''un arkadaşı.

Polydektes: Magnes''in oğlu Seriphos adasının kralı.

Poldeukes: Kastor''un ikiz kardeşi. İki kardeşe Dioskur''lar adı verilir.

Poldoros: Kadmos ile Harmonia''nın oğlu. Nykteus''un kızı ile evlendi, Labdakos adında bir oğlu oldu.

Polydos: Korintoslu meşhur bir kahin.

Polhymnia: Musalardan biri. Şairlere heyecan ilham ederdi.

Polkaste: İkarios''un karısı, Penelope''nin annesi

Polykrite: Naksos adasınınkahramanı olan güzel bir kadın.

Polymede: Auotolykos''un kızı. Aeson''un karısı.Jason''un annesi. Kocası ölüme mahkum edilince kandini astı.

Polyneikes: Eteokles''in kardeşiOidipus ile İokastenin oğlu.

Polyphemos: Poseidon''un oğlu olan korkunç dev.

Polksena: Priamos ile Hekaube''nin kızı.Yunan kahramanlarından Akhileus bu kıza gönül vermişti. Fakat birlikte olamadan her ikiside öldüler.

Polykso: Troia savaşında öldürülen meşhur kahraman Tlepolemus''un karısı.

Polypontea: Hipponoos ile Thrassa''nın kızı. Artemis''in av arkadaşıydı.Aphrodite aşka boyun eğmeyen bu kızı bir erkek ayıya aşık etti. Polypontea''nın bu ayıdan iki oğlu oldu. Orios ve Agrios.

Pomona: Romalıların meyve tanrıçası.

Pontos: Poseidon''un oğlu, karadenize adını vermişti.

Poros: Bereket tanrısı. Metis''in oğlu.Penia ile evlendi ve bundan Amour doğdu.Böylece aşkın babası bolluk anası yoksulluk oldu.

Poseidon: Yunanlıların deniz tanrısına verdikleri ad. Romalılar ona Neptune der.

Pothos: Eros''un yanından hiç ayrılamayn arkadaşlarından biriAşk arzusunun sembolü idi. Aphrodite''in oğlu.

Praksidike: Adalet tanrıçası sayılıyor ve hiddete kapılanlara sakin olmalarını telkin ediyordu. Babası muhafız tanrısı Soter idi. İki kızı vardı,Homonoe(Birlik)   ve Arete(Fazilet)

Priamos: Troia şehrinin son kralı. Paris ile Hector elli oğlu arasından en tanınmışlarıdır.

Priapos: Bugünkü Lapseki şehrinin tanrısı. Dionysos ile Aphrodite''in oğlu.

Proitos: Tiryns kralı. Bellerophon Proitos''un sarayına sığınmıştı.

Promakhos: Athena''nın lakabı.

Prokne: Atina kralı Pandion''un kızı.

Prokrustes: Poseidon''un oğlu olduğu söylenen bir haydut.

Proetid''ler: Argos kralı Proetos ileSthenebea''nın kızlarına verilen ad. Bu üç kız kardeş kendilerini Hera''dan daha güzel gördükleri için akılları başlarından alındı. 

Proetos: Argos kralı. Abas''ın oğlu, Akrisios''un ikiz kardeşi.

Promakhos: Zeka tanrıçasının lakabıdır.

Prometheus: Bir titan oğlu, ilk insanı yaratmıştır.

Propoetid''ler: Kıbrıslı Amathonte''nin kızları.Aphrodite''in kudretini inkar ettikleri için Aphrodite tarafından cezalandırıldılar. Tanrıça onları iflah olmaz fahişelere dönüştürdü. 

Proteus: Deniz tanrısı Poseidon ile Phenike''nin oğlu.

Protesailaos: Thessalialı bir yiğit. Troia savaşında karaya çıkan ilk yunanlıydı, hemen öldürüldü.

Prytaneion: Hestia''nın kutsal ateşinin yakıldığı yer.

Psykhagogos: Hermes''in lakabı. Ölülerin ruhlarını götürücü anlamındadır.

Psykhe: Ruh.Eros''un karısı.

Pygas: Pygmaiosların kraliçesi idi. Kendini tanrıçalara eş gördüğünden Artemis ile Hera onu turna kuşuna çevirdiler.

Pygmaios: Yunan mitolojisinin efsanevi cüceleri Lillipular. Boyları yarım metreden kısa oldukça cesur insanlardı.

Pygmalion: Kıbrıslı heykeltraş.Yaptığı heykele aşık olmuştu.

Pylades: Orestes''in en yakın dostu. Arkadaşının hayatını kendi hayatından üstün tutmuştur.

Pylios: Hephaisrtos''un oğlu

Pylos: Nestor''un yurdu Messenia da bir liman

Pyramos: Thisbe''nin sevgilisi. Bunların birbirlerine duydukları sevgi çok meşhurdu.

Pyrene: İspanya kralının kızı.Herakles bu güzele gönül vermişti.Birlikteliklerinden bir yılan yavrusu doğdu.

Pyreneos: Phokide kralı ilham perilerine göz koymuştu ancak başarılı olamadı.

Pyrrha: Epimetheus ile Pandora''nın kızı, Deukalion''un karısı.

Pyrrhos: Akhilleus''un oğlu Neoptolemos''un lakabı.

Pythia: Gaipten haberler veren Apollon rahibelerine verilen ad.

Python: Gaia''nın doğurduğu efsanevi yılan. Yüz tane başı, alev kusan yüz tane ağazı vardı. Apollon tarafından öldürüldü.

R

Raros: Karnaos''un oğlu. Triptolemos''un babası. Eleusis de Raros vadisine adını verdi.

Remus: Romulus''un ikiz kardeşi, Mars ile Rea Silvanın oğlu, Roma şehrinin kuruluşunda önemli bir yeri vardır.

Rhakios: Giritli bir kahraman, Lebes''in oğlu. Manto ile evlenmişti.

Rhadamantys: Cehennemlerde bulunan meşhur bir yargıç. Zeus ile Europa''nın oğlu ve Girit kralı Minos''un kardeşidir.

Rhadios: Neleus ile Khloris''in oğlu. Pylos şehrine saldırdığı için Herakles tarafından öldürüldü.

Rhea: Dağlık bölgelerin tanrıçası idi. Bir adıda İdalı ana idi. Zeus''u onun büyüttüğüne inanılırdı.

Rheme: Şöhret tanrıçası. Gaia tarafından yaratıldı, Zeus''a habercilik yaptı.

Rhesos: Thrakia''lı bir kahraman Troia savaşında Troia''lılara yardıma koştu.

Rhodope: Artemis''in hizmetindekilerden biriydi ve masumiyetini sonsuz dek saklaak istiyordu, ancak bu durumdan hoşlanmayan Aphrodite onu haşin ve ahlaksız bir avcı olan Euthynokos''a aşık etti. İki sevgili dağlarda gizlice buuşup birlikte oluyorlardı. Artemis bunu haber alınca onu sevgilisi ile gizlice buluştuğu mağarada Styks ırmağına dönüştürdü.

Rhodos: Güneş''in karısı. Rhodos adasına adını verdi.

Rhoetos: Tanrılarla savaşan devlerden biri. Dionysos tarafından öldürüldü.

Rhoksane: Kordyas''ın kızı. İran şahının oğlu Medos ona tecavüz etti, cezalandırılacağından korkan Medos kendininehre attı. O günden sonra nehrin adı Medos olarak değiştirildi.(Bu günkü Fırat)

Rhopalos: Herakles''in oğlu, Phaestos''un babası.

Rhytia: Korybant''ların annesi. Samothrake adasında yaşayan bu dokuz kardeşin Apollon''un çocukları oldukları söylenir.

Risus: Neşe ve kahkaha tanrısı. İnsanların kalplerinden kederleri kovan acıları yatıştıran bir tanrıydı.

Romos: Roma şehrini kuran ve adını veren kahraman.

Romulus: Mars ile Rea Silva''nın ikiz oğullarından biridir. Ropma şehrinin kuruluşunda önemli rol oynamıştır.

Ros: Hava ile Ay''ın oğlu, Çiy Şebnem tanrısı. Ros, seher tanrısı Eos''un kocasıydı. 

S

Sabazios: Phyrygia''lıların inandıkları bir tanrı. Zeus ile Persophene''in oğlu. Dianysos gibi insanlara bağ, bahçe yapmayı, öküz yetiştirmeyi öğretti.

Sagaris: Kral Midas''ın oğlu. Tanrıça Kybele''ye hürmette kusur ettiği için tanrıça onun aklını başından aldı ve Sagaris kendini Kserabates ırmağına attı. O günden sonra bu nehrin adı Sangarios oldu (Bugünkü Sakarya nehri)

Sagaritis: Bir meşenin ruhu olan peri kendini Kybele''ye adamış Attis isminde bir delikanlıyı yoldan çıkardığı için tanrıça Sagaritis''in bağlı bulunduğu meşe ağacını devirdi ve peri kızı can verdi.

Salambo: Babilde Aphrodite yerine tapınılan Astarte''nin bir adı.

Salamis: Asopos ile Menthone''nin kızı. Poseidon bu kıza gönül verdiğinden onu kaçırdı. Kykhreus adında bir oğulları oldu.

Salmakis: Bugünkü Bodrum yakınlarında bir gölcüğün perisi Aphodite''in oğlu Hemaphrodite''e aşık olmuştu

Salmoneos: Thessalia kahramanlarından Eolos''un oğlu. Peloponnes''te bir şehir kurarak kendi adını verdi.Başarılarından gurura kapılarak kendini baştanrıya eşit saydırmak için tunçtan bir körü üzerinde araba koşturarak kurbanlarının üzerine yanan meşaleler atarak öldürüyordu. Zeus buna çok sinirlendi ve onu yıldırımıyla vurup Tartoros''a attırdı.

Salus: Romalıların sağlık tanrıçası. Asklepios''un kız olduğuna inanılırdı.

Sanape: Bugünkü Sinop şehrine adını veren kahraman bir amozon. Herakles amazonlarla çatışmaya girdiğinde Sanape kaçarak onun elinden kurtulmuş ve bu bölgeye gelip Paphlagonia kralı ile evlenmişti. Çok fazla içki içtiğinden halk ona sarhoş anlamına gelen Sanape diyordu.

Sapho: Lesbos adasında Erebos şehrinde doğmuş efsanevi bir kadın şair.

Saron: Troizen krallarından biri, ava çok düşkündü. Bir gün bir geyik kovalarken hayvanın peşi sıra denize atladı ama çok fazla açıldığı için boğuldu. O günden sonra Attikia bölgesinin güneyindeki denize Saronikos denizi adı verildi. Ve halk av uğruna denizde boğularak ölen krallarını tanrılaştırdılar.

Sarppedon: Zeus ile Europa''nın oğlu. Lykia''da kraldı. Adaletseverliği ve insanlığı ile halkının sevgisini kazanmıştı. Troia savaşı sırasında Troia''lılara yardıma koştu. Patroklos''a saldırdı fakat onun tarafından öldürüldü.

Saturnus: Romalıların Kronoslara verdiği ad.

Satyr''ler: Silenler adı ilede tanınan Satyr''ler ikinci derecede gelen kır tanrılarıdır. 

Sivri uzun kulaklı, boynuzlu, yassı burunlu, keçi ayaklı, kısa kuyruklu ve gövdesi baştan aşağı kıllarla kaplı acaip bir varlık

Satyria: Girit kralı Minos''un kızı. Poseidonla beraber olup Taras adlı bir erkek çocuk dünyaya getirdi.

Sauros: Elis bölgesini haraca bağlayan bir haydut. Herakles tarafından öldürüldü.

Selen: Ay tanrıçası

Selinos: Poseidon''un oğlu

Semele: Kadmos ile Harmonia''nın kızı. Zeus ile birlikte oldu ve bu birliktelikten Dionysos dünyaya geldi.

Semiremis: Efsanevi Babil kraliçesi. Askolon şehrinin gölde yaşayan tanrıçası Derketo ile Kaystre''nin kızı. Önce Niniva kralının müşaviri Onnes ile evlendi, ondan iki çocuğu oldu. Daha sonra kral Ninos ona aşık olunca, kendi kızının karşılığında Semiramis''I kocasından istedi ancal Onnes razı olmadı. Bunun üzerine kral onun gözlerini oydurttu ve Semiramis''I kendisine eş olarak aldı. Ninyas adlı bir oğulları oldu. Kral ölünce yerine Semiramis Babil melikesi oldu. Asma bahçeleri dillere destandı.

Senius: İhtiyarlığa gözcü olan tanrı.

Sentius: Doğarken çocuklara duygu bağışlayan tanrı.

Sevekhoros: Babil''in efsanevi kralı. Kızından olacak torununun kendisini tahtından edeceğini tanrılardan duyunca kızını hapsetmişti. Ama kızının hamile kalmasını engelliyemedi ve Gilgamos dünyaya geldi. Muhafızlar korkarak çocuğu kuleden aşağı fırlattılar ama bir kartal yere düşmeden onu kurtardı ve bir bahçeye bıraktı. Bahçıvan onu büyüttü ve Gilgamos Babil''in meşhur hükümdarı, kanun yaıcısı Gılgamış oldu.

Sibylle: Apollon rahibelerine verilen ad, bunlar gaipten haberler verirlerdi.

Side: Anadolu''lu kahraman Tauros''un kızı ve Kimolos''un karısı. Side şehrine kendi adını vermiştir.

Siderites: Apollon''un Troia''lı Helenus''a verdiği sihirli taş. Efsaneye göre bu taş konuşabilirmiş.Helenus Troia''nın başına gelecek felaketi de bu taştan öğrenmiş.

Sikinos: Naiadlardan Oenoe ile Lemnos kralı Thoas''ın oğlu.

Silenos: Satyr''lar yaşlanınca Silenos adını alırlar. Dionysos''a arkadaşlık ederlerdi.

Silvanus: Romalıların orman bağ bahçe tanrısı.

Sinis: Theseus tarafından öldülen bir haydut.

Sphinks: Göğsü ve yüzü kadına, gövdesi arslana kanatları kartala benziyen acayip bir varlık

Staphyle: Şarap tanrısının gönül verdiği bir peri kızının adı.

Stellio: Kertenkeleye çevirilen küçük bir çocuğun adı.Demeter''in kana kana su içmesi ile alay ettiği için bu cezaya çarptırıldı.

Stentor: Sesi çok gür olan bir adam.

Sterope: Atlas ile Peione''nin kızı. Ares ile evlendi Oenomaos doğdu.

Stheneboia: Tiryns kralı. Protios''un kocası.

Sthenelos: Aktor''un oğlu Herakles''in silah arkadaşı.

Stheno: Grai''lerden biri.

Stilbe: Peneos nehrinin kızı. Apollon''un bu kızdan Kenthauros ve Lapithes adlarında iki oğlu oldu.

Strymon: Thrakia kralı, Ares''in oğlu. Oğlu Rhesos''un Troia da öldüğünü duyunca üzüntüden kendisini öldürdü.

Styks: (Styx)   Cehennem nehri. 

Stymphalos: Elatos ile Laodike''nin oğlu. 

Summanus: Romalıların gece çakan şimşek tanrısı.

Syka: Dionysos''un gönül verdiği bir peri kızının adı. Onu incir ağacına dönüştürdü.

Syleus: Thesselia kralı ve Poseidon''un oğlu. Zorba bir kraldı, Herakles tarafından öldürüldü.

Symplegad: Karadeniz boğazındaki oynak kayalıklar.

Syrinks: Arkadialı bir peri kızı. Pan bu periye gönül vermişti.

Syrna: Karia bölgesinin kralı olan Damaethos''un kızı. Damdan düşerek bütünkemiklerini kırdı, öleceği sırada Podalirios çıka geldi iki kolundan kan alarak kızı tedavi etti ve daha sonrada onunla evlendi.

T

Talos: Girit adasını beklemekle görevlendirilmiş tunç vücutlu dev. Bir yabancı gördüğünde hemen ateşin içine girer, kızıl kor haline gelir, sonra koşar yabancıyı kucaklar diri diri yakardı.

Talthybios: Agememnon''un habercilerinden biri.

Tanais: Okeanos ile Tethys''in oğlu, bugünkü Don nehrinin tanrısı

Tantalos: Batı anadoluda Lydia kralı. Zeus ile Plouto''nun oğlu. Sipylos(Manisa)   dağında hüküm sürüyordu. Atlas''ın kızı Dione ile evlenmişti. Paktolos ırmağının kızı Eurnassa da onun karısı idi. Pelops ve Niobe onun çocukları idi. Tantalos tanrıların hoşgörüsünü kötüye kullandı ve müthiş bir azaba çarptırıldı.

Tantalid''ler: Tantalos''un soyundan gelenler.

Taraksippos: Hipodrumlarada atları ürküten habis ruh.

Taras: Poseidon ile Satyra adlı bir perinin oğlu. İtalyada Tarente şehrinin kurucularından.

Tartaros: Yeraltında, cehennemlerin derinliklerinde bulunan korkunç yer. Zeus kendisine isyan edenleri oraya atardı.

Tauros: Pasiphae''nin aşık olduğu bir delikanlı. Minotauros bu birliktelik sonucu doğdu. Minos onu Girit''te yer altı mağarasına hapsetti. Theseus onu öldürdü.

Taygete: Atlas ile Pleione''nin kızı. Zeus ile birlikte olup Lakedaemon''u doğurdu. Çok utangaç bir yapıya sahipti.

Teiresias: Ünlü kahin, ve Manto''nun babası.

Tekmessa: Anadolu da Phrygia kralı Teuthras''ın kızı. Yunanlıların saldırısı sırasında büyük kahraman Aiaks''ın eline düştü. Bu evliliğin sonucunda Eurysakes adında bir oğlu oldu.

Telamon: Büyük Aiaks''ın babası ve Aigina kralı. Birçok savaşta Herakles ile birlikte oldu.

Telegonos: Odysseus''un sihirbaz Kirke''den olan oğlu

Telemakhos: Odysseus''un Penelope''den olan oğlu. Babası Troia savaşından geri dönmeyince henüz küçük bir çocuk olmasına rağmen babasını aramak iiçin yollara düştü. Zeka tanrıçası Athena Mentor adlı filozofun kılığına girerek ona daima öğüt verdi yol gösterdi.

Telephassa: Agenor''un karısı.Kadmos, Kiliks, Phoeniks,Europa''nın annesi.

Telephos: Herakles''in oğlu.Akhilleus onu savaşta yaralamıştı. Bir kahin mızrağın pası ile yarasını iyileştirdi.

Telesphoros: Meşhur bir hekim. Tanrılar katına kadar çıkmış.

Telkhin''ler: Güneşin çocukları. Volkanik olayların sembolüdürler. Bir bakışta insanları büyüleyebilen sihirbazdırlar.

Telmessus: Bugünkü Fethiye şehrinin kahramanı. Apollon ile Fenike kralının kızlarından birinin oğlu idi.

Tellus: Romalıların toprak tanrıçası Gaia''ya verdikleri ad.

Telonia: Yunanlıların dini merasim yapılmadan önce çocuklarının ruhlarına verdikleri ad.

Telphoussa: Bir Nymphe''nin adı.Ladon ırmağının kızıydı.Adını suyu buz gibi olan bir çeşmeye vermişti.

Tempe: Thessalia''da bir vadi. Poseidon burayı üç dişli yabasıyla açmıştı.

Tenedoks: Bozcaadanın eski adı.

Tenes: Tenedoks''a adını veren kahraman. Kolones kralı Kyknos''un oğlu.Akhilleus tarafından öldürüldü.

Terambos: Zamanın en iyi musiki sanatçısıydı, lir ve flüt çalmakta çok ustaydı.

Tereos: Thrakia kralı. Ares''in oğlu

Termeros: Termera şehrine adını veren azılı bir haydut. Herakles tarafından öldürüldü.

Terminüs: Romalıların sınır taşı tanrısı.

Terpsikhore: İlham perilerinden biri, dans Musa''sı.Sirenlerin annesi.

Tethys: Okeanos''un karısı. Okeanidler diye bilinen 3000 güzel kızın annesi

Teukris: Teukros''un kızı, Dardanos''un karısı

Teukros: Skamandros çayının tanrısı ile İda dağı perisi İdaea''nın oğlu.

Teuthis: Arkadia şeflerinden biri. Troia savaşında Agamemnon ile aralarında çıkan anlaşmazlık sonucu ordudan ayrılmıştı.

Tuthras: Anadoluda Mysia bölgesi kralı

Thalia: İlham perilerinden biri. Apollon ile evlenmiş Korybant''ları doğurmuştu. Sürülerin, bitkilerin, ekinlerin koruyucusu idi. Letafet perilerinden birinin adıda Thalia''dır.

Thamyris: Thrakia''lı efsanevi müzisyen ve şair. Philammon ile peri Argiope''nin oğlu. İlham perilerine meydan okuduğu için sesini güzelliğini ve gözlerini kaybetti.

Thanatos: Yunanlıların ölüm tanrısı, Hypnos''un ikiz kardeşi idi.

Thaumas: Pontos ile Gaia''nın oğlu. Okeanos''un kızı Elektra ile evlendi. İris ile Harryi''ler bu evlilik sonucu dünyaya geldiler.

Thebe: Kilika''lı bir kahraman kadın.Adramys''in kızı. Koşuda kendisini yenecek erkekle evleneceğini ilan etti, Herakles onu yendi ve onunla evlendi.

Thebai: Boiotia''lı Kadmos tarafından kurulan ünlü bir şehir. Yüksek surlarını Amphion lirinin sesi ile taşları yürüterek yapmıştı.

Theia: Uranos ile Gaia''nın kızı. Hyperion ile evlendi. Helios, Eos, Selen onun çocuklarıdır.

Theias: Belus''un oğlu, kendi öz kızı Smyra ile evlendi.

Themis: Kanunların, adaletin, örf ve adetlerin tanrıçası. Uranos ile Gaia''nın kızı. Zeus ile evlenerek Hora''ları, Parka''ları ve Metis''I doğurdu.

Theonoe: Thestor''un kızı.

Theophane: Bisaltes''in kızı. Çok güzel bir kızdı. Poseidon onu Krinis adasına kaçırdı.

Therapne: Leleks''in kızı

Thermedon: Amazonlar diyarında akan Terme çayı.

Therodamas: Skythia''nın efsanevi kralı. Aslanlarını insan eti ile beslerdi.

Thersandros: Thebai şehrinin kralı. Polynikes ile Argia''nın oğlu olan Amphia''nın oğlu. Amphiaros''un kızı Demonassa ile evlendi ve Tisamenos adında bir oğlu oldu. Telephos tarafından öldürüldü.

Thersites: Argios''un oğlu. Troia savaşında maskaralıklar yaparak askerleri eğlendirirdi.

Theseus: Yunanlıların en büyük kahramanlarından biri.

Thespiadlar: Thespios''un elli kızına ve onların çocuklarına verilen ad.

Thespios: Thespies şehrinin kahramanı. Erekhtheus''un oğlu. Elli kızının hepsinide Herakles''e metres olarak vermişti. Sadece bir kızını vermekten kaçınmıştı. Herakles te bu kızı Thespies şehrindeki kendi tapınağına rahibe yaptı. Diğer 49 kızın her biri birer erkek çocuk dünyaya getirdi. Bunlara Thespiadlar dendi.

Thesprotlar: Epir halkına verilen ad.

Thessallia: Tanrılar dağı Olympos''u da içine alan kuzey doğu Yunanistan da bir bölge.Herakles ile Khalkiope''nin oğlu Thessalos bu bölgeye adını vermiştir.

Thestiad''lar: Melagros''un iki dayısına bu ad verilir.

Thestion: Pleuron kralı.

Thestor: Apollon ile Laothoe''nin oğlu. Çok bilgili zeki biri olduğundan ona Yunanca bilgili anlamına gelen İdmon lakabını vermişlerdi.

Thetis: Nereus ile Doris''in kızı. Peleus''un karısı. Akhilleus''un annesi.Thetis Nereidlerin en güzeli idi. Zeus ile Poseidon onunla evlenmek istemişlerdi ancak Thetis''ten doğacak çocuğun babasını geçeceği haberi üzerine tanrılar küçük düşmekten çekinerek onunla evlenmeyi göze alamadılar. Bu yüzden de bu güzel tanrıça kral Peleus ile evlendirildi. 

Thiasos: Dionysos şerefine yapılan gece şenlikleri.

Thoas: Lemnos adasının kralı. Otreus''ın kızı Kallikopis (Myrina)   ile evlendi. Karısının kendisini Dionysos ile aldattığını öğrenince çok öfkelendi fakat tanrı şarap içirerek onu sakinleştirdi ve ona şarap yapmayı öğretti. Çok sonra Lemnos kadınları ayaklanıp kocalarını öldürmeye başladıklarında kızı Hipsipyle Thoas''u gizlice Lemnos''dan kaçırdı.

Thoe: Deniz Nymphelerinden biri. Okeanos ile Tethys''in kızı.

Thoosa: Phorkys''in kızı. Poseidon''dan Polyphemoz adında bir çocuğu oldu.

Thrakia: Ares''in, rüzgarların ve Orpheus''un yurdu.

Thrake: Okeanos ile Parthenone''nin kızı. Adını Thrakia bölgesine verdi.. Kız kardeşi Europa da adını Avrupa bölgesine verdi.

Thriai: Apollon''u Parnassos dağında büyüten üç periye verilen ad.Bunlar küçük çakıl taşları ile fala bakarak gelecekte olacaklarla ilgili bilgiler verirlerdi.

Thyestes: Pelops ile Hippodamia''nın oğlu. Babasının yerine kral olmak istediğinden kendisinden büyük olan kardeşi Atreus''tan nefret ediyor onun aile sadetini kıskanıyordu.Atreus''un karısı Europa''yı baştan çıkarıp ondan bir kaç tane çocuk sahibi oldu. Durum ortaya çıktığındaysa öldürülmekten korkarak kaçtı. 

Thyia: Deukalion''un kızı. Zeus''tan Makedonia adında bir kızı olmuştu.

Thyiadlar: Mainadlara, Bakhantlara verilen ad.

Thyria: Amphinomus''un kızı.Apollon''dan Kyknoks adında bir oğlu oldu.

Tiphys: Poseidon''un oğlu eşşiz bir gemi olan Argo gemisinin baş kaptanı idi.

Tiresias: Eski devirlerin en ünlü kahini. Athena''yı çıplak gördüğü için gözleri tanrıça tarafından kör edilmişti.

Tisiphone: Üç Eriny''den birinin adı. Öldüreni cezalandıran anlamına gelir. Bu kadın katillerden intkam almakla görevlendirilmişti.

Titanlar: Uranos ile Gaia''nın oğulları. İlk tanrıların soyundan olan Titanlar altı erkek altı da kız kardeştiler. Kronos kardeşlerin en küçüğü idi ve annesi ile birlikte babasını öldürerek yerine geçti.

Titanidler: Uranos ile Gaia''nın çocukları olan Titanlardan altı kzı kardeşe verilen ad. Bunlar Theia, Rhea, Themis, Mnomosyne, Phoebe, veTethys. Bunlar kendi kardeşleri ile evlenerek başka tanrıların doğmasını sağladılar.

Tithonos: Troia prenslerinden biri. Laomedon ile Skamandros''un kızı olan Strymo''nun oğlu. Eos bu prense aşık olarak onu kaçırdı. Zeus''tan kocasını ölmezler arasına almasını istedi ancak bu arada ebedi gençliğini istemeyi unutmuştu. Yıllar geçipte Tithonos yaşlanmaya başlayınca çekilmez biri oldu ve tanrılar onu çır çır böceğine dönüştürdüler.

Tityos: Zeus ile Elara''nın oğlu olan dev. Zeus kıskanç Hera''nın krokusundan Elara''yı yerin altında bir mağaraya saklamıştı. Elara doğum sırasında ölünce Zeus oğlunu yer''e emanet etti. Yer ona süt annelik yaptı bu yüzden Tityos''a yerin oğlu derler.

Tlepolemos: Herakles ile Astyokhe''nin oğlu. Yalnışlıkla Alkmene''nin kardeşi Lykymnios''u öldürünce Rodos adasına kçtı ve orada bir koloni kurdu.

Tlos: Miletus ile Praktisidike adlı bir perinin oğlu. Tlos şehrini o kurdu.

Tmolos: Lydia kralı. Ares ile Theogone''nin oğlu. Artemis''in arkadaşlarından biri olan peri Arripe''ye zorla sahip olunca Artemis tarafından cezalandırıldı ve bir boğanın boynuzlarında can verdi.

Trambelos: Telamon ile Theanira''nı oğlu. Miletus şehrinin kralı Arion tarafından büyütüldü. Bir peri kızna zorla shaip olup öldürdüğü için Akhilleus tarafından öldürüldü.

Trinakria: Helios''un yurdu.Sicilia adası.

Triopas: Poseidon''un oğlu Knidos şehrini kuran kahraman.

Triptolemos: Eleusis kralı. Keleus ile Metanire''nin oğlu. Ziraat aletlerinin mucididir.

Triton: Poseidon ile Amphhitrite''ninoğlu. Belden yukarısı insan belden aşağısı balık şeklinde ayakları at ayağına benzeyen bir deniz tanrısı.

Tritonlar: Nereidlerin arkadaşları olan deniz tanrıları.

Troia: Bugünkü Hisarcık şehrinin bulunduğu yerde olan eski bir şehir. Mitolojide Troia savaşına büyük yer verilmişti.

Troilos: Priamos ile Hekube''ninn oğlu. Akhilleus tarafından öldürüldü.

Trokhilos: Argos''lu bir kahraman. İo''nun oğlu savaş arabasını icat etmiştir.

Trophonios: Erginos''un oğlu olan Boiotia''lı kahraman. 

Tros: Phrygia kralı Erikhthonios''un oğlu,Troia şehrine adını vermiştir.

Turnus: İtalyada yaşayan Rutillerin kralı.

Tydeus: Etolia kahramanlarından. Kral Oeneus ile Periboia''nın oğlu. Diomedes''in babası.

Tykhe: Talih, tesadüf tanrıçası.

Tympanon: Korybantların icat ettikleri tef.

Tyndareos: Isparta kralı, Leda''nın kocası.

Typhon: Tartaros ile Gaia''nın oğlu olan korkunç bir ifrit. Yüz başlı ve yılan ayaklı idi.

Tyro: Salmoneus ile Alkidike''nin kızı. Enipe ırmağınıntanrısına gönül vermişti. 

Poseidon Tyro''yu sevdi ve Enipe ırmağı tanrısının kılığına girerek onunla birlikte oldu. Pelias ile Neleus adlarında iki çocukları oldu

U

Udeus: Euripe''nin babası. Kadmos''un arkadaşlarından biri.

Ufens: İtalya prenslerinden biri. Turnus yardımcısı. Troia''lı Gyas tarafından öldürüldü.

Ukelegon: Priamos''un dostlarından biri. Troia da çok önemli bir şahsiyetti. Yaşlı olduğundan savaşa katılamamıştı.

Ulius: Apollon''un isimlerinden biri. Canlı sıhhatli anlamına gelir.

Ultio: İntikam. Ether (Hava)   ile Gaia (Yer)  ''nın kızı.

Ultor: İntikamcı. Zeus ile Ares''in lakabı

Uragos: Hades''in bir diğer adı.

Urania: Göklerdeki Nymphelere verilen ad. Bunlar gökkubbesini idare ederlerdi.

Urania: Dokuz Musa (İlham tanrıçası)   ndan biri. Astronomi ve geometri ilham ederdi. 

Apollon ile birlikteliğinden Linus ile Hymene doğdu.

Uranos: En eski tanrı. Gaia''nın oğlu ve kocası.

V

Vagitanos: Çocukların bağırmalarını ve ağlamalarını idare eden tanrı.

Vakana: Kırlarda sayfiyelerde dinlenen, istrahat edenleri koruyan tanrı.

Velovis: Bir roma tanrısı. Yer altı tanrılarından sayılmakta, volkanlar ve balıkları bunun idare ettiğine inanılır.

Venüs: Güzellikve aşk tanrıçası Aphrodite''in bir diğer adı.

Vesper: Hesperos''un latince adı.

Vesta: Ocak başı tanrıçası Hestia''nın diğer adı.

Victoria: Zafer tanrıçası Nike''nin latince adı.

Vulturus: Apollon''un lakabı 

Y

Yphikles: Amphitryon ile Alkmene''nin oğlu. Alkides''in ikiz kardeşi. Alkides''in babası zeus olmasına rağmen Zeus sevgilisinin ikinci bir defa doğum sncıları çekmemesi için ikisini aynı zamanda doğurtmuştu.

Yphitime: Hermes''in aşık olduğu bir Nymphe. Bu birlikteliğin sonucunda Satyr''ler doğdu.

Z

Zagreus: Zeus ile Persephone''nin oğlu. Zeus bir yılan şekline girerek Persephone''a yaklaştı ve birlikteliklerinden Zagreus doğdu.

Zakoreus: Perseus''un yardımına koşan prenlerden birinin adı. Argos tarafından öldürüldü.

Zakynthos: Boiotia''lı bir kahraman..Dardanos''un oğlu olduğuna inanılır, adını Zanta adasına vermişti.

Zamolksis: Thrakia''lı bir kahraman, sonradan tanrılaştırılmış

Zazanas: Zeus''un lakabı

Zelos: Sadakat sembolü. Styks ile Okeanos''un oğlu. Zafer, Kudret, Şiddet Zelos''un kardeşleridir.

Zephyros: Batı rüzgarı, ilkbaharın müjdecisi.

Zetes: Boreas ile Orithyie''nin oğlu. Kalais''in ikiz kardeşi. Bu yüzden bu iki kardeşe Boreadlar derler. Bunların omuzlarında ve başlarında kanatları vardır.

Zethos: Zeus ile Antiope''nin oğlu. Amphion''un kardeşi.

Zeuksippe: Laomedon''un kızı

Zeukso: Okeanos ile Tethys''in kızı olan bir peri.

Zeus: Baştanrı. Tanrıların en büyüğü ve en güçlüsü. Babası Kronos''u tahttan indirerek yerine kendisi geçti. 

