INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Baharı Düşlemek İstiyorum', 'bahari-duslemek-i-stiyorum-bekir-mutlu-gokcesu-88oz6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Baharı düşlemek istiyorum

Beyaz ve pembe çiçeklerini

Ağaçların...

Olmuyor...

Vuruluyorum

Her yanımdan

Hissetmiyorum sıcağı ile

Ama biliyorum...

Yıldızların yaylım ateşinden

Kaçıyorum

Şehrin ışıkları tarıyor bedenimi

Yumuyorum gözlerimi

Bu kez de bir film şeridi

Saplanıyor her yanıma

Yaşanılası karelerin köşeleri

Helal olsun

Benimle vuruyorlar beni...

Ben bu gece

Baharı düşlemek isterken

Defalarca vuruluyorum

Tek sen ağlıyorsun

Biliyorum...

Bu yüzden

Ne kadar vurulsam da

Ölmüyorum...', 'Baharı düşlemek istiyorum Beyaz ve pembe çiçeklerini Ağaçların... Olmuyor... Vuruluyorum Her yanımdan Hissetmiyorum sıcağı ile Ama biliyorum...', ARRAY['Türk Edebiyatı','Şiir','Bekir Mutlu Gökçesu']::text[], 8.5, '{"poet":"Bekir Mutlu Gökçesu","poet_slug":"bekir-mutlu-gokcesu","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/bahari-duslemek-istiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acıktım', 'aciktim-serap-taylan-3gpc1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Şişmiş dalağından bir öğün yemek çıkar! ! ! 

Kanlı kansız farketmez

Canına susadım senin! 

Canın elimde 

Ha bugun ha yarın..

13/11/00', 'Şişmiş dalağından bir öğün yemek çıkar! ! !  Kanlı kansız farketmez Canına susadım senin!  Canın elimde  Ha bugun ha yarın.. 13/11/00...', ARRAY['Türk Edebiyatı','Şiir','Serap Taylan']::text[], 8.5, '{"poet":"Serap Taylan","poet_slug":"serap-taylan","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/aciktim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Misyoner', 'misyoner-kadir-soyturk-c1jyt', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dinime geri diyen; sinsi, sapık misyoner

İnsanlıktan çaldığın; para, servet  dinindir! 

Başka bir gücün mü var; yedir, içir, para ver

Dönekler, yüreksizler -al, git- hepsi senindir! 

“Allah birdir”diyemez; üç tanrıya taparsın

Kilise bir bahane; sen hainlik  yaparsın; 

Avrupada kapatıp, Türkiyede açarsın

Seni böyle gezdiren; menfaatin,  kinindir!', 'Dinime geri diyen; sinsi, sapık misyoner İnsanlıktan çaldığın; para, servet  dinindir!  Başka bir gücün mü var; yedir, içir, para ver Dönekl...', ARRAY['Türk Edebiyatı','Şiir','Kadir Soytürk']::text[], 8.5, '{"poet":"Kadir Soytürk","poet_slug":"kadir-soyturk","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/misyoner-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vatan Millet Sakarya, Hep Sizlere Akarya! ...', 'vatan-millet-sakarya-hep-sizlere-akarya-ozan-sah-turna-agdasan-go6a4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Suyun başında başları

İçtikleri göz yaşları

Uy derimizin közünde

Kaynıyor haram aşları...

Vatan millet sakarya

Hep sizlere akarya

Biri yer, bini bakar

Bir gün kıyamet koparya! ...

Uy að dalı dillerinden 

Riya kokan güllerinden

Boynuz boynuza tosladı

Yer gök inler zillerinden! 

Yurt tapusu, yat kat sizin

Parsel parsel çarp sat sizin

Talan pazarı kurulmuş...

Panzer, zulüm, çat-pat  sizin...

Nakarat:

Vatan millet sakarya

Hep sizlere akar ya

Biri yer bini bakar

Ký yamet ondan kopar ya! 

Yurdu sevmek soymak deð il

Ar, onurdan caymak deð il

Işık saçan ŞAHTURNA''nın

Gözlerini oymak deð il! ...

Nakarat:...

Söz ve Müzik: Halk Ozanı Aşık ŞAHTURNA / Ozan ŞİAR 

Aranje-Düzenleme: Ozan ŞİAR Ağdaşan

Barış Anaları/ Dumanlı Ödül Albümü (Halk Ozanı Aşık ŞAHTURNA) 

''Şakıyan Turna-ŞAHTURNA'' Kitab Can Yay.

www.sahturna.com

Not: Vatan, Millet-Sakarya edebiyatı ile Halkın Yurtseverlik duygularını

sömürenlere karşın; yıılardır gerek mücadelemizde haykırdığımız ve

gerekse de sazım, sözüm ve bestelerimde, yapıtlarımda dile getirdiğim

mizahi, didaktik eserimi sunuyorum. Yurdu ve halkı gerçek sevenlere merhaba diyerek...

Sevgiyle kalın, umudunuz solmasın! 

Halk Ozanı Aşık Şahturna

ŞAHTURNA Kültür-Sanat Evi  Enternasyonal Kadın Platf

www.sahturna.com', 'Suyun başında başları İçtikleri göz yaşları Uy derimizin közünde Kaynıyor haram aşları... Vatan millet sakarya Hep sizlere akarya Biri yer, ...', ARRAY['Türk Edebiyatı','Şiir','Ozan Şah Turna Ağdaşan']::text[], 8.5, '{"poet":"Ozan Şah Turna Ağdaşan","poet_slug":"ozan-sah-turna-agdasan","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/vatan-millet-sakarya-hep-sizlere-akarya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fotosentez', 'fotosentez-serap-taylan-hwzag', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ben yaprağın klorofilindeydim.

Yeşildim, kızıldım, sararmıştım.

Çiğ tutmuştum sabah sabah.

Yoksa yalan ben ağlamış mıydım? 

Geceleri nefes vermiş gibiydim.

Son nefesimi sana mı vermiştim? 

Yoksa yalan, ben ölmüş müydüm? 

Ezilmişim  iki yaprak arasında 

Unutulmuş hatıra, öylesıne saklanmışım.

Yoksa yalan  ben  hiç sevilmemiş miyim? 

02,11,00', 'Ben yaprağın klorofilindeydim. Yeşildim, kızıldım, sararmıştım. Çiğ tutmuştum sabah sabah. Yoksa yalan ben ağlamış mıydım?  Geceleri nefes v...', ARRAY['Türk Edebiyatı','Şiir','Serap Taylan']::text[], 8.5, '{"poet":"Serap Taylan","poet_slug":"serap-taylan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/fotosentez-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamak İçin', 'yasamak-i-cin-yasin-ozcan-e8odo', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir umut benimkisi

Benim beklediğim gemi

Yıllar önce ayrıldı bu limandan

Ve galiba yeminli

Demir atmış gelmemneye

Gönlüm

Tövbeli kara gözlere

Yalnız ona sevdalı

Oysa sır

Bu ucsuz bucaksız denizlerde

Gelmez bilirim

Bilirde anlamazdan gelir içim

Burda sefil perişan

Gelirdiye değil

YAŞAMAK İÇİN......', 'Bir umut benimkisi Benim beklediğim gemi Yıllar önce ayrıldı bu limandan Ve galiba yeminli Demir atmış gelmemneye Gönlüm Tövbeli kara gözler...', ARRAY['Türk Edebiyatı','Şiir','Yasin Özcan']::text[], 8.5, '{"poet":"Yasin Özcan","poet_slug":"yasin-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/yasamak-icin-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Aksam', 'bu-aksam-serap-taylan-4hm0m', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bu akşam,dalgalardaki köpüğüm 

Müziğin en hızlı ezgisiyim.	

Ve kalbini yumusatan

Çınarın tepesindeki en güçlü yaprak! 

Bu akşam rüzgarın sesiyim.

Bu akşam sokakların serserisiyim

Okyanusun  en dibindeki istiridyeyeyim. 

Ve içinde olabilecek en parlak inci

Bu aksam ben  şiirim 

aşıkların yalnızların  berduşların ağzındayım

Bu aksam ağzındaki son sigaranın dumanıyım

Ve ciğerlerinde dolaşan

Bu akşam ben senin herşeyinim

Olmami  istediğin herşeyim

Bu aksam ben ılık  bir esintiyim 

Ve senden habersiz kollarındayım.

06.05.98', 'Bu akşam,dalgalardaki köpüğüm  Müziğin en hızlı ezgisiyim.	 Ve kalbini yumusatan Çınarın tepesindeki en güçlü yaprak!  Bu akşam rüzgarın ses...', ARRAY['Türk Edebiyatı','Şiir','Serap Taylan']::text[], 8.5, '{"poet":"Serap Taylan","poet_slug":"serap-taylan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bu-aksam-35-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Resmin', 'resmin-can-ozcan-ozkan-ionz1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'akşamları 

koynumda sabahlarla avuturken

hasret yüklenmiş gecelerde 

yıldızlarla oynadım 

çocukluğumda kalma oyunları 

özlem sağanaklarında ıslanarak

 bekledim gün doğumunu 

ve 

ardından gelen tebessümünün 

ilk ışıklarını tutan 

göz bebeklerimde 

gökkuşağından salınan renklerle 

belirlendi resmin 

damla 

damla

akan göz yaşlarıma

her karenden bir renk bulandı

senden bana

şimdi ben 

biraz sen 

biraz da benim…', 'akşamları  koynumda sabahlarla avuturken hasret yüklenmiş gecelerde  yıldızlarla oynadım  çocukluğumda kalma oyunları  özlem sağanaklarında ...', ARRAY['Türk Edebiyatı','Şiir','Can Özcan Özkan']::text[], 8.5, '{"poet":"Can Özcan Özkan","poet_slug":"can-ozcan-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/resmin-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıldız', 'yildiz-can-ozcan-ozkan-2h3lc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ellerimin 

Bedeninde rüzgar esintisinde

Yüreğinde yanan mumu titretirken

Yüreğim avuçlarında 

Saçlarının gölgesinde

Bekliyor

Gecemden söküp alacağın 

Yıldızı…', 'Ellerimin  Bedeninde rüzgar esintisinde Yüreğinde yanan mumu titretirken Yüreğim avuçlarında  Saçlarının gölgesinde Bekliyor Gecemden söküp ...', ARRAY['Türk Edebiyatı','Şiir','Can Özcan Özkan']::text[], 8.5, '{"poet":"Can Özcan Özkan","poet_slug":"can-ozcan-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yildiz-33-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '14 Subat', '14-subat-serap-taylan-ibi18', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Oyle cok sevdim ki kendimi

Bir baskasini sevmeyi unuttum yasarken 

Oyle cok sevdim ki kendimi

Istemedim baska kimseyi

Ruhumu seyrederken aynada

Kiskandim aynayi

Oyle bir kara sevdayla tutuldum kendime 

Yillardir bitip tukenmeyen…

25,03,1999', 'Oyle cok sevdim ki kendimi Bir baskasini sevmeyi unuttum yasarken  Oyle cok sevdim ki kendimi Istemedim baska kimseyi Ruhumu seyrederken ayn...', ARRAY['Türk Edebiyatı','Şiir','Serap Taylan']::text[], 8.5, '{"poet":"Serap Taylan","poet_slug":"serap-taylan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/14-subat-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen', 'sen-can-ozcan-ozkan-jffpt', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gece

