INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüzgar', 'ruzgar-serap-taylan-unbgi', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ölüm gibi saklanarak

Ve bir anda vuruyor rüzgar

Rüzgar; 

Geçmeye korktuğum sokakların 

Kapısı olmuş girdirmiyor.

Rüzgar; 

Parmaklarımın arasında 

Kulaklarımda vınlıyor.

Rüzgar; 

-Küstüm- e benzetiyor beni

İçime  sarılıyorum 

Yetmiyor! ! Yetmiyor! ! ! 

Rüzgar; 

Beni öldürüyor! 

07.05.99', 'Ölüm gibi saklanarak Ve bir anda vuruyor rüzgar Rüzgar;  Geçmeye korktuğum sokakların  Kapısı olmuş girdirmiyor. Rüzgar;  Parmaklarımın aras...', ARRAY['Türk Edebiyatı','Şiir','Serap Taylan']::text[], 8.5, '{"poet":"Serap Taylan","poet_slug":"serap-taylan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ruzgar-87-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olur ya...', 'olur-ya-hasim-turker-csafm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'olur ya bir gün,

şefkatle dokunan

elleri ararsa,

sarı saçların,

hasretle bakan

gözleri görmek isterse

güzel gözlerin,

delice çarpan

bir kalbi

duymak isterse kulakların,

ve hatıraların ılık meltemi 

vurup da melek yüzüne,

hissedersen gönderdiğim buseyi,

işte o gün ben,

seni bekliyor olacağım…', 'olur ya bir gün, şefkatle dokunan elleri ararsa, sarı saçların, hasretle bakan gözleri görmek isterse güzel gözlerin, delice çarpan bir kalb...', ARRAY['Türk Edebiyatı','Şiir','Haşim Türker']::text[], 8.5, '{"poet":"Haşim Türker","poet_slug":"hasim-turker","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/olur-ya-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adını adıma yazdım', 'adini-adima-yazdim-i-brahim-duskun-fneeb', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'adını adıma yazdım

gözlerinde büyüttüm umudu

bir sabah gelirsin diye

günleri bir bir ben gönderdim

yıllar nede çabuk tükendi

bu kaçıncı mevsim eskidi

bak bir kış daha geldi

zemheri aylar şimdi

umuda nice zaman eridi

bahar düşlerim vardı bitmedi

güneş özlemi oldu yüreğin

geceler gündüze yetmedi.', 'adını adıma yazdım gözlerinde büyüttüm umudu bir sabah gelirsin diye günleri bir bir ben gönderdim yıllar nede çabuk tükendi bu kaçıncı mevs...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Düşkün']::text[], 8.5, '{"poet":"İbrahim Düşkün","poet_slug":"i-brahim-duskun","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/adini-adima-yazdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sıcak Eller', 'sicak-eller-serap-taylan-dhxs6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bana ellerinin devamını ver.

Suskunluğun olmalı verirken.

Sana bugün anlatacaklarım var.

Pek renkli değil cümlelerim.

Ellerimi sıkı tut! 

Cümlelerim bittiği gibi.

Sende herşeyi unut! Unut! Unut! ! ! 

13,11,00', 'Bana ellerinin devamını ver. Suskunluğun olmalı verirken. Sana bugün anlatacaklarım var. Pek renkli değil cümlelerim. Ellerimi sıkı tut!  Cü...', ARRAY['Türk Edebiyatı','Şiir','Serap Taylan']::text[], 8.5, '{"poet":"Serap Taylan","poet_slug":"serap-taylan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sicak-eller-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İkibin bir', 'i-kibin-bir-serap-taylan-iaf05', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Devir milenyum devri 

Öyle böyle degil takvimdeki 

Rakam “ikibinbir “.

Mektup dedigin elektronik 

Kalemi kagıdı unut.

Bir bilgisayara bakıyor aşklar.

Ne güvercin ne duman

Mesajlar  eline düşüyor birer birer

Bır geldim de   yeter.

Bu devir baska devir

Takvimdeki rakam heyyy! ! ! 

Ikibinbir! ! ! ! !', 'Devir milenyum devri  Öyle böyle degil takvimdeki  Rakam “ikibinbir “. Mektup dedigin elektronik  Kalemi kagıdı unut. Bir bilgisayara bakıyo...', ARRAY['Türk Edebiyatı','Şiir','Serap Taylan']::text[], 8.5, '{"poet":"Serap Taylan","poet_slug":"serap-taylan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ikibin-bir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Paralel bir hüzündü', 'paralel-bir-huzundu-gencay-coskun-jfcyc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Paralel bir hüzündü 

Yan yana yerde yatan 

Ölüme beş kala 

Su çekilirdi ince damarlardan 

Etraf bir garip gri 

İçlerde sızlayan bir pınar 

Renklerin görünesi yoktu bu saatlerde 

Ağlayan rüzgardı 

Sesini duyan olmazdı 

Paralel bir hüzündü 

Biz hangi mevsimde 

Kaçırmıştık zamanı....', 'Paralel bir hüzündü  Yan yana yerde yatan  Ölüme beş kala  Su çekilirdi ince damarlardan  Etraf bir garip gri  İçlerde sızlayan bir pınar  R...', ARRAY['Türk Edebiyatı','Şiir','Gencay Coşkun']::text[], 8.5, '{"poet":"Gencay Coşkun","poet_slug":"gencay-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/paralel-bir-huzundu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Menekşe', 'menekse-serap-taylan-81mes', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben mor sandim menekseyi

gördüğüm bütün menekşeler

mordu çünkü...', 'Ben mor sandim menekseyi gördüğüm bütün menekşeler mordu çünkü......', ARRAY['Türk Edebiyatı','Şiir','Serap Taylan']::text[], 8.5, '{"poet":"Serap Taylan","poet_slug":"serap-taylan","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/menekse-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gediz 1.', 'gediz-1-sezer-odabasioglu-wujzu', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'bunca rüzgara

yağmura

tufana

kara kışa dayanırım da 

dayanamam tek vedana

ki vedan acılı ağlatmalı

vedan zorlu zorba

ha bir çiçeği koparır dalından

ha bir gediz''i koparır coğrafyadan...

''Irmak Türküleri'' başlıklı şiir dosyasından.', 'bunca rüzgara yağmura tufana kara kışa dayanırım da  dayanamam tek vedana ki vedan acılı ağlatmalı vedan zorlu zorba ha bir çiçeği koparır d...', ARRAY['Türk Edebiyatı','Şiir','Sezer Odabaşıoğlu']::text[], 8.5, '{"poet":"Sezer Odabaşıoğlu","poet_slug":"sezer-odabasioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/gediz-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Seviyorum', 'seni-seviyorum-tunahan-ermihan-pgjwt', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Karanlık içinde açıyorum avuçlarımı semaya

Gözlerimde senden kalma gözyaşı pırıltıları

Sesleniyorum yaratanıma, dualar ediyorum sana

İncinmesin bir gün bile diyorum sessizce

Gözlerinde sadece tebessüm

Yüreğinde her daim mutluluk olsun diyorum

Karanlıklar içinde açıyorum avuçlarımı semaya

Hatıra kırıklarım aydınlatıyor sokakları gece yarısı

Ağlamaklı çıkıyor sesim adın dilime dokunduğunda

Gelişlerini izlediğim pencereden bakıyorum

Gidişin canlanıyor hep gözlerimde bebeğim

Gittiği yerlerde hep mutlu olsun diyorum

Karanlıklar içinde açıyorum avuçlarımı semaya

Bir yıl devrediyor ömrümüz şu yaşlı dünyada

Usulca dökülüyor yeni sene gökyüzünden

Geçen sene de yoktun ve yine yağmur yağmıştı

Ben sensiz girdiğim her seneye

Küskün kaldım bütün sene boyunca

Bensiz girdiği senelerle barışık olsun diyorum

Karanlıklar içinde açıyorum avuçlarımı semaya

Uykularımı hediye ettim az önce sokak çocuklarına

Birisi gülümsedi öteki alıp kaçmaya çalıştı

Şimdi ellerim duada gözlerim semada

Bensiz girdiği yatağında

Huzur içinde uyusun diyorum', 'Karanlık içinde açıyorum avuçlarımı semaya Gözlerimde senden kalma gözyaşı pırıltıları Sesleniyorum yaratanıma, dualar ediyorum sana İncinme...', ARRAY['Türk Edebiyatı','Şiir','Tunahan Ermihan']::text[], 8.5, '{"poet":"Tunahan Ermihan","poet_slug":"tunahan-ermihan","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/seni-seviyorum-230-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalabalık Yalnızlık', 'kalabalik-yalnizlik-sezer-odabasioglu-x8ntq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'bir kalın kabuklu ağaca

bir kafesteki kuşa

bir ince daldaki çiçeğe 

                   dokunduğumuz gibi

                   dokunamadık birbirimize

bir dokunsak

ah bir dokunabilsek ellerimizle

ya da gözlerimizle

biliyorum temizlenecek

ilk çocukluğumuzda

                   korkularla beslenen ruhumuz

ve dağılacak

içimizdeki kalabalık yalnızlık.

''Senden Yana Büyür Çığlığım'' başlıklı şiir dosyasından.', 'bir kalın kabuklu ağaca bir kafesteki kuşa bir ince daldaki çiçeğe                     dokunduğumuz gibi                    dokunamadık birb...', ARRAY['Türk Edebiyatı','Şiir','Sezer Odabaşıoğlu']::text[], 8.5, '{"poet":"Sezer Odabaşıoğlu","poet_slug":"sezer-odabasioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/kalabalik-yalnizlik-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Entel dantel', 'entel-dantel-sair-shimalwest-e45jf', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ne adamlar gördüm üzerinde elbise yok

ne elbiseler gördüm içinde adam yok

.........

metroseksüel olsan kaç yazar

iki laf edince herkes kaçar

giymişsin üzerine grantuvalet

sanmışsın oldum önemli şahsiyet

statü atlamak böyle kolay mı

adam olana statü şart mı

keşke benzemesen hiçbirşeye

vakıf olsan herşeye

entellektüel olmak asıl olay

entel görünmek çok kolay

televole melevole derken

yozlaşıyoruz AB ye giderken

ne işimiz var bizim orda

entel dantel dolu toplumla

bıraksınlar bizi kendimize

girmesinler her özelimize

güdülmeye alışanları birlikte

eğitelim fikrimizle......', 'ne adamlar gördüm üzerinde elbise yok ne elbiseler gördüm içinde adam yok ......... metroseksüel olsan kaç yazar iki laf edince herkes kaçar...', ARRAY['Türk Edebiyatı','Şiir','Şair Shimalwest']::text[], 8.5, '{"poet":"Şair Shimalwest","poet_slug":"sair-shimalwest","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/entel-dantel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur Şiir Yazıyordu', 'yagmur-siir-yaziyordu-meral-vurgun-64un5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'AYDIN’A 

yağmur şiir yazıyordu Ren üstüne 

yapış yapış ıslanıyordu alnı kirli yüzler 

yüreğini kendi ayaklarıyla ezenlerin 

katran kara ter kusan tenlerinden 

irin dökülüyordu aşınmış ellerine 

kof bakışlı çürük alınlarıyla 

bir zamanlar Munzur çağlayan 

Toros’lar kokan gözler 

haraç mezat,üç kuruş hesap 

her yana saçılmış riyalarını 

satışa çıkarıyordu sokak aralarında 

inadına o terasta içtiğimiz kahveye 

kırk yıl hatır biçmedik biz 

ama biliriz ki kenetlenmişti 

dost yüzümüzde bir çift yürek 

şimdi hüzün kasırgası 

kan damlayan yüreğin 

toplasak parçalarını 

tuza bandırıp acılarını içsek 

geçilmemiş ıssızlar gibi 

baykuşlara mesken olan 

bağrımızın en yangın yeri 

susku çığları düşürür us’umuza 

vadilerimizde bulanık seller köpürür 

mavi balıklarını boğar ırmaklarımız 

şimdi yaralarımızı közle dağlasak 

her damlası hicran olur dizelerin 

bilirim can 

şimdi sürgünlüğümüzü taşımaz künyemiz 

vurgun yemiş bir yunus gibi dibe vursak da 

sesimizi etimize diken gibi batıra batıra 

susmayı da biliriz 

hadi kaldır başını yukarı 

kaldır ki 

o kalenin burcundaki bakır şovalye 

görsün gözlerinde Munzur gözelerini...', 'AYDIN’A  yağmur şiir yazıyordu Ren üstüne  yapış yapış ıslanıyordu alnı kirli yüzler  yüreğini kendi ayaklarıyla ezenlerin  katran kara ter ...', ARRAY['Türk Edebiyatı','Şiir','Meral Vurgun']::text[], 8.5, '{"poet":"Meral Vurgun","poet_slug":"meral-vurgun","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/yagmur-siir-yaziyordu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'II38 Un(bull) do(ser)', 'ii38-un-bull-do-ser-akin-akca-2j9sh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Macabre-windmill make ‘em search for the walking-pill 

THX Cop did not stop, 

being a running owl with high speed! 

Sec.Op. Newshead, did run after him; 

(mind is busy, cos we’re runnin in tommarrow. 

Together, robots with human..)

in an extraordinary 

rabbit exit tunnel of Lucas, it was brought a gift. 

Could it be said for “love” as it’s the “ultimate crime”? 

or its lift, are the steps of overcome? 

.. Where escape of one’s, hath real fear 

of the cousin of near-death: 

“You should not escape,! ”

”You shall not love! “

Ye, such twins are the best crime? ? 

Oh, no, this had no succeed 

   Indeed! 

      Ennuyeux, Intéressant… 

         Un anniversaire! 

            Voulez-vous danser avec moi? 

I shall escape! ! 

with the days o’yor nightmare,

while nuthing would be back upon us. 

But at least, i chose a bot cop 

which will come behind me 

so as to catch me, 

Thx-Undo, punishers.. 

.. at 1138-underground! 

(Origin? 

Betw. Human, 

unfortunately, no more, origin …)

: I want its mask, 

I want this light grey mask 

And this bronz activated 

anger piece of body: 

These are hammer,

thoughts of wish! 

It’s nice, around, like that manner; 

and mine is, sure! best task 

Türkçesi: 

1138 Yoldüz(meğ)  er 

Ölümcül yel değirmeni, yürüten-hapı arattı 

Robot polis Newshead, durmadı; 

koşan baykuş olarak, yüksek hızda: 

Thx Güvenlik Botu, ondan sonra koştu 

(Zihin meşgul, geleceğin dünyasında. 

Birlikte bir şekilde, makkinnainsanlar..)

Sıra dışı bir tavşan çıkış tünelinde Lucas’ın, 

bir hediye ona verildi. 

Sevgi için, denilebilir mi aşk için; 

onun, son bir suç olduğu? 

Ya da basamakları üstesinden gelme’nin, 

asansörü mü onun? 

Kaçış’ının birisinin.. sahip olunan gençlik hali’nin..

kendisi korku’nun olabildiği, 

.. yakın-ölüm’ün hısım kuzeni’nin: 

“Kaçmamalısın! ” 

“Sevmeyeceksin! ” 

Bu ikizler, bir araya mı gelince 

büyük suçturlar? 

Hayır! hayır! bunun başarısı yok! 

gerçekten! 

Sıkıcı! .. ama ilginç.. 

de … 

ve doğum günü! 

Benimle dans eder misiniz? 

Kaçacağım! ! 

Kabusun ile kaçacağım, 

Bir şey kalmaksızın bize! 

Fakat, en azından, 

hepsi de birbirine, birbirine 

benzeyen lağım botlarından 

bir polis seçtim: 

(huyu suyuma uyan - 

ben kaçacağım, o yakalayacak. 

Orijinalite? daha yok.)

Arkamdan koşturacak,

az becerisi olan; 

beni yakalamak için, 

… Thx-Bozguncu,

1138-Yeraltı’nda! 

Onun maskesini istiyorum. 

Onun parlak, açık gri maskesini! .. 

Güzel olan etraftaki tek şeyi. 

Ve soluk, silik, isteksiz 

meyleden kavgacı cüssesini: 

Bunlar çekiç,

dileğin düşünce kıvrımları! 

Ve en iyisi, bu tavır bendeki, 

emin olmalısın! ve yine etraftaki 

- 

George Lucas. İlk film. 

thx-1138 kült b.kurgu filmi için 

sec op Newshead: ürettiğim bir terim. 

Security guard Haber kafalı=metal yığını= 

İnsnları, üretmek ile tüketmek arasında bacalatarak

karıncalaştırıp devamlı satın almaya zorlayan

bir robotlar ordusunun elemanı.

Yeraltında, hayat böyle geçip gidiyor

Şiirin tam adı: THX•II38 4EB  Un(bull) do(ser) 

Orijinal adı: II38 Un(bull) do(ser)', 'Macabre-windmill make ‘em search for the walking-pill  THX Cop did not stop,  being a running owl with high speed!  Sec.Op. Newshead, did ru...', ARRAY['Türk Edebiyatı','Şiir','Akın Akça']::text[], 8.5, '{"poet":"Akın Akça","poet_slug":"akin-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":101,"source_url":"https://www.antoloji.com/ii38-un-bull-do-ser-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen de Kırılıp Döküldün', 'sen-de-kirilip-dokuldun-ahmet-hakan-yilmazturk-tkrm6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'bu ayrılık biliyorum seni yatak döşek yatıracak

kaçınılmaz bir tekerrürü kaderinin, ağı örülmüş

dikkati elden bırakma, delice divanece aşılısın

suç doğurmaya meyillisin de, korkum ondandır

hem de insanlık suçu saçma sapan özensizliğin

hala tavını bulmamış bu çocukcağızların kalbi

camdan olduğundan tınlıyor, duymuyor musun

yazmaya kalkma kaderlerini seninki kahpeyken

el yordamıyla yoklamaya benzemez yetiştirmek

sahipleneceksin şartı yok, yargısızca seveceksin

ümitlerini besleyeceksin, gönüllerini sulayarak

taviz de alacaklar, izin  de vereceksin hatalara

biliyorum sana benzemesinler diye gayretlerin

ama olmuyorki, mutfakta dolaşan filler gibisin

hatırla, sen de kırılıp döküldün, hala da öyle ya

bu yaralı çocuklar sana rağmen büyüyecekler 

ezilecekler, çarkı feleğin göbeğinden görünen

yetişkin olacaklar ama kırık, ama tokatlanmış

onların bakir ağına da kaderin yuvalandığında 

suçlar isnat edip ak kaşıklık mı taslayacaksın

bu ayrılık biliyorum seni yatak döşek yatıracak

kaçınılmaz bir tekerrürü kaderinin, ağı örülmüş

04.01.2005

***Samanyolu Grubunun 2K1Ş ''İki Kelime Bir Şiir'' Aktivitesi için kaleme alınmıştır. 16. Hafta Kelimeleri: ''AYRILIK'' ve ''ÇOCUK''', 'bu ayrılık biliyorum seni yatak döşek yatıracak kaçınılmaz bir tekerrürü kaderinin, ağı örülmüş dikkati elden bırakma, delice divanece aşılı...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Hakan Yılmaztürk']::text[], 8.5, '{"poet":"Ahmet Hakan Yılmaztürk","poet_slug":"ahmet-hakan-yilmazturk","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sen-de-kirilip-dokuldun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YENiDEN', 'yeniden-rengin-gardner-y2unk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Muslugun ilik suyu, yikadi anilarimi

Yuzumde dune ait hic bir ani birakmadim

Banyo aynasi buharlasti,

Cunku dunumu yikadim,

Gecmisim  bugunden arindi, 

Yarina giyindim, umutla susledim

Anilardan arinan suratimi.

Temiz havayi cigerlerime cektim

Cicek kokularini parfum yaptim kendime.

Guzel bir gune uyandim,

Koynumda yalnizligim, ozgurlugumu kucakladim,

Yeni bir yilin, ilk gununde

Soz verdim kendi kendime,

Yeni bir ben ile basladim yeni gune.

Rengin Gardner ocak /3 /2004', 'Muslugun ilik suyu, yikadi anilarimi Yuzumde dune ait hic bir ani birakmadim Banyo aynasi buharlasti, Cunku dunumu yikadim, Gecmisim  bugund...', ARRAY['Türk Edebiyatı','Şiir','Rengin Gardner']::text[], 8.5, '{"poet":"Rengin Gardner","poet_slug":"rengin-gardner","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/yeniden-46-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cocuk Olmak', 'cocuk-olmak-rengin-gardner-dfwlf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ne guzel yine ben olmak,

O mutlu, o sirin, kiz cocugunu

saklandigi yerden bulup cikarmak.

Kir ciceklerini, menekseleri, 

Loparmaya kiyamadan seven koklayan 

Yanaklari elma sekeri misali,

O sevincli, umutlu, o sevgi dolu

Minik kiz cocugu,

Hosgeldin bana, hosgeldin kendi yuvana.

Artik hic birsey urkutmuyor beni,

Ben bir cocugum, severim tatlilari sekerleri

Gucluk nedir bilememki, hersey flim gibi

Evdeki cocuklarda kim? 

Onlar benim oyuncak bebeklerim

Uc tane bebegim var ikisi kiz birisi erkek

En cok evde onlarla oynamayi severim.

Yalanciktan anne olurum, bulasik yikarim camasir katlarim.

Bazen mahsuscuktan isede giderim,

Buyuk anne babalar gibi para kazanir gelirim.

Yine evcilik oynarim, bebeklerimle

Gucluk nedir bilmemki, Hayat flim gibi.

Hic birseyden korkmam hem,

Karanlik ve gok gurultusu korkutur beni

Cocuk olmak oyle guzelki

Tasimiyorsun hic yarinlar endisesi

Ocak 03 2005 Rengin Gardner', 'Ne guzel yine ben olmak, O mutlu, o sirin, kiz cocugunu saklandigi yerden bulup cikarmak. Kir ciceklerini, menekseleri,  Loparmaya kiyamadan...', ARRAY['Türk Edebiyatı','Şiir','Rengin Gardner']::text[], 8.5, '{"poet":"Rengin Gardner","poet_slug":"rengin-gardner","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/cocuk-olmak-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne dersek diyelim', 'ne-dersek-diyelim-burhan-kucuk-fin4j', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ne dersek diyelim

Zaman sürgüsünü çekti mi

Sallanır dünya

Ve depremler,tufanlar

Acımasız...

Bilenler söylemezler

Alır altına,sürükler yüz binleri

Bir bir göçer insanlar

Amansız...

Zaman sürgüsünü çekti mi

Ayrılırlar....

Denizler ötesinden

Otlaktaki çürümüş kemikten

Akbabalar,leş kuşları

Pike yaparlar göklerden

Körpe serçe kuşlarına

Yanık bir ağıt olur

Kuş sesleri

Altında yakan günün

Çok oldu öleli kızılderili

Ne dersek diyelim..

Burhan KÜÇÜK

Kdz.Ereğli_01.01.2005', 'Ne dersek diyelim Zaman sürgüsünü çekti mi Sallanır dünya Ve depremler,tufanlar Acımasız... Bilenler söylemezler Alır altına,sürükler yüz bi...', ARRAY['Türk Edebiyatı','Şiir','Burhan Küçük']::text[], 8.5, '{"poet":"Burhan Küçük","poet_slug":"burhan-kucuk","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/ne-dersek-diyelim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kavanoz Dipli Dünya', 'kavanoz-dipli-dunya-ekrem-sama-rc2am', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '(Kavanoz dipli dünyada nelere şahit oluyoruz? 

İslamın ilk yıllarında Peygamberimiz (SAV) e ve müslümanlara en büyük kötülükleri yapan nice insanlar, sonradan müslüman olarak dine ve dindarlara en büyük hizmeti yaptılar.

Ebu Süfyan (RA)  ve İkrime (RA)  isimleri bunlardan sadece iki örnektir. Yine o devirde Peygamberimiz (SAV) in dizinin dibinde feyz alan ve en uç noktalarda görev yapan bazı insanlar da, bir anda dinden çıkarak düşman oluvermişlerdir. Peygamberimizin zekat memuru Abdullah bin Hatal ile  vahiy katibi Abdullah bin Sa''d sadece iki örnektir.

Çağımızda da insana çelişkili gibi görünen bu tür olaylar yaşanmaktadır:

Seksen küsür yaşına gelene kadar Allah''ın olmadığını savunan ünlü felsefe profesörü Ateist Antony Flew; ''Yeni anlıyorum ki  Allah varmış, ben hep yanlışta imişim.''  dedi. Ateist olduğunu her fırsatta dile getiren ünlü gazeteci ve köşe yazarı Serdar Turgut da yanıldığını ve artık Allah''a sığındığını açıkladı. Ömür boyu dini savunanlara gerici, yobaz, bağnaz ve laiklik düşmanı diye sıfatlar takmış bulunan ünlü siyasetçi Rahşan ve Bülent Ecevit çifti, yazılı bir açıklama yaparak; başbakanının ve bakanlarının çoğun İmam Hatip kökenli olan ''Hükümetin dinimize ters icraatları yüzünden, hıristiyanlığın yayılmakta olduğunu ve İslam Dini''nin yok olma tehlikesi ile karşı karşıya bırakıldığını, misyoner faaliyetlerinin arttığını, her sokakta kiliseler açılmakta olduğunu ve tedbir almak gerektiğini'' ifade ettiler...) 

İşte kavanoz dipli dünyadan bir kesit,

Hiç kimse değil, bulunduğu yerde daim...

İslamı savunur oldu şimdi Ecevit,

Bakmışsın zalimler alim, alimler zalim...

(İstanbul:04.01.2005)', '(Kavanoz dipli dünyada nelere şahit oluyoruz?  İslamın ilk yıllarında Peygamberimiz (SAV) e ve müslümanlara en büyük kötülükleri yapan nice ...', ARRAY['Türk Edebiyatı','Şiir','Ekrem Şama']::text[], 8.5, '{"poet":"Ekrem Şama","poet_slug":"ekrem-sama","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/kavanoz-dipli-dunya-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlık Üstüne', 'yalnizlik-ustune-mutluhan-kurt-ht270', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'sigaramı yaktı yanımda sırt üstü uzanmış çocukluğum,konuşmaya başladı sonra,içini bir yılanın zehiri gibi içime akıtarak.bende yazmaya başlıyorum,sadece usulca ağlayarak yalnızlığıma...

gidişine ağız dolusu bir küfür savurup,dişlerimi sızlatan yağmursuz bulutların gölgesine bırakıyorum dolmuş yüreğimin bütün boşluğunu.sen sayki; hala adınla başlayan şiirler yazıyorum...sen sayki; bütün çıkmaz sokakları yüreğimin sana çıkıyor...ve sayki; yüreği elinde koşan o mutlu çocuğun yüzü hala gülüyor...

yüzünün yanılmışlığı var artık ellerimde,yüzümde yüzünün yanılmışlığı,birazda ağlamışlığı soğuk gecelerimde.artık görmeyek kadar kör olamıyorum yada duymayacak kadar lal.yersiz bir renk gibi beklerken baharın müjdesini,en siyah renklerin matemiyle soldurdun beni.bu kefen dar geliyor,teninin kokusunun sinmişliği varken tenime.dar geliyor,giderken son kez dokunduğun gözbebeklerime...

otopsisi yapılmamış bir ölünün morgdaki en soğuk saatleri kadar yalnız ve kanamalı bir şiire asıyorum kendimi.bir ölüme kaç şiir sığarsa,bir şiire o kadar ölüyorum...

baharları bıraktım ayazların soğuk gençliğinde,şimdi iklimsiz şehirlerin haritalara yazılmamış günlerini yaşıyorum.her adım üzülüp,her sokak ağlıyorum.deniz mavi hala belkide öyle sanıyorum...

suskunluğumun gardiyanı dilim paramparça,sen hala bölünmüş bütünlüğünle kalbimdesin.

utanmıyorum...

çünkü; dilim paramparça,kalbim değil...', 'sigaramı yaktı yanımda sırt üstü uzanmış çocukluğum,konuşmaya başladı sonra,içini bir yılanın zehiri gibi içime akıtarak.bende yazmaya başlı...', ARRAY['Türk Edebiyatı','Şiir','Mutluhan Kurt']::text[], 8.5, '{"poet":"Mutluhan Kurt","poet_slug":"mutluhan-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yalnizlik-ustune-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Meleğin Ölümü', 'bir-melegin-olumu-mutluhan-kurt-74c6a', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'gülüyorsun; 

dişlerinin arasından pul pul güneş ışığı saçılıyor dört bir yana

akşam olmuyor hiç gözlerinde 

çocuklar hep gülüyor...

ağlıyorsun; 

hiç bir canlı senin kadar güzel ağlayamıyor

gözlerinden düşmek istiyorum

yere çarparak ölmek istiyorum...

gidiyorsun; 

aklınca bütün cenazeleri götürüyorsun benden

bilmiyorsun en büyük cenazeyi bana bıraktığını

en büyük acıyı bana yaşattığını...

ölüyorsun; 

bir melek gibi ölüyorsun

gözlerime bütün karanlıklar çöküyor

yinde görüyorum seni kör olmak pahasına...

sana bakıyorum; 

                            gülüyorsun...

sana bakıyorum; 

                            ağlıyorsun...

sana bakıyorum; 

                            gidiyorsun...

seni görüyorum; 

                            ölüyorsun...', 'gülüyorsun;  dişlerinin arasından pul pul güneş ışığı saçılıyor dört bir yana akşam olmuyor hiç gözlerinde  çocuklar hep gülüyor... ağlıyors...', ARRAY['Türk Edebiyatı','Şiir','Mutluhan Kurt']::text[], 8.5, '{"poet":"Mutluhan Kurt","poet_slug":"mutluhan-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bir-melegin-olumu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Benim İşte', 'o-benim-i-ste-murat-demir-4fm21', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sen aşka susayıpta

Yananı hiç gördün mü

Sen birini sevipte

Peşinden süründün mü

Yüreğin kavruldukça

Kızıpta darıldın mı

Yastığa dudak vurup

Yorgana sarıldın mı

Park bahçe bağ dağ derken

Aramaktan yıldın mı

Bir zalimin yüzünden

Aleme darıldın mı

Bilmiyorsan sevdiğim

Öğren o işte benim

Bir sevda ki günbegün

Yanıyor ciğerlerim

Bilmiyorsan birtanem

İşte o kurban benim

Aşk bende hançer sende

Vur kesilsin her yerim

Bilmiyorsan a canım

İşte o yanan benim

Gündüzlerim bir yana

Bitmiyor gecelerim

Geçer dedikçe battım

Senin derinliğine

Gel nerdesin gel n’olur

Bari bir günlüğüne!', 'Sen aşka susayıpta Yananı hiç gördün mü Sen birini sevipte Peşinden süründün mü Yüreğin kavruldukça Kızıpta darıldın mı Yastığa dudak vurup ...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/o-benim-iste-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Şehir Senin Yüzünü Kuşanmış', 'bu-sehir-senin-yuzunu-kusanmis-mutluhan-kurt-rvtxb', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'bir ayaza uyandım bu sabah,özlemine yattığım uykudan,kınanmış bir sabır değilki benimki baharı beklemiyeyim.ama sabahlar zor,sabahlar erken...ölmek için...bu sabah sensizliğe uyandım...

bir kardelen düşü,bir salkımsöğüt gölgesi,birazda yamalı anılarla kendimi alıp bu günlerin paslı demir tadından rüzgara savuruyorum.ellerimde hasret,kulağım tanıdık bir yalnızlık ezgisi...bu sabah bir karanfil düştü uykusuzluğuma...

kalktım,daha gün yıkamamıştı yüzünü dağların sularında.kalktım,hiçbirşey yerinde değildi

sızılarımdan,yaralarımdan başka.yerindeydi yaralarım kalbimin tam ortasında.kalktım,böyle yorgun,böyle yılgın ve paramparça.şakaklarımda bu kent terliyordu,cenazeler kalkıyordu kuşların kanatlarında...kalktım ki; bu sabah dünler ve bugünler yine akraba...

yalnızlığımı demledim,sonbaharın düşen yapraklarıyla.yaralı bedenimi alıp bu kentin kirlenmiş sokaklarına çıktım.adını üstüme almayı unutmadım.

yağmur yağdı sonra...sonra ağladım...gitmiştinya zaten,bir intiharı tetiklemekten başka bir şey kalmamıştı bu kentin avuçlarında...

bu kent avuçlarını uzattı bana,baktım yüzün vardı orada...', 'bir ayaza uyandım bu sabah,özlemine yattığım uykudan,kınanmış bir sabır değilki benimki baharı beklemiyeyim.ama sabahlar zor,sabahlar erken....', ARRAY['Türk Edebiyatı','Şiir','Mutluhan Kurt']::text[], 8.5, '{"poet":"Mutluhan Kurt","poet_slug":"mutluhan-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/bu-sehir-senin-yuzunu-kusanmis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fırat 7.', 'firat-7-sezer-odabasioglu-15vls', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'bu fırat var ya bu fırat

söylencesi çok

bilmeyeni çok

yükü çok hüznü çok

yangısı çok yankısı çok

boz bulanık suyu çok

toprağa olan sevdası çok

bu fırat var ya bu fırat

türkünün, ağıtın, göçün, sevginin,

                                        sazın ve sözün

ve aklıma gelmeyen çok şeyin

                                        adıdır bı fırat.

''Irmak Türküleri'' başlıklı şiir dosyasından.', 'bu fırat var ya bu fırat söylencesi çok bilmeyeni çok yükü çok hüznü çok yangısı çok yankısı çok boz bulanık suyu çok toprağa olan sevdası ç...', ARRAY['Türk Edebiyatı','Şiir','Sezer Odabaşıoğlu']::text[], 8.5, '{"poet":"Sezer Odabaşıoğlu","poet_slug":"sezer-odabasioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/firat-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yare Dua', 'yare-dua-meral-yagcioglu-ed5k9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Güle  güle  sevgili yarim

Yolun açık,

Yüreğin aşk ile 

Dopdolu olsun.

Tek bir gün bile ıslanmasın

Kederden gözlerin.

Yaşamın boyunca mutluluk

Her daim yoldaşın olsun.

Güle, güle sevgili yarim

Yüzün daima neşe ile

Aydınlansın.

Gözlerin ışık saçsın mutluluktan

Harelerden etrafına yayılsın

Dert ve hüzün senden uzakta

Çok uzakta dursun.

Sana asla vurmasın sillesini hayat.

Kaderin yalnızlık olmasın

Yalancı dostlar değil,

Gerçek can dostlar sarsın etrafını.

Güle, güle sevgili yarim

Gündüzleri güneşin hiç batmasın

Geceleri kaymasın yıldızın

Kararmasın dünyan.

Büyük yaradan daima seni

Kötülerden korusun.

Hep güzel haberlerin çalınsın kulağıma,

Sevdaların,başarıların nağme,nağme türkülerin

Her ne kadar kan ağlasa da yüreğim.

Yolun açık,bahtın aydın olsun

Güle  güle...', 'Güle  güle  sevgili yarim Yolun açık, Yüreğin aşk ile  Dopdolu olsun. Tek bir gün bile ıslanmasın Kederden gözlerin. Yaşamın boyunca mutlulu...', ARRAY['Türk Edebiyatı','Şiir','Meral Yağcıoğlu']::text[], 8.5, '{"poet":"Meral Yağcıoğlu","poet_slug":"meral-yagcioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/yare-dua-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karanlıktaki Güzellikler', 'karanliktaki-guzellikler-sezer-odabasioglu-miemr', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'hüzne ve tütüne

  alıştığımız gibi çabuk

    alışamadık bir türlü kendimize

unutuldu insan olduğumuz

hep çocuk kaldık gözünüzde

bu yüzden

  bir türlü alışamadı karanlığa gözlerimiz

oysa

hep karanlıkta kaşmıştı güzelliklerimiz

                                                     seçemedik.

''Senden Yana Büyür Çığlığım'' başlıklı şiir dosyasından.', 'hüzne ve tütüne   alıştığımız gibi çabuk     alışamadık bir türlü kendimize unutuldu insan olduğumuz hep çocuk kaldık gözünüzde bu yüzden   ...', ARRAY['Türk Edebiyatı','Şiir','Sezer Odabaşıoğlu']::text[], 8.5, '{"poet":"Sezer Odabaşıoğlu","poet_slug":"sezer-odabasioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/karanliktaki-guzellikler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Seviyorum', 'seni-seviyorum-huseyin-erdogan-hnszi', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'şu anda 

her yer zifiri karanlık İstanbul''da

sen bu sabah uyanınca 

benden tarafa bakıp da

henüz hiç tebessüm etmedin galiba

her gün böyle yapıp da

sakın beni zindanlara koyma

sensiz geçmiyor bir anım bile

yokluğunda çeksem de çile

ne olur bir gün çıkıp gel de yanıma

beni buralarda

ayazlarda bırakma

keşke aşkımı 

fısıldayabilsem kulağına

usulca geceler boyunca

şimdi beni iyi dinle

sana bir şey söylemek istiyorum

bunu kimseden gizleme

her gittiğin yerde

defalarca söyle herkese

seni seviyorum

hem de delicesine

                  04.01.2005', 'şu anda  her yer zifiri karanlık İstanbul''da sen bu sabah uyanınca  benden tarafa bakıp da henüz hiç tebessüm etmedin galiba her gün böyle y...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Erdoğan']::text[], 8.5, '{"poet":"Hüseyin Erdoğan","poet_slug":"huseyin-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/seni-seviyorum-231-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karanfil Kırmızısı', 'karanfil-kirmizisi-sezer-odabasioglu-c21m5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'yanardağ lavları sanki yüzümüzde

karanfil kırmızısı utançlarımız

yakıyor yüzümüzü

                       hem de içimizi

ıslak yağmurlu bir gecede

                dönerken evlerimize

                             salt el ele tutuştuk diye.

''Senden Yana Büyür Çığlığım'' başlıklı şiir dosyasından.', 'yanardağ lavları sanki yüzümüzde karanfil kırmızısı utançlarımız yakıyor yüzümüzü                        hem de içimizi ıslak yağmurlu bir g...', ARRAY['Türk Edebiyatı','Şiir','Sezer Odabaşıoğlu']::text[], 8.5, '{"poet":"Sezer Odabaşıoğlu","poet_slug":"sezer-odabasioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/karanfil-kirmizisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Serzenişin Ayrıştırılması...', 'serzenisin-ayristirilmasi-mehmet-asim-wu59q', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Betül''e

                                                                                                   

Dostum

Ayrıştırılmış bir savaşın 

En yoğun  yerindeyim

Her tarafım sur

Sanki kaleler ardı 

Bir sırdayım  da

kalakalmışım...

Kalabalıklar içerisindeyken

İçimdeki yanlızlığına ait

Serzenişlerim sana...

-Kanıyorum

-Kalbim bedenimi kaldıramıyor

Diyerek 

Karanlığıma gitmiştin

Oysa hep karanlıktan korkardım

Korkardın karanlıktan...

Katrana çekerken gece

Küfredip hayata

Bir hasır rahatsızlığında

Atmıştım kendimi

Uykuya.

Nice kabuslarınla

Karabasanlarımla

Eyvah etmeden sana 

Yaşayamıyorum...

Dostum

Ayrıştır artık ellerimi

Kelepçelerden

Bu savaşı

Kaybediyorum.', 'Betül''e                                                                                                     Dostum Ayrıştırılmış bir savaşın...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Asım']::text[], 8.5, '{"poet":"Mehmet Asım","poet_slug":"mehmet-asim","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/serzenisin-ayristirilmasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ulak Güne', 'ulak-gune-asim-ildiz-tnj0x', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ulanmış gün hasrete çok güzeller bağlar.

Geceye, güne değdikçe ki sevda ağlar.

Nazenin bir iple âna atılmış ağlar.

İple yanar inceden aşka bağlı yüzüm...', 'Ulanmış gün hasrete çok güzeller bağlar. Geceye, güne değdikçe ki sevda ağlar. Nazenin bir iple âna atılmış ağlar. İple yanar inceden aşka b...', ARRAY['Türk Edebiyatı','Şiir','Asım Ildız']::text[], 8.5, '{"poet":"Asım Ildız","poet_slug":"asim-ildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ulak-gune-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Diyorum ki', 'diyorum-ki-necmi-otcu-u4bjd', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Nazar değmiş sizlere 

Biliyorum ki

Kurşun gerek dökmeye

Peki

Neden duruyu yoruyorsunuz öyle

Kurşun askerlerinizi eritsenize', 'Nazar değmiş sizlere  Biliyorum ki Kurşun gerek dökmeye Peki Neden duruyu yoruyorsunuz öyle Kurşun askerlerinizi eritsenize...', ARRAY['Türk Edebiyatı','Şiir','Necmi Otçu']::text[], 8.5, '{"poet":"Necmi Otçu","poet_slug":"necmi-otcu","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/diyorum-ki-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüya', 'ruya-seher-gungor-n8ocx', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir GününDaha Sayfasını KapatırkenUykuyaDaldım.ÇokUzun Bir Yoldayım.Etrafım Ağaçlarla Çevrili Dar Ve Uzun Bir Yol Bu.Bu Yolda Kimsecikler Yok Birtek Ben Varım Mis Gibi Kokuyo Hertaraf.Yürüyorum Yürüyorum Yol Bitmiyo.Etrafımda Gördüklerimin Hepsi Birbirinin Aynısı.Sanki Hiç Kıpırdamamışım,Olduğum Yerde Duruyormuşum Gibi..Nefes Nefese Kalmışım.Öylede Yorulmuşum ki…Omuzlarımda Tonlarca Yük Varmış Gibi.Birparça Soluklanayım Derken Havanın Gittikçe Kararmakta Olduğunu Farkettim.Ne Geldiğim Yolu Görebiliyordum Artık,Ne de Varacağım Yeri…Galiba Kaybolmuştum O Ormanda..Bu Yorgunluğun İçinde Ömrümde Hiç Tatmadığım Duygular Var.Özlem,Hasret,Umut,Acı,Sevinç Ve Birçok Şey.. Tuhaf Hemde Çok Tuhaf Geldi Bana…Çöreklenmekte Olan Karanlığın Yanı Sıra Bir Fırtına Koptu.Gökyüzü Delinmişçesine Yağmur Başladı Birden..Sis Çöktü Göz Gözü Görmüyo…Kala Kaldım Oracıkta.İliklerime Kadar Islandığımı Farkettim.Üzerime De Doğru Dürüst Hiçbişey Almamışım.Yağmur Dağıttı Birden Sisleri.Aydınlandı Gözümün Önü..Son Sürat Yağmurla Beraber Koşmaya Başladım.Daldım Ormanın Derinliklerine..Kayboldum Birden Ağaçlar Üstüme,Üstüme Geliyo Sanki..En Nefes Alınabilecek Yerde Ben Boğulmak Üzereyim,Nefes Alamıyorum…Arada Bir Yanıp Sönen Işığın Dışında Her Yer Zifiri Karanlık.Koştum O Işığın Peşinden Korkmamak İçin Kapadım Gözümü..Sırılsıklam Olmuştu Her Bir Yanım…Nefes Nefese Kalmıştım.Hafiften Titremeye Başladım..O Ara Mis Kokulu Güllerin Arasına Daldım..Sanki Yol Gösterirmişçesine Dizilmişlerdi Ayaklarımın Dibine..Rengarenk Güller Kırmızısı,Sarısı,Pembesi Katmer Katmer Güller…O Koku,Hayatımda Hiç Tatmadığım Ah..O Koku. Buldum İşte.Tam Karşımda Duruyo Sığınabileceğim Ev,Gözlerimin Önünde…Açtım Yarı Kapalı Gözlerimi, Baktım Etrafıma..Yaklaştım Kapıya, Kalbimin Yerinden Fırlayacakmışçasına Atıttığını  Farkettim.Ne Kadar Aç,Ne Kadar Islanmış Olduğumu Ve De Korktuğumu…Son Sürat  Durmaksızın Tekrar Tekrar Usanmadım Çaldım Kapıyı…Açılmadı Kapı.Etrafında Dolandım Evin Her Bir Köşesine Kilitler Vurulmuş.Senelerdir Açılmamış Ve Pas Tutmuş Kilitler…Meğer Gördüğüm Işık Tepede Yanan Fenerin Işığıymış..Of…. Of….Dönemezdim De Artık Geriye.Gül Döşenmiş Yoldan O Kokuyu Tekrarİçime Çeke Çeke Bir Daha Hissedemeyecekmişçesine Kayboldum Karanlıklarda.İrkilerek Uyandım..Gördüğüm Kabusmuydu Yoksa Rüyamı Varamadım Farkına.Yanağımda Geceden Kalma Yağmur Tanesi Ve İçimde Karmakarışık Duygular …. 

İşte yeni bir gün daha başlıyor.Meğerse hepsi bir rüyadan ibaretmiş….', 'Bir GününDaha Sayfasını KapatırkenUykuyaDaldım.ÇokUzun Bir Yoldayım.Etrafım Ağaçlarla Çevrili Dar Ve Uzun Bir Yol Bu.Bu Yolda Kimsecikler Yo...', ARRAY['Türk Edebiyatı','Şiir','Seher Güngör']::text[], 8.5, '{"poet":"Seher Güngör","poet_slug":"seher-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/ruya-160-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '* AsLA BoŞa GeÇMeDi ZaMaN *', 'asla-bosa-gecmedi-zaman-mine-ozdemirtas-e8qrp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Onca fırın ekmek yemişlikle

yine de geri saymazken adımlarım

ne çıkar yani...? mevsimlerle ayların

hızına yetişemediyse kanatlarım.

Asla boşa geçmedi zaman......

Başkalarını ebe var sayardım./değilmiş..! 

kendime.... sobelerde yakalandım.

Belki...! kırık dökük aşkların

kara dulu olamadım

Belki...! içimde ki sarayların

sahibini bulamadım.

Ama...! 

Geçip giden yılların

bir de eskiyen yolların

alnından öpmem gerektiğini

anladım.

Az şey mi bu...? ben kârdayım...! 

04/01/2005.... çamlıca', 'Onca fırın ekmek yemişlikle yine de geri saymazken adımlarım ne çıkar yani...? mevsimlerle ayların hızına yetişemediyse kanatlarım. Asla boş...', ARRAY['Türk Edebiyatı','Şiir','Mine Özdemirtaş']::text[], 8.5, '{"poet":"Mine Özdemirtaş","poet_slug":"mine-ozdemirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/asla-bosa-gecmedi-zaman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayata Yakalanırım', 'hayata-yakalanirim-yunus-guzel-1b8az', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Penceremden bakarken uzaklara

Karışık hayallere dalarım

Kumrular konar pencereme

Birbiriyle oynaşırlar

Düşeceklerinden korkarım

Parktaki ağaçlara kayar gözlerim

Palmiyenin kahverengi ve yeşiline

Umutlarım canlanır birden

Kendimi gülümserken yakalarım

Sersem bulutlar rotasız geçer önümden 	

Serin bir rüzgar saçlarımla oynaşır

Güneşin akşam kızıllığı,

Karşı camda şavkılar...

Uzak göklerde şimşek çakar aniden,

Penceremde olduğumu anımsarım

Hayata yakalanırım yeniden

Ve hayat,

Kaldığı yerden devam eder...', 'Penceremden bakarken uzaklara Karışık hayallere dalarım Kumrular konar pencereme Birbiriyle oynaşırlar Düşeceklerinden korkarım Parktaki ağa...', ARRAY['Türk Edebiyatı','Şiir','Yunus Güzel']::text[], 8.5, '{"poet":"Yunus Güzel","poet_slug":"yunus-guzel","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/hayata-yakalanirim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Savruluyor Hüzünlü Dizeler', 'savruluyor-huzunlu-dizeler-sevtap-ozkahraman-qu5vm', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Son kapıyı da açtık,

Pusudaki ayrılmak korkusuna

Ki hep oradaydı! 

Yabancı..

Yıkıcı..

Yalnız kılan düşler gibi

Senden bana doğan..

Oysa,

Sana batıyorum biraz daha

Ayrılığa attığım her adımda! 

Şiirler de koruyamıyor beni

Ki

İnsafsızca

Kavuruyor..

Savuruyor..

Savruluyor hüzünlü dizeler..

Ve 

İsyankarlığım! 

Vicdanım! 

Herşeyi sevebilsem diyor

Yeniden eksiksiz...

Yani sensiz...

Sessiz...

Kimsesiz...

(03/01/2005 Ankara)', 'Son kapıyı da açtık, Pusudaki ayrılmak korkusuna Ki hep oradaydı!  Yabancı.. Yıkıcı.. Yalnız kılan düşler gibi Senden bana doğan.. Oysa, San...', ARRAY['Türk Edebiyatı','Şiir','Sevtap Özkahraman']::text[], 8.5, '{"poet":"Sevtap Özkahraman","poet_slug":"sevtap-ozkahraman","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/savruluyor-huzunlu-dizeler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hesaplaşma', 'hesaplasma-ahmet-kaytanci-e34bu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Masallar yazdık birlik üstüne

Şiirler okuduk, türküler söyledik

Aldırmadık meşin kırbaç darbelerine

Demir kazıklar üstünde

Ninniler dinledik

Ninniler söyledik, doğmamış bebelere

Ağıtlar söyledik soğumamış bedenlere

Sevinmedik gelenlere,

Üzülmedik gidenlere.

Kaderin her türlüsüne boyun eğdik

Harman yerine dökülen buğday tanelerini

Sadaka diye kuşlara verdik

Aldılar gönlümüzden ülkü tomurcuklarını

“Mekanı cennettir” dedik

Üzülmedik.

Kaçtık köşe-bucak şeytan sürülerinden

Karanlıkta bıraktık göz yaşlarımızı 

Kimseler görmesin diye içimize gömdük

Matem yüklü düşlerimizi.

Ana kucağından üstün bildik ocağımızı

Başımıza geçenlere “baş” dedik

Kadeh kaldırdılar şehitler üstüne

“Belki cayarlar” diye sustuk

Ne susması gözüm kardeşim

Küfürler doldu ağzımıza zehir –zemberek

Düşmanlar görmesin diye

İçimize kustuk.

Sır  verdik eli kanlı katillere

Kutsal selamlarla karşıladık meydanlarda

Düşmanı dost tuttuk

Fikir üreten gönül erlerine; 

“Haindir, kahpedir, dönektir” diye

Damgalar vurduk.

Ucuza verdik gönül erlerini

Bir eylül sabahında

Güneş karanlığı kovmadan

Pehlivanlar ipe çekildi

Yağlı urganlar sıktı boğazımızı

“Gık” demedik

Özümüz  gömülü kaldı 

Toprağın bir kulaç altında

Canlar can pazarında canını verdi

Vatan sevdasıyla yanan gönül erleri

Vatansız kaldı

Toprağa düştü taze bedenler

Kimini kara toprak,

Kimini taş medrese aldı.

Sonra? 

Sonrası yok ki gülüm

Bir eylül sabahında umutlar söndü

Dağıldı ocaklar, virana döndü

Harman yerine döktüğümüz taneler

Filiz verir diye beklerim

Bekledikçe sorgularım kendimi

Hesaba çekerim nefsimi

Her gece hayal kurarım birlik üstüne

Kim duyar beni, bilmem ki gülüm

Ben her sabah doğar,

Her akşam ölürüm.

İçimizdeki Ses sayfa:96-97', 'Masallar yazdık birlik üstüne Şiirler okuduk, türküler söyledik Aldırmadık meşin kırbaç darbelerine Demir kazıklar üstünde Ninniler dinledik...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Kaytancı']::text[], 8.5, '{"poet":"Ahmet Kaytancı","poet_slug":"ahmet-kaytanci","theme":"Türk Şiiri","is_hero":false,"total_lines":60,"source_url":"https://www.antoloji.com/hesaplasma-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yediğim Her Lokma', 'yedigim-her-lokma-ahmet-kaytanci-gchej', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ben Toros Dağlarının eteklerinde doğdum

Sultani kirazların olduğu yerde

Karnı aç,başı dik insanların

Kartal bakışlarında tanıdım

Memleket sevdasını.

Yağız delikanlılar türkü söylerlerdi

Yıldıza-aya

Bir name çıkardı suların aktığı yerden

Mehteri andırırdı,gümbür gümbür

Tempo tutardık suların sesine

Ulubatlı Hasan olurduk

Yırtardık dağları

Titretirdik kayaları

Erkekçesine.

Ben yalçın kayalarda öğrendim

Toprağın kıymetini

Başı boş deli çayların yularsız sularında

Bir karış toprak için dökülen alın terlerini

Nasırlı ellerin sertliğinde

Gariban insanların mertliğinde tanıdım.

Ben ondan sevdalıyım

Toprakların en kıracına

Ondan severim suların delice aktığı yeri

Yediğim  her lokma ekmekte

Anamın nasırlı elleri,

Babamın alın teri.

İçimizdeki Ses- Sayfa:98', 'Ben Toros Dağlarının eteklerinde doğdum Sultani kirazların olduğu yerde Karnı aç,başı dik insanların Kartal bakışlarında tanıdım Memleket se...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Kaytancı']::text[], 8.5, '{"poet":"Ahmet Kaytancı","poet_slug":"ahmet-kaytanci","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/yedigim-her-lokma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dilimin altındakini yutsam', 'dilimin-altindakini-yutsam-necmi-otcu-fj651', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İçime sığmaz

Çıkartsam yaşatmazlar

Dilimin ucuyla dokunuyorum yaşatılmazlığa 

Tozutuyorum

İki gözü iki çeşme gülüyoruz 

Toz duman içinde', 'İçime sığmaz Çıkartsam yaşatmazlar Dilimin ucuyla dokunuyorum yaşatılmazlığa  Tozutuyorum İki gözü iki çeşme gülüyoruz  Toz duman içinde...', ARRAY['Türk Edebiyatı','Şiir','Necmi Otçu']::text[], 8.5, '{"poet":"Necmi Otçu","poet_slug":"necmi-otcu","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/dilimin-altindakini-yutsam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anında ömür yaşıyorum', 'aninda-omur-yasiyorum-necmi-otcu-xyvjw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kara kalem çizilmiş

Gri zenginliğinde 

Yorgun eğriler serpintisinde 

Eğilmez başım düşüyor

Yumruğumun üstüne

Siyah bir damar yaşıyor

Gök mavisinde

San bezmiş san yılgın

Kanı kanım akar

Yürekte şarap lekesi

Her kendinde duruş

Yaşarken içimde

Durduğum yerler duramıyor

Kendinde

Anım anın oluyor

Duru-yorum

Dünyalarım oynuyor yerinden

Toz duman içinde

Yekpare kalıyorum kendimde

Durduğu yerde duramıyor hiçbir şey

Dünyanın bütün telaşı içimde', 'Kara kalem çizilmiş Gri zenginliğinde  Yorgun eğriler serpintisinde  Eğilmez başım düşüyor Yumruğumun üstüne Siyah bir damar yaşıyor Gök mav...', ARRAY['Türk Edebiyatı','Şiir','Necmi Otçu']::text[], 8.5, '{"poet":"Necmi Otçu","poet_slug":"necmi-otcu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/aninda-omur-yasiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arı', 'ari-bayram-tunca-qwlbf', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ağzında hayat mucizesi

Kuyruğunda mıhlı iğnesi

Düşün bu hal neyin nesi

Hayrete düşürür herkesi

03.01.2005-13:01', 'Ağzında hayat mucizesi Kuyruğunda mıhlı iğnesi Düşün bu hal neyin nesi Hayrete düşürür herkesi 03.01.2005-13:01...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/ari-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çağrısız çoğalıyorum', 'cagrisiz-cogaliyorum-necmi-otcu-xdalo', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Işığı sönüyor sigaramın

Düşüyorum kül tablasına

İtfaiyeciler pür telaş 

Yanlış ihbar diyorum

Anlamıyorlar külümle oynadığımı

Islak bir ıslık dudaklarımda

Sular basıyor kenti

Kağıt kayıklar yapıyorum kendimle

Çağrılı çağrısız

Gelmeler gitmeler içinde

Azalarak çoğalarak

Yaşıyor umut

Direngen bir eğrilik içinde', 'Işığı sönüyor sigaramın Düşüyorum kül tablasına İtfaiyeciler pür telaş  Yanlış ihbar diyorum Anlamıyorlar külümle oynadığımı Islak bir ıslık...', ARRAY['Türk Edebiyatı','Şiir','Necmi Otçu']::text[], 8.5, '{"poet":"Necmi Otçu","poet_slug":"necmi-otcu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/cagrisiz-cogaliyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sarı Papatya...', 'sari-papatya-i-brahim-ethem-bingul-y00xi', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Papatyaları özledim

Tabi mevsimi gelecek

Keyfi olacak

Açacak

Asil asil salınacak

Koklarken

İçim açılacak

Ve o etrafa neşe saçacak

Hayal bu ya

Şimdi mevsim kış ya

İnadına

Papatyaları özledim...

Sarı sarı papatyaları

Özledim sarı papatyamı

Ya illâ sarı mı olmalı papatyam

İllâ sarı

Onda gizemin demi saklı...

www.iebingul.com', 'Papatyaları özledim Tabi mevsimi gelecek Keyfi olacak Açacak Asil asil salınacak Koklarken İçim açılacak Ve o etrafa neşe saçacak Hayal bu y...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sari-papatya-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir güzel gün', 'bir-guzel-gun-necmi-otcu-bsfkg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kesilmişim gökyüzüne

Şafak inkardan gelse de

Karanfil kuruyan günlerde 

Koleksiyon oluyor ömrüm

Bir kelebek bir toplu iğne

Bir kelebek bir toplu iğne

Kozalı günler

Kelebek olur konar çiçeğe

Tamda yaşayacakken bir ince

Nereden çıktı bu toplu iğne

Hergün binlerce kelebek

Konuyorum ömrünüze

Siz gülüp oynuyorsunuz

Yüreğimde toplu iğne', 'Kesilmişim gökyüzüne Şafak inkardan gelse de Karanfil kuruyan günlerde  Koleksiyon oluyor ömrüm Bir kelebek bir toplu iğne Bir kelebek bir t...', ARRAY['Türk Edebiyatı','Şiir','Necmi Otçu']::text[], 8.5, '{"poet":"Necmi Otçu","poet_slug":"necmi-otcu","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/bir-guzel-gun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hani Şifam Olacaktın', 'hani-sifam-olacaktin-murat-demir-u80uv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hani sen dertlerimin 

Şifası olacaktın

Hani sen yüreğime

Gül olup dolacaktın

Ya şimdi sen nerdesin

Ne oldu sözlerine

Koysaydım ölür muydun

Başımı dizlerine

Ya şimdi sen nerdesin

Ne oldu sözlerine

Sen, dökülmek için mi

Dolmuştun gözlerime

Hani sen bu dünyada

Bir beni sevecektin

Hani benimle yanıp

Benimle gülecektin

Ya şimdi sen nerdesin

Ne oldu dünlerine

Hiç mi acımıyorsun

Benim bugünlerime

Ya şimdi sen nerdesin

Ne oldu güllerine

Yoksa sende mi düştün

Hasretin  ellerine!', 'Hani sen dertlerimin  Şifası olacaktın Hani sen yüreğime Gül olup dolacaktın Ya şimdi sen nerdesin Ne oldu sözlerine Koysaydım ölür muydun B...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/hani-sifam-olacaktin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gökyüzü başında kep', 'gokyuzu-basinda-kep-necmi-otcu-96v2z', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Toprak ayağında postal

Yarısı yenmiş

Yarısı çürük

Kalmışken böyle

İki dirhem bir çekirdek

Yaşayıp ta ne olacak deme

Neler olmaz ki 

İlahi çekirdek', 'Toprak ayağında postal Yarısı yenmiş Yarısı çürük Kalmışken böyle İki dirhem bir çekirdek Yaşayıp ta ne olacak deme Neler olmaz ki  İlahi çe...', ARRAY['Türk Edebiyatı','Şiir','Necmi Otçu']::text[], 8.5, '{"poet":"Necmi Otçu","poet_slug":"necmi-otcu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/gokyuzu-basinda-kep-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Soğuk Günlerdeyiz', 'soguk-gunlerdeyiz-oguzkan-bolukbasi-b2frz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Soğuk günlerdeyiz

Kendime bir kanat yaptım

Bir yerlere uçmak gerekir diye

Sıcaklara

Uzaklara

Uzaklar vatan içinde kalmalı

Uzak bir yerde

Sıcak bir yerde

Ama vatanımda

Sesim yanı başımda

İnsanım

O sıcak dokunuşta

Her şey kötüleşse bile

Bir yerlerde

Kırıntı halinde de olsa

Güzellikler kalmıştır

Eminim

Soğuk günlerdeyiz

Paylaşmak lazım soğuğu

Bir çorba pişse

Kokusunu değil tencereyi bölüşmeliyiz

Nasıl anlamazsın o çocuğu

Güzel gözlerindeki umutsuzluğu

Güzel gözlerindeki umudu

Var olmanın

Bazen delice sorumsuzluğu

Bazen inanılmaz sorumluluğu

Yüreğine sapladığın bıçağı çıkarmana yardımcı olacaktır

Benim vatanımda insanlar

Bana anlatıldığı gibi olacaktır

Yoksa 

Çocukluğumda ne varsa

Yalan olacaktır

Sevgili öğretmenim

Anam

Babam

Komşu kadınlar

Amcalar

Teyzeler

“o güzel insanlar

o güzel atlara binip”

Gitmediler deyin bana

Soğuk günlerdeyiz

Kendime bir kanat yaptım

Bir yerlere uçmak gerekir diye

Sıcaklara

Uzaklara', 'Soğuk günlerdeyiz Kendime bir kanat yaptım Bir yerlere uçmak gerekir diye Sıcaklara Uzaklara Uzaklar vatan içinde kalmalı Uzak bir yerde Sıc...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/soguk-gunlerdeyiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmurun Düşü', 'yagmurun-dusu-mehmet-erdogdu-vwkc9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ne var bunda? 

Boşluğa asıp hüznümü

Ölümcül yalnızlıklarıma

Sensizliği giydiriyorum

Bir yağmur taneciğinde

Yetim bir

              yağmur taneciğinde.

Sesini rüzgar yapıp

Kırık kanatlı serçeye

İstanbulu seyrettiriyorum

Denizi,

          ıslak gökyüzünü,

Ankara kimsesizliğimi

Kızılay''da kendiyle konusan

tu-tar-sız-lı-ğı-mı

Hem sana ne ki? 

Bu benim düşüm

Bu benim düşüşüm

Tutamam mı sandın yoksa? 

Ellerin gibi

Rüzgarı.

Bak ben 

Yağmur taneciğiyim şimdi

Bir başıma yağıyorum

Denizin üstüne

Korkma heme

Bu ilk intihar teşebbüsüm değil

Çok kez düştüm

Demli sıcak çayların içine

                                    -sensiz dost meclislerinde-

Gözlerini ararken bir de

Islak çimenlerin üstünde.

Bilmezsin! 

İlk şarabı tattığımda dudaklarından,

Sen sürgünlüğümün rahminde

Yeni filiz veriyordun

Yarınsızlığıma.

Sen merak etme beni

Ağzımda kekremsi tadıyla dudaklarının

Hayallerimi çizerim gene

Gecelere.

Özlediğim İstanbul gibi

İstanbul sevdiğim

Sen üzülme,

Şizüfren gecelerimde

seni düşünüp

Çıkarım gene sabaha

Biraz yarım,

Biraz kırık da olsa....', 'Ne var bunda?  Boşluğa asıp hüznümü Ölümcül yalnızlıklarıma Sensizliği giydiriyorum Bir yağmur taneciğinde Yetim bir               yağmur ta...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Erdoğdu']::text[], 8.5, '{"poet":"Mehmet Erdoğdu","poet_slug":"mehmet-erdogdu","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/yagmurun-dusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küçücük sanal bir sandık', 'kucucuk-sanal-bir-sandik-necmi-otcu-3ku92', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sığmazlık sınanıyor sırrında

Gelişi yorumsuz

Duru-yorum

İçine sığıyor dünya

Şiir diyorlar

Birkaç satırda ki sonsuzluğa 

Ben seni yoğuruyor 

Giz yapıyor içinde

Islanıyor yağmur

Şarap sarhoş oluyor

Kayboluyorum içinde

Ellerim terliyor gök yüzünden

Dünya biz ıslanıyor

Alışıyorum yaşamaya', 'Sığmazlık sınanıyor sırrında Gelişi yorumsuz Duru-yorum İçine sığıyor dünya Şiir diyorlar Birkaç satırda ki sonsuzluğa  Ben seni yoğuruyor  ...', ARRAY['Türk Edebiyatı','Şiir','Necmi Otçu']::text[], 8.5, '{"poet":"Necmi Otçu","poet_slug":"necmi-otcu","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/kucucuk-sanal-bir-sandik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kim Ölçer', 'kim-olcer-mustafa-kahramanoglu-rkh0k', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Zaman yürür.

Zamanın adımlarını,

Ölçer saatler.

Akrep yürür,

Yelkovan yürür.

Saatin direncini,

Ölçer zamanlar.', 'Zaman yürür. Zamanın adımlarını, Ölçer saatler. Akrep yürür, Yelkovan yürür. Saatin direncini, Ölçer zamanlar....', ARRAY['Türk Edebiyatı','Şiir','Mustafa Kahramanoğlu']::text[], 8.5, '{"poet":"Mustafa Kahramanoğlu","poet_slug":"mustafa-kahramanoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/kim-olcer-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neydi', 'neydi-bunyamin-dizlek-6wrk0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hiç miydi neydi

kumral denizlerde korkunç güzel balıklar

sesi uzaklara giden büyük dalga

hiç miydi neydi

Bir şiir elbette mavi olabilir

bütün gece bir kadın düşünülebilir

belki de sarhoşluk kafanı masada bırakabilir

ama hiçmiydi neydi

incecik sesi beyaz bir yelkeni negüzel şişiriyordu', 'Hiç miydi neydi kumral denizlerde korkunç güzel balıklar sesi uzaklara giden büyük dalga hiç miydi neydi Bir şiir elbette mavi olabilir bütü...', ARRAY['Türk Edebiyatı','Şiir','Bünyamin Dizlek']::text[], 8.5, '{"poet":"Bünyamin Dizlek","poet_slug":"bunyamin-dizlek","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/neydi-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Bana Baktı', 'o-bana-bakti-sair-astor-is4qt', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'O bana baktı, ben ona

Sonra ben ona, o bana

En güzel deniz manzarası

Bizim için yaratılmıştı sanki

Sonra ben ona, o bana baktı

Bakıştık iki sözcüğü söylemeden

Öylece saatlerce ve günlerce.', 'O bana baktı, ben ona Sonra ben ona, o bana En güzel deniz manzarası Bizim için yaratılmıştı sanki Sonra ben ona, o bana baktı Bakıştık iki ...', ARRAY['Türk Edebiyatı','Şiir','Şair Astor']::text[], 8.5, '{"poet":"Şair Astor","poet_slug":"sair-astor","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/o-bana-bakti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canımdan Çok Severim!', 'canimdan-cok-severim-ramazan-ece-31msk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sabah oldu kar yağdı

Gözüm taze açıldı

Birkaç günün içinde

Hak nurunu kazandı! 

Ey Resul, tek önderim

Sensin benim rehberim

Hayatta ben kaldıkça

Canımdan çok severim! 

Sabah oldu kalkıyor

Gerçekleri arıyor

Kara gurbet elinde

Emr-i mâruf yapıyor! 

Ey Resul, tek önderim

Sensin benim rehberim

Hayatta ben kaldıkça

Canımdan çok severim! 

Gârip Kurân okuyor

Göz yaşları döküyor

Sünnete sarılıyor

Gerçek huzur buluyor! 

Ey Resul, tek önderim

Sensin benim rehberim

Hayatta ben kaldıkça

Canımdan çok severim! 

Ramazan   Ece  Danimarka/Odense', 'Sabah oldu kar yağdı Gözüm taze açıldı Birkaç günün içinde Hak nurunu kazandı!  Ey Resul, tek önderim Sensin benim rehberim Hayatta ben kald...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Ece']::text[], 8.5, '{"poet":"Ramazan Ece","poet_slug":"ramazan-ece","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/canimdan-cok-severim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İyi Çocuktur İlhâmi', 'i-yi-cocuktur-i-lh-mi-ramazan-ece-953m7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İyi çocuktur İlhâmi

Derse gelir çok samimi

Sevindirir şu kalbimi

İyi çocuktur İlhâmi! 

Kurânını güzel okur

Kalbini imanla korur

Ancak böyle mutlu olur

İyi çocuktur İlhâmi! 

Allah’ın emrine bakar

Resulün sözüne uyar

Her yerde islâmca yaşar

İyi çocuktur İlhâmi! 

Anne babasını sever

Onlara itaat eder

Büyüklere hürmet eder

İyi çocuktur İlhâmi! 

Câhiller gibi değildir

O biricik mücahittir

İslâm için fedâidir

İyi çocuktur İlhâmi! 

Hocasıdır Ece garip

Yetiştirdi onu garip

Bu evsafa oldu sahip

İyi çocuktur İlhâmi! 

Çok söylerim dileğimi

Ya Rab koru şu kalbimi

Hakta sâbit kıl İlhâmi

İyi çocuktur İlhâmi! 

Ramazan   Ece Danimarka/Odense', 'İyi çocuktur İlhâmi Derse gelir çok samimi Sevindirir şu kalbimi İyi çocuktur İlhâmi!  Kurânını güzel okur Kalbini imanla korur Ancak böyle ...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Ece']::text[], 8.5, '{"poet":"Ramazan Ece","poet_slug":"ramazan-ece","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/iyi-cocuktur-ilhami-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşlerim Kan Kırmızı', 'duslerim-kan-kirmizi-muharrem-ozturk-tpxyv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Siz hiç kurşun deliğinden baktınız mı içeri? 

Kan gördünüz mü hiç,damardan sızan? 

Ya da hayalleriniz kan kesti mi? 

Ölümün soğuk yüzüne bakarken uzaktan,

Korkuyu hissettiniz mi? 

Kan kırmızı düşlerim yine,

Kimi zaman bir bomba düşüyor önüme,

Aldırmıyorum bile.

Kanıksamışım,Kim bilir? 

Yada ölmeyi istiyorum belki de.

Kimi zaman Kardeşim,

Kimi zaman babam ölüyor gözümde.

Ve kan büyüyor hızla,

Gözbebeklerimde.

Yarınları nasıl Yaşarım? 

Bilmiyorum.

Ve artık “Yeter” deyip,

Ölmek İstiyorum.

03.01.2005', 'Siz hiç kurşun deliğinden baktınız mı içeri?  Kan gördünüz mü hiç,damardan sızan?  Ya da hayalleriniz kan kesti mi?  Ölümün soğuk yüzüne bak...', ARRAY['Türk Edebiyatı','Şiir','Muharrem Öztürk']::text[], 8.5, '{"poet":"Muharrem Öztürk","poet_slug":"muharrem-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/duslerim-kan-kirmizi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Hasan’ dan Mektup / 5 (İsyân ve Aşk)', 'hasan-dan-mektup-5-i-sy-n-ve-ask-ahmet-turan-altunsu-zzuxv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '(Hasan karındaşım yine sözü almış; dolmuş, boşalmış! .. / Kolay değil: Bitlis, Ağrı, Bingöl, Muş… / Geze geze yorulmuş! .. / Bir de Ankara’ nın puslu havasını duyunca ajanslardan; yıkılmış kalmış! ..)    

Doğuyu kar sarmış, sarmalamış dost,

Ankara’ da nasıl şimdi havalar? ..

Birileri yine zırvalamış dost; 

Hedefini bulmuyor mu dualar? ..

Saflar bir bir buluyormuş yerini,

Bilmezler mi ülkemin değerini? 

İhanetin soluyan ciğerini

Parçalayıp almıyor mu dualar? ..

Sevenlere saygı bizden; deyiver! 

Duysun dostlar, seslice ünleyiver.

Kanını ver, geleceği, soyu ver; 

Semâdan duyulmuyor mu dualar? ..

Ya senin aşk öyküne ne demeli? 

-Yari başka, yurdu başka sevmeli! -

Yurt giderse namus olmaz, bilmeli; 

Havuzuna dolmuyor mu dualar? ..

Hasan der ki yurt yok ise yâr da yok,

Bir ışık yok, kıvılcım yok, har da yok,

Esaret zül sayılmıyor: ar da yok; 

Akıllarda kalmıyor mu dualar? ..

                       03.01.2005 / Muş', '(Hasan karındaşım yine sözü almış; dolmuş, boşalmış! .. / Kolay değil: Bitlis, Ağrı, Bingöl, Muş… / Geze geze yorulmuş! .. / Bir de Ankara’ ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Turan Altunsu']::text[], 8.5, '{"poet":"Ahmet Turan Altunsu","poet_slug":"ahmet-turan-altunsu","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/hasan-dan-mektup-5-isyan-ve-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşe sayılmışız bir kez', 'duse-sayilmisiz-bir-kez-necmi-otcu-pnjda', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'içimden geçip gidiyorsunuz

Ben sahiciyim dedikçe

Başımda aşkın işler 

Benzemezliklerimle bezeniyorum

Bilmedik çiçekler açıyor içimde

Ben karanfil diyorum

Saklambaç körebe

Benim yüreğim oyun çocuğu

Usulca alışıyorum 

Elim kalıyor sizde

Sıkıştım kitapların kıvrımına

Altı çizilen satırlarda

Çiziliyor üstü şaşkınlığımın

Düşü-yorum kolay iç çekmelerinize

Tutuşu- yorum ateşler içinde

Ne büyük katliamdı bilemezsiniz

Bir gün parantez açacağım

Usulca alıştım deyişime', 'içimden geçip gidiyorsunuz Ben sahiciyim dedikçe Başımda aşkın işler  Benzemezliklerimle bezeniyorum Bilmedik çiçekler açıyor içimde Ben kar...', ARRAY['Türk Edebiyatı','Şiir','Necmi Otçu']::text[], 8.5, '{"poet":"Necmi Otçu","poet_slug":"necmi-otcu","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/duse-sayilmisiz-bir-kez-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anla', 'anla-ahmet-turan-altunsu-3zxk9', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Seni çok seviyorum, duysana beni kadın! ..

Bunca çırpındım durdum anlatmak için sana,

Ağzımla kuş tuttum da yine anlayamadın; 

Şu derbeder halime bakıp da anlasana! ..

Şarkılara söz olur bu dizeler gün gelir,

Dillerde nağme olup asumana yükselir,

Sevginin kıymetini ancak sevenler bilir; 

Bir zerre kulak verip sözümü dinlesene! ..

                                     03.01.2005 / Ankara', 'Seni çok seviyorum, duysana beni kadın! .. Bunca çırpındım durdum anlatmak için sana, Ağzımla kuş tuttum da yine anlayamadın;  Şu derbeder h...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Turan Altunsu']::text[], 8.5, '{"poet":"Ahmet Turan Altunsu","poet_slug":"ahmet-turan-altunsu","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/anla-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gibi...', 'gibi-ferit-teksoy-rdwel', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yoz olmak bilmedik,toz etti devir

Yokuşa razıydık,düz etti devir

Yanalım isterken buz etti devir

Kesildik kurumuş kızıl çam gibi

Masal dinleyerek geçti ömrümüz

Kuşa benzetilmiş leylek gönlümüz

Kısıldı sesimiz,geçmez sözümüz 

Dağıttı fırtına,esti sam gibi

Her yüze güleni dostumuz bildik

Adama benzettik muhabbet umduk

Dolu sanılanı içi boş bulduk

Unuttuk gülmeyi,kalan gam gibi

Anlaşılmak için anlamı seçtik

Bu uğurda yollar,engeller geçtik

Ektiğimiz değil,biteni biçtik

Eledik,kalanlar kuşa yem gibi

Ufukta vuslatı görmez gözümüz

Bağırsak yerine varmaz sözümüz

Bitti direncimiz,yorgun özümüz

Kırıldı kalbimiz tıpkı cam gibi

04 Ocak 2005', 'Yoz olmak bilmedik,toz etti devir Yokuşa razıydık,düz etti devir Yanalım isterken buz etti devir Kesildik kurumuş kızıl çam gibi Masal dinle...', ARRAY['Türk Edebiyatı','Şiir','Ferit Teksoy']::text[], 8.5, '{"poet":"Ferit Teksoy","poet_slug":"ferit-teksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/gibi-32-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şaşırdım Kaldım', 'sasirdim-kaldim-suheyl-turkoglu-m9jmh', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hayırdır inşallah,

Bu yaştan sonra,

Aklıma düştü,

Sevda.

Isındım,

İçimdeki gençle,

Baktım,

Eski yıllara.

Hakkım yok,

Yaşlandım ya,

İltifat edemem,

Bıçkınlıklara.

Eskimemiş,

İçimdeki arzular,

Son durağa,

Beş kala.

Korkuyorum,

Madara,

Olmak ta var,

İşin ucunda.

Allah korusun,

Bir duyulursa,

Sakız olurum,

Elin adamına.', 'Hayırdır inşallah, Bu yaştan sonra, Aklıma düştü, Sevda. Isındım, İçimdeki gençle, Baktım, Eski yıllara. Hakkım yok, Yaşlandım ya, İltifat e...', ARRAY['Türk Edebiyatı','Şiir','Süheyl Türkoğlu']::text[], 8.5, '{"poet":"Süheyl Türkoğlu","poet_slug":"suheyl-turkoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sasirdim-kaldim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yenik Düşürme Beni', 'yenik-dusurme-beni-huseyin-erdogan-pv8al', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'günlerden beri nerdesin? 

sen nerelerdesin? 

iyi ki gündüzleri hayallerimde

geceleri de düşlerimdesin

yoksa sensizlik çıldırtırdı beni

her gün adın dilimde

gözlerim caddede

bekliyorum seni

belki çıkıp gelirsin diye

ne sen geldin

ne de senin haberin

ben de ne varsa

topladım gök yüzünden

hiç olmazsa her gece

sen çıkarsın diye semaya

yıldızlar yerine

haydi gülümse bana

uzaktan da olsa 

ışılda geceler boyunca

bir mum gibi olsa da

ne olursun

yenik düşürme beni

karabasana

            04.01.2005', 'günlerden beri nerdesin?  sen nerelerdesin?  iyi ki gündüzleri hayallerimde geceleri de düşlerimdesin yoksa sensizlik çıldırtırdı beni her g...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Erdoğan']::text[], 8.5, '{"poet":"Hüseyin Erdoğan","poet_slug":"huseyin-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/yenik-dusurme-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dönülmez Yol Atlıları', 'donulmez-yol-atlilari-zulfikar-yapar-kaleli-4kxfo', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'font face=''Comic Sans MS'' color=''black'' size=''0,5''

Tüm ışıklar söndü güneş karardı 

Uzattılar arkam tahta önüm yar 

Yola revan oldum gelmiyor ardı 

Yollar uzun zaman kısa geçit dar 

Yıldıza dayalı merdiven burda 

Ahirete göç başladı art arda 

Ah şu adaletsiz haksız diyarda 

Bir ana oturmuş ellerin ovar 

Kıyarım geceye el vermez arım 

Yıldızı çengelle yere sarkarım 

Eller boş göz yılgın dizden korkarım 

Yar bizi başından düşüne kovar 

Destursuz ordular otağsız hakan 

Yetkisiz mahkeme etkisiz bakan 

Yar başında yazma yar başında kan 

Ülkülerim beni başından savar 

Sevda gelin olur şölensiz yuğsuz 

Yıldız aya bağlı zincirsiz bağsız 

Yüksekten seslenir kumandan tuğsuz 

Yüreklerde ezilmişlik hırsı var', 'font face=''Comic Sans MS'' color=''black'' size=''0,5'' Tüm ışıklar söndü güneş karardı  Uzattılar arkam tahta önüm yar  Yola revan oldum gelmiyo...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/donulmez-yol-atlilari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nisan Mayıs Ayları', 'nisan-mayis-aylari-suheyl-turkoglu-tclzj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sabırsızlıkla beklerdik,

Nisan, mayıs aylarını.

Yeşile nakış atan,

Kızıl gelincikler,

Etrafı saran,

Fal papatyaları.

Tespih gibi,

İpe dizdiğimiz,

Cebimizde taşıdığımız,

Kokusuyla mayıştığımız,

Portakal çiçekleri.

Çok başkaydı,

Eski baharlar.

Uzayan dersler,

Bitiminde,

Tenefüs aşkları.

Şiir yazdığımız,

İçimizi ısıtan,

Kaçamak bakışlar.

Sarhoşluğa dönüşen,

Bahar yorgunluğu.

Sevdayı yaşadığımız,

Rüyasına yattığımız,

Aşklar ne güzeldi.

Kıyamet kopsa

Umursamazdık,

Aklımıza bile gelmezdi,

O anı yaşardık,

Ama çok güzeldi.

Kalp çizerdik,

Ya da oyardık,

Ağaç gövdelerine,

Cebimizdeki çakıyla,

Birde ortasına,

Ok saplayarak,

Yarısına kendimizin,

Diğerine sevdiğimizin,

Baş harflerini yazardık.

Böyle anlatırdık,

Sevdiğimizi.

Ne güzeldi hayat,

O yaşlarda.

Romantik tutkular,

Okul bahçesinden taşan,

Platonik aşklar,

Hayata,

Pembe bakışlar,

Ucuz yiğitlenip,

Yorgan yakışlar,

Geleceğe,

Tertemiz,

Kabadayı bakışlar,

Hayalde şekillenen,

Dokunuşlar,

Bu yaşta,

Yaşayamayacağımız,

Mutluluklar.

Ne güzeldi,

Nisan, mayıs ayları.', 'Sabırsızlıkla beklerdik, Nisan, mayıs aylarını. Yeşile nakış atan, Kızıl gelincikler, Etrafı saran, Fal papatyaları. Tespih gibi, İpe dizdiğ...', ARRAY['Türk Edebiyatı','Şiir','Süheyl Türkoğlu']::text[], 8.5, '{"poet":"Süheyl Türkoğlu","poet_slug":"suheyl-turkoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":59,"source_url":"https://www.antoloji.com/nisan-mayis-aylari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz hayat', 'sensiz-hayat-ferit-ozcan-g8ida', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'sensiz günler geçmek bilmiyor

seni arıyorum diyar diyar

sensiz hayat geçmiyor be güzelim

sana hasret, sana deli bu gönül

seni arıyorum diyar diyar', 'sensiz günler geçmek bilmiyor seni arıyorum diyar diyar sensiz hayat geçmiyor be güzelim sana hasret, sana deli bu gönül seni arıyorum diyar...', ARRAY['Türk Edebiyatı','Şiir','Ferit Özcan']::text[], 8.5, '{"poet":"Ferit Özcan","poet_slug":"ferit-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/sensiz-hayat-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutuması gereken bir yanım', 'unutumasi-gereken-bir-yanim-huseyin-cayikli-xouni', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'ismini hatırlatacak birşeyle karşılaşsam

bakmadan geçiyoum...

tek şahit...

martı ve serçeler...

ve ben her zaman ki gibi aynı

hiç değişmeyen olarak

yaşıyorum

unutuyorum...

unutmayı çalışmamı...', 'ismini hatırlatacak birşeyle karşılaşsam bakmadan geçiyoum... tek şahit... martı ve serçeler... ve ben her zaman ki gibi aynı hiç değişmeyen...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Cayıklı']::text[], 8.5, '{"poet":"Hüseyin Cayıklı","poet_slug":"huseyin-cayikli","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/unutumasi-gereken-bir-yanim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat Dedikleri', 'hayat-dedikleri-huseyin-cayikli-o77yx', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'yazılar suçlu ve cesur oldukça

ağır sandığınız hayat dürüst davranır...', 'yazılar suçlu ve cesur oldukça ağır sandığınız hayat dürüst davranır......', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Cayıklı']::text[], 8.5, '{"poet":"Hüseyin Cayıklı","poet_slug":"huseyin-cayikli","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/hayat-dedikleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Okyanus', 'okyanus-ozkan-ozdogan-0c30i', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'En son

seni balık ağlarından çekip

çıkardığımı hatırlıyorum..

Şaşkınlıkla,

biraz da isteyerek

maviye atmıştın hani kendini..

Kırılan güneş ışığı

yolunu şaşırtıp da

çekmeseydi seni açığa

nasıl bulurduk birbirimizi? 

Pul pul olmuş gözlerinle

tuz yarası ellerinle,

uzanıp beni de çekivermiş,

ortak etmişsin meğer

soluksuz bir derinliğe...

Saçlarım yosun

gözlerim deniztaşı şimdi,

ve ben bir damlasıyım

''sen'' dediğim

bu koskoca okyanusun..', 'En son seni balık ağlarından çekip çıkardığımı hatırlıyorum.. Şaşkınlıkla, biraz da isteyerek maviye atmıştın hani kendini.. Kırılan güneş ı...', ARRAY['Türk Edebiyatı','Şiir','Özkan Özdoğan']::text[], 8.5, '{"poet":"Özkan Özdoğan","poet_slug":"ozkan-ozdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/okyanus-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalan', 'yalan-mustafa-gokcek-iufba', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'YALAN

Gözlerimi yatırıp uzaklara

Bakıyorum işte, öylesine

Yaşamak ağrısı saplandı boynuma

Yaşamak, başkası içinde olsa

Pusatsızım, artık mavzerimi astım duvara

Ve yüreğimi rehin bıraktım, yüreklice

Cesaretim onmaz yaralarla

Yol bitiyor artık ve ne olur, ne olur yalan de…



03.01.05                                          M.Gökçek', 'YALAN Gözlerimi yatırıp uzaklara Bakıyorum işte, öylesine Yaşamak ağrısı saplandı boynuma Yaşamak, başkası içinde olsa Pusatsızım, artık mav...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Gökçek']::text[], 8.5, '{"poet":"Mustafa Gökçek","poet_slug":"mustafa-gokcek","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/yalan-127-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Memleket', 'bu-memleket-sadik-softa-ecc9i', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bu memleket birden var olmamıştır; 

Atalar kanından kan verdi oğul...

Böyle sana bana yol olmamıştır; 

Atalar kanat ve kol gerdi oğul...

Hep bakarız hala dosta, düşmana; 

Ufak bir açıkta düşer armkana; 

Sarılmaya hele bir gör yakana; 

Vallahi tükenmez kul derdi oğul.

Su uyur da düşman uyumaz derler; 

Bulunma gaflette hemen güderler; 

Hayale gelmedik haltı ederler; 

Atalar olsaydı dur derdi oğul.

Unuttun mu yedi düvel n''apmıştı? 

Üç günlüğü, yetmişlikle yakmıştı; 

Bütün millet canın dişe takmıştı; 

Ata bu memleket hür derdi oğul.', 'Bu memleket birden var olmamıştır;  Atalar kanından kan verdi oğul... Böyle sana bana yol olmamıştır;  Atalar kanat ve kol gerdi oğul... Hep...', ARRAY['Türk Edebiyatı','Şiir','Sadık Softa']::text[], 8.5, '{"poet":"Sadık Softa","poet_slug":"sadik-softa","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bu-memleket-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sir ve ney', 'sir-ve-ney-huseyin-gazi-sener-8x712', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ver bütün servetini, hatta damarında kanını

Tut içinde gizli kalsın, açma sırrını

Gönül derdini gizle, sessiz beklesin. 

Üfle bir kamışı da sonra inlesin

Şimdi sırrın aşikar, cümle alem dinlesin

Kuru kamış ses verir sır vermez

İçi hikmet doludur akıl ermez…', 'Ver bütün servetini, hatta damarında kanını Tut içinde gizli kalsın, açma sırrını Gönül derdini gizle, sessiz beklesin.  Üfle bir kamışı da ...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Gazi Sener']::text[], 8.5, '{"poet":"Hüseyin Gazi Sener","poet_slug":"huseyin-gazi-sener","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/sir-ve-ney-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevda Misali...', 'sevda-misali-sibel-uygun-e8ix8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İnsanlar bir kumsal, hayatsa bir deniz...

Kimi zaman durgun...

Kimi zaman dalgalı…

Kimi zamansa, köpürür kudurmuşcasına…

Dalgalar kumsala her çarpışta, kumları sürükleyip götürürler.

Akıp gider kumları sakın bekleme! ..

Onlar asla dönmezler…

Tıpkı geçip giden sevdalar misali…', 'İnsanlar bir kumsal, hayatsa bir deniz... Kimi zaman durgun... Kimi zaman dalgalı… Kimi zamansa, köpürür kudurmuşcasına… Dalgalar kumsala he...', ARRAY['Türk Edebiyatı','Şiir','Sibel Uygun']::text[], 8.5, '{"poet":"Sibel Uygun","poet_slug":"sibel-uygun","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sevda-misali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elveda...', 'elveda-sibel-uygun-y4sqw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '''Her gidişin bir dönüşü vardır. Ben bu sefer tek gidişi seçiyorum. 

Bekleme hiç, dönmeyeceğim...

Biliyorum çok zor olacak, ama zorlar da başarılmak için yaratılmıştır. 

Hep kolayı seçmek, bir şeylerin ardına sığınmak, gerçekleri gizleyip hayallerde yaşamak...

Göz yaşlarını gülüşlerin ardına gizlemek...

İşte bunlar kolay olanlar.

Hayatla yüzleşmenin tam zamanı. 

Gidiyorsam eğer sonuna kadar sürmeli bu yol'' demiştin...

Ve yüzün yola dönük, bense ardında kalmıştım. 

Senden duyduğum son söz ''hoşçakal'' hala kulaklarımda uğulduyor...

Attığın her adımda biraz daha uzaklaşırken senden, yüreğimden bir şeyler kopup gidiyor...

Biliyorum ardına bakmayacaksın.

Bense ''dur gitme'' demeyeceğim...

Zor olan hangisi? 

Senin son kez bakabilme ihtimalin mi? 

Yoksa benim ''gitme'' diye haykırabilmem mi? 

Derken ben, işte gittin ve ben bittim...

Gurur:1 Aşk:0', '''Her gidişin bir dönüşü vardır. Ben bu sefer tek gidişi seçiyorum.  Bekleme hiç, dönmeyeceğim... Biliyorum çok zor olacak, ama zorlar da baş...', ARRAY['Türk Edebiyatı','Şiir','Sibel Uygun']::text[], 8.5, '{"poet":"Sibel Uygun","poet_slug":"sibel-uygun","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/elveda-127-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Damlalar', 'damlalar-ahmet-kaytanci-oyi90', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Avuçlarıma düştü damlalar

Yanağımdan süzülüp birer birer 

Od bürüdü beynimin bütün hücrelerini

Sevgiden yana ne varsa

Bu alevi ancak damlalar yener

Kavrulur ruhumda bütün düşünceler

Yanık buğdaylar gibi

Cehennemini yaşarım

Uykusuz gecelerin

Gökyüzünde birer birer 

Yıldızlar söner

Kirpiklerime takılır dolunay

Göz çukurlarıma

Damlalar iner

Saçlarımda taşırım yılların yorgunluğunu

Omuzlarımda bir yığın yük

Kahırlar tokat vurur suratıma

Küçük büyük

Can havliyle bağırmak gelir içimden

Ruhumda karabulutlar döner

Göz pınarlarıma sığınırım her defasında

Damlalara sığınmak sanki hüner

Acılar birleşir, zerre olurlar

Her yerden gelir gözlerimi bulurlar

Aklımı başımdan çekip alırlar

Nerden gelir, nere gider bilinmez

“Gül” demeyle bir çırpıda gülünmez

“Öl” demeyle istesen de ölünmez

Dertlerim çıngı olur, çıra olur yanar 

Damlalar olmasa ne ile söner

Damlalar olmasa ne ile söner', 'Avuçlarıma düştü damlalar Yanağımdan süzülüp birer birer  Od bürüdü beynimin bütün hücrelerini Sevgiden yana ne varsa Bu alevi ancak damlala...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Kaytancı']::text[], 8.5, '{"poet":"Ahmet Kaytancı","poet_slug":"ahmet-kaytanci","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/damlalar-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelmez', 'gelmez-ahmet-kaytanci-cvanm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Uzak derler bizim dağ yamacına

Buralara gönül vermeyen gelmez

Kimse bakmaz senin bir gün acına

Kalp gözüyle bakıp görmeyen gelmez

Çetin olur bu dağların arası

Hiç iyileşmez sırtındaki yarası

Zifiri karanlık her dem burası

Sevdasını saça örmeyen gelmez

Deniz yoktur burada, villa yoktur

Derdin depreşir de bulunmaz doktor

Gençliği azdır da, yaşlısı çoktur

Dünyadan elini dermeyen gelmez

Belki bulamaz hastalar ilacı

Belki de çekilir her daim acı

Şu dağlar görülür belki de öcü

Şehrin havasını yermeyen gelmez

Bir lokma ekmeğin tutsa ucundan

Şehirde ölse de her gün acından 

Yine ürkerler bu dağ yamacından

Kendini sürgüne sürmeyen gelmez

Bu dağlarda her gün çiçekler açsa

Mis gibi kokuyu her yana saçsa

Kuşlar cıvıldaşıp göklerde uçsa

Başını ayağa sermeyen gelmez

Kaytancı çağırma kimseyi sakın

Uzaklar olmuyor bir türlü yakın

Şimdi bize değil ellere akın

Vuslatın sırrına ermeyen gelmez', 'Uzak derler bizim dağ yamacına Buralara gönül vermeyen gelmez Kimse bakmaz senin bir gün acına Kalp gözüyle bakıp görmeyen gelmez Çetin olur...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Kaytancı']::text[], 8.5, '{"poet":"Ahmet Kaytancı","poet_slug":"ahmet-kaytanci","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/gelmez-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerin Gözlerime Baktığı Zaman', 'gozlerin-gozlerime-baktigi-zaman-ahmet-kaytanci-6p7bb', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gözlerin gözlerime baktığı zaman

Bir hoş olur içim

Uçarım bulutların üstünde

Rüyada sanırım kendimi

Dokunmak isterim sana uzatıp da ellerimi

Sen ateş olup yakarsın diye

Bir korku saplanır yüreğime

Titrer ellerim utançtan

Yanaklarım pembeleşir

Gözlerim dolar sanki

Dinlerim tüm şarkıları sil baştan

Hasret, hüzün ve umut

Hep seni hatırlatır

Duyguların doruk noktasına 

Gözlerim dolar

Kaçarım 

Belki kaçmak değil benimkisi

Derdimi göz yaşlarıma açarım

Gözlerin gözlerime baktığı zaman

Kelimeler düğümlenir dudaklarımda

İçime gömerim duygularımı

Kimseler görmesin,

Kimseler bilmesin,

Kimseler duymasın diye

Bir sırra kadem basarım

Alır götürür sevdan beni

Kar topu bulutlar üstüne

Gülerim, ağlarım, şaşarım

Bazen kanatlanırım kırlangıç misali

Ülkeden ülkeye uçarım

Bazen kurşun yemiş kınalı keklik gibi

Bir avcının ayaklarına düşerim.

Sen bilemezsin; 

Kelebek kanatlarınla estirdiğin meltemin

İçimde kopardığı  fırtınaları

Sen göremezsin; 

Beynime balyoz gibi çakılan gülücüklerin

Hayallerimde yaptığı depremi

Sen duyamazsın; 

Ruhumda  yanar dağlar gibi fışkıran lavların

Yüreğimde yaktığı ateşi

Sen anlayamazsın; 

Boğazıma düğümlenen kelimelerin

Gönlüme neler anlattığını

Bir anlayabilsen, bir görebilsen, bir duyabilsen

Ne kadar derinden seni sevdiğimi.

Gözlerin gözlerime baktığı zaman', 'Gözlerin gözlerime baktığı zaman Bir hoş olur içim Uçarım bulutların üstünde Rüyada sanırım kendimi Dokunmak isterim sana uzatıp da ellerimi...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Kaytancı']::text[], 8.5, '{"poet":"Ahmet Kaytancı","poet_slug":"ahmet-kaytanci","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/gozlerin-gozlerime-baktigi-zaman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Unutacağım', 'seni-unutacagim-zeynep-nilgun-gokceoz-yos5h', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Her sabah uyandığımda,

Yeni bir gün doğduğunda, 

Doğan güne söz verdim

Seni unutacağım.

Gönlümde hasret türküleri çaldığında,

Nağmeler yaramı her kanattığında,

Yüreğime söz verdim

Seni unutacağım.

Issız sokaklarda sensiz dolaştığımda,

Ağaçlara, yapraklara seni anlattığımda 

Kuşlara söz verdim 

Seni unutacağım.

Çaresizce kaderime inandığımda,

Yalnızlığı kendimle paylaştığımda,

Gönlüme söz verdim

Seni unutacağım.

Sensizlik kokan gecelere,

Avunduğum rüyalarıma,

Yaşattığım hayallerime söz verdim

Seni unutacağım.

Zeynep Nilgün Gökçeöz', 'Her sabah uyandığımda, Yeni bir gün doğduğunda,  Doğan güne söz verdim Seni unutacağım. Gönlümde hasret türküleri çaldığında, Nağmeler yaram...', ARRAY['Türk Edebiyatı','Şiir','Zeynep Nilgün Gökçeöz']::text[], 8.5, '{"poet":"Zeynep Nilgün Gökçeöz","poet_slug":"zeynep-nilgun-gokceoz","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/seni-unutacagim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerine', 'gozlerine-ahmet-kaytanci-mgg06', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Mahkûm ettim sevdalarımı

Doğmamış duyguların gözbebeklerine 

Uzansa da ellerim, zaman zaman ellerine

Dalsa da gözlerim gözlerine

Mahkum ettim duygularımı

Gözbebeklerine

Çatılsa da kaşlarım anlamsız ve çirkin

Dökülse de dilimden kelimeler

Manasız ve bitkin

Alınsam da mantıksız tavrına

Anlamsız sözlerine

Mahkum ettim duygularımı

Duygusuz gözlerine

Her gün lapa lapa kar yağsa

Kar durup, yağmur yağsa

Fırtına esip, hava soğusa

Ya da, gün gülümseyip güle doğsa

Ne donar, ne yanarım

Bir çift gözün güzelliğine kanarım

Bir yudum su, bir lokma ekmek

Bir nefes hava, bir hayat demek

Hayatın içinde en garip duygu

Bir çift gözü; göz diye beklemek

Bütün manalar sözde gizlidir

Zaman zaman özde gizlidir

Bülbül olup konuşsa da dillerimiz

En gerçek sırlar gözde gizlidir

Sırrında yok olur giderim

Gözlerimi gözlerine mahkûm ederim', 'Mahkûm ettim sevdalarımı Doğmamış duyguların gözbebeklerine  Uzansa da ellerim, zaman zaman ellerine Dalsa da gözlerim gözlerine Mahkum etti...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Kaytancı']::text[], 8.5, '{"poet":"Ahmet Kaytancı","poet_slug":"ahmet-kaytanci","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/gozlerine-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalan ve Gerçek', 'yalan-ve-gercek-fatih-cunus-cxtrc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Avucumda hala elinin sıcaklığı 

Tenimde hala teninin ateşi

Kalbimde hala sevginin sonsuzluğu

Gözlerimde hala gözlerin

Hücrelerimde hala hücrelerin 

Bağımlılığımsın

Sen beni bıraksan da 

Ben seni bırakamıyorum

Farkın ne bilmiyorum ama

Farklılığın olduğu kesin

Benim için ayrıcalığın olduğun ortada

Sen kendi ayrıcalığının farkında olmasan da 

Ve benim de ayrıcalığımın

Geçen zaman teselli etmiyor

Unutturmuyor seni bana

Silinmiş geleceğimizi hatırlatıyor

Gözyaşları çare değil artık 

Yakarışlar da çare değil

Çare yok artık, sen yoksun

Bedenim iki parça 

Yüreğim ise paramparça

Ruhum can çekişiyor

Kalp atışlarım anlamsız 

Ve gereksiz ve sensiz

Rüyalarım kabus 

Ve kabuslarım sensizlik

Sensizlik ise hiçlik 

Yaşadığımız gerçek

Aşkımız yalan 

Sevgimiz gerçek 

Hayat gerçeklerle dolu

Hem de kocaman yalan gerçeklerle

O halde gerçek olan sadece aşkımız 

Yalan olan ise hayatın kendisi

Gerçek hayatın ta kendisi', 'Avucumda hala elinin sıcaklığı  Tenimde hala teninin ateşi Kalbimde hala sevginin sonsuzluğu Gözlerimde hala gözlerin Hücrelerimde hala hücr...', ARRAY['Türk Edebiyatı','Şiir','Fatih Cünüş']::text[], 8.5, '{"poet":"Fatih Cünüş","poet_slug":"fatih-cunus","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/yalan-ve-gercek-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırk Yılın Hesabı', 'kirk-yilin-hesabi-ahmet-kaytanci-jxnoo', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kırk yıl insan bekletilir mi be

Kırk yıl bu dile kolay

Her geçen gün ıstırap 

Her geçen gün olay

Kırk yıl sonra gelmişsin 

Bir de ediyorsun alay

Hadi geceleri sayma

Gündüzler eder yirmi

Bu bir ömür değil mi? 

Halâ “birkaç gün daha bekle” diyorsun

Zaten sen hiç doğmadın

Doğmakta istemiyorsun

Sanki orada sana “Kraliçe”  dediler

Başına bir de taç giydirdiler

Cenneti aladan bir köşeydi yerin

Etrafında pervane dönüyordu hizmetçilerin

Bir havuz başında ayaklarını suya uzatmış

Gölgeliyordun altında şemsiyelerin

Eskiden böyle değildi saçlarım

Hep seni beklemekten beyazlaştı bıyıklarım

Kırk yıl daha beklerim

Ne olacak sanki

Seni beklemek o kadar güzel

İnan ki

Alnımdaki kırışıklıklar

Hasret yolları

Gözümdeki halkalar

Gecenin gülleri

Kınamıyorum artık

Tel üstünde kumruları

Gül yanında bülbülleri

Sen bir umutsun

Ha bu gün, ha yarın gelecek

Belki de senin geldiğin gün

Bütün hayaller ölecek

Sen meleksin bunu biliyorum

Hep beyaz elbiselerinle geleceğin günü bekliyorum

Cebrail yada Azrail ol ne fark eder ki

Senin kollarında ölmeyi özlüyorum', 'Kırk yıl insan bekletilir mi be Kırk yıl bu dile kolay Her geçen gün ıstırap  Her geçen gün olay Kırk yıl sonra gelmişsin  Bir de ediyorsun ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Kaytancı']::text[], 8.5, '{"poet":"Ahmet Kaytancı","poet_slug":"ahmet-kaytanci","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/kirk-yilin-hesabi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Günü Yaşarsınya Hani', 'gunu-yasarsinya-hani-sinan-dayan-cbl6p', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Günü yaşarsınya hani! 

Günün içinde.

Yüreğindeki tıkırtı,

Bedenindeki ürperti,

Sessizliğin tek şahitleridir,

Sensizliği soluduğum bu dünyada.

Günü yaşarsınya hani! 

Dünle birlikde....

Ellerin açılmıştır,

Gökyüzüne,ileriye ve hatta her şeye.

Sanki yüreğindir açılan, ellerin değil.

Günü yaşarsınya hani! 

Sensizliklerde...

Ellerim,bedenim,yüreğim,

Sensizliklerde bir ve tekim.

Günü yaşarkende,solurkende,

Sensizliği yüreğimde hissederim.

Günü yaşarsınya hani! 

Solmuş yüreklerde...', 'Günü yaşarsınya hani!  Günün içinde. Yüreğindeki tıkırtı, Bedenindeki ürperti, Sessizliğin tek şahitleridir, Sensizliği soluduğum bu dünyada...', ARRAY['Türk Edebiyatı','Şiir','Sinan Dayan']::text[], 8.5, '{"poet":"Sinan Dayan","poet_slug":"sinan-dayan","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/gunu-yasarsinya-hani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlatabildim mi Hasreti', 'anlatabildim-mi-hasreti-mehmet-nedim-korkmaz-uqrje', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen gittikten sonra; 

Gökkuşağı kayıp

Bütün renkler sarı

Mevsimler hep sonbahar

Narlar nar kırmızısı

Kuşların hepsi Bülbül

Güller sadece diken

Yağmurlar sağanak.

Dalgaların hepsi hırçın

Dönülmez seferlere çıktı gemiler.

Günbatımı kızıllık

Kerem’i yakan ateşten armağan.

Dağların hepsi Nemrut

Kentlerin sokakları ışıksız

Geceleri dipsiz uçurum

Bütün hastalar ağır verem

Yemekler tadsız tuzsuz

Kahveler hep şekersiz

Sevdalar hep yarım

gidenlerin tümü zalim

Dervişler sabır yoksulu

Mahkumların tümü müebbet

Sözlüklerde tek kelime yazılı

Hasret.

Söz ustalarının üstadı

Şairlerin şahı olsan

Karetmez.

Ne kalem tüketir,

Ne kelam anlatır.

Avuçlarımda,

Hıçkırığı yasak

Birkaç damla yaş.

gözlerimde

deniz gözlerinden bir yudum.

Dilimde hep o türkü

“Ayrılık hasreti kar etti cana”

bakışlarımda beklemenin ümidi

öylece  kalakaldım.

Özcesi,

sen gittikten sonra

hayatın adını

Hasret koydum..

                     Bulancak

                    07.11.2004 

                      02.30', 'Sen gittikten sonra;  Gökkuşağı kayıp Bütün renkler sarı Mevsimler hep sonbahar Narlar nar kırmızısı Kuşların hepsi Bülbül Güller sadece dik...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Nedim Korkmaz']::text[], 8.5, '{"poet":"Mehmet Nedim Korkmaz","poet_slug":"mehmet-nedim-korkmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/anlatabildim-mi-hasreti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekleyiş', 'bekleyis-servet-suner-grnpz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir şehrin tam orta yerinde ben,

İnsanlar etrafımda karınca gibi kaynıyorken,

Ve ben.. dünyanın uçsuz bucaksız bomboş,

Öbür yüzünde yapayalnız bir başıma,

Bir kule yaqtım gündüz gözüne,

Girdim gecenin karanlığında içine,

Pencerelerde,odalarda ve duvarlarında,

İnsan yüzleri birer hayalet gibi sessiz,

Buz gibi soğuk ve anlamsız bakar yüzüme,

Ve ben kendi kendime yapayalnız,

Bu buz dağının içinde beklerim.

Artık şu kapı açılsın sonsuz''a diye.', 'Bir şehrin tam orta yerinde ben, İnsanlar etrafımda karınca gibi kaynıyorken, Ve ben.. dünyanın uçsuz bucaksız bomboş, Öbür yüzünde yapayaln...', ARRAY['Türk Edebiyatı','Şiir','Servet Suner']::text[], 8.5, '{"poet":"Servet Suner","poet_slug":"servet-suner","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bekleyis-105-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlasana', 'anlasana-suheyl-turkoglu-b51y7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kar tuttu ellerim,

Tırnaklarım sızladı,

Morardı parmaklarım,

Göstermedim sana.

Ateş küresiyle,

Top gibi oynadım,

Yandı her bir yanım,

Söylemedim sana.

Çiçekleri verdim,

Dikenleri sırtladım,

Acıtmasın diye,

Taşıtmadım sana.

Dahası yok,

Ötesinde biterim,

Böyle gidemez,

Artık anlasana.', 'Kar tuttu ellerim, Tırnaklarım sızladı, Morardı parmaklarım, Göstermedim sana. Ateş küresiyle, Top gibi oynadım, Yandı her bir yanım, Söylem...', ARRAY['Türk Edebiyatı','Şiir','Süheyl Türkoğlu']::text[], 8.5, '{"poet":"Süheyl Türkoğlu","poet_slug":"suheyl-turkoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/anlasana-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Merhaba', 'merhaba-zeynep-nilgun-gokceoz-103om', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gözümü açtığımda ışıldayan güneşe,

Masmavi gökyüzüne,

Bastığım toprağa,

Fısıldayan rüzgara

Merhaba.

Sevginin ısıttığı gönüllere,

Sevdalı türkülere,

Gülümseyen her yüze

Merhaba.

Meçhul geleceğime,

Tatlı anılarıma,

Bitmez umutlarıma

Merhaba.

Beni seven herkese, benim sevdiklerime,

Bitmeyen dostluklarıma,

Gönül yoldaşlarıma

Merhaba.

Hatıralar bizim olsun,

Rüyalar tatlı kalsın,

Yalanlar uğramasın,

Bir merhaba hepimizin olsun.

Zeynep Nilgün Gökçeöz', 'Gözümü açtığımda ışıldayan güneşe, Masmavi gökyüzüne, Bastığım toprağa, Fısıldayan rüzgara Merhaba. Sevginin ısıttığı gönüllere, Sevdalı tür...', ARRAY['Türk Edebiyatı','Şiir','Zeynep Nilgün Gökçeöz']::text[], 8.5, '{"poet":"Zeynep Nilgün Gökçeöz","poet_slug":"zeynep-nilgun-gokceoz","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/merhaba-84-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmiştim Seni...', 'sevmistim-seni-kazim-basekmekci-xp3ir', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ellerin bir tabancanın kabzası kadar soğuk,

Bakışların kurşunlar kadar sıcakken,

Sevmiştim seni.

Belki bende olmayan yanlarındı,

Beni sana yaklaştıran.

Kendimi sende bulduğumu sanmıştım.

Damarlarımda dolaştırmıştım kanını.

Gün oldu, bir rüyadır demiştim.

Gün oldu, sevgilimdin benim.

Ben seni bir temmuz sıcağında değil,

Sevginin bir çift çizmeye tutsak olduğu,

Karakışta, Şubat’ın on sekizinde sevmiştim.

Gözlerine bakmaktan korkardım bazen,

Kaçırırdım bakışımı, bakışlarından,

Tutamazdım kendimi yine de

Korku böyle başladı benliğimde.

Dağlara dalıp gitmem bundandır.

Bundandır, aşık olmam bulutlara,

İçli içli türküleri sevmem,

Ve yaşıma nefretim bundandır.

Çok geç sevmiştim seni,

Belki de  ben erken gelmiştim dünyaya.

Ya da  bastıramadığım duygulardı,

Aklımdan geçenler.

Adına ne dersen de! 

Bana ne söylersen söyle! 

Ölümüne sevdayla sevmiştim seni.

Bir içimdeki seni öldürememiştim.

Bir de mertliğini yüreğimin.

Kederli akşamlarımın, bir kadeh içkisiydi,

O yeşil gözlerin.

Yeşili senle sevmiştim.

Şubat’ı senle...

Şimdi yoksun yanımda.

Rüzgar  yeşil yeşil esiyor.

Kar yeşil taneciklerini döküyor, doğama.

Ben her Şubat’ın on sekizinde.

Karlara çimen  diye basıyor, 

Leylekler getiriyorum dünyama.

Ve her Şubat’ın on sekizinde,

Bir bıçak saplanıyor yüreğime.

Yarısını alıp götürüyor uzaklara.

Ben ölüyorum yavaş yavaş,

Görüyorum ki; sen hala yaşıyorsun.

Bilki ben senin yaşamanı  istemiştim.

Ben senin bir çift yeşil gözünü değil,

Hayata bakışını sevmiştim..', 'Ellerin bir tabancanın kabzası kadar soğuk, Bakışların kurşunlar kadar sıcakken, Sevmiştim seni. Belki bende olmayan yanlarındı, Beni sana y...', ARRAY['Türk Edebiyatı','Şiir','Kazım Başekmekçi']::text[], 8.5, '{"poet":"Kazım Başekmekçi","poet_slug":"kazim-basekmekci","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/sevmistim-seni-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Siyah', 'siyah-sair-zeyneps-5t7sj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Beyaz gecenin ardından,

Siyahın şeffaflığını izle

Yoksa kaybolup gidersin

Karanlığın ötesinde...

Sitem edersin

Susmanın öldürücü matemine...

Karanlıkta yaşamak

Siyah kadar korkutucu

Ve bir o kadar da yalın

Yalnızlığın baslangıcıdır..

Önemli olan,

Işığı bulmaktır

Yaşarken ölürcesine...', 'Beyaz gecenin ardından, Siyahın şeffaflığını izle Yoksa kaybolup gidersin Karanlığın ötesinde... Sitem edersin Susmanın öldürücü matemine......', ARRAY['Türk Edebiyatı','Şiir','Şair Zeyneps']::text[], 8.5, '{"poet":"Şair Zeyneps","poet_slug":"sair-zeyneps","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/siyah-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Smyrnalı Bir Rüzgar', 'smyrnali-bir-ruzgar-sezer-odabasioglu-fcfxj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'gülümsedin ya

nefesi aşk kokulu

bin martı kanat vuruşlu

smyrnalı bir rüzgar

kopup koştu körfezden...

suya düşen ihanete aldırmadan.

suyun yüreğine

           yüreğine düşen acıya aldırmadan.

nefesindeki kaç intihardan kalıt-aşk kokusu

smyrnalı rüzgarın

soramam şimdi

daha sonra sorarım belki...

bakıp gözümün derinliğine

                            gülümsedin ya,

kaç kör pencere açıldı bir bilsen...

ve kaç yorgun papatya

taç yapraklı mendiliyle terini sildi

                             kimseye göstermeden.

gülümsedin ya,

sanki aynı şarkıdan

                            sular içti kuşlar.', 'gülümsedin ya nefesi aşk kokulu bin martı kanat vuruşlu smyrnalı bir rüzgar kopup koştu körfezden... suya düşen ihanete aldırmadan. suyun yü...', ARRAY['Türk Edebiyatı','Şiir','Sezer Odabaşıoğlu']::text[], 8.5, '{"poet":"Sezer Odabaşıoğlu","poet_slug":"sezer-odabasioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/smyrnali-bir-ruzgar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalem', 'kalem-suheyl-turkoglu-760ru', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Aşkı yazmak istedim,

Elimdeki kalem,

Önce pembe,

Sonra,

Siyah yazdı.

Sevgiyi yazarken,

Yumuşadı,

Avucumun içinde,

Mayıştı kaldı.

Sadakati yazarken,

Ucu,

Eğri, büğrü,

Yamuk, yumuk oldu.

Dürüstlük deyince,

Takıldı kaldı,

Haddini aştı,

yazmamaya başladı.

Cesareti yazarken,

Titremeye başladı,

Panikle,

Parmaklarımdan kayıp,

Sayfalara sığındı.

Mertlik deyince,

Çok keyiflendi,

Alay edercesine,

Arkasını dönüp,

Oynamaya başladı.

Yalanı yazarken,

Öyle yüklendi ki,

Sayfaya,

Yırtarcasına,

Şaşırıp kaldım.

Sonuncusu,

Çok komikti,

''Vefa''yı yazarken,

Elimdeki kalem,

Gülmekten kırıldı.', 'Aşkı yazmak istedim, Elimdeki kalem, Önce pembe, Sonra, Siyah yazdı. Sevgiyi yazarken, Yumuşadı, Avucumun içinde, Mayıştı kaldı. Sadakati ya...', ARRAY['Türk Edebiyatı','Şiir','Süheyl Türkoğlu']::text[], 8.5, '{"poet":"Süheyl Türkoğlu","poet_slug":"suheyl-turkoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/kalem-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söyle Gönül', 'soyle-gonul-firat-yilmaz-uqtss', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Olmaz ya hani

Eğer bir gün aşık olursam.

Bir çift yeşil uğruna

Kuytu kuytu buseler aşkına

Ve arşa yükselircesine kanatlanırsa bu beden.

Küser misin bana gönlüm,

Söyle küser misin? 

Biliyorum

Sana sözler verdim, yeminler ettim,

Dimağı zaptettim de bak

Sana söz geçiremedim, küstün mü yoksa bana? 

Üzdüm mü anılar sandığındaki beni? 

Yaptım mı bunu gönül...

Çiğnedim mi çiğnenmezleri? 

Ben sen ile bütün olalı

Sen ile yol tutalı, çok oldu gönül,

Unuttum mu acep ona olan vuslatı? 

Gönlüm.

Sor kalemime, ne kadar olmuş onu yazmayalı? 

Bir sor, söyler belki zamanı,

Gün mü, ay mı, yıl mı,

Yada bir asır mı olmuş dünya başımıza yıkılalı? 

Hata mı ediyorum gönül,

Hain miyim aşkına, yada geçmişe? 

Terk eden o değil miydi seni? 

Kim hain hadi söyle

Söyle gönül, yetmedi mi karalar bağladığın? 

Yok mu hakkın

Yok mu......? 

Söyle

Yok mu seninde sevilmeye hakkın?', 'Olmaz ya hani Eğer bir gün aşık olursam. Bir çift yeşil uğruna Kuytu kuytu buseler aşkına Ve arşa yükselircesine kanatlanırsa bu beden. Küse...', ARRAY['Türk Edebiyatı','Şiir','Fırat Yılmaz']::text[], 8.5, '{"poet":"Fırat Yılmaz","poet_slug":"firat-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/soyle-gonul-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tutuklu...', 'tutuklu-tulay-sustam-rmav1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'beni yüreğinden salmıştın

gölgenden öteye gidememiştim

geceyi senin için rehin aldım 

seni azat ediyorum

hadi uç bakalım mavi gökyüzünde

bil ki yüreğimden öteye gidemeyeceksin', 'beni yüreğinden salmıştın gölgenden öteye gidememiştim geceyi senin için rehin aldım  seni azat ediyorum hadi uç bakalım mavi gökyüzünde bil...', ARRAY['Türk Edebiyatı','Şiir','Tülay Sustam']::text[], 8.5, '{"poet":"Tülay Sustam","poet_slug":"tulay-sustam","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/tutuklu-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '...................Ya Pabucum Damdaysa...', 'ya-pabucum-damdaysa-suheyl-turkoglu-txq9i', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Uzun zaman oldu,

Çıkamıyorum dama,

Yükseklik korkum yok,

Yalan söylüyorum etrafa.

Çıkamıyorum,

Ödüm kopuyor,

Bulamadığım pabuçlarım,

Ya oradaysa.

Kolayıma gidiyor,

Pabuçsuzluk,

Cesaretim yok,

Yenilerini almaya,

Yine kaybolurlarsa

Mecbur kalıp,

Çıkarım dama.

Belki de sorsam,

Söyleyecekler yerlerini,

Bulabileceğim,

Elimle koymuş gibi.

Ama,

Yıkılmak ta var,

İşin ucunda.

Allah korusun,

Ya pabuçlarım

Dama atıldıysa..?', 'Uzun zaman oldu, Çıkamıyorum dama, Yükseklik korkum yok, Yalan söylüyorum etrafa. Çıkamıyorum, Ödüm kopuyor, Bulamadığım pabuçlarım, Ya orad...', ARRAY['Türk Edebiyatı','Şiir','Süheyl Türkoğlu']::text[], 8.5, '{"poet":"Süheyl Türkoğlu","poet_slug":"suheyl-turkoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/-ya-pabucum-damdaysa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dileğim', 'dilegim-serap-demirturk-z4eym', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kararan,yüreğin olmasın, gün olsun; açar...

Bulutlar gökyüzünü sarsın, gözlerini değil...

Sen umut saç güzel gözlerinle bakmasını bilmeyene

Elinle verdiğin, gönülleri sarar sevgiyle; üzülme.

Ey yar...puslu günler, karlı dağlar ne kadar uzak olabilirse bizden o kadar uzağız dertten, tasadan ve yaşadıkça bil ki karanlıklar içinde de kalsak bir ışık hep olacak. Işığını bulman dileği ile...', 'Kararan,yüreğin olmasın, gün olsun; açar... Bulutlar gökyüzünü sarsın, gözlerini değil... Sen umut saç güzel gözlerinle bakmasını bilmeyene ...', ARRAY['Türk Edebiyatı','Şiir','Serap Demirtürk']::text[], 8.5, '{"poet":"Serap Demirtürk","poet_slug":"serap-demirturk","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/dilegim-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Minik Serçe''nin Gidişi...', 'minik-serce-nin-gidisi-tulay-sustam-s4txg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'yetim bir martının dostuyum ben

adım öksüz minik serçe

laf taşıyan leylek ile işim olmadı benim

mavi gökyüzü hiç uğruna siyaha boyandı

martımı bana geri verin, gökyüzü sizin olsun

gökyüzü olmasa da; martı benim mavi evrenim', 'yetim bir martının dostuyum ben adım öksüz minik serçe laf taşıyan leylek ile işim olmadı benim mavi gökyüzü hiç uğruna siyaha boyandı martı...', ARRAY['Türk Edebiyatı','Şiir','Tülay Sustam']::text[], 8.5, '{"poet":"Tülay Sustam","poet_slug":"tulay-sustam","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/minik-serce-nin-gidisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kargı Anılarımda', 'kargi-anilarimda-ayhan-altay-kx7px', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Beş buçuk saatte almıştık

Doksan kilometre yolu ilk gelişimizde

Kızılırmak mıydı bükülen, kaderimiz miydi? 

Yoksa Anadolu muydu/ bir kaya dibine oturan

Bir çırpıda dokuz yıl

Ölümüne dostluklar, aşkına kavga dolu

“Kirli sac” kokulu çarşıda.

Akyel sokağından beklenirdi, 

Çeltik tarlalarının sivrisinekleriyle gelen yazlar,

Yaşlı sakız ağacının karşısına,

Derneğin bahçesine dikmiştim 

İlk konuk çınarlarını Kargı’nın

-Babam göndermişti Karadeniz’den-

Komşum Osman’ın oğulları; delifişek devrimci.

Bahçe duvarlarında yazılar,

Akşamları manda sürülerinin geçtiği sokaklarında 

kavga vardı. 

Yürekte coşku, belde tabanca taşınırdı.

Dernekte topal kekliği ocakçı Vedat’ın,

Bizden daha özgürdü.

Terzi Osman’ın dükkanı / bu başka Osman.

İpsiz Recep’in, Gamo’nun, Kaptanın,

Kıvrak Yaşar’ın, Hakkı’nın ve benimdi.

Birlikte yaşardık umutlarımızı.

Kavgamı yükledim yorgun yollara,

Dostları ve gençliğimi bıraktım,

Kara bir güz günü ayrıldığım Kargı’da.', 'Beş buçuk saatte almıştık Doksan kilometre yolu ilk gelişimizde Kızılırmak mıydı bükülen, kaderimiz miydi?  Yoksa Anadolu muydu/ bir kaya di...', ARRAY['Türk Edebiyatı','Şiir','Ayhan Altay']::text[], 8.5, '{"poet":"Ayhan Altay","poet_slug":"ayhan-altay","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/kargi-anilarimda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mayıs Güneşi Sevdası', 'mayis-gunesi-sevdasi-ayhan-altay-v2cet', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'istiridye kabuğundan dinledik şiirleri

iyot taşıyan dalgalardık ilk yaza

adımız umut

dallarda kalmış baharlarda

yaşlanmadı sevdalarımız 

güzdönümü akşamlarında vurulduk

yine de kardelen sürdük namluya

yağlı kurşuna inat

kara kargaların değil

leş kargalarınındı karanlıklar

Nesimi’ydik  sitemsiz

mayıs güneşinedir

kavak yellerinden beri

tutsaklığımız', 'istiridye kabuğundan dinledik şiirleri iyot taşıyan dalgalardık ilk yaza adımız umut dallarda kalmış baharlarda yaşlanmadı sevdalarımız  güz...', ARRAY['Türk Edebiyatı','Şiir','Ayhan Altay']::text[], 8.5, '{"poet":"Ayhan Altay","poet_slug":"ayhan-altay","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/mayis-gunesi-sevdasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Altı Ocak *Ağabeyimin Ardından*', 'alti-ocak-agabeyimin-ardindan-erdogan-ergin-dzf53', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '''06.01.2004 Tarihinde aramızdan ayrıldın. Ama hala kokunu hissediyorum, teninin sıcaklığı elimde, sesin kulağıma geliyor. Niçin diye sormayacağım. Şehitler''e sorulmaz biliyorum. Ama hala kabul edemiyorum 37 yaşında gidişini. Allah yar ve yardımcın olsun.''

Hayatımdan bir gün eksik artık

Zamana inat siliyorum

Bugünü, altı ocak

Ne var yani yaşamak mı gerek

Hep aynı acıyı

Damla damla niçin düşüyor 

Yüreğime

Koz taneleri

Acıyı haketmedim ki ben

Haketmedi ailem

Hayatımdan bir gün eksik artık

Zamana inat; yaşamıyorum

Ayaklarım titriyor

Ellerimi kaldıramıyorum

Beynimde karıncalanmalar

Kalbimin sormayın sakın! 

Soğuk kanımın dolaştığını hissediyorum

Damarlarımda ve kalbimde

Hayatımdan bir gün eksik artık

Altı ocak yoksun

O gün

Kar yağıyordu, rahmet vardı

Karda

Kar yağıyordu

Kardan adamlar geldi

Aldılar ağabeyimi

Kar gibi beyaz örtüye

Nur yüzünü yerleştirdiler

Kar yağıyordu

Yüreğime.

Kardan adamlar geldiler

Aldılar yüreğimi

Örttüler ağabeyimin üzerine

Altı ocak yok artık

Kaldıramıyor bedenim

Kalbimin olmayışını

*** SEZA Şiir ve Edebiyat Dergisi''nin ARALIK 2005 sayısında yayınlanmıştır.', '''06.01.2004 Tarihinde aramızdan ayrıldın. Ama hala kokunu hissediyorum, teninin sıcaklığı elimde, sesin kulağıma geliyor. Niçin diye sormaya...', ARRAY['Türk Edebiyatı','Şiir','Erdoğan Ergin']::text[], 8.5, '{"poet":"Erdoğan Ergin","poet_slug":"erdogan-ergin","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/alti-ocak-agabeyimin-ardindan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir düş', 'bir-dus-ayhan-altay-k73sg', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'bir düş gemisi

dün gece

bir düş ülkesine taşıdı beni

dalgaların tınısında şiir

şiirin yüreğinde sevda

sevdasında

kavgası vardı özgürlüğün

bir düş gemisi

bir düş', 'bir düş gemisi dün gece bir düş ülkesine taşıdı beni dalgaların tınısında şiir şiirin yüreğinde sevda sevdasında kavgası vardı özgürlüğün bi...', ARRAY['Türk Edebiyatı','Şiir','Ayhan Altay']::text[], 8.5, '{"poet":"Ayhan Altay","poet_slug":"ayhan-altay","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/bir-dus-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adımı Anmayın', 'adimi-anmayin-ayhan-altay-2yza6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Adımı anmayın rüzgarlar! 

Estirmedi gönlümün yelini

Tutuklu kalan aklım.

Kavak yellerim bile yoktu,

Yaşayamadım.

Denizleri çok sevdim ama

Ardısıra koşamadım...

Adımı anmayın denizler! 

Özgürlüğün mavisinde salınamadım.

Amaçsız yolculuklara izin vermedi,

İçimdeki sansür.

Beni beklemedi dalgaların,

İzboyu akşamlarda...

Adımı anmayın akşamlar! 

Günbatımı yalnızlığı hep içimdeydi.

Sağamadım hüznünü.

Belirdiğinde ilk ışıkları Zühre’nin; 

Şarkımı içime gizledim,

Düşlerimi de...

Adımı anmayın düşler! 

Hep bekledim, hep umdum.

Umut yorgunu oldum.

Koşturamadım yılkı atlarını doludizgin.

Düşlerim,

Güz yaprakları ormanların...

Adımı anmayın ormanlar! 

Yaşamadım kardeşçesine özgür.

Uzatamadım kollarımı,

Sonsuzluğuna dostluğun.

Yapraklarım güz yelleri,

Dal uçlarım tomurcuk bahar...', 'Adımı anmayın rüzgarlar!  Estirmedi gönlümün yelini Tutuklu kalan aklım. Kavak yellerim bile yoktu, Yaşayamadım. Denizleri çok sevdim ama Ar...', ARRAY['Türk Edebiyatı','Şiir','Ayhan Altay']::text[], 8.5, '{"poet":"Ayhan Altay","poet_slug":"ayhan-altay","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/adimi-anmayin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıllara İsyân', 'yillara-i-sy-n-dursun-elmas-lf9ps', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yine bana kazık attın

Ömrümden çalan yıllar.

Veda bile etmedin

Ömrümden çalan yıllar! 

Ümit verdin,aşk dedin

Gözlerim yorgun düştü.

Demet demet gül dedin,

Güllerim solgun düştü.

Aha bu gün,aha yarın

Diye diye avuttun,

Hayâllerimi yuttun

Ömrümden çalan yıllar! 

Benim keseden çaldın,

Başkasına yamadın,

Bir kez olsun sormadın,

Ömrümden çalan yıllar! 

Fakirlere kindarsın,

Varlıklıya hep yârsın,

Allah belanı versin,

Ömrümden çalan yıllar! 

Yokmuş sende merhamet,

Telafer''i mahvettin! 

Anlaşıldı niyetin,

Ömrümden çalan yıllar! 

Hep Coni''ye yararsın,

Mazlumlara düşmansın,

Zalimlerden yanasın,

Ömrümden çalan yıllar! 

Ağıt yazdım taşlara,

Ses veririm kuşlara,

Sürersin yokuşlara,

Ömrümden çalan yıllar!', 'Yine bana kazık attın Ömrümden çalan yıllar. Veda bile etmedin Ömrümden çalan yıllar!  Ümit verdin,aşk dedin Gözlerim yorgun düştü. Demet de...', ARRAY['Türk Edebiyatı','Şiir','Dursun Elmas']::text[], 8.5, '{"poet":"Dursun Elmas","poet_slug":"dursun-elmas","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/yillara-isyan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Mutlu Sana', 'ne-mutlu-sana-erdem-yalcin-4533u', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Neler getirdi neler götürdü bilinmez

Geçen günlerse asla geri gelmez

Dalıp gitme sakın geçmişin hayaline

Hiç olmazsa bugününü de yitirme

Yaşa hissederek hayatın renklerini

Sudan bahaneyle üzme sevdiklerini

Bırak Uzaklaşıp gitsin içinden hüzünler 

Kimbilir belki gerçek olur güzel düşler

Hem sev hemde sevilerek yaşa

Yaşamda Gerisini asla umursama

Birkaç iyi dost varsa ardında

Öğün dostum ne mutlu sana', 'Neler getirdi neler götürdü bilinmez Geçen günlerse asla geri gelmez Dalıp gitme sakın geçmişin hayaline Hiç olmazsa bugününü de yitirme Yaş...', ARRAY['Türk Edebiyatı','Şiir','Erdem Yalçın']::text[], 8.5, '{"poet":"Erdem Yalçın","poet_slug":"erdem-yalcin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ne-mutlu-sana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sesleniş', 'seslenis-ekrem-ogdum-b87dl', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sana aşkımı bilmem ki nasıl anlatsam,

Gönül defterine sığmaz yazmaya kalksam,

Hani bir balık misali vardır; sudan haberi olmayan,

Bir damlası için neler vermez ki çıktığı zaman deryadan,

Hani bir bülbülün gülüne haykırdığı sevdasında,

Kim bilir nice ümitler saklıdır her yakarışında,

Hani bir çiçeğin yapraklarını kitap misali okuduğunda,

Her zerresi seni götürür güneşle olan aşkına...

Sevdama ne derya ne de çiçek olabilir kılavuz,

Anlatamaz bu tutkuyu ne bir isim ne de bir rumuz...

Sevdam derya kadar büyük bülbül kadar ümitli,

Bırakma beni böyle ne olur duy sesimi...', 'Sana aşkımı bilmem ki nasıl anlatsam, Gönül defterine sığmaz yazmaya kalksam, Hani bir balık misali vardır; sudan haberi olmayan, Bir damlas...', ARRAY['Türk Edebiyatı','Şiir','Ekrem Öğdüm']::text[], 8.5, '{"poet":"Ekrem Öğdüm","poet_slug":"ekrem-ogdum","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/seslenis-27-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fide', 'fide-ekrem-ogdum-pdkvs', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bugün bir fideyi toprağa gömdüm ben,

“Kim toprağa gömülür” diye düşünürken,

Fide boy attı; boy attıkça büyüdü aniden,

İşte o zaman anladım, biri sevinirken

Diğeri üzülür korkar toprağa girerken...

Sanki bir rüyadayım bir kabus mu bu? 

Yoksa gerçekleri kabul etmek bu kadar zor mu? 

Hani benim hayallerim, yoksa hepsi bozuldu mu? 

Heyhat! Gözyaşının zamanında gözlerim uyudu,

Şimdi uyandı da ne oldu; ne umuyordu ne buldu...

Selam sana toprağa verdiğim fide selam! 

Kurtuldun işte o kahırdan vesselam,

Acılara, öfkelere, kinlere en pak düşüncen kêlam,

Dar ağacına astım senin o yüzünü bir daha bakmam

Bitti sendeki bu bekleyiş artık onu da sormam...

Bugün ruhumu toprağa gömüyorum ben,

“Kim ister ki gömülmek” diye düşünürken,

Ruhum boy attı boy attıkça büyüdü aniden,

İşte o zaman anladım ruhum sevinirken; 

Bedenim üzüldü korktu toprağa girerken...', 'Bugün bir fideyi toprağa gömdüm ben, “Kim toprağa gömülür” diye düşünürken, Fide boy attı; boy attıkça büyüdü aniden, İşte o zaman anladım, ...', ARRAY['Türk Edebiyatı','Şiir','Ekrem Öğdüm']::text[], 8.5, '{"poet":"Ekrem Öğdüm","poet_slug":"ekrem-ogdum","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/fide-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dönek dünya', 'donek-dunya-ekrem-ogdum-l5j51', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Güneşler asla batmaz! 

Batmış gibi gösteren dönek dünyadır...

Her geçen saniye aleyhime,

Her batan güneş aleyhime,

Mümin dünyayı zindan bellese,

Zindanda eylen-mek onun neyine...

Binmişim saatin narin teline,,

Her tıklayış götürür ağır ağır ölüme,

Vazgeçilemeyen, reddedilemeyen kaderin

Diğer bilinen adı; doğmak, yaşamak, ölüm...

Ta uzaklarda, çok uzaklarda görünür,

Ansızın başucunda nedensizce dikilir,

Doğarken sorulmadığı gibi sualsizce,

Bitmeyen zamanı birden bire bitirir...', 'Güneşler asla batmaz!  Batmış gibi gösteren dönek dünyadır... Her geçen saniye aleyhime, Her batan güneş aleyhime, Mümin dünyayı zindan bell...', ARRAY['Türk Edebiyatı','Şiir','Ekrem Öğdüm']::text[], 8.5, '{"poet":"Ekrem Öğdüm","poet_slug":"ekrem-ogdum","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/donek-dunya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deli gönül', 'deli-gonul-ekrem-ogdum-jlucv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Heyhat deli gönül! Artık yeter...

Elini eline vermedin; bakışına bakmadın zamanında,

Nice anlamı sırtlanmış gözleri keskin bıçaktan beter,

Şimdi boşuna yalvarma, cezanı çekte kurtul zamanında...

Ey benim akılsız başım! Gönül işine akıl erer mi hiç? 

Gönül bu ne sağı belli ne solu. Sen yorulsan da o hep dinç,

Severek saraydan çıkıp girer bir eve; duvarları beyaz kerpiç,

Dünya cehenneme dönse ona yeter bir günlük sevinç.

Neden boyun eydim ki o azgın, uslanmaz gönlüme? 

Daha yirmi yaşındayken düşman oldum güzelliklere,

Bittim, tükendim, dayanamıyorum artık sevdiğim hasretine,

Bir ayağım çukurda bir gözüm kör ölmek istiyorum elinde...', 'Heyhat deli gönül! Artık yeter... Elini eline vermedin; bakışına bakmadın zamanında, Nice anlamı sırtlanmış gözleri keskin bıçaktan beter, Ş...', ARRAY['Türk Edebiyatı','Şiir','Ekrem Öğdüm']::text[], 8.5, '{"poet":"Ekrem Öğdüm","poet_slug":"ekrem-ogdum","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/deli-gonul-33-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dertlerim', 'dertlerim-ekrem-ogdum-r763u', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dertlerim yüzünden boğazıma kadar battım,

Ellerimden tutup ta kaldıracak kimseyi bulamadım,

Dertlerime derman için her şeyimle çabaladım,

Ama nafile!  Olmuyor olmadı işte yapamadım...

Ellerimde ayaklarımda fer kalmadı bu yüzden,

Soğuktan üşüdü titremeye başladı cüssem,

Kendime güvenim kalmadı, korkuyorum gelecekten,

Ama sabredeceğim, bende güleceğim yeniden...

Beni dinle ey kara bahtlı, kara yazılı başım! 

Sayısız çile çektim fakat hala gençtir yaşım; 

Öldüğüm zaman kara kefene sarılsın naaşım,

Belki o zaman son bulur derdi dermansız yaşamım...

Siz hiç gördünüz mü ölmeden mezarını kazanı? 

Kapkara kefeni ölmeden vücuduna saranı? 

Toprağın azap dolu sinesine uzanıp yatanı? 

Daha ölmeden çürüyüp de toprak olanı? 

İşte ben bunların hepsini yaşayanlardanım,

“Ben kimim” diye her gün kendime soranlardanım,

Dertlerim gözlerimi kör etmiş zindanlardayım,

İsyan edecek halim yok ama isyanlardayım...

Her gün sabahlara kadar sigaramla ağlıyorum,

Söyleyecek sözüm kalmadı artık bende susuyorum,

Biçare Ekrem’in dertlerinin dermanını arıyorum,

Dertlerine derman bulacağıma nedense inanamıyorum...', 'Dertlerim yüzünden boğazıma kadar battım, Ellerimden tutup ta kaldıracak kimseyi bulamadım, Dertlerime derman için her şeyimle çabaladım, Am...', ARRAY['Türk Edebiyatı','Şiir','Ekrem Öğdüm']::text[], 8.5, '{"poet":"Ekrem Öğdüm","poet_slug":"ekrem-ogdum","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/dertlerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık', 'ayrilik-ekrem-ogdum-pck0w', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gökten taş yağsaydı bu kadar düşünmezdim,

Su yerine kan aksaydı bu kadar özlemezdim,

Sevgin o kadar sardı ki yüreğimi sana nasıl anlatsam,

Ayırdı ellerimizi ayrılık ben onun için bu kadar dertliyim...

Hasret tüm gücüyle üzerime yüklenmiş parçalarken ruhumu,

Gurbet ile özlem ele hazırlarken hazin sonumu,

Tam gözlerinde aşkı bulmuşken değiştirdim yolumu,

Sarıldı bedenime ayrılık bu benim boynumun borcu...

Önce vatan sonra canan üzülme sakın sevdiğim,

Gül ki güleyim, öl de öleyim ama sakın gel deme sevdiğim,

Vazifem kutsaldır bu vatana can vermekse veririm sevdiğim,

Allah’a şükür askerim; ayrılık beni tek üzen şey sevdiğim...

Sana kavuşacağım günü düşünüyorum da içim içime sığmıyor,

“Seni seviyorum” değişini hayal ediyorum da aklım bir türlü almıyor,

Sanki tutmuş gibiyim ellerinden bırakmak istemiyor ellerim,

Yeter artık ayrılık bırak; bırak ta sevdiğime gideyim...

Şu satırlara cevap isterdim fakat sebeplerden korkuyorum,

“Seni seviyorum” demesen bile ben bunu hissediyorum,

Mesafe ne kadar uzak olursa olsun duyuyorum

Evet biliyorum! sende beni seviyorsun! duyuyorum...', 'Gökten taş yağsaydı bu kadar düşünmezdim, Su yerine kan aksaydı bu kadar özlemezdim, Sevgin o kadar sardı ki yüreğimi sana nasıl anlatsam, A...', ARRAY['Türk Edebiyatı','Şiir','Ekrem Öğdüm']::text[], 8.5, '{"poet":"Ekrem Öğdüm","poet_slug":"ekrem-ogdum","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ayrilik-215-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir nasihat', 'bir-nasihat-ekrem-ogdum-6d09m', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Rahmet yağıyor karlı dağlara,

Daldaki zikreden yaprağa,

Yere düşen her damla,

Hakkı zikreder yeşeren doğa...

Beşer kalbi yanar paraya mala,

Paranın değeri yok giren için toprağa,

İnsan, insan olmadıkça döner hayvana,

Hayvanın aslı şudur! Hizmet eder insana...

Görmez misin vardır her şeyin bir sonu? 

Ecel geldi mi eşerler sana da bir kuyu,

Üstünü örterler kıyamete kadar uyu,

Kalktın mı hesabın sorulacak iyi bil bunu...

Daha gaflet uykusundan dönmez misin geri? 

Kabirde görürsün o müthiş melekleri,

Tattırırlar sana o zaman narlı ateşi,

Aklını başına devşir zamanı gelmedi mi?', 'Rahmet yağıyor karlı dağlara, Daldaki zikreden yaprağa, Yere düşen her damla, Hakkı zikreder yeşeren doğa... Beşer kalbi yanar paraya mala, ...', ARRAY['Türk Edebiyatı','Şiir','Ekrem Öğdüm']::text[], 8.5, '{"poet":"Ekrem Öğdüm","poet_slug":"ekrem-ogdum","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bir-nasihat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arkadaşıma', 'arkadasima-ekrem-ogdum-ir8sg', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir sıkıntı var gurbet deryasının içindeyken,

Sanki biri beni bekliyor sılaya doğru giderken,

Neden hep beni buldu bu tükenmez kötü gidiş,

Ne gelir ki elimden; yapacak bir şey yok ölürken...

Bekleyenim çok ama nafile yetişemiyorum bekleyene,

Gelip de kimse demesin “neden nem inmiş gözlerine”,

Heyhat kim bilir bendeki bu derdi Allah bilir elbette,

Ben bir insanım ne kadar haykırsam kimse gelmez sesime,

Bir gün bitecek biliyorum ama bilmediğim şey,

Bu günler biterken acaba bende biter miyim? 

Hiç merak etmedim ya ben biterken,

Kimin umurundayım ki, insanların arasında ölümü beklerken...

Of arkadaş of! Sesim çıkmaz oldu bu diyarda,

Savaşmalısın yoksa seninde farkın kalmaz oralarda,

Benim yerime haykır sılamıza sessizce,

Bunun sonu selamettir, verilen kadere sabrettikçe...', 'Bir sıkıntı var gurbet deryasının içindeyken, Sanki biri beni bekliyor sılaya doğru giderken, Neden hep beni buldu bu tükenmez kötü gidiş, N...', ARRAY['Türk Edebiyatı','Şiir','Ekrem Öğdüm']::text[], 8.5, '{"poet":"Ekrem Öğdüm","poet_slug":"ekrem-ogdum","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/arkadasima-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Askerim', 'askerim-ekrem-ogdum-8rj6q', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Eğer vurulursam bu yurdun ıssız bir dağında

Eğer kanım akarsa vatanımın kurak toprağına,

Eğer toprağı yorgan diye sararsam vücuduma,

Ağlama sakın ana; şunu bil ki ben askerim...

Kaç kurşun geçti kim bilir başımın üstünden

Nice ananın öcünü aldım kefere bedeninden,

Aylarca aç kaldım silahım düşmedi elimden,

Ağlama sakın ana; şunu bil ki ben askerim...

Burada düşmanı ne göz görür ne kulak işitir,

Korkma bendeki bu iman bu korkuların hepsini sindirir,

Anlıma bir namlu dayansa da cihat benim işimdir,

Ağlama sakın ana; şunu bil ki ben askerim...

Bir gün bu hasret bitecek geleceğim yanına,

Hasretle sıvanmış ellerini öpeceğim doya doya,

Eğer kavuşamaz isem benim için ağlama,

Ağlama sakın ana; şunu bil ki ben askerim...', 'Eğer vurulursam bu yurdun ıssız bir dağında Eğer kanım akarsa vatanımın kurak toprağına, Eğer toprağı yorgan diye sararsam vücuduma, Ağlama ...', ARRAY['Türk Edebiyatı','Şiir','Ekrem Öğdüm']::text[], 8.5, '{"poet":"Ekrem Öğdüm","poet_slug":"ekrem-ogdum","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/askerim-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vaz Mı Geçtim?', 'vaz-mi-gectim-halil-kesken-wux9k', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Çok değiştin son günler, vaz mı geçtin diyorsun

Senden vaz geçermiyim, yer oynasa yerinden

Dağları bile delen, Ferhat’ı biliyorsun

Dağda altın çıksa da, vaz geçermi Şirin’den? 

Ne para, ne de senden, bir kaç yıl fazla ömür

Kimseyi sevmedim ben, seni sevdim derinden

Sen gözümün nurusun, yaksan da olup kömür

Hangi kul vaz geçer ki, gözlerinin ferinden? 

Biz artık sadakatle, bir ömüre kök saldık

Hangi fırtına söker, bu kökleri yerinden? 

Benim baş tacım değil, başımla birsin artık

Hiç kimse ayrılır mı, vaz geçer mi ser’inden?', 'Çok değiştin son günler, vaz mı geçtin diyorsun Senden vaz geçermiyim, yer oynasa yerinden Dağları bile delen, Ferhat’ı biliyorsun Dağda alt...', ARRAY['Türk Edebiyatı','Şiir','Halil Kesken']::text[], 8.5, '{"poet":"Halil Kesken","poet_slug":"halil-kesken","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/vaz-mi-gectim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hadi Bana Bir Şiir Oku', 'hadi-bana-bir-siir-oku-galip-sinecikli-6ui5p', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ben senin,

En çok leylak kokan,

Belik belik saçlarını sevdim,

Kekik kokan tenini sevdim,

Bir kardelen gibi,

Asi bakışlarını sevdim,

Çağla yeşili gözlerini,

Pamuk yumuşaklığındaki,

Yumuk yumuk ellerini sevdim,

Bebek gibi masum gülüşünü sevdim,

Mesela,

Beni hoyrat öpüşünü sevdim,

Dağ çileği tadındaki dudaklarını,

Kakülünü, zülüfünü,

En çok ta,

'' S '' leri basık söyleyen dilini sevdim,

Ben senin herşeyini,

Ama herşeyini çok sevdim de,

Bir tek,

Senin beni sevmeyişini sevemedim.

Hadi bana bir şiir oku...', 'Ben senin, En çok leylak kokan, Belik belik saçlarını sevdim, Kekik kokan tenini sevdim, Bir kardelen gibi, Asi bakışlarını sevdim, Çağla ye...', ARRAY['Türk Edebiyatı','Şiir','Galip Sinecikli']::text[], 8.5, '{"poet":"Galip Sinecikli","poet_slug":"galip-sinecikli","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/hadi-bana-bir-siir-oku-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MİNE(Akrostiş)', 'mi-ne-akrostis-muzaffer-erdogan-uf3jj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'M azinin hayalini düşlerimde ararken

İ   çim bir tuhaf oldu karşımda sen varken

N asıl teklif edeceğimi düşündüm ama çok erken

E tkilediğini düşündünmü hiç adıma şiir yaz derken...!', 'M azinin hayalini düşlerimde ararken İ   çim bir tuhaf oldu karşımda sen varken N asıl teklif edeceğimi düşündüm ama çok erken E tkilediğini...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Erdoğan']::text[], 8.5, '{"poet":"Muzaffer Erdoğan","poet_slug":"muzaffer-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/mine-akrostis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'HÜLYAM(Akrostiş)', 'hulyam-akrostis-muzaffer-erdogan-0c6as', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'H asretini çekerim inan arayıp sormadığında

Ü zerine selatü-selamlar okurum beni yormadığında

L eylanın mecnuna olan hasretini hiç duymadınmı

Y anlızlığında beni mecnunun yerine koymadınmı

A nlat güzelim sen kimsin ve nesin

M erak et kimliğimi bırak sana zaman söylesin...!', 'H asretini çekerim inan arayıp sormadığında Ü zerine selatü-selamlar okurum beni yormadığında L eylanın mecnuna olan hasretini hiç duymadınm...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Erdoğan']::text[], 8.5, '{"poet":"Muzaffer Erdoğan","poet_slug":"muzaffer-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/hulyam-akrostis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '.Gömdüm Toprağa Bedduayla', 'gomdum-topraga-bedduayla-hulya-karaca-f5rnp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kara gözlüm şiir sözlüm, vefasız sevgilim

İnsafsız taş kalpli platonik sevgim

Bedduların en büyüğü başında olsun

Sevdaların en çekilmezi kaderine dolsun

Hançerle parçaladın yüreğimi 

İç şimdi kadehinde zehiri

Bak bırakıp gittiğinin gözlerine

Bak ki gör çığlık ve feryatlar içindeki isyanı

Dönme artık istemem yalancı çehreni

Sorma bırak gitsin her zaman yaptığın gibi

Cehennem azabı sarsın tüm bedenini

Azrail olsun tek kapını çalan

Zebaniler olsun sana hesap soran

Gönül gözlüm, sevdamın küllerini al

Alda savur poyraz rüzgarlara

İstemem çalma artık kapımı

Sana geleceğim tek yer mezarlık olsun

Mezar taşın olsun benimle konuşan 

Saf ve temiz duygularımı toprağına gömeyim

Toprağın olsun benim yarenim

Toprağın olsun gözyaşlarımı döktüğüm 

İçimde cinayet işlemişte olsam

Seni gömdüm o kara toprağa

Seni sildim siyah kalemle yazdığım kağıttan

Gömdüm seni zor olsada

Dana ettiğim tek dua

Ben sormadım Allah sorsun sana

Ben kıyamadım Allah versin ceza', 'Kara gözlüm şiir sözlüm, vefasız sevgilim İnsafsız taş kalpli platonik sevgim Bedduların en büyüğü başında olsun Sevdaların en çekilmezi kad...', ARRAY['Türk Edebiyatı','Şiir','Hülya Karaca']::text[], 8.5, '{"poet":"Hülya Karaca","poet_slug":"hulya-karaca","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/gomdum-topraga-bedduayla-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duymadin', 'duymadin-fatih-vapur-0wuew', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Nerede gezdigini bilmeden

arkandan geldim.

Seni hep ucarken gördüm, ben kanatsizken

Kayboldugumda oldu senin yaninda.

Hep ümit dolu gördüm seni, ben caresizken.

Susarken konustum seninle 

göreceksin diye korktum

sevisirken beni,

duymadin ben sana haykirirken

nerede oldugunu bilmeden

arkandan gelmezdim

ölecegini bilseydim...

Izmir (1998)', 'Nerede gezdigini bilmeden arkandan geldim. Seni hep ucarken gördüm, ben kanatsizken Kayboldugumda oldu senin yaninda. Hep ümit dolu gördüm s...', ARRAY['Türk Edebiyatı','Şiir','Fatih Vapur']::text[], 8.5, '{"poet":"Fatih Vapur","poet_slug":"fatih-vapur","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/duymadin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sihirsiz Masal', 'sihirsiz-masal-sahan-coker-iww72', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '…Şahidim olmadı. Şehir, bebeklerin sımsıkı ve yumuk ellerinde uyuyordu.Kırılacakmış  gibi duran,kara bileklerin,çay bardağını gerdanından tutan, zarif ellerin celladım gibi boynumda geziyordu..Kokumuzu solurken avcılar, geceye karışan tıkırtılardık..Ve zaten…

Ölüm gözlüm… 

Yaşamasak ta olurdu bu sihirsiz  masalda…

Çinko damı gagalarken

O şarkıda ki  yağmurlar

Ve hiç gelmeyecek sandığım

Sabah

Örümcek ağından telli duvak biçen ağartı

Çıktı geldi de

Dudakların akrep gibi

Kendini zehirledi

Oysa hep susmuştuk

Yıllar dedin

Ne çabuk geçti değil mi? 

Manzarasız evlerde

Haritasız büyüdük biz

İyi çocuktum

Korkunçtum

Çıktım gittim

Köpekler gibi acı çekerek

Ağlayamadım  güldüm…

Bir daha kimse görmedi beni…

Böyle gülerken…', '…Şahidim olmadı. Şehir, bebeklerin sımsıkı ve yumuk ellerinde uyuyordu.Kırılacakmış  gibi duran,kara bileklerin,çay bardağını gerdanından tu...', ARRAY['Türk Edebiyatı','Şiir','Şahan Çoker']::text[], 8.5, '{"poet":"Şahan Çoker","poet_slug":"sahan-coker","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/sihirsiz-masal-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olsun', 'olsun-murtaza-yildirim-ahz3u', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Meyil verme şu dünyanın süsüne,

Güllerini derecek kadar olsun

Şaşırıp yönünü tersine dönme,

Muradına erecek kadar olsun.

Helalinden kazanmalı doğruca,

Hesabını verecek kadar olsun,

Günahlara batma, yaşa usluca,

Cevabını verecek kadar olsun.

Sen seni bil,eli düşman edinme,

Korkusuzca yatacak kadar olsun,

Sakın dost sırrını yerlere serme,

Aynı yüze bakacak kadar olsun.

Sözü ham söyleme, kaba söyleme,

Usul söyle, duyacak kadar olsun,

Akıl nimetini heba eyleme,

Ak yüzünü yuyacak kadar olsun.', 'Meyil verme şu dünyanın süsüne, Güllerini derecek kadar olsun Şaşırıp yönünü tersine dönme, Muradına erecek kadar olsun. Helalinden kazanmal...', ARRAY['Türk Edebiyatı','Şiir','Murtaza Yıldırım']::text[], 8.5, '{"poet":"Murtaza Yıldırım","poet_slug":"murtaza-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/olsun-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Diyarbakır sedası', 'diyarbakir-sedasi-mehmet-selim-tolay-57p65', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir masal başladı

ucunda benim tanık

gözleri al al sünbül

saçları tel tel bildik

neydi anlayamadığım

hayat dolu seslenişinden

büyük büyük esrarengizliğinden

mahzunluğun elifi gizli bu kızın gözlerinde

masumluğun öfkesi...

sordum ona nerelisin il il dolaştır benliğinde

hangi diyarın hayat dolu sessizliğisin Türkiyemin bebeğinde

hadi kaldır ellerini at bedenime

süzülsün ruhum senin en serin gölgelerinde

dedi diyarbakırlıyım

coşkulu gür bir sesle

annemim memleketinde çıktım hoş bir gezintiye

hangi saraydı bilmem

kanında gizlenen hangi bahar...

bu kızın gözlerinde kocaman bilinirlik var

bir masal başladı adı sevdamı bilmem

bir yokoluşbaşladı adı aşkmı bilmem...

belirgindi zaten hayat dolu oluşundan

kaybettiğim annemi gözlerinde bulacağımdan

dehlizlerin kervanlarında konaklayacağımdan

belirgindi sesinin yansımasından,

hissettimi bilmem yayılan kalbimdeki kokuyu

anladımı yoksa yalnızlığımın haritasını

girdimi yoksa nasılsınların en acımasız durağına

adım adım

benim diyarbakırlım

benim diyarbakırlım

bir ses bekleroldum işçi dudaklarından

bir terennüm

bir nefeski rüzgarında kaybolduğum

bereketli topraklarında

gül gül sevdalara garkolduğum

bir ses

bir masal başladı

ucunda benim tanık

gözleri al al sünbül

saçları tel tel bildik.

03.01.2005', 'Bir masal başladı ucunda benim tanık gözleri al al sünbül saçları tel tel bildik neydi anlayamadığım hayat dolu seslenişinden büyük büyük es...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Selim Tolay']::text[], 8.5, '{"poet":"Mehmet Selim Tolay","poet_slug":"mehmet-selim-tolay","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/diyarbakir-sedasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aldırma', 'aldirma-ali-galip-sari-k63wq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yüreğinden sanki bir şey çalmışlar,

Gözlerin çok mahzun bakıyor can be...

Sanki yüreksizler esir almışlar,

Gözlerin  çok mahzun bakıyor can be...

Aldırma yıl geçer, mevsimler çürür,

Hayat peşi sıra umudu sürür,

Bir gün bu kervan da umuda yürür,

Gözlerin yok yere ağlıyor can be...', 'Yüreğinden sanki bir şey çalmışlar, Gözlerin çok mahzun bakıyor can be... Sanki yüreksizler esir almışlar, Gözlerin  çok mahzun bakıyor can ...', ARRAY['Türk Edebiyatı','Şiir','Ali Galip Sarı']::text[], 8.5, '{"poet":"Ali Galip Sarı","poet_slug":"ali-galip-sari","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/aldirma-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tpk -b', 'tpk-b-akin-akca-p1pqo', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '1. Bitmez Koza

İşte Kozmik yumurta, her şey onun içinde! 

Yavaşça yaklaşıyorum, sanki ürkütecek bir şey varmış da! 

Özenle soyduğum kabuğunu anı olarak parçalara ayırıp ceketimin cebine atıyorum … 

Beynin kıvrımları gibi şeyler var etti kendini! ! nerede ne var, ya da ne bulmalı ya da düşünerek gelmiştim buraya ne? 

Bakıyorum, araştırıyorum … kolay değil, ormansal ve kendime yapacağım kısa sürede bu orman göletindeki nöron bileşenlerinden beynin bir sal. 

Yürek şekilli bir oluşum sürükleniyor merkeze, bunu, görüyorum! O çok ötede ama yüzüyor, ulaşmak için bir yere, hissediyorum. 

Odağında olmasa da böyle merceğin- ki zaten bir çekirdeği olsa idi evrenin, dışı da olmaz mıydı- gidiyor O’na doğru. 

Peki O kim, veyahut nerede? bilen var mı, yoksa bilenler saklandı mı? 

Ya da ben diyeyim “Bilenler sezgisel düzeyin çok ötesindeki bir sis olmanın koşulu olarak hep orda zaten vardıydı da bundan mı asla oluşmamışlardı? 

Ah, kemirgenler dizgesi, derince boyunlu bir zürafanın mamut eşiğinde çizgileri yoktur hem Afrika zebrasının yine de! 

Şimdi vahşilerin arasına geldik: kiminin dudağı sallantılı, kiminin boynu pek çok halkalı; 

sormak günah olur Amerikada’kiler peki niye şen tabelalar önünde poz verir ve onların ne diye var

hava atmaya pahalı arabaları da zarar görmüş ruhları? Evet, bu kadar da keskin olur yarın ucu bazen, 

koca şatolar barındıran; çünkü düzeltmek içinse bir terzinin naftalinlediği doku huzmesinin bir ceketin 

veya bir pantalonun, içi çıkar da durur ve dışı da içine.. devamlı biçimde.. ki usta mıdır terzi de o da ayrı! ! 

*

Derken su yükseliyor ve içine kaparak, turuncu portakal kasesinin bulunduğu odaya geri yontuyor! Gariptir ki, sevmiştim burayı: 

belki de ‘sevmiştim’ dememden daha çok, ‘burayı’ deyişimden anlaşılmalı sevmek eylemim bu mevkiyi! ! Çünkü öyle tuhaflıklar peydahlanıyor ki 

insan hayatında, o anlayacaktır karşısına çıkan şu efsunları kuvvetlendirdikçe kendi hayal gemisi güvertesindeki miço yer silenlerini…

Ben tekrar geri gidiyorum, sular tekrar geldi, ama bu sefer beyni göremedim; kozmik yumurta gitmişti. 

Demek geceleri oksijen depolayıp yeryüzüne, yaşatan bizleri, bitkiler de hareketlenmişti ya da her zaman öyleydi! 

Ne nedir, nasıl? Yeniden beni zorla götürdükleri izbe şehre doğru kulaç atmak için dalmak kutsal nehre; 

fakat bu seferki kendi isteğimle… Yumurta çekiyor beni, şu yumurta çekiyor bir memeli cinsini? 

Nöronlar kayıplarda, bomboş bir kozmik yumurta: neden gördüm ki şimdi böyle? ? 

Ya neyi, nasıl gördüğümü hangi olay dürtüsü açıklar nasıl, nereden biliyorum, örgüsünü seçemediğim bir şeklin? 

Orada bir oluşum yoksa izlemediğim; ben neyim, neredeyim, nasıl buradayım, ya? 

Nehir neydi yüzeyinde kulaç çırpındığım? Halbuki şimdi bu yumurtanın iç çeperinin kabzasının tozunu bile almıyorum! 

Nihayet düşünce çarpıştırıcımı çıkaracağım için mutluyum: 

İnsanın bulandırdığında zihnini, organizmanın sorular; işte cebimden çıkarıyorum küçük gerecimi, geçtiğinden yorgunluğum.

Daha etraflı düşünmek lazım gelir: rus ruleti masasına damlıyorum dolu kovanların bir tabancanın; diğer yana, iç çeperi falan bırakırken.

ama o çembere de hürmet gerekmez mi, o ulaştırdı beni bu bilmediğim diyarlara…

Ve …… Asla göremeyeceğim belki de, ne var; 

sırlar perdesinin değil gerisinde, onun izdüşümü.. aklım, fikrimde.

Ellerim tırmanmakta bir dağdan, kasenin eteğindeymişim meğer. Dalgalar aşağıda şu an ne var ki; 

demin beni mi dövmüşler, yerine kayalıkların? ? Bilemedim, işte ama demiştim; ‘belki de asla düşüncemi bilemeyeceğim’ …

Ancak tek şey olsa da ilk kez  diyorum; ‘ellerim taşımış beni, bunu da, her zaman için ila şu an öğreniyorum’.

2. Aranan Orman

Hareket eden figürleri bir resmin, asılı duvarda! 

Çanağın içinde bıcırdıyor Merlyn, çanağın içinde… Ve yaşadığı mağarası onun, o da mağaranın içinde. 

mağara, sonsuzluktan gelen bir odunun gövdesinde.. korunuyor, kökleri yeryüzünü kapsayan, yeşilin ve

mavinin ardıllarını.. ve dev ağacın; görünmez, yemyeşil dalları… her geçen saniye fakat, imparatorluğun sınırları genişliyor:

Merlyn, oldukça adil halbuki davranmıştı? Ancak, dünya sınırları yer yüzeyinde olmalı? 

Ağaç ise, muğlak ormanda barınıyor. muğlak orman kasenin gözbebekleri. Turuncu dalgalar aşındırıyor, kayalıkları aşağıdaki. 

Diğer odalara bakmıştım, yalnız başıma araştırdım; hepsinin kapısı kilitlenmişti. Artık kasenin içine inmeliyim.

Görev de tamamlanmadı ama: kapıları açana kadar yok  yok. Bu işi de bitirip öyle inmeli.', '1. Bitmez Koza İşte Kozmik yumurta, her şey onun içinde!  Yavaşça yaklaşıyorum, sanki ürkütecek bir şey varmış da!  Özenle soyduğum kabuğunu...', ARRAY['Türk Edebiyatı','Şiir','Akın Akça']::text[], 8.5, '{"poet":"Akın Akça","poet_slug":"akin-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/tpk-b-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Güzel Şeysin', 'ne-guzel-seysin-nedim-saatcioglu-wm8qs', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Mavi gökyüzünde bir tutam pamuk

Gelincik bağında bir dal gibisin

Sanki yeni açmış pembe tomurcuk

Allah’ım Yarabbim ne güzel şeysin

Saçların ipekten gözlerin kömür

Dudağın ateşten tenin bir ömür

Çözülmez kalbime vurduğun mühür

Allah’ım Yarabbim ne güzel şeysin

Adımlar ardında pervane olur

Görenler yolunda divane olur

Kıskanır sokaklar virane olur

Allah’ım Yarabbim  ne güzel şeysin

============================================ 

Beste ; Cem Adalı

Albüm ; Cem Adalı', 'Mavi gökyüzünde bir tutam pamuk Gelincik bağında bir dal gibisin Sanki yeni açmış pembe tomurcuk Allah’ım Yarabbim ne güzel şeysin Saçların ...', ARRAY['Türk Edebiyatı','Şiir','Nedim Saatcioğlu']::text[], 8.5, '{"poet":"Nedim Saatcioğlu","poet_slug":"nedim-saatcioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ne-guzel-seysin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ceylan', 'ceylan-mustafa-ceylan-jo4wo', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ayrılık ateşi yakar, kavurur

Gözümden akanlar sel ceylan ceylan

İçimde hasretin dağ gibi durur

Bekletme yollarda gel ceylan ceylan

Sevda kervanını çeken baş idim

Bir kutsal yük gibi aşkı taşıdım

Yapayalnız kaldım, dondum, üşüdüm

Esiyor bağrımda yel ceylan ceylan

Ağlayan sazımın telleri kopuk

Kader taylarından yemişim topuk

Düştüm uçuruma kanadım kopuk

Elime el uzat el ceylan ceylan

Ne Mecnun, ne Ferhat değilim inan

Kurumuş yaprağım dalda çırpınan

Birgün kurumadı avcumda kınan

Hatırlatır seni bil ceylan ceylan

Ben de bir Ceylan’ ım düşmüşüm dile

Yolunda bekleyen köleyim köle

Göğsünden çıkarıp mendilin ile

Gözümün yaşını sil ceylan ceylan', 'Ayrılık ateşi yakar, kavurur Gözümden akanlar sel ceylan ceylan İçimde hasretin dağ gibi durur Bekletme yollarda gel ceylan ceylan Sevda ker...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ceylan-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gurbette Sıla Derdi', 'gurbette-sila-derdi-mustafa-ceylan-ai3pp', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Benden selam söylen Elmadağ’ına

Hasretim, büründüm karalarına

Yalvardım, yakardım; zalim feleğin

Yazmadı kalemi sıralarına

Fabrika bacası savurmuş duman

İşsizlik, yoksulluk getirmiş zaman

Bu nasıl çiledir, of aman aman! 

Bir melhem olaydım yaralarına

Kargalı Bağları dönmüş toprağa

Betonlar dikilmiş bahçeye, bağa

Düşmüş kelebekler, ölmüş kurbağa

Çağlayıp dolsaydım derelerine

Kurumuş çeşmeler, yok olmuş kuyu

Köylüm de gözlerden silmiş uykuyu

Akdeniz’ den alıp tonlarca suyu

Fıskıye olaydım seralarına

Bir serçe kuşuna bakar kamışlar

Zindana dönünce baharlar, kışlar

Komşudan yaylayı icarlamışlar

Karşılık olaydım kiralarına

Ey Ceylan, gurbete dolanmış paçan

Böyl’olur demişler zamansız göçen

Özlem çiğdemidir gözümde açan

Bir kuzu olaydım meralarına', 'Benden selam söylen Elmadağ’ına Hasretim, büründüm karalarına Yalvardım, yakardım; zalim feleğin Yazmadı kalemi sıralarına Fabrika bacası sa...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/gurbette-sila-derdi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seher Yeli', 'seher-yeli-mustafa-ceylan-ipmrx', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Karac’oğlan ne ki benim yanımda? 

Tutuşan bağrıma es seher yeli

Yâr hasreti damar damar kanımda

Bıçak vur, kökünden kes seher yeli

Hani nerededir çeşmenin başı

Güvercin topuğu, ak göğsü, kaşı? 

Gelsin de öğrensin betonu, taşı

Yoktur sazı bile, sus seher yeli

Uğraşma boşuna, yorma kendini

Bulamazsın güzellerin merdini

Hasta cüzdan ile geçim derdini

Fil gibi üstüme bas seher yeli

Yaylaya gökdelen dikti ağalar

Çiğdem, çiçek değil betondur yollar

Bir tek kuşa bile hasrettir dallar

Çamlar salonlarda süs seher yeli

Eğil ey Ceylan’ım kahredip eğil

Bu devran böyledir, bozulup dağıl

Güneşle uyanan tül perde değil

Her bir pençerede yas seher yeli', 'Karac’oğlan ne ki benim yanımda?  Tutuşan bağrıma es seher yeli Yâr hasreti damar damar kanımda Bıçak vur, kökünden kes seher yeli Hani nere...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/seher-yeli-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Divaneyim Ben', 'divaneyim-ben-mustafa-ceylan-vjho7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Nedir suratının hali diyorlar

Sokağa bir çıksam deli diyorlar

O ahu gözlünün kulu diyorlar

Yâr senin aşkından divaneyim ben

Benim olacaksın yazdım deftere

Göğsümün solundan düşürmem yere

Gurbet havasıyla helikoptere

Yâr senin aşkından pervaneyim ben

Gelirsen noksanlar, yarımlar tamdır

Gündüze el pençe duran akşamdır

Aklıma bir düşsen, içim bayramdır

Yâr senin aşkından şahaneyim ben

Sevda dedikleri solmayan resim

Benden bana yansır kaybolan sesim

Cümle kara günler oldu adresim

Bilinmez sebebim, bahaneyim ben

Çılgın karıncayım senin izinde

Ceylan yüreğimi uyut dizinde

Kürek mahkumuyum aşk denizinde

Bilsem anlatırım daha neyim ben?', 'Nedir suratının hali diyorlar Sokağa bir çıksam deli diyorlar O ahu gözlünün kulu diyorlar Yâr senin aşkından divaneyim ben Benim olacaksın ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/divaneyim-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur,sen ve ben', 'yagmur-sen-ve-ben-murat-ceylan-1ksu4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bu gece kararmış gökyüzü sanki içimdeki sevda misali

Yağmur havası var,hem gökyüzünde hem de gözlerimde

Benim gibi gökyüzüde kızmış,yoksa öfkeyle çakmazdı şimşeklerini

Yağmur,sen ve ben var sanki kainatın her yerinde

Yağmur kokusu girdi mi genzime,gözlerimde bir drama filmi oynar sanki

Yağmurlu bir havada aşık olmuştuk,damlalarla ayrılmıştı ellerimiz

Ne vakit bir damla gökyüzünden intihara kalkışsa bir ağlama sarsar benliğimi

Toprağa düşen ölü yağmur damlalarına bıraktık,sevdamızı biz

Ne durursun gökyüzüne hakim yağmur,yağsana başıma suskun durma

Ben gözyaşımla sen damlalarınla yarışırcasına ıslatalım aşkı,sevdayı

Bakalım bu gece hangimiz galip çıkacak bu anlamsız yarışta

Bakalım hangimiz önce pes edecek gözyaşları mı yoksa damlalar mı    

Yağmur bak sen bir yağmaya başla başlayacak benim beddualarım

Önce yüce dağların zirvesine çıkacak sonra oturacak vefasızların yüreğine 

Korkma senin damlalarınla dinmez fırtınam,sönmez yangınlarım

Ama sen üzülme yağmur,sığacak fırtınam,yangınım bedenim gibi kefene

Sanki yağınca yağmur bütün acılarım damlalar halinde dağılacak yeryüzüne

Kurumuş yüreğim sanki birden yeşeriverecek o serin damlalarınla 

Hadi yağ artık,açtım avuçlarımla,yüreğimi,düş artık yüzüme

Bu gece bir tek duam var Allah’tan yağmur yağsın yeter bana

Gözlerim beklerken yağmuru sabaha karşı uyuyakalmış 

Yağmur yağmasını istedim,nasipte rüyamda seni görmek varmış

Uyandığımda içimi bir korku,etrafı toprak kokusu sarmış

Yağmur ben uyuduğumda sabaha karşı yağmış

SENİN BANA HARAM OLDUĞUN GİBİ 

YAĞMURLA AĞLAMAKTA BANA HARAMMIŞ

                                                             Murat CEYLAN', 'Bu gece kararmış gökyüzü sanki içimdeki sevda misali Yağmur havası var,hem gökyüzünde hem de gözlerimde Benim gibi gökyüzüde kızmış,yoksa öf...', ARRAY['Türk Edebiyatı','Şiir','Murat Ceylan']::text[], 8.5, '{"poet":"Murat Ceylan","poet_slug":"murat-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/yagmur-sen-ve-ben-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlk kez', 'i-lk-kez-murat-ceylan-fhbsd', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Odam ilk kez bu kadar soğuk geliyor bana

Ve ben ilk kez bu kadar çok ağlamak istiyorum

Senli günler canlanıyor her daim hatırımda 

Ben ilk kez yağmur damlalarında seni arıyorum

İnsan hayalleri kadar büyükmüş,rüyaları kadar yalan

İlk kez hayallerim kadar uzaklaştın,rüyalarım kadar yalan oldun

Bu koca sevdadan bir avuç hiç sana ve bana kalan

Sen ilk kez beni böyle çaresiz,böyle deli divane ortalarda koydun

                                                    Murat CEYLAN', 'Odam ilk kez bu kadar soğuk geliyor bana Ve ben ilk kez bu kadar çok ağlamak istiyorum Senli günler canlanıyor her daim hatırımda  Ben ilk k...', ARRAY['Türk Edebiyatı','Şiir','Murat Ceylan']::text[], 8.5, '{"poet":"Murat Ceylan","poet_slug":"murat-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ilk-kez-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hoş Seda', 'hos-seda-yavuz-agir-u5ubc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Evliyalar diyarında

Erenlerin sofrasında

Yiğitlerin yüreğinde

Hoş seda var hoş seda

Bizim köyün yamacında

Şarıl şarıl akan sularında

Gurbet elin diyarında

Hoş seda var,hoş seda.

Eski dostlar eyvanında,

Güzel annemin kucağında,

Ata,dede ocağında

Hoş seda var,hoş seda.

Gönlümün bitmez hayalinde

Gül yüzlü yarin şemalinde

Hoşgörünün temelinde

Hoş seda var,hoş seda....', 'Evliyalar diyarında Erenlerin sofrasında Yiğitlerin yüreğinde Hoş seda var hoş seda Bizim köyün yamacında Şarıl şarıl akan sularında Gurbet ...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Ağır']::text[], 8.5, '{"poet":"Yavuz Ağır","poet_slug":"yavuz-agir","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hos-seda-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm Olursa Aşk Biter Mi?', 'olum-olursa-ask-biter-mi-muge-arikan-0yfcg', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Tanımadığım bir yüze aşık oluyorum gitgide,

Kalbime birşey oluyor gündengüne

Napmalıyım bilmiyorum her geçen güne

Ölmelimiyim yoksa öbür güne

Kalbimi durdurmalımıyım onu unutmak için,

Beynimi aldırmalımıyım onu unutmak için

Tanrım al artık şu canımı onu unutmak için 

Canımı veriyorum aşkım seni unutmak için 

Aşkımız için bizim aşkımız için

Korkuyorum aşkım öldükten sonra seni unutamamaya

korkuyorum,

Ruhumda senin aşkının çizgilerinin kalmasından

korkuyorum,

Ama tek birşeyden korkmuyorum aşkım,

Senin için kalbimi,canımı vermeye korkmuyorum

Ve şuan inan aşkım senin için

CANIMI VERİYORUM....!', 'Tanımadığım bir yüze aşık oluyorum gitgide, Kalbime birşey oluyor gündengüne Napmalıyım bilmiyorum her geçen güne Ölmelimiyim yoksa öbür gün...', ARRAY['Türk Edebiyatı','Şiir','Müge Arıkan']::text[], 8.5, '{"poet":"Müge Arıkan","poet_slug":"muge-arikan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/olum-olursa-ask-biter-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlem', 'ozlem-songul-ucar-zjf8s', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Suya hasret çiçek gibi,

Muhtacım sana...

Güle hasret bülbül gibi özlem doluyum.

Toprağa kenetlenmiş bir çınarın kökleri gibi,

Kucaklamak isterdim bu akşam seni..

Suya kanan çiçek gibi...

Güle konan bülbül gibi...

Bir çınarın kökleri gibi...

Sahili döven dalgalar gibi hırçın yüreğim.

Düşüncelerim,

Gökyüzü gibi bulanık ve sessiz...

Hırçınlığı bitirip,sessizliğe rest çekip,

Ağlamak isterdim bu gece...

Denize düşen damlalar gibi...

Geceyi saran sessizlik gibi...

Senin gibi...

...gökyüzü gibi...', 'Suya hasret çiçek gibi, Muhtacım sana... Güle hasret bülbül gibi özlem doluyum. Toprağa kenetlenmiş bir çınarın kökleri gibi, Kucaklamak ist...', ARRAY['Türk Edebiyatı','Şiir','Songül Uçar']::text[], 8.5, '{"poet":"Songül Uçar","poet_slug":"songul-ucar","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ozlem-199-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Gün', 'bir-gun-songul-ucar-bkhmx', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir gün:

Bakarken ufka,yaşam denizinin kıyısında...

(Güneşin)

Altın sarısında; saçlarının taze bahar kokusu,

Kızıl alevlerinde; dudakların sevdiğim.

Gece mavisinde okyanusların; 

Uzay gözlerinden bir yıldız akşamlarıma...

Bir başka gün:

Bakarken yarınlara,aynı denizin rıhtımında; 

Bir martı çığlığında hayalin,

Bir martı kanadında savaşım,

Bir martı sıfatında umutlarım...

...uçar,gider sevdiğim.

Belki aynı gün:

Bakarken kıyıya,yaşam denizinin ufkundan; 

Bir martı çığlığında hayalim,

Bir martı kanadında savaşın,

Bir martı sıfatında umutların...

...uçar gider sevdiğim.

Elbet bir gün:

Coşarken acılarımızla ve...

...ve savaşırken o denizin ortasında dalgalarla; 

Bir martı çığlığında hayaller,

Bir martı kanadında sevgiler,

Bir martı sıfatında umutlar...

...uçar konar penceremize sevdiğim.', 'Bir gün: Bakarken ufka,yaşam denizinin kıyısında... (Güneşin) Altın sarısında; saçlarının taze bahar kokusu, Kızıl alevlerinde; dudakların s...', ARRAY['Türk Edebiyatı','Şiir','Songül Uçar']::text[], 8.5, '{"poet":"Songül Uçar","poet_slug":"songul-ucar","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/bir-gun-92-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidenin Ardından...', 'gidenin-ardindan-songul-ucar-5zq2m', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hasret çığlıklarım göğü değil,

Beynimi deler.

Özlem kokan türkülerim,

Sılayı değil kalbimi dağlar.

Eğer,

Pınarlar yanaklarımdan süzülseydi,

Hüzün uzun sürer miydi hiç bu kadar? 

Bir gün,

Kavuşmak ümidi olsaydı,

Zaman,

Soğuk olur muydu hiç ölüm kadar? 

“Dön! “desem,

Dönemezsin bilirim de...

Hayalini arar donmuş ellerim.

Resmine bakarken puslu gözlerle,

Bende sana koşsam derim; 

Cansız bedenle....', 'Hasret çığlıklarım göğü değil, Beynimi deler. Özlem kokan türkülerim, Sılayı değil kalbimi dağlar. Eğer, Pınarlar yanaklarımdan süzülseydi, ...', ARRAY['Türk Edebiyatı','Şiir','Songül Uçar']::text[], 8.5, '{"poet":"Songül Uçar","poet_slug":"songul-ucar","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gidenin-ardindan-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Baba..', 'baba-songul-ucar-4vex2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Özlem dolu yüreğimle çıkmıştım yola,

Hasret kokan türkülerle koşmuştum sana...

Sen değil cansız bedenin sarıldı bana,

Yansam...

Bitsem...

Kül olsam..

Tükensem baba...', 'Özlem dolu yüreğimle çıkmıştım yola, Hasret kokan türkülerle koşmuştum sana... Sen değil cansız bedenin sarıldı bana, Yansam... Bitsem... Kü...', ARRAY['Türk Edebiyatı','Şiir','Songül Uçar']::text[], 8.5, '{"poet":"Songül Uçar","poet_slug":"songul-ucar","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/baba-26-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Liman', 'liman-songul-ucar-hf09s', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İlkin bu limana; 

“Merhaba! “ demeye geldim yeni hayata! 

Kalbimde yepyeni bir sayfa,

Yüzümde rengarenk baharlarla...

İlkin bu limana; 

“Merhaba! “ demeye geldim yeni ufuklara.

Sonra bu limana; 

Coşkuyla geldik bir dostla.

Aynı pencereden bakıp dünyaya,

Aynı dili konuştuğum bu insanla,

Birlikte geldik bu limana,

Kadeh kaldırmaya yeni dostluklara...

Derken bu limana; 

Veda etmeye geldim insanlığıma.

Utancımı gizleyen göğün kızıllığında,

O görünmez gemiye bindirip, usulca...

O gün bu limanda,

Merhaba dedim insan olmayan insanlara.

Dün bu limana; 

Kanadım kırık geldim,gözümde yaşla.

Özde hasret,kalpte pişmanlıklarla..

Beyninde dinmez çığlık,susmak nedir bilmezya..

Dün bu limana,

Ağlamaya geldim dostum babama..

Bu gün bu limana; 

Sohbete geldim balıklarla.

Ağlayıp bulutlarla kayıtsızca,

Coşmaya med-cezirlerle umarsızca...

Bu gün bu limana,

Dertleşmeye geldim doğayla...

Bir gün bu limana; 

Son kez geleceğim,beyaz bir çarşafla.

Dudağımda titrek bir elveda,

Gözümde pınarlarla..

Bir gün bu limana,

Geleceğim ama,

Son defa...', 'İlkin bu limana;  “Merhaba! “ demeye geldim yeni hayata!  Kalbimde yepyeni bir sayfa, Yüzümde rengarenk baharlarla... İlkin bu limana;  “Mer...', ARRAY['Türk Edebiyatı','Şiir','Songül Uçar']::text[], 8.5, '{"poet":"Songül Uçar","poet_slug":"songul-ucar","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/liman-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Serzeniş...Yas...', 'serzenis-yas-songul-ucar-yge8u', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yıkılan onca hayal...

Hasreti unutturan keder...

Uyanmak istesen de bu kabustan,

Zalim dünya! 

İnsafsızca dönerde döner...', 'Yıkılan onca hayal... Hasreti unutturan keder... Uyanmak istesen de bu kabustan, Zalim dünya!  İnsafsızca dönerde döner......', ARRAY['Türk Edebiyatı','Şiir','Songül Uçar']::text[], 8.5, '{"poet":"Songül Uçar","poet_slug":"songul-ucar","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/serzenis-yas-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yiten Neydi? / Düz yazı', 'yiten-neydi-duz-yazi-serap-demirturk-fw2c7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Duvarlara resimler yaparmış mahkumlar,

Ağaçlara isimler kazırmış aşıklar,

Kumsallarda iz bırakırmış sevenler,

Ben hiç mi iz bırakmamışım yüreğinde? 



Bu sabah karar verdim onu arayacaktım. Yıllardır onu ne büyük bir sevgi ile sevdiğimi ama gururumu bırakıp da arayamadığımı söyleyecektim. Güzelim gözlerini hatırlıyorum da nasıl özlemli ayrılmıştık. 

Erkenden uyandım bu gün, traşımı oldum. Sigaramın dumanı hayallerime karışırken gazetemi aldım, tam okuyacakken Cem aradı, ''Aşağıdayım abi, hadi in.'' dedi. Kaç gündür birlikte gidiyorduk işe. Sanki yıllardır tanışıyormuş gibi nelerimizi paylaşmamıştık. Hemen indim, yeni aldığı arabası ile beni işe bırakmak hoşuna gidiyordu. 26 yıllık memuriyetten sonra yeniden çalışmaya başlamak,  zaman zaman zor geliyordu ama hayat omuzlarımızı sevmişti bir kere...inmiyordu. Sürekli konuşuyordu Cem, anlattıkları beni yormuyordu. Gençliğimin kopmuş damarlarından biri olmuştu sanki. Yarım kalan sevdamın diliydi sanki. O anlattıkça ben dalıp gidiyordum. Sonuçta bu sabah arabada gazetemi de okutturmadı. ''Abi daldın, hayrola? '' derken gerçekten benim için endişeliydi. Nasıl denir ki senin sevda coşkun, benim sönmüş derdimi depreştirdi diye. Dün sordum eski dostlara, evlenip ayrılmış dediler. Ayrılığa sevinilir mi, sevindim işte. Belki kaybolan yıllara inat birlikte paylaşılacak bir zaman dilimi yakalayabiliriz,diye düşündüm... 

Cem beni bıraktı, büfeden sigaramı aldım. Karşı yolda bir kadın,çocuğuna kızıyor; bir adam yolda oturmuş dileniyor; çiçekçi,çiçeklerini düzenliyor. Arabalar geçiyor hızlı hızlı, her birinde bir şarkı. Bir an ''Ben seni unutmak için sevmedim.'' diyen şarkıyı Tarkan''ın ezgisi kesiyor. Karşı yolda bir çocuk, kaçan topun peşinden bana doğru koşuyor. Allahım, araba geliyor. ''Dur! ! ! ! '' Kim durdu, ne oldu...yerde yatan kim? Bu kanlar kimden akıyor? Çocuk sapasağlam, çok şükür ama neden herkes başıma toplanmış. Durun, o gazete bugünün! ...Daha okumadım, okuyamadım. Üşümedim ki ben, neden örtüyorlar üstümü? Neden?', 'Duvarlara resimler yaparmış mahkumlar, Ağaçlara isimler kazırmış aşıklar, Kumsallarda iz bırakırmış sevenler, Ben hiç mi iz bırakmamışım yür...', ARRAY['Türk Edebiyatı','Şiir','Serap Demirtürk']::text[], 8.5, '{"poet":"Serap Demirtürk","poet_slug":"serap-demirturk","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/yiten-neydi-duz-yazi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Sordum', 'seni-sordum-yavuz-agir-d0rhz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Seni sordum bulutlara

Yağan deli yağmurlara

Çılgın esen rüzgarlara

Yıldızlara seni sordum.

Goncalardan güllere

Dağda açan sümbüllere

Aşık olan gönüllere

Bülbüllere seni sordum.

Denizlerde martılara

Havadaki ucan kuşlara,

Yeryüzünde tüm kullara

Usanmadan seni sordum.', 'Seni sordum bulutlara Yağan deli yağmurlara Çılgın esen rüzgarlara Yıldızlara seni sordum. Goncalardan güllere Dağda açan sümbüllere Aşık ol...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Ağır']::text[], 8.5, '{"poet":"Yavuz Ağır","poet_slug":"yavuz-agir","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/seni-sordum-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kayıp Yıllar', 'kayip-yillar-salim-yilmaz-mzwbv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Biz

      bir sel gibi yitip gitmişiz dostum.

Tutunamadan bir umut dalına sıkıca.

Çelimsiz bir poyraza bile karşı koyamadan

                                                                         adeta umarsızca.

Ne kadar kar varsa yağdırmışız

                                                      ömrümüzün baharına.

Ağlamaklıyız şimdi.

Bakmaktan utanarak geçmişteki resmimize

sığınacak bir liman ararız

                                           lime lime yüreğimize

ve nasılsa ağarmadan kalan

                                                 bir kaç siyah saç telimize...', 'Biz       bir sel gibi yitip gitmişiz dostum. Tutunamadan bir umut dalına sıkıca. Çelimsiz bir poyraza bile karşı koyamadan                 ...', ARRAY['Türk Edebiyatı','Şiir','Salim Yılmaz']::text[], 8.5, '{"poet":"Salim Yılmaz","poet_slug":"salim-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kayip-yillar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Ben Bilirim Aşk''ı-2', 'bir-ben-bilirim-ask-i-2-his-kaybi-mk-j0frr', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir Ben Bilirim Aşk''ı-2 

Sorumsuz sevdalarda 

utangaç duygularımla

siyahın üstünde beyaz tadında umut''la

nefes alıp soluksuz kalmak - yaşamak adın''a -

Belediyenin zehirlediği köpek

el açtığın insan, düşüpte yere

vururken bir dost sırtından 

iç çekmiyorsan, bunada eyvallah diyorsa yaşam 

Bir ben bilirim Aşk''ı bir''de Gönül''deki sitem 

Ayakkabısını kaybetmişse yaşam- yürüyemiyor

Bir balık kaybetti yolunu Okyanusa küskün

gönlümün nasihat dinlemeyen yanında gizlemişsen gözlerini

Bir ben bilsem Aşk''ı - gönlüme ne fayda 

Utanıp darılıp uyansan bir sabah 

ellerini açıp''ta - sen''de pişmanlıklar

Her gece yaşadığım sensizlikti - yaşasan 

Anlatması güçtü - yaşaması imkansız 

Beden Tel tel yaprak dökerken

İhanet''ti hergece beden''e

Susmak susturulmak 

Sevip''te Aşk''ı tanımlayamamak

yılgınlık,sensizlik

Bir ben bilirim Aşk''ı bir''de İçimdeki Öfke 

Sabırsız düşlerim''le Sabırtaşı hayallerim 

Gönlümün kuytusuna sakladığım sen 

Ve beni bir bir tüketen 

Bir ben Bilirdim Aşk''ı Uğrunda Ölürken...... Sende Bilmediysen! ! ! 

M.K. Versac Üsküdar........ 04/01/2005 s:22.00', 'Bir Ben Bilirim Aşk''ı-2  Sorumsuz sevdalarda  utangaç duygularımla siyahın üstünde beyaz tadında umut''la nefes alıp soluksuz kalmak - yaşama...', ARRAY['Türk Edebiyatı','Şiir','His Kaybı Mk']::text[], 8.5, '{"poet":"His Kaybı Mk","poet_slug":"his-kaybi-mk","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/bir-ben-bilirim-ask-i-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yitik', 'yitik-ahmet-volkan-c05tl', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yıllar acımasız, yıllar güçlü

Çekip gider gözünün içine baka baka.

Kaptırırsan kendini

Kaybeden hep sen olursun

Farketmezsin bile ezildiğini bir an olsun.

Bir gün SEN’le dolu zamanlarımda

Delirdiğimi duyarsan,

Anla ki bu benim suçum,

Yıllar saniyeler kadar acımasız olmasa da,

Anla ki, yarın YOKUM...

(25-05-2000  İzmit-Isparta arası Pamukkale Expresi’nde)', 'Yıllar acımasız, yıllar güçlü Çekip gider gözünün içine baka baka. Kaptırırsan kendini Kaybeden hep sen olursun Farketmezsin bile ezildiğini...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Volkan']::text[], 8.5, '{"poet":"Ahmet Volkan","poet_slug":"ahmet-volkan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/yitik-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur', 'yagmur-salim-yilmaz-24d2s', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yağmur yağıyor yağmur

Ağlıyor gökyüzü

Siyahla lacivert arası

Yağmur yağıyor

Her damlası

Bir kalp sayrısı...', 'Yağmur yağıyor yağmur Ağlıyor gökyüzü Siyahla lacivert arası Yağmur yağıyor Her damlası Bir kalp sayrısı......', ARRAY['Türk Edebiyatı','Şiir','Salim Yılmaz']::text[], 8.5, '{"poet":"Salim Yılmaz","poet_slug":"salim-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/yagmur-158-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yolculuk', 'yolculuk-salim-yilmaz-8y3li', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dün gece uçuyordum

Sultanahmet yolunda

Yeni Rakı Havayollarıyla...', 'Dün gece uçuyordum Sultanahmet yolunda Yeni Rakı Havayollarıyla......', ARRAY['Türk Edebiyatı','Şiir','Salim Yılmaz']::text[], 8.5, '{"poet":"Salim Yılmaz","poet_slug":"salim-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/yolculuk-63-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsimsiz Şiirlerim No: 1', 'i-simsiz-siirlerim-no-1-ahmet-volkan-fjab7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Silahlı süvariler dolaşıyordu karanlıkta,

Bir gölge gibi peşimdeydi ölüm,

Sevgi ise yürek derinliğinde.

Bir ceset kadar duygusal,

Bir mahkum kadar özgürdüm o an

Ölüm yaklaşıyordu! 

Nefesini hissediyordum dikenleşmiş tüylerimde.

Korkmuyordum! 

Ne kalmışsa yüreğimde 

Sevdadan yana,

Bomboş sokaklara saça saça yürüyordum.

Yıldızların ışıltısıydı,

Bir yakamozdu,

Belki de eski bir deniz fenerinin

Acıklı haykırışıydı gecenin zifrinde,

Anlatamazdım...

(13-06-2001 / 08-2004 Kocaeli-Gölcük)', 'Silahlı süvariler dolaşıyordu karanlıkta, Bir gölge gibi peşimdeydi ölüm, Sevgi ise yürek derinliğinde. Bir ceset kadar duygusal, Bir mahkum...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Volkan']::text[], 8.5, '{"poet":"Ahmet Volkan","poet_slug":"ahmet-volkan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/isimsiz-siirlerim-no-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsimsiz Şiirlerim No: 2', 'i-simsiz-siirlerim-no-2-ahmet-volkan-bzhqb', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gün usulca batarken penceremden

Yine hüzünlerde yüreğim

Bakma sen bana

Sadece sen zannediyorum ışığı,

Bu yüzden, lambayı kapatmadan uyurum ben.

Bomboş caddeleri geziyorum şimdi

Yine sırlarla doluyum içimde

Yine seninle doluyum karanlık kaldırımlarda.

Sanki karşıma çıkıverecekmişsin gibi

Sanki şimdi sırtımda hissedeceğim gölgeni..

Ayak seslerini duyar gibi oluyorum bir an

Gittikce yaklaşan.

Usulca yağan yağmur

Islatırken sokakları

Peşine düşüyorum yalnızlığımın

Lambalar adını haykırıyor sokaklara

Bir gün karşılaşıversek

Dünyanın bir yerinde

Avuçlarini kalbime değdirsem

Sonra,

Usulca bıraksam

O sırrımı eline.

Çeker gider miydin

Yoksa benimle gelir miydin

Rûyalar alemine? 

Tekrar çocuk olmak isterdim seninle

Tekrar emeklemek

Koşup terlemek

Delice şarkılar söylemek elele

Seninle büyümek

Dostluğu seninle öğrenmek isterdim

Ama sen

Çocukluğumdan daha uzaksın! ..

(08-11-2000 Isparta)', 'Gün usulca batarken penceremden Yine hüzünlerde yüreğim Bakma sen bana Sadece sen zannediyorum ışığı, Bu yüzden, lambayı kapatmadan uyurum b...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Volkan']::text[], 8.5, '{"poet":"Ahmet Volkan","poet_slug":"ahmet-volkan","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/isimsiz-siirlerim-no-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'TR 26/ Eskişiir', 'tr-26-eskisiir-fevzi-gunenc-ygc3e', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yeni şeyler yapmak gerekiyor

yeni şiirler yazmak...

Eskinin köhne duvarları arasında sıkışarak

yazdıkları da kemikleri gibi 

çürümüş ilahlara tapmaya paydos 

Gelişebilmek için ileri

daha ileri bakmak gerek

bunun gereğini yapmak için

uzun adımlar atmak gerek…

Devrim deniyor bunun adına mirim

devrimci olmak gerek

gerçi yeterince biliniyor

ama bilmeyenler için söylüyorum

devrim adına ölünüyor.

Ben bu şiiri Eskişehir''de yazdım gözlerim

Samanpazarı''nda dolaşırken avere avare

sevgili kadar eski bir dostu ararken

Zerbank''ın, Etibank''ın camlarında kendime bakarken

Porsuk kıyılarında dolaşırken yazdım bu şiiri ben...

Selam tanıdık tanımadık 

yüreği yeni bütün şehirlilere

olsa bile eski/adı...

Sevdiğim şehir Eskişehir oldu hep 

ama şiirim hiç bir zaman

eskişiir olmadı.', 'Yeni şeyler yapmak gerekiyor yeni şiirler yazmak... Eskinin köhne duvarları arasında sıkışarak yazdıkları da kemikleri gibi  çürümüş ilahlar...', ARRAY['Türk Edebiyatı','Şiir','Fevzi Günenç']::text[], 8.5, '{"poet":"Fevzi Günenç","poet_slug":"fevzi-gunenc","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/tr-26-eskisiir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Keşfin İdrâki', 'kesfin-i-dr-ki-ahmet-volkan-52p4y', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir mekan aldatmacasıydı bu yaşadığım

İzâfiyet teorilerine takılı

Zaman kaybıydı aşklarım.

4 koca kış

Artı vektörel toplamıydı kazıkların.

Uzak memleket sevdalarından

Ve sensiz hayatın 

Zulmünden mi kaçmışım? 

Hepsi yalan! 

Sanma ki sana yazıyorum

Sanma ki seni seviyorum

Fosil papatyam aç o gözlerini

Sen bende biteli 

Ne ihtillâller oldu dünyada

Gotik değil yazılarım.

Sonsuzluk ve sensizlik

İki ayrı dava

İki yıldız arasında bir çekim var ama

Gurbet başka türlü burda

Çocukların gülüşü gerçekte

Elimdeki silah bu işte.

Güneş sistemi yok muydu ki/söyle

Kopernik bulmadan önce? 

(30-11-2004 Viyana)', 'Bir mekan aldatmacasıydı bu yaşadığım İzâfiyet teorilerine takılı Zaman kaybıydı aşklarım. 4 koca kış Artı vektörel toplamıydı kazıkların. U...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Volkan']::text[], 8.5, '{"poet":"Ahmet Volkan","poet_slug":"ahmet-volkan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/kesfin-idraki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Uyarı', 'son-uyari-ahmet-volkan-qywyp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Neden bahsedeyim 

Freud’un yalanlarından mı

Tutsak özgürlüklerden bu yana

Ne mi kaldı? 

Tarih kokla biraz

II.Wilhelm ne zaman yaptırdı

O çeşmeyi? 

Richard aslan yürekli miydi

Masumları katlederken? 

Ve pişman mıydı 

Papa Urban Loritz? 

Hayatına son vermeden 

Bir kez daha düşün.

Hayır, kesme sözümü! 

Pişman mısın yaptıklarından

Nasıl olmalıydı

Ya da nasıl olmalıydın? 

Yüreği yaralı 

Çaresiz çocuk mu

Yoksa eli silahli/roketatarlı

Amerikan mıydın topraklarımda? 

Ne sanıyorsun Monika? 

(2004 – Viyana)    Boşa yaşamış bir kadın’a ithâfen..', 'Neden bahsedeyim  Freud’un yalanlarından mı Tutsak özgürlüklerden bu yana Ne mi kaldı?  Tarih kokla biraz II.Wilhelm ne zaman yaptırdı O çeş...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Volkan']::text[], 8.5, '{"poet":"Ahmet Volkan","poet_slug":"ahmet-volkan","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/son-uyari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki Damla Kan', 'i-ki-damla-kan-serap-taylan-q45c2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Nefret iki damla kan gibi

Düşer gözlerinden.

Ya tükür içindekilerini dışarılarına 

Ya bırak aksın  gözlerinden 

İki damla kan! ! 

21,01,03', 'Nefret iki damla kan gibi Düşer gözlerinden. Ya tükür içindekilerini dışarılarına  Ya bırak aksın  gözlerinden  İki damla kan! !  21,01,03...', ARRAY['Türk Edebiyatı','Şiir','Serap Taylan']::text[], 8.5, '{"poet":"Serap Taylan","poet_slug":"serap-taylan","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/iki-damla-kan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kayan Yıldız', 'kayan-yildiz-deger-ulas-turan-jtk44', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İşte ellerim al tut desem 

Gidişin öyle bir acı 

Derin bir uçurum belki 

Duruşun sessiz yokluk içinde. 

Bir varsın 

Bir yok olmuşsun kendini kandırarak 

Al desem 

Sar şu kollarımı 

Boynunda uzun bir hayat… 

Gel desem

Özlemek gibi 

İçimde kayıp bir kitap.

Sen bir aşk gibi korudun kendini kandırarak 

Ben her aşka bir daha kanayıp düştüm 

Her gece yeniden parlayıp söndüm 

Ben düşerken tuttuğunuz dileklerdi 

Sevdiğinle koyun koyuna.

Geri dön desem,

Acıların var şimdi. 

Hem onlar hem olanlar… 

Önceleri sadece sen vardın 

Ve arı bir yürek içinde çırpınan deniz. 

Şimdi yaşadığın hikâyene bir sayfa daha ekleyeceğin 

Küçük yıldızın unutulan yalnızlığı, 

Kayıyorum, 

tutmayın beni! ... 

Kayıp giden şu çaresizliğimdir, 

Belki daha da çok sevilir çocuklar

Her defasında tutulan dileklerinizde. 

Ellerini uzat bana, 

Kollarınla sararmış gibi yap 

tutku olsun, hasret olsun... 

Aşk olsun. 

Seni her düşündüğümde içimde güller olsun. 

Dikenin varlığında kokunu taşıyayım rüyalarıma... 

Ama unutma yüreğinde hep umut olsun...', 'İşte ellerim al tut desem  Gidişin öyle bir acı  Derin bir uçurum belki  Duruşun sessiz yokluk içinde.  Bir varsın  Bir yok olmuşsun kendini...', ARRAY['Türk Edebiyatı','Şiir','Değer Ulaş Turan']::text[], 8.5, '{"poet":"Değer Ulaş Turan","poet_slug":"deger-ulas-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/kayan-yildiz-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Giderken', 'giderken-serap-taylan-9v1oe', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Giderken  bırakıp gitmen güzeldi

Giderken sevdim ben seni 

Şimdi bu gelmelerin 

Hos değil! 

hoş değil!', 'Giderken  bırakıp gitmen güzeldi Giderken sevdim ben seni  Şimdi bu gelmelerin  Hos değil!  hoş değil!...', ARRAY['Türk Edebiyatı','Şiir','Serap Taylan']::text[], 8.5, '{"poet":"Serap Taylan","poet_slug":"serap-taylan","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/giderken-52-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dur gitme', 'dur-gitme-evren-dalgic-ajp50', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'dur gitme,

bitereyim şu son sigaramıda,

gitme ki,

görme titreyen ellerimi.

onlar ki hiç böyle boş kalmadılar,

hiç,

yalnızlığa açmadılar.

dur gitme,

sindireyim şu son vefasızlığınıda,

gitme ki,

anlayayım anlamadığım iç yüzünü.

yüreğim ki hiç bunu anlamadı,

hiç,

akıllanmadılar.

dur gitme,

öldüreyim şu son hayallerimide,

gömeyim toprağa o gözlerini.

gözlerim ki hiç boş kalmadı,

hiç,

böyle ağlamadılar.

dur gitme,

bitireyim şu son şiirimide.

tamamlayayım son mısraları.

şiirlerim ki hiç böyle buruk,

hiç; 

yarım kalmadılar.

(Ankara 2005)', 'dur gitme, bitereyim şu son sigaramıda, gitme ki, görme titreyen ellerimi. onlar ki hiç böyle boş kalmadılar, hiç, yalnızlığa açmadılar. dur...', ARRAY['Türk Edebiyatı','Şiir','Evren Dalgıç']::text[], 8.5, '{"poet":"Evren Dalgıç","poet_slug":"evren-dalgic","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/dur-gitme-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasretine Dayanamadım', 'hasretine-dayanamadim-i-brahim-necati-gunay-xxsib', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bu hasretlik bitsin artık,

Kalplerimiz sevgiyle dolsun,

O güzel kaşların kalplerimizi yakar,

Sensizliğin acısı içimi (Hepimizi)  yakar,

O zalim anan senide benide yakar,

Bu hasretlik bitsin artık,

Bu çekilen acılar artık son bulsun,

Derdime derman aradım bulamadım,

Sensizlik içimi dağladı buralarda duramadım,

Yandım anam derdimi anlatamadım,

O zalimin inadını kıramadım,

Seni kollarıma alıp yunamadım,

Senin yokluğuna alışamadım,

Bu derdime bir çare bulamadım,

O güzel gözlerine bakamadım,

O güzelin gönlünü çalamadım,

O''na ihaneti yapamadım,

Senin yokluğunda hiç bir şey yapamadım,

Şu gönlümü avutamadım,

Senden sonra hayattan tad alamadım,

Senin hasretine dayanamadım,

O güzellerin elini tutamadım,

Bu derdime bir çare bulamadım,

Dertlerimi şiire döktüm,

Yalnızlığıma bir çare bulamadım.

www.ultrailan.com 

Şair Dr İbrahim Necati Günay''ın ADINI SEN KOY adlı şiir kitabı 

GÜNMAT LTD:ŞTİ tarafından yayınlanmış olup satışa arz edilmiştir.', 'Bu hasretlik bitsin artık, Kalplerimiz sevgiyle dolsun, O güzel kaşların kalplerimizi yakar, Sensizliğin acısı içimi (Hepimizi)  yakar, O za...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Necati Günay']::text[], 8.5, '{"poet":"İbrahim Necati Günay","poet_slug":"i-brahim-necati-gunay","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/hasretine-dayanamadim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul Dışında', 'i-stanbul-disinda-serap-taylan-rzm3k', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yol boyu aklımdan geçen şiirlerim,

