deniz düşlerim.', 'düşlerim deniz düşlerim dalar ufuklara gözlerim deniz düşlerim bahtımı sulara vurur deniz düşlerim aşk sessiz yürek ıssız birbaşına kimsesiz...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Düşkün']::text[], 8.5, '{"poet":"İbrahim Düşkün","poet_slug":"i-brahim-duskun","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/duslerim-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Değil', 'degil-serap-taylan-051vv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kalemim kalem değil! 

