INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saray Gözlü', 'saray-gozlu-evren-dalgic-ydpwk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'sözüm yok,

gidin hayallerim.

isterseniz yolu tarif edeyim.

Çıkınca yüreğimden,

hemen ilk göze değil,

sağa dönün,

ya da ne bileyim belki de sola.

Ama direk bakmayın karşınıza 

onun gözlerine takılmayın.

O süzme ışık yalan,

onu sizde saray gözlü sanmayın.

sözüm yok,

gidin hayallerim.

heryer serbest,

herşeye gidin de,

bir tek ona,

yalnız ona gitmeyin.

(Ankara 2005)', 'sözüm yok, gidin hayallerim. isterseniz yolu tarif edeyim. Çıkınca yüreğimden, hemen ilk göze değil, sağa dönün, ya da ne bileyim belki de s...', ARRAY['Türk Edebiyatı','Şiir','Evren Dalgıç']::text[], 8.5, '{"poet":"Evren Dalgıç","poet_slug":"evren-dalgic","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/saray-gozlu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gittin Ya!', 'gittin-ya-kadriye-erol-conwi', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'gittin ya! 

çınarlar yaprak döküyor ardından

serçeler suskun kentin soğuk sabahına

geceden beri ağırlığın yüreğimde 

gözümde büyüyor Ankara 

yalnızlık gelip yerleşmiş

senden boşalan sokaklara...

yabancı yüzler geçiyor önümden

apayrı hayatlara koşuyorlar telaşla 

zamanı izliyorum

anlamsız... 

bakışını sakladım,

hani o veda ederken

bir de gülüşünü,

sıcaklığı içimde 

aynı olmasa da damarlarımızda akan kan

yüreğin kardeş yüreğime

sevdası aynı... 

                                          

gittin ya! 

öksüz kaldı 

''''İzmir''in Kavakları''''

Reşide''me', 'gittin ya!  çınarlar yaprak döküyor ardından serçeler suskun kentin soğuk sabahına geceden beri ağırlığın yüreğimde  gözümde büyüyor Ankara ...', ARRAY['Türk Edebiyatı','Şiir','Kadriye Erol']::text[], 8.5, '{"poet":"Kadriye Erol","poet_slug":"kadriye-erol","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/gittin-ya-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aklıma sen düşünce', 'aklima-sen-dusunce-necmettin-davulcu-xguum', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'aklıma sen düşünce

hergün hüküm giyer yüreğim

prangaları dolar boynuma

bin deprem olur hergün bedenimde

vurur derinden dokuz şiddetinde

aklıma sen düşünce

aklıma sen düşünce

dört duvar hapsim olur gözlerin

görüşe bile gelmezsin çoğu zaman

depremlere taş çıkartır hasretin

yumruk gibi düşer adın

dudaklarımdan betonlara çarpar

aklıma sen düşünce

aklıma sen düşünce

sancılar çoğalır kıvrılır bedenim

bir duble rakıda ararım dudaklarını

suskunluğum isyan olur ışıklı şehirlere

güneşe çıkasım gelmez

aklıma sen düşünce

07.01.2005', 'aklıma sen düşünce hergün hüküm giyer yüreğim prangaları dolar boynuma bin deprem olur hergün bedenimde vurur derinden dokuz şiddetinde aklı...', ARRAY['Türk Edebiyatı','Şiir','Necmettin Davulcu']::text[], 8.5, '{"poet":"Necmettin Davulcu","poet_slug":"necmettin-davulcu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/aklima-sen-dusunce-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arz-ı Muhabbet', 'arz-i-muhabbet-sair-sinas-qzukl', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Eşi yok bir güzeli sevdi beğendi gönlüm

Kıskanır kendi gözümden yine kendi gönlüm

Gâhi hasret iken ol sîneye sînem kavuşur

Sanma gönlümde olan derd-i muhabbet savuşur

Candan ülfet edeli öyle civân dilber ile

İstemem gayrisini hûr u melek olsa bile

Uğradım zülfü hayâli ile karasevdâya

Böyle Mecnûn dahi düşkün mü idi Leylâ''ya

Cân çekişmekten ise cânımı versem bâri

Cân fedâ eyleme bir iş mi sevince yâri

Ben şehîd olmadan aşkıyla mezârım kazayım

Taşımı gözlerimin kanlı yaşıyla yazayım', 'Eşi yok bir güzeli sevdi beğendi gönlüm Kıskanır kendi gözümden yine kendi gönlüm Gâhi hasret iken ol sîneye sînem kavuşur Sanma gönlümde ol...', ARRAY['Türk Edebiyatı','Şiir','Şair Şinasî']::text[], 8.5, '{"poet":"Şair Şinasî","poet_slug":"sair-sinas","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/arz-i-muhabbet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkımızda Sonbahar', 'askimizda-sonbahar-hifzi-ozbekmez-9ci2a', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'AŞKIMIZDA SONBAHAR

Aylardan sonbahardı günlerden ise Salı

Baktım yeniden açtı gönlümde aşkın dalı

İste böyle başladı sevda da baharımız

Sanmıştım gelmeyecek bizim son baharımız

Aşkımız böyle biter diyenler vardı amma

Vuslat neden olmadı bunu bilmem muamma

Kurumuş yaprak gibi umutlarım döküldü

Senden ayrı kalınca sanki kalbim söküldü

Demek ki baharımız kışlara döndü gülüm

Sensizlik öyle zor ki ondan kolaydır ölüm

Latif sonsuz umutla  aşkın yolunu bekler

Sen gelmeyince gülüm derdine derdi ekler

29  ARALIK  2004 SAAT: 16:00

SAMANYOLU GRUBUNUN 2 KELİME  1 ŞİİR AKTİVİTESİ İÇİN YAZILMIŞTIR 

KELİMELER: SONBAHAR / AŞK

''Aşağıdaki isim linkini tıklayarak, bu haftanın aktivitesine katılan diğer bir arkadaşımızın şiirlerini okuyabilirsiniz.'' 

 Tülin Şen Altınlı', 'AŞKIMIZDA SONBAHAR Aylardan sonbahardı günlerden ise Salı Baktım yeniden açtı gönlümde aşkın dalı İste böyle başladı sevda da baharımız Sanm...', ARRAY['Türk Edebiyatı','Şiir','Hıfzı Özbekmez']::text[], 8.5, '{"poet":"Hıfzı Özbekmez","poet_slug":"hifzi-ozbekmez","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/askimizda-sonbahar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlıyormusun', 'anliyormusun-mehmet-ali-suzen-vzy4n', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İSYANIMDIR HAYATA

        Anlıyorum! Gözlerindeki hüznü

Hep yanımda olmak ister bu gönlün,hıçkırıklara boğulur yüreğin

Ama gözlerin hep bakmak ister sakin,sakin

Ne kadar saklamak istemişse gerçeği lakin

Başaramadı bak gör kendini,yüzündeki gizli kalmış hüznünü

     Söyleyemez içindekini dilin,bir gariplikler dünyasıdır yaşanılan yaşatılan

Kabul etmek istemeyen yüreğinin isyanıdır, bu hüznün, bu bakışların

Vurur yüzüne bir tokat gibi,aşkı anlayana bir mesaj der gibi

     Al beni kopar yaşadığımı zannettiğim dünyamdan

Tüm kalabalık ve yalnızlıktan,seninle sadece seninle

Yalnızlığın ile doldur dünyamı,hiçbir boşluk kalmayana denk

Öyle gel ki bana,fırtınalar gibi, kasırgalar gibi,nasıl ki şehirleri,evleri ve

Tüm kuralları, kahrolası engelleri yıkarak öyle gel,öyle gel ki yüreğime

Şimşekler gibi,alev gibi,volkan gibi,yakarak,eriterek

Öyle güçlü ol ki, öyle sıcak, yok ki senden başka sığınak

 Buna küçücük kalbim nasıl dayanacak,gel gene gel,neyleyim

İçimi viran eyledin

Sen varken bu hayatta, yaşanır mı sensizlik

Gel haydi gel,tüm fırtınaların ardındaki sakinlik için,aranılan mutluluk için gel

Bir günde kendin için yaşa,değil etrafındakilerden haberli,dünyadan,insanlardan

Hatta evrenden bile habersiz,sessizce gel,mutluluğa doğru gel

     Yaşamadan bilemezsin,yaşamın tadını,tarif edilen meyvelerin balını,

Geri dönüp baktın mı hiç,hayatta tatmadığın meyvelerin hazzına,onlar  şimdi sana uzakta

İstesen de geri gelmez, geçen ne tatlar nede zamanlar,işte yaşa hayatı korkusuzca,

Yaşamaya vakit varken cesurca,sanki hiç korku,elem,keder var olmamış gibi

Yaşa ki sorarlarsa bir gün sevdim diyebilesin,boğazın düğümlenir bir gün,geri gelmez

Umuda giden zaman.

       Bir çocuk gibi oyuncaklarla oynar insan,hayatta tüm objelerle,kimini kırar,

Kimini çok sever hiç elinden bırakmaz,elinden alındığı zaman,tüm hüznü yüreğine dolar

Sen sakın elinden bırakma oyuncaklarını

Ben hiç bırakmadım

Yüreğimin içinde sakladım

Ne oyuncaklarımı verebildim

Nede seni! 

Hiç kimseler dolduramaz bendeki yerini

İnan

Kıskanırım sana olan sevgimi

Kıskandır sende bana olan sevgini

    Böyle olmamalı hayat, yaşanırken böyle yaşlanmamalı

Ne olur bir kez de kendin için yaşa

Ne olur bir kez de kendin için bak

Ne olur bir kez de kendin için tat

Ne olur bir kez de kendin için utan

Sadece kendin için! YAŞA

Anlıyor musun', 'İSYANIMDIR HAYATA         Anlıyorum! Gözlerindeki hüznü Hep yanımda olmak ister bu gönlün,hıçkırıklara boğulur yüreğin Ama gözlerin hep bakm...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Süzen']::text[], 8.5, '{"poet":"Mehmet Ali Süzen","poet_slug":"mehmet-ali-suzen","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/anliyormusun-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalancı 2 ci Hikaye', 'yalanci-2-ci-hikaye-ahmet-ersin-tasel-bj3jc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', ') .

İnsan insanın aynasıdır.

**************************

Körler ülkesinde, tek gözlüyü kral yaparlar....

Hikayelerde, çocuklara anlatılan masallarda,

hileleriyle ünlenen türlü göz boyamalarıyla 

etrafındaki insanları kandıran usta bir yalancıdan bahsedilir.

Karşılaştığınızda ondan uzak durmanız 

gerektiği konusunda size öğütler verilir.

Onu tanımanın bir yolu vardır.

''O sadece tek gözlüdür.''

Işık görmeyen gözünün gördüklerine inanır 

ve etrafındakileri de buna inandırır.

Şunlar onun hikayesinden alıntılar:

.........

Diğer gözü kendine dönük tek gözlü adam

 ''Ben''den başka bir şey görmeyen gözünü 

tüm dünyada gezdirerek her şeyin haberini alır,

bu olağanüstü yeteneği sayesinde öğrendiklerini

çevresindekileri aldatmada kullanırmış.

Ona şimdilerde ''YALANCI'' diyorlar.

…..

…

..

Kör ile yatan şaşı kalkar diye bir söz vardır.

Yalancı da,  beraber olduğu insanların,

benliklerine dönerek  kör olan gözlerinin 

gördüklerini,  yalanlardan oluşan halkalarına eklermiş.

........

…

''İnsanları kandıran işine kendisiyle başlamalı.''

Fark edilmeyen size her yönden, 

ansızın yaklaşır, 

damarlarınızda dolaşır.

Günün birinde daha siz onu kavrayamadan 

derinliklerinde bulursunuz kendinizi.

Anlamaya çalışırken anlaşılmayan olmak gibi.

Adı efsanelere karışan bu tek gözlü adamı,

ismini duyduğum ilk günden beri her gün aradım.

Yalancının bana yaklaşacağı anları kollarken, 

karşılaştığım insanların gözlerine, 

ruhlarının derinliklerine inene kadar baktım. 

Kör oldukları söylenen özürlü insanlarla sohbet edip 

onları tanımaya çalıştım.

Sonunda ''Gerçeğin ışığını '' görmek için 

gözlere gerek olmadığını anladım. 

Artık yalancıyı bulduğuma inanıyorum 

ve göz boyamalarına yalanlarına kanmıyorum.

Çünkü zaman geçtikçe 

çevremdeki insanların değişmelerine şahit oldum.

Bazıları bir yaprak gibi kayboldular, 

bazılarıysa artık benimle aynı fikirleri paylaşıyorlar 

bazılarınınsa ne olduklarından haberim yok 

artık onları göremiyorum. 

Aslında bu ''Değişimin'' nasıl olduğunu 

onlar daha iyi bililer.

Bundan birkaç sene önceydi, 

bir arkadaşım şiirlerinden bahsetmişti. 

Deli divane gibi o aralar  şiirlerle ilgileniyordum.

Arkadaşım, dolabının kapısında 

''aynasının'' altına yazdıklarını bana gösterdi.

İşte yalancının izlerini ilk kez o gün fark ettim.

Yazılanlar şöyleydi:

Sabah uyandım aynaya baktım kirliydi sildim.

Sabah uyandım aynaya baktım kirliydim, 

Ama  aynanın elleri yoktu.

Bir sabah aceleden işe yetişmeye çalışırken 

boyadığım ayakkabımın boyası kazara yüzüme bulaştı.

Aynadaki gözümün kenarına bulaşan boyayı silmeye çalışırken 

kısa bir an yüzüme diğer gözümle baktım.

''Görmediklerim beni korkuttu. ''

Eğer bir gün benim gibi yalancıyı arayacak olursanız 

Onu bulmak için fazla derinlere inmenize gerek yok.

Yakınınızda bulunan bir aynanın karşısına geçip

aynadaki boyaları silmeye çalışmanız 

onu farketmek için yeterli olacaktır. 

Göremediklerimi belki siz de  görürsünüz.

Kandırdığım dostlarımla beraber.', ') . İnsan insanın aynasıdır. ************************** Körler ülkesinde, tek gözlüyü kral yaparlar.... Hikayelerde, çocuklara anlatılan mas...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ersin Taşel']::text[], 8.5, '{"poet":"Ahmet Ersin Taşel","poet_slug":"ahmet-ersin-tasel","theme":"Türk Şiiri","is_hero":false,"total_lines":78,"source_url":"https://www.antoloji.com/yalanci-2-ci-hikaye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey Çocuk', 'ey-cocuk-hifzi-ozbekmez-8p9jf', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'EY ÇOCUK

Ayrılık vakti diye, ey çocuk sen ağlama

Unutma ki koyundan, ayrılıyor kuzular 

Boşuna hüzünlenip, yüreğini dağlama

Başa geliyor elbet kaderdeki yazılar

Halimize şükretmek en baştaki görevdir

İnsanları sev önce, sonra kendini sevdir

Ne gerek var bunlara, deme sakın ey çocuk

Unutma yalan dünya, sana geçici evdir

Ayrılık hüzünlüdür, acı veriyor elbet

Kimlere mekan oldu, çekilmeyen o gurbet

Sonsuz bir hayatı, arıyorsan ey çocuk

Unutma ki ahreti, o sürer ilelebet

04 OCAK 2005 

SAMANYOLU GRUBUNUN 2 KELİME  1 ŞİİR AKTİVİTESİ İÇİN YAZILMIŞTIR 

KELİMELER: AYRILIK / ÇOCUK

''Aşağıdaki isim linkini tıklayarak, bu haftanın aktivitesine katılan diğer bir arkadaşımızın şiirlerini okuyabilirsiniz.'' 

 Tülin Şen Altınlı', 'EY ÇOCUK Ayrılık vakti diye, ey çocuk sen ağlama Unutma ki koyundan, ayrılıyor kuzular  Boşuna hüzünlenip, yüreğini dağlama Başa geliyor elb...', ARRAY['Türk Edebiyatı','Şiir','Hıfzı Özbekmez']::text[], 8.5, '{"poet":"Hıfzı Özbekmez","poet_slug":"hifzi-ozbekmez","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ey-cocuk-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstemiyorum', 'i-stemiyorum-suheyl-turkoglu-yw9q1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Canım sıkılıyor,

Beynim ısınıyor,

İçim yanıyor,

Yazmak istemiyorum.

Kişiye özel,

Bencil tanımlamalar,

Bataklıktayken uçabilme,

Anlayışını istemiyorum.

İstememlere sığınıp,

Yan ceplerini açanlar,

Karaktersiz insanlar,

İstemiyorum,

Sahibi deyilim,

Koskoca dünyanın,

Kendi çevremde,

Riya istemiyorum.

Çok seviliyor,

Reklam arası,

Ucuz övünmeler,

İstemiyorum.

Sirkesi bal olmuş,

El sırtında,

Böyle fırsatçılar,

İstemiyorum.

Yalan ağızla,

Yemin edenler,

Kuru gürültüler,

İstemiyorum.

Benim dünyam,

Böyle olmamalı,

Haddimden fazlasını,

İstemiyorum.', 'Canım sıkılıyor, Beynim ısınıyor, İçim yanıyor, Yazmak istemiyorum. Kişiye özel, Bencil tanımlamalar, Bataklıktayken uçabilme, Anlayışını is...', ARRAY['Türk Edebiyatı','Şiir','Süheyl Türkoğlu']::text[], 8.5, '{"poet":"Süheyl Türkoğlu","poet_slug":"suheyl-turkoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/istemiyorum-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin Vefasız', 'senin-vefasiz-hifzi-ozbekmez-xi0ob', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'SENİN VEFASIZ 

Gönlümde açardın çiçekler gibi

Saçların tarardım ipekler gibi

Dururdun yolumu hep bekler gibi

Sevginde yalanmış senin vefasız 

Sevdiğim diyerek överdim seni

Esmerim diyerek severdim seni

Ele güne rezil eyledin beni

Aşkında yalanmış senin vefasız 

Uykumu bölerdim gece yarısı

Kimin sevdiği var böyle birisi

Sevenlere olsun derdim darısı

Sevdanda yalanmış senin vefasız

Güzelim boşuna yalan söyledin

Demek ki benimle gönül eyledin

Gördüm ayrılığı aşka yeğledin

Her şeyin yalanmış senin vefasız 

05 OCAK 2005  SAAT: 02:30

Şiir perisi  Grubunun haftanın '' Vefa ''konulu  Aktivitesi için kaleme alınmıştır..', 'SENİN VEFASIZ  Gönlümde açardın çiçekler gibi Saçların tarardım ipekler gibi Dururdun yolumu hep bekler gibi Sevginde yalanmış senin vefasız...', ARRAY['Türk Edebiyatı','Şiir','Hıfzı Özbekmez']::text[], 8.5, '{"poet":"Hıfzı Özbekmez","poet_slug":"hifzi-ozbekmez","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/senin-vefasiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dostun Vefası', 'dostun-vefasi-hifzi-ozbekmez-kersq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'DOSTUN VEFASI

Hüzünler gördüm ben çileler çektim

Yanımda sadece dostun vefası

Sevgiyi gönlüme gül diye diktim

Kanımda sadece dostun vefası

Düştüğümde tuttu kaldırdı beni

Dostlar meclisine aldırdı beni

Ham meyve gibiydim oldurdu beni

Canımda sadece dostun vefası

Niye böyle insan bilmem ki niye

Boşa sevinmişim seven var diye

Örnek verdiğim gerçek sevgiye

Anımda sadece dostun vefası

Sevdiğim koysa da beni elemde

Gönülden silse de bir tek kalemde

Latifi olmuşsam koca alemde

Şanımda sadece dostun vefası

05 OCAK 2005  SAAT: 03:00



Şiir perisi  Grubunun haftanın '' Vefa ''konulu  Aktivitesi için kaleme alınmıştır..', 'DOSTUN VEFASI Hüzünler gördüm ben çileler çektim Yanımda sadece dostun vefası Sevgiyi gönlüme gül diye diktim Kanımda sadece dostun vefası D...', ARRAY['Türk Edebiyatı','Şiir','Hıfzı Özbekmez']::text[], 8.5, '{"poet":"Hıfzı Özbekmez","poet_slug":"hifzi-ozbekmez","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/dostun-vefasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Günce...', 'gunce-cigdem-agbulak-tn8ic', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Usumda ezik bir şeyler var,

Silikleşiyor gittikçe,

Ya ben uzaklaşıyorum ondan,

Ya da o beni terk ediyor günden güne.

Oysa,

Panayırım kurulmuşta el ediyor bana,

Elimi sallamak istiyorum,

Kocaman bir karanlık dikiliyor karşıma.

Soğuk,

El değmez bir günce.

Seslerimi alıyor karanlık belli,

Çok uzakta kalmış tanıdık bir ninni,

Bir masa başı,

Seçemediğim insanlar yığını.

Sen hiç öldün mü? 

Günceme işliyorum ölümü,

Sessiz ve ani...

Aşağıdan bağırıyorlar,

Çıkıyorum dışarı,

Gürültülü bir kalabalık.

Yıldızlar simli suretler yükleyip gölgelere,

Oynatıyorlar sessiz.

Mahallenin kızları

Pencere onu oturmalarında,

Tül perdelerin ardından,

Yaşama bıraktıkları tek damla gözyaşları,

Besleyip büyütüyor sardunyalarını.

Sen bilmezsin ya, 

Sardunyalar ondan bunca sevdalı.', 'Usumda ezik bir şeyler var, Silikleşiyor gittikçe, Ya ben uzaklaşıyorum ondan, Ya da o beni terk ediyor günden güne. Oysa, Panayırım kurulmu...', ARRAY['Türk Edebiyatı','Şiir','Çiğdem Ağbulak']::text[], 8.5, '{"poet":"Çiğdem Ağbulak","poet_slug":"cigdem-agbulak","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/gunce-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
