INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözyaşımsın', 'gozyasimsin-mahya-sultan-tosun-wbt8o', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hüzünlüyüm ben yine

Dalıyorum derinlere

Seni seviyorum diye

İki gözü iki çeşme

Benden gayrı herkes.

Yılmayan sevgim

İnceltiyor beni içten içe

Sen yokken açım

Seninle doyuyorum

Anlatamadım derdimi

Senden gayrı herkese.', 'Hüzünlüyüm ben yine Dalıyorum derinlere Seni seviyorum diye İki gözü iki çeşme Benden gayrı herkes. Yılmayan sevgim İnceltiyor beni içten iç...', ARRAY['Türk Edebiyatı','Şiir','Mahya Sultan Tosun']::text[], 8.5, '{"poet":"Mahya Sultan Tosun","poet_slug":"mahya-sultan-tosun","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/gozyasimsin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamak', 'yasamak-mahya-sultan-tosun-8ntpq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sana inanmak,

