INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Yaptıysam Olmadı', 'ne-yaptiysam-olmadi-mahya-sultan-tosun-8yf39', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sen ruhunu kaybetmişsin 

Sevgilim,

İzlediğin film,

Dinlediğin müzik,

Sana yapılan serenatlar,

Senin için yazılan şiirler,

Seni etkilemiyorsa; 

Verilen bir gül

Sadece gülümsetiyor

Sevgilinle kucaklaştırmıyorsa,

Senin ruhun ölmüş

Sevgilim.', 'Sen ruhunu kaybetmişsin  Sevgilim, İzlediğin film, Dinlediğin müzik, Sana yapılan serenatlar, Senin için yazılan şiirler, Seni etkilemiyorsa...', ARRAY['Türk Edebiyatı','Şiir','Mahya Sultan Tosun']::text[], 8.5, '{"poet":"Mahya Sultan Tosun","poet_slug":"mahya-sultan-tosun","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ne-yaptiysam-olmadi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizce', 'sensizce-mahya-sultan-tosun-hp0j1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Geçen günlerin ciddiyeti ile

