INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kar Taneleri', 'kar-taneleri-deniz-onderoglu-1gnb4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kar tanelerini düşün

Birer birer düşüyorlar yeryüzüne

Yavaş yavaş

Sonra her yeri kaplıyorlar

Hiç boşluk bırakmadan

Sen de böyle yavaş yavaş

Gir kalbime

Sonra en ücra köşesine kadar

Her yerini kapla

