INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bildim', 'bildim-tuncay-pektas-9ekp9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'her uzaklık kendi yakınlığına kanardı

bildim 

beni sana taşıyan 

otogarlarında ayak sürüdüm

bu şehirden bozma 

kaba saba taşranın', 'her uzaklık kendi yakınlığına kanardı bildim  beni sana taşıyan  otogarlarında ayak sürüdüm bu şehirden bozma  kaba saba taşranın...', ARRAY['Türk Edebiyatı','Şiir','Tuncay Pektaş']::text[], 8.5, '{"poet":"Tuncay Pektaş","poet_slug":"tuncay-pektas","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/bildim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çiçek ol', 'cicek-ol-tuncay-pektas-64rfj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'bazı bazı

içimdeki çocuk

