INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonudur yolun, yola çıktığın yaşam kıvılcımları', 'sonudur-yolun-yola-ciktigin-yasam-kivilcimlari-lzcramcil-ceyhun-erdem-2khig', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yolu yürümektir yolun getirdiği yük omuzlarına,

yürümelisin ki yolu, kendini bulmalısın sonunda o yolun

Yolu yürümelisin, adanmalısın yola

varacağın yer adanmışlıkların yeri olmalıdır çünki

Sonu yolun kürkçü dükkanıdır, 

her çıktığında geri döndüğün yerdir varmak istediğin

Yolu yürümek, aynı zamanda düşünmektir onu

yürümek hissetmektir, solumaktır, damarlarında dolaşmasıdır yolun

Varacağın yeri düşünmeli, günler geceler boyu, sessizlikle ve bazen haykırışla, isyanla ve uysallıkla

ama asla yola kaptırmamalı kendini, çünki yolun sonuna yaklaştığında yeni bir kavşak, yeni bir yol ayrımı koyar karşına yol, o senin düşüncelerini bölmek ister,

yol ayırmak istemez seni kendinden, sarhoşlukları, cicileri ve yalanları vardır onun.

o seni ayırmak istemez senden.

ancak bir gün girdiğin bir yolda ağırca ilerlerken anlarsın ki bu yol seni varmak istediğin yere gider, ruhuna, kendine gider

işte o yol seni bırakmak ister, senden ayrılmak onunla yürümek kadar büyük bir huzur verir.

bu yol seni varmak istediğin yere götürürken ağır davranır 

çünki gerçeklikte hız yoktur, gerçek vardır ve zaman yalnız yere düşen kuru bir yapraktır.

ve sen kuruyup salınırken yere doğru, yol seni huzurla teslim eder Yaratıcıya

Yolun sonu budur.', 'Yolu yürümektir yolun getirdiği yük omuzlarına, yürümelisin ki yolu, kendini bulmalısın sonunda o yolun Yolu yürümelisin, adanmalısın yola v...', ARRAY['Türk Edebiyatı','Şiir','Lzcramcil Ceyhun Erdem']::text[], 8.5, '{"poet":"Lzcramcil Ceyhun Erdem","poet_slug":"lzcramcil-ceyhun-erdem","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sonudur-yolun-yola-ciktigin-yasam-kivilcimlari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Batmış gemi', 'batmis-gemi-sair-shimalwest-k7k0i', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'batmış geminin karaya vuran insanları,

dolaşıp dururken,biliçsizce kıyıları,

tanımak için çıktıkları toprakları,

anlayınca buraları kendi toprakları,

toplandılar atmak için korsanları.

lider lazımdı örgütlenmek için,

kurtuluş mücadelesini kazanmak için.

sivrilince içlerinden mazi gözlü olanı,

inanç geldi hepsine kaynadı kanları.

üç beş taş,üç beş dal parçası,

kovmaya yeter mi düşmanları.

işte böyle kazandılar bu toprakları.

batmış geminin karaya vuran insanları,

bayrak dikmek için akan kanları,

unuttuğunu gördükce, torunları,

kemikleri sızlayarak izliyor toprakları,

biliyorlar geçti artık lider çıkarma zamanları.', 'batmış geminin karaya vuran insanları, dolaşıp dururken,biliçsizce kıyıları, tanımak için çıktıkları toprakları, anlayınca buraları kendi to...', ARRAY['Türk Edebiyatı','Şiir','Şair Shimalwest']::text[], 8.5, '{"poet":"Şair Shimalwest","poet_slug":"sair-shimalwest","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/batmis-gemi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bunun icin seviyorum seni', 'bunun-icin-seviyorum-seni-kardelen-ceyda-mq6g0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'ayri yönlerde yürüyoruz seninle

ayni yolda,kavusma ihtimali olmadan.

iste bunun icin seviyorum seni

bir ihtimal olsa belkide; 

seni sevmekten vazgececegim

hevesim gececek biliyorum bunu

imkansizsinya benim icin

her nefes alisimda sen olacaksinya

sana kavusma ihtimaliyle yüreyecegim ya yollarda

sevgin hic tükenmeyecekya

iste; 

bunun icin seviyorum seni...', 'ayri yönlerde yürüyoruz seninle ayni yolda,kavusma ihtimali olmadan. iste bunun icin seviyorum seni bir ihtimal olsa belkide;  seni sevmekte...', ARRAY['Türk Edebiyatı','Şiir','Kardelen Ceyda']::text[], 8.5, '{"poet":"Kardelen Ceyda","poet_slug":"kardelen-ceyda","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bunun-icin-seviyorum-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen iyileş', 'sen-iyiles-meryem-i-sler-a7vb7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'bu hüzün beni öldürüyor

için için içimi kemiriyor

gözlerim gözlerine gülsede

kalbim eriyip bitiyor

dayanamam senin hastalığına

senin yerine ben düşeyim yataklara

yeterki iyileş ben taşırım acılarını

ver bana çektiğin tüm sancılarını

canımın canısın kıyamam

sen hastayken ben iyi olamam

gece gündüz başını beklerim

kirpiğim kirpiğime deymez uyuyamam

anayım ben ateşten çok yanarım

yüzüne ğüler ciğerimden ağlarım

ben canımı sana adadım

sen iyileş uğruna cehenemde yanarım', 'bu hüzün beni öldürüyor için için içimi kemiriyor gözlerim gözlerine gülsede kalbim eriyip bitiyor dayanamam senin hastalığına senin yerine ...', ARRAY['Türk Edebiyatı','Şiir','Meryem İşler']::text[], 8.5, '{"poet":"Meryem İşler","poet_slug":"meryem-i-sler","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sen-iyiles-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ateş olur yakar yüreğin', 'ates-olur-yakar-yuregin-i-brahim-duskun-xbor0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'alevlenen ateşlere atılan ibrahimdi 

ruhunu özgürlüğe adamışın biriydi 

kıvılcımlara direnen saran yüreğindi 

bin ateşe direnir ateş yakmaz ibrahimi 

yüreğin ateş olur nasılda yakar ibrahimi 

sürüp giden bir yazgı gibidir sana yolculuk 

ateşinde serinlik,serinliğinde ateş gizlenir 

böyledir yürekler,kadim bir gelenekten beslenir.', 'alevlenen ateşlere atılan ibrahimdi  ruhunu özgürlüğe adamışın biriydi  kıvılcımlara direnen saran yüreğindi  bin ateşe direnir ateş yakmaz ...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Düşkün']::text[], 8.5, '{"poet":"İbrahim Düşkün","poet_slug":"i-brahim-duskun","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ates-olur-yakar-yuregin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben seni çok sevdim', 'ben-seni-cok-sevdim-huseyin-i-rfan-kibrislioglu-d7jci', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ben senin en çok o çocuk yüzünü sevdim biliyormusun

Bana ılık ılık  bakışlarındaki o katışıksız sevgiyi, o ürkek telaşı, 

gözlerinin o bitmeyen gülüşlerini sevdim.

Hani sana her dokunduğumda o titreyişlerini, seni her öptüğümde

kalbinin bir minik kuş misali o çırpınışlarını sevdim.

Ben senin o gencecik ömründe böylesine sevgiyle dolu kalbini sevdim en çok 

İsmin misali sevişlerini sevdim sonra

Ne diyeyim  daha sana bilmem ki

Ben sendeki insan sıcaklığını sevdim en çok

Kısacası sen bazen inanmasan da bana

ben seni çok, ama çok sevdim.', 'Ben senin en çok o çocuk yüzünü sevdim biliyormusun Bana ılık ılık  bakışlarındaki o katışıksız sevgiyi, o ürkek telaşı,  gözlerinin o bitme...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin İrfan Kıbrıslıoğlu']::text[], 8.5, '{"poet":"Hüseyin İrfan Kıbrıslıoğlu","poet_slug":"huseyin-i-rfan-kibrislioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/ben-seni-cok-sevdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alkışlarla', 'alkislarla-suheyl-turkoglu-u5b4i', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sevinç doldu içime,

Sığamadım kabuğuma,

Bilemiyordum ne yapacağımı,

Anlattım ALKIŞLARLA,

Olamazdı böyle bir şey,

Çok güzeldi herşey,

Beğenim doruktaydı,

Anlattım ALKIŞLARLA.

İçimde büyüydü öfke,

Kızmıştım, darılmıştım,

Protesto etmeliydim,

Anlattım ALKIŞLARLA.

Omuzlardaki tabutta,

Sevdiğim gidiyordu,

Üzüntüm sel olmuştu,

Anlattım ALKIŞLARLA,

Sevinci beğeniyi,

Öfkeyi üzüntüyü,

Hayatım boyunca hep,

Anlattım ALKIŞLARLA.

Karar verin alkışlar,

Neyi anlatıyorsunuz,

Diye hesap sorarken,

Gidiyorum ALKIŞLARLA...', 'Sevinç doldu içime, Sığamadım kabuğuma, Bilemiyordum ne yapacağımı, Anlattım ALKIŞLARLA, Olamazdı böyle bir şey, Çok güzeldi herşey, Beğenim...', ARRAY['Türk Edebiyatı','Şiir','Süheyl Türkoğlu']::text[], 8.5, '{"poet":"Süheyl Türkoğlu","poet_slug":"suheyl-turkoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/alkislarla-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gül Bahçesi', 'gul-bahcesi-suheyl-turkoglu-kiiai', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gül bitermiş öğretmenim,

Vurduğun yerde,

Gül bahçesine döndüm,

Canım öğretmenim,

Sayende...', 'Gül bitermiş öğretmenim, Vurduğun yerde, Gül bahçesine döndüm, Canım öğretmenim, Sayende......', ARRAY['Türk Edebiyatı','Şiir','Süheyl Türkoğlu']::text[], 8.5, '{"poet":"Süheyl Türkoğlu","poet_slug":"suheyl-turkoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/gul-bahcesi-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yol', 'yol-suheyl-turkoglu-b1wrd', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Arama doğruyu,

Hangisi diye,

Çıkar farklılıkları,

Dinlerden,

Geriye,

Tanrı''nın doğruları kalır...', 'Arama doğruyu, Hangisi diye, Çıkar farklılıkları, Dinlerden, Geriye, Tanrı''nın doğruları kalır......', ARRAY['Türk Edebiyatı','Şiir','Süheyl Türkoğlu']::text[], 8.5, '{"poet":"Süheyl Türkoğlu","poet_slug":"suheyl-turkoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/yol-74-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Birazcık', 'birazcik-bekir-mutlu-gokcesu-evkus', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Buraları çok karanlık

Şimdi yavaş, yavaş

Yaklaşsaydın bana

Keşke birazcık...

Tutunsaydın ellerime

Dokunsaydın gözlerime...

Bir mumumuz olacaktı

Buralarda

Yüreğim kadar titreyen

Aşkımıza

Bitmekten korkan

Yaksaydın keşke biraz...

Bir şarkımız

Bir şarkımız olacaktı 

Buralarda

Dilimden düşmeyen

Tekrar, tekrar başlayan

Dudaklarımda

Öpseydin keşke biraz...

Kuytularında kaldım 

Yüreğimin...

Yorgun düşlerim

Dilediğimce

Uçmuyor artık

Buraları çok karanlık

Keşke gelebilseydin 

Nefesinle nefesime

Birazcık...

Sabahlarına gözlerinin

Çekip çıkarabilseydin

Yüreğimin kuytularından

Keşke beni birazcık...', 'Buraları çok karanlık Şimdi yavaş, yavaş Yaklaşsaydın bana Keşke birazcık... Tutunsaydın ellerime Dokunsaydın gözlerime... Bir mumumuz olaca...', ARRAY['Türk Edebiyatı','Şiir','Bekir Mutlu Gökçesu']::text[], 8.5, '{"poet":"Bekir Mutlu Gökçesu","poet_slug":"bekir-mutlu-gokcesu","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/birazcik-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni sorarsan eğer..', 'beni-sorarsan-eger-selma-sengoren-k4vrb', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Beni sorarsan eğer,

Ağlayan bir çocuğa bak...

Yanaklarından dökülen yağmur damlasındayım

Tarlalarda uzanan buğday filizlerine bak

Buğday tanelerinin içindeyim 

Gökyüzündeki mavi kızıllığın kaybolduğu

Ufuklara bak...

Güneşin battığı en son yerdeyim 

Acı çeken yüreklerin seslerini dinle,

Acının zerresinde saklıyım 

Sevgilerin yoğunlaştığı gönüllerde,

Sevginin yumağında çevrili

Gülümseyen ruhların noktasındaki gamzeyim 

Beni sorarsan eğer,

Sonsuzluğa açılan pencereden

Çok uzaklara bak

Yalansız, riyasız bir dünya görürsen aç kapısını,

İşte..

O dünyanın içindeyim ben.', 'Beni sorarsan eğer, Ağlayan bir çocuğa bak... Yanaklarından dökülen yağmur damlasındayım Tarlalarda uzanan buğday filizlerine bak Buğday tan...', ARRAY['Türk Edebiyatı','Şiir','Selma Şengören']::text[], 8.5, '{"poet":"Selma Şengören","poet_slug":"selma-sengoren","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/beni-sorarsan-eger-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaybettim...', 'kaybettim-selma-sengoren-tl5o7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir nar çiçeğinin kırmızısıydın içimde..

Bilinmeyen mevsimlere taşındığın an...

Bütün mevsimlerimi kaybettim..

Yaşattığın yüreğimdin..

Yeşerten bağlarım koptu..

Yüreğimi kaybettim..

Biliyormusun sen benim için..

Denizin rengiydin..dalgaların sesi..

Yanağımdaki gamzeydin..

Yağmurlarımdın..elif elif çisildeyen.. 

Yazımdın..kışımdın..

Ekmeğimdin..suyumdun..

Gönül bahçemdeki nefesimdin..

Şimdi yoksun..

Bendeki seni kaybettim..

Apansız gözlerinle vedalaştın..apansız..

Nasıl bir bakıştı o Tanrım..

Sanki sayfalar dolusu birşeyler anlatacakmış gibi..

Neyi anlatacaktın? 

Neyi söyleyecektin? 

Mıhlanmıştım çelik gibi gözlerine...

Okuyamadım gözlerindeki sözlerini..

İşte..o anda..

Gözlerimi de...kaybettim...

''', 'Bir nar çiçeğinin kırmızısıydın içimde.. Bilinmeyen mevsimlere taşındığın an... Bütün mevsimlerimi kaybettim.. Yaşattığın yüreğimdin.. Yeşer...', ARRAY['Türk Edebiyatı','Şiir','Selma Şengören']::text[], 8.5, '{"poet":"Selma Şengören","poet_slug":"selma-sengoren","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/kaybettim-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Gittim', 'ben-gittim-tayfun-yilmaz-t96er', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'bu dönüşün sonu yok

geri gelmem için sebep yok

niçin sorasın beni

neden arasın hala beni

ben yokum 

sen hiç yoksun

gelme benim üstüme

kaç

git

yüreksiz ol

kork bir çoçuk gibi

kaç bir hırsız gibi

kaybol bir büyü gibi

ben gittim çoktan 

karış sende gecenin kor karanlıklarına

                         tayfun yılmaz (deneme)  10.01.2005', 'bu dönüşün sonu yok geri gelmem için sebep yok niçin sorasın beni neden arasın hala beni ben yokum  sen hiç yoksun gelme benim üstüme kaç gi...', ARRAY['Türk Edebiyatı','Şiir','Tayfun Yılmaz']::text[], 8.5, '{"poet":"Tayfun Yılmaz","poet_slug":"tayfun-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ben-gittim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstemeden', 'i-stemeden-bekir-mutlu-gokcesu-rwz3c', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ben sana

Beni sev demedim

Senin bana 

Gel demediğin gibi

Ben sana

Benim ol demedim

Senin bana

Nerelerdeydin? 

Demediğin gibi

Ben seni sevdiğimi

Kendime bile söylemedim

Ansızın

Ve istemeden oldu

Yine de 

Özür dilerim...', 'Ben sana Beni sev demedim Senin bana  Gel demediğin gibi Ben sana Benim ol demedim Senin bana Nerelerdeydin?  Demediğin gibi Ben seni sevdiğ...', ARRAY['Türk Edebiyatı','Şiir','Bekir Mutlu Gökçesu']::text[], 8.5, '{"poet":"Bekir Mutlu Gökçesu","poet_slug":"bekir-mutlu-gokcesu","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/istemeden-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bittim Attım', 'bittim-attim-tayfun-yilmaz-r28f8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'sana yazdıgım son mektup

sana geldigim son gece

seni görebilecegim son gece

senin kokunu duyabilecegim son son

ben sonu seçtim 

sen ilkleri seç 

ben gidiyorum

ben korkuyorum

ben kaçıyorum

ben ben 

seni istemiyorum

bakma sakın arkana

dur sana yalan söyledim demiyecegim

gözün hep ileride olsun

ben bitiyorum

bittim...

seni çıkardım içimden

attım...

                         tayfun yılmaz (deneme2)  10.01.2005', 'sana yazdıgım son mektup sana geldigim son gece seni görebilecegim son gece senin kokunu duyabilecegim son son ben sonu seçtim  sen ilkleri ...', ARRAY['Türk Edebiyatı','Şiir','Tayfun Yılmaz']::text[], 8.5, '{"poet":"Tayfun Yılmaz","poet_slug":"tayfun-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/bittim-attim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmurdereli''ye', 'yagmurdereli-ye-suheyl-turkoglu-ocp91', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sen şiir yazıyormuşsun Eşber,

Roman yazıyormuşsun,

Ud çalıyormuşsun,

On parmak daktilon da varmış,

Güzel konuşup,

İnsanları etkiliyormuşsun,

Uyanık olduğun sürece,

Sigara içiyormuşsun.

İnan bana,

Bunların hepsini,

Ben de yapıyorum,

Ama benim, 

Bir eksiğim var,

Ben GÖRÜYORUM...', 'Sen şiir yazıyormuşsun Eşber, Roman yazıyormuşsun, Ud çalıyormuşsun, On parmak daktilon da varmış, Güzel konuşup, İnsanları etkiliyormuşsun,...', ARRAY['Türk Edebiyatı','Şiir','Süheyl Türkoğlu']::text[], 8.5, '{"poet":"Süheyl Türkoğlu","poet_slug":"suheyl-turkoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/yagmurdereli-ye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalb agrisi', 'kalb-agrisi-aynur-i-lkay-qj4xw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gozden yaslar dokulur

                                  Sanki disim sokulur

                                  Kalp agrisi cekilir

                                  Giden yarin pesinden

                                  Yaslar akar durulmaz

                                  Kalbim sizlar yorulmaz

                                  Asika dert sorulmaz

                                  Ayrilinca esinden

                                  Aynur Ilkay

                                  24 Agustos 1998

                                  Toronto,Ont.

                                  Kanada', 'Gozden yaslar dokulur                                   Sanki disim sokulur                                   Kalp agrisi cekilir           ...', ARRAY['Türk Edebiyatı','Şiir','Aynur İlkay']::text[], 8.5, '{"poet":"Aynur İlkay","poet_slug":"aynur-i-lkay","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kalb-agrisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Su kenari', 'su-kenari-aynur-i-lkay-dm2d1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Zaman zaman dusunurum bir su kenari

		Bahce icinde suya bakan zarif bir yali

		

Yesil cimenlik ta suya kadar uzanir

		Ulu sogudun yapraklari yere varir

		Altinda yatipda masmavi goge dalsam

		Gece mehtapta dusen yildizlari saysam

		Suyun sesi kulaga ninni gibi gelir

		Sanki melekler semadan inip konser verir

		Mehtap,yildizlar ve suyun billur sesi

		Safakda kuslarin sen sakrak nesesi

		Ben o su kenarini henuz bulamadim

		Sogudun altindan mehtaba doyamadim

		O cennetten koseyi ruyamda gordumde

		Hafizama ince bir dantel gibi ordumde

		Su fani dunyada oraya varamadim

		Onume cikar dedim ayrica aramadim

		Aynur Ilkay

		1 Eylul 1997

		Toronto,Ont.

		Kanada', 'Zaman zaman dusunurum bir su kenari 		Bahce icinde suya bakan zarif bir yali 		 Yesil cimenlik ta suya kadar uzanir 		Ulu sogudun yapraklari...', ARRAY['Türk Edebiyatı','Şiir','Aynur İlkay']::text[], 8.5, '{"poet":"Aynur İlkay","poet_slug":"aynur-i-lkay","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/su-kenari-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Baba', 'baba-suheyl-turkoglu-u3l64', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'En güçlüydün benim için her zaman,

En akıllı, en bilge.

Kucağında yenerdim korkuları,

Güvenle bakardım,

Sevimli olurdu herşey,

Ama her şey.

Adımlarım cesurlaşırdı,

Elimi tuttuğunda,

Yüreğim ısınırdı,

Şefkatle baktığında,

Yaslardım başımı,

Güçlü omuzlarına,

Ne olur baba derdim,

Saçımı okşa.

Varlığını duyardım,

Dokunuşlarında.

Nasıl bilirdin baba,

Yalan söylediğimi,

Rüzgarı abartarak,

Fırtına dediğimi,

Çiçekleri koparıp,

Suları döktüğümü,

Duvarı karaladığımı,

Bütün gün huysuzlukla,

Annemi üzdüğümü.

Sana söyleyen kuşlar,

Nereye gitti baba? 

Onlar mı alırlardı,

Dama attığın dişlerimi? 

Beni getiren leylek nerede? 

Titizlenir, titrerdin,

Sakınırdın herşeyden,

Sıkardı beni baba,

Bu kadar korku,

Solacak çiçek,

Kırılacak yumurta,

Patlayacak balon,

Sönecek ışık,

Kaybolacak servet,

Umut gibi,

Ayırmak istemezdin,

Bir an bile yanından.

Tablosunu seyreden,

Ressam.

Şiirini okuyan,

Şair,

Mutluluğu vardı,

Gözlerinde,

Bana bakarken.

Eskilere dönüp,

Küçücük çocuk olsam,

''BABA'' diye haykırıp,

Kollarına sığınsam.

Gözünde hep çocuğum,

Büyümedim, biliyorum,

Yıllar değiştirdi rolleri,

Kabullen artık baba,

En büyük varlığımsın,

Kokuna canım feda.', 'En güçlüydün benim için her zaman, En akıllı, en bilge. Kucağında yenerdim korkuları, Güvenle bakardım, Sevimli olurdu herşey, Ama her şey. ...', ARRAY['Türk Edebiyatı','Şiir','Süheyl Türkoğlu']::text[], 8.5, '{"poet":"Süheyl Türkoğlu","poet_slug":"suheyl-turkoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":59,"source_url":"https://www.antoloji.com/baba-27-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çığır..', 'cigir-yilmaz-boga-ss32k', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'susma....

güzel insanım

ürkeklik yakışmıyor sana

titremesin sesin

ölüm kapı tokmağında

daracık vaktimiz

anlamak zor suskunluğu

kardeş türküleri çığır

gamzelerinde ısınsın bedenim

sevgi kimliğin olsun

acılarım sende çiçeklensin

dostluğun

özlemimde saklı

Veysel''in sazında yanık

susma...

güzel insanım

çığır....

sevgi türkülerini

sende duyulsun sesleri

sesi duyulmayan dostların

yılmaz Boğa....15.9.2000..sydney', 'susma.... güzel insanım ürkeklik yakışmıyor sana titremesin sesin ölüm kapı tokmağında daracık vaktimiz anlamak zor suskunluğu kardeş türkül...', ARRAY['Türk Edebiyatı','Şiir','Yılmaz Boğa']::text[], 8.5, '{"poet":"Yılmaz Boğa","poet_slug":"yilmaz-boga","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/cigir-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Serin Sevda...', 'serin-sevda-zulfikar-yapar-kaleli-0bj8a', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'embed src= http://www.neyzen.com/images/taksim/arif_erdebil/arif_erdebil_zirgulelihicaz.wma

font face=''TR ProseAntique'' color=''black'' size=''1''

Eğlemezdi zincirlesen bu gönlü 

Bir esmer nazenin tüle bağladı. 

Sehere resmetti arkalı önlü 

Kul etti bülbülü, güle bağladı 

Alevlenir gönül aşkın közünden 

Aşık ayrılır mı ahu izinden? 

Bir ceren sekişli Leyla yüzünden 

Mecalsiz mecnunu çöle bağladı. 

Bağlanmış sonsuzda tükenmez vara 

Ferhat Şirin diye yüklenir yara 

Kerem''i yaktı da sevda nara 

Aslı''yı kefilsiz küle bağladı 

Hayat yıllarını emdikten sonra 

İnişi görmedi dimdikten sonra 

Kamber''i toprağa gömdükten sonra 

Arzu''yu kim için yola bağladı. 

Yusuflar sevdadır Züleyhalar''a 

Selvi''yi Emrah’ın düşünde ara 

Mevlüt İhsani’yi muhannet yara 

Beni de bir çürük dala bağladı.

